--
-- Name: apply_jsonb_amount_access("jsonb", "text"[], "text"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."apply_jsonb_amount_access"("p_data" "jsonb", "p_keys" "text"[], "p_access" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  v_result jsonb := coalesce(p_data, '{}'::jsonb);
  v_key text;
begin
  foreach v_key in array p_keys loop
    if p_access = 'hidden' then
      v_result := v_result - v_key;
    elsif p_access = 'masked' and v_result ? v_key then
      v_result := jsonb_set(v_result, array[v_key], '"***"'::jsonb, true);
    end if;
  end loop;
  return v_result;
end;
$$;


ALTER FUNCTION "app_private"."apply_jsonb_amount_access"("p_data" "jsonb", "p_keys" "text"[], "p_access" "text") OWNER TO "postgres";

