--

--
-- Name: attempt_workflow_business_callback("uuid", "text"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."attempt_workflow_business_callback"("p_outbox_id" "uuid", "p_worker_name" "text" DEFAULT 'workflow-inline'::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_event public.wf_business_callback_outbox;
  v_attempt_no integer;
  v_started_at timestamptz := clock_timestamp();
  v_error_code text;
  v_error_message text;
begin
  select *
  into v_event
  from public.wf_business_callback_outbox o
  where o.id = p_outbox_id
  for update;

  if not found then
    raise exception '审批业务回调事件不存在';
  end if;

  if v_event.status = 'succeeded' then
    return 'succeeded';
  end if;

  if v_event.status = 'dead_letter' then
    return 'dead_letter';
  end if;

  if exists (
    select 1
    from public.wf_business_callback_outbox earlier
    where earlier.instance_id = v_event.instance_id
      and earlier.event_no < v_event.event_no
      and earlier.status <> 'succeeded'
  ) then
    return 'blocked_by_predecessor';
  end if;

  select coalesce(max(a.attempt_no), 0) + 1
  into v_attempt_no
  from public.wf_business_callback_attempt a
  where a.outbox_id = v_event.id;

  update public.wf_business_callback_outbox
  set status = 'processing',
      attempt_count = attempt_count + 1,
      locked_at = now(),
      locked_by = coalesce(nullif(btrim(p_worker_name), ''), 'workflow-worker'),
      last_error_code = null,
      last_error = null
  where id = v_event.id
  returning * into v_event;

  begin
    perform app_private.execute_workflow_business_callback(
      v_event.business_type,
      v_event.business_id,
      v_event.target_status,
      v_event.actor_name,
      v_event.callback_comment
    );

    insert into public.wf_business_callback_attempt(
      outbox_id, attempt_no, outcome, worker_name, duration_ms
    ) values (
      v_event.id,
      v_attempt_no,
      'succeeded',
      v_event.locked_by,
      greatest(0, extract(milliseconds from clock_timestamp() - v_started_at)::integer)
    );

    update public.wf_business_callback_outbox
    set status = 'succeeded',
        processed_at = now(),
        next_attempt_at = now(),
        locked_at = null,
        locked_by = null,
        last_error_code = null,
        last_error = null
    where id = v_event.id;

    return 'succeeded';
  exception
    when others then
      get stacked diagnostics
        v_error_code = returned_sqlstate,
        v_error_message = message_text;

      insert into public.wf_business_callback_attempt(
        outbox_id, attempt_no, outcome, worker_name,
        error_code, error_message, duration_ms
      ) values (
        v_event.id,
        v_attempt_no,
        'failed',
        v_event.locked_by,
        v_error_code,
        left(v_error_message, 2000),
        greatest(0, extract(milliseconds from clock_timestamp() - v_started_at)::integer)
      );

      update public.wf_business_callback_outbox
      set status = case
            when v_event.attempt_count >= v_event.max_attempts then 'dead_letter'
            else 'retry_wait'
          end,
          next_attempt_at = case
            when v_event.attempt_count >= v_event.max_attempts then now()
            else now() + make_interval(
              secs => least(3600, 60 * power(2, least(v_event.attempt_count - 1, 6))::integer)
            )
          end,
          locked_at = null,
          locked_by = null,
          last_error_code = v_error_code,
          last_error = left(v_error_message, 2000)
      where id = v_event.id;

      return case
        when v_event.attempt_count >= v_event.max_attempts then 'dead_letter'
        else 'retry_wait'
      end;
  end;
end;
$$;


ALTER FUNCTION "app_private"."attempt_workflow_business_callback"("p_outbox_id" "uuid", "p_worker_name" "text") OWNER TO "postgres";

--

--
-- Name: auth_user_tenant_id(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."auth_user_tenant_id"() RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select user_row.tenant_id
  from public.sys_user user_row
  join public.sys_tenant tenant_row on tenant_row.id = user_row.tenant_id
  where user_row.auth_user_id = (select auth.uid())
    and user_row.status = '1'
    and user_row.deleted_at is null
    and tenant_row.status = '1'
    and (
      tenant_row.service_start_date is null
      or tenant_row.service_start_date <= (now() at time zone 'Asia/Shanghai')::date
    )
    and (
      tenant_row.service_end_date is null
      or tenant_row.service_end_date >= (now() at time zone 'Asia/Shanghai')::date
    )
  limit 1;
$$;


ALTER FUNCTION "app_private"."auth_user_tenant_id"() OWNER TO "postgres";

--

--
-- Name: can_access_business_menu("text"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."can_access_business_menu"("p_menu_name" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select (select auth.uid()) is not null
    and (
      app_private.is_platform_super()
      or exists (
        select 1
        from public.sys_user current_user_row
        join public.sys_role role_row
          on role_row.tenant_id = current_user_row.tenant_id
         and role_row.enabled is true
         and role_row.role_code = any(coalesce(current_user_row.user_roles, array[]::text[]))
        join public.sys_role_menu role_menu
          on role_menu.tenant_id = role_row.tenant_id
         and role_menu.role_id = role_row.id
        join public.sys_menu menu_row
          on menu_row.id = role_menu.menu_id
         and menu_row.name = p_menu_name
         and menu_row.type is distinct from 'button'
        where current_user_row.auth_user_id = (select auth.uid())
          and current_user_row.status = '1'
          and current_user_row.deleted_at is null
          and (menu_row.meta->>'is_enable') is distinct from 'false'
      )
    );
$$;


ALTER FUNCTION "app_private"."can_access_business_menu"("p_menu_name" "text") OWNER TO "postgres";

--

--
-- Name: can_execute_business_action("text", "text", "uuid", boolean); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."can_execute_business_action"("p_menu_name" "text", "p_permission" "text", "p_record_owner_id" "uuid" DEFAULT NULL::"uuid", "p_allow_owner" boolean DEFAULT false) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select app_private.can_access_business_menu(p_menu_name)
    and (
      app_private.is_platform_super()
      or (
        p_allow_owner
        and p_record_owner_id is not null
        and p_record_owner_id = app_private.current_app_user_id()
      )
      or not exists (
        select 1 from public.sys_menu menu_row
        where menu_row.type = 'button'
          and menu_row.name = p_permission
          and (menu_row.meta->>'is_enable') is distinct from 'false'
      )
      or app_private.has_permission(p_permission)
    );
$$;


ALTER FUNCTION "app_private"."can_execute_business_action"("p_menu_name" "text", "p_permission" "text", "p_record_owner_id" "uuid", "p_allow_owner" boolean) OWNER TO "postgres";

