--

--
-- Name: current_read_tenant_id(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."current_read_tenant_id"() RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_scope_text text;
  v_tenant_id uuid;
begin
  if (select auth.uid()) is null then
    raise exception '请先登录后再读取租户数据' using errcode = '42501';
  end if;

  if not app_private.is_platform_super() then
    v_tenant_id := app_private.auth_user_tenant_id();
    if v_tenant_id is null then
      raise exception '当前账号无有效租户，无法读取租户数据' using errcode = '42501';
    end if;
    return v_tenant_id;
  end if;

  v_scope_text := nullif(
    btrim(
      coalesce(
        current_setting('request.headers', true)::jsonb ->> 'x-art-tenant-scope',
        ''
      )
    ),
    ''
  );

  if v_scope_text is null then
    return null;
  end if;

  return app_private.current_user_tenant_id();
end;
$$;


ALTER FUNCTION "app_private"."current_read_tenant_id"() OWNER TO "postgres";

