--
-- Name: document_number_period_key("text", timestamp with time zone, "text"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."document_number_period_key"("p_reset_cycle" "text", "p_now" timestamp with time zone, "p_timezone" "text") RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select case p_reset_cycle
    when 'year' then to_char(p_now at time zone p_timezone, 'YYYY')
    when 'month' then to_char(p_now at time zone p_timezone, 'YYYYMM')
    when 'day' then to_char(p_now at time zone p_timezone, 'YYYYMMDD')
    else ''
  end
$$;


