CREATE TABLE IF NOT EXISTS "public"."hr_employee_relation_case" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" DEFAULT "app_private"."current_user_tenant_id"() NOT NULL,
    "case_no" "text" NOT NULL,
    "case_type" "text" NOT NULL,
    "title" "text" NOT NULL,
    "subject_employee_id" "uuid" NOT NULL,
    "reporter_employee_id" "uuid",
    "anonymous_report" boolean DEFAULT false NOT NULL,
    "source" "text" DEFAULT 'hr'::"text" NOT NULL,
    "severity" "text" DEFAULT 'medium'::"text" NOT NULL,
    "confidentiality_level" "text" DEFAULT 'restricted'::"text" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "owner_employee_id" "uuid",
    "reported_at" timestamp with time zone,
    "target_resolution_date" "date",
    "triaged_at" timestamp with time zone,
    "investigation_started_at" timestamp with time zone,
    "resolved_at" timestamp with time zone,
    "closed_at" timestamp with time zone,
    "allegation_summary" "text" NOT NULL,
    "findings_summary" "text",
    "outcome" "text",
    "resolution_summary" "text",
    "attachment_urls" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "external_reference" "text",
    "remark" "text",
    "create_by" "text",
    "create_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "update_by" "text",
    "update_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "hr_employee_relation_case_allegation_not_blank" CHECK ((NULLIF("btrim"("allegation_summary"), ''::"text") IS NOT NULL)),
    CONSTRAINT "hr_employee_relation_case_anonymous_reporter_check" CHECK (((NOT "anonymous_report") OR ("reporter_employee_id" IS NULL))),
    CONSTRAINT "hr_employee_relation_case_attachment_urls_check" CHECK (("jsonb_typeof"("attachment_urls") = 'array'::"text")),
    CONSTRAINT "hr_employee_relation_case_closed_check" CHECK ((("status" <> 'closed'::"text") OR ("closed_at" IS NOT NULL))),
    CONSTRAINT "hr_employee_relation_case_confidentiality_check" CHECK (("confidentiality_level" = ANY (ARRAY['standard'::"text", 'restricted'::"text", 'highly_restricted'::"text"]))),
    CONSTRAINT "hr_employee_relation_case_investigation_check" CHECK ((("status" <> ALL (ARRAY['investigating'::"text", 'action_required'::"text", 'resolved'::"text", 'closed'::"text"])) OR ("investigation_started_at" IS NOT NULL))),
    CONSTRAINT "hr_employee_relation_case_no_not_blank" CHECK ((NULLIF("btrim"("case_no"), ''::"text") IS NOT NULL)),
    CONSTRAINT "hr_employee_relation_case_outcome_check" CHECK ((("outcome" IS NULL) OR ("outcome" = ANY (ARRAY['substantiated'::"text", 'unsubstantiated'::"text", 'inconclusive'::"text", 'resolved_informally'::"text", 'withdrawn'::"text"])))),
    CONSTRAINT "hr_employee_relation_case_resolution_check" CHECK ((("status" <> ALL (ARRAY['resolved'::"text", 'closed'::"text"])) OR (("outcome" IS NOT NULL) AND (NULLIF("btrim"("resolution_summary"), ''::"text") IS NOT NULL) AND ("resolved_at" IS NOT NULL)))),
    CONSTRAINT "hr_employee_relation_case_severity_check" CHECK (("severity" = ANY (ARRAY['low'::"text", 'medium'::"text", 'high'::"text", 'critical'::"text"]))),
    CONSTRAINT "hr_employee_relation_case_source_check" CHECK (("source" = ANY (ARRAY['employee_report'::"text", 'manager_report'::"text", 'hr'::"text", 'hotline'::"text", 'service_escalation'::"text", 'audit'::"text"]))),
    CONSTRAINT "hr_employee_relation_case_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'reported'::"text", 'triaged'::"text", 'investigating'::"text", 'action_required'::"text", 'resolved'::"text", 'closed'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "hr_employee_relation_case_title_not_blank" CHECK ((NULLIF("btrim"("title"), ''::"text") IS NOT NULL)),
    CONSTRAINT "hr_employee_relation_case_triage_check" CHECK ((("status" = ANY (ARRAY['draft'::"text", 'reported'::"text", 'cancelled'::"text"])) OR (("owner_employee_id" IS NOT NULL) AND ("target_resolution_date" IS NOT NULL) AND ("triaged_at" IS NOT NULL)))),
    CONSTRAINT "hr_employee_relation_case_type_check" CHECK (("case_type" = ANY (ARRAY['grievance'::"text", 'misconduct'::"text", 'harassment'::"text", 'workplace_conflict'::"text", 'accommodation'::"text", 'policy_violation'::"text", 'other'::"text"])))
);


