    "tenant_id" "uuid" DEFAULT "app_private"."current_user_tenant_id"() NOT NULL,
    "request_no" "text" NOT NULL,
    "employee_id" "uuid" NOT NULL,
    "request_type" "text" NOT NULL,
    "title" "text" NOT NULL,
    "start_at" timestamp with time zone,
    "end_at" timestamp with time zone,
    "duration_hours" numeric(10,2),
    "reason" "text" NOT NULL,
    "request_data" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "workflow_instance_id" "uuid",
    "reviewed_at" timestamp with time zone,
    "reviewed_by" "text",
    "review_comment" "text",
    "create_by" "text",
    "create_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "update_by" "text",
    "update_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "service_id" "uuid",
    "priority" "text" DEFAULT 'normal'::"text" NOT NULL,
    "channel" "text" DEFAULT 'self_service'::"text" NOT NULL,
    "assigned_employee_id" "uuid",
    "first_response_due_at" timestamp with time zone,
    "resolution_due_at" timestamp with time zone,
    "first_responded_at" timestamp with time zone,
    "resolved_at" timestamp with time zone,
    "closed_at" timestamp with time zone,
    "waiting_started_at" timestamp with time zone,
    "last_activity_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "waiting_reason" "text",
    "resolution" "text",
    "attachment_urls" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "reopen_count" integer DEFAULT 0 NOT NULL,
    CONSTRAINT "hr_self_service_request_attachment_urls_check" CHECK (("jsonb_typeof"("attachment_urls") = 'array'::"text")),
    CONSTRAINT "hr_self_service_request_channel_check" CHECK (("channel" = ANY (ARRAY['self_service'::"text", 'agent'::"text", 'email'::"text", 'phone'::"text"]))),
    CONSTRAINT "hr_self_service_request_dates_check" CHECK ((("end_at" IS NULL) OR ("start_at" IS NULL) OR ("end_at" >= "start_at"))),
    CONSTRAINT "hr_self_service_request_duration_check" CHECK ((("duration_hours" IS NULL) OR ("duration_hours" >= (0)::numeric))),
    CONSTRAINT "hr_self_service_request_priority_check" CHECK (("priority" = ANY (ARRAY['low'::"text", 'normal'::"text", 'high'::"text", 'urgent'::"text"]))),
    CONSTRAINT "hr_self_service_request_reopen_count_check" CHECK (("reopen_count" >= 0)),
    CONSTRAINT "hr_self_service_request_resolution_check" CHECK ((("status" <> ALL (ARRAY['resolved'::"text", 'closed'::"text"])) OR (NULLIF("btrim"("resolution"), ''::"text") IS NOT NULL))),
    CONSTRAINT "hr_self_service_request_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'submitted'::"text", 'assigned'::"text", 'in_progress'::"text", 'waiting_employee'::"text", 'resolved'::"text", 'closed'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "hr_self_service_request_waiting_check" CHECK (((("status" = 'waiting_employee'::"text") AND ("waiting_started_at" IS NOT NULL) AND (NULLIF("btrim"("waiting_reason"), ''::"text") IS NOT NULL)) OR (("status" <> 'waiting_employee'::"text") AND ("waiting_started_at" IS NULL))))
);


