--

--
-- Name: hr_append_candidate_stage("uuid", "text", "text"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."hr_append_candidate_stage"("p_candidate_id" "uuid", "p_to_stage" "text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_candidate public.hr_candidate;
  v_valid boolean := false;
begin
  select * into v_candidate
  from public.hr_candidate
  where id = p_candidate_id
  for update;
  if not found then raise exception '候选人不存在'; end if;
  if v_candidate.stage = p_to_stage then return; end if;

  v_valid :=
    (v_candidate.stage = 'new' and p_to_stage in ('screening', 'rejected', 'withdrawn')) or
    (v_candidate.stage = 'screening' and p_to_stage in ('interview', 'rejected', 'withdrawn')) or
    (v_candidate.stage = 'interview' and p_to_stage in ('offer', 'rejected', 'withdrawn')) or
    (v_candidate.stage = 'offer' and p_to_stage in ('hired', 'rejected', 'withdrawn'));
  if not v_valid then
    raise exception '候选人阶段不能从 % 变更为 %', v_candidate.stage, p_to_stage;
  end if;
  if p_to_stage in ('rejected', 'withdrawn') and nullif(btrim(p_reason), '') is null then
    raise exception '淘汰或放弃候选人必须填写原因';
  end if;

  perform pg_catalog.set_config('app.hr_recruitment_engine', 'on', true);
  update public.hr_candidate
  set stage = p_to_stage,
      rejection_reason = case when p_to_stage in ('rejected', 'withdrawn') then btrim(p_reason) else null end
  where id = p_candidate_id;
  insert into public.hr_candidate_stage_history(
    tenant_id, candidate_id, from_stage, to_stage, transition_reason, changed_by
  ) values (
    v_candidate.tenant_id, v_candidate.id, v_candidate.stage, p_to_stage,
    nullif(btrim(p_reason), ''), coalesce(app_private.current_user_email(), 'system')
  );
end
$$;


ALTER FUNCTION "app_private"."hr_append_candidate_stage"("p_candidate_id" "uuid", "p_to_stage" "text", "p_reason" "text") OWNER TO "postgres";

--

--
-- Name: hr_assignment_snapshot("uuid"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."hr_assignment_snapshot"("p_assignment_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'assignmentId', assignment_row.id,
    'assignmentUpdatedAt', assignment_row.update_time,
    'organizationId', assignment_row.organization_id,
    'organizationCode', organization_row.organization_code,
    'organizationName', organization_row.organization_name,
    'positionId', assignment_row.position_id,
    'positionCode', position_row.position_code,
    'positionName', position_row.position_name,
    'jobProfileId', assignment_row.job_profile_id,
    'jobCode', profile_row.job_code,
    'jobName', profile_row.job_name,
    'gradeId', assignment_row.grade_id,
    'gradeCode', grade_row.grade_code,
    'gradeName', grade_row.grade_name,
    'businessTitle', assignment_row.business_title,
    'assignmentStatus', assignment_row.assignment_status,
    'employmentStatus', employee_row.employment_status,
    'effectiveStart', assignment_row.effective_start,
    'fte', assignment_row.fte
  )
  from public.hr_employee_assignment assignment_row
  join public.hr_employee employee_row
    on employee_row.id = assignment_row.employee_id and employee_row.tenant_id = assignment_row.tenant_id
  join public.sys_organization organization_row
    on organization_row.id = assignment_row.organization_id and organization_row.tenant_id = assignment_row.tenant_id
  join public.hr_position position_row
    on position_row.id = assignment_row.position_id and position_row.tenant_id = assignment_row.tenant_id
  join public.hr_job_profile profile_row
    on profile_row.id = assignment_row.job_profile_id and profile_row.tenant_id = assignment_row.tenant_id
  left join public.hr_grade grade_row
    on grade_row.id = assignment_row.grade_id and grade_row.tenant_id = assignment_row.tenant_id
  where assignment_row.id = p_assignment_id;
$$;


ALTER FUNCTION "app_private"."hr_assignment_snapshot"("p_assignment_id" "uuid") OWNER TO "postgres";

