--

--
-- Name: hr_set_candidate_stage_sequence(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."hr_set_candidate_stage_sequence"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.sequence_no is null then
    select coalesce(max(history.sequence_no), 0) + 1
    into new.sequence_no
    from public.hr_candidate_stage_history history
    where history.candidate_id = new.candidate_id;
  end if;
  return new;
end
$$;


