--

--
-- Name: hr_validate_compensation_review_budget("uuid"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."hr_validate_compensation_review_budget"("p_cycle_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_overrun record;
begin
  select
    coalesce(organization.organization_name, '未分配组织') as organization_name,
    coalesce(budget.budget_amount, 0) as budget_amount,
    coalesce(sum(greatest(item.proposed_base_amount - item.current_base_amount, 0)), 0) as used_amount
  into v_overrun
  from public.hr_compensation_review_item item
  left join public.sys_organization organization
    on organization.id = item.organization_id
   and organization.tenant_id = item.tenant_id
  left join public.hr_compensation_review_budget budget
    on budget.cycle_id = item.cycle_id
   and budget.tenant_id = item.tenant_id
   and budget.organization_id is not distinct from item.organization_id
  where item.cycle_id = p_cycle_id
    and item.status <> 'excluded'
  group by item.organization_id, organization.organization_name, budget.budget_amount
  having coalesce(sum(greatest(item.proposed_base_amount - item.current_base_amount, 0)), 0)
       > coalesce(budget.budget_amount, 0)
  order by
    coalesce(sum(greatest(item.proposed_base_amount - item.current_base_amount, 0)), 0)
      - coalesce(budget.budget_amount, 0) desc
  limit 1;

  if found then
    raise exception '% 调薪预算超支：预算 %，已建议 %',
      v_overrun.organization_name, v_overrun.budget_amount, v_overrun.used_amount;
  end if;
end;
$$;


ALTER FUNCTION "app_private"."hr_validate_compensation_review_budget"("p_cycle_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_valuate_attendance_record("uuid"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."hr_valuate_attendance_record"("p_record_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_record public.hr_attendance_record;
  v_shift public.hr_shift;
  v_planned_start timestamptz;
  v_planned_end timestamptz;
  v_scheduled integer := 0;
  v_work integer := 0;
  v_late integer := 0;
  v_early integer := 0;
  v_absence integer := 0;
  v_overtime integer := 0;
  v_status text := 'normal';
  v_exception text := 'clear';
  v_note text;
begin
  select * into v_record from public.hr_attendance_record where id = p_record_id for update;
  if not found then raise exception '考勤记录不存在'; end if;
  if v_record.locked_at is not null then raise exception '考勤记录已封账，不能重新核算'; end if;

  if v_record.shift_id is not null then
    select * into v_shift from public.hr_shift
    where id = v_record.shift_id and tenant_id = v_record.tenant_id;
  else
    select shift.* into v_shift
    from public.hr_shift_assignment assignment
    join public.hr_shift shift on shift.id = assignment.shift_id and shift.tenant_id = assignment.tenant_id
    where assignment.tenant_id = v_record.tenant_id
      and assignment.employee_id = v_record.employee_id
      and assignment.work_date = v_record.work_date
      and assignment.assignment_status <> 'cancelled';
  end if;

  if found then
    v_planned_start := (v_record.work_date::timestamp + v_shift.start_time) at time zone v_shift.time_zone;
    v_planned_end := ((v_record.work_date + case when v_shift.cross_day then 1 else 0 end)::timestamp
      + v_shift.end_time) at time zone v_shift.time_zone;
    v_scheduled := greatest(floor(extract(epoch from (v_planned_end - v_planned_start)) / 60)::integer
      - v_shift.break_minutes, 0);
  end if;

  if v_record.attendance_status in ('leave', 'business_trip') then
    v_status := v_record.attendance_status;
    v_note := case when v_status = 'leave' then '已批准休假，不生成出勤异常' else '已登记出差，不生成出勤异常' end;
  elsif v_record.clock_in_at is null or v_record.clock_out_at is null then
    v_status := 'absent';
    v_absence := v_scheduled;
    v_exception := 'open';
    v_note := case
      when v_record.clock_in_at is null and v_record.clock_out_at is null then '缺少上下班打卡'
      when v_record.clock_in_at is null then '缺少上班打卡'
      else '缺少下班打卡'
    end;
  else
    v_work := greatest(floor(extract(epoch from (v_record.clock_out_at - v_record.clock_in_at)) / 60)::integer
      - coalesce(v_shift.break_minutes, 0), 0);
    if v_planned_start is not null then
      v_late := greatest(floor(extract(epoch from (v_record.clock_in_at - v_planned_start)) / 60)::integer
        - v_shift.late_grace_minutes, 0);
      v_early := greatest(floor(extract(epoch from (v_planned_end - v_record.clock_out_at)) / 60)::integer
        - v_shift.early_leave_grace_minutes, 0);
    end if;
    v_absence := greatest(v_scheduled - v_work, 0);
    v_overtime := greatest(v_work - v_scheduled, 0);
    if v_late > 0 then v_status := 'late';
    elsif v_early > 0 then v_status := 'early_leave';
    else v_status := 'normal'; end if;
    if v_late > 0 or v_early > 0 or v_absence > 0 then v_exception := 'open'; end if;
    v_note := concat_ws('；',
      case when v_late > 0 then '迟到 ' || v_late || ' 分钟' end,
      case when v_early > 0 then '早退 ' || v_early || ' 分钟' end,
      case when v_absence > 0 then '缺勤 ' || v_absence || ' 分钟' end,
      case when v_overtime > 0 then '超出计划 ' || v_overtime || ' 分钟' end
    );
    if v_note = '' then v_note := '打卡覆盖计划工时'; end if;
  end if;

  update public.hr_attendance_record
  set shift_id = coalesce(shift_id, v_shift.id),
      scheduled_minutes = v_scheduled,
      work_minutes = v_work,
      overtime_minutes = v_overtime,
      late_minutes = v_late,
      early_leave_minutes = v_early,
      absence_minutes = v_absence,
      payable_minutes = v_work,
      attendance_status = v_status,
      exception_status = v_exception,
      valuation_note = v_note
  where id = p_record_id;
end
$$;


ALTER FUNCTION "app_private"."hr_valuate_attendance_record"("p_record_id" "uuid") OWNER TO "postgres";

--

--
-- Name: is_platform_super(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."is_platform_super"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1
    from public.sys_user u
    join public.sys_tenant t on t.id = u.tenant_id
    join public.sys_role r
      on r.tenant_id = u.tenant_id
     and r.builtin_type = 'platform_super'
     and r.role_code = any(coalesce(u.user_roles, array[]::text[]))
    where u.auth_user_id = auth.uid()
      and lower(u.user_email) = 'platform-owner@example.com'
      and t.builtin_type = 'platform'
      and u.status = '1'
      and r.enabled is true
  )
$$;


ALTER FUNCTION "app_private"."is_platform_super"() OWNER TO "postgres";

--

--
-- Name: mask_permission_value("text", "text"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mask_permission_value"("p_value" "text", "p_strategy" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  v_length integer := char_length(coalesce(p_value, ''));
begin
  if p_value is null then
    return null;
  end if;

  return case p_strategy
    when 'phone' then
      case when v_length >= 7
        then left(p_value, 3) || repeat('*', greatest(v_length - 7, 4)) || right(p_value, 4)
        else repeat('*', greatest(v_length, 4))
      end
    when 'id_card' then
      case when v_length >= 8
        then left(p_value, 4) || repeat('*', v_length - 8) || right(p_value, 4)
        else repeat('*', greatest(v_length, 4))
      end
    when 'bank_account' then
      case when v_length >= 8
        then left(p_value, 4) || repeat('*', v_length - 8) || right(p_value, 4)
        else repeat('*', greatest(v_length, 4))
      end
    when 'address' then
      case when v_length > 6 then left(p_value, 6) || '***' else '***' end
    when 'amount' then '***'
    else '***'
  end;
end;
$$;


ALTER FUNCTION "app_private"."mask_permission_value"("p_value" "text", "p_strategy" "text") OWNER TO "postgres";

--

--
-- Name: next_document_number("text", "uuid"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."next_document_number"("p_rule_key" "text", "p_tenant_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_rule public.sys_document_number_rule;
  v_now timestamptz := clock_timestamp();
  v_period_key text;
  v_sequence bigint;
  v_width integer;
  v_result text;
begin
  if p_tenant_id is null then
    raise exception '生成编号时缺少租户';
  end if;
  if auth.uid() is not null
     and not app_private.is_platform_super()
     and p_tenant_id is distinct from app_private.current_user_tenant_id() then
    raise exception '无权为其他租户生成编号';
  end if;

  select * into v_rule
  from public.sys_document_number_rule
  where tenant_id = p_tenant_id and rule_key = p_rule_key and enabled;
  if not found then
    raise exception '未找到已启用的编号规则：%', p_rule_key;
  end if;
  if not v_rule.auto_enabled then
    raise exception '编号规则 % 已切换为手工填写', v_rule.rule_name;
  end if;

  v_period_key := app_private.document_number_period_key(
    v_rule.reset_cycle, v_now, v_rule.timezone
  );
  insert into public.sys_document_number_counter (
    rule_id, tenant_id, rule_version, period_key, current_value, create_by, update_by
  ) values (
    v_rule.id, p_tenant_id, v_rule.rule_version, v_period_key, v_rule.sequence_start,
    coalesce(nullif(auth.jwt() ->> 'email', ''), 'number-engine'),
    coalesce(nullif(auth.jwt() ->> 'email', ''), 'number-engine')
  )
  on conflict (rule_id, tenant_id, rule_version, period_key)
  do update set
    current_value = public.sys_document_number_counter.current_value + 1,
    update_time = now(),
    update_by = coalesce(nullif(auth.jwt() ->> 'email', ''), 'number-engine')
  returning current_value into v_sequence;

  v_width := substring(v_rule.template from '\{SEQ:([1-9][0-9]?)\}')::integer;
  if length(v_sequence::text) > v_width then
    raise exception '编号规则 % 的 % 位流水号已用尽，请调整模板', v_rule.rule_name, v_width;
  end if;

  v_result := v_rule.template;
  v_result := replace(v_result, '{YYYYMMDD}', to_char(v_now at time zone v_rule.timezone, 'YYYYMMDD'));
  v_result := replace(v_result, '{YYYYMM}', to_char(v_now at time zone v_rule.timezone, 'YYYYMM'));
  v_result := replace(v_result, '{YYMM}', to_char(v_now at time zone v_rule.timezone, 'YYMM'));
  v_result := replace(v_result, '{YYYY}', to_char(v_now at time zone v_rule.timezone, 'YYYY'));
  v_result := replace(v_result, '{YY}', to_char(v_now at time zone v_rule.timezone, 'YY'));
  v_result := replace(v_result, '{MM}', to_char(v_now at time zone v_rule.timezone, 'MM'));
  v_result := replace(v_result, '{DD}', to_char(v_now at time zone v_rule.timezone, 'DD'));
  return regexp_replace(v_result, '\{SEQ:[1-9][0-9]?\}', lpad(v_sequence::text, v_width, '0'));
end;
$$;


ALTER FUNCTION "app_private"."next_document_number"("p_rule_key" "text", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: permission_access_rank("text"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."permission_access_rank"("p_access" "text") RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case p_access
    when 'edit' then 3
    when 'read' then 2
    when 'masked' then 1
    else 0
  end;
$$;


ALTER FUNCTION "app_private"."permission_access_rank"("p_access" "text") OWNER TO "postgres";

