--

--
-- Name: start_workflow("text", "uuid", "text", "jsonb", "text"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."start_workflow"("p_business_type" "text", "p_business_id" "uuid", "p_business_title" "text", "p_context" "jsonb", "p_idempotency_key" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_user_id uuid := app_private.current_app_user_id();
  v_actor text := coalesce(nullif(auth.jwt() ->> 'email', ''), auth.uid()::text);
  v_actor_name text;
  v_definition public.wf_definition;
  v_instance_id uuid;
  v_context jsonb := coalesce(p_context, '{}'::jsonb);
  v_business record;
begin
  if auth.uid() is null or v_user_id is null then raise exception '当前登录用户未绑定业务账号'; end if;
  if jsonb_typeof(v_context) <> 'object' then raise exception '流程上下文必须是对象'; end if;
  perform pg_advisory_xact_lock(hashtextextended(
    v_tenant_id::text || ':' || p_business_type || ':' || p_business_id::text, 91311
  ));
  select id into v_instance_id from public.wf_instance
  where tenant_id = v_tenant_id and business_type = p_business_type
    and business_id = p_business_id and status = 'running';
  if found then return v_instance_id; end if;

  select coalesce(nullif(nick_name, ''), nullif(user_name, ''), user_email, id::text)
  into v_actor_name from public.sys_user
  where id = v_user_id and tenant_id = v_tenant_id and status = '1';
  select * into v_definition from public.wf_definition
  where tenant_id = v_tenant_id and business_type = p_business_type and status = 'published';
  if not found then raise exception '当前业务类型没有已启用的审批流程'; end if;

  if p_business_type = 'tms_waybill_cost' then
    select c.id, c.audit_status business_status, c.amount, c.cost_type, c.waybill_id
    into v_business from public.tms_waybill_cost c
    where c.id = p_business_id and c.tenant_id = v_tenant_id for update;
    if not found then raise exception '运单费用不存在或无权提交'; end if;
    if v_business.business_status not in ('draft', 'rejected') then raise exception '当前费用状态不允许提交审批'; end if;
    v_context := v_context || jsonb_build_object(
      'amount', v_business.amount, 'costType', v_business.cost_type, 'waybillId', v_business.waybill_id
    );
  elsif p_business_type = 'tms_in_transit_expense' then
    raise exception '在途费用申报功能已停用，请使用运单费用流程';
  elsif p_business_type = 'tms_expense_reimbursement' then
    select r.id, r.status business_status, r.total_amount, r.reimbursement_no,
           r.payment_method, r.planned_payment_date,
           (select count(*)::integer from public.tms_expense_reimbursement_item i
            where i.reimbursement_id = r.id) item_count,
           (select count(distinct i.waybill_id)::integer
            from public.tms_expense_reimbursement_item i
            where i.reimbursement_id = r.id) waybill_count
    into v_business from public.tms_expense_reimbursement r
    where r.id = p_business_id and r.tenant_id = v_tenant_id
    for update;
    if not found then raise exception '费用报销单不存在、无明细或无权提交'; end if;
    if v_business.business_status not in ('draft', 'rejected') then raise exception '当前报销单状态不允许提交审批'; end if;
    v_context := v_context || jsonb_build_object(
      'amount', v_business.total_amount, 'reimbursementNo', v_business.reimbursement_no,
      'paymentMethod', v_business.payment_method, 'plannedPaymentDate', v_business.planned_payment_date,
      'itemCount', v_business.item_count, 'waybillCount', v_business.waybill_count
    );
  end if;

  insert into public.wf_instance(
    definition_id, version_id, business_type, business_id, business_title,
    initiator_user_id, initiator_name_snapshot, context_snapshot, tenant_id, create_by, update_by
  ) values (
    v_definition.id, v_definition.current_version_id, p_business_type, p_business_id,
    btrim(p_business_title), v_user_id, v_actor_name, v_context, v_tenant_id, v_actor, v_actor
  ) returning id into v_instance_id;
  insert into public.wf_action(
    instance_id, action, actor_user_id, actor_name_snapshot, comment,
    idempotency_key, tenant_id, create_by
  ) values (
    v_instance_id, 'submit', v_user_id, v_actor_name, '提交审批',
    nullif(p_idempotency_key, ''), v_tenant_id, v_actor
  );
  perform app_private.apply_workflow_business_status(
    p_business_type, p_business_id, 'running', v_actor_name, null
  );
  perform app_private.activate_next_workflow_node(v_instance_id, 0);
  return v_instance_id;
end;
$$;


ALTER FUNCTION "app_private"."start_workflow"("p_business_type" "text", "p_business_id" "uuid", "p_business_title" "text", "p_context" "jsonb", "p_idempotency_key" "text") OWNER TO "postgres";

--

--
-- Name: sync_delete_auth_user_on_app_delete(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."sync_delete_auth_user_on_app_delete"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if old.auth_user_id is not null
     and exists (
       select 1
       from auth.users
       where id = old.auth_user_id
     )
  then
    delete from auth.users
    where id = old.auth_user_id;
  end if;

  return old;
end;
$$;


