--

--
-- Name: upsert_notification_subject("uuid", "text", "text", "uuid", "text", "text", timestamp with time zone, "uuid", "text", "jsonb", "jsonb", "text"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."upsert_notification_subject"("p_tenant_id" "uuid", "p_scenario_code" "text", "p_business_type" "text", "p_business_id" "uuid", "p_subject_key" "text", "p_subject_title" "text", "p_due_at" timestamp with time zone, "p_owner_user_id" "uuid", "p_route_path" "text", "p_route_query" "jsonb", "p_metadata" "jsonb", "p_status" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_scenario public.sys_notification_scenario%rowtype;
  v_subject_id uuid;
begin
  select * into v_scenario
  from public.sys_notification_scenario
  where scenario_code = p_scenario_code and enabled is true;
  if not found then raise exception 'Notification scenario not found: %', p_scenario_code; end if;

  if p_due_at is null or p_status <> 'active' then
    update public.sys_notification_subject
    set status = case when p_status in ('resolved', 'cancelled') then p_status else 'cancelled' end,
        update_by = 'system-reminder'
    where tenant_id = p_tenant_id
      and scenario_id = v_scenario.id
      and business_type = p_business_type
      and business_id = p_business_id
      and subject_key = coalesce(nullif(p_subject_key, ''), 'default')
    returning id into v_subject_id;
    return v_subject_id;
  end if;

  insert into public.sys_notification_subject (
    tenant_id, scenario_id, business_type, business_id, subject_key,
    subject_title, due_at, owner_user_id, route_path, route_query, metadata,
    status, create_by, update_by
  )
  values (
    p_tenant_id, v_scenario.id, p_business_type, p_business_id,
    coalesce(nullif(p_subject_key, ''), 'default'), btrim(p_subject_title), p_due_at,
    p_owner_user_id, coalesce(nullif(p_route_path, ''), v_scenario.route_path),
    coalesce(p_route_query, '{}'::jsonb), coalesce(p_metadata, '{}'::jsonb),
    'active', 'system-reminder', 'system-reminder'
  )
  on conflict (tenant_id, scenario_id, business_type, business_id, subject_key)
  do update set
    subject_title = excluded.subject_title,
    due_at = excluded.due_at,
    owner_user_id = excluded.owner_user_id,
    route_path = excluded.route_path,
    route_query = excluded.route_query,
    metadata = excluded.metadata,
    status = 'active',
    update_by = excluded.update_by
  returning id into v_subject_id;
  return v_subject_id;
end;
$$;


ALTER FUNCTION "app_private"."upsert_notification_subject"("p_tenant_id" "uuid", "p_scenario_code" "text", "p_business_type" "text", "p_business_id" "uuid", "p_subject_key" "text", "p_subject_title" "text", "p_due_at" timestamp with time zone, "p_owner_user_id" "uuid", "p_route_path" "text", "p_route_query" "jsonb", "p_metadata" "jsonb", "p_status" "text") OWNER TO "postgres";

--

--
-- Name: validate_hr_employee_assignment_capacity(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."validate_hr_employee_assignment_capacity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_position public.hr_position%rowtype;
  v_incumbent_count integer;
begin
  if not new.primary_assignment
     or new.effective_end is not null
     or new.assignment_status = 'ended' then
    return new;
  end if;

  select position_row.*
  into v_position
  from public.hr_position position_row
  where position_row.id = new.position_id
    and position_row.tenant_id = new.tenant_id
  for update;

  if not found then
    raise exception '任职岗位不存在';
  end if;
  if not v_position.enabled then
    raise exception '任职岗位已停用';
  end if;
  if v_position.organization_id is not null
     and v_position.organization_id <> new.organization_id then
    raise exception '任职组织与岗位所属组织不一致';
  end if;
  if v_position.job_profile_id <> new.job_profile_id then
    raise exception '任职标准职务与岗位标准职务不一致';
  end if;

  select count(*)::integer
  into v_incumbent_count
  from public.hr_employee_assignment assignment_row
  where assignment_row.tenant_id = new.tenant_id
    and assignment_row.position_id = new.position_id
    and assignment_row.primary_assignment
    and assignment_row.effective_end is null
    and assignment_row.assignment_status <> 'ended'
    and assignment_row.id <> new.id;

  if not v_position.multiple_incumbents_allowed and v_incumbent_count >= 1 then
    raise exception '该岗位仅允许一人任职';
  end if;
  if v_incumbent_count >= v_position.headcount_limit then
    raise exception '该岗位编制已满（上限 % 人）', v_position.headcount_limit;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "app_private"."validate_hr_employee_assignment_capacity"() OWNER TO "postgres";

--

--
-- Name: validate_hr_personnel_change_target(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."validate_hr_personnel_change_target"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_position public.hr_position%rowtype;
begin
  select position_row.*
  into v_position
  from public.hr_position position_row
  where position_row.id = new.to_position_id
    and position_row.tenant_id = new.tenant_id;

  if not found then
    raise exception '目标岗位不存在';
  end if;
  if v_position.job_profile_id <> new.to_job_profile_id then
    raise exception '目标标准职务必须与目标岗位的标准职务一致';
  end if;
  if v_position.organization_id is not null
     and v_position.organization_id <> new.to_organization_id then
    raise exception '目标组织必须与目标岗位所属组织一致';
  end if;

  if new.change_type in ('promotion', 'demotion')
     and new.to_position_id is not distinct from new.from_position_id
     and new.to_job_profile_id is not distinct from new.from_job_profile_id
     and new.to_grade_id is not distinct from new.from_grade_id
     and new.to_business_title is not distinct from new.from_business_title then
    raise exception '晋升或降职至少需要实际调整岗位、职级或任职称谓';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "app_private"."validate_hr_personnel_change_target"() OWNER TO "postgres";

--

--
-- Name: validate_hr_position_capacity(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."validate_hr_position_capacity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_incumbent_count integer;
begin
  select count(*)::integer
  into v_incumbent_count
  from public.hr_employee_assignment assignment_row
  where assignment_row.tenant_id = new.tenant_id
    and assignment_row.position_id = new.id
    and assignment_row.primary_assignment
    and assignment_row.effective_end is null
    and assignment_row.assignment_status <> 'ended';

  if new.headcount_limit < v_incumbent_count then
    raise exception '岗位编制上限不能低于当前任职人数（%）', v_incumbent_count;
  end if;
  if not new.multiple_incumbents_allowed and v_incumbent_count > 1 then
    raise exception '当前岗位已有多人任职，不能改为单人岗位';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "app_private"."validate_hr_position_capacity"() OWNER TO "postgres";

--

--
-- Name: workflow_condition_matches("jsonb", "jsonb"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."workflow_condition_matches"("p_context" "jsonb", "p_node" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
declare
  v_operator text := coalesce(p_node #>> '{condition,operator}', 'always');
  v_field text := p_node #>> '{condition,field}';
  v_expected jsonb := p_node #> '{condition,value}';
  v_actual jsonb;
begin
  if v_operator = 'always' then return true; end if;
  if v_field is null or v_field !~ '^[A-Za-z][A-Za-z0-9_.-]{0,79}$' then return false; end if;
  v_actual := p_context #> string_to_array(v_field, '.');
  if v_operator = 'not_empty' then return v_actual is not null and v_actual <> 'null'::jsonb and v_actual <> '""'::jsonb; end if;
  if v_operator = 'eq' then return v_actual = v_expected; end if;
  if v_operator = 'ne' then return v_actual is distinct from v_expected; end if;
  if v_operator in ('gt', 'gte', 'lt', 'lte') then
    begin
      return case v_operator
        when 'gt' then (v_actual #>> '{}')::numeric > (v_expected #>> '{}')::numeric
        when 'gte' then (v_actual #>> '{}')::numeric >= (v_expected #>> '{}')::numeric
        when 'lt' then (v_actual #>> '{}')::numeric < (v_expected #>> '{}')::numeric
        else (v_actual #>> '{}')::numeric <= (v_expected #>> '{}')::numeric end;
    exception when invalid_text_representation then return false; end;
  end if;
  if v_operator = 'in' then return jsonb_typeof(v_expected) = 'array' and v_expected @> jsonb_build_array(v_actual); end if;
  if v_operator = 'contains' then
    return case jsonb_typeof(v_actual)
      when 'array' then v_actual @> jsonb_build_array(v_expected)
      when 'string' then position(lower(v_expected #>> '{}') in lower(v_actual #>> '{}')) > 0
      else false end;
  end if;
  return false;
end;
$_$;


ALTER FUNCTION "app_private"."workflow_condition_matches"("p_context" "jsonb", "p_node" "jsonb") OWNER TO "postgres";

