--

--
-- Name: hr_absence_overview_secure("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_absence_overview_secure"("p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
begin
  if not app_private.can_execute_business_action('HrAbsence', 'Hr:Absence:View', null, false) then
    raise exception 'Missing absence view permission' using errcode = '42501';
  end if;
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;

  return jsonb_build_object(
    'pending_count', (select count(*) from public.hr_leave_request request_row
      where (p_tenant_id is null or request_row.tenant_id = p_tenant_id) and request_row.status = 'pending'),
    'upcoming_count', (select count(*) from public.hr_leave_request request_row
      where (p_tenant_id is null or request_row.tenant_id = p_tenant_id)
        and request_row.status = 'approved' and request_row.start_date between current_date and current_date + 30),
    'covered_employee_count', (select count(distinct balance_row.employee_id)
      from public.hr_leave_balance balance_row
      where (p_tenant_id is null or balance_row.tenant_id = p_tenant_id)
        and balance_row.balance_year = extract(year from current_date)::integer),
    'active_policy_count', (select count(*) from public.hr_leave_policy policy_row
      where (p_tenant_id is null or policy_row.tenant_id = p_tenant_id)
        and policy_row.status = 'active'
        and policy_row.effective_from <= current_date
        and coalesce(policy_row.effective_to, 'infinity'::date) >= current_date),
    'expiring_balance_count', (select count(*) from public.hr_leave_balance balance_row
      where (p_tenant_id is null or balance_row.tenant_id = p_tenant_id)
        and balance_row.expires_on between current_date and current_date + 30
        and balance_row.opening_amount + balance_row.accrued_amount + balance_row.adjusted_amount
          - balance_row.pending_amount - balance_row.used_amount - balance_row.expired_amount > 0)
  );
end;
$$;


ALTER FUNCTION "public"."hr_absence_overview_secure"("p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_act_compensation_record_secure("text", "uuid", "text", "date"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_act_compensation_record_secure"("p_kind" "text", "p_id" "uuid", "p_action" "text", "p_effective_to" "date" DEFAULT NULL::"date") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_band public.hr_salary_band%rowtype;
  v_compensation public.hr_employee_compensation%rowtype;
begin
  if not app_private.can_execute_business_action(
    'HrCompensation', 'Hr:Compensation:Approve', null, false
  ) then raise exception 'Missing compensation approve permission' using errcode = '42501'; end if;

  if p_kind = 'band' then
    select * into v_band from public.hr_salary_band
    where id = p_id and (app_private.is_platform_super() or tenant_id = v_tenant_id)
    for update;
    if not found then raise exception '薪级范围不存在或无权操作'; end if;
    if p_action = 'approve' then
      if v_band.status <> 'draft' then raise exception '只有草稿薪级范围可以批准'; end if;
      if exists (
        select 1 from public.hr_salary_band band_row
        where band_row.tenant_id = v_band.tenant_id
          and band_row.grade_id = v_band.grade_id
          and band_row.currency_code = v_band.currency_code
          and band_row.status = 'approved'
          and band_row.effective_from >= v_band.effective_from
          and band_row.effective_from <= coalesce(v_band.effective_to, 'infinity'::date)
      ) then raise exception '该职级在生效区间内已有已批准薪级范围'; end if;
      update public.hr_salary_band band_row
      set effective_to = v_band.effective_from - 1
      where band_row.tenant_id = v_band.tenant_id
        and band_row.grade_id = v_band.grade_id
        and band_row.currency_code = v_band.currency_code
        and band_row.status = 'approved'
        and band_row.effective_from < v_band.effective_from
        and coalesce(band_row.effective_to, 'infinity'::date) >= v_band.effective_from;
      update public.hr_salary_band set status = 'approved' where id = p_id;
    elsif p_action = 'cancel' then
      if v_band.status = 'approved' and v_band.effective_from <= current_date then
        raise exception '已生效薪级范围不能取消，请新建后续版本';
      end if;
      if v_band.status = 'cancelled' then raise exception '薪级范围已取消'; end if;
      update public.hr_salary_band set status = 'cancelled' where id = p_id;
    else raise exception '不支持的薪级范围操作'; end if;
    return true;
  end if;

  if p_kind <> 'employee' then raise exception '不支持的薪酬操作类型'; end if;
  select * into v_compensation from public.hr_employee_compensation
  where id = p_id and (app_private.is_platform_super() or tenant_id = v_tenant_id)
  for update;
  if not found then raise exception '员工薪酬不存在或无权操作'; end if;

  if p_action = 'approve' then
    if v_compensation.status <> 'draft' then raise exception '只有草稿员工薪酬可以批准'; end if;
    if exists (
      select 1 from public.hr_employee_compensation compensation_row
      where compensation_row.tenant_id = v_compensation.tenant_id
        and compensation_row.employee_id = v_compensation.employee_id
        and compensation_row.status = 'approved'
        and compensation_row.effective_from >= v_compensation.effective_from
        and compensation_row.effective_from <= coalesce(v_compensation.effective_to, 'infinity'::date)
    ) then raise exception '该员工在生效区间内已有已批准薪酬'; end if;
    update public.hr_employee_compensation compensation_row
    set effective_to = v_compensation.effective_from - 1
    where compensation_row.tenant_id = v_compensation.tenant_id
      and compensation_row.employee_id = v_compensation.employee_id
      and compensation_row.status = 'approved'
      and compensation_row.effective_from < v_compensation.effective_from
      and coalesce(compensation_row.effective_to, 'infinity'::date) >= v_compensation.effective_from;
    update public.hr_employee_compensation set
      status = 'approved', approved_by = coalesce(auth.uid()::text, 'system'), approved_at = now()
    where id = p_id;
  elsif p_action = 'cancel' then
    if v_compensation.status = 'approved' and v_compensation.effective_from <= current_date then
      raise exception '已生效员工薪酬不能取消，请使用终止或新建调薪记录';
    end if;
    if v_compensation.status = 'cancelled' then raise exception '员工薪酬已取消'; end if;
    update public.hr_employee_compensation set status = 'cancelled' where id = p_id;
  elsif p_action = 'end' then
    if v_compensation.status <> 'approved'
      or v_compensation.effective_from > current_date then
      raise exception '只有已生效员工薪酬可以终止';
    end if;
    if p_effective_to is null or p_effective_to < v_compensation.effective_from then
      raise exception '请选择有效的终止日期';
    end if;
    update public.hr_employee_compensation set effective_to = p_effective_to where id = p_id;
  else raise exception '不支持的员工薪酬操作'; end if;
  return true;
end;
$$;


ALTER FUNCTION "public"."hr_act_compensation_record_secure"("p_kind" "text", "p_id" "uuid", "p_action" "text", "p_effective_to" "date") OWNER TO "postgres";

--

--
-- Name: hr_act_leave_request_secure("uuid", "text", "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_act_leave_request_secure"("p_request_id" "uuid", "p_action" "text", "p_comment" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_request public.hr_leave_request%rowtype;
  v_balance public.hr_leave_balance%rowtype;
  v_policy public.hr_leave_policy%rowtype;
  v_available numeric(12, 2);
  v_permission text;
begin
  if p_action not in ('submit', 'approve', 'reject', 'cancel') then
    raise exception '不支持的休假申请动作';
  end if;
  v_permission := case when p_action in ('approve', 'reject')
    then 'Hr:Absence:Approve' else 'Hr:Absence:Submit' end;
  if not app_private.can_execute_business_action('HrAbsence', v_permission, null, false) then
    raise exception 'Missing leave request action permission' using errcode = '42501';
  end if;

  select * into v_request from public.hr_leave_request where id = p_request_id for update;
  if v_request.id is null then raise exception '休假申请不存在'; end if;
  if not app_private.is_platform_super() and v_request.tenant_id <> app_private.current_user_tenant_id() then
    raise exception '不能处理其他租户的休假申请' using errcode = '42501';
  end if;

  if p_action = 'submit' then
    if v_request.status <> 'draft' then raise exception '仅草稿申请可提交'; end if;
    v_request.balance_id := app_private.hr_ensure_leave_balance(
      v_request.tenant_id, v_request.employee_id, v_request.leave_type_id,
      extract(year from v_request.start_date)::integer, v_request.start_date
    );
    select * into v_balance from public.hr_leave_balance where id = v_request.balance_id for update;
    select * into v_policy from public.hr_leave_policy where id = v_balance.policy_id;
    v_available := v_balance.opening_amount + v_balance.accrued_amount + v_balance.adjusted_amount
      - v_balance.pending_amount - v_balance.used_amount - v_balance.expired_amount;
    if (not v_policy.allow_negative and v_available < v_request.requested_amount)
      or (v_policy.allow_negative and v_available - v_request.requested_amount < -v_policy.negative_limit) then
      raise exception '可用休假余额不足';
    end if;
    update public.hr_leave_balance set pending_amount = pending_amount + v_request.requested_amount
      where id = v_balance.id;
    insert into public.hr_leave_ledger(
      tenant_id, balance_id, employee_id, leave_type_id, request_id,
      transaction_type, delta_pending, occurred_on, reason, idempotency_key
    ) values (
      v_request.tenant_id, v_balance.id, v_request.employee_id, v_request.leave_type_id,
      v_request.id, 'reservation', v_request.requested_amount, current_date,
      '提交休假申请 ' || v_request.request_no, 'request:' || v_request.id::text || ':submit'
    );
    update public.hr_leave_request set status = 'pending', balance_id = v_balance.id,
      policy_id = v_balance.policy_id, submitted_at = now()
    where id = v_request.id;
    return true;
  end if;

  if p_action = 'approve' then
    if v_request.status <> 'pending' then raise exception '仅待审批申请可批准'; end if;
    select * into v_balance from public.hr_leave_balance where id = v_request.balance_id for update;
    if v_balance.pending_amount < v_request.requested_amount then raise exception '待审批余额数据不一致'; end if;
    update public.hr_leave_balance set
      pending_amount = pending_amount - v_request.requested_amount,
      used_amount = used_amount + v_request.requested_amount
    where id = v_balance.id;
    insert into public.hr_leave_ledger(
      tenant_id, balance_id, employee_id, leave_type_id, request_id,
      transaction_type, delta_pending, delta_used, occurred_on, reason, idempotency_key
    ) values (
      v_request.tenant_id, v_balance.id, v_request.employee_id, v_request.leave_type_id,
      v_request.id, 'usage', -v_request.requested_amount, v_request.requested_amount,
      v_request.start_date, '批准休假申请 ' || v_request.request_no,
      'request:' || v_request.id::text || ':approve'
    );
    update public.hr_leave_request set status = 'approved', reviewed_at = now(),
      reviewed_by = coalesce((select user_email from public.sys_user
        where id = app_private.current_app_user_id()), auth.uid()::text, 'system'),
      review_comment = nullif(btrim(p_comment), '')
    where id = v_request.id;
    return true;
  end if;

  if p_action = 'reject' then
    if v_request.status <> 'pending' then raise exception '仅待审批申请可驳回'; end if;
    if nullif(btrim(p_comment), '') is null then raise exception '请输入驳回原因'; end if;
    select * into v_balance from public.hr_leave_balance where id = v_request.balance_id for update;
    update public.hr_leave_balance set pending_amount = pending_amount - v_request.requested_amount
      where id = v_balance.id;
    insert into public.hr_leave_ledger(
      tenant_id, balance_id, employee_id, leave_type_id, request_id,
      transaction_type, delta_pending, occurred_on, reason, idempotency_key
    ) values (
      v_request.tenant_id, v_balance.id, v_request.employee_id, v_request.leave_type_id,
      v_request.id, 'release', -v_request.requested_amount, current_date,
      '驳回休假申请：' || btrim(p_comment), 'request:' || v_request.id::text || ':reject'
    );
    update public.hr_leave_request set status = 'rejected', reviewed_at = now(),
      reviewed_by = coalesce((select user_email from public.sys_user
        where id = app_private.current_app_user_id()), auth.uid()::text, 'system'),
      review_comment = btrim(p_comment)
    where id = v_request.id;
    return true;
  end if;

  if v_request.status = 'draft' then
    update public.hr_leave_request set status = 'cancelled', review_comment = nullif(btrim(p_comment), '')
      where id = v_request.id;
    return true;
  elsif v_request.status = 'pending' then
    select * into v_balance from public.hr_leave_balance where id = v_request.balance_id for update;
    update public.hr_leave_balance set pending_amount = pending_amount - v_request.requested_amount
      where id = v_balance.id;
    insert into public.hr_leave_ledger(
      tenant_id, balance_id, employee_id, leave_type_id, request_id,
      transaction_type, delta_pending, occurred_on, reason, idempotency_key
    ) values (
      v_request.tenant_id, v_balance.id, v_request.employee_id, v_request.leave_type_id,
      v_request.id, 'release', -v_request.requested_amount, current_date,
      '撤销休假申请 ' || v_request.request_no, 'request:' || v_request.id::text || ':cancel'
    );
  elsif v_request.status = 'approved' then
    if v_request.start_date < current_date then raise exception '已开始的休假不能直接撤销，请走考勤冲销流程'; end if;
    select * into v_balance from public.hr_leave_balance where id = v_request.balance_id for update;
    update public.hr_leave_balance set used_amount = used_amount - v_request.requested_amount
      where id = v_balance.id;
    insert into public.hr_leave_ledger(
      tenant_id, balance_id, employee_id, leave_type_id, request_id,
      transaction_type, delta_used, occurred_on, reason, idempotency_key
    ) values (
      v_request.tenant_id, v_balance.id, v_request.employee_id, v_request.leave_type_id,
      v_request.id, 'reversal', -v_request.requested_amount, current_date,
      '撤销已批准休假 ' || v_request.request_no, 'request:' || v_request.id::text || ':cancel-approved'
    );
  else
    raise exception '当前申请状态不能撤销';
  end if;
  update public.hr_leave_request set status = 'cancelled', review_comment = nullif(btrim(p_comment), '')
  where id = v_request.id;
  return true;
end;
$$;


ALTER FUNCTION "public"."hr_act_leave_request_secure"("p_request_id" "uuid", "p_action" "text", "p_comment" "text") OWNER TO "postgres";

--

--
-- Name: hr_adjust_leave_balance_secure("uuid", "uuid", integer, numeric, "text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_adjust_leave_balance_secure"("p_employee_id" "uuid", "p_leave_type_id" "uuid", "p_balance_year" integer, "p_delta" numeric, "p_reason" "text", "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_balance public.hr_leave_balance%rowtype;
  v_policy public.hr_leave_policy%rowtype;
begin
  if not app_private.can_execute_business_action('HrAbsence', 'Hr:Absence:Balance:Adjust', null, false) then
    raise exception 'Missing leave balance adjustment permission' using errcode = '42501';
  end if;
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;
  p_tenant_id := coalesce(p_tenant_id, v_tenant_id);
  if p_delta = 0 then raise exception '调整数量不能为 0'; end if;
  if nullif(btrim(p_reason), '') is null then raise exception '请输入余额调整原因'; end if;

  perform app_private.hr_ensure_leave_balance(
    p_tenant_id, p_employee_id, p_leave_type_id, p_balance_year,
    make_date(p_balance_year, 1, 1)
  );
  select * into v_balance from public.hr_leave_balance
  where tenant_id = p_tenant_id and employee_id = p_employee_id
    and leave_type_id = p_leave_type_id and balance_year = p_balance_year
  for update;
  select * into v_policy from public.hr_leave_policy where id = v_balance.policy_id;

  if not v_policy.allow_negative and
    v_balance.opening_amount + v_balance.accrued_amount + v_balance.adjusted_amount + p_delta
      - v_balance.pending_amount - v_balance.used_amount - v_balance.expired_amount < 0 then
    raise exception '调整后可用余额不能小于 0';
  end if;
  if v_policy.allow_negative and
    v_balance.opening_amount + v_balance.accrued_amount + v_balance.adjusted_amount + p_delta
      - v_balance.pending_amount - v_balance.used_amount - v_balance.expired_amount < -v_policy.negative_limit then
    raise exception '调整后余额超过政策允许的负数额度';
  end if;

  update public.hr_leave_balance set adjusted_amount = adjusted_amount + p_delta
  where id = v_balance.id;
  insert into public.hr_leave_ledger(
    tenant_id, balance_id, employee_id, leave_type_id, transaction_type,
    delta_adjusted, occurred_on, reason, idempotency_key
  ) values (
    p_tenant_id, v_balance.id, p_employee_id, p_leave_type_id, 'adjustment',
    p_delta, current_date, btrim(p_reason), 'adjust:' || gen_random_uuid()::text
  );
  return v_balance.id;
end;
$$;


ALTER FUNCTION "public"."hr_adjust_leave_balance_secure"("p_employee_id" "uuid", "p_leave_type_id" "uuid", "p_balance_year" integer, "p_delta" numeric, "p_reason" "text", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_attendance_overview_secure("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_attendance_overview_secure"("p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
begin
  if not app_private.can_execute_business_action('HrAttendance', 'Hr:Attendance:View', null, false) then
    raise exception '当前账号没有查看考勤工时的权限' using errcode = '42501';
  end if;
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;

  return jsonb_build_object(
    'active_shift_count', (select count(*) from public.hr_shift s
      where (p_tenant_id is null or s.tenant_id = p_tenant_id) and s.enabled),
    'today_assignment_count', (select count(*) from public.hr_shift_assignment a
      where (p_tenant_id is null or a.tenant_id = p_tenant_id)
        and a.work_date = current_date and a.assignment_status <> 'cancelled'),
    'open_exception_count', (select count(*) from public.hr_attendance_record r
      where (p_tenant_id is null or r.tenant_id = p_tenant_id) and r.exception_status = 'open'),
    'pending_correction_count', (select count(*) from public.hr_attendance_correction c
      where (p_tenant_id is null or c.tenant_id = p_tenant_id) and c.status = 'submitted'),
    'reviewing_period_count', (select count(*) from public.hr_attendance_period p
      where (p_tenant_id is null or p.tenant_id = p_tenant_id) and p.status = 'reviewing'),
    'month_completion_rate', (
      select coalesce(round(100 * count(*) filter (where r.exception_status <> 'open')::numeric
        / nullif(count(*), 0), 1), 0)
      from public.hr_attendance_record r
      where (p_tenant_id is null or r.tenant_id = p_tenant_id)
        and r.work_date >= date_trunc('month', current_date)::date
        and r.work_date < (date_trunc('month', current_date) + interval '1 month')::date
    )
  );
end
$$;


ALTER FUNCTION "public"."hr_attendance_overview_secure"("p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_benefit_payroll_inputs_secure("date", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_benefit_payroll_inputs_secure"("p_payroll_month" "date", "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_month_start date := date_trunc('month', p_payroll_month)::date;
  v_month_end date := (date_trunc('month', p_payroll_month) + interval '1 month - 1 day')::date;
begin
  if auth.uid() is null or not app_private.can_execute_business_action(
    'HrBenefits', 'Hr:Benefits:Payroll:Export', null, false
  ) then raise exception '当前账号没有导出福利薪资输入的权限' using errcode = '42501'; end if;
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;

  return coalesce((select jsonb_agg(jsonb_build_object(
    'enrollment_id', enrollment.id, 'enrollment_no', enrollment.enrollment_no,
    'tenant_id', enrollment.tenant_id, 'employee_id', enrollment.employee_id,
    'employee_no', employee.employee_no, 'employee_name', employee.employee_name,
    'plan_id', plan.id, 'plan_code', plan.plan_code, 'plan_name', plan.plan_name,
    'plan_type', plan.plan_type, 'option_id', option.id,
    'option_code', option.option_code, 'option_name', option.option_name,
    'pay_component_id', option.pay_component_id,
    'employee_contribution', enrollment.employee_contribution,
    'employer_contribution', enrollment.employer_contribution,
    'currency_code', enrollment.currency_code,
    'coverage_from', enrollment.coverage_from, 'coverage_to', enrollment.coverage_to
  ) order by employee.employee_no, plan.plan_code)
  from public.hr_employee_benefit_enrollment enrollment
  join public.mdm_employee employee on employee.id = enrollment.employee_id
    and employee.tenant_id = enrollment.tenant_id
  join public.hr_benefit_plan plan on plan.id = enrollment.plan_id
    and plan.tenant_id = enrollment.tenant_id
  join public.hr_benefit_option option on option.id = enrollment.option_id
    and option.tenant_id = enrollment.tenant_id
  where (p_tenant_id is null or enrollment.tenant_id = p_tenant_id)
    and enrollment.status = 'active'
    and enrollment.payroll_sync_status in ('ready', 'exported')
    and enrollment.coverage_from <= v_month_end
    and (enrollment.coverage_to is null or enrollment.coverage_to >= v_month_start)), '[]'::jsonb);
end
$$;


ALTER FUNCTION "public"."hr_benefit_payroll_inputs_secure"("p_payroll_month" "date", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_benefit_plan_options_secure("uuid", "uuid", boolean); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_benefit_plan_options_secure"("p_plan_id" "uuid" DEFAULT NULL::"uuid", "p_tenant_id" "uuid" DEFAULT NULL::"uuid", "p_active_only" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_amount_visible boolean := app_private.hr_benefit_amount_visible();
begin
  if auth.uid() is null or not app_private.can_execute_business_action(
    'HrBenefits', 'Hr:Benefits:View', null, false
  ) then
    raise exception '当前账号没有查看福利计划的权限' using errcode = '42501';
  end if;
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;

  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', option.id, 'tenant_id', option.tenant_id,
      'plan_id', option.plan_id, 'option_code', option.option_code,
      'option_name', option.option_name, 'coverage_level', option.coverage_level,
      'contribution_type', option.contribution_type,
      'employee_contribution', case when v_amount_visible then option.employee_contribution else null end,
      'employer_contribution', case when v_amount_visible then option.employer_contribution else null end,
      'employee_rate', case when v_amount_visible then option.employee_rate else null end,
      'employer_rate', case when v_amount_visible then option.employer_rate else null end,
      'pay_component_id', option.pay_component_id, 'enabled', option.enabled,
      'sort', option.sort, 'description', option.description,
      'plan', jsonb_build_object(
        'id', plan.id, 'plan_code', plan.plan_code, 'plan_name', plan.plan_name,
        'plan_type', plan.plan_type, 'currency_code', plan.currency_code,
        'status', plan.status
      )
    ) order by plan.plan_name, option.sort, option.option_name)
    from public.hr_benefit_option option
    join public.hr_benefit_plan plan on plan.id = option.plan_id
      and plan.tenant_id = option.tenant_id
    where (p_tenant_id is null or option.tenant_id = p_tenant_id)
      and (p_plan_id is null or option.plan_id = p_plan_id)
      and (not p_active_only or (option.enabled and plan.status = 'active'))
  ), '[]'::jsonb);
end
$$;


ALTER FUNCTION "public"."hr_benefit_plan_options_secure"("p_plan_id" "uuid", "p_tenant_id" "uuid", "p_active_only" boolean) OWNER TO "postgres";

--

--
-- Name: hr_benefits_overview_secure("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_benefits_overview_secure"("p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_amount_visible boolean := app_private.hr_benefit_amount_visible();
begin
  if auth.uid() is null or not app_private.can_execute_business_action(
    'HrBenefits', 'Hr:Benefits:View', null, false
  ) then
    raise exception '当前账号没有查看福利与参保的权限' using errcode = '42501';
  end if;
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;

  return jsonb_build_object(
    'active_plan_count', (
      select count(*) from public.hr_benefit_plan plan
      where (p_tenant_id is null or plan.tenant_id = p_tenant_id)
        and plan.status = 'active'
        and plan.effective_from <= current_date
        and (plan.effective_to is null or plan.effective_to >= current_date)
    ),
    'active_enrollment_count', (
      select count(*) from public.hr_employee_benefit_enrollment enrollment
      where (p_tenant_id is null or enrollment.tenant_id = p_tenant_id)
        and enrollment.status = 'active'
        and enrollment.coverage_from <= current_date
        and (enrollment.coverage_to is null or enrollment.coverage_to >= current_date)
    ),
    'pending_enrollment_count', (
      select count(*) from public.hr_employee_benefit_enrollment enrollment
      where (p_tenant_id is null or enrollment.tenant_id = p_tenant_id)
        and enrollment.status = 'pending'
    ),
    'open_event_count', (
      select count(*) from public.hr_benefit_life_event event
      where (p_tenant_id is null or event.tenant_id = p_tenant_id)
        and event.status = 'open' and event.enrollment_window_end >= current_date
    ),
    'expiring_event_count', (
      select count(*) from public.hr_benefit_life_event event
      where (p_tenant_id is null or event.tenant_id = p_tenant_id)
        and event.status = 'open'
        and event.enrollment_window_end between current_date and current_date + 7
    ),
    'monthly_employee_contribution', case when v_amount_visible then (
      select coalesce(sum(enrollment.employee_contribution), 0)
      from public.hr_employee_benefit_enrollment enrollment
      where (p_tenant_id is null or enrollment.tenant_id = p_tenant_id)
        and enrollment.status = 'active'
        and enrollment.coverage_from <= current_date
        and (enrollment.coverage_to is null or enrollment.coverage_to >= current_date)
    ) else null end,
    'monthly_employer_contribution', case when v_amount_visible then (
      select coalesce(sum(enrollment.employer_contribution), 0)
      from public.hr_employee_benefit_enrollment enrollment
      where (p_tenant_id is null or enrollment.tenant_id = p_tenant_id)
        and enrollment.status = 'active'
        and enrollment.coverage_from <= current_date
        and (enrollment.coverage_to is null or enrollment.coverage_to >= current_date)
    ) else null end,
    'amount_visible', v_amount_visible
  );
end
$$;


ALTER FUNCTION "public"."hr_benefits_overview_secure"("p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_cancel_recruitment_interview_secure("uuid", boolean, "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_cancel_recruitment_interview_secure"("p_interview_id" "uuid", "p_no_show" boolean DEFAULT false, "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
begin
  if not app_private.can_execute_business_action('HrRecruitment', 'Hr:Recruitment:Interview:Edit', null, false) then
    raise exception '当前账号没有取消面试的权限' using errcode = '42501';
  end if;
  if nullif(btrim(p_reason), '') is null then raise exception '取消面试必须填写原因'; end if;
  update public.hr_recruitment_interview
  set status = case when p_no_show then 'no_show' else 'cancelled' end,
      feedback = btrim(p_reason), completed_at = null
  where id = p_interview_id and status = 'scheduled'
    and (app_private.is_platform_super() or tenant_id = v_tenant_id);
  if not found then raise exception '待进行的面试不存在或无权操作'; end if;
end
$$;


ALTER FUNCTION "public"."hr_cancel_recruitment_interview_secure"("p_interview_id" "uuid", "p_no_show" boolean, "p_reason" "text") OWNER TO "postgres";

--

--
-- Name: hr_compensation_overview_secure("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_compensation_overview_secure"("p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_employee_count integer := 0;
  v_covered_count integer := 0;
begin
  if not app_private.can_execute_business_action(
    'HrCompensation', 'Hr:Compensation:View', null, false
  ) then
    raise exception 'Missing compensation view permission' using errcode = '42501';
  end if;
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;

  select count(*)::integer into v_employee_count
  from public.mdm_employee employee_row
  where (p_tenant_id is null or employee_row.tenant_id = p_tenant_id)
    and employee_row.employment_status in ('probation', 'active', 'leave');

  select count(distinct compensation_row.employee_id)::integer into v_covered_count
  from public.hr_employee_compensation compensation_row
  join public.mdm_employee employee_row
    on employee_row.id = compensation_row.employee_id
   and employee_row.tenant_id = compensation_row.tenant_id
  where (p_tenant_id is null or compensation_row.tenant_id = p_tenant_id)
    and employee_row.employment_status in ('probation', 'active', 'leave')
    and compensation_row.status = 'approved'
    and compensation_row.effective_from <= current_date
    and coalesce(compensation_row.effective_to, 'infinity'::date) >= current_date;

  return jsonb_build_object(
    'employee_count', v_employee_count,
    'covered_count', v_covered_count,
    'coverage_rate', case when v_employee_count = 0 then 0
      else round(v_covered_count::numeric * 100 / v_employee_count, 1) end,
    'scheduled_count', (
      select count(*) from public.hr_employee_compensation compensation_row
      where (p_tenant_id is null or compensation_row.tenant_id = p_tenant_id)
        and compensation_row.status = 'approved'
        and compensation_row.effective_from > current_date
    ),
    'enabled_plan_count', (
      select count(*) from public.hr_compensation_plan plan_row
      where (p_tenant_id is null or plan_row.tenant_id = p_tenant_id)
        and plan_row.enabled
    ),
    'enabled_component_count', (
      select count(*) from public.hr_pay_component component_row
      where (p_tenant_id is null or component_row.tenant_id = p_tenant_id)
        and component_row.enabled
    )
  );
end;
$$;


ALTER FUNCTION "public"."hr_compensation_overview_secure"("p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_compensation_payroll_inputs_secure("date", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_compensation_payroll_inputs_secure"("p_payroll_month" "date", "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_month_start date := date_trunc('month', p_payroll_month)::date;
  v_month_end date := (date_trunc('month', p_payroll_month) + interval '1 month - 1 day')::date;
begin
  if not (
    app_private.can_execute_business_action(
      'HrCompensation', 'Hr:Compensation:Amount:View', null, false
    )
    or app_private.can_execute_business_action(
      'FinancePayroll', 'FinancePayroll:Edit', null, false
    )
    or app_private.can_execute_business_action(
      'FinancePayroll', 'FinancePayroll:Calculate', null, false
    )
  ) then raise exception 'Missing payroll input permission' using errcode = '42501'; end if;
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;
  if p_tenant_id is null then raise exception '请选择所属租户'; end if;

  return coalesce((
    with effective_compensation as (
      select distinct on (compensation_row.employee_id)
        compensation_row.*, employee_row.employee_no, employee_row.employee_name,
        organization_row.organization_name, plan_row.plan_code, plan_row.plan_name
      from public.hr_employee_compensation compensation_row
      join public.mdm_employee employee_row
        on employee_row.id = compensation_row.employee_id
       and employee_row.tenant_id = compensation_row.tenant_id
      left join public.mdm_organization organization_row on organization_row.id = employee_row.organization_id
      join public.hr_compensation_plan plan_row
        on plan_row.id = compensation_row.plan_id
       and plan_row.tenant_id = compensation_row.tenant_id
      where compensation_row.tenant_id = p_tenant_id
        and compensation_row.status = 'approved'
        and compensation_row.effective_from <= v_month_end
        and coalesce(compensation_row.effective_to, 'infinity'::date) >= v_month_start
      order by compensation_row.employee_id, compensation_row.effective_from desc
    )
    select jsonb_agg(jsonb_build_object(
      'compensation_id', compensation_row.id,
      'employee_id', compensation_row.employee_id,
      'employee_no', compensation_row.employee_no,
      'employee_name', compensation_row.employee_name,
      'organization_name', compensation_row.organization_name,
      'plan_code', compensation_row.plan_code,
      'plan_name', compensation_row.plan_name,
      'currency_code', compensation_row.currency_code,
      'pay_frequency', compensation_row.pay_frequency,
      'effective_from', compensation_row.effective_from,
      'effective_to', compensation_row.effective_to,
      'base_amount', compensation_row.base_amount,
      'earning_items', jsonb_build_array(jsonb_build_object(
        'code', 'BASE_SALARY',
        'name', case compensation_row.pay_frequency
          when 'annual' then '月度基本工资'
          when 'hourly' then '基础时薪'
          else '基本工资' end,
        'amount', case compensation_row.pay_frequency
          when 'annual' then round(compensation_row.base_amount / 12, 2)
          else compensation_row.base_amount end,
        'source', 'hr_compensation'
      )) || coalesce((
        select jsonb_agg(jsonb_build_object(
          'code', component_row.component_code,
          'name', component_row.component_name,
          'amount', coalesce(
            item_row.amount,
            round((case compensation_row.pay_frequency
              when 'annual' then compensation_row.base_amount / 12
              else compensation_row.base_amount end) * item_row.rate, 2),
            0
          ),
          'rate', item_row.rate,
          'source', 'hr_compensation'
        ) order by component_row.sort, component_row.component_name)
        from public.hr_employee_compensation_item item_row
        join public.hr_pay_component component_row on component_row.id = item_row.component_id
        where item_row.compensation_id = compensation_row.id
          and component_row.category = 'earning'
      ), '[]'::jsonb),
      'deduction_items', coalesce((
        select jsonb_agg(jsonb_build_object(
          'code', component_row.component_code,
          'name', component_row.component_name,
          'amount', coalesce(
            item_row.amount,
            round((case compensation_row.pay_frequency
              when 'annual' then compensation_row.base_amount / 12
              else compensation_row.base_amount end) * item_row.rate, 2),
            0
          ),
          'rate', item_row.rate,
          'source', 'hr_compensation'
        ) order by component_row.sort, component_row.component_name)
        from public.hr_employee_compensation_item item_row
        join public.hr_pay_component component_row on component_row.id = item_row.component_id
        where item_row.compensation_id = compensation_row.id
          and component_row.category = 'deduction'
      ), '[]'::jsonb),
      'employer_cost_items', coalesce((
        select jsonb_agg(jsonb_build_object(
          'code', component_row.component_code,
          'name', component_row.component_name,
          'amount', coalesce(
            item_row.amount,
            round((case compensation_row.pay_frequency
              when 'annual' then compensation_row.base_amount / 12
              else compensation_row.base_amount end) * item_row.rate, 2),
            0
          ),
          'rate', item_row.rate,
          'source', 'hr_compensation'
        ) order by component_row.sort, component_row.component_name)
        from public.hr_employee_compensation_item item_row
        join public.hr_pay_component component_row on component_row.id = item_row.component_id
        where item_row.compensation_id = compensation_row.id
          and component_row.category = 'employer_cost'
      ), '[]'::jsonb)
    ) order by compensation_row.employee_name)
    from effective_compensation compensation_row
  ), '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."hr_compensation_payroll_inputs_secure"("p_payroll_month" "date", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_compensation_review_overview_secure("uuid", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_compensation_review_overview_secure"("p_cycle_id" "uuid" DEFAULT NULL::"uuid", "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    SET "TimeZone" TO 'Asia/Shanghai'
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_cycle public.hr_compensation_review_cycle%rowtype;
  v_amount_access boolean;
  v_budget numeric(18, 2) := 0;
  v_used numeric(18, 2) := 0;
begin
  if auth.uid() is null or not app_private.can_execute_business_action(
    'HrCompensationReview', 'Hr:CompensationReview:View', null, false
  ) then
    raise exception '当前账号没有查看调薪复核的权限' using errcode = '42501';
  end if;
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;
  v_amount_access := app_private.can_execute_business_action(
    'HrCompensationReview', 'Hr:CompensationReview:Amount:View', null, false
  );

  if p_cycle_id is not null then
    select * into v_cycle
    from public.hr_compensation_review_cycle cycle_row
    where cycle_row.id = p_cycle_id
      and (p_tenant_id is null or cycle_row.tenant_id = p_tenant_id);
  else
    select * into v_cycle
    from public.hr_compensation_review_cycle cycle_row
    where (p_tenant_id is null or cycle_row.tenant_id = p_tenant_id)
      and cycle_row.status <> 'cancelled'
    order by
      case cycle_row.status
        when 'open' then 1 when 'calibrating' then 2 when 'approved' then 3
        when 'draft' then 4 when 'effected' then 5 else 6
      end,
      cycle_row.effective_date desc,
      cycle_row.create_time desc
    limit 1;
  end if;

  if v_cycle.id is not null then
    select coalesce(sum(budget_amount), 0) into v_budget
    from public.hr_compensation_review_budget where cycle_id = v_cycle.id;

    select coalesce(sum(greatest(proposed_base_amount - current_base_amount, 0)), 0)
    into v_used
    from public.hr_compensation_review_item
    where cycle_id = v_cycle.id and status <> 'excluded';
  end if;

  return jsonb_build_object(
    'cycle_count', (
      select count(*) from public.hr_compensation_review_cycle cycle_row
      where (p_tenant_id is null or cycle_row.tenant_id = p_tenant_id)
        and cycle_row.status <> 'cancelled'
    ),
    'amount_access', v_amount_access,
    'selected_cycle', case when v_cycle.id is null then null else jsonb_build_object(
      'id', v_cycle.id,
      'tenant_id', v_cycle.tenant_id,
      'cycle_code', v_cycle.cycle_code,
      'cycle_name', v_cycle.cycle_name,
      'review_year', v_cycle.review_year,
      'effective_date', v_cycle.effective_date,
      'recommendation_due_date', v_cycle.recommendation_due_date,
      'calibration_due_date', v_cycle.calibration_due_date,
      'scope_organization_id', v_cycle.scope_organization_id,
      'currency_code', v_cycle.currency_code,
      'default_budget_percent', v_cycle.default_budget_percent,
      'guideline_min_percent', v_cycle.guideline_min_percent,
      'guideline_max_percent', v_cycle.guideline_max_percent,
      'status', v_cycle.status,
      'description', v_cycle.description,
      'decision_note', v_cycle.decision_note
    ) end,
    'eligible_count', case when v_cycle.id is null then 0 else (
      select count(*) from public.hr_compensation_review_item where cycle_id = v_cycle.id
    ) end,
    'pending_count', case when v_cycle.id is null then 0 else (
      select count(*) from public.hr_compensation_review_item
      where cycle_id = v_cycle.id and status = 'pending'
    ) end,
    'recommended_count', case when v_cycle.id is null then 0 else (
      select count(*) from public.hr_compensation_review_item
      where cycle_id = v_cycle.id and status = 'recommended'
    ) end,
    'calibrated_count', case when v_cycle.id is null then 0 else (
      select count(*) from public.hr_compensation_review_item
      where cycle_id = v_cycle.id and status in ('calibrated', 'approved', 'effected')
    ) end,
    'approved_count', case when v_cycle.id is null then 0 else (
      select count(*) from public.hr_compensation_review_item
      where cycle_id = v_cycle.id and status in ('approved', 'effected')
    ) end,
    'effected_count', case when v_cycle.id is null then 0 else (
      select count(*) from public.hr_compensation_review_item
      where cycle_id = v_cycle.id and status = 'effected'
    ) end,
    'excluded_count', case when v_cycle.id is null then 0 else (
      select count(*) from public.hr_compensation_review_item
      where cycle_id = v_cycle.id and status = 'excluded'
    ) end,
    'out_of_guideline_count', case when v_cycle.id is null then 0 else (
      select count(*)
      from public.hr_compensation_review_item item
      where item.cycle_id = v_cycle.id
        and item.status <> 'excluded'
        and item.current_base_amount > 0
        and round((item.proposed_base_amount - item.current_base_amount) * 100
          / item.current_base_amount, 4)
          not between v_cycle.guideline_min_percent and v_cycle.guideline_max_percent
    ) end,
    'budget_amount', case when v_amount_access then v_budget else null end,
    'proposed_increase_amount', case when v_amount_access then v_used else null end,
    'budget_utilization', case
      when not v_amount_access then null
      when v_budget = 0 and v_used = 0 then 0
      when v_budget = 0 then 100
      else round(v_used * 100 / v_budget, 1)
    end
  );
end;
$$;


ALTER FUNCTION "public"."hr_compensation_review_overview_secure"("p_cycle_id" "uuid", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_complete_recruitment_interview_secure("uuid", numeric, "text", "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_complete_recruitment_interview_secure"("p_interview_id" "uuid", "p_score" numeric, "p_recommendation" "text", "p_feedback" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
begin
  if not app_private.can_execute_business_action('HrRecruitment', 'Hr:Recruitment:Interview:Complete', null, false) then
    raise exception '当前账号没有提交面试评价的权限' using errcode = '42501';
  end if;
  if p_score not between 0 and 100 or p_recommendation not in ('strong_hire', 'hire', 'hold', 'no_hire')
    or nullif(btrim(p_feedback), '') is null then
    raise exception '请完整填写面试评分、建议和评价依据';
  end if;
  update public.hr_recruitment_interview
  set status = 'completed', score = p_score, recommendation = p_recommendation,
      feedback = btrim(p_feedback), completed_at = now()
  where id = p_interview_id and status = 'scheduled'
    and (app_private.is_platform_super() or tenant_id = v_tenant_id);
  if not found then raise exception '待进行的面试不存在或无权操作'; end if;
end
$$;


ALTER FUNCTION "public"."hr_complete_recruitment_interview_secure"("p_interview_id" "uuid", "p_score" numeric, "p_recommendation" "text", "p_feedback" "text") OWNER TO "postgres";

--

--
-- Name: hr_complete_recruitment_task_secure("uuid", boolean, "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_complete_recruitment_task_secure"("p_task_id" "uuid", "p_skip" boolean DEFAULT false, "p_note" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
begin
  if not app_private.can_execute_business_action('HrRecruitment', 'Hr:Recruitment:Task:Manage', null, false) then
    raise exception '当前账号没有处理入职任务的权限' using errcode = '42501';
  end if;
  if p_skip and nullif(btrim(p_note), '') is null then raise exception '跳过任务必须填写原因'; end if;
  update public.hr_recruitment_onboarding_task
  set status = case when p_skip then 'skipped' else 'completed' end,
      completion_note = nullif(btrim(p_note), ''), completed_at = now()
  where id = p_task_id and status in ('pending', 'in_progress')
    and (app_private.is_platform_super() or tenant_id = v_tenant_id);
  if not found then raise exception '待处理的入职任务不存在或无权操作'; end if;
end
$$;


ALTER FUNCTION "public"."hr_complete_recruitment_task_secure"("p_task_id" "uuid", "p_skip" boolean, "p_note" "text") OWNER TO "postgres";

--

--
-- Name: hr_compliance_overview_secure("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_compliance_overview_secure"("p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
begin
  if not app_private.can_execute_business_action(
    'HrCompliance', 'Hr:Compliance:View', null, false
  ) then
    raise exception '当前账号没有查看用工合规中心的权限' using errcode = '42501';
  end if;
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;

  return jsonb_build_object(
    'active_contract_count', (
      select count(*) from public.hr_employee_contract contract
      where (p_tenant_id is null or contract.tenant_id = p_tenant_id)
        and contract.contract_status in ('active', 'renewing')
    ),
    'contract_risk_count', (
      select count(*) from public.hr_employee_contract contract
      where (p_tenant_id is null or contract.tenant_id = p_tenant_id)
        and contract.contract_status in ('active', 'renewing')
        and contract.end_date is not null
        and contract.end_date <= current_date + contract.renewal_reminder_days
    ),
    'overdue_contract_count', (
      select count(*) from public.hr_employee_contract contract
      where (p_tenant_id is null or contract.tenant_id = p_tenant_id)
        and contract.contract_status in ('active', 'renewing')
        and contract.end_date < current_date
    ),
    'qualification_risk_count', (
      select count(*) from public.hr_employee_qualification qualification
      where (p_tenant_id is null or qualification.tenant_id = p_tenant_id)
        and qualification.status <> 'revoked'
        and qualification.expiry_date is not null
        and qualification.expiry_date <= current_date + qualification.reminder_days
    ),
    'expired_qualification_count', (
      select count(*) from public.hr_employee_qualification qualification
      where (p_tenant_id is null or qualification.tenant_id = p_tenant_id)
        and qualification.status <> 'revoked'
        and qualification.expiry_date < current_date
    ),
    'pending_verification_count', (
      select count(*) from public.hr_employee_qualification qualification
      where (p_tenant_id is null or qualification.tenant_id = p_tenant_id)
        and qualification.status <> 'revoked'
        and qualification.verification_status in ('pending', 'rejected')
    ),
    'verified_rate', (
      select coalesce(round(
        100 * count(*) filter (where qualification.verification_status = 'verified')::numeric
        / nullif(count(*) filter (where qualification.status <> 'revoked'), 0), 1
      ), 0)
      from public.hr_employee_qualification qualification
      where p_tenant_id is null or qualification.tenant_id = p_tenant_id
    )
  );
end
$$;


ALTER FUNCTION "public"."hr_compliance_overview_secure"("p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_contingent_workforce_overview_secure("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_contingent_workforce_overview_secure"("p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    SET "TimeZone" TO 'Asia/Shanghai'
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_today date := current_date;
begin
  if auth.uid() is null or not app_private.can_execute_business_action(
    'HrContingentWorkforce', 'Hr:ContingentWorkforce:View', null, false
  ) then
    raise exception '当前账号没有查看外部用工的权限' using errcode = '42501';
  end if;
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;

  return jsonb_build_object(
    'pii_access', app_private.can_execute_business_action(
      'HrContingentWorkforce', 'Hr:ContingentWorkforce:PII:View', null, false
    ),
    'cost_access', app_private.can_execute_business_action(
      'HrContingentWorkforce', 'Hr:ContingentWorkforce:Cost:View', null, false
    ),
    'active_vendor_count', (
      select count(*) from public.mdm_external_vendor vendor
      where (p_tenant_id is null or vendor.tenant_id = p_tenant_id)
        and vendor.status = 'active'
    ),
    'active_worker_count', (
      select count(*) from public.hr_external_worker worker
      where (p_tenant_id is null or worker.tenant_id = p_tenant_id)
        and worker.status = 'active'
    ),
    'active_engagement_count', (
      select count(*) from public.hr_external_engagement engagement
      where (p_tenant_id is null or engagement.tenant_id = p_tenant_id)
        and engagement.status = 'active'
    ),
    'pending_review_count', (
      select count(*) from public.hr_external_engagement engagement
      where (p_tenant_id is null or engagement.tenant_id = p_tenant_id)
        and engagement.status = 'pending_review'
    ),
    'pending_control_count', (
      select count(*)
      from public.hr_external_engagement_control control
      join public.hr_external_engagement engagement on engagement.id = control.engagement_id
      where (p_tenant_id is null or control.tenant_id = p_tenant_id)
        and engagement.status in ('draft', 'pending_review', 'active', 'offboarding')
        and control.required
        and control.status not in ('completed', 'waived')
    ),
    'ending_soon_count', (
      select count(*) from public.hr_external_engagement engagement
      where (p_tenant_id is null or engagement.tenant_id = p_tenant_id)
        and engagement.status = 'active'
        and engagement.end_date between v_today and v_today + 30
    ),
    'access_expiring_count', (
      select count(*) from public.hr_external_engagement engagement
      where (p_tenant_id is null or engagement.tenant_id = p_tenant_id)
        and engagement.status in ('active', 'offboarding')
        and engagement.access_expiry_date between v_today and v_today + 14
    ),
    'blocked_count', (
      select count(*) from public.hr_external_engagement engagement
      where (p_tenant_id is null or engagement.tenant_id = p_tenant_id)
        and engagement.status in ('draft', 'pending_review', 'active')
        and engagement.compliance_status = 'blocked'
    )
  );
end;
$$;


ALTER FUNCTION "public"."hr_contingent_workforce_overview_secure"("p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_create_employee_with_driver_secure("jsonb", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_create_employee_with_driver_secure"("p_employee" "jsonb", "p_driver" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_employee public.mdm_employee%rowtype;
  v_tenant_id uuid;
  v_employee_id uuid;
begin
  if not app_private.can_execute_business_action(
    'HrEmployeeRoster', 'Hr:Employee:Add', null, false
  ) then
    raise exception 'Missing employee create permission' using errcode = '42501';
  end if;
  if p_employee is null or jsonb_typeof(p_employee) <> 'object' then
    raise exception '员工数据格式不正确';
  end if;
  if p_driver is not null and p_driver <> 'null'::jsonb then
    raise exception '员工档案不再创建司机档案，请前往司机管理从员工花名册选取';
  end if;
  if exists (
    select 1
    from jsonb_object_keys(p_employee) key
    where key <> all(array[
      'tenant_id','organization_id','employee_no','employee_name','avatar_url','position_id',
      'employment_status','employment_type','gender','birth_date','phone','email','id_card_no',
      'ethnicity','education_level','school_name','major_name','marital_status','political_status',
      'native_place','home_address','hire_date','probation_end_date','leave_date',
      'contract_start_date','contract_end_date','emergency_contact_name',
      'emergency_contact_relation','emergency_contact_phone','remark'
    ]::text[])
  ) then
    raise exception '员工数据包含不允许写入的字段';
  end if;

  select * into v_employee
  from jsonb_populate_record(null::public.mdm_employee, p_employee);
  v_tenant_id := case when app_private.is_platform_super()
    then v_employee.tenant_id
    else app_private.current_user_tenant_id()
  end;
  if v_tenant_id is null then raise exception '请选择员工所属租户'; end if;

  if not exists (
    select 1
    from public.mdm_position position_row
    where position_row.id = v_employee.position_id
      and position_row.tenant_id = v_tenant_id
      and position_row.enabled
  ) then
    raise exception '所选岗位不存在、已停用或不属于当前租户';
  end if;
  if not exists (
    select 1
    from public.mdm_organization organization_row
    where organization_row.id = v_employee.organization_id
      and organization_row.tenant_id = v_tenant_id
      and organization_row.status = '1'
  ) then
    raise exception '所选组织不存在、已停用或不属于当前租户';
  end if;

  insert into public.mdm_employee (
    tenant_id, organization_id, employee_no, employee_name, avatar_url, position_id,
    employment_status, employment_type, gender, birth_date, phone, email, id_card_no,
    ethnicity, education_level, school_name, major_name, marital_status, political_status,
    native_place, home_address, hire_date, probation_end_date, leave_date,
    contract_start_date, contract_end_date, emergency_contact_name,
    emergency_contact_relation, emergency_contact_phone, remark, create_by
  ) values (
    v_tenant_id, v_employee.organization_id, btrim(v_employee.employee_no),
    btrim(v_employee.employee_name), v_employee.avatar_url, v_employee.position_id,
    coalesce(v_employee.employment_status, 'active'),
    coalesce(v_employee.employment_type, 'full_time'), v_employee.gender,
    v_employee.birth_date, v_employee.phone, v_employee.email, v_employee.id_card_no,
    v_employee.ethnicity, v_employee.education_level, v_employee.school_name,
    v_employee.major_name, v_employee.marital_status, v_employee.political_status,
    v_employee.native_place, v_employee.home_address, v_employee.hire_date,
    v_employee.probation_end_date, v_employee.leave_date, v_employee.contract_start_date,
    v_employee.contract_end_date, v_employee.emergency_contact_name,
    v_employee.emergency_contact_relation, v_employee.emergency_contact_phone,
    v_employee.remark, coalesce(auth.uid()::text, 'system')
  ) returning id into v_employee_id;

  return jsonb_build_object('employee_id', v_employee_id, 'driver_id', null);
end;
$$;


ALTER FUNCTION "public"."hr_create_employee_with_driver_secure"("p_employee" "jsonb", "p_driver" "jsonb") OWNER TO "postgres";

--

--
-- Name: hr_create_position_secure("jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_create_position_secure"("p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid;
  v_id uuid;
  v_organization_id uuid;
  v_job_profile_id uuid;
  v_grade_id uuid;
  v_headcount_limit integer;
  v_multiple boolean;
begin
  if not app_private.can_execute_business_action('HrPosition', 'Hr:Position:Add', null, false) then
    raise exception 'Missing position create permission' using errcode = '42501';
  end if;
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then raise exception '岗位数据格式不正确'; end if;
  if exists (
    select 1 from jsonb_object_keys(p_payload) key
    where key <> all(array[
      'tenant_id','organization_id','job_profile_id','grade_id','position_code','position_name',
      'enabled','sort','description','headcount_limit','multiple_incumbents_allowed'
    ]::text[])
  ) then raise exception '岗位数据包含不允许写入的字段'; end if;

  v_tenant_id := case when app_private.is_platform_super()
    then nullif(p_payload->>'tenant_id', '')::uuid else app_private.current_user_tenant_id() end;
  v_organization_id := nullif(p_payload->>'organization_id', '')::uuid;
  v_job_profile_id := nullif(p_payload->>'job_profile_id', '')::uuid;
  v_grade_id := nullif(p_payload->>'grade_id', '')::uuid;
  v_headcount_limit := coalesce((p_payload->>'headcount_limit')::integer, 1);
  v_multiple := coalesce((p_payload->>'multiple_incumbents_allowed')::boolean, false);
  if v_tenant_id is null then raise exception '请选择岗位所属租户'; end if;
  if v_organization_id is null then raise exception '请选择岗位所属组织'; end if;
  if v_job_profile_id is null then raise exception '请选择岗位对应的标准职务'; end if;
  if not v_multiple and v_headcount_limit <> 1 then raise exception '单人岗位的编制人数必须为 1'; end if;

  if not exists (select 1 from public.mdm_organization where id = v_organization_id and tenant_id = v_tenant_id and status = '1') then
    raise exception '所选组织不存在、已停用或不属于当前租户';
  end if;
  if not exists (select 1 from public.mdm_job_profile where id = v_job_profile_id and tenant_id = v_tenant_id and enabled) then
    raise exception '所选标准职务不存在、已停用或不属于当前租户';
  end if;
  if v_grade_id is not null and not exists (select 1 from public.mdm_grade where id = v_grade_id and tenant_id = v_tenant_id and enabled) then
    raise exception '所选职级不存在、已停用或不属于当前租户';
  end if;

  insert into public.mdm_position (
    tenant_id, organization_id, job_profile_id, grade_id, position_code, position_name,
    enabled, sort, description, headcount_limit, multiple_incumbents_allowed, create_by
  ) values (
    v_tenant_id, v_organization_id, v_job_profile_id, v_grade_id,
    upper(btrim(p_payload->>'position_code')), btrim(p_payload->>'position_name'),
    coalesce((p_payload->>'enabled')::boolean, true), coalesce((p_payload->>'sort')::integer, 0),
    nullif(btrim(p_payload->>'description'), ''), v_headcount_limit, v_multiple,
    coalesce(auth.uid()::text, 'system')
  ) returning id into v_id;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."hr_create_position_secure"("p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: hr_delete_absence_record_secure("text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_delete_absence_record_secure"("p_kind" "text", "p_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_permission text;
  v_count integer;
begin
  if p_kind not in ('type', 'policy', 'request') then raise exception '不支持的删除类型'; end if;
  v_permission := case when p_kind = 'request' then 'Hr:Absence:Request:Delete'
    else 'Hr:Absence:Policy:Delete' end;
  if not app_private.can_execute_business_action('HrAbsence', v_permission, null, false) then
    raise exception 'Missing absence delete permission' using errcode = '42501';
  end if;
  if p_kind = 'request' then
    delete from public.hr_leave_request where id = p_id and status = 'draft'
      and (app_private.is_platform_super() or tenant_id = app_private.current_user_tenant_id());
  elsif p_kind = 'policy' then
    delete from public.hr_leave_policy where id = p_id and status = 'draft'
      and not exists (select 1 from public.hr_leave_balance where policy_id = p_id)
      and (app_private.is_platform_super() or tenant_id = app_private.current_user_tenant_id());
  else
    delete from public.hr_leave_type where id = p_id
      and not exists (select 1 from public.hr_leave_policy where leave_type_id = p_id)
      and (app_private.is_platform_super() or tenant_id = app_private.current_user_tenant_id());
  end if;
  get diagnostics v_count = row_count;
  if v_count = 0 then raise exception '记录不存在、状态不可删除或已被业务引用'; end if;
  return true;
end;
$$;


ALTER FUNCTION "public"."hr_delete_absence_record_secure"("p_kind" "text", "p_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_delete_attendance_record_secure("text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_delete_attendance_record_secure"("p_kind" "text", "p_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid:=app_private.current_user_tenant_id();
  v_deleted integer;
begin
  if p_kind not in ('shift','assignment','correction','period') then raise exception '该类考勤记录不允许删除'; end if;
  if not app_private.can_execute_business_action('HrAttendance','Hr:Attendance:Delete',null,false) then
    raise exception '当前账号没有删除考勤记录的权限' using errcode='42501';
  end if;
  if p_kind='shift' then
    delete from public.hr_shift s where s.id=p_id and (app_private.is_platform_super() or s.tenant_id=v_tenant_id)
      and not exists(select 1 from public.hr_shift_assignment a where a.shift_id=s.id)
      and not exists(select 1 from public.hr_attendance_record r where r.shift_id=s.id);
  elsif p_kind='assignment' then
    delete from public.hr_shift_assignment a where a.id=p_id
      and (app_private.is_platform_super() or a.tenant_id=v_tenant_id) and a.assignment_status='scheduled'
      and not exists(select 1 from public.hr_attendance_record r where r.tenant_id=a.tenant_id
        and r.employee_id=a.employee_id and r.work_date=a.work_date)
      and not exists(select 1 from public.hr_attendance_period p where p.tenant_id=a.tenant_id and p.status='closed'
        and a.work_date>=p.period_month and a.work_date<p.period_month+interval '1 month');
  elsif p_kind='correction' then
    delete from public.hr_attendance_correction c where c.id=p_id
      and (app_private.is_platform_super() or c.tenant_id=v_tenant_id) and c.status='draft';
  else
    delete from public.hr_attendance_period p where p.id=p_id
      and (app_private.is_platform_super() or p.tenant_id=v_tenant_id) and p.status='open'
      and not exists(select 1 from public.hr_attendance_record r where r.tenant_id=p.tenant_id
        and r.work_date>=p.period_month and r.work_date<p.period_month+interval '1 month');
  end if;
  get diagnostics v_deleted=row_count;
  if v_deleted=0 then raise exception '记录不存在、状态不允许删除或已被业务引用'; end if;
end
$$;


ALTER FUNCTION "public"."hr_delete_attendance_record_secure"("p_kind" "text", "p_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_delete_compensation_record_secure("text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_delete_compensation_record_secure"("p_kind" "text", "p_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_tenant_id uuid := app_private.current_user_tenant_id();
begin
  if not app_private.can_execute_business_action(
    'HrCompensation',
    case when p_kind = 'employee' then 'Hr:Compensation:Record:Delete'
      else 'Hr:Compensation:Policy:Delete' end,
    null, false
  ) then raise exception 'Missing compensation delete permission' using errcode = '42501'; end if;

  if p_kind = 'employee' then
    delete from public.hr_employee_compensation
    where id = p_id and status = 'draft'
      and (app_private.is_platform_super() or tenant_id = v_tenant_id);
  elsif p_kind = 'band' then
    delete from public.hr_salary_band
    where id = p_id and status = 'draft'
      and (app_private.is_platform_super() or tenant_id = v_tenant_id);
  elsif p_kind = 'plan' then
    if exists (select 1 from public.hr_employee_compensation where plan_id = p_id) then
      raise exception '该薪酬方案已有员工薪酬记录，不能删除';
    end if;
    delete from public.hr_compensation_plan
    where id = p_id and (app_private.is_platform_super() or tenant_id = v_tenant_id);
  elsif p_kind = 'component' then
    if exists (select 1 from public.hr_compensation_plan_item where component_id = p_id) then
      raise exception '该薪酬项目已被方案使用，不能删除';
    end if;
    delete from public.hr_pay_component
    where id = p_id and (app_private.is_platform_super() or tenant_id = v_tenant_id);
  else
    raise exception '不支持的薪酬记录类型';
  end if;
  if not found then raise exception '仅草稿记录可删除，或记录不存在'; end if;
  return true;
end;
$$;


ALTER FUNCTION "public"."hr_delete_compensation_record_secure"("p_kind" "text", "p_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_delete_compensation_review_record_secure("text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_delete_compensation_review_record_secure"("p_kind" "text", "p_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_cycle_status text;
begin
  if p_kind not in ('cycle', 'budget') then raise exception '不支持删除该类调薪复核记录'; end if;
  if auth.uid() is null then raise exception '请先登录' using errcode = '42501'; end if;

  if p_kind = 'cycle' then
    if not app_private.can_execute_business_action(
      'HrCompensationReview', 'Hr:CompensationReview:Cycle:Manage', null, false
    ) then raise exception '当前账号没有管理调薪周期的权限' using errcode = '42501'; end if;
    select status into v_cycle_status from public.hr_compensation_review_cycle
    where id = p_id and (app_private.is_platform_super() or tenant_id = v_tenant_id) for update;
    if not found then raise exception '调薪周期不存在'; end if;
    if v_cycle_status <> 'draft' then raise exception '只有草稿周期可以删除'; end if;
    delete from public.hr_compensation_review_cycle where id = p_id;
    return true;
  end if;

  if not app_private.can_execute_business_action(
    'HrCompensationReview', 'Hr:CompensationReview:Budget:Manage', null, false
  ) then raise exception '当前账号没有管理调薪预算的权限' using errcode = '42501'; end if;
  select cycle_row.status into v_cycle_status
  from public.hr_compensation_review_budget budget
  join public.hr_compensation_review_cycle cycle_row
    on cycle_row.id = budget.cycle_id and cycle_row.tenant_id = budget.tenant_id
  where budget.id = p_id and (app_private.is_platform_super() or budget.tenant_id = v_tenant_id)
  for update of budget;
  if not found then raise exception '组织预算不存在'; end if;
  if v_cycle_status not in ('draft', 'open') then raise exception '当前阶段不能删除组织预算'; end if;
  delete from public.hr_compensation_review_budget where id = p_id;
  return true;
end;
$$;


ALTER FUNCTION "public"."hr_delete_compensation_review_record_secure"("p_kind" "text", "p_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_delete_compliance_record_secure("text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_delete_compliance_record_secure"("p_kind" "text", "p_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_status text;
  v_verification_status text;
  v_record_tenant uuid;
begin
  if not app_private.can_execute_business_action(
    'HrCompliance', 'Hr:Compliance:Delete', p_id, false
  ) then raise exception '当前账号没有删除合同或资质的权限' using errcode = '42501'; end if;

  if p_kind = 'contract' then
    select tenant_id, contract_status into v_record_tenant, v_status
    from public.hr_employee_contract where id = p_id for update;
    if not found or (not app_private.is_platform_super() and v_record_tenant <> v_tenant_id) then
      raise exception '劳动合同不存在或无权删除' using errcode = '42501';
    end if;
    if v_status <> 'draft' then raise exception '只有待签署合同可以删除'; end if;
    delete from public.hr_compliance_event
    where tenant_id = v_record_tenant and entity_type = 'contract' and entity_id = p_id;
    delete from public.hr_employee_contract where id = p_id;
  elsif p_kind = 'qualification' then
    select tenant_id, status, verification_status
      into v_record_tenant, v_status, v_verification_status
    from public.hr_employee_qualification where id = p_id for update;
    if not found or (not app_private.is_platform_super() and v_record_tenant <> v_tenant_id) then
      raise exception '员工资质不存在或无权删除' using errcode = '42501';
    end if;
    if v_status = 'revoked' or v_verification_status = 'verified' then
      raise exception '已核验或已撤销资质必须保留审计记录，不能删除';
    end if;
    delete from public.hr_compliance_event
    where tenant_id = v_record_tenant and entity_type = 'qualification' and entity_id = p_id;
    delete from public.hr_employee_qualification where id = p_id;
  else
    raise exception '不支持的用工合规记录类型';
  end if;
end
$$;


ALTER FUNCTION "public"."hr_delete_compliance_record_secure"("p_kind" "text", "p_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_delete_contingent_workforce_record_secure("text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_delete_contingent_workforce_record_secure"("p_kind" "text", "p_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_permission text;
begin
  if p_kind not in ('vendor', 'worker', 'engagement', 'control') then
    raise exception '不支持的外部用工记录类型';
  end if;
  v_permission := case p_kind
    when 'vendor' then 'Hr:ContingentWorkforce:Vendor:Manage'
    when 'worker' then 'Hr:ContingentWorkforce:Worker:Manage'
    when 'engagement' then 'Hr:ContingentWorkforce:Engagement:Manage'
    else 'Hr:ContingentWorkforce:Control:Manage'
  end;
  if auth.uid() is null or not app_private.can_execute_business_action(
    'HrContingentWorkforce', v_permission, null, false
  ) then
    raise exception '当前账号没有删除外部用工记录的权限' using errcode = '42501';
  end if;

  if p_kind = 'vendor' then
    delete from public.mdm_external_vendor
    where id = p_id and (app_private.is_platform_super() or tenant_id = v_tenant_id)
      and status = 'draft';
  elsif p_kind = 'worker' then
    delete from public.hr_external_worker
    where id = p_id and (app_private.is_platform_super() or tenant_id = v_tenant_id)
      and status = 'candidate';
  elsif p_kind = 'engagement' then
    delete from public.hr_external_engagement
    where id = p_id and (app_private.is_platform_super() or tenant_id = v_tenant_id)
      and status = 'draft';
  else
    delete from public.hr_external_engagement_control control
    using public.hr_external_engagement engagement
    where control.id = p_id and control.engagement_id = engagement.id
      and (app_private.is_platform_super() or control.tenant_id = v_tenant_id)
      and engagement.status in ('draft', 'pending_review');
  end if;
  if not found then raise exception '记录不存在、已进入流程或不允许删除'; end if;
  return true;
end;
$$;


ALTER FUNCTION "public"."hr_delete_contingent_workforce_record_secure"("p_kind" "text", "p_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_delete_employee_relations_record_secure("text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_delete_employee_relations_record_secure"("p_kind" "text", "p_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_case public.hr_employee_relation_case;
  v_action public.hr_employee_relation_action;
begin
  if p_kind = 'case' then
    if not app_private.can_execute_business_action(
      'HrEmployeeRelations', 'Hr:EmployeeRelations:Delete', p_id, false
    ) then
      raise exception '当前账号没有删除案件草稿的权限' using errcode = '42501';
    end if;
    select * into v_case from public.hr_employee_relation_case where id = p_id for update;
    if v_case.id is null or v_case.status <> 'draft'
      or not app_private.hr_employee_relation_case_visible(
        v_case.tenant_id, v_case.subject_employee_id, v_case.reporter_employee_id,
        v_case.owner_employee_id
      ) then
      raise exception '只有有权访问的案件草稿可以删除';
    end if;
    delete from public.hr_employee_relation_case where id = v_case.id;
    return true;
  elsif p_kind = 'action' then
    if not app_private.has_permission('Hr:EmployeeRelations:Action:Manage') then
      raise exception '当前账号没有删除处置行动的权限' using errcode = '42501';
    end if;
    select * into v_action from public.hr_employee_relation_action where id = p_id for update;
    if v_action.id is null or v_action.status <> 'planned' then
      raise exception '只有待开始的处置行动可以删除';
    end if;
    select * into v_case from public.hr_employee_relation_case where id = v_action.case_id;
    if not app_private.hr_employee_relation_case_visible(
      v_case.tenant_id, v_case.subject_employee_id, v_case.reporter_employee_id,
      v_case.owner_employee_id
    ) then
      raise exception '处置行动不存在或无权删除' using errcode = '42501';
    end if;
    delete from public.hr_employee_relation_action where id = v_action.id;
    perform app_private.hr_add_employee_relation_event(
      v_case, 'action_cancelled', v_case.status, v_case.status,
      '删除尚未启动的处置行动', jsonb_build_object('action_id', v_action.id)
    );
    return true;
  end if;
  raise exception '不支持的员工关系记录类型';
end
$$;


ALTER FUNCTION "public"."hr_delete_employee_relations_record_secure"("p_kind" "text", "p_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_delete_employee_secure("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_delete_employee_secure"("p_employee_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not app_private.can_execute_business_action(
    'HrEmployeeRoster', 'Hr:Employee:Delete', null, false
  ) then
    raise exception 'Missing employee delete permission' using errcode = '42501';
  end if;

  delete from public.mdm_employee employee_row
  where employee_row.id = p_employee_id
    and (
      app_private.is_platform_super()
      or employee_row.tenant_id = app_private.current_user_tenant_id()
    );
  if not found then
    raise exception '员工档案不存在或无权删除' using errcode = 'P0002';
  end if;
end;
$$;


ALTER FUNCTION "public"."hr_delete_employee_secure"("p_employee_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_delete_internal_mobility_record_secure("text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_delete_internal_mobility_record_secure"("p_kind" "text", "p_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_tenant_id uuid:=app_private.current_user_tenant_id(); v_employee_id uuid:=app_private.hr_current_employee_id();
begin
  if p_kind not in ('opportunity','application') then raise exception '不支持的内部人才市场删除类型'; end if;
  if p_kind='opportunity' then
    if auth.uid() is null or not app_private.can_execute_business_action('HrInternalMobility','Hr:InternalMobility:Opportunity:Manage',null,false)
      then raise exception '当前账号没有删除内部机会草稿的权限' using errcode='42501'; end if;
    delete from public.hr_internal_opportunity o where o.id=p_id and (app_private.is_platform_super() or o.tenant_id=v_tenant_id)
      and o.status='draft' and not exists(select 1 from public.hr_internal_mobility_application a where a.opportunity_id=o.id);
  else
    delete from public.hr_internal_mobility_application a where a.id=p_id
      and (app_private.is_platform_super() or a.tenant_id=v_tenant_id)
      and a.status='draft' and (a.employee_id=v_employee_id or app_private.can_execute_business_action('HrInternalMobility','Hr:InternalMobility:Application:Manage',null,false));
  end if;
  if not found then raise exception '记录不存在、已进入流程或不允许删除'; end if;
  return true;
end;
$$;


ALTER FUNCTION "public"."hr_delete_internal_mobility_record_secure"("p_kind" "text", "p_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_delete_job_architecture_record_secure("text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_delete_job_architecture_record_secure"("p_kind" "text", "p_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_tenant_id uuid:=app_private.current_user_tenant_id(); v_permission text;
begin
  v_permission:=case p_kind when 'family' then 'Hr:JobFamily:Delete' when 'grade' then 'Hr:Grade:Delete' when 'profile' then 'Hr:JobProfile:Delete' else null end;
  if v_permission is null then raise exception '不支持的职务体系记录类型'; end if;
  if not app_private.can_execute_business_action('HrJobArchitecture',v_permission,null,false) then raise exception 'Missing job architecture delete permission' using errcode='42501'; end if;
  if p_kind='family' then
    if exists(select 1 from public.mdm_job_profile where family_id=p_id) then raise exception '该职族已有标准职务使用，不能删除'; end if;
    delete from public.mdm_job_family where id=p_id and (app_private.is_platform_super() or tenant_id=v_tenant_id);
  elsif p_kind='grade' then
    if exists(select 1 from public.mdm_job_profile where default_grade_id=p_id) or exists(select 1 from public.mdm_position where grade_id=p_id) then raise exception '该职级正在使用，不能删除'; end if;
    delete from public.mdm_grade where id=p_id and (app_private.is_platform_super() or tenant_id=v_tenant_id);
  else
    if exists(select 1 from public.mdm_position where job_profile_id=p_id) then raise exception '该标准职务已有岗位使用，不能删除'; end if;
    delete from public.mdm_job_profile where id=p_id and (app_private.is_platform_super() or tenant_id=v_tenant_id);
  end if;
  if not found then raise exception '记录不存在或无权删除'; end if; return true;
end;
$$;


ALTER FUNCTION "public"."hr_delete_job_architecture_record_secure"("p_kind" "text", "p_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_delete_learning_record_secure("text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_delete_learning_record_secure"("p_kind" "text", "p_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_permission text;
begin
  v_permission := case p_kind
    when 'plan' then 'Hr:Talent:Delete'
    when 'course' then 'Hr:Talent:Course:Edit'
    when 'session' then 'Hr:Talent:Session:Edit'
    when 'enrollment' then 'Hr:Talent:Enrollment:Manage'
    when 'course_competency' then 'Hr:Talent:Course:Competency'
    else null end;
  if v_permission is null then raise exception '不支持删除该记录'; end if;
  if not app_private.can_execute_business_action('HrTalentDevelopment', v_permission, null, false) then
    raise exception '当前账号没有删除该记录的权限' using errcode = '42501';
  end if;
  if p_kind = 'plan' then
    delete from public.hr_training_plan where id = p_id and status = 'draft'
      and (app_private.is_platform_super() or tenant_id = v_tenant_id);
  elsif p_kind = 'course' then
    delete from public.hr_learning_course where id = p_id and status = 'draft'
      and (app_private.is_platform_super() or tenant_id = v_tenant_id);
  elsif p_kind = 'session' then
    delete from public.hr_learning_session where id = p_id and status = 'planned'
      and (app_private.is_platform_super() or tenant_id = v_tenant_id);
  elsif p_kind = 'enrollment' then
    delete from public.hr_training_enrollment where id = p_id and status = 'enrolled'
      and (app_private.is_platform_super() or tenant_id = v_tenant_id);
  else
    delete from public.hr_learning_course_competency where id = p_id
      and (app_private.is_platform_super() or tenant_id = v_tenant_id)
      and exists (
        select 1 from public.hr_learning_course c
        where c.id = hr_learning_course_competency.course_id and c.status = 'draft'
      );
  end if;
  if not found then raise exception '记录不存在或当前状态不允许删除'; end if;
  return true;
end
$$;


ALTER FUNCTION "public"."hr_delete_learning_record_secure"("p_kind" "text", "p_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_delete_lifecycle_record_secure("text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_delete_lifecycle_record_secure"("p_kind" "text", "p_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_deleted integer;
begin
  if p_kind not in ('case', 'task', 'template', 'template_task') then raise exception '不支持的生命周期记录类型'; end if;
  if p_kind in ('template', 'template_task') then
    if not app_private.can_execute_business_action('HrLifecycle', 'Hr:Lifecycle:ManageTemplate', null, false) then
      raise exception '当前账号没有删除标准任务包的权限' using errcode = '42501';
    end if;
  elsif not app_private.can_execute_business_action('HrLifecycle', 'Hr:Lifecycle:Delete', null, false) then
    raise exception '当前账号没有删除生命周期记录的权限' using errcode = '42501';
  end if;
  if p_kind = 'case' then
    delete from public.hr_lifecycle_case c where c.id = p_id
      and (app_private.is_platform_super() or c.tenant_id = v_tenant_id)
      and c.status in ('draft', 'rejected') and c.execution_status = 'planning';
  elsif p_kind = 'task' then
    delete from public.hr_lifecycle_task t where t.id = p_id
      and (app_private.is_platform_super() or t.tenant_id = v_tenant_id) and t.status = 'pending';
  elsif p_kind = 'template' then
    delete from public.hr_lifecycle_template t where t.id = p_id
      and (app_private.is_platform_super() or t.tenant_id = v_tenant_id)
      and t.status in ('draft', 'inactive')
      and not exists (select 1 from public.hr_lifecycle_case c where c.template_id = t.id);
  else
    delete from public.hr_lifecycle_template_task task where task.id = p_id
      and (app_private.is_platform_super() or task.tenant_id = v_tenant_id)
      and exists (select 1 from public.hr_lifecycle_template template
        where template.id = task.template_id and template.status in ('draft', 'inactive'));
  end if;
  get diagnostics v_deleted = row_count;
  if v_deleted = 0 then raise exception '记录不存在、状态不允许删除或仍被业务引用'; end if;
end
$$;


ALTER FUNCTION "public"."hr_delete_lifecycle_record_secure"("p_kind" "text", "p_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_delete_organization_design_record_secure("text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_delete_organization_design_record_secure"("p_kind" "text", "p_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_tenant_id uuid:=app_private.current_user_tenant_id();
begin
  if p_kind not in ('scenario','change') then raise exception '不支持的组织变革删除类型'; end if;
  if auth.uid() is null or not app_private.can_execute_business_action(
    'HrOrganizationDesign','Hr:OrganizationDesign:Scenario:Manage',null,false
  ) then raise exception '当前账号没有删除组织变革草稿的权限' using errcode='42501'; end if;
  if p_kind='scenario' then
    delete from public.hr_organization_design_scenario s where s.id=p_id
      and (app_private.is_platform_super() or s.tenant_id=v_tenant_id) and s.status in ('draft','rejected');
  else
    delete from public.hr_organization_design_change c using public.hr_organization_design_scenario s
    where c.id=p_id and s.id=c.scenario_id and (app_private.is_platform_super() or c.tenant_id=v_tenant_id)
      and s.status in ('draft','rejected');
  end if;
  if not found then raise exception '记录不存在、已进入流程或不允许删除'; end if;
  return true;
end;
$$;


ALTER FUNCTION "public"."hr_delete_organization_design_record_secure"("p_kind" "text", "p_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_delete_performance_record_secure("text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_delete_performance_record_secure"("p_kind" "text", "p_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
begin
  if p_kind not in ('cycle','review','goal','check_in','calibration') then raise exception '不支持删除该绩效记录'; end if;
  if not app_private.can_execute_business_action('HrPerformance','Hr:Performance:Delete',null,false) then
    raise exception '当前账号没有删除绩效记录的权限' using errcode='42501';
  end if;
  if p_kind='cycle' then
    delete from public.hr_performance_cycle where id=p_id
      and (app_private.is_platform_super() or tenant_id=v_tenant_id) and status='draft';
  elsif p_kind='review' then
    delete from public.hr_performance_review where id=p_id
      and (app_private.is_platform_super() or tenant_id=v_tenant_id) and status='draft';
  elsif p_kind='goal' then
    delete from public.hr_performance_goal g using public.hr_performance_review r
      where g.id=p_id and g.review_id=r.id and g.tenant_id=r.tenant_id
        and (app_private.is_platform_super() or g.tenant_id=v_tenant_id) and r.status='draft';
  elsif p_kind='check_in' then
    delete from public.hr_performance_check_in ci using public.hr_performance_review r
      where ci.id=p_id and ci.review_id=r.id and ci.tenant_id=r.tenant_id
        and (app_private.is_platform_super() or ci.tenant_id=v_tenant_id)
        and r.status in ('self_review','manager_review');
  else
    delete from public.hr_performance_calibration_session where id=p_id
      and (app_private.is_platform_super() or tenant_id=v_tenant_id) and status='setup';
  end if;
  if not found then raise exception '记录不存在或当前阶段不允许删除'; end if;
  return true;
end
$$;


ALTER FUNCTION "public"."hr_delete_performance_record_secure"("p_kind" "text", "p_id" "uuid") OWNER TO "postgres";

