--

--
-- Name: hr_delete_position_secure("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_delete_position_secure"("p_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_position public.mdm_position%rowtype;
begin
  if not app_private.can_execute_business_action(
    'HrPosition', 'Hr:Position:Delete', null, false
  ) then
    raise exception 'Missing position delete permission' using errcode = '42501';
  end if;
  select * into v_position from public.mdm_position where id = p_id;
  if not found or (
    not app_private.is_platform_super()
    and v_position.tenant_id <> app_private.current_user_tenant_id()
  ) then
    raise exception '岗位不存在或无权删除';
  end if;
  if exists (select 1 from public.mdm_employee where position_id = p_id) then
    raise exception '该岗位已有员工使用，请先调整员工岗位';
  end if;
  delete from public.mdm_position where id = p_id;
  return true;
end;
$$;


ALTER FUNCTION "public"."hr_delete_position_secure"("p_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_delete_recruitment_record_secure("text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_delete_recruitment_record_secure"("p_kind" "text", "p_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
begin
  if p_kind not in ('requisition', 'candidate') then
    raise exception '仅招聘需求和未进入流程的候选人允许删除';
  end if;
  if not app_private.can_execute_business_action('HrRecruitment', 'Hr:Recruitment:Delete', null, false) then
    raise exception '当前账号没有删除招聘记录的权限' using errcode = '42501';
  end if;

  if p_kind = 'requisition' then
    delete from public.hr_recruitment_requisition requisition
    where requisition.id = p_id
      and requisition.status in ('draft', 'rejected')
      and (app_private.is_platform_super() or requisition.tenant_id = v_tenant_id)
      and not exists (
        select 1 from public.hr_candidate candidate where candidate.requisition_id = requisition.id
      );
    if not found then
      raise exception '仅没有候选人的草稿或已驳回招聘需求可以删除';
    end if;
    return;
  end if;

  if not exists (
    select 1 from public.hr_candidate candidate
    where candidate.id = p_id and candidate.stage = 'new'
      and (app_private.is_platform_super() or candidate.tenant_id = v_tenant_id)
      and not exists (
        select 1 from public.hr_recruitment_interview interview where interview.candidate_id = candidate.id
      )
      and not exists (
        select 1 from public.hr_recruitment_offer offer where offer.candidate_id = candidate.id
      )
      and not exists (
        select 1 from public.hr_recruitment_handoff handoff where handoff.candidate_id = candidate.id
      )
  ) then
    raise exception '仅未进入筛选且没有后续业务记录的候选人可以删除';
  end if;
  perform pg_catalog.set_config('app.hr_recruitment_erasure', 'on', true);
  delete from public.hr_candidate_stage_history where candidate_id = p_id;
  delete from public.hr_candidate where id = p_id;
end
$$;


ALTER FUNCTION "public"."hr_delete_recruitment_record_secure"("p_kind" "text", "p_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_delete_service_request_secure("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_delete_service_request_secure"("p_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_record public.hr_self_service_request;
  v_manage boolean := app_private.is_platform_super()
    or app_private.has_permission('Hr:SelfService:Manage');
begin
  if not app_private.can_execute_business_action(
    'HrSelfService', 'Hr:SelfService:Delete', null, false
  ) then
    raise exception '当前账号没有删除员工服务工单的权限' using errcode = '42501';
  end if;
  select * into v_record from public.hr_self_service_request where id = p_id for update;
  if not found or not app_private.hr_service_case_visible(
    v_record.tenant_id, v_record.employee_id
  ) then
    raise exception '员工服务工单不存在或无权删除' using errcode = '42501';
  end if;
  if v_record.status <> 'draft' then raise exception '仅草稿工单可以删除'; end if;
  if not (v_manage or v_record.employee_id = app_private.hr_current_employee_id()) then
    raise exception '只能删除本人草稿工单' using errcode = '42501';
  end if;
  delete from public.hr_self_service_request where id = p_id;
end
$$;


ALTER FUNCTION "public"."hr_delete_service_request_secure"("p_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_delete_succession_record_secure("text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_delete_succession_record_secure"("p_kind" "text", "p_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_permission text;
begin
  v_permission := case p_kind
    when 'plan' then 'Hr:Succession:Plan:Delete'
    when 'candidate' then 'Hr:Succession:Candidate:Delete'
    when 'action' then 'Hr:Succession:Action:Delete'
    else null
  end;
  if v_permission is null then raise exception '不支持的继任记录类型'; end if;
  if not app_private.can_execute_business_action('HrSuccession', v_permission, null, false) then
    raise exception 'Missing succession delete permission' using errcode = '42501';
  end if;

  if p_kind = 'plan' then
    if exists (
      select 1 from public.hr_succession_candidate candidate_row
      where candidate_row.plan_id = p_id
        and (app_private.is_platform_super() or candidate_row.tenant_id = v_tenant_id)
    ) then
      raise exception '该计划已有候选人记录，请先逐项处理候选人，继任历史不会级联删除';
    end if;
    delete from public.hr_succession_plan
    where id = p_id and status = 'draft'
      and (app_private.is_platform_super() or tenant_id = v_tenant_id);
  elsif p_kind = 'candidate' then
    if exists (
      select 1 from public.hr_succession_development_action action_row
      where action_row.candidate_id = p_id
        and (app_private.is_platform_super() or action_row.tenant_id = v_tenant_id)
    ) then
      raise exception '该候选人已有发展行动，请先逐项处理行动，人才发展历史不会级联删除';
    end if;
    delete from public.hr_succession_candidate
    where id = p_id and status = 'nominated'
      and (app_private.is_platform_super() or tenant_id = v_tenant_id);
  else
    delete from public.hr_succession_development_action
    where id = p_id and status = 'planned'
      and (app_private.is_platform_super() or tenant_id = v_tenant_id);
  end if;
  if not found then
    raise exception '仅草稿计划、待评审候选人或计划中行动可删除';
  end if;
end;
$$;


ALTER FUNCTION "public"."hr_delete_succession_record_secure"("p_kind" "text", "p_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_delete_workforce_record_secure("text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_delete_workforce_record_secure"("p_kind" "text", "p_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid;
  v_status text;
begin
  if p_kind not in ('cycle','line','effective') then raise exception '不支持的人力规划记录类型'; end if;
  if not app_private.can_execute_business_action('HrHeadcount', 'Hr:Headcount:Delete', null, false) then
    raise exception '当前账号没有删除人力规划记录的权限' using errcode = '42501';
  end if;
  if p_kind = 'cycle' then
    select tenant_id,status into v_tenant_id,v_status from public.hr_workforce_plan_cycle where id=p_id;
    if not found then raise exception '人力规划周期不存在'; end if;
    if v_status <> 'draft' then raise exception '仅草稿规划可以删除'; end if;
    if not app_private.is_platform_super() and v_tenant_id <> app_private.current_user_tenant_id() then raise exception '无权删除其他租户数据'; end if;
    delete from public.hr_workforce_plan_cycle where id=p_id;
    return true;
  end if;
  if p_kind = 'line' then
    select l.tenant_id,c.status into v_tenant_id,v_status
    from public.hr_workforce_plan_line l join public.hr_workforce_plan_cycle c on c.id=l.plan_id
    where l.id=p_id;
    if not found then raise exception '岗位需求不存在'; end if;
    if v_status <> 'draft' then raise exception '仅草稿规划的岗位需求可以删除'; end if;
    if not app_private.is_platform_super() and v_tenant_id <> app_private.current_user_tenant_id() then raise exception '无权删除其他租户数据'; end if;
    delete from public.hr_workforce_plan_line where id=p_id;
    return true;
  end if;
  select tenant_id into v_tenant_id from public.hr_position_headcount where id=p_id
    and source_plan_line_id is null and effective_from > current_date;
  if not found then raise exception '仅可删除尚未生效且非规划启用产生的编制记录'; end if;
  if not app_private.is_platform_super() and v_tenant_id <> app_private.current_user_tenant_id() then raise exception '无权删除其他租户数据'; end if;
  delete from public.hr_position_headcount where id=p_id;
  return true;
end
$$;


ALTER FUNCTION "public"."hr_delete_workforce_record_secure"("p_kind" "text", "p_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_effect_personnel_change("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_effect_personnel_change"("p_change_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_change public.hr_personnel_change%rowtype;
  v_employee public.mdm_employee%rowtype;
  v_current public.mdm_employee_assignment%rowtype;
  v_assignment_status text;
  v_actor text;
begin
  if not app_private.is_platform_super() and not app_private.has_permission('Hr:PersonnelChange:Effect') then raise exception '当前账号没有生效人事异动的权限' using errcode='42501'; end if;
  select * into v_change from public.hr_personnel_change where id=p_change_id and (app_private.is_platform_super() or tenant_id=app_private.current_user_tenant_id()) for update;
  if not found then raise exception '人事异动单不存在'; end if;
  if v_change.status<>'approved' then raise exception '只有已批准异动单可以生效'; end if;
  if v_change.effective_date>current_date then raise exception '尚未到异动生效日期'; end if;
  select * into v_employee from public.mdm_employee where id=v_change.employee_id and tenant_id=v_change.tenant_id for update;
  if not found then raise exception '异动员工不存在'; end if;
  select * into v_current from public.mdm_employee_assignment where tenant_id=v_change.tenant_id and employee_id=v_change.employee_id and primary_assignment and effective_end is null for update;
  if not found then raise exception '员工没有当前有效的主任职记录'; end if;
  if v_current.id is distinct from v_change.base_assignment_id or v_current.update_time is distinct from v_change.base_assignment_updated_at then raise exception '员工当前任职已发生变化，请撤回后重新创建异动单'; end if;
  if v_change.effective_date<v_current.effective_start then raise exception '生效日期不能早于当前任职开始日期'; end if;

  if v_change.effective_date=v_current.effective_start then
    delete from public.mdm_employee_assignment where id=v_current.id;
  else
    update public.mdm_employee_assignment set effective_end=v_change.effective_date-1,assignment_status='ended',version=version+1 where id=v_current.id;
  end if;
  v_assignment_status:=case when v_change.to_employment_status='leave' then 'suspended' else 'active' end;
  if v_change.to_employment_status<>'terminated' then
    insert into public.mdm_employee_assignment(
      tenant_id,employee_id,organization_id,position_id,job_profile_id,grade_id,business_title,
      assignment_status,primary_assignment,fte,effective_start,source_type,source_change_id
    ) values(
      v_change.tenant_id,v_change.employee_id,v_change.to_organization_id,v_change.to_position_id,
      v_change.to_job_profile_id,v_change.to_grade_id,v_change.to_business_title,
      v_assignment_status,true,v_current.fte,v_change.effective_date,'personnel_change',v_change.id
    );
  end if;

  perform pg_catalog.set_config('app.hr_assignment_engine','on',true);
  update public.mdm_employee set
    organization_id=coalesce(v_change.to_organization_id,organization_id),
    position_id=coalesce(v_change.to_position_id,position_id),
    employment_status=coalesce(v_change.to_employment_status,employment_status),
    job_title=coalesce(v_change.to_business_title,v_change.after_assignment_snapshot->>'jobName',job_title),
    leave_date=case when v_change.to_employment_status='terminated' then v_change.effective_date else leave_date end
  where id=v_change.employee_id and tenant_id=v_change.tenant_id;

  v_actor:=coalesce((select user_email from public.sys_user where id=app_private.current_app_user_id()),auth.uid()::text,'system');
  perform pg_catalog.set_config('app.workflow_engine','on',true);
  update public.hr_personnel_change set status='effective',effected_at=now(),effected_by=v_actor where id=v_change.id;
  return true;
end;
$$;


ALTER FUNCTION "public"."hr_effect_personnel_change"("p_change_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_effect_recruitment_requisition("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_effect_recruitment_requisition"("p_requisition_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_requisition public.hr_recruitment_requisition;
begin
  if not (select app_private.is_platform_super())
     and not (select app_private.has_permission('Hr:Recruitment:Effect')) then
    raise exception '当前账号没有启动招聘的权限' using errcode='42501';
  end if;
  select * into v_requisition from public.hr_recruitment_requisition
  where id=p_requisition_id
    and ((select app_private.is_platform_super()) or tenant_id=(select app_private.current_user_tenant_id()))
  for update;
  if not found then raise exception '招聘需求不存在'; end if;
  if v_requisition.status<>'approved' then raise exception '只有已批准的招聘需求可以启动'; end if;
  perform pg_catalog.set_config('app.workflow_engine','on',true);
  update public.hr_recruitment_requisition
  set status='effective',update_by=coalesce((select app_private.current_user_email()),'system')
  where id=v_requisition.id;
  return true;
end $$;


ALTER FUNCTION "public"."hr_effect_recruitment_requisition"("p_requisition_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_employee_experience_overview_secure("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_employee_experience_overview_secure"("p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_employee_id uuid := app_private.hr_current_employee_id();
  v_insights boolean := app_private.hr_experience_insights_visible();
  v_comments boolean := app_private.hr_experience_comments_visible();
  v_respond boolean := app_private.is_platform_super()
    or app_private.has_permission('Hr:Experience:Respond');
begin
  if auth.uid() is null or not app_private.can_execute_business_action(
    'HrEmployeeExperience', 'Hr:Experience:View', null, false
  ) then raise exception '当前账号没有查看员工体验工作台的权限' using errcode = '42501'; end if;
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;

  return jsonb_build_object(
    'open_survey_count', case when v_insights then (
      select count(*) from public.hr_experience_survey survey
      where (p_tenant_id is null or survey.tenant_id = p_tenant_id)
        and survey.status = 'open'
    ) when v_respond and v_employee_id is not null then (
      select count(*) from public.hr_experience_participant participant
      join public.hr_experience_survey survey on survey.id = participant.survey_id
        and survey.tenant_id = participant.tenant_id
      where participant.tenant_id = v_tenant_id
        and participant.employee_id = v_employee_id
        and participant.status = 'invited' and survey.status = 'open'
        and current_date between survey.start_date and survey.end_date
    ) else 0 end,
    'my_pending_count', case when v_respond and v_employee_id is not null then (
      select count(*) from public.hr_experience_participant participant
      join public.hr_experience_survey survey on survey.id = participant.survey_id
        and survey.tenant_id = participant.tenant_id
      where participant.tenant_id = v_tenant_id
        and participant.employee_id = v_employee_id
        and participant.status = 'invited' and survey.status = 'open'
        and current_date between survey.start_date and survey.end_date
    ) else 0 end,
    'participant_count', case when v_insights then (
      select count(*) from public.hr_experience_participant participant
      where p_tenant_id is null or participant.tenant_id = p_tenant_id
    ) else 0 end,
    'completed_count', case when v_insights then (
      select count(*) from public.hr_experience_participant participant
      where (p_tenant_id is null or participant.tenant_id = p_tenant_id)
        and participant.status = 'completed'
    ) else 0 end,
    'response_rate', case when v_insights then (
      select case when count(*) = 0 then 0
        else round(100.0 * count(*) filter (where participant.status = 'completed') / count(*), 1)
      end
      from public.hr_experience_participant participant
      where p_tenant_id is null or participant.tenant_id = p_tenant_id
    ) else null end,
    'low_dimension_count', case when v_insights then (
      with dimension_scores as (
        select response.survey_id, question.dimension,
          count(distinct response.id) respondent_count,
          avg(case when question.answer_type = 'rating_5'
            then (answer.numeric_score - 1) * 25
            else answer.numeric_score * 10 end) score_percent,
          max(survey.minimum_group_size) minimum_group_size
        from public.hr_experience_answer answer
        join public.hr_experience_response response on response.id = answer.response_id
          and response.tenant_id = answer.tenant_id
        join public.hr_experience_question question on question.id = answer.question_id
          and question.tenant_id = answer.tenant_id
        join public.hr_experience_survey survey on survey.id = response.survey_id
          and survey.tenant_id = response.tenant_id
        where (p_tenant_id is null or response.tenant_id = p_tenant_id)
          and answer.numeric_score is not null
        group by response.survey_id, question.dimension
      )
      select count(*) from dimension_scores
      where respondent_count >= minimum_group_size and score_percent < 60
    ) else 0 end,
    'open_action_count', case when v_insights then (
      select count(*) from public.hr_experience_action action
      where (p_tenant_id is null or action.tenant_id = p_tenant_id)
        and action.status in ('planned', 'in_progress')
    ) else 0 end,
    'overdue_action_count', case when v_insights then (
      select count(*) from public.hr_experience_action action
      where (p_tenant_id is null or action.tenant_id = p_tenant_id)
        and action.status in ('planned', 'in_progress') and action.due_date < current_date
    ) else 0 end,
    'insights_visible', v_insights,
    'comments_visible', v_comments,
    'respond_visible', v_respond
  );
end
$$;


ALTER FUNCTION "public"."hr_employee_experience_overview_secure"("p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_employee_relations_overview_secure("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_employee_relations_overview_secure"("p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_sensitive boolean := app_private.is_platform_super()
    or app_private.has_permission('Hr:EmployeeRelations:Sensitive:View');
begin
  if not app_private.can_execute_business_action(
    'HrEmployeeRelations', 'Hr:EmployeeRelations:View', null, false
  ) then
    raise exception '当前账号没有查看员工关系案件的权限' using errcode = '42501';
  end if;
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;

  return jsonb_build_object(
    'open_case_count', (
      select count(*) from public.hr_employee_relation_case relation_case
      where (p_tenant_id is null or relation_case.tenant_id = p_tenant_id)
        and app_private.hr_employee_relation_case_visible(
          relation_case.tenant_id, relation_case.subject_employee_id,
          relation_case.reporter_employee_id, relation_case.owner_employee_id
        )
        and relation_case.status in ('reported', 'triaged', 'investigating', 'action_required')
    ),
    'critical_case_count', (
      select count(*) from public.hr_employee_relation_case relation_case
      where (p_tenant_id is null or relation_case.tenant_id = p_tenant_id)
        and app_private.hr_employee_relation_case_visible(
          relation_case.tenant_id, relation_case.subject_employee_id,
          relation_case.reporter_employee_id, relation_case.owner_employee_id
        )
        and relation_case.status in ('reported', 'triaged', 'investigating', 'action_required')
        and relation_case.severity = 'critical'
    ),
    'unassigned_case_count', (
      select count(*) from public.hr_employee_relation_case relation_case
      where (p_tenant_id is null or relation_case.tenant_id = p_tenant_id)
        and app_private.hr_employee_relation_case_visible(
          relation_case.tenant_id, relation_case.subject_employee_id,
          relation_case.reporter_employee_id, relation_case.owner_employee_id
        )
        and relation_case.status = 'reported' and relation_case.owner_employee_id is null
    ),
    'overdue_case_count', (
      select count(*) from public.hr_employee_relation_case relation_case
      where (p_tenant_id is null or relation_case.tenant_id = p_tenant_id)
        and app_private.hr_employee_relation_case_visible(
          relation_case.tenant_id, relation_case.subject_employee_id,
          relation_case.reporter_employee_id, relation_case.owner_employee_id
        )
        and relation_case.status in ('triaged', 'investigating', 'action_required')
        and relation_case.target_resolution_date < current_date
    ),
    'overdue_action_count', (
      select count(*)
      from public.hr_employee_relation_action action
      join public.hr_employee_relation_case relation_case
        on relation_case.id = action.case_id and relation_case.tenant_id = action.tenant_id
      where (p_tenant_id is null or action.tenant_id = p_tenant_id)
        and app_private.hr_employee_relation_case_visible(
          relation_case.tenant_id, relation_case.subject_employee_id,
          relation_case.reporter_employee_id, relation_case.owner_employee_id
        )
        and action.status in ('planned', 'in_progress') and action.due_date < current_date
    ),
    'resolved_month_count', (
      select count(*) from public.hr_employee_relation_case relation_case
      where (p_tenant_id is null or relation_case.tenant_id = p_tenant_id)
        and app_private.hr_employee_relation_case_visible(
          relation_case.tenant_id, relation_case.subject_employee_id,
          relation_case.reporter_employee_id, relation_case.owner_employee_id
        )
        and relation_case.resolved_at >= date_trunc('month', now())
    ),
    'sensitive_access', v_sensitive
  );
end
$$;


ALTER FUNCTION "public"."hr_employee_relations_overview_secure"("p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_get_benefit_detail_secure("text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_get_benefit_detail_secure"("p_kind" "text", "p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_result jsonb;
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_amount_visible boolean := app_private.hr_benefit_amount_visible();
  v_evidence_visible boolean := app_private.hr_benefit_evidence_visible();
begin
  if auth.uid() is null or not app_private.can_execute_business_action(
    'HrBenefits', 'Hr:Benefits:View', p_id, false
  ) then
    raise exception '当前账号没有查看福利详情的权限' using errcode = '42501';
  end if;
  if p_kind not in ('plan', 'enrollment', 'event') then raise exception '不支持的福利记录类型'; end if;

  if p_kind = 'plan' then
    select to_jsonb(plan) || jsonb_build_object(
      'options', coalesce((select jsonb_agg(
        to_jsonb(option) - 'employee_contribution' - 'employer_contribution'
          - 'employee_rate' - 'employer_rate'
        || case when v_amount_visible then jsonb_build_object(
          'employee_contribution', option.employee_contribution,
          'employer_contribution', option.employer_contribution,
          'employee_rate', option.employee_rate,
          'employer_rate', option.employer_rate
        ) else '{}'::jsonb end
        order by option.sort, option.option_name)
        from public.hr_benefit_option option
        where option.plan_id = plan.id and option.tenant_id = plan.tenant_id), '[]'::jsonb),
      'events', coalesce((select jsonb_agg(to_jsonb(event) order by event.create_time desc)
        from public.hr_benefit_event event
        where event.entity_type = 'plan' and event.entity_id = plan.id
          and event.tenant_id = plan.tenant_id), '[]'::jsonb),
      'amount_visible', v_amount_visible
    ) into v_result
    from public.hr_benefit_plan plan
    where plan.id = p_id
      and (app_private.is_platform_super() or (app_private.current_read_tenant_id() is null or plan.tenant_id = app_private.current_read_tenant_id()));
  elsif p_kind = 'enrollment' then
    select (to_jsonb(enrollment) - 'employee_contribution' - 'employer_contribution')
      || case when v_amount_visible then jsonb_build_object(
        'employee_contribution', enrollment.employee_contribution,
        'employer_contribution', enrollment.employer_contribution
      ) else '{}'::jsonb end
      || jsonb_build_object(
        'employee', jsonb_build_object(
          'id', employee.id, 'employee_no', employee.employee_no,
          'employee_name', employee.employee_name, 'job_title', employee.job_title
        ),
        'plan', jsonb_build_object('id', plan.id, 'plan_code', plan.plan_code,
          'plan_name', plan.plan_name, 'plan_type', plan.plan_type),
        'option', jsonb_build_object('id', option.id, 'option_code', option.option_code,
          'option_name', option.option_name, 'coverage_level', option.coverage_level),
        'life_event', case when life_event.id is null then null else jsonb_build_object(
          'id', life_event.id, 'event_type', life_event.event_type,
          'event_date', life_event.event_date
        ) end,
        'events', coalesce((select jsonb_agg(to_jsonb(event) order by event.create_time desc)
          from public.hr_benefit_event event
          where event.entity_type = 'enrollment' and event.entity_id = enrollment.id
            and event.tenant_id = enrollment.tenant_id), '[]'::jsonb),
        'amount_visible', v_amount_visible
      ) into v_result
    from public.hr_employee_benefit_enrollment enrollment
    join public.mdm_employee employee on employee.id = enrollment.employee_id
      and employee.tenant_id = enrollment.tenant_id
    join public.hr_benefit_plan plan on plan.id = enrollment.plan_id
      and plan.tenant_id = enrollment.tenant_id
    join public.hr_benefit_option option on option.id = enrollment.option_id
      and option.tenant_id = enrollment.tenant_id
    left join public.hr_benefit_life_event life_event on life_event.id = enrollment.life_event_id
      and life_event.tenant_id = enrollment.tenant_id
    where enrollment.id = p_id
      and (app_private.is_platform_super() or (app_private.current_read_tenant_id() is null or enrollment.tenant_id = app_private.current_read_tenant_id()));
  else
    select (to_jsonb(life_event) - 'evidence_urls')
      || jsonb_build_object(
      'evidence_urls', case when v_evidence_visible then life_event.evidence_urls else '[]'::jsonb end,
      'evidence_restricted', not v_evidence_visible,
      'employee', jsonb_build_object('id', employee.id, 'employee_no', employee.employee_no,
        'employee_name', employee.employee_name, 'job_title', employee.job_title),
      'enrollments', coalesce((select jsonb_agg(jsonb_build_object(
        'id', enrollment.id, 'enrollment_no', enrollment.enrollment_no,
        'status', enrollment.status, 'plan_id', enrollment.plan_id,
        'plan_name', plan.plan_name, 'option_name', option.option_name
      ) order by enrollment.create_time desc)
        from public.hr_employee_benefit_enrollment enrollment
        join public.hr_benefit_plan plan on plan.id = enrollment.plan_id
          and plan.tenant_id = enrollment.tenant_id
        join public.hr_benefit_option option on option.id = enrollment.option_id
          and option.tenant_id = enrollment.tenant_id
        where enrollment.life_event_id = life_event.id
          and enrollment.tenant_id = life_event.tenant_id), '[]'::jsonb),
      'events', coalesce((select jsonb_agg(to_jsonb(event) order by event.create_time desc)
        from public.hr_benefit_event event
        where event.entity_type = 'life_event' and event.entity_id = life_event.id
          and event.tenant_id = life_event.tenant_id), '[]'::jsonb)
    ) into v_result
    from public.hr_benefit_life_event life_event
    join public.mdm_employee employee on employee.id = life_event.employee_id
      and employee.tenant_id = life_event.tenant_id
    where life_event.id = p_id
      and (app_private.is_platform_super() or (app_private.current_read_tenant_id() is null or life_event.tenant_id = app_private.current_read_tenant_id()));
  end if;

  if v_result is null then raise exception '福利记录不存在或无权查看' using errcode = '42501'; end if;
  return v_result;
end
$$;


ALTER FUNCTION "public"."hr_get_benefit_detail_secure"("p_kind" "text", "p_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_get_compliance_detail_secure("text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_get_compliance_detail_secure"("p_kind" "text", "p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_record jsonb;
  v_record_tenant uuid;
begin
  if p_kind not in ('contract', 'qualification') then
    raise exception '不支持的用工合规记录类型';
  end if;
  if not app_private.can_execute_business_action(
    'HrCompliance', 'Hr:Compliance:View', p_id, false
  ) then
    raise exception '当前账号没有查看用工合规详情的权限' using errcode = '42501';
  end if;

  if p_kind = 'contract' then
    select contract.tenant_id,
      to_jsonb(contract) || jsonb_build_object(
        'employee', jsonb_build_object(
          'id', employee.id, 'employee_no', employee.employee_no,
          'employee_name', employee.employee_name, 'job_title', employee.job_title,
          'organization_name', organization.organization_name,
          'position_name', position.position_name
        ),
        'renewal_owner', case when owner.id is null then null else jsonb_build_object(
          'id', owner.id, 'employee_no', owner.employee_no,
          'employee_name', owner.employee_name, 'job_title', owner.job_title
        ) end,
        'previous_contract_no', previous.contract_no
      ) into v_record_tenant, v_record
    from public.hr_employee_contract contract
    join public.mdm_employee employee
      on employee.id = contract.employee_id and employee.tenant_id = contract.tenant_id
    left join public.mdm_organization organization on organization.id = employee.organization_id
    left join public.mdm_position position on position.id = employee.position_id
    left join public.mdm_employee owner
      on owner.id = contract.renewal_owner_id and owner.tenant_id = contract.tenant_id
    left join public.hr_employee_contract previous
      on previous.id = contract.previous_contract_id and previous.tenant_id = contract.tenant_id
    where contract.id = p_id;
  else
    select qualification.tenant_id,
      to_jsonb(qualification) || jsonb_build_object(
        'employee', jsonb_build_object(
          'id', employee.id, 'employee_no', employee.employee_no,
          'employee_name', employee.employee_name, 'job_title', employee.job_title,
          'organization_name', organization.organization_name,
          'position_name', position.position_name
        ),
        'responsible_employee', case when responsible.id is null then null else jsonb_build_object(
          'id', responsible.id, 'employee_no', responsible.employee_no,
          'employee_name', responsible.employee_name, 'job_title', responsible.job_title
        ) end,
        'verified_by_employee', case when verifier.id is null then null else jsonb_build_object(
          'id', verifier.id, 'employee_no', verifier.employee_no,
          'employee_name', verifier.employee_name, 'job_title', verifier.job_title
        ) end
      ) into v_record_tenant, v_record
    from public.hr_employee_qualification qualification
    join public.mdm_employee employee
      on employee.id = qualification.employee_id and employee.tenant_id = qualification.tenant_id
    left join public.mdm_organization organization on organization.id = employee.organization_id
    left join public.mdm_position position on position.id = employee.position_id
    left join public.mdm_employee responsible
      on responsible.id = qualification.responsible_employee_id
      and responsible.tenant_id = qualification.tenant_id
    left join public.mdm_employee verifier
      on verifier.id = qualification.verified_by_employee_id
      and verifier.tenant_id = qualification.tenant_id
    where qualification.id = p_id;
  end if;

  if v_record is null
    or (not app_private.is_platform_super() and v_record_tenant <> v_tenant_id) then
    raise exception '用工合规记录不存在或无权查看' using errcode = '42501';
  end if;

  return v_record || jsonb_build_object(
    'events', coalesce((
      select jsonb_agg(to_jsonb(event) || jsonb_build_object(
        'actor', case when actor.id is null then null else jsonb_build_object(
          'id', actor.id, 'employee_no', actor.employee_no,
          'employee_name', actor.employee_name, 'job_title', actor.job_title
        ) end
      ) order by event.create_time desc)
      from public.hr_compliance_event event
      left join public.mdm_employee actor
        on actor.id = event.actor_employee_id and actor.tenant_id = event.tenant_id
      where event.tenant_id = v_record_tenant
        and event.entity_type = p_kind and event.entity_id = p_id
    ), '[]'::jsonb)
  );
end
$$;


ALTER FUNCTION "public"."hr_get_compliance_detail_secure"("p_kind" "text", "p_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_get_employee_experience_detail_secure("text", "uuid", "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_get_employee_experience_detail_secure"("p_kind" "text", "p_id" "uuid", "p_dimension" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_employee_id uuid := app_private.hr_current_employee_id();
  v_insights boolean := app_private.hr_experience_insights_visible();
  v_comments boolean := app_private.hr_experience_comments_visible();
  v_result jsonb;
begin
  if auth.uid() is null or not app_private.can_execute_business_action(
    'HrEmployeeExperience', 'Hr:Experience:View', p_id, false
  ) then raise exception '当前账号没有查看员工体验详情的权限' using errcode = '42501'; end if;

  if p_kind = 'my' then
    if v_employee_id is null or not (
      app_private.is_platform_super() or app_private.has_permission('Hr:Experience:Respond')
    ) then raise exception '当前账号没有填写员工体验调查的权限' using errcode = '42501'; end if;
    select to_jsonb(participant) || jsonb_build_object(
      'survey', to_jsonb(survey),
      'questions', coalesce((select jsonb_agg(to_jsonb(question) order by question.sort, question.id)
        from public.hr_experience_question question
        where question.survey_id = survey.id and question.tenant_id = survey.tenant_id
          and question.enabled), '[]'::jsonb),
      'privacy_note', '系统仅记录您是否完成，答案不保存员工或参与记录标识。'
    ) into v_result
    from public.hr_experience_participant participant
    join public.hr_experience_survey survey on survey.id = participant.survey_id
      and survey.tenant_id = participant.tenant_id
    where participant.id = p_id and (app_private.current_read_tenant_id() is null or participant.tenant_id = app_private.current_read_tenant_id())
      and participant.employee_id = v_employee_id;
  elsif p_kind = 'survey' then
    if not v_insights then raise exception '当前账号没有查看调查详情的权限' using errcode = '42501'; end if;
    select to_jsonb(survey) || jsonb_build_object(
      'audience_organization', case when organization.id is null then null else
        jsonb_build_object('id', organization.id, 'organization_name', organization.organization_name) end,
      'questions', coalesce((select jsonb_agg(to_jsonb(question) order by question.sort, question.id)
        from public.hr_experience_question question
        where question.survey_id = survey.id and question.tenant_id = survey.tenant_id), '[]'::jsonb),
      'participant_count', (select count(*) from public.hr_experience_participant participant
        where participant.survey_id = survey.id and participant.tenant_id = survey.tenant_id),
      'completed_count', (select count(*) from public.hr_experience_participant participant
        where participant.survey_id = survey.id and participant.tenant_id = survey.tenant_id
          and participant.status = 'completed'),
      'events', coalesce((select jsonb_agg(to_jsonb(event) order by event.create_time desc)
        from public.hr_experience_event event where event.entity_type = 'survey'
          and event.entity_id = survey.id and event.tenant_id = survey.tenant_id), '[]'::jsonb)
    ) into v_result
    from public.hr_experience_survey survey
    left join public.mdm_organization organization on organization.id = survey.audience_organization_id
      and organization.tenant_id = survey.tenant_id
    where survey.id = p_id and (app_private.is_platform_super() or (app_private.current_read_tenant_id() is null or survey.tenant_id = app_private.current_read_tenant_id()));
  elsif p_kind = 'insight' then
    if not v_insights or nullif(p_dimension, '') is null then
      raise exception '当前账号没有查看匿名聚合洞察的权限' using errcode = '42501';
    end if;
    with survey_context as (
      select * from public.hr_experience_survey survey
      where survey.id = p_id and (app_private.is_platform_super() or (app_private.current_read_tenant_id() is null or survey.tenant_id = app_private.current_read_tenant_id()))
    ), response_count as (
      select count(distinct response.id)::integer value
      from public.hr_experience_response response
      join survey_context survey on survey.id = response.survey_id
        and survey.tenant_id = response.tenant_id
      join public.hr_experience_answer answer on answer.response_id = response.id
        and answer.tenant_id = response.tenant_id
      join public.hr_experience_question question on question.id = answer.question_id
        and question.tenant_id = answer.tenant_id
      where question.dimension = p_dimension
    )
    select to_jsonb(survey) || jsonb_build_object(
      'dimension', p_dimension,
      'respondent_count', response_count.value,
      'privacy_threshold_met', response_count.value >= survey.minimum_group_size,
      'question_scores', case when response_count.value >= survey.minimum_group_size then
        coalesce((select jsonb_agg(jsonb_build_object(
          'question_id', question.id, 'question_text', question.question_text,
          'answer_type', question.answer_type,
          'respondent_count', aggregate.respondent_count,
          'score_percent', aggregate.score_percent
        ) order by question.sort, question.id)
        from public.hr_experience_question question
        join lateral (
          select count(distinct response.id)::integer respondent_count,
            round(avg(case when question.answer_type = 'rating_5'
              then (answer.numeric_score - 1) * 25 else answer.numeric_score * 10 end), 1)
              score_percent
          from public.hr_experience_answer answer
          join public.hr_experience_response response on response.id = answer.response_id
            and response.tenant_id = answer.tenant_id
          where answer.question_id = question.id and answer.tenant_id = survey.tenant_id
            and answer.numeric_score is not null
        ) aggregate on true
        where question.survey_id = survey.id and question.tenant_id = survey.tenant_id
          and question.dimension = p_dimension and question.answer_type <> 'open_text'), '[]'::jsonb)
        else '[]'::jsonb end,
      'organization_scores', case when response_count.value >= survey.minimum_group_size then
        coalesce((select jsonb_agg(to_jsonb(cohort) order by cohort.score_percent, cohort.organization_name)
        from (
          select organization.id organization_id, organization.organization_name,
            count(distinct response.id)::integer respondent_count,
            round(avg(case when question.answer_type = 'rating_5'
              then (answer.numeric_score - 1) * 25 else answer.numeric_score * 10 end), 1)
              score_percent
          from public.hr_experience_response response
          join public.hr_experience_answer answer on answer.response_id = response.id
            and answer.tenant_id = response.tenant_id and answer.numeric_score is not null
          join public.hr_experience_question question on question.id = answer.question_id
            and question.tenant_id = answer.tenant_id and question.dimension = p_dimension
          join public.mdm_organization organization on organization.id = response.cohort_organization_id
            and organization.tenant_id = response.tenant_id
          where response.survey_id = survey.id and response.tenant_id = survey.tenant_id
          group by organization.id, organization.organization_name
          having count(distinct response.id) >= survey.minimum_group_size
        ) cohort), '[]'::jsonb) else '[]'::jsonb end,
      'comments_restricted', not v_comments,
      'comments', case when response_count.value >= survey.minimum_group_size and v_comments then
        coalesce((select jsonb_agg(jsonb_build_object(
          'question_text', question.question_text,
          'text', answer.text_answer,
          'submitted_at', response.submitted_at
        ) order by response.submitted_at desc)
        from public.hr_experience_answer answer
        join public.hr_experience_response response on response.id = answer.response_id
          and response.tenant_id = answer.tenant_id
        join public.hr_experience_question question on question.id = answer.question_id
          and question.tenant_id = answer.tenant_id
        where response.survey_id = survey.id and response.tenant_id = survey.tenant_id
          and question.dimension = p_dimension and answer.text_answer is not null), '[]'::jsonb)
        else '[]'::jsonb end,
      'actions', coalesce((select jsonb_agg(to_jsonb(action) order by action.due_date)
        from public.hr_experience_action action where action.survey_id = survey.id
          and action.tenant_id = survey.tenant_id and action.dimension = p_dimension
          and action.status <> 'cancelled'), '[]'::jsonb)
    ) into v_result
    from survey_context survey cross join response_count;
  elsif p_kind = 'action' then
    if not v_insights then raise exception '当前账号没有查看员工体验行动的权限' using errcode = '42501'; end if;
    select to_jsonb(action) || jsonb_build_object(
      'survey', jsonb_build_object('id', survey.id, 'survey_code', survey.survey_code,
        'survey_name', survey.survey_name, 'survey_type', survey.survey_type),
      'organization', case when organization.id is null then null else
        jsonb_build_object('id', organization.id, 'organization_name', organization.organization_name) end,
      'owner_employee', jsonb_build_object('id', employee.id, 'employee_no', employee.employee_no,
        'employee_name', employee.employee_name, 'job_title', employee.job_title),
      'events', coalesce((select jsonb_agg(to_jsonb(event) order by event.create_time desc)
        from public.hr_experience_event event where event.entity_type = 'action'
          and event.entity_id = action.id and event.tenant_id = action.tenant_id), '[]'::jsonb)
    ) into v_result
    from public.hr_experience_action action
    join public.hr_experience_survey survey on survey.id = action.survey_id
      and survey.tenant_id = action.tenant_id
    left join public.mdm_organization organization on organization.id = action.organization_id
      and organization.tenant_id = action.tenant_id
    join public.mdm_employee employee on employee.id = action.owner_employee_id
      and employee.tenant_id = action.tenant_id
    where action.id = p_id and (app_private.is_platform_super() or (app_private.current_read_tenant_id() is null or action.tenant_id = app_private.current_read_tenant_id()));
  else
    raise exception '不支持的员工体验详情类型';
  end if;

  if v_result is null then raise exception '员工体验记录不存在或无权查看' using errcode = '42501'; end if;
  return v_result;
end
$$;


ALTER FUNCTION "public"."hr_get_employee_experience_detail_secure"("p_kind" "text", "p_id" "uuid", "p_dimension" "text") OWNER TO "postgres";

--

--
-- Name: hr_get_employee_profile_secure("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_get_employee_profile_secure"("p_employee_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_owner_id uuid;
  v_employee jsonb;
begin
  perform app_private.assert_hr_employee_readable();

  select employee_row.created_by_user_id into v_owner_id
  from public.mdm_employee employee_row
  where employee_row.id = p_employee_id
    and (
      app_private.is_platform_super()
      or (app_private.current_read_tenant_id() is null or employee_row.tenant_id = app_private.current_read_tenant_id())
    );
  if not found then
    raise exception 'Employee profile not found' using errcode = 'P0002';
  end if;

  v_employee := app_private.hr_employee_to_secure_json(p_employee_id, v_owner_id);
  return v_employee || app_private.hr_employee_histories_to_secure_json(
    p_employee_id, v_owner_id
  );
end;
$$;


ALTER FUNCTION "public"."hr_get_employee_profile_secure"("p_employee_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_get_employee_relation_case_detail_secure("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_get_employee_relation_case_detail_secure"("p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_result jsonb;
  v_sensitive boolean := app_private.is_platform_super()
    or app_private.has_permission('Hr:EmployeeRelations:Sensitive:View');
begin
  v_result := app_private.hr_get_employee_relation_case_detail_internal(p_id);
  if not v_sensitive then
    v_result := v_result
      - 'remark'
      - 'external_reference'
      - 'reporter_employee';
  end if;
  return v_result;
end
$$;


ALTER FUNCTION "public"."hr_get_employee_relation_case_detail_secure"("p_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_get_organization_position_directory_secure("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_get_organization_position_directory_secure"("p_organization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_current_tenant_id uuid := app_private.current_user_tenant_id();
  v_target_tenant_id uuid;
  v_organization_ids uuid[];
  v_employee_total bigint;
  v_employee_limit integer := 2000;
begin
  if not app_private.can_execute_business_action(
    'HrOrganizationPosition',
    'Hr:OrganizationPosition:View',
    null,
    false
  ) then
    raise exception 'Missing organization position directory view permission'
      using errcode = '42501';
  end if;

  select organization_row.tenant_id
  into v_target_tenant_id
  from public.mdm_organization organization_row
  where organization_row.id = p_organization_id
    and organization_row.status = '1';

  if v_target_tenant_id is null
    or (
      not app_private.is_platform_super()
      and v_target_tenant_id <> v_current_tenant_id
    )
    or not app_private.tenant_in_current_read_scope(v_target_tenant_id)
  then
    raise exception '组织不存在、已停用或超出当前租户范围' using errcode = '42501';
  end if;

  with recursive organization_scope as (
    select organization_row.id
    from public.mdm_organization organization_row
    where organization_row.id = p_organization_id
      and organization_row.tenant_id = v_target_tenant_id
      and organization_row.status = '1'
    union
    select child.id
    from public.mdm_organization child
    join organization_scope parent on child.parent_id = parent.id
    where child.tenant_id = v_target_tenant_id
      and child.status = '1'
  )
  select coalesce(array_agg(id), '{}'::uuid[])
  into v_organization_ids
  from organization_scope;

  select count(*)
  into v_employee_total
  from public.mdm_employee employee_row
  where employee_row.tenant_id = v_target_tenant_id
    and employee_row.organization_id = any(v_organization_ids)
    and employee_row.employment_status <> 'terminated';

  return (
    with position_records as (
      select
        position_row.id,
        position_row.tenant_id,
        position_row.organization_id,
        position_row.position_code,
        position_row.position_name,
        position_row.position_kind,
        position_row.system_code,
        position_row.enabled,
        position_row.sort,
        position_row.description,
        (
          select count(*)
          from public.mdm_employee employee_row
          where employee_row.tenant_id = v_target_tenant_id
            and employee_row.organization_id = any(v_organization_ids)
            and employee_row.position_id = position_row.id
            and employee_row.employment_status <> 'terminated'
        )::integer as employee_count
      from public.mdm_position position_row
      where position_row.tenant_id = v_target_tenant_id
        and position_row.enabled
        and (
          position_row.organization_id = any(v_organization_ids)
          or exists (
            select 1
            from public.mdm_employee employee_row
            where employee_row.tenant_id = v_target_tenant_id
              and employee_row.organization_id = any(v_organization_ids)
              and employee_row.position_id = position_row.id
              and employee_row.employment_status <> 'terminated'
          )
          or exists (
            select 1
            from public.hr_position_headcount headcount_row
            where headcount_row.tenant_id = v_target_tenant_id
              and headcount_row.organization_id = any(v_organization_ids)
              and headcount_row.position_id = position_row.id
              and headcount_row.enabled
              and headcount_row.effective_from <= current_date
              and (
                headcount_row.effective_to is null
                or headcount_row.effective_to >= current_date
              )
          )
        )
    ), employee_records as (
      select
        employee_row.id,
        employee_row.organization_id,
        employee_row.position_id,
        employee_row.employee_no,
        employee_row.employee_name,
        employee_row.avatar_url,
        employee_row.job_title,
        employee_row.employment_status,
        employee_row.employment_type,
        employee_row.hire_date
      from public.mdm_employee employee_row
      where employee_row.tenant_id = v_target_tenant_id
        and employee_row.organization_id = any(v_organization_ids)
        and employee_row.employment_status <> 'terminated'
      order by employee_row.employee_name, employee_row.employee_no
      limit v_employee_limit
    )
    select jsonb_build_object(
      'positions', coalesce((
        select jsonb_agg(to_jsonb(position_records) order by sort, position_name, position_code)
        from position_records
      ), '[]'::jsonb),
      'employees', coalesce((
        select jsonb_agg(to_jsonb(employee_records) order by employee_name, employee_no)
        from employee_records
      ), '[]'::jsonb),
      'employee_total', v_employee_total,
      'truncated', v_employee_total > v_employee_limit
    )
  );
end;
$$;


ALTER FUNCTION "public"."hr_get_organization_position_directory_secure"("p_organization_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_get_service_request_detail_secure("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_get_service_request_detail_secure"("p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_request public.hr_self_service_request;
  v_result jsonb;
begin
  if not app_private.can_execute_business_action(
    'HrSelfService', 'Hr:SelfService:View', null, false
  ) then
    raise exception '当前账号没有查看员工服务中心的权限' using errcode = '42501';
  end if;

  select * into v_request from public.hr_self_service_request where id = p_id;
  if not found or not app_private.hr_service_case_visible(
    v_request.tenant_id, v_request.employee_id
  ) then
    raise exception '员工服务工单不存在或无权查看' using errcode = '42501';
  end if;

  select to_jsonb(request)
    || jsonb_build_object(
      'service', case when service.id is null then null else jsonb_build_object(
        'id', service.id, 'code', service.service_code, 'name', service.service_name,
        'category', service.category, 'routing_group', service.routing_group
      ) end,
      'requester', jsonb_build_object(
        'id', requester.id, 'code', requester.employee_no,
        'name', requester.employee_name, 'job_title', requester.job_title
      ),
      'assignee', case when assignee.id is null then null else jsonb_build_object(
        'id', assignee.id, 'code', assignee.employee_no, 'name', assignee.employee_name
      ) end,
      'events', coalesce((
        select jsonb_agg(
          to_jsonb(event) || jsonb_build_object(
            'actor', case when actor.id is null then null else jsonb_build_object(
              'id', actor.id, 'code', actor.employee_no, 'name', actor.employee_name
            ) end
          ) order by event.create_time desc
        )
        from public.hr_service_request_event event
        left join public.mdm_employee actor
          on actor.id = event.actor_employee_id and actor.tenant_id = event.tenant_id
        where event.request_id = request.id and event.tenant_id = request.tenant_id
      ), '[]'::jsonb)
    ) into v_result
  from public.hr_self_service_request request
  left join public.hr_service_catalog service
    on service.id = request.service_id and service.tenant_id = request.tenant_id
  join public.mdm_employee requester
    on requester.id = request.employee_id and requester.tenant_id = request.tenant_id
  left join public.mdm_employee assignee
    on assignee.id = request.assigned_employee_id and assignee.tenant_id = request.tenant_id
  where request.id = p_id;

  return v_result;
end
$$;


ALTER FUNCTION "public"."hr_get_service_request_detail_secure"("p_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_get_skill_matrix_secure(); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_get_skill_matrix_secure"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_is_platform_super boolean := app_private.is_platform_super();
  v_record_limit constant integer := 1000;
  v_total_records integer := 0;
  v_modelled_employees integer := 0;
  v_assessed_employees integer := 0;
  v_ready_employees integer := 0;
  v_gap_employees integer := 0;
  v_unassessed_employees integer := 0;
  v_records jsonb := '[]'::jsonb;
  v_competencies jsonb := '[]'::jsonb;
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;
  if not coalesce(app_private.has_permission('Hr:SkillMatrix:View'), false) then
    raise exception 'Missing skill matrix view permission' using errcode = '42501';
  end if;
  if not v_is_platform_super and v_tenant_id is null then
    raise exception 'Skill matrix tenant is required' using errcode = '22023';
  end if;

  select count(*)::integer
  into v_total_records
  from public.mdm_employee employee_row
  where (v_is_platform_super or (app_private.current_read_tenant_id() is null or employee_row.tenant_id = app_private.current_read_tenant_id()))
    and employee_row.employment_status <> 'terminated';

  with employee_scope as (
    select employee_row.id, employee_row.tenant_id, employee_row.employee_no,
      employee_row.employee_name, employee_row.job_title, employee_row.organization_id,
      employee_row.position_id, organization_row.organization_name, position_row.position_name
    from public.mdm_employee employee_row
    left join public.mdm_organization organization_row
      on organization_row.id = employee_row.organization_id
      and organization_row.tenant_id = employee_row.tenant_id
    left join public.mdm_position position_row
      on position_row.id = employee_row.position_id
      and position_row.tenant_id = employee_row.tenant_id
    where (v_is_platform_super or (app_private.current_read_tenant_id() is null or employee_row.tenant_id = app_private.current_read_tenant_id()))
      and employee_row.employment_status <> 'terminated'
    order by employee_row.tenant_id, employee_row.employee_name, employee_row.id
    limit v_record_limit
  ), employee_matrix as (
    select employee_row.*,
      coalesce(matrix.required_count, 0)::integer as required_count,
      coalesce(matrix.assessed_count, 0)::integer as assessed_count,
      coalesce(matrix.met_count, 0)::integer as met_count
    from employee_scope employee_row
    left join lateral (
      select count(*)::integer as required_count,
        count(employee_competency.id)::integer as assessed_count,
        count(*) filter (where
          case employee_competency.current_level
            when 'expert' then 4 when 'advanced' then 3 when 'intermediate' then 2
            when 'basic' then 1 else 0 end
          >= case position_competency.required_level
            when 'expert' then 4 when 'advanced' then 3 when 'intermediate' then 2
            when 'basic' then 1 else 0 end
        )::integer as met_count
      from public.hr_position_competency position_competency
      left join public.hr_employee_competency employee_competency
        on employee_competency.employee_id = employee_row.id
        and employee_competency.competency_id = position_competency.competency_id
        and employee_competency.tenant_id = employee_row.tenant_id
      where position_competency.position_id = employee_row.position_id
        and position_competency.tenant_id = employee_row.tenant_id
    ) matrix on true
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', employee_matrix.id,
      'employeeNo', employee_matrix.employee_no,
      'employeeName', employee_matrix.employee_name,
      'jobTitle', employee_matrix.job_title,
      'organizationName', employee_matrix.organization_name,
      'positionName', employee_matrix.position_name,
      'requiredCount', employee_matrix.required_count,
      'assessedCount', employee_matrix.assessed_count,
      'metCount', employee_matrix.met_count,
      'gapCount', greatest(employee_matrix.required_count - employee_matrix.met_count, 0),
      'unassessedCount', greatest(employee_matrix.required_count - employee_matrix.assessed_count, 0),
      'readinessRate', case when employee_matrix.required_count = 0 then null
        else round(employee_matrix.met_count * 100.0 / employee_matrix.required_count, 1) end
    ) order by greatest(employee_matrix.required_count - employee_matrix.met_count, 0) desc,
      employee_matrix.employee_name, employee_matrix.id), '[]'::jsonb),
    count(*) filter (where employee_matrix.required_count > 0)::integer,
    count(*) filter (where employee_matrix.assessed_count > 0)::integer,
    count(*) filter (where employee_matrix.required_count > 0
      and employee_matrix.met_count = employee_matrix.required_count)::integer,
    count(*) filter (where employee_matrix.required_count > employee_matrix.met_count)::integer,
    count(*) filter (where employee_matrix.required_count > 0
      and employee_matrix.assessed_count = 0)::integer
  into v_records, v_modelled_employees, v_assessed_employees, v_ready_employees,
    v_gap_employees, v_unassessed_employees
  from employee_matrix;

  with employee_scope as (
    select employee_row.id, employee_row.tenant_id, employee_row.position_id
    from public.mdm_employee employee_row
    where (v_is_platform_super or (app_private.current_read_tenant_id() is null or employee_row.tenant_id = app_private.current_read_tenant_id()))
      and employee_row.employment_status <> 'terminated'
    order by employee_row.tenant_id, employee_row.employee_name, employee_row.id
    limit v_record_limit
  ), competency_matrix as (
    select competency_row.id, competency_row.competency_code, competency_row.competency_name,
      coalesce(nullif(competency_row.category, ''), '未分类') as category,
      count(*)::integer as required_employees,
      count(employee_competency.id)::integer as assessed_employees,
      count(*) filter (where
        case employee_competency.current_level
          when 'expert' then 4 when 'advanced' then 3 when 'intermediate' then 2
          when 'basic' then 1 else 0 end
        >= case position_competency.required_level
          when 'expert' then 4 when 'advanced' then 3 when 'intermediate' then 2
          when 'basic' then 1 else 0 end
      )::integer as met_employees,
      round(avg(position_competency.weight), 1) as average_weight
    from employee_scope employee_row
    join public.hr_position_competency position_competency
      on position_competency.position_id = employee_row.position_id
      and position_competency.tenant_id = employee_row.tenant_id
    join public.hr_competency competency_row
      on competency_row.id = position_competency.competency_id
      and competency_row.tenant_id = employee_row.tenant_id
    left join public.hr_employee_competency employee_competency
      on employee_competency.employee_id = employee_row.id
      and employee_competency.competency_id = competency_row.id
      and employee_competency.tenant_id = employee_row.tenant_id
    group by competency_row.id, competency_row.competency_code,
      competency_row.competency_name, competency_row.category
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', competency_matrix.id,
    'competencyCode', competency_matrix.competency_code,
    'competencyName', competency_matrix.competency_name,
    'category', competency_matrix.category,
    'requiredEmployees', competency_matrix.required_employees,
    'assessedEmployees', competency_matrix.assessed_employees,
    'metEmployees', competency_matrix.met_employees,
    'gapEmployees', greatest(competency_matrix.required_employees - competency_matrix.met_employees, 0),
    'unassessedEmployees', greatest(competency_matrix.required_employees - competency_matrix.assessed_employees, 0),
    'readinessRate', case when competency_matrix.required_employees = 0 then null
      else round(competency_matrix.met_employees * 100.0 / competency_matrix.required_employees, 1) end,
    'averageWeight', competency_matrix.average_weight
  ) order by greatest(competency_matrix.required_employees - competency_matrix.met_employees, 0) desc,
    competency_matrix.competency_name, competency_matrix.id), '[]'::jsonb)
  into v_competencies
  from competency_matrix;

  return jsonb_build_object(
    'generatedAt', now(),
    'totalRecords', v_total_records,
    'returnedRecords', jsonb_array_length(v_records),
    'truncated', v_total_records > jsonb_array_length(v_records),
    'employeeCount', jsonb_array_length(v_records),
    'modelledEmployeeCount', v_modelled_employees,
    'assessedEmployeeCount', v_assessed_employees,
    'readyEmployeeCount', v_ready_employees,
    'gapEmployeeCount', v_gap_employees,
    'unassessedEmployeeCount', v_unassessed_employees,
    'records', v_records,
    'competencies', v_competencies
  );
end;
$$;


ALTER FUNCTION "public"."hr_get_skill_matrix_secure"() OWNER TO "postgres";

--

--
-- Name: hr_get_talent_inventory_secure(); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_get_talent_inventory_secure"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_is_platform_super boolean := app_private.is_platform_super();
  v_record_limit constant integer := 1000;
  v_total_records bigint := 0;
  v_records jsonb := '[]'::jsonb;
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;
  if not coalesce(app_private.has_permission('Hr:TalentInventory:View'), false) then
    raise exception 'Missing talent inventory view permission' using errcode = '42501';
  end if;
  if not v_is_platform_super and v_tenant_id is null then
    raise exception 'Talent inventory tenant is required' using errcode = '22023';
  end if;

  select count(*)
  into v_total_records
  from public.mdm_employee employee_row
  where (v_is_platform_super or (app_private.current_read_tenant_id() is null or employee_row.tenant_id = app_private.current_read_tenant_id()))
    and employee_row.employment_status <> 'terminated';

  with employee_scope as (
    select employee_row.id, employee_row.employee_no, employee_row.employee_name,
      employee_row.job_title, employee_row.organization_id, employee_row.position_id,
      employee_row.tenant_id, organization_row.organization_name, position_row.position_name
    from public.mdm_employee employee_row
    left join public.mdm_organization organization_row
      on organization_row.id = employee_row.organization_id
      and organization_row.tenant_id = employee_row.tenant_id
    left join public.mdm_position position_row
      on position_row.id = employee_row.position_id
      and position_row.tenant_id = employee_row.tenant_id
    where (v_is_platform_super or (app_private.current_read_tenant_id() is null or employee_row.tenant_id = app_private.current_read_tenant_id()))
      and employee_row.employment_status <> 'terminated'
    order by employee_row.tenant_id, employee_row.employee_name, employee_row.id
    limit v_record_limit
  ), latest_review as (
    select distinct on (review_row.employee_id)
      review_row.employee_id, review_row.total_score, review_row.performance_level,
      cycle_row.cycle_name
    from public.hr_performance_review review_row
    join public.hr_performance_cycle cycle_row on cycle_row.id = review_row.cycle_id
    join employee_scope employee_row on employee_row.id = review_row.employee_id
      and employee_row.tenant_id = review_row.tenant_id
    where review_row.status in ('confirmed', 'completed')
    order by review_row.employee_id, cycle_row.end_date desc,
      review_row.confirmed_at desc nulls last, review_row.id desc
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', employee_row.id,
    'employeeNo', employee_row.employee_no,
    'employeeName', employee_row.employee_name,
    'jobTitle', employee_row.job_title,
    'organizationName', employee_row.organization_name,
    'positionName', employee_row.position_name,
    'performanceLevel', review_row.performance_level,
    'totalScore', review_row.total_score,
    'cycleName', review_row.cycle_name,
    'competencyTotal', coalesce(competency.total_count, 0),
    'competencyMet', coalesce(competency.met_count, 0),
    'competencyGapCount', coalesce(competency.total_count - competency.met_count, 0),
    'readinessRate', case when coalesce(competency.total_count, 0) = 0 then null
      else round(competency.met_count * 100.0 / competency.total_count, 1) end
  ) order by coalesce(competency.total_count - competency.met_count, 0) desc,
    employee_row.employee_name, employee_row.id), '[]'::jsonb)
  into v_records
  from employee_scope employee_row
  left join latest_review review_row on review_row.employee_id = employee_row.id
  left join lateral (
    select count(*)::integer as total_count,
      count(*) filter (where
        case employee_competency.current_level
          when 'expert' then 4 when 'advanced' then 3 when 'intermediate' then 2 when 'basic' then 1 else 0 end
        >= case position_competency.required_level
          when 'expert' then 4 when 'advanced' then 3 when 'intermediate' then 2 when 'basic' then 1 else 0 end
      )::integer as met_count
    from public.hr_position_competency position_competency
    left join public.hr_employee_competency employee_competency
      on employee_competency.employee_id = employee_row.id
      and employee_competency.competency_id = position_competency.competency_id
      and employee_competency.tenant_id = employee_row.tenant_id
    where position_competency.position_id = employee_row.position_id
      and position_competency.tenant_id = employee_row.tenant_id
  ) competency on true;

  return jsonb_build_object(
    'generatedAt', now(),
    'records', v_records,
    'totalRecords', v_total_records,
    'returnedRecords', jsonb_array_length(v_records),
    'truncated', v_total_records > jsonb_array_length(v_records)
  );
end;
$$;


ALTER FUNCTION "public"."hr_get_talent_inventory_secure"() OWNER TO "postgres";

--

--
-- Name: hr_get_workforce_risk_secure(); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_get_workforce_risk_secure"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_is_platform_super boolean := app_private.is_platform_super();
begin
  if not coalesce(app_private.has_permission('Hr:WorkforceRisk:View'), false) then
    raise exception 'Missing workforce risk view permission' using errcode = '42501';
  end if;

  if not v_is_platform_super and v_tenant_id is null then
    raise exception 'Workforce risk tenant is required' using errcode = '22023';
  end if;

  return jsonb_build_object(
    'activeEmployeeCount', (
      select count(*)
      from public.mdm_employee employee_row
      where (v_is_platform_super or (app_private.current_read_tenant_id() is null or employee_row.tenant_id = app_private.current_read_tenant_id()))
        and employee_row.employment_status = 'active'
    ),
    'probationEmployees', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', scoped.id,
        'employeeNo', scoped.employee_no,
        'employeeName', scoped.employee_name,
        'probationEndDate', scoped.probation_end_date
      ) order by scoped.probation_end_date, scoped.id)
      from (
        select employee_row.id, employee_row.employee_no, employee_row.employee_name,
          employee_row.probation_end_date
        from public.mdm_employee employee_row
        where (v_is_platform_super or (app_private.current_read_tenant_id() is null or employee_row.tenant_id = app_private.current_read_tenant_id()))
          and employee_row.employment_status = 'probation'
          and employee_row.probation_end_date is not null
          and employee_row.probation_end_date <= current_date + 30
        order by employee_row.probation_end_date, employee_row.id
        limit 1000
      ) scoped
    ), '[]'::jsonb),
    'contracts', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', scoped.id,
        'contractNo', scoped.contract_no,
        'endDate', scoped.end_date,
        'employee', jsonb_build_object(
          'id', scoped.employee_id,
          'employeeNo', scoped.employee_no,
          'employeeName', scoped.employee_name
        )
      ) order by scoped.end_date, scoped.id)
      from (
        select contract_row.id, contract_row.contract_no, contract_row.end_date,
          employee_row.id as employee_id, employee_row.employee_no, employee_row.employee_name
        from public.hr_employee_contract contract_row
        left join public.mdm_employee employee_row
          on employee_row.id = contract_row.employee_id
          and employee_row.tenant_id = contract_row.tenant_id
        where (v_is_platform_super or (app_private.current_read_tenant_id() is null or contract_row.tenant_id = app_private.current_read_tenant_id()))
          and contract_row.contract_status = 'active'
          and contract_row.end_date is not null
          and contract_row.end_date <= current_date + 60
        order by contract_row.end_date, contract_row.id
        limit 1000
      ) scoped
    ), '[]'::jsonb),
    'qualifications', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', scoped.id,
        'qualificationName', scoped.qualification_name,
        'expiryDate', scoped.expiry_date,
        'employee', jsonb_build_object(
          'id', scoped.employee_id,
          'employeeNo', scoped.employee_no,
          'employeeName', scoped.employee_name
        )
      ) order by scoped.expiry_date, scoped.id)
      from (
        select qualification_row.id, qualification_row.qualification_name,
          qualification_row.expiry_date, employee_row.id as employee_id,
          employee_row.employee_no, employee_row.employee_name
        from public.hr_employee_qualification qualification_row
        left join public.mdm_employee employee_row
          on employee_row.id = qualification_row.employee_id
          and employee_row.tenant_id = qualification_row.tenant_id
        where (v_is_platform_super or (app_private.current_read_tenant_id() is null or qualification_row.tenant_id = app_private.current_read_tenant_id()))
          and qualification_row.status = 'valid'
          and qualification_row.expiry_date is not null
          and qualification_row.expiry_date <= current_date + 60
        order by qualification_row.expiry_date, qualification_row.id
        limit 1000
      ) scoped
    ), '[]'::jsonb),
    'headcounts', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', scoped.id,
        'approvedCount', scoped.approved_count,
        'occupiedCount', scoped.occupied_count,
        'vacancyCount', greatest(scoped.approved_count - scoped.occupied_count, 0),
        'enabled', scoped.enabled,
        'organization', jsonb_build_object(
          'id', scoped.organization_id,
          'organizationCode', scoped.organization_code,
          'organizationName', scoped.organization_name
        ),
        'position', jsonb_build_object(
          'id', scoped.position_id,
          'positionCode', scoped.position_code,
          'positionName', scoped.position_name
        )
      ) order by scoped.organization_name, scoped.position_name, scoped.id)
      from (
        select headcount_row.id, headcount_row.organization_id, headcount_row.position_id,
          headcount_row.approved_count, headcount_row.enabled,
          organization_row.organization_code, organization_row.organization_name,
          position_row.position_code, position_row.position_name,
          (
            select count(*)::integer
            from public.mdm_employee employee_row
            where employee_row.tenant_id = headcount_row.tenant_id
              and employee_row.organization_id = headcount_row.organization_id
              and employee_row.position_id = headcount_row.position_id
              and employee_row.employment_status <> 'terminated'
          ) as occupied_count
        from public.hr_position_headcount headcount_row
        left join public.mdm_organization organization_row
          on organization_row.id = headcount_row.organization_id
          and organization_row.tenant_id = headcount_row.tenant_id
        left join public.mdm_position position_row
          on position_row.id = headcount_row.position_id
          and position_row.tenant_id = headcount_row.tenant_id
        where (v_is_platform_super or (app_private.current_read_tenant_id() is null or headcount_row.tenant_id = app_private.current_read_tenant_id()))
          and headcount_row.enabled
          and headcount_row.effective_from <= current_date
          and (headcount_row.effective_to is null or headcount_row.effective_to >= current_date)
        order by organization_row.organization_name, position_row.position_name, headcount_row.id
        limit 1000
      ) scoped
    ), '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."hr_get_workforce_risk_secure"() OWNER TO "postgres";

--

--
-- Name: hr_internal_mobility_overview_secure("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_internal_mobility_overview_secure"("p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    SET "TimeZone" TO 'Asia/Shanghai'
    AS $$
declare
  v_tenant_id uuid:=app_private.current_user_tenant_id();
  v_employee_id uuid:=app_private.hr_current_employee_id();
  v_manage boolean;
begin
  if auth.uid() is null or not app_private.can_execute_business_action(
    'HrInternalMobility','Hr:InternalMobility:View',null,false
  ) then raise exception '当前账号没有查看内部人才市场的权限' using errcode='42501'; end if;
  if not app_private.is_platform_super() then p_tenant_id:=v_tenant_id; end if;
  v_manage:=app_private.can_execute_business_action(
    'HrInternalMobility','Hr:InternalMobility:Application:Manage',null,false
  );
  return jsonb_build_object(
    'open_opportunity_count',(select count(*) from public.hr_internal_opportunity o
      where (p_tenant_id is null or o.tenant_id=p_tenant_id) and o.status='open'
        and current_date between o.application_open_date and o.application_close_date),
    'closing_soon_count',(select count(*) from public.hr_internal_opportunity o
      where (p_tenant_id is null or o.tenant_id=p_tenant_id) and o.status='open'
        and o.application_close_date between current_date and current_date+7),
    'application_count',(select count(*) from public.hr_internal_mobility_application a
      where (p_tenant_id is null or a.tenant_id=p_tenant_id) and (v_manage or a.employee_id=v_employee_id)),
    'active_application_count',(select count(*) from public.hr_internal_mobility_application a
      where (p_tenant_id is null or a.tenant_id=p_tenant_id) and (v_manage or a.employee_id=v_employee_id)
        and a.status in ('submitted','under_review','shortlisted','offered')),
    'offer_count',(select count(*) from public.hr_internal_mobility_application a
      where (p_tenant_id is null or a.tenant_id=p_tenant_id) and (v_manage or a.employee_id=v_employee_id)
        and a.status in ('offered','accepted','converted')),
    'converted_count',(select count(*) from public.hr_internal_mobility_application a
      where (p_tenant_id is null or a.tenant_id=p_tenant_id) and (v_manage or a.employee_id=v_employee_id)
        and a.status='converted'),
    'my_employee_id',v_employee_id,
    'manage_access',v_manage
  );
end;
$$;


ALTER FUNCTION "public"."hr_internal_mobility_overview_secure"("p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_learning_overview_secure("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_learning_overview_secure"("p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
begin
  if not app_private.can_execute_business_action('HrTalentDevelopment', 'Hr:Talent:View', null, false) then
    raise exception '当前账号没有查看学习发展工作台的权限' using errcode = '42501';
  end if;
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;

  update public.hr_learning_certificate
  set status = 'expired'
  where status = 'valid' and expires_on is not null and expires_on < current_date
    and (p_tenant_id is null or tenant_id = p_tenant_id);

  return jsonb_build_object(
    'published_course_count', (
      select count(*) from public.hr_learning_course c
      where (p_tenant_id is null or c.tenant_id = p_tenant_id) and c.status = 'published'
    ),
    'open_session_count', (
      select count(*) from public.hr_learning_session s
      where (p_tenant_id is null or s.tenant_id = p_tenant_id)
        and s.status in ('open', 'in_progress')
    ),
    'active_learner_count', (
      select count(distinct e.employee_id) from public.hr_training_enrollment e
      where (p_tenant_id is null or e.tenant_id = p_tenant_id)
        and e.status in ('enrolled', 'attending') and e.session_id is not null
    ),
    'completion_rate', (
      select coalesce(round(
        100 * count(*) filter (where e.status = 'passed')::numeric
        / nullif(count(*) filter (where e.status in ('passed', 'failed', 'no_show')), 0), 1
      ), 0)
      from public.hr_training_enrollment e
      where (p_tenant_id is null or e.tenant_id = p_tenant_id) and e.session_id is not null
    ),
    'expiring_certificate_count', (
      select count(*) from public.hr_learning_certificate c
      where (p_tenant_id is null or c.tenant_id = p_tenant_id)
        and c.status = 'valid' and c.expires_on between current_date and current_date + 60
    ),
    'budget_execution_rate', (
      select coalesce(round(100 * sum(coalesce(p.actual_cost, 0)) / nullif(sum(coalesce(p.budget, 0)), 0), 1), 0)
      from public.hr_training_plan p
      where (p_tenant_id is null or p.tenant_id = p_tenant_id)
        and p.status in ('published', 'in_progress', 'completed')
    )
  );
end
$$;


ALTER FUNCTION "public"."hr_learning_overview_secure"("p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_lifecycle_overview_secure("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_lifecycle_overview_secure"("p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
begin
  if not app_private.can_execute_business_action('HrLifecycle', 'Hr:Lifecycle:View', null, false) then
    raise exception '当前账号没有查看入转调离工作台的权限' using errcode = '42501';
  end if;
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;

  return jsonb_build_object(
    'active_case_count', (
      select count(*) from public.hr_lifecycle_case c
      where (p_tenant_id is null or c.tenant_id = p_tenant_id)
        and c.execution_status in ('planning', 'in_progress', 'ready')
    ),
    'due_soon_case_count', (
      select count(*) from public.hr_lifecycle_case c
      where (p_tenant_id is null or c.tenant_id = p_tenant_id)
        and c.execution_status in ('planning', 'in_progress')
        and c.planned_effective_date between current_date and current_date + 7
    ),
    'overdue_blocking_task_count', (
      select count(*) from public.hr_lifecycle_task t
      join public.hr_lifecycle_case c on c.id = t.lifecycle_case_id and c.tenant_id = t.tenant_id
      where (p_tenant_id is null or t.tenant_id = p_tenant_id)
        and c.execution_status in ('planning', 'in_progress')
        and t.blocking and t.status in ('pending', 'processing') and t.due_date < current_date
    ),
    'ready_case_count', (
      select count(*) from public.hr_lifecycle_case c
      where (p_tenant_id is null or c.tenant_id = p_tenant_id)
        and c.execution_status = 'ready'
    ),
    'default_template_count', (
      select count(*) from public.hr_lifecycle_template t
      where (p_tenant_id is null or t.tenant_id = p_tenant_id)
        and t.status = 'active' and t.is_default
    ),
    'completion_rate', (
      select coalesce(round(100 * count(*) filter (where c.execution_status = 'completed')::numeric
        / nullif(count(*) filter (where c.execution_status in ('completed', 'cancelled')), 0), 1), 0)
      from public.hr_lifecycle_case c
      where (p_tenant_id is null or c.tenant_id = p_tenant_id)
        and c.create_time >= now() - interval '90 days'
    )
  );
end
$$;


ALTER FUNCTION "public"."hr_lifecycle_overview_secure"("p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_list_absence_options_secure("text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_absence_options_secure"("p_kind" "text", "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_result jsonb;
begin
  if not app_private.can_execute_business_action('HrAbsence', 'Hr:Absence:View', null, false) then
    raise exception 'Missing absence view permission' using errcode = '42501';
  end if;
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;

  if p_kind = 'employee' then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', employee_row.id, 'tenant_id', employee_row.tenant_id,
      'code', employee_row.employee_no, 'name', employee_row.employee_name,
      'organization_id', employee_row.organization_id,
      'organization_name', organization_row.organization_name
    ) order by employee_row.employee_name), '[]'::jsonb) into v_result
    from public.mdm_employee employee_row
    left join public.mdm_organization organization_row on organization_row.id = employee_row.organization_id
    where (p_tenant_id is null or employee_row.tenant_id = p_tenant_id)
      and employee_row.employment_status in ('probation', 'active', 'leave');
  elsif p_kind = 'leave_type' then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', type_row.id, 'tenant_id', type_row.tenant_id,
      'code', type_row.leave_code, 'name', type_row.leave_name,
      'unit', type_row.unit, 'minimum_increment', type_row.minimum_increment
    ) order by type_row.sort, type_row.leave_name), '[]'::jsonb) into v_result
    from public.hr_leave_type type_row
    where (p_tenant_id is null or type_row.tenant_id = p_tenant_id) and type_row.enabled;
  elsif p_kind = 'organization' then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', organization_row.id, 'tenant_id', organization_row.tenant_id,
      'code', organization_row.organization_code, 'name', organization_row.organization_name
    ) order by organization_row.organization_name), '[]'::jsonb) into v_result
    from public.mdm_organization organization_row
    where (p_tenant_id is null or organization_row.tenant_id = p_tenant_id);
  elsif p_kind = 'grade' then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', grade_row.id, 'tenant_id', grade_row.tenant_id,
      'code', grade_row.grade_code, 'name', grade_row.grade_name
    ) order by grade_row.grade_level, grade_row.grade_name), '[]'::jsonb) into v_result
    from public.mdm_grade grade_row
    where (p_tenant_id is null or grade_row.tenant_id = p_tenant_id) and grade_row.enabled;
  elsif p_kind = 'policy' then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', policy_row.id, 'tenant_id', policy_row.tenant_id,
      'code', policy_row.policy_code, 'name', policy_row.policy_name,
      'leave_type_id', policy_row.leave_type_id
    ) order by policy_row.policy_name), '[]'::jsonb) into v_result
    from public.hr_leave_policy policy_row
    where (p_tenant_id is null or policy_row.tenant_id = p_tenant_id)
      and policy_row.status = 'active'
      and policy_row.effective_from <= current_date
      and coalesce(policy_row.effective_to, 'infinity'::date) >= current_date;
  else
    raise exception '不支持的假勤选项类型';
  end if;
  return coalesce(v_result, '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."hr_list_absence_options_secure"("p_kind" "text", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_list_absence_records_secure("text", integer, integer, "text", "text", integer, "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_absence_records_secure"("p_kind" "text", "p_from" integer DEFAULT 0, "p_to" integer DEFAULT 19, "p_keyword" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_balance_year" integer DEFAULT NULL::integer, "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_offset integer := greatest(coalesce(p_from, 0), 0);
  v_limit integer := least(500, greatest(coalesce(p_to, 19) - greatest(coalesce(p_from, 0), 0) + 1, 1));
  v_keyword text := nullif(btrim(p_keyword), '');
  v_can_view_reason boolean;
  v_result jsonb;
begin
  if p_kind not in ('request', 'balance', 'policy', 'type', 'ledger') then
    raise exception '不支持的假勤记录类型';
  end if;
  if not app_private.can_execute_business_action('HrAbsence', 'Hr:Absence:View', null, false) then
    raise exception 'Missing absence view permission' using errcode = '42501';
  end if;
  v_can_view_reason := app_private.can_execute_business_action(
    'HrAbsence', 'Hr:Absence:Reason:View', null, false
  );
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;

  if p_kind = 'type' then
    with filtered as materialized (
      select type_row.*, tenant_row.tenant_code, tenant_row.tenant_name,
        (select count(*) from public.hr_leave_policy policy_row
          where policy_row.leave_type_id = type_row.id) as policy_count
      from public.hr_leave_type type_row
      join public.sys_tenant tenant_row on tenant_row.id = type_row.tenant_id
      where (p_tenant_id is null or type_row.tenant_id = p_tenant_id)
        and (p_status is null or type_row.enabled = (p_status = 'enabled'))
        and (v_keyword is null or type_row.leave_code ilike '%' || v_keyword || '%'
          or type_row.leave_name ilike '%' || v_keyword || '%')
    ), paged as (
      select * from filtered order by tenant_name, sort, leave_name offset v_offset limit v_limit
    )
    select jsonb_build_object(
      'records', coalesce(jsonb_agg((to_jsonb(paged) - 'tenant_code' - 'tenant_name') ||
        jsonb_build_object('tenant', jsonb_build_object('id', tenant_id,
          'tenant_code', tenant_code, 'tenant_name', tenant_name))
        order by tenant_name, sort, leave_name), '[]'::jsonb),
      'total', (select count(*) from filtered), 'reason_access', v_can_view_reason
    ) into v_result from paged;
    return coalesce(v_result, jsonb_build_object('records', '[]'::jsonb, 'total', 0, 'reason_access', v_can_view_reason));
  end if;

  if p_kind = 'policy' then
    with filtered as materialized (
      select policy_row.*, tenant_row.tenant_code, tenant_row.tenant_name,
        type_row.leave_code, type_row.leave_name, type_row.unit,
        organization_row.organization_code, organization_row.organization_name,
        employee_row.employee_no, employee_row.employee_name,
        grade_row.grade_code, grade_row.grade_name
      from public.hr_leave_policy policy_row
      join public.sys_tenant tenant_row on tenant_row.id = policy_row.tenant_id
      join public.hr_leave_type type_row on type_row.id = policy_row.leave_type_id
      left join public.mdm_organization organization_row on organization_row.id = policy_row.organization_id
      left join public.mdm_employee employee_row on employee_row.id = policy_row.employee_id
      left join public.mdm_grade grade_row on grade_row.id = policy_row.grade_id
      where (p_tenant_id is null or policy_row.tenant_id = p_tenant_id)
        and (p_status is null or policy_row.status = p_status)
        and (v_keyword is null or policy_row.policy_code ilike '%' || v_keyword || '%'
          or policy_row.policy_name ilike '%' || v_keyword || '%'
          or type_row.leave_name ilike '%' || v_keyword || '%')
    ), paged as (
      select * from filtered order by tenant_name, policy_name offset v_offset limit v_limit
    )
    select jsonb_build_object(
      'records', coalesce(jsonb_agg((to_jsonb(paged)
        - 'tenant_code' - 'tenant_name' - 'leave_code' - 'leave_name' - 'unit'
        - 'organization_code' - 'organization_name' - 'employee_no' - 'employee_name'
        - 'grade_code' - 'grade_name') || jsonb_build_object(
          'tenant', jsonb_build_object('id', tenant_id, 'tenant_code', tenant_code, 'tenant_name', tenant_name),
          'leave_type', jsonb_build_object('id', leave_type_id, 'leave_code', leave_code, 'leave_name', leave_name, 'unit', unit),
          'scope', jsonb_strip_nulls(jsonb_build_object(
            'organization_id', organization_id, 'organization_code', organization_code, 'organization_name', organization_name,
            'employee_id', employee_id, 'employee_no', employee_no, 'employee_name', employee_name,
            'grade_id', grade_id, 'grade_code', grade_code, 'grade_name', grade_name
          ))
        ) order by tenant_name, policy_name), '[]'::jsonb),
      'total', (select count(*) from filtered), 'reason_access', v_can_view_reason
    ) into v_result from paged;
    return coalesce(v_result, jsonb_build_object('records', '[]'::jsonb, 'total', 0, 'reason_access', v_can_view_reason));
  end if;

  if p_kind = 'balance' then
    with filtered as materialized (
      select balance_row.*, tenant_row.tenant_code, tenant_row.tenant_name,
        employee_row.employee_no, employee_row.employee_name,
        organization_row.organization_name,
        type_row.leave_code, type_row.leave_name, type_row.unit,
        policy_row.policy_code, policy_row.policy_name,
        balance_row.opening_amount + balance_row.accrued_amount + balance_row.adjusted_amount
          - balance_row.pending_amount - balance_row.used_amount - balance_row.expired_amount as available_amount
      from public.hr_leave_balance balance_row
      join public.sys_tenant tenant_row on tenant_row.id = balance_row.tenant_id
      join public.mdm_employee employee_row on employee_row.id = balance_row.employee_id
      left join public.mdm_organization organization_row on organization_row.id = employee_row.organization_id
      join public.hr_leave_type type_row on type_row.id = balance_row.leave_type_id
      left join public.hr_leave_policy policy_row on policy_row.id = balance_row.policy_id
      where (p_tenant_id is null or balance_row.tenant_id = p_tenant_id)
        and (p_balance_year is null or balance_row.balance_year = p_balance_year)
        and (v_keyword is null or employee_row.employee_no ilike '%' || v_keyword || '%'
          or employee_row.employee_name ilike '%' || v_keyword || '%'
          or type_row.leave_name ilike '%' || v_keyword || '%')
    ), paged as (
      select * from filtered order by tenant_name, employee_name, leave_name offset v_offset limit v_limit
    )
    select jsonb_build_object(
      'records', coalesce(jsonb_agg((to_jsonb(paged)
        - 'tenant_code' - 'tenant_name' - 'employee_no' - 'employee_name' - 'organization_name'
        - 'leave_code' - 'leave_name' - 'unit' - 'policy_code' - 'policy_name') || jsonb_build_object(
          'tenant', jsonb_build_object('id', tenant_id, 'tenant_code', tenant_code, 'tenant_name', tenant_name),
          'employee', jsonb_build_object('id', employee_id, 'employee_no', employee_no, 'employee_name', employee_name),
          'organization', jsonb_build_object('organization_name', organization_name),
          'leave_type', jsonb_build_object('id', leave_type_id, 'leave_code', leave_code, 'leave_name', leave_name, 'unit', unit),
          'policy', case when policy_id is null then null else jsonb_build_object('id', policy_id, 'policy_code', policy_code, 'policy_name', policy_name) end
        ) order by tenant_name, employee_name, leave_name), '[]'::jsonb),
      'total', (select count(*) from filtered), 'reason_access', v_can_view_reason
    ) into v_result from paged;
    return coalesce(v_result, jsonb_build_object('records', '[]'::jsonb, 'total', 0, 'reason_access', v_can_view_reason));
  end if;

  if p_kind = 'request' then
    with filtered as materialized (
      select request_row.*, tenant_row.tenant_code, tenant_row.tenant_name,
        employee_row.employee_no, employee_row.employee_name,
        organization_row.organization_name,
        type_row.leave_code, type_row.leave_name,
        case when v_can_view_reason then request_row.reason else '***' end as visible_reason
      from public.hr_leave_request request_row
      join public.sys_tenant tenant_row on tenant_row.id = request_row.tenant_id
      join public.mdm_employee employee_row on employee_row.id = request_row.employee_id
      left join public.mdm_organization organization_row on organization_row.id = employee_row.organization_id
      join public.hr_leave_type type_row on type_row.id = request_row.leave_type_id
      where (p_tenant_id is null or request_row.tenant_id = p_tenant_id)
        and (p_status is null or request_row.status = p_status)
        and (v_keyword is null or request_row.request_no ilike '%' || v_keyword || '%'
          or employee_row.employee_no ilike '%' || v_keyword || '%'
          or employee_row.employee_name ilike '%' || v_keyword || '%'
          or type_row.leave_name ilike '%' || v_keyword || '%')
    ), paged as (
      select * from filtered order by tenant_name, create_time desc offset v_offset limit v_limit
    )
    select jsonb_build_object(
      'records', coalesce(jsonb_agg(((to_jsonb(paged)
        - 'tenant_code' - 'tenant_name' - 'employee_no' - 'employee_name' - 'organization_name'
        - 'leave_code' - 'leave_name' - 'visible_reason' - 'reason'
        - case when v_can_view_reason then '__keep_proof__' else 'proof_urls' end) || jsonb_build_object(
          'reason', visible_reason,
          'proof_urls', case when v_can_view_reason then proof_urls else '[]'::jsonb end,
          'tenant', jsonb_build_object('id', tenant_id, 'tenant_code', tenant_code, 'tenant_name', tenant_name),
          'employee', jsonb_build_object('id', employee_id, 'employee_no', employee_no, 'employee_name', employee_name),
          'organization', jsonb_build_object('organization_name', organization_name),
          'leave_type', jsonb_build_object('id', leave_type_id, 'leave_code', leave_code, 'leave_name', leave_name, 'unit', unit_snapshot)
        )) order by tenant_name, create_time desc), '[]'::jsonb),
      'total', (select count(*) from filtered), 'reason_access', v_can_view_reason
    ) into v_result from paged;
    return coalesce(v_result, jsonb_build_object('records', '[]'::jsonb, 'total', 0, 'reason_access', v_can_view_reason));
  end if;

  with filtered as materialized (
    select ledger_row.*, employee_row.employee_no, employee_row.employee_name,
      type_row.leave_code, type_row.leave_name, type_row.unit,
      request_row.request_no
    from public.hr_leave_ledger ledger_row
    join public.mdm_employee employee_row on employee_row.id = ledger_row.employee_id
    join public.hr_leave_type type_row on type_row.id = ledger_row.leave_type_id
    left join public.hr_leave_request request_row on request_row.id = ledger_row.request_id
    where (p_tenant_id is null or ledger_row.tenant_id = p_tenant_id)
      and (p_balance_year is null or extract(year from ledger_row.occurred_on)::integer = p_balance_year)
      and (p_status is null or ledger_row.transaction_type = p_status)
      and (v_keyword is null or employee_row.employee_no ilike '%' || v_keyword || '%'
        or employee_row.employee_name ilike '%' || v_keyword || '%'
        or type_row.leave_name ilike '%' || v_keyword || '%'
        or request_row.request_no ilike '%' || v_keyword || '%')
  ), paged as (
    select * from filtered order by occurred_on desc, create_time desc offset v_offset limit v_limit
  )
  select jsonb_build_object(
    'records', coalesce(jsonb_agg((to_jsonb(paged)
      - 'employee_no' - 'employee_name' - 'leave_code' - 'leave_name' - 'unit' - 'request_no') || jsonb_build_object(
        'employee', jsonb_build_object('id', employee_id, 'employee_no', employee_no, 'employee_name', employee_name),
        'leave_type', jsonb_build_object('id', leave_type_id, 'leave_code', leave_code, 'leave_name', leave_name, 'unit', unit),
        'request', case when request_id is null then null else jsonb_build_object('id', request_id, 'request_no', request_no) end
      ) order by occurred_on desc, create_time desc), '[]'::jsonb),
    'total', (select count(*) from filtered), 'reason_access', v_can_view_reason
  ) into v_result from paged;
  return coalesce(v_result, jsonb_build_object('records', '[]'::jsonb, 'total', 0, 'reason_access', v_can_view_reason));
end;
$$;


ALTER FUNCTION "public"."hr_list_absence_records_secure"("p_kind" "text", "p_from" integer, "p_to" integer, "p_keyword" "text", "p_status" "text", "p_balance_year" integer, "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_list_assignment_position_options_secure("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_assignment_position_options_secure"("p_organization_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_tenant_id uuid:=app_private.current_user_tenant_id();
begin
  if not (
    app_private.can_execute_business_action('HrPersonnelChange','Hr:PersonnelChange:Add',null,false)
    or app_private.can_execute_business_action('HrPersonnelChange','Hr:PersonnelChange:Edit',null,false)
    or app_private.can_execute_business_action('HrEmployeeRoster','Hr:Employee:Add',null,false)
    or app_private.can_execute_business_action('HrEmployeeRoster','Hr:Employee:Edit',null,false)
  ) then raise exception 'Missing assignment position permission' using errcode='42501'; end if;
  if p_organization_id is not null and not exists(select 1 from public.mdm_organization where id=p_organization_id and (app_private.current_read_tenant_id() is null or tenant_id = app_private.current_read_tenant_id()) and status='1') then raise exception '所选组织不可用'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
    'id',position_row.id,'organization_id',position_row.organization_id,
    'position_code',position_row.position_code,'position_name',position_row.position_name,
    'position_kind',position_row.position_kind,'job_profile_id',position_row.job_profile_id,
    'grade_id',position_row.grade_id,'headcount_limit',position_row.headcount_limit,
    'multiple_incumbents_allowed',position_row.multiple_incumbents_allowed,
    'job_profile',jsonb_build_object('id',profile_row.id,'job_code',profile_row.job_code,'job_name',profile_row.job_name),
    'grade',case when grade_row.id is null then null else jsonb_build_object('id',grade_row.id,'grade_code',grade_row.grade_code,'grade_name',grade_row.grade_name) end
  ) order by position_row.sort,position_row.position_name)
  from public.mdm_position position_row
  join public.mdm_job_profile profile_row on profile_row.id=position_row.job_profile_id and profile_row.tenant_id=position_row.tenant_id
  left join public.mdm_grade grade_row on grade_row.id=position_row.grade_id and grade_row.tenant_id=position_row.tenant_id
  where (app_private.current_read_tenant_id() is null or position_row.tenant_id = app_private.current_read_tenant_id()) and position_row.enabled
    and (p_organization_id is null or position_row.organization_id=p_organization_id or position_row.organization_id is null)
  ),'[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."hr_list_assignment_position_options_secure"("p_organization_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_list_attendance_options_secure("text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_attendance_options_secure"("p_kind" "text", "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
begin
  if p_kind not in ('employee','shift','record') then raise exception '不支持的考勤选项类型'; end if;
  if not app_private.can_execute_business_action('HrAttendance', 'Hr:Attendance:View', null, false) then
    raise exception '当前账号没有查看考勤选项的权限' using errcode='42501';
  end if;
  if not app_private.is_platform_super() then p_tenant_id:=v_tenant_id; end if;
  if p_kind='employee' then
    return coalesce((select jsonb_agg(jsonb_build_object('id',e.id,'tenant_id',e.tenant_id,
      'code',e.employee_no,'name',e.employee_name) order by e.employee_no)
      from public.mdm_employee e where (p_tenant_id is null or e.tenant_id=p_tenant_id)
        and e.employment_status <> 'terminated'),'[]'::jsonb);
  end if;
  if p_kind='shift' then
    return coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'tenant_id',s.tenant_id,
      'code',s.shift_code,'name',s.shift_name,'start_time',s.start_time,'end_time',s.end_time,
      'time_zone',s.time_zone) order by s.shift_code)
      from public.hr_shift s where (p_tenant_id is null or s.tenant_id=p_tenant_id) and s.enabled),'[]'::jsonb);
  end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'tenant_id',r.tenant_id,
    'code',to_char(r.work_date,'YYYY-MM-DD'),'name',e.employee_name,'employee_id',r.employee_id,
    'work_date',r.work_date,'clock_in_at',r.clock_in_at,'clock_out_at',r.clock_out_at,
    'exception_status',r.exception_status) order by r.work_date desc,e.employee_name)
    from public.hr_attendance_record r join public.mdm_employee e on e.id=r.employee_id and e.tenant_id=r.tenant_id
    where (p_tenant_id is null or r.tenant_id=p_tenant_id) and r.locked_at is null
      and not exists(select 1 from public.hr_attendance_correction c
        where c.attendance_record_id=r.id and c.status in ('draft','submitted'))),'[]'::jsonb);
end
$$;


ALTER FUNCTION "public"."hr_list_attendance_options_secure"("p_kind" "text", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_list_attendance_records_secure("text", integer, integer, "text", "text", "date", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_attendance_records_secure"("p_kind" "text", "p_from" integer DEFAULT 0, "p_to" integer DEFAULT 19, "p_keyword" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_period_month" "date" DEFAULT NULL::"date", "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_offset integer := greatest(coalesce(p_from, 0), 0);
  v_limit integer := least(500, greatest(coalesce(p_to, 19) - greatest(coalesce(p_from, 0), 0) + 1, 1));
  v_keyword text := nullif(btrim(p_keyword), '');
  v_result jsonb;
begin
  if p_kind not in ('record', 'assignment', 'correction', 'period', 'shift') then
    raise exception '不支持的考勤记录类型';
  end if;
  if not app_private.can_execute_business_action('HrAttendance', 'Hr:Attendance:View', null, false) then
    raise exception '当前账号没有查看考勤工时的权限' using errcode = '42501';
  end if;
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;

  if p_kind = 'shift' then
    with filtered as materialized (
      select s.*,
        (select count(*) from public.hr_shift_assignment a where a.shift_id=s.id and a.tenant_id=s.tenant_id) usage_count
      from public.hr_shift s
      where (p_tenant_id is null or s.tenant_id=p_tenant_id)
        and (p_status is null or s.enabled = (p_status='enabled'))
        and (v_keyword is null or s.shift_code ilike '%'||v_keyword||'%'
          or s.shift_name ilike '%'||v_keyword||'%')
    ), paged as (
      select * from filtered order by enabled desc, shift_code offset v_offset limit v_limit
    )
    select jsonb_build_object('records',coalesce(jsonb_agg(to_jsonb(paged) order by enabled desc,shift_code),'[]'::jsonb),
      'total',(select count(*) from filtered)) into v_result from paged;
    return coalesce(v_result,jsonb_build_object('records','[]'::jsonb,'total',0));
  end if;

  if p_kind = 'assignment' then
    with filtered as materialized (
      select a.*, e.employee_no,e.employee_name,s.shift_code,s.shift_name,s.start_time,s.end_time
      from public.hr_shift_assignment a
      join public.mdm_employee e on e.id=a.employee_id and e.tenant_id=a.tenant_id
      join public.hr_shift s on s.id=a.shift_id and s.tenant_id=a.tenant_id
      where (p_tenant_id is null or a.tenant_id=p_tenant_id)
        and (p_status is null or a.assignment_status=p_status)
        and (p_period_month is null or a.work_date >= date_trunc('month',p_period_month)::date
          and a.work_date < (date_trunc('month',p_period_month)+interval '1 month')::date)
        and (v_keyword is null or e.employee_no ilike '%'||v_keyword||'%'
          or e.employee_name ilike '%'||v_keyword||'%' or s.shift_name ilike '%'||v_keyword||'%')
    ), paged as (
      select * from filtered order by work_date desc,employee_name offset v_offset limit v_limit
    )
    select jsonb_build_object('records',coalesce(jsonb_agg(
      (to_jsonb(paged)-'employee_no'-'employee_name'-'shift_code'-'shift_name'-'start_time'-'end_time')
      ||jsonb_build_object('employee',jsonb_build_object('id',employee_id,'code',employee_no,'name',employee_name),
        'shift',jsonb_build_object('id',shift_id,'code',shift_code,'name',shift_name,'start_time',start_time,'end_time',end_time))
      order by work_date desc,employee_name),'[]'::jsonb),'total',(select count(*) from filtered))
    into v_result from paged;
    return coalesce(v_result,jsonb_build_object('records','[]'::jsonb,'total',0));
  end if;

  if p_kind = 'record' then
    with filtered as materialized (
      select r.*, e.employee_no,e.employee_name,s.shift_code,s.shift_name,
        exists(select 1 from public.hr_attendance_correction c where c.attendance_record_id=r.id and c.status='submitted') pending_correction
      from public.hr_attendance_record r
      join public.mdm_employee e on e.id=r.employee_id and e.tenant_id=r.tenant_id
      left join public.hr_shift s on s.id=r.shift_id and s.tenant_id=r.tenant_id
      where (p_tenant_id is null or r.tenant_id=p_tenant_id)
        and (p_status is null or r.exception_status=p_status)
        and (p_period_month is null or r.work_date >= date_trunc('month',p_period_month)::date
          and r.work_date < (date_trunc('month',p_period_month)+interval '1 month')::date)
        and (v_keyword is null or e.employee_no ilike '%'||v_keyword||'%'
          or e.employee_name ilike '%'||v_keyword||'%' or s.shift_name ilike '%'||v_keyword||'%'
          or r.valuation_note ilike '%'||v_keyword||'%')
    ), paged as (
      select * from filtered order by work_date desc,employee_name offset v_offset limit v_limit
    )
    select jsonb_build_object('records',coalesce(jsonb_agg(
      (to_jsonb(paged)-'employee_no'-'employee_name'-'shift_code'-'shift_name')
      ||jsonb_build_object('employee',jsonb_build_object('id',employee_id,'code',employee_no,'name',employee_name),
        'shift',case when shift_id is null then null else jsonb_build_object('id',shift_id,'code',shift_code,'name',shift_name) end)
      order by work_date desc,employee_name),'[]'::jsonb),'total',(select count(*) from filtered))
    into v_result from paged;
    return coalesce(v_result,jsonb_build_object('records','[]'::jsonb,'total',0));
  end if;

  if p_kind = 'correction' then
    with filtered as materialized (
      select c.*,r.work_date,r.clock_in_at original_clock_in_at,r.clock_out_at original_clock_out_at,
        r.exception_status,e.employee_no,e.employee_name
      from public.hr_attendance_correction c
      join public.hr_attendance_record r on r.id=c.attendance_record_id and r.tenant_id=c.tenant_id
      join public.mdm_employee e on e.id=c.employee_id and e.tenant_id=c.tenant_id
      where (p_tenant_id is null or c.tenant_id=p_tenant_id)
        and (p_status is null or c.status=p_status)
        and (p_period_month is null or r.work_date >= date_trunc('month',p_period_month)::date
          and r.work_date < (date_trunc('month',p_period_month)+interval '1 month')::date)
        and (v_keyword is null or c.correction_no ilike '%'||v_keyword||'%'
          or e.employee_no ilike '%'||v_keyword||'%' or e.employee_name ilike '%'||v_keyword||'%'
          or c.reason ilike '%'||v_keyword||'%')
    ), paged as (
      select * from filtered order by case when status='submitted' then 0 else 1 end,create_time desc
      offset v_offset limit v_limit
    )
    select jsonb_build_object('records',coalesce(jsonb_agg(
      (to_jsonb(paged)-'employee_no'-'employee_name')
      ||jsonb_build_object('employee',jsonb_build_object('id',employee_id,'code',employee_no,'name',employee_name),
        'record',jsonb_build_object('id',attendance_record_id,'work_date',work_date,
          'clock_in_at',original_clock_in_at,'clock_out_at',original_clock_out_at,'exception_status',exception_status))
      order by case when status='submitted' then 0 else 1 end,create_time desc),'[]'::jsonb),
      'total',(select count(*) from filtered)) into v_result from paged;
    return coalesce(v_result,jsonb_build_object('records','[]'::jsonb,'total',0));
  end if;

  with filtered as materialized (
    select p.* from public.hr_attendance_period p
    where (p_tenant_id is null or p.tenant_id=p_tenant_id)
      and (p_status is null or p.status=p_status)
      and (p_period_month is null or p.period_month=date_trunc('month',p_period_month)::date)
  ), paged as (
    select * from filtered order by period_month desc offset v_offset limit v_limit
  )
  select jsonb_build_object('records',coalesce(jsonb_agg(to_jsonb(paged) order by period_month desc),'[]'::jsonb),
    'total',(select count(*) from filtered)) into v_result from paged;
  return coalesce(v_result,jsonb_build_object('records','[]'::jsonb,'total',0));
end
$$;


ALTER FUNCTION "public"."hr_list_attendance_records_secure"("p_kind" "text", "p_from" integer, "p_to" integer, "p_keyword" "text", "p_status" "text", "p_period_month" "date", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_list_benefit_records_secure("text", integer, integer, "text", "text", "text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_benefit_records_secure"("p_kind" "text", "p_from" integer DEFAULT 0, "p_to" integer DEFAULT 19, "p_keyword" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_plan_type" "text" DEFAULT NULL::"text", "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_from integer := greatest(coalesce(p_from, 0), 0);
  v_to integer := greatest(coalesce(p_to, 19), greatest(coalesce(p_from, 0), 0));
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_keyword text := nullif(btrim(p_keyword), '');
  v_amount_visible boolean := app_private.hr_benefit_amount_visible();
  v_evidence_visible boolean := app_private.hr_benefit_evidence_visible();
  v_records jsonb;
  v_total bigint;
begin
  if auth.uid() is null or not app_private.can_execute_business_action(
    'HrBenefits', 'Hr:Benefits:View', null, false
  ) then
    raise exception '当前账号没有查看福利与参保的权限' using errcode = '42501';
  end if;
  if p_kind not in ('plan', 'enrollment', 'event') then
    raise exception '不支持的福利记录类型';
  end if;
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;

  if p_kind = 'plan' then
    with filtered as (
      select plan.*,
        (select count(*) from public.hr_benefit_option option
          where option.plan_id = plan.id and option.tenant_id = plan.tenant_id
            and option.enabled) as option_count,
        (select count(*) from public.hr_employee_benefit_enrollment enrollment
          where enrollment.plan_id = plan.id and enrollment.tenant_id = plan.tenant_id
            and enrollment.status = 'active') as active_enrollment_count
      from public.hr_benefit_plan plan
      where (p_tenant_id is null or plan.tenant_id = p_tenant_id)
        and (p_status is null or plan.status = p_status)
        and (p_plan_type is null or plan.plan_type = p_plan_type)
        and (v_keyword is null or plan.plan_code ilike '%' || v_keyword || '%'
          or plan.plan_name ilike '%' || v_keyword || '%'
          or coalesce(plan.provider_name, '') ilike '%' || v_keyword || '%')
    ), page as (
      select *, count(*) over() as total_count from filtered order by effective_from desc, plan_name, id
      offset v_from limit v_to - v_from + 1
    )
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', page.id, 'tenant_id', page.tenant_id,
      'plan_code', page.plan_code, 'plan_name', page.plan_name,
      'plan_type', page.plan_type, 'provider_name', page.provider_name,
      'enrollment_method', page.enrollment_method, 'coverage_scope', page.coverage_scope,
      'currency_code', page.currency_code, 'effective_from', page.effective_from,
      'effective_to', page.effective_to, 'status', page.status,
      'description', page.description, 'option_count', page.option_count,
      'active_enrollment_count', page.active_enrollment_count,
      'create_time', page.create_time, 'update_time', page.update_time
    )), '[]'::jsonb), coalesce(max(page.total_count), 0)
    into v_records, v_total from page;
  elsif p_kind = 'enrollment' then
    with filtered as (
      select enrollment.*,
        employee.employee_no, employee.employee_name, employee.job_title,
        organization.organization_name, position.position_name,
        plan.plan_code, plan.plan_name, plan.plan_type,
        option.option_code, option.option_name, option.coverage_level,
        life_event.event_type as life_event_type, life_event.event_date,
        case
          when enrollment.status = 'active' and enrollment.coverage_to is not null
            and enrollment.coverage_to < current_date then 'expired'
          when enrollment.status = 'active' and enrollment.coverage_to is not null
            and enrollment.coverage_to <= current_date + 30 then 'expiring'
          else 'clear'
        end as due_status
      from public.hr_employee_benefit_enrollment enrollment
      join public.mdm_employee employee on employee.id = enrollment.employee_id
        and employee.tenant_id = enrollment.tenant_id
      join public.hr_benefit_plan plan on plan.id = enrollment.plan_id
        and plan.tenant_id = enrollment.tenant_id
      join public.hr_benefit_option option on option.id = enrollment.option_id
        and option.tenant_id = enrollment.tenant_id
      left join public.hr_benefit_life_event life_event on life_event.id = enrollment.life_event_id
        and life_event.tenant_id = enrollment.tenant_id
      left join public.mdm_organization organization on organization.id = employee.organization_id
      left join public.mdm_position position on position.id = employee.position_id
        and position.tenant_id = employee.tenant_id
      where (p_tenant_id is null or enrollment.tenant_id = p_tenant_id)
        and (p_status is null or enrollment.status = p_status)
        and (p_plan_type is null or plan.plan_type = p_plan_type)
        and (v_keyword is null or enrollment.enrollment_no ilike '%' || v_keyword || '%'
          or employee.employee_no ilike '%' || v_keyword || '%'
          or employee.employee_name ilike '%' || v_keyword || '%'
          or plan.plan_name ilike '%' || v_keyword || '%')
    ), page as (
      select *, count(*) over() as total_count from filtered order by coverage_from desc, enrollment_no, id
      offset v_from limit v_to - v_from + 1
    )
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', page.id, 'tenant_id', page.tenant_id,
      'enrollment_no', page.enrollment_no, 'employee_id', page.employee_id,
      'employee', jsonb_build_object(
        'id', page.employee_id, 'employee_no', page.employee_no,
        'employee_name', page.employee_name, 'job_title', page.job_title,
        'organization_name', page.organization_name, 'position_name', page.position_name
      ),
      'plan_id', page.plan_id, 'plan', jsonb_build_object(
        'id', page.plan_id, 'plan_code', page.plan_code,
        'plan_name', page.plan_name, 'plan_type', page.plan_type
      ),
      'option_id', page.option_id, 'option', jsonb_build_object(
        'id', page.option_id, 'option_code', page.option_code,
        'option_name', page.option_name, 'coverage_level', page.coverage_level
      ),
      'life_event_id', page.life_event_id,
      'life_event', case when page.life_event_id is null then null else jsonb_build_object(
        'id', page.life_event_id, 'event_type', page.life_event_type,
        'event_date', page.event_date
      ) end,
      'coverage_from', page.coverage_from, 'coverage_to', page.coverage_to,
      'status', page.status, 'waiver_reason', page.waiver_reason,
      'employee_contribution', case when v_amount_visible then page.employee_contribution else null end,
      'employer_contribution', case when v_amount_visible then page.employer_contribution else null end,
      'currency_code', page.currency_code, 'payroll_sync_status', page.payroll_sync_status,
      'due_status', page.due_status, 'remark', page.remark,
      'approved_by', page.approved_by, 'approved_at', page.approved_at,
      'create_time', page.create_time, 'update_time', page.update_time
    )), '[]'::jsonb), coalesce(max(page.total_count), 0)
    into v_records, v_total from page;
  else
    with filtered as (
      select event.*, employee.employee_no, employee.employee_name,
        employee.job_title, organization.organization_name, position.position_name,
        case
          when event.status = 'open' and event.enrollment_window_end < current_date then 'expired'
          when event.status = 'open' and event.enrollment_window_end <= current_date + 7 then 'due_soon'
          else 'clear'
        end as due_status
      from public.hr_benefit_life_event event
      join public.mdm_employee employee on employee.id = event.employee_id
        and employee.tenant_id = event.tenant_id
      left join public.mdm_organization organization on organization.id = employee.organization_id
      left join public.mdm_position position on position.id = employee.position_id
        and position.tenant_id = employee.tenant_id
      where (p_tenant_id is null or event.tenant_id = p_tenant_id)
        and (p_status is null or event.status = p_status)
        and (v_keyword is null or employee.employee_no ilike '%' || v_keyword || '%'
          or employee.employee_name ilike '%' || v_keyword || '%'
          or event.event_type ilike '%' || v_keyword || '%')
    ), page as (
      select *, count(*) over() as total_count from filtered order by event_date desc, id
      offset v_from limit v_to - v_from + 1
    )
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', page.id, 'tenant_id', page.tenant_id,
      'employee_id', page.employee_id,
      'employee', jsonb_build_object(
        'id', page.employee_id, 'employee_no', page.employee_no,
        'employee_name', page.employee_name, 'job_title', page.job_title,
        'organization_name', page.organization_name, 'position_name', page.position_name
      ),
      'event_type', page.event_type, 'event_date', page.event_date,
      'enrollment_window_end', page.enrollment_window_end,
      'status', page.status,
      'evidence_urls', case when v_evidence_visible then page.evidence_urls else '[]'::jsonb end,
      'evidence_restricted', not v_evidence_visible,
      'remark', page.remark, 'processed_at', page.processed_at,
      'due_status', page.due_status, 'create_time', page.create_time,
      'update_time', page.update_time
    )), '[]'::jsonb), coalesce(max(page.total_count), 0)
    into v_records, v_total from page;
  end if;

  return jsonb_build_object('records', v_records, 'total', v_total,
    'amount_visible', v_amount_visible);
end
$$;


ALTER FUNCTION "public"."hr_list_benefit_records_secure"("p_kind" "text", "p_from" integer, "p_to" integer, "p_keyword" "text", "p_status" "text", "p_plan_type" "text", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_list_compensation_options_secure("text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_compensation_options_secure"("p_kind" "text", "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_tenant_id uuid := app_private.current_user_tenant_id();
begin
  if not app_private.can_execute_business_action(
    'HrCompensation', 'Hr:Compensation:View', null, false
  ) then
    raise exception 'Missing compensation view permission' using errcode = '42501';
  end if;
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;
  if p_tenant_id is null then return '[]'::jsonb; end if;

  if p_kind = 'employee' then
    return coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', employee_row.id,
        'code', employee_row.employee_no,
        'name', employee_row.employee_name,
        'organization_id', employee_row.organization_id,
        'organization_name', organization_row.organization_name,
        'grade_id', assignment_row.grade_id,
        'grade_name', grade_row.grade_name
      ) order by employee_row.employee_name)
      from public.mdm_employee employee_row
      left join public.mdm_organization organization_row on organization_row.id = employee_row.organization_id
      left join lateral (
        select assignment.grade_id
        from public.mdm_employee_assignment assignment
        where assignment.employee_id = employee_row.id
          and assignment.tenant_id = employee_row.tenant_id
          and assignment.primary_assignment
          and assignment.assignment_status = 'active'
          and assignment.effective_start <= current_date
          and coalesce(assignment.effective_end, 'infinity'::date) >= current_date
        order by assignment.effective_start desc limit 1
      ) assignment_row on true
      left join public.mdm_grade grade_row on grade_row.id = assignment_row.grade_id
      where employee_row.tenant_id = p_tenant_id
        and employee_row.employment_status in ('probation', 'active', 'leave')
    ), '[]'::jsonb);
  end if;
  if p_kind = 'plan' then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', id, 'code', plan_code, 'name', plan_name,
      'currency_code', currency_code, 'pay_frequency', pay_frequency
    ) order by sort, plan_name) from public.hr_compensation_plan
      where tenant_id = p_tenant_id and enabled), '[]'::jsonb);
  end if;
  if p_kind = 'component' then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', id, 'code', component_code, 'name', component_name,
      'category', category, 'amount_type', amount_type
    ) order by category, sort, component_name) from public.hr_pay_component
      where tenant_id = p_tenant_id and enabled), '[]'::jsonb);
  end if;
  if p_kind = 'grade' then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', id, 'code', grade_code, 'name', grade_name, 'level', grade_level
    ) order by grade_level, sort, grade_name) from public.mdm_grade
      where tenant_id = p_tenant_id and enabled), '[]'::jsonb);
  end if;
  raise exception '不支持的薪酬选项类型';
end;
$$;


ALTER FUNCTION "public"."hr_list_compensation_options_secure"("p_kind" "text", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_list_compensation_records_secure("text", integer, integer, "text", "text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_compensation_records_secure"("p_kind" "text", "p_from" integer DEFAULT 0, "p_to" integer DEFAULT 19, "p_keyword" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_offset integer := greatest(coalesce(p_from, 0), 0);
  v_limit integer := least(500, greatest(coalesce(p_to, 19) - greatest(coalesce(p_from, 0), 0) + 1, 1));
  v_keyword text := nullif(btrim(p_keyword), '');
  v_can_view_amount boolean;
  v_result jsonb;
begin
  if p_kind not in ('employee', 'plan', 'component', 'band') then
    raise exception '不支持的薪酬记录类型';
  end if;
  if not app_private.can_execute_business_action(
    'HrCompensation', 'Hr:Compensation:View', null, false
  ) then
    raise exception 'Missing compensation view permission' using errcode = '42501';
  end if;
  v_can_view_amount := app_private.can_execute_business_action(
    'HrCompensation', 'Hr:Compensation:Amount:View', null, false
  );
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;

  if p_kind = 'component' then
    with filtered as materialized (
      select component_row.*, tenant_row.tenant_code, tenant_row.tenant_name,
        (select count(*) from public.hr_compensation_plan_item item_row
          where item_row.component_id = component_row.id) as plan_count
      from public.hr_pay_component component_row
      join public.sys_tenant tenant_row on tenant_row.id = component_row.tenant_id
      where (p_tenant_id is null or component_row.tenant_id = p_tenant_id)
        and (p_status is null or component_row.enabled = (p_status = 'enabled'))
        and (v_keyword is null
          or component_row.component_code ilike '%' || v_keyword || '%'
          or component_row.component_name ilike '%' || v_keyword || '%')
    ), paged as (
      select * from filtered order by tenant_name, category, sort, component_name
      offset v_offset limit v_limit
    )
    select jsonb_build_object(
      'records', coalesce(jsonb_agg(
        (to_jsonb(paged) - 'tenant_code' - 'tenant_name') ||
        jsonb_build_object('tenant', jsonb_build_object(
          'id', tenant_id, 'tenant_code', tenant_code, 'tenant_name', tenant_name
        )) order by tenant_name, category, sort, component_name
      ), '[]'::jsonb),
      'total', (select count(*) from filtered),
      'amount_access', v_can_view_amount
    ) into v_result from paged;
    return coalesce(v_result, jsonb_build_object('records', '[]'::jsonb, 'total', 0, 'amount_access', v_can_view_amount));
  end if;

  if p_kind = 'plan' then
    with filtered as materialized (
      select plan_row.*, tenant_row.tenant_code, tenant_row.tenant_name,
        (select count(*) from public.hr_compensation_plan_item item_row
          where item_row.plan_id = plan_row.id) as component_count,
        (select count(*) from public.hr_employee_compensation compensation_row
          where compensation_row.plan_id = plan_row.id
            and compensation_row.status <> 'cancelled') as employee_count,
        coalesce((
          select jsonb_agg(jsonb_build_object(
            'id', item_row.id,
            'component_id', item_row.component_id,
            'component_code', component_row.component_code,
            'component_name', component_row.component_name,
            'category', component_row.category,
            'amount_type', component_row.amount_type,
            'default_amount', case when v_can_view_amount then to_jsonb(item_row.default_amount) else 'null'::jsonb end,
            'default_rate', case when v_can_view_amount then to_jsonb(item_row.default_rate) else 'null'::jsonb end,
            'required', item_row.required,
            'sort', item_row.sort
          ) order by item_row.sort, component_row.component_name)
          from public.hr_compensation_plan_item item_row
          join public.hr_pay_component component_row on component_row.id = item_row.component_id
          where item_row.plan_id = plan_row.id
        ), '[]'::jsonb) as items
      from public.hr_compensation_plan plan_row
      join public.sys_tenant tenant_row on tenant_row.id = plan_row.tenant_id
      where (p_tenant_id is null or plan_row.tenant_id = p_tenant_id)
        and (p_status is null or plan_row.enabled = (p_status = 'enabled'))
        and (v_keyword is null
          or plan_row.plan_code ilike '%' || v_keyword || '%'
          or plan_row.plan_name ilike '%' || v_keyword || '%')
    ), paged as (
      select * from filtered order by tenant_name, sort, plan_name
      offset v_offset limit v_limit
    )
    select jsonb_build_object(
      'records', coalesce(jsonb_agg(
        (to_jsonb(paged) - 'tenant_code' - 'tenant_name') ||
        jsonb_build_object('tenant', jsonb_build_object(
          'id', tenant_id, 'tenant_code', tenant_code, 'tenant_name', tenant_name
        )) order by tenant_name, sort, plan_name
      ), '[]'::jsonb),
      'total', (select count(*) from filtered),
      'amount_access', v_can_view_amount
    ) into v_result from paged;
    return coalesce(v_result, jsonb_build_object('records', '[]'::jsonb, 'total', 0, 'amount_access', v_can_view_amount));
  end if;

  if p_kind = 'band' then
    with filtered as materialized (
      select band_row.*, tenant_row.tenant_code, tenant_row.tenant_name,
        grade_row.grade_code, grade_row.grade_name, grade_row.grade_level,
        case
          when band_row.status = 'cancelled' then 'cancelled'
          when band_row.status = 'draft' then 'draft'
          when band_row.effective_from > current_date then 'scheduled'
          when band_row.effective_to is not null and band_row.effective_to < current_date then 'expired'
          else 'active'
        end as lifecycle_status
      from public.hr_salary_band band_row
      join public.mdm_grade grade_row
        on grade_row.id = band_row.grade_id and grade_row.tenant_id = band_row.tenant_id
      join public.sys_tenant tenant_row on tenant_row.id = band_row.tenant_id
      where (p_tenant_id is null or band_row.tenant_id = p_tenant_id)
        and (p_status is null or case
          when band_row.status = 'cancelled' then 'cancelled'
          when band_row.status = 'draft' then 'draft'
          when band_row.effective_from > current_date then 'scheduled'
          when band_row.effective_to is not null and band_row.effective_to < current_date then 'expired'
          else 'active' end = p_status)
        and (v_keyword is null
          or grade_row.grade_code ilike '%' || v_keyword || '%'
          or grade_row.grade_name ilike '%' || v_keyword || '%')
    ), paged as (
      select * from filtered order by tenant_name, grade_level, effective_from desc
      offset v_offset limit v_limit
    )
    select jsonb_build_object(
      'records', coalesce(jsonb_agg(
        (to_jsonb(paged)
          - 'tenant_code' - 'tenant_name' - 'grade_code' - 'grade_name' - 'grade_level'
          - case when v_can_view_amount then '__keep_amounts__' else 'minimum_amount' end
          - case when v_can_view_amount then '__keep_midpoint__' else 'midpoint_amount' end
          - case when v_can_view_amount then '__keep_maximum__' else 'maximum_amount' end) ||
        jsonb_build_object(
          'tenant', jsonb_build_object('id', tenant_id, 'tenant_code', tenant_code, 'tenant_name', tenant_name),
          'grade', jsonb_build_object('id', grade_id, 'grade_code', grade_code, 'grade_name', grade_name, 'grade_level', grade_level),
          'minimum_amount', case when v_can_view_amount then to_jsonb(minimum_amount) else to_jsonb('***'::text) end,
          'midpoint_amount', case when v_can_view_amount then to_jsonb(midpoint_amount) else to_jsonb('***'::text) end,
          'maximum_amount', case when v_can_view_amount then to_jsonb(maximum_amount) else to_jsonb('***'::text) end
        ) order by tenant_name, grade_level, effective_from desc
      ), '[]'::jsonb),
      'total', (select count(*) from filtered),
      'amount_access', v_can_view_amount
    ) into v_result from paged;
    return coalesce(v_result, jsonb_build_object('records', '[]'::jsonb, 'total', 0, 'amount_access', v_can_view_amount));
  end if;

  with filtered as materialized (
    select compensation_row.*, tenant_row.tenant_code, tenant_row.tenant_name,
      employee_row.employee_no, employee_row.employee_name, employee_row.organization_id,
      organization_row.organization_code, organization_row.organization_name,
      plan_row.plan_code, plan_row.plan_name,
      grade_row.grade_code, grade_row.grade_name, grade_row.grade_level,
      case
        when compensation_row.status = 'cancelled' then 'cancelled'
        when compensation_row.status = 'draft' then 'draft'
        when compensation_row.effective_from > current_date then 'scheduled'
        when compensation_row.effective_to is not null and compensation_row.effective_to < current_date then 'expired'
        else 'active'
      end as lifecycle_status,
      active_band.minimum_amount as band_minimum,
      active_band.maximum_amount as band_maximum,
      case
        when active_band.id is null then 'unconfigured'
        when compensation_row.base_amount < active_band.minimum_amount then 'below'
        when compensation_row.base_amount > active_band.maximum_amount then 'above'
        else 'within'
      end as range_status,
      coalesce((
        select jsonb_agg(jsonb_build_object(
          'id', item_row.id,
          'component_id', item_row.component_id,
          'component_code', component_row.component_code,
          'component_name', component_row.component_name,
          'category', component_row.category,
          'amount_type', component_row.amount_type,
          'amount', case when v_can_view_amount then to_jsonb(item_row.amount) else 'null'::jsonb end,
          'rate', case when v_can_view_amount then to_jsonb(item_row.rate) else 'null'::jsonb end,
          'source', item_row.source
        ) order by component_row.sort, component_row.component_name)
        from public.hr_employee_compensation_item item_row
        join public.hr_pay_component component_row on component_row.id = item_row.component_id
        where item_row.compensation_id = compensation_row.id
      ), '[]'::jsonb) as items
    from public.hr_employee_compensation compensation_row
    join public.mdm_employee employee_row
      on employee_row.id = compensation_row.employee_id
     and employee_row.tenant_id = compensation_row.tenant_id
    left join public.mdm_organization organization_row on organization_row.id = employee_row.organization_id
    join public.hr_compensation_plan plan_row
      on plan_row.id = compensation_row.plan_id
     and plan_row.tenant_id = compensation_row.tenant_id
    left join public.mdm_grade grade_row
      on grade_row.id = compensation_row.grade_id
     and grade_row.tenant_id = compensation_row.tenant_id
    join public.sys_tenant tenant_row on tenant_row.id = compensation_row.tenant_id
    left join lateral (
      select band_row.* from public.hr_salary_band band_row
      where band_row.tenant_id = compensation_row.tenant_id
        and band_row.grade_id = compensation_row.grade_id
        and band_row.currency_code = compensation_row.currency_code
        and band_row.status = 'approved'
        and band_row.effective_from <= compensation_row.effective_from
        and coalesce(band_row.effective_to, 'infinity'::date) >= compensation_row.effective_from
      order by band_row.effective_from desc limit 1
    ) active_band on true
    where (p_tenant_id is null or compensation_row.tenant_id = p_tenant_id)
      and (p_status is null or case
        when compensation_row.status = 'cancelled' then 'cancelled'
        when compensation_row.status = 'draft' then 'draft'
        when compensation_row.effective_from > current_date then 'scheduled'
        when compensation_row.effective_to is not null and compensation_row.effective_to < current_date then 'expired'
        else 'active' end = p_status)
      and (v_keyword is null
        or employee_row.employee_no ilike '%' || v_keyword || '%'
        or employee_row.employee_name ilike '%' || v_keyword || '%'
        or plan_row.plan_name ilike '%' || v_keyword || '%')
  ), paged as (
    select * from filtered order by tenant_name, effective_from desc, employee_name
    offset v_offset limit v_limit
  )
  select jsonb_build_object(
    'records', coalesce(jsonb_agg(
      (to_jsonb(paged)
        - 'tenant_code' - 'tenant_name' - 'employee_no' - 'employee_name'
        - 'organization_code' - 'organization_name' - 'plan_code' - 'plan_name'
        - 'grade_code' - 'grade_name' - 'grade_level' - 'band_minimum' - 'band_maximum'
        - 'base_amount') ||
      jsonb_build_object(
        'tenant', jsonb_build_object('id', tenant_id, 'tenant_code', tenant_code, 'tenant_name', tenant_name),
        'employee', jsonb_build_object('id', employee_id, 'employee_no', employee_no, 'employee_name', employee_name),
        'organization', case when organization_id is null then null else jsonb_build_object(
          'id', organization_id, 'organization_code', organization_code, 'organization_name', organization_name
        ) end,
        'plan', jsonb_build_object('id', plan_id, 'plan_code', plan_code, 'plan_name', plan_name),
        'grade', case when grade_id is null then null else jsonb_build_object(
          'id', grade_id, 'grade_code', grade_code, 'grade_name', grade_name, 'grade_level', grade_level
        ) end,
        'base_amount', case when v_can_view_amount then to_jsonb(base_amount) else to_jsonb('***'::text) end,
        'band_minimum', case when not v_can_view_amount or band_minimum is null then null else to_jsonb(band_minimum) end,
        'band_maximum', case when not v_can_view_amount or band_maximum is null then null else to_jsonb(band_maximum) end
      ) order by tenant_name, effective_from desc, employee_name
    ), '[]'::jsonb),
    'total', (select count(*) from filtered),
    'amount_access', v_can_view_amount
  ) into v_result from paged;
  return coalesce(v_result, jsonb_build_object('records', '[]'::jsonb, 'total', 0, 'amount_access', v_can_view_amount));
end;
$$;


ALTER FUNCTION "public"."hr_list_compensation_records_secure"("p_kind" "text", "p_from" integer, "p_to" integer, "p_keyword" "text", "p_status" "text", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_list_compensation_review_options_secure("text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_compensation_review_options_secure"("p_kind" "text", "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
begin
  if p_kind not in ('cycle', 'organization') then raise exception '不支持的调薪选项类型'; end if;
  if auth.uid() is null or not app_private.can_execute_business_action(
    'HrCompensationReview', 'Hr:CompensationReview:View', null, false
  ) then
    raise exception '当前账号没有查看调薪复核的权限' using errcode = '42501';
  end if;
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;

  if p_kind = 'cycle' then
    return (
      select coalesce(jsonb_agg(jsonb_build_object(
        'id', cycle_row.id,
        'tenant_id', cycle_row.tenant_id,
        'code', cycle_row.cycle_code,
        'name', cycle_row.cycle_name,
        'status', cycle_row.status,
        'effective_date', cycle_row.effective_date
      ) order by cycle_row.effective_date desc), '[]'::jsonb)
      from public.hr_compensation_review_cycle cycle_row
      where (p_tenant_id is null or cycle_row.tenant_id = p_tenant_id)
        and cycle_row.status <> 'cancelled'
    );
  end if;

  return (
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', organization.id,
      'tenant_id', organization.tenant_id,
      'code', organization.organization_code,
      'name', organization.organization_name
    ) order by organization.sort, organization.organization_name), '[]'::jsonb)
    from public.mdm_organization organization
    where (p_tenant_id is null or organization.tenant_id = p_tenant_id)
      and organization.status = '1'
  );
end;
$$;


ALTER FUNCTION "public"."hr_list_compensation_review_options_secure"("p_kind" "text", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_list_compensation_review_records_secure("text", integer, integer, "text", "text", "uuid", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_compensation_review_records_secure"("p_kind" "text", "p_from" integer DEFAULT 0, "p_to" integer DEFAULT 19, "p_keyword" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_cycle_id" "uuid" DEFAULT NULL::"uuid", "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    SET "TimeZone" TO 'Asia/Shanghai'
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_offset integer := greatest(coalesce(p_from, 0), 0);
  v_limit integer := least(500, greatest(coalesce(p_to, 19) - greatest(coalesce(p_from, 0), 0) + 1, 1));
  v_keyword text := nullif(btrim(p_keyword), '');
  v_amount_access boolean;
  v_records jsonb := '[]'::jsonb;
  v_total integer := 0;
begin
  if p_kind not in ('cycle', 'item', 'budget') then
    raise exception '不支持的调薪复核记录类型';
  end if;
  if auth.uid() is null or not app_private.can_execute_business_action(
    'HrCompensationReview', 'Hr:CompensationReview:View', null, false
  ) then
    raise exception '当前账号没有查看调薪复核的权限' using errcode = '42501';
  end if;
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;
  v_amount_access := app_private.can_execute_business_action(
    'HrCompensationReview', 'Hr:CompensationReview:Amount:View', null, false
  );

  if p_kind = 'cycle' then
    select count(*)::integer into v_total
    from public.hr_compensation_review_cycle cycle_row
    left join public.mdm_organization organization
      on organization.id = cycle_row.scope_organization_id
     and organization.tenant_id = cycle_row.tenant_id
    where (p_tenant_id is null or cycle_row.tenant_id = p_tenant_id)
      and (p_status is null or p_status = '' or cycle_row.status = p_status)
      and (v_keyword is null or cycle_row.cycle_code ilike '%' || v_keyword || '%'
        or cycle_row.cycle_name ilike '%' || v_keyword || '%'
        or organization.organization_name ilike '%' || v_keyword || '%');

    select coalesce(jsonb_agg(row_data order by effective_date desc, create_time desc), '[]'::jsonb)
    into v_records
    from (
      select
        cycle_row.effective_date,
        cycle_row.create_time,
        jsonb_build_object(
          'id', cycle_row.id,
          'tenant_id', cycle_row.tenant_id,
          'cycle_code', cycle_row.cycle_code,
          'cycle_name', cycle_row.cycle_name,
          'review_year', cycle_row.review_year,
          'effective_date', cycle_row.effective_date,
          'recommendation_due_date', cycle_row.recommendation_due_date,
          'calibration_due_date', cycle_row.calibration_due_date,
          'scope_organization_id', cycle_row.scope_organization_id,
          'scope_organization_name', organization.organization_name,
          'currency_code', cycle_row.currency_code,
          'default_budget_percent', cycle_row.default_budget_percent,
          'guideline_min_percent', cycle_row.guideline_min_percent,
          'guideline_max_percent', cycle_row.guideline_max_percent,
          'status', cycle_row.status,
          'description', cycle_row.description,
          'decision_note', cycle_row.decision_note,
          'employee_count', (select count(*) from public.hr_compensation_review_item item where item.cycle_id = cycle_row.id),
          'pending_count', (select count(*) from public.hr_compensation_review_item item where item.cycle_id = cycle_row.id and item.status = 'pending'),
          'budget_amount', case when v_amount_access then to_jsonb((select coalesce(sum(budget_amount), 0) from public.hr_compensation_review_budget budget where budget.cycle_id = cycle_row.id)) else to_jsonb('***'::text) end,
          'proposed_increase_amount', case when v_amount_access then to_jsonb((select coalesce(sum(greatest(proposed_base_amount - current_base_amount, 0)), 0) from public.hr_compensation_review_item item where item.cycle_id = cycle_row.id and item.status <> 'excluded')) else to_jsonb('***'::text) end,
          'create_time', cycle_row.create_time,
          'update_time', cycle_row.update_time
        ) as row_data
      from public.hr_compensation_review_cycle cycle_row
      left join public.mdm_organization organization
        on organization.id = cycle_row.scope_organization_id
       and organization.tenant_id = cycle_row.tenant_id
      where (p_tenant_id is null or cycle_row.tenant_id = p_tenant_id)
        and (p_status is null or p_status = '' or cycle_row.status = p_status)
        and (v_keyword is null or cycle_row.cycle_code ilike '%' || v_keyword || '%'
          or cycle_row.cycle_name ilike '%' || v_keyword || '%'
          or organization.organization_name ilike '%' || v_keyword || '%')
      order by cycle_row.effective_date desc, cycle_row.create_time desc
      offset v_offset limit v_limit
    ) page;
  elsif p_kind = 'budget' then
    select count(*)::integer into v_total
    from public.hr_compensation_review_budget budget
    join public.hr_compensation_review_cycle cycle_row
      on cycle_row.id = budget.cycle_id and cycle_row.tenant_id = budget.tenant_id
    left join public.mdm_organization organization
      on organization.id = budget.organization_id and organization.tenant_id = budget.tenant_id
    where (p_tenant_id is null or budget.tenant_id = p_tenant_id)
      and (p_cycle_id is null or budget.cycle_id = p_cycle_id)
      and (v_keyword is null or organization.organization_name ilike '%' || v_keyword || '%'
        or cycle_row.cycle_name ilike '%' || v_keyword || '%');

    select coalesce(jsonb_agg(row_data order by organization_name), '[]'::jsonb)
    into v_records
    from (
      select
        coalesce(organization.organization_name, '未分配组织') organization_name,
        jsonb_build_object(
          'id', budget.id,
          'tenant_id', budget.tenant_id,
          'cycle_id', budget.cycle_id,
          'cycle_name', cycle_row.cycle_name,
          'organization_id', budget.organization_id,
          'organization_name', coalesce(organization.organization_name, '未分配组织'),
          'budget_amount', case when v_amount_access then to_jsonb(budget.budget_amount) else to_jsonb('***'::text) end,
          'used_amount', case when v_amount_access then to_jsonb(coalesce(usage.used_amount, 0)) else to_jsonb('***'::text) end,
          'remaining_amount', case when v_amount_access then to_jsonb(budget.budget_amount - coalesce(usage.used_amount, 0)) else to_jsonb('***'::text) end,
          'utilization_percent', case when not v_amount_access then null when budget.budget_amount = 0 and coalesce(usage.used_amount, 0) = 0 then 0 when budget.budget_amount = 0 then 100 else round(coalesce(usage.used_amount, 0) * 100 / budget.budget_amount, 1) end,
          'employee_count', coalesce(usage.employee_count, 0),
          'source', budget.source,
          'note', budget.note,
          'cycle_status', cycle_row.status,
          'create_time', budget.create_time,
          'update_time', budget.update_time
        ) row_data
      from public.hr_compensation_review_budget budget
      join public.hr_compensation_review_cycle cycle_row
        on cycle_row.id = budget.cycle_id and cycle_row.tenant_id = budget.tenant_id
      left join public.mdm_organization organization
        on organization.id = budget.organization_id and organization.tenant_id = budget.tenant_id
      left join lateral (
        select
          count(*)::integer employee_count,
          coalesce(sum(greatest(item.proposed_base_amount - item.current_base_amount, 0)), 0) used_amount
        from public.hr_compensation_review_item item
        where item.cycle_id = budget.cycle_id
          and item.organization_id is not distinct from budget.organization_id
          and item.status <> 'excluded'
      ) usage on true
      where (p_tenant_id is null or budget.tenant_id = p_tenant_id)
        and (p_cycle_id is null or budget.cycle_id = p_cycle_id)
        and (v_keyword is null or organization.organization_name ilike '%' || v_keyword || '%'
          or cycle_row.cycle_name ilike '%' || v_keyword || '%')
      order by coalesce(organization.organization_name, '未分配组织')
      offset v_offset limit v_limit
    ) page;
  else
    select count(*)::integer into v_total
    from public.hr_compensation_review_item item
    join public.mdm_employee employee on employee.id = item.employee_id and employee.tenant_id = item.tenant_id
    left join public.mdm_organization organization on organization.id = item.organization_id and organization.tenant_id = item.tenant_id
    where (p_tenant_id is null or item.tenant_id = p_tenant_id)
      and (p_cycle_id is null or item.cycle_id = p_cycle_id)
      and (p_status is null or p_status = '' or item.status = p_status)
      and (v_keyword is null or employee.employee_name ilike '%' || v_keyword || '%'
        or employee.employee_no ilike '%' || v_keyword || '%'
        or organization.organization_name ilike '%' || v_keyword || '%');

    select coalesce(jsonb_agg(row_data order by organization_name, employee_name), '[]'::jsonb)
    into v_records
    from (
      select
        coalesce(organization.organization_name, '未分配组织') organization_name,
        employee.employee_name,
        jsonb_build_object(
          'id', item.id,
          'tenant_id', item.tenant_id,
          'cycle_id', item.cycle_id,
          'cycle_name', cycle_row.cycle_name,
          'cycle_status', cycle_row.status,
          'employee_id', item.employee_id,
          'employee_no', employee.employee_no,
          'employee_name', employee.employee_name,
          'organization_id', item.organization_id,
          'organization_name', coalesce(organization.organization_name, '未分配组织'),
          'current_compensation_id', item.current_compensation_id,
          'current_grade_id', item.current_grade_id,
          'grade_name', grade.grade_name,
          'current_base_amount', case when v_amount_access then to_jsonb(item.current_base_amount) else to_jsonb('***'::text) end,
          'proposed_base_amount', case when v_amount_access then to_jsonb(item.proposed_base_amount) else to_jsonb('***'::text) end,
          'increase_amount', case when v_amount_access then to_jsonb(item.proposed_base_amount - item.current_base_amount) else to_jsonb('***'::text) end,
          'increase_percent', case when v_amount_access and item.current_base_amount > 0 then round((item.proposed_base_amount - item.current_base_amount) * 100 / item.current_base_amount, 2) else null end,
          'performance_level', item.performance_level,
          'status', item.status,
          'recommendation_reason', item.recommendation_reason,
          'recommended_by', item.recommended_by,
          'recommended_at', item.recommended_at,
          'calibration_note', item.calibration_note,
          'calibrated_by', item.calibrated_by,
          'calibrated_at', item.calibrated_at,
          'exclusion_reason', item.exclusion_reason,
          'new_compensation_id', item.new_compensation_id,
          'out_of_guideline', case when item.current_base_amount = 0 then false else round((item.proposed_base_amount - item.current_base_amount) * 100 / item.current_base_amount, 4) not between cycle_row.guideline_min_percent and cycle_row.guideline_max_percent end,
          'create_time', item.create_time,
          'update_time', item.update_time
        ) row_data
      from public.hr_compensation_review_item item
      join public.hr_compensation_review_cycle cycle_row on cycle_row.id = item.cycle_id and cycle_row.tenant_id = item.tenant_id
      join public.mdm_employee employee on employee.id = item.employee_id and employee.tenant_id = item.tenant_id
      left join public.mdm_organization organization on organization.id = item.organization_id and organization.tenant_id = item.tenant_id
      left join public.mdm_grade grade on grade.id = item.current_grade_id and grade.tenant_id = item.tenant_id
      where (p_tenant_id is null or item.tenant_id = p_tenant_id)
        and (p_cycle_id is null or item.cycle_id = p_cycle_id)
        and (p_status is null or p_status = '' or item.status = p_status)
        and (v_keyword is null or employee.employee_name ilike '%' || v_keyword || '%'
          or employee.employee_no ilike '%' || v_keyword || '%'
          or organization.organization_name ilike '%' || v_keyword || '%')
      order by coalesce(organization.organization_name, '未分配组织'), employee.employee_name
      offset v_offset limit v_limit
    ) page;
  end if;

  return jsonb_build_object(
    'records', v_records,
    'total', v_total,
    'amount_access', v_amount_access
  );
end;
$$;


ALTER FUNCTION "public"."hr_list_compensation_review_records_secure"("p_kind" "text", "p_from" integer, "p_to" integer, "p_keyword" "text", "p_status" "text", "p_cycle_id" "uuid", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_list_compliance_records_secure("text", integer, integer, "text", "text", "text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_compliance_records_secure"("p_kind" "text", "p_from" integer DEFAULT 0, "p_to" integer DEFAULT 19, "p_keyword" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_risk_status" "text" DEFAULT NULL::"text", "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_offset integer := greatest(coalesce(p_from, 0), 0);
  v_limit integer := least(500,
    greatest(coalesce(p_to, 19) - greatest(coalesce(p_from, 0), 0) + 1, 1));
  v_keyword text := nullif(btrim(p_keyword), '');
  v_result jsonb;
begin
  if p_kind not in ('risk', 'contract', 'qualification') then
    raise exception '不支持的用工合规记录类型';
  end if;
  if not app_private.can_execute_business_action(
    'HrCompliance', 'Hr:Compliance:View', null, false
  ) then
    raise exception '当前账号没有查看用工合规中心的权限' using errcode = '42501';
  end if;
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;

  if p_kind = 'contract' then
    with enriched as materialized (
      select contract.*,
        case
          when contract.contract_status in ('active', 'renewing')
            and contract.end_date < current_date then 'expired'
          else contract.contract_status
        end as effective_status,
        case
          when contract.contract_status not in ('active', 'renewing') or contract.end_date is null then 'clear'
          when contract.end_date < current_date then 'overdue'
          when contract.end_date <= current_date + 7 then 'critical'
          when contract.end_date <= current_date + 30 then 'due_soon'
          when contract.end_date <= current_date + contract.renewal_reminder_days then 'watch'
          else 'clear'
        end as risk_status,
        case when contract.end_date is null then null
          else contract.end_date - current_date end as days_remaining,
        previous.contract_no as previous_contract_no,
        jsonb_build_object(
          'id', employee.id, 'employee_no', employee.employee_no,
          'employee_name', employee.employee_name, 'job_title', employee.job_title,
          'organization_name', organization.organization_name,
          'position_name', position.position_name
        ) as employee,
        case when owner.id is null then null else jsonb_build_object(
          'id', owner.id, 'employee_no', owner.employee_no,
          'employee_name', owner.employee_name, 'job_title', owner.job_title
        ) end as renewal_owner
      from public.hr_employee_contract contract
      join public.mdm_employee employee
        on employee.id = contract.employee_id and employee.tenant_id = contract.tenant_id
      left join public.mdm_organization organization
        on organization.id = employee.organization_id
      left join public.mdm_position position on position.id = employee.position_id
      left join public.hr_employee_contract previous
        on previous.id = contract.previous_contract_id and previous.tenant_id = contract.tenant_id
      left join public.mdm_employee owner
        on owner.id = contract.renewal_owner_id and owner.tenant_id = contract.tenant_id
      where (p_tenant_id is null or contract.tenant_id = p_tenant_id)
    ), filtered as materialized (
      select * from enriched
      where (p_status is null or effective_status = p_status)
        and (p_risk_status is null or risk_status = p_risk_status)
        and (
          v_keyword is null
          or contract_no ilike '%' || v_keyword || '%'
          or employee->>'employee_name' ilike '%' || v_keyword || '%'
          or employee->>'employee_no' ilike '%' || v_keyword || '%'
          or employee->>'job_title' ilike '%' || v_keyword || '%'
        )
    ), paged as (
      select * from filtered
      order by case risk_status when 'overdue' then 1 when 'critical' then 2
        when 'due_soon' then 3 when 'watch' then 4 else 5 end,
        end_date nulls last, update_time desc
      offset v_offset limit v_limit
    )
    select jsonb_build_object(
      'records', coalesce(jsonb_agg(
        (to_jsonb(paged) - 'effective_status')
          || jsonb_build_object('contract_status', paged.effective_status)
        order by case paged.risk_status when 'overdue' then 1 when 'critical' then 2
          when 'due_soon' then 3 when 'watch' then 4 else 5 end,
          paged.end_date nulls last, paged.update_time desc
      ), '[]'::jsonb),
      'total', (select count(*) from filtered)
    ) into v_result from paged;
    return coalesce(v_result, jsonb_build_object('records', '[]'::jsonb, 'total', 0));
  end if;

  if p_kind = 'qualification' then
    with enriched as materialized (
      select qualification.*,
        case
          when qualification.status <> 'revoked' and qualification.expiry_date < current_date
            then 'expired'
          when qualification.status <> 'revoked'
            and qualification.expiry_date <= current_date + qualification.reminder_days
            then 'expiring'
          else qualification.status
        end as effective_status,
        case
          when qualification.status = 'revoked' or qualification.expiry_date is null then 'clear'
          when qualification.expiry_date < current_date then 'overdue'
          when qualification.expiry_date <= current_date + 7 then 'critical'
          when qualification.expiry_date <= current_date + 30 then 'due_soon'
          when qualification.expiry_date <= current_date + qualification.reminder_days then 'watch'
          else 'clear'
        end as risk_status,
        case when qualification.expiry_date is null then null
          else qualification.expiry_date - current_date end as days_remaining,
        jsonb_build_object(
          'id', employee.id, 'employee_no', employee.employee_no,
          'employee_name', employee.employee_name, 'job_title', employee.job_title,
          'organization_name', organization.organization_name,
          'position_name', position.position_name
        ) as employee,
        case when responsible.id is null then null else jsonb_build_object(
          'id', responsible.id, 'employee_no', responsible.employee_no,
          'employee_name', responsible.employee_name, 'job_title', responsible.job_title
        ) end as responsible_employee,
        case when verifier.id is null then null else jsonb_build_object(
          'id', verifier.id, 'employee_no', verifier.employee_no,
          'employee_name', verifier.employee_name, 'job_title', verifier.job_title
        ) end as verified_by_employee
      from public.hr_employee_qualification qualification
      join public.mdm_employee employee
        on employee.id = qualification.employee_id and employee.tenant_id = qualification.tenant_id
      left join public.mdm_organization organization
        on organization.id = employee.organization_id
      left join public.mdm_position position on position.id = employee.position_id
      left join public.mdm_employee responsible
        on responsible.id = qualification.responsible_employee_id
        and responsible.tenant_id = qualification.tenant_id
      left join public.mdm_employee verifier
        on verifier.id = qualification.verified_by_employee_id
        and verifier.tenant_id = qualification.tenant_id
      where (p_tenant_id is null or qualification.tenant_id = p_tenant_id)
    ), filtered as materialized (
      select * from enriched
      where (p_status is null or effective_status = p_status or verification_status = p_status)
        and (p_risk_status is null or risk_status = p_risk_status)
        and (
          v_keyword is null
          or qualification_name ilike '%' || v_keyword || '%'
          or certificate_no ilike '%' || v_keyword || '%'
          or issuer ilike '%' || v_keyword || '%'
          or employee->>'employee_name' ilike '%' || v_keyword || '%'
          or employee->>'employee_no' ilike '%' || v_keyword || '%'
        )
    ), paged as (
      select * from filtered
      order by case risk_status when 'overdue' then 1 when 'critical' then 2
        when 'due_soon' then 3 when 'watch' then 4 else 5 end,
        expiry_date nulls last, update_time desc
      offset v_offset limit v_limit
    )
    select jsonb_build_object(
      'records', coalesce(jsonb_agg(
        (to_jsonb(paged) - 'effective_status')
          || jsonb_build_object('status', paged.effective_status)
        order by case paged.risk_status when 'overdue' then 1 when 'critical' then 2
          when 'due_soon' then 3 when 'watch' then 4 else 5 end,
          paged.expiry_date nulls last, paged.update_time desc
      ), '[]'::jsonb),
      'total', (select count(*) from filtered)
    ) into v_result from paged;
    return coalesce(v_result, jsonb_build_object('records', '[]'::jsonb, 'total', 0));
  end if;

  with risks as materialized (
    select 'contract'::text as entity_type, contract.id as record_id,
      contract.tenant_id, contract.contract_no as subject,
      contract.contract_status as status,
      contract.end_date as due_date,
      contract.end_date - current_date as days_remaining,
      case
        when contract.end_date < current_date then 'overdue'
        when contract.end_date <= current_date + 7 then 'critical'
        when contract.end_date <= current_date + 30 then 'due_soon'
        else 'watch'
      end as risk_status,
      '劳动合同到期处置'::text as risk_type,
      case when owner.id is null then null else jsonb_build_object(
        'id', owner.id, 'employee_no', owner.employee_no,
        'employee_name', owner.employee_name, 'job_title', owner.job_title
      ) end as owner,
      jsonb_build_object(
        'id', employee.id, 'employee_no', employee.employee_no,
        'employee_name', employee.employee_name, 'job_title', employee.job_title,
        'organization_name', organization.organization_name,
        'position_name', position.position_name
      ) as employee,
      concat(contract.contract_no, ' · ',
        case when contract.renewal_decision = 'pending' then '等待续签决策'
          else '尚未启动续签处置' end) as description
    from public.hr_employee_contract contract
    join public.mdm_employee employee
      on employee.id = contract.employee_id and employee.tenant_id = contract.tenant_id
    left join public.mdm_organization organization on organization.id = employee.organization_id
    left join public.mdm_position position on position.id = employee.position_id
    left join public.mdm_employee owner
      on owner.id = contract.renewal_owner_id and owner.tenant_id = contract.tenant_id
    where contract.contract_status in ('active', 'renewing')
      and contract.end_date is not null
      and contract.end_date <= current_date + contract.renewal_reminder_days
      and (p_tenant_id is null or contract.tenant_id = p_tenant_id)
    union all
    select 'qualification', qualification.id, qualification.tenant_id,
      qualification.qualification_name, qualification.status,
      qualification.expiry_date, qualification.expiry_date - current_date,
      case
        when qualification.expiry_date < current_date then 'overdue'
        when qualification.expiry_date <= current_date + 7 then 'critical'
        when qualification.expiry_date <= current_date + 30 then 'due_soon'
        else 'watch'
      end,
      '员工资质到期处置',
      case when responsible.id is null then null else jsonb_build_object(
        'id', responsible.id, 'employee_no', responsible.employee_no,
        'employee_name', responsible.employee_name, 'job_title', responsible.job_title
      ) end,
      jsonb_build_object(
        'id', employee.id, 'employee_no', employee.employee_no,
        'employee_name', employee.employee_name, 'job_title', employee.job_title,
        'organization_name', organization.organization_name,
        'position_name', position.position_name
      ),
      concat(coalesce(qualification.certificate_no, '无证书编号'), ' · ',
        case when qualification.verification_status = 'verified' then '已核验'
          else '待完成真实性核验' end)
    from public.hr_employee_qualification qualification
    join public.mdm_employee employee
      on employee.id = qualification.employee_id and employee.tenant_id = qualification.tenant_id
    left join public.mdm_organization organization on organization.id = employee.organization_id
    left join public.mdm_position position on position.id = employee.position_id
    left join public.mdm_employee responsible
      on responsible.id = qualification.responsible_employee_id
      and responsible.tenant_id = qualification.tenant_id
    where qualification.status <> 'revoked'
      and qualification.expiry_date is not null
      and qualification.expiry_date <= current_date + qualification.reminder_days
      and (p_tenant_id is null or qualification.tenant_id = p_tenant_id)
  ), filtered as materialized (
    select * from risks
    where (p_status is null or entity_type = p_status)
      and (p_risk_status is null or risk_status = p_risk_status)
      and (
        v_keyword is null
        or subject ilike '%' || v_keyword || '%'
        or risk_type ilike '%' || v_keyword || '%'
        or employee->>'employee_name' ilike '%' || v_keyword || '%'
        or employee->>'employee_no' ilike '%' || v_keyword || '%'
      )
  ), paged as (
    select * from filtered
    order by case risk_status when 'overdue' then 1 when 'critical' then 2
      when 'due_soon' then 3 else 4 end, due_date, subject
    offset v_offset limit v_limit
  )
  select jsonb_build_object(
    'records', coalesce(jsonb_agg(to_jsonb(paged)
      order by case paged.risk_status when 'overdue' then 1 when 'critical' then 2
        when 'due_soon' then 3 else 4 end, paged.due_date, paged.subject), '[]'::jsonb),
    'total', (select count(*) from filtered)
  ) into v_result from paged;
  return coalesce(v_result, jsonb_build_object('records', '[]'::jsonb, 'total', 0));
end
$$;


ALTER FUNCTION "public"."hr_list_compliance_records_secure"("p_kind" "text", "p_from" integer, "p_to" integer, "p_keyword" "text", "p_status" "text", "p_risk_status" "text", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_list_contingent_workforce_options_secure("text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_contingent_workforce_options_secure"("p_kind" "text", "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_result jsonb := '[]'::jsonb;
begin
  if p_kind not in ('vendor', 'worker', 'organization', 'position', 'sponsor', 'engagement') then
    raise exception '不支持的外部用工选项类型';
  end if;
  if auth.uid() is null or not app_private.can_execute_business_action(
    'HrContingentWorkforce', 'Hr:ContingentWorkforce:View', null, false
  ) then
    raise exception '当前账号没有查看外部用工的权限' using errcode = '42501';
  end if;
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;

  if p_kind = 'vendor' then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', vendor.id, 'code', vendor.vendor_code, 'name', vendor.vendor_name,
      'status', vendor.status, 'extra', vendor.compliance_status
    ) order by vendor.vendor_name), '[]'::jsonb)
    into v_result
    from public.mdm_external_vendor vendor
    where (p_tenant_id is null or vendor.tenant_id = p_tenant_id)
      and vendor.status <> 'inactive';
  elsif p_kind = 'worker' then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', worker.id, 'code', worker.worker_no, 'name', worker.worker_name,
      'status', worker.status, 'extra', worker.worker_type, 'vendor_id', worker.vendor_id
    ) order by worker.worker_name), '[]'::jsonb)
    into v_result
    from public.hr_external_worker worker
    where (p_tenant_id is null or worker.tenant_id = p_tenant_id)
      and worker.status <> 'blocked';
  elsif p_kind = 'organization' then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', organization.id, 'code', organization.organization_code,
      'name', organization.organization_name, 'status', organization.status
    ) order by organization.sort, organization.organization_name), '[]'::jsonb)
    into v_result
    from public.mdm_organization organization
    where (p_tenant_id is null or organization.tenant_id = p_tenant_id);
  elsif p_kind = 'position' then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', position.id, 'code', position.position_code, 'name', position.position_name,
      'status', case when position.enabled then 'active' else 'inactive' end,
      'organization_id', position.organization_id
    ) order by position.sort, position.position_name), '[]'::jsonb)
    into v_result
    from public.mdm_position position
    where (p_tenant_id is null or position.tenant_id = p_tenant_id) and position.enabled;
  elsif p_kind = 'sponsor' then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', employee.id, 'code', employee.employee_no, 'name', employee.employee_name,
      'status', employee.employment_status, 'organization_id', employee.organization_id
    ) order by employee.employee_name), '[]'::jsonb)
    into v_result
    from public.mdm_employee employee
    where (p_tenant_id is null or employee.tenant_id = p_tenant_id)
      and employee.employment_status = 'active';
  else
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', engagement.id, 'code', engagement.engagement_no,
      'name', worker.worker_name || ' · ' || engagement.service_title,
      'status', engagement.status, 'extra', engagement.end_date
    ) order by engagement.end_date, worker.worker_name), '[]'::jsonb)
    into v_result
    from public.hr_external_engagement engagement
    join public.hr_external_worker worker on worker.id = engagement.worker_id
    where (p_tenant_id is null or engagement.tenant_id = p_tenant_id)
      and engagement.status in ('draft', 'pending_review', 'active', 'offboarding');
  end if;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."hr_list_contingent_workforce_options_secure"("p_kind" "text", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_list_contingent_workforce_records_secure("text", integer, integer, "text", "text", "uuid", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_contingent_workforce_records_secure"("p_kind" "text", "p_from" integer DEFAULT 0, "p_to" integer DEFAULT 19, "p_keyword" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_engagement_id" "uuid" DEFAULT NULL::"uuid", "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    SET "TimeZone" TO 'Asia/Shanghai'
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_offset integer := greatest(coalesce(p_from, 0), 0);
  v_limit integer := least(500, greatest(coalesce(p_to, 19) - greatest(coalesce(p_from, 0), 0) + 1, 1));
  v_keyword text := nullif(btrim(p_keyword), '');
  v_pii_access boolean;
  v_cost_access boolean;
  v_records jsonb := '[]'::jsonb;
  v_total integer := 0;
begin
  if p_kind not in ('vendor', 'worker', 'engagement', 'control') then
    raise exception '不支持的外部用工记录类型';
  end if;
  if auth.uid() is null or not app_private.can_execute_business_action(
    'HrContingentWorkforce', 'Hr:ContingentWorkforce:View', null, false
  ) then
    raise exception '当前账号没有查看外部用工的权限' using errcode = '42501';
  end if;
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;
  v_pii_access := app_private.can_execute_business_action(
    'HrContingentWorkforce', 'Hr:ContingentWorkforce:PII:View', null, false
  );
  v_cost_access := app_private.can_execute_business_action(
    'HrContingentWorkforce', 'Hr:ContingentWorkforce:Cost:View', null, false
  );

  if p_kind = 'vendor' then
    select count(*)::integer into v_total
    from public.mdm_external_vendor vendor
    where (p_tenant_id is null or vendor.tenant_id = p_tenant_id)
      and (p_status is null or p_status = '' or vendor.status = p_status)
      and (v_keyword is null or vendor.vendor_code ilike '%' || v_keyword || '%'
        or vendor.vendor_name ilike '%' || v_keyword || '%'
        or vendor.contract_no ilike '%' || v_keyword || '%');

    select coalesce(jsonb_agg(row_data order by sort_active, vendor_name), '[]'::jsonb)
    into v_records
    from (
      select
        case vendor.status when 'active' then 0 else 1 end as sort_active,
        vendor.vendor_name,
        jsonb_build_object(
          'id', vendor.id,
          'tenant_id', vendor.tenant_id,
          'vendor_code', vendor.vendor_code,
          'vendor_name', vendor.vendor_name,
          'registration_no', vendor.registration_no,
          'contact_name', case when v_pii_access then vendor.contact_name else app_private.hr_mask_external_phone(vendor.contact_name) end,
          'contact_phone', case when v_pii_access then vendor.contact_phone else app_private.hr_mask_external_phone(vendor.contact_phone) end,
          'contact_email', case when v_pii_access then vendor.contact_email else app_private.hr_mask_external_email(vendor.contact_email) end,
          'service_scope', vendor.service_scope,
          'contract_no', vendor.contract_no,
          'contract_start_date', vendor.contract_start_date,
          'contract_end_date', vendor.contract_end_date,
          'compliance_status', vendor.compliance_status,
          'risk_level', vendor.risk_level,
          'status', vendor.status,
          'note', vendor.note,
          'active_engagement_count', (
            select count(*) from public.hr_external_engagement engagement
            where engagement.vendor_id = vendor.id and engagement.status = 'active'
          ),
          'worker_count', (
            select count(*) from public.hr_external_worker worker where worker.vendor_id = vendor.id
          ),
          'create_time', vendor.create_time,
          'update_time', vendor.update_time
        ) as row_data
      from public.mdm_external_vendor vendor
      where (p_tenant_id is null or vendor.tenant_id = p_tenant_id)
        and (p_status is null or p_status = '' or vendor.status = p_status)
        and (v_keyword is null or vendor.vendor_code ilike '%' || v_keyword || '%'
          or vendor.vendor_name ilike '%' || v_keyword || '%'
          or vendor.contract_no ilike '%' || v_keyword || '%')
      order by sort_active, vendor.vendor_name
      offset v_offset limit v_limit
    ) rows;
  elsif p_kind = 'worker' then
    select count(*)::integer into v_total
    from public.hr_external_worker worker
    left join public.mdm_external_vendor vendor on vendor.id = worker.vendor_id
    where (p_tenant_id is null or worker.tenant_id = p_tenant_id)
      and (p_status is null or p_status = '' or worker.status = p_status)
      and (v_keyword is null or worker.worker_no ilike '%' || v_keyword || '%'
        or worker.worker_name ilike '%' || v_keyword || '%'
        or worker.vendor_worker_no ilike '%' || v_keyword || '%'
        or vendor.vendor_name ilike '%' || v_keyword || '%');

    select coalesce(jsonb_agg(row_data order by sort_active, worker_name), '[]'::jsonb)
    into v_records
    from (
      select
        case worker.status when 'active' then 0 when 'ready' then 1 else 2 end as sort_active,
        worker.worker_name,
        jsonb_build_object(
          'id', worker.id,
          'tenant_id', worker.tenant_id,
          'worker_no', worker.worker_no,
          'worker_name', worker.worker_name,
          'worker_type', worker.worker_type,
          'vendor_id', worker.vendor_id,
          'vendor_name', vendor.vendor_name,
          'vendor_worker_no', worker.vendor_worker_no,
          'phone', case when v_pii_access then worker.phone else app_private.hr_mask_external_phone(worker.phone) end,
          'email', case when v_pii_access then worker.email else app_private.hr_mask_external_email(worker.email) end,
          'identity_check_status', worker.identity_check_status,
          'status', worker.status,
          'note', worker.note,
          'active_engagement_count', (
            select count(*) from public.hr_external_engagement engagement
            where engagement.worker_id = worker.id and engagement.status = 'active'
          ),
          'next_end_date', (
            select min(engagement.end_date) from public.hr_external_engagement engagement
            where engagement.worker_id = worker.id and engagement.status = 'active'
          ),
          'create_time', worker.create_time,
          'update_time', worker.update_time
        ) as row_data
      from public.hr_external_worker worker
      left join public.mdm_external_vendor vendor on vendor.id = worker.vendor_id
      where (p_tenant_id is null or worker.tenant_id = p_tenant_id)
        and (p_status is null or p_status = '' or worker.status = p_status)
        and (v_keyword is null or worker.worker_no ilike '%' || v_keyword || '%'
          or worker.worker_name ilike '%' || v_keyword || '%'
          or worker.vendor_worker_no ilike '%' || v_keyword || '%'
          or vendor.vendor_name ilike '%' || v_keyword || '%')
      order by sort_active, worker.worker_name
      offset v_offset limit v_limit
    ) rows;
  elsif p_kind = 'engagement' then
    select count(*)::integer into v_total
    from public.hr_external_engagement engagement
    join public.hr_external_worker worker on worker.id = engagement.worker_id
    join public.mdm_organization organization on organization.id = engagement.organization_id
    where (p_tenant_id is null or engagement.tenant_id = p_tenant_id)
      and (p_status is null or p_status = '' or engagement.status = p_status)
      and (v_keyword is null or engagement.engagement_no ilike '%' || v_keyword || '%'
        or engagement.service_title ilike '%' || v_keyword || '%'
        or worker.worker_name ilike '%' || v_keyword || '%'
        or organization.organization_name ilike '%' || v_keyword || '%');

    select coalesce(jsonb_agg(row_data order by sort_active, end_date, worker_name), '[]'::jsonb)
    into v_records
    from (
      select
        case engagement.status when 'active' then 0 when 'pending_review' then 1 when 'offboarding' then 2 else 3 end as sort_active,
        engagement.end_date,
        worker.worker_name,
        jsonb_build_object(
          'id', engagement.id,
          'tenant_id', engagement.tenant_id,
          'engagement_no', engagement.engagement_no,
          'worker_id', engagement.worker_id,
          'worker_no', worker.worker_no,
          'worker_name', worker.worker_name,
          'worker_type', worker.worker_type,
          'vendor_id', engagement.vendor_id,
          'vendor_name', vendor.vendor_name,
          'organization_id', engagement.organization_id,
          'organization_name', organization.organization_name,
          'position_id', engagement.position_id,
          'position_name', position.position_name,
          'sponsor_employee_id', engagement.sponsor_employee_id,
          'sponsor_employee_name', sponsor.employee_name,
          'service_title', engagement.service_title,
          'work_location', engagement.work_location,
          'start_date', engagement.start_date,
          'end_date', engagement.end_date,
          'access_expiry_date', engagement.access_expiry_date,
          'actual_exit_date', engagement.actual_exit_date,
          'fte', engagement.fte,
          'billing_rate', case when v_cost_access then to_jsonb(engagement.billing_rate) else to_jsonb('***'::text) end,
          'billing_unit', case when v_cost_access then engagement.billing_unit else null end,
          'currency_code', case when v_cost_access then engagement.currency_code else null end,
          'compliance_status', engagement.compliance_status,
          'status', engagement.status,
          'activation_note', engagement.activation_note,
          'end_reason', engagement.end_reason,
          'version', engagement.version,
          'pending_control_count', (
            select count(*) from public.hr_external_engagement_control control
            where control.engagement_id = engagement.id and control.required
              and control.status not in ('completed', 'waived')
          ),
          'control_count', (
            select count(*) from public.hr_external_engagement_control control
            where control.engagement_id = engagement.id
          ),
          'create_time', engagement.create_time,
          'update_time', engagement.update_time
        ) as row_data
      from public.hr_external_engagement engagement
      join public.hr_external_worker worker on worker.id = engagement.worker_id
      left join public.mdm_external_vendor vendor on vendor.id = engagement.vendor_id
      join public.mdm_organization organization on organization.id = engagement.organization_id
      left join public.mdm_position position on position.id = engagement.position_id
      join public.mdm_employee sponsor on sponsor.id = engagement.sponsor_employee_id
      where (p_tenant_id is null or engagement.tenant_id = p_tenant_id)
        and (p_status is null or p_status = '' or engagement.status = p_status)
        and (v_keyword is null or engagement.engagement_no ilike '%' || v_keyword || '%'
          or engagement.service_title ilike '%' || v_keyword || '%'
          or worker.worker_name ilike '%' || v_keyword || '%'
          or organization.organization_name ilike '%' || v_keyword || '%')
      order by sort_active, engagement.end_date, worker.worker_name
      offset v_offset limit v_limit
    ) rows;
  else
    select count(*)::integer into v_total
    from public.hr_external_engagement_control control
    join public.hr_external_engagement engagement on engagement.id = control.engagement_id
    join public.hr_external_worker worker on worker.id = engagement.worker_id
    where (p_tenant_id is null or control.tenant_id = p_tenant_id)
      and (p_engagement_id is null or control.engagement_id = p_engagement_id)
      and (p_status is null or p_status = '' or control.status = p_status)
      and (v_keyword is null or control.control_name ilike '%' || v_keyword || '%'
        or engagement.engagement_no ilike '%' || v_keyword || '%'
        or worker.worker_name ilike '%' || v_keyword || '%');

    select coalesce(jsonb_agg(row_data order by required desc, due_date nulls last, control_name), '[]'::jsonb)
    into v_records
    from (
      select
        control.required,
        control.due_date,
        control.control_name,
        jsonb_build_object(
          'id', control.id,
          'tenant_id', control.tenant_id,
          'engagement_id', control.engagement_id,
          'engagement_no', engagement.engagement_no,
          'engagement_status', engagement.status,
          'worker_name', worker.worker_name,
          'control_type', control.control_type,
          'control_name', control.control_name,
          'required', control.required,
          'status', control.status,
          'due_date', control.due_date,
          'completed_at', control.completed_at,
          'completed_by', control.completed_by,
          'evidence_reference', control.evidence_reference,
          'note', control.note,
          'create_time', control.create_time,
          'update_time', control.update_time
        ) as row_data
      from public.hr_external_engagement_control control
      join public.hr_external_engagement engagement on engagement.id = control.engagement_id
      join public.hr_external_worker worker on worker.id = engagement.worker_id
      where (p_tenant_id is null or control.tenant_id = p_tenant_id)
        and (p_engagement_id is null or control.engagement_id = p_engagement_id)
        and (p_status is null or p_status = '' or control.status = p_status)
        and (v_keyword is null or control.control_name ilike '%' || v_keyword || '%'
          or engagement.engagement_no ilike '%' || v_keyword || '%'
          or worker.worker_name ilike '%' || v_keyword || '%')
      order by control.required desc, control.due_date nulls last, control.control_name
      offset v_offset limit v_limit
    ) rows;
  end if;

  return jsonb_build_object(
    'records', v_records,
    'total', v_total,
    'pii_access', v_pii_access,
    'cost_access', v_cost_access
  );
end;
$$;


ALTER FUNCTION "public"."hr_list_contingent_workforce_records_secure"("p_kind" "text", "p_from" integer, "p_to" integer, "p_keyword" "text", "p_status" "text", "p_engagement_id" "uuid", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_list_employee_experience_records_secure("text", integer, integer, "text", "text", "text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_employee_experience_records_secure"("p_kind" "text", "p_from" integer DEFAULT 0, "p_to" integer DEFAULT 19, "p_keyword" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_survey_type" "text" DEFAULT NULL::"text", "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_employee_id uuid := app_private.hr_current_employee_id();
  v_limit integer := greatest(least(p_to - p_from + 1, 200), 1);
  v_offset integer := greatest(p_from, 0);
  v_insights boolean := app_private.hr_experience_insights_visible();
  v_result jsonb;
begin
  if auth.uid() is null or not app_private.can_execute_business_action(
    'HrEmployeeExperience', 'Hr:Experience:View', null, false
  ) then raise exception '当前账号没有查看员工体验工作台的权限' using errcode = '42501'; end if;
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;

  if p_kind = 'my' then
    if v_employee_id is null or not (
      app_private.is_platform_super() or app_private.has_permission('Hr:Experience:Respond')
    ) then raise exception '当前账号没有填写员工体验调查的权限' using errcode = '42501'; end if;
    with base as (
      select participant.id, participant.tenant_id, participant.survey_id,
        participant.status, participant.assigned_on, participant.completed_on,
        survey.survey_code, survey.survey_name, survey.survey_type,
        survey.cadence, survey.start_date, survey.end_date, survey.description,
        survey.minimum_group_size,
        (select count(*) from public.hr_experience_question question
          where question.survey_id = survey.id and question.tenant_id = survey.tenant_id
            and question.enabled) question_count,
        case when participant.status = 'invited' and survey.status = 'open'
          and current_date between survey.start_date and survey.end_date then 'available'
          when participant.status = 'completed' then 'completed'
          when survey.end_date < current_date then 'expired'
          else 'unavailable' end availability
      from public.hr_experience_participant participant
      join public.hr_experience_survey survey on survey.id = participant.survey_id
        and survey.tenant_id = participant.tenant_id
      where (app_private.current_read_tenant_id() is null or participant.tenant_id = app_private.current_read_tenant_id())
        and participant.employee_id = v_employee_id
        and (p_status is null or participant.status = p_status)
        and (p_survey_type is null or survey.survey_type = p_survey_type)
        and (p_keyword is null or survey.survey_name ilike '%' || btrim(p_keyword) || '%'
          or survey.survey_code ilike '%' || btrim(p_keyword) || '%')
    ), page as (
      select * from base order by
        case availability when 'available' then 0 when 'unavailable' then 1
          when 'completed' then 2 else 3 end,
        end_date, survey_name limit v_limit offset v_offset
    )
    select jsonb_build_object(
      'records', coalesce(jsonb_agg(to_jsonb(page)), '[]'::jsonb),
      'total', (select count(*) from base)
    ) into v_result from page;
  elsif p_kind = 'survey' then
    if not v_insights then raise exception '当前账号没有查看调查管理数据的权限' using errcode = '42501'; end if;
    with base as (
      select survey.*,
        organization.organization_name audience_organization_name,
        (select count(*) from public.hr_experience_question question
          where question.survey_id = survey.id and question.tenant_id = survey.tenant_id
            and question.enabled) question_count,
        (select count(*) from public.hr_experience_participant participant
          where participant.survey_id = survey.id and participant.tenant_id = survey.tenant_id)
          participant_count,
        (select count(*) from public.hr_experience_participant participant
          where participant.survey_id = survey.id and participant.tenant_id = survey.tenant_id
            and participant.status = 'completed') completed_count
      from public.hr_experience_survey survey
      left join public.mdm_organization organization
        on organization.id = survey.audience_organization_id
        and organization.tenant_id = survey.tenant_id
      where (p_tenant_id is null or survey.tenant_id = p_tenant_id)
        and (p_status is null or survey.status = p_status)
        and (p_survey_type is null or survey.survey_type = p_survey_type)
        and (p_keyword is null or survey.survey_name ilike '%' || btrim(p_keyword) || '%'
          or survey.survey_code ilike '%' || btrim(p_keyword) || '%')
    ), page as (
      select * from base order by start_date desc, create_time desc
      limit v_limit offset v_offset
    )
    select jsonb_build_object(
      'records', coalesce(jsonb_agg(to_jsonb(page) || jsonb_build_object(
        'response_rate', case when page.participant_count = 0 then 0
          else round(100.0 * page.completed_count / page.participant_count, 1) end
      )), '[]'::jsonb),
      'total', (select count(*) from base)
    ) into v_result from page;
  elsif p_kind = 'insight' then
    if not v_insights then raise exception '当前账号没有查看匿名聚合洞察的权限' using errcode = '42501'; end if;
    with scores as (
      select survey.id survey_id, survey.tenant_id, survey.survey_code,
        survey.survey_name, survey.survey_type, survey.status survey_status,
        survey.minimum_group_size, question.dimension,
        count(distinct response.id)::integer respondent_count,
        count(distinct question.id)::integer question_count,
        round(avg(case when question.answer_type = 'rating_5'
          then (answer.numeric_score - 1) * 25
          else answer.numeric_score * 10 end), 1) score_percent,
        (select count(*)::integer
          from public.hr_experience_action action
          where action.survey_id = survey.id
            and action.tenant_id = survey.tenant_id
            and action.dimension = question.dimension
            and action.status <> 'cancelled') action_count
      from public.hr_experience_survey survey
      join public.hr_experience_response response on response.survey_id = survey.id
        and response.tenant_id = survey.tenant_id
      join public.hr_experience_answer answer on answer.response_id = response.id
        and answer.tenant_id = response.tenant_id and answer.numeric_score is not null
      join public.hr_experience_question question on question.id = answer.question_id
        and question.tenant_id = answer.tenant_id
      where (p_tenant_id is null or survey.tenant_id = p_tenant_id)
        and (p_status is null or survey.status = p_status)
        and (p_survey_type is null or survey.survey_type = p_survey_type)
        and (p_keyword is null or survey.survey_name ilike '%' || btrim(p_keyword) || '%'
          or survey.survey_code ilike '%' || btrim(p_keyword) || '%')
      group by survey.id, survey.tenant_id, survey.survey_code, survey.survey_name,
        survey.survey_type, survey.status, survey.minimum_group_size, question.dimension
    ), eligible as (
      select *, case when score_percent < 60 then 'high'
        when score_percent < 75 then 'medium' else 'healthy' end risk_level
      from scores where respondent_count >= minimum_group_size
    ), page as (
      select * from eligible order by
        case risk_level when 'high' then 0 when 'medium' then 1 else 2 end,
        score_percent, survey_name, dimension limit v_limit offset v_offset
    )
    select jsonb_build_object(
      'records', coalesce(jsonb_agg(to_jsonb(page)), '[]'::jsonb),
      'total', (select count(*) from eligible),
      'privacy_note', '仅展示达到最小汇报人数的匿名聚合结果'
    ) into v_result from page;
  elsif p_kind = 'action' then
    if not v_insights then raise exception '当前账号没有查看员工体验行动的权限' using errcode = '42501'; end if;
    with base as (
      select action.*, survey.survey_code, survey.survey_name,
        organization.organization_name,
        employee.employee_no owner_employee_no,
        employee.employee_name owner_employee_name,
        employee.job_title owner_job_title,
        case when action.status in ('planned', 'in_progress')
          and action.due_date < current_date then 'overdue'
          when action.status in ('planned', 'in_progress')
          and action.due_date <= current_date + 7 then 'due_soon'
          else 'clear' end due_status
      from public.hr_experience_action action
      join public.hr_experience_survey survey on survey.id = action.survey_id
        and survey.tenant_id = action.tenant_id
      left join public.mdm_organization organization on organization.id = action.organization_id
        and organization.tenant_id = action.tenant_id
      join public.mdm_employee employee on employee.id = action.owner_employee_id
        and employee.tenant_id = action.tenant_id
      where (p_tenant_id is null or action.tenant_id = p_tenant_id)
        and (p_status is null or action.status = p_status)
        and (p_survey_type is null or survey.survey_type = p_survey_type)
        and (p_keyword is null or action.title ilike '%' || btrim(p_keyword) || '%'
          or survey.survey_name ilike '%' || btrim(p_keyword) || '%'
          or employee.employee_name ilike '%' || btrim(p_keyword) || '%')
    ), page as (
      select * from base order by
        case due_status when 'overdue' then 0 when 'due_soon' then 1 else 2 end,
        due_date, create_time desc limit v_limit offset v_offset
    )
    select jsonb_build_object(
      'records', coalesce(jsonb_agg(to_jsonb(page)), '[]'::jsonb),
      'total', (select count(*) from base)
    ) into v_result from page;
  else
    raise exception '不支持的员工体验记录类型';
  end if;
  return coalesce(v_result, jsonb_build_object('records', '[]'::jsonb, 'total', 0));
end
$$;


ALTER FUNCTION "public"."hr_list_employee_experience_records_secure"("p_kind" "text", "p_from" integer, "p_to" integer, "p_keyword" "text", "p_status" "text", "p_survey_type" "text", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_list_employee_organization_scope_secure("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_employee_organization_scope_secure"("p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_target_tenant_id uuid;
begin
  perform app_private.assert_hr_employee_readable();

  v_target_tenant_id := case
    when app_private.is_platform_super() then p_tenant_id
    else app_private.current_user_tenant_id()
  end;

  if not app_private.is_platform_super() and v_target_tenant_id is null then
    raise exception 'Employee tenant is required' using errcode = '22023';
  end if;

  return coalesce((
    select jsonb_agg(
      jsonb_build_object(
        'id', organization_row.id,
        'tenant_id', organization_row.tenant_id,
        'tenant', jsonb_build_object(
          'tenant_code', tenant_row.tenant_code,
          'tenant_name', tenant_row.tenant_name
        ),
        'parent_id', organization_row.parent_id,
        'organization_code', organization_row.organization_code,
        'organization_name', organization_row.organization_name,
        'organization_type', organization_row.organization_type,
        'status', organization_row.status,
        'sort', organization_row.sort,
        'is_system', organization_row.is_system,
        'scope_count', (
          select count(*)
          from public.mdm_employee employee_row
          where employee_row.tenant_id = organization_row.tenant_id
            and employee_row.organization_id = organization_row.id
        )
      )
      order by tenant_row.tenant_name, organization_row.sort, organization_row.organization_name
    )
    from public.mdm_organization organization_row
    join public.sys_tenant tenant_row on tenant_row.id = organization_row.tenant_id
    where (v_target_tenant_id is null or organization_row.tenant_id = v_target_tenant_id)
      and organization_row.status = '1'
  ), '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."hr_list_employee_organization_scope_secure"("p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_list_employee_relations_records_secure("text", integer, integer, "text", "text", "text", "text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_employee_relations_records_secure"("p_kind" "text", "p_from" integer DEFAULT 0, "p_to" integer DEFAULT 19, "p_keyword" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_case_type" "text" DEFAULT NULL::"text", "p_severity" "text" DEFAULT NULL::"text", "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_result jsonb;
  v_sensitive boolean := app_private.is_platform_super()
    or app_private.has_permission('Hr:EmployeeRelations:Sensitive:View');
begin
  v_result := app_private.hr_list_employee_relations_records_internal(
    p_kind, p_from, p_to, p_keyword, p_status, p_case_type, p_severity, p_tenant_id
  );

  select jsonb_set(
    v_result,
    '{records}',
    coalesce(jsonb_agg(
      case
        when v_sensitive then record - 'safe_title'
        else record - 'safe_title' - 'remark' - 'external_reference' - 'reporter_employee'
      end
    ), '[]'::jsonb)
  )
  into v_result
  from jsonb_array_elements(coalesce(v_result -> 'records', '[]'::jsonb)) record;

  return coalesce(v_result, jsonb_build_object('records', '[]'::jsonb, 'total', 0));
end
$$;


ALTER FUNCTION "public"."hr_list_employee_relations_records_secure"("p_kind" "text", "p_from" integer, "p_to" integer, "p_keyword" "text", "p_status" "text", "p_case_type" "text", "p_severity" "text", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_list_employee_selector_secure(integer, integer, "uuid", "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_employee_selector_secure"("p_from" integer DEFAULT 0, "p_to" integer DEFAULT 19, "p_tenant_id" "uuid" DEFAULT NULL::"uuid", "p_keyword" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_target_tenant_id uuid;
  v_from integer := greatest(coalesce(p_from, 0), 0);
  v_limit integer := least(
    greatest(coalesce(p_to, 19) - greatest(coalesce(p_from, 0), 0) + 1, 1),
    200
  );
  v_keyword text := nullif(btrim(p_keyword), '');
  v_has_hr_menu boolean := app_private.can_execute_business_action(
    'HrEmployeeRoster', null, null, false
  );
  v_contact_access text := case when v_has_hr_menu then app_private.resolve_field_access(
    'hr.employee', 'contactDetails', null
  ) else 'hidden' end;
  v_identity_access text := case when v_has_hr_menu then app_private.resolve_field_access(
    'hr.employee', 'identityDetails', null
  ) else 'hidden' end;
  v_total bigint;
  v_records jsonb;
begin
  if not (
    app_private.can_execute_business_action(
      'HrEmployeeRoster', 'Hr:Employee:View', null, false
    )
    or app_private.can_execute_business_action('User', 'System:User:Add', null, false)
    or app_private.can_execute_business_action('User', 'System:User:Edit', null, false)
  ) then
    raise exception 'Missing employee selector permission' using errcode = '42501';
  end if;

  v_target_tenant_id := case
    when app_private.is_platform_super() and p_tenant_id is not null then p_tenant_id
    else v_tenant_id
  end;
  if v_target_tenant_id is null then
    return jsonb_build_object('records', '[]'::jsonb, 'total', 0);
  end if;

  with filtered as materialized (
    select
      employee_row.*,
      organization_row.organization_code,
      organization_row.organization_name
    from public.mdm_employee employee_row
    left join public.mdm_organization organization_row
      on organization_row.id = employee_row.organization_id
     and organization_row.tenant_id = employee_row.tenant_id
    where employee_row.tenant_id = v_target_tenant_id
      and employee_row.employment_status in ('probation', 'active')
      and not exists (
        select 1
        from public.sys_user user_row
        where user_row.hr_employee_id = employee_row.id
          and user_row.tenant_id = employee_row.tenant_id
          and user_row.deleted_at is null
      )
      and (
        v_keyword is null
        or employee_row.employee_no ilike '%' || v_keyword || '%'
        or employee_row.employee_name ilike '%' || v_keyword || '%'
        or employee_row.job_title ilike '%' || v_keyword || '%'
        or (
          v_contact_access in ('read', 'edit')
          and (
            employee_row.phone ilike '%' || v_keyword || '%'
            or employee_row.email ilike '%' || v_keyword || '%'
          )
        )
      )
  ), paged as (
    select *
    from filtered
    order by employee_name, employee_no, id
    offset v_from limit v_limit
  )
  select
    (select count(*) from filtered),
    coalesce((
      select jsonb_agg(
        jsonb_strip_nulls(jsonb_build_object(
          'id', paged.id,
          'tenant_id', paged.tenant_id,
          'organization_id', paged.organization_id,
          'employee_no', paged.employee_no,
          'employee_name', paged.employee_name,
          'avatar_url', paged.avatar_url,
          'job_title', paged.job_title,
          'employment_status', paged.employment_status,
          'organization', case when paged.organization_id is null then null else jsonb_build_object(
            'id', paged.organization_id,
            'organization_code', paged.organization_code,
            'organization_name', paged.organization_name
          ) end,
          'gender', case when v_identity_access in ('read', 'edit') then paged.gender else null end,
          'phone', case when v_contact_access in ('read', 'edit') then paged.phone else null end,
          'email', case when v_contact_access in ('read', 'edit') then paged.email else null end
        )) order by paged.employee_name, paged.employee_no, paged.id
      )
      from paged
    ), '[]'::jsonb)
  into v_total, v_records;

  return jsonb_build_object(
    'records', v_records,
    'total', v_total,
    'field_access', case when v_has_hr_menu
      then app_private.field_access_map('hr.employee', null)
      else '{}'::jsonb
    end
  );
end;
$$;


ALTER FUNCTION "public"."hr_list_employee_selector_secure"("p_from" integer, "p_to" integer, "p_tenant_id" "uuid", "p_keyword" "text") OWNER TO "postgres";

--

--
-- Name: hr_list_employees_secure(integer, integer, "uuid", "uuid"[], boolean, "text", "text", "text", "date", "date", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_employees_secure"("p_from" integer DEFAULT 0, "p_to" integer DEFAULT 19, "p_tenant_id" "uuid" DEFAULT NULL::"uuid", "p_organization_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_organization_unassigned" boolean DEFAULT false, "p_employment_status" "text" DEFAULT NULL::"text", "p_employment_type" "text" DEFAULT NULL::"text", "p_keyword" "text" DEFAULT NULL::"text", "p_hire_start" "date" DEFAULT NULL::"date", "p_hire_end" "date" DEFAULT NULL::"date", "p_record_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_target_tenant_id uuid;
  v_current_user_id uuid := app_private.current_app_user_id();
  v_from integer := greatest(coalesce(p_from, 0), 0);
  v_limit integer := least(
    greatest(coalesce(p_to, 19) - greatest(coalesce(p_from, 0), 0) + 1, 1),
    1000
  );
  v_keyword text := nullif(btrim(p_keyword), '');
  v_contact_access text := app_private.resolve_field_access(
    'hr.employee', 'contactDetails', null
  );
  v_identity_access text := app_private.resolve_field_access(
    'hr.employee', 'identityDetails', null
  );
  v_total bigint;
  v_records jsonb := '[]'::jsonb;
  v_row record;
begin
  perform app_private.assert_hr_employee_readable();

  v_target_tenant_id := case
    when app_private.is_platform_super() then p_tenant_id
    else v_tenant_id
  end;

  if not app_private.is_platform_super() and v_target_tenant_id is null then
    raise exception 'Employee tenant is required' using errcode = '22023';
  end if;

  select count(*) into v_total
  from public.mdm_employee employee_row
  where (v_target_tenant_id is null or employee_row.tenant_id = v_target_tenant_id)
    and (p_record_id is null or employee_row.id = p_record_id)
    and (
      not coalesce(p_organization_unassigned, false)
      or employee_row.organization_id is null
    )
    and (
      coalesce(p_organization_unassigned, false)
      or p_organization_ids is null
      or employee_row.organization_id = any(p_organization_ids)
    )
    and (p_employment_status is null or employee_row.employment_status = p_employment_status)
    and (p_employment_type is null or employee_row.employment_type = p_employment_type)
    and (p_hire_start is null or employee_row.hire_date >= p_hire_start)
    and (p_hire_end is null or employee_row.hire_date <= p_hire_end)
    and (
      v_keyword is null
      or employee_row.employee_no ilike '%' || v_keyword || '%'
      or employee_row.employee_name ilike '%' || v_keyword || '%'
      or employee_row.job_title ilike '%' || v_keyword || '%'
      or (
        (
          employee_row.created_by_user_id = v_current_user_id
          or v_contact_access in ('read', 'edit')
        )
        and (
          employee_row.phone ilike '%' || v_keyword || '%'
          or employee_row.email ilike '%' || v_keyword || '%'
        )
      )
      or (
        (
          employee_row.created_by_user_id = v_current_user_id
          or v_identity_access in ('read', 'edit')
        )
        and employee_row.id_card_no ilike '%' || v_keyword || '%'
      )
    );

  for v_row in
    select employee_row.id, employee_row.created_by_user_id
    from public.mdm_employee employee_row
    where (v_target_tenant_id is null or employee_row.tenant_id = v_target_tenant_id)
      and (p_record_id is null or employee_row.id = p_record_id)
      and (
        not coalesce(p_organization_unassigned, false)
        or employee_row.organization_id is null
      )
      and (
        coalesce(p_organization_unassigned, false)
        or p_organization_ids is null
        or employee_row.organization_id = any(p_organization_ids)
      )
      and (p_employment_status is null or employee_row.employment_status = p_employment_status)
      and (p_employment_type is null or employee_row.employment_type = p_employment_type)
      and (p_hire_start is null or employee_row.hire_date >= p_hire_start)
      and (p_hire_end is null or employee_row.hire_date <= p_hire_end)
      and (
        v_keyword is null
        or employee_row.employee_no ilike '%' || v_keyword || '%'
        or employee_row.employee_name ilike '%' || v_keyword || '%'
        or employee_row.job_title ilike '%' || v_keyword || '%'
        or (
          (
            employee_row.created_by_user_id = v_current_user_id
            or v_contact_access in ('read', 'edit')
          )
          and (
            employee_row.phone ilike '%' || v_keyword || '%'
            or employee_row.email ilike '%' || v_keyword || '%'
          )
        )
        or (
          (
            employee_row.created_by_user_id = v_current_user_id
            or v_identity_access in ('read', 'edit')
          )
          and employee_row.id_card_no ilike '%' || v_keyword || '%'
        )
      )
    order by
      employee_row.tenant_id,
      employee_row.employment_status,
      employee_row.hire_date desc nulls last,
      employee_row.create_time desc,
      employee_row.id
    offset v_from limit v_limit
  loop
    v_records := v_records || jsonb_build_array(
      app_private.hr_employee_to_secure_json(v_row.id, v_row.created_by_user_id)
    );
  end loop;

  return jsonb_build_object(
    'records', v_records,
    'total', v_total,
    'field_access', app_private.field_access_map('hr.employee', null)
  );
end;
$$;


ALTER FUNCTION "public"."hr_list_employees_secure"("p_from" integer, "p_to" integer, "p_tenant_id" "uuid", "p_organization_ids" "uuid"[], "p_organization_unassigned" boolean, "p_employment_status" "text", "p_employment_type" "text", "p_keyword" "text", "p_hire_start" "date", "p_hire_end" "date", "p_record_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_list_internal_mobility_options_secure("text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_internal_mobility_options_secure"("p_kind" "text", "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_tenant_id uuid:=app_private.current_user_tenant_id(); v_result jsonb:='[]'::jsonb; v_manage boolean;
begin
  if p_kind not in ('organization','position','employee','opportunity') then raise exception '不支持的内部人才市场选项类型'; end if;
  if auth.uid() is null or not app_private.can_execute_business_action('HrInternalMobility','Hr:InternalMobility:View',null,false)
    then raise exception '当前账号没有查看内部人才市场的权限' using errcode='42501'; end if;
  if not app_private.is_platform_super() then p_tenant_id:=v_tenant_id; end if;
  v_manage:=app_private.can_execute_business_action('HrInternalMobility','Hr:InternalMobility:Opportunity:Manage',null,false)
    or app_private.can_execute_business_action('HrInternalMobility','Hr:InternalMobility:Application:Manage',null,false);
  if p_kind in ('organization','position','employee') and not v_manage then
    raise exception '当前账号没有读取内部管理选项的权限' using errcode='42501';
  end if;
  if p_kind='organization' then
    select coalesce(jsonb_agg(jsonb_build_object('id',o.id,'tenant_id',o.tenant_id,'code',o.organization_code,'name',o.organization_name,'status',o.status) order by o.sort,o.organization_name),'[]'::jsonb)
    into v_result from public.mdm_organization o where (p_tenant_id is null or o.tenant_id=p_tenant_id) and o.status='1';
  elsif p_kind='position' then
    select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'tenant_id',p.tenant_id,'code',p.position_code,'name',p.position_name,'organization_id',p.organization_id,'status',case when p.enabled then 'active' else 'inactive' end) order by p.sort,p.position_name),'[]'::jsonb)
    into v_result from public.mdm_position p where (p_tenant_id is null or p.tenant_id=p_tenant_id) and p.enabled;
  elsif p_kind='employee' then
    select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'tenant_id',e.tenant_id,'code',e.employee_no,'name',e.employee_name,'organization_id',e.organization_id,'status',e.employment_status) order by e.employee_name),'[]'::jsonb)
    into v_result from public.mdm_employee e where (p_tenant_id is null or e.tenant_id=p_tenant_id) and e.employment_status in ('probation','active','leave');
  else
    select coalesce(jsonb_agg(jsonb_build_object('id',o.id,'tenant_id',o.tenant_id,'code',o.opportunity_code,'name',o.opportunity_title,'status',o.status) order by o.application_close_date,o.opportunity_title),'[]'::jsonb)
    into v_result from public.hr_internal_opportunity o where (p_tenant_id is null or o.tenant_id=p_tenant_id) and o.status='open';
  end if;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."hr_list_internal_mobility_options_secure"("p_kind" "text", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_list_internal_mobility_records_secure("text", integer, integer, "text", "text", "uuid", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_internal_mobility_records_secure"("p_kind" "text", "p_from" integer DEFAULT 0, "p_to" integer DEFAULT 19, "p_keyword" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_opportunity_id" "uuid" DEFAULT NULL::"uuid", "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    SET "TimeZone" TO 'Asia/Shanghai'
    AS $$
declare
  v_tenant_id uuid:=app_private.current_user_tenant_id(); v_employee_id uuid:=app_private.hr_current_employee_id();
  v_manage boolean; v_offset integer:=greatest(coalesce(p_from,0),0);
  v_limit integer:=least(500,greatest(coalesce(p_to,19)-greatest(coalesce(p_from,0),0)+1,1));
  v_keyword text:=nullif(btrim(p_keyword),''); v_total integer:=0; v_records jsonb:='[]'::jsonb;
begin
  if p_kind not in ('opportunity','application') then raise exception '不支持的内部人才市场记录类型'; end if;
  if auth.uid() is null or not app_private.can_execute_business_action(
    'HrInternalMobility','Hr:InternalMobility:View',null,false
  ) then raise exception '当前账号没有查看内部人才市场的权限' using errcode='42501'; end if;
  if not app_private.is_platform_super() then p_tenant_id:=v_tenant_id; end if;
  v_manage:=app_private.can_execute_business_action(
    'HrInternalMobility','Hr:InternalMobility:Application:Manage',null,false
  );

  if p_kind='opportunity' then
    select count(*)::integer into v_total from public.hr_internal_opportunity o
    join public.mdm_organization organization on organization.id=o.organization_id
    left join public.mdm_position position_row on position_row.id=o.position_id
    where (p_tenant_id is null or o.tenant_id=p_tenant_id)
      and (v_manage or o.status in ('open','paused','closed'))
      and (p_status is null or p_status='' or o.status=p_status)
      and (v_keyword is null or o.opportunity_code ilike '%'||v_keyword||'%'
        or o.opportunity_title ilike '%'||v_keyword||'%' or o.role_summary ilike '%'||v_keyword||'%'
        or o.required_skills ilike '%'||v_keyword||'%' or organization.organization_name ilike '%'||v_keyword||'%'
        or position_row.position_name ilike '%'||v_keyword||'%');
    select coalesce(jsonb_agg(row_data order by open_rank,application_close_date,update_time desc),'[]'::jsonb)
    into v_records from (
      select case when o.status='open' then 0 else 1 end open_rank,o.application_close_date,o.update_time,
        jsonb_build_object(
          'id',o.id,'tenant_id',o.tenant_id,'opportunity_code',o.opportunity_code,
          'opportunity_title',o.opportunity_title,'opportunity_type',o.opportunity_type,
          'organization_id',o.organization_id,'organization_name',organization.organization_name,
          'position_id',o.position_id,'position_name',position_row.position_name,
          'hiring_manager_employee_id',o.hiring_manager_employee_id,
          'hiring_manager_name',manager_employee.employee_name,'capacity',o.capacity,
          'work_location',o.work_location,'work_mode',o.work_mode,
          'expected_start_date',o.expected_start_date,'expected_end_date',o.expected_end_date,
          'application_open_date',o.application_open_date,'application_close_date',o.application_close_date,
          'min_tenure_months',o.min_tenure_months,'role_summary',o.role_summary,
          'required_skills',o.required_skills,'eligibility_notes',o.eligibility_notes,
          'status',o.status,'published_at',o.published_at,'published_by',o.published_by,
          'decision_note',o.decision_note,'version',o.version,
          'application_count',(select count(*) from public.hr_internal_mobility_application a where a.opportunity_id=o.id and (v_manage or a.employee_id=v_employee_id)),
          'shortlisted_count',(select count(*) from public.hr_internal_mobility_application a where a.opportunity_id=o.id and a.status in ('shortlisted','offered','accepted','converted') and (v_manage or a.employee_id=v_employee_id)),
          'accepted_count',(select count(*) from public.hr_internal_mobility_application a where a.opportunity_id=o.id and a.status in ('accepted','converted')),
          'my_application_id',(select a.id from public.hr_internal_mobility_application a where a.opportunity_id=o.id and a.employee_id=v_employee_id),
          'my_application_status',(select a.status from public.hr_internal_mobility_application a where a.opportunity_id=o.id and a.employee_id=v_employee_id),
          'create_time',o.create_time,'update_time',o.update_time
        ) row_data
      from public.hr_internal_opportunity o
      join public.mdm_organization organization on organization.id=o.organization_id
      left join public.mdm_position position_row on position_row.id=o.position_id
      join public.mdm_employee manager_employee on manager_employee.id=o.hiring_manager_employee_id
      where (p_tenant_id is null or o.tenant_id=p_tenant_id)
        and (v_manage or o.status in ('open','paused','closed'))
        and (p_status is null or p_status='' or o.status=p_status)
        and (v_keyword is null or o.opportunity_code ilike '%'||v_keyword||'%'
          or o.opportunity_title ilike '%'||v_keyword||'%' or o.role_summary ilike '%'||v_keyword||'%'
          or o.required_skills ilike '%'||v_keyword||'%' or organization.organization_name ilike '%'||v_keyword||'%'
          or position_row.position_name ilike '%'||v_keyword||'%')
      offset v_offset limit v_limit
    ) rows;
  else
    select count(*)::integer into v_total from public.hr_internal_mobility_application a
    join public.hr_internal_opportunity o on o.id=a.opportunity_id
    join public.mdm_employee e on e.id=a.employee_id
    where (p_tenant_id is null or a.tenant_id=p_tenant_id) and (v_manage or a.employee_id=v_employee_id)
      and (p_opportunity_id is null or a.opportunity_id=p_opportunity_id)
      and (p_status is null or p_status='' or a.status=p_status)
      and (v_keyword is null or e.employee_no ilike '%'||v_keyword||'%'
        or e.employee_name ilike '%'||v_keyword||'%' or o.opportunity_code ilike '%'||v_keyword||'%'
        or o.opportunity_title ilike '%'||v_keyword||'%');
    select coalesce(jsonb_agg(row_data order by update_time desc),'[]'::jsonb) into v_records from (
      select a.update_time,jsonb_build_object(
        'id',a.id,'tenant_id',a.tenant_id,'opportunity_id',a.opportunity_id,
        'opportunity_code',o.opportunity_code,'opportunity_title',o.opportunity_title,
        'opportunity_type',o.opportunity_type,'opportunity_status',o.status,
        'target_organization_name',target_org.organization_name,'target_position_name',target_position.position_name,
        'employee_id',a.employee_id,'employee_no',e.employee_no,'employee_name',e.employee_name,
        'current_organization_id',a.current_organization_id,'current_organization_name',current_org.organization_name,
        'current_position_id',a.current_position_id,'current_position_name',current_position.position_name,
        'current_job_title',a.current_job_title,'motivation',a.motivation,
        'relevant_experience',a.relevant_experience,'preferred_start_date',a.preferred_start_date,
        'manager_awareness',a.manager_awareness,'status',a.status,'submitted_at',a.submitted_at,
        'reviewed_at',a.reviewed_at,'reviewed_by',a.reviewed_by,
        'assessment_score',case when v_manage then a.assessment_score else null end,
        'assessment_note',case when v_manage then a.assessment_note else null end,
        'decision_at',a.decision_at,'decision_by',a.decision_by,
        'decision_note',case when v_manage or a.employee_id=v_employee_id then a.decision_note else null end,
        'accepted_at',a.accepted_at,'accepted_by',a.accepted_by,
        'personnel_change_id',a.personnel_change_id,
        'create_time',a.create_time,'update_time',a.update_time
      ) row_data
      from public.hr_internal_mobility_application a
      join public.hr_internal_opportunity o on o.id=a.opportunity_id
      join public.mdm_employee e on e.id=a.employee_id
      join public.mdm_organization current_org on current_org.id=a.current_organization_id
      join public.mdm_organization target_org on target_org.id=o.organization_id
      left join public.mdm_position current_position on current_position.id=a.current_position_id
      left join public.mdm_position target_position on target_position.id=o.position_id
      where (p_tenant_id is null or a.tenant_id=p_tenant_id) and (v_manage or a.employee_id=v_employee_id)
        and (p_opportunity_id is null or a.opportunity_id=p_opportunity_id)
        and (p_status is null or p_status='' or a.status=p_status)
        and (v_keyword is null or e.employee_no ilike '%'||v_keyword||'%'
          or e.employee_name ilike '%'||v_keyword||'%' or o.opportunity_code ilike '%'||v_keyword||'%'
          or o.opportunity_title ilike '%'||v_keyword||'%')
      offset v_offset limit v_limit
    ) rows;
  end if;
  return jsonb_build_object('records',v_records,'total',v_total,'manage_access',v_manage,'my_employee_id',v_employee_id);
end;
$$;


ALTER FUNCTION "public"."hr_list_internal_mobility_records_secure"("p_kind" "text", "p_from" integer, "p_to" integer, "p_keyword" "text", "p_status" "text", "p_opportunity_id" "uuid", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_list_job_architecture_options_secure("text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_job_architecture_options_secure"("p_kind" "text", "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_tenant_id uuid := app_private.current_user_tenant_id();
begin
  if not (
    app_private.can_execute_business_action('HrJobArchitecture', null, null, false)
    or app_private.can_execute_business_action('HrPosition', null, null, false)
    or app_private.can_execute_business_action('HrPersonnelChange', null, null, false)
  ) then raise exception 'Missing HR architecture permission' using errcode='42501'; end if;
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;
  if p_tenant_id is null then return '[]'::jsonb; end if;
  if p_kind='family' then return coalesce((select jsonb_agg(jsonb_build_object('id',id,'code',family_code,'name',family_name) order by sort,family_name) from public.mdm_job_family where tenant_id=p_tenant_id and enabled),'[]'::jsonb); end if;
  if p_kind='grade' then return coalesce((select jsonb_agg(jsonb_build_object('id',id,'code',grade_code,'name',grade_name,'level',grade_level) order by sort,grade_level,grade_name) from public.mdm_grade where tenant_id=p_tenant_id and enabled),'[]'::jsonb); end if;
  if p_kind='profile' then return coalesce((select jsonb_agg(jsonb_build_object('id',id,'code',job_code,'name',job_name,'family_id',family_id,'default_grade_id',default_grade_id) order by sort,job_name) from public.mdm_job_profile where tenant_id=p_tenant_id and enabled),'[]'::jsonb); end if;
  raise exception '不支持的职务体系选项类型';
end;
$$;


ALTER FUNCTION "public"."hr_list_job_architecture_options_secure"("p_kind" "text", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_list_learning_options_secure("text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_learning_options_secure"("p_kind" "text", "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_result jsonb;
begin
  if not app_private.can_execute_business_action('HrTalentDevelopment', 'Hr:Talent:View', null, false) then
    raise exception '当前账号没有查看学习发展选项的权限' using errcode = '42501';
  end if;
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;

  if p_kind = 'plan' then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', p.id, 'tenant_id', p.tenant_id, 'code', p.plan_code, 'name', p.plan_name, 'status', p.status
    ) order by p.plan_code), '[]'::jsonb) into v_result
    from public.hr_training_plan p
    where (p_tenant_id is null or p.tenant_id = p_tenant_id) and p.status in ('published', 'in_progress');
  elsif p_kind = 'course' then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', c.id, 'tenant_id', c.tenant_id, 'code', c.course_code, 'name', c.course_name,
      'status', c.status, 'duration_hours', c.duration_hours
    ) order by c.course_code), '[]'::jsonb) into v_result
    from public.hr_learning_course c
    where (p_tenant_id is null or c.tenant_id = p_tenant_id) and c.status = 'published';
  elsif p_kind = 'session' then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', s.id, 'tenant_id', s.tenant_id, 'code', s.session_code, 'name', c.course_name,
      'plan_id', s.plan_id, 'course_id', s.course_id, 'start_at', s.start_at, 'status', s.status
    ) order by s.start_at), '[]'::jsonb) into v_result
    from public.hr_learning_session s
    join public.hr_learning_course c on c.id = s.course_id and c.tenant_id = s.tenant_id
    where (p_tenant_id is null or s.tenant_id = p_tenant_id) and s.status = 'open';
  elsif p_kind = 'competency' then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', c.id, 'tenant_id', c.tenant_id, 'code', c.competency_code, 'name', c.competency_name
    ) order by c.competency_code), '[]'::jsonb) into v_result
    from public.hr_competency c
    where (p_tenant_id is null or c.tenant_id = p_tenant_id) and c.enabled;
  else
    raise exception '不支持的学习发展选项类型';
  end if;
  return v_result;
end
$$;


ALTER FUNCTION "public"."hr_list_learning_options_secure"("p_kind" "text", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_list_learning_records_secure("text", integer, integer, "text", "text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_learning_records_secure"("p_kind" "text", "p_from" integer DEFAULT 0, "p_to" integer DEFAULT 19, "p_keyword" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_offset integer := greatest(coalesce(p_from, 0), 0);
  v_limit integer := least(500, greatest(coalesce(p_to, 19) - greatest(coalesce(p_from, 0), 0) + 1, 1));
  v_keyword text := nullif(btrim(p_keyword), '');
  v_result jsonb;
begin
  if p_kind not in ('plan', 'course', 'session', 'enrollment', 'certificate', 'course_competency') then
    raise exception '不支持的学习发展记录类型';
  end if;
  if not app_private.can_execute_business_action('HrTalentDevelopment', 'Hr:Talent:View', null, false) then
    raise exception '当前账号没有查看学习发展工作台的权限' using errcode = '42501';
  end if;
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;

  if p_kind = 'plan' then
    with filtered as materialized (
      select p.*, owner.employee_no owner_no, owner.employee_name owner_name,
        (select count(*) from public.hr_learning_session s where s.plan_id = p.id) session_count,
        (select count(*) from public.hr_training_enrollment e where e.plan_id = p.id and e.session_id is not null) learner_count
      from public.hr_training_plan p
      left join public.mdm_employee owner on owner.id = p.owner_employee_id and owner.tenant_id = p.tenant_id
      where (p_tenant_id is null or p.tenant_id = p_tenant_id)
        and (p_status is null or p.status = p_status)
        and (v_keyword is null or p.plan_code ilike '%' || v_keyword || '%'
          or p.plan_name ilike '%' || v_keyword || '%' or owner.employee_name ilike '%' || v_keyword || '%')
    ), paged as (
      select * from filtered order by start_date desc, plan_code offset v_offset limit v_limit
    )
    select jsonb_build_object(
      'records', coalesce(jsonb_agg(
        (to_jsonb(paged) - 'owner_no' - 'owner_name') || jsonb_build_object(
          'owner', case when owner_employee_id is null then null else jsonb_build_object(
            'id', owner_employee_id, 'code', owner_no, 'name', owner_name
          ) end
        ) order by start_date desc, plan_code
      ), '[]'::jsonb),
      'total', (select count(*) from filtered)
    ) into v_result from paged;
    return coalesce(v_result, jsonb_build_object('records', '[]'::jsonb, 'total', 0));
  end if;

  if p_kind = 'course' then
    with filtered as materialized (
      select c.*,
        (select count(*) from public.hr_learning_session s where s.course_id = c.id) session_count,
        (select count(*) from public.hr_learning_course_competency cc where cc.course_id = c.id) competency_count
      from public.hr_learning_course c
      where (p_tenant_id is null or c.tenant_id = p_tenant_id)
        and (p_status is null or c.status = p_status)
        and (v_keyword is null or c.course_code ilike '%' || v_keyword || '%'
          or c.course_name ilike '%' || v_keyword || '%' or c.provider_name ilike '%' || v_keyword || '%')
    ), paged as (
      select * from filtered order by course_code offset v_offset limit v_limit
    )
    select jsonb_build_object(
      'records', coalesce(jsonb_agg(to_jsonb(paged) order by course_code), '[]'::jsonb),
      'total', (select count(*) from filtered)
    ) into v_result from paged;
    return coalesce(v_result, jsonb_build_object('records', '[]'::jsonb, 'total', 0));
  end if;

  if p_kind = 'session' then
    with filtered as materialized (
      select s.*, p.plan_code, p.plan_name, c.course_code, c.course_name,
        (select count(*) from public.hr_training_enrollment e where e.session_id = s.id) enrollment_count,
        (select count(*) from public.hr_training_enrollment e where e.session_id = s.id and e.status = 'passed') passed_count
      from public.hr_learning_session s
      join public.hr_training_plan p on p.id = s.plan_id and p.tenant_id = s.tenant_id
      join public.hr_learning_course c on c.id = s.course_id and c.tenant_id = s.tenant_id
      where (p_tenant_id is null or s.tenant_id = p_tenant_id)
        and (p_status is null or s.status = p_status)
        and (v_keyword is null or s.session_code ilike '%' || v_keyword || '%'
          or p.plan_name ilike '%' || v_keyword || '%' or c.course_name ilike '%' || v_keyword || '%'
          or s.instructor_name ilike '%' || v_keyword || '%')
    ), paged as (
      select * from filtered order by start_at desc, session_code offset v_offset limit v_limit
    )
    select jsonb_build_object(
      'records', coalesce(jsonb_agg(
        (to_jsonb(paged) - 'plan_code' - 'plan_name' - 'course_code' - 'course_name')
        || jsonb_build_object(
          'plan', jsonb_build_object('id', plan_id, 'code', plan_code, 'name', plan_name),
          'course', jsonb_build_object('id', course_id, 'code', course_code, 'name', course_name)
        ) order by start_at desc, session_code
      ), '[]'::jsonb),
      'total', (select count(*) from filtered)
    ) into v_result from paged;
    return coalesce(v_result, jsonb_build_object('records', '[]'::jsonb, 'total', 0));
  end if;

  if p_kind = 'enrollment' then
    with filtered as materialized (
      select e.*, employee.employee_no, employee.employee_name,
        s.session_code, s.start_at, s.end_at,
        p.plan_code, p.plan_name, c.id course_id, c.course_code, c.course_name,
        nominator.employee_no nominator_no, nominator.employee_name nominator_name
      from public.hr_training_enrollment e
      join public.mdm_employee employee on employee.id = e.employee_id and employee.tenant_id = e.tenant_id
      left join public.hr_learning_session s on s.id = e.session_id and s.tenant_id = e.tenant_id
      join public.hr_training_plan p on p.id = e.plan_id and p.tenant_id = e.tenant_id
      left join public.hr_learning_course c on c.id = s.course_id and c.tenant_id = e.tenant_id
      left join public.mdm_employee nominator on nominator.id = e.nominated_by_employee_id and nominator.tenant_id = e.tenant_id
      where e.session_id is not null and (p_tenant_id is null or e.tenant_id = p_tenant_id)
        and (p_status is null or e.status = p_status)
        and (v_keyword is null or employee.employee_no ilike '%' || v_keyword || '%'
          or employee.employee_name ilike '%' || v_keyword || '%' or s.session_code ilike '%' || v_keyword || '%'
          or c.course_name ilike '%' || v_keyword || '%')
    ), paged as (
      select * from filtered order by start_at desc, employee_no offset v_offset limit v_limit
    )
    select jsonb_build_object(
      'records', coalesce(jsonb_agg(
        (to_jsonb(paged) - 'employee_no' - 'employee_name' - 'session_code' - 'start_at' - 'end_at'
          - 'plan_code' - 'plan_name' - 'course_code' - 'course_name' - 'nominator_no' - 'nominator_name')
        || jsonb_build_object(
          'employee', jsonb_build_object('id', employee_id, 'code', employee_no, 'name', employee_name),
          'session', jsonb_build_object('id', session_id, 'code', session_code, 'start_at', start_at, 'end_at', end_at),
          'plan', jsonb_build_object('id', plan_id, 'code', plan_code, 'name', plan_name),
          'course', jsonb_build_object('id', course_id, 'code', course_code, 'name', course_name),
          'nominator', case when nominated_by_employee_id is null then null else jsonb_build_object(
            'id', nominated_by_employee_id, 'code', nominator_no, 'name', nominator_name
          ) end
        ) order by start_at desc, employee_no
      ), '[]'::jsonb),
      'total', (select count(*) from filtered)
    ) into v_result from paged;
    return coalesce(v_result, jsonb_build_object('records', '[]'::jsonb, 'total', 0));
  end if;

  if p_kind = 'certificate' then
    with filtered as materialized (
      select cert.*, employee.employee_no, employee.employee_name, c.course_code, c.course_name
      from public.hr_learning_certificate cert
      join public.mdm_employee employee on employee.id = cert.employee_id and employee.tenant_id = cert.tenant_id
      join public.hr_learning_course c on c.id = cert.course_id and c.tenant_id = cert.tenant_id
      where (p_tenant_id is null or cert.tenant_id = p_tenant_id)
        and (p_status is null or cert.status = p_status)
        and (v_keyword is null or cert.certificate_no ilike '%' || v_keyword || '%'
          or employee.employee_no ilike '%' || v_keyword || '%' or employee.employee_name ilike '%' || v_keyword || '%'
          or c.course_name ilike '%' || v_keyword || '%')
    ), paged as (
      select * from filtered order by issued_on desc, certificate_no offset v_offset limit v_limit
    )
    select jsonb_build_object(
      'records', coalesce(jsonb_agg(
        (to_jsonb(paged) - 'employee_no' - 'employee_name' - 'course_code' - 'course_name')
        || jsonb_build_object(
          'employee', jsonb_build_object('id', employee_id, 'code', employee_no, 'name', employee_name),
          'course', jsonb_build_object('id', course_id, 'code', course_code, 'name', course_name)
        ) order by issued_on desc, certificate_no
      ), '[]'::jsonb),
      'total', (select count(*) from filtered)
    ) into v_result from paged;
    return coalesce(v_result, jsonb_build_object('records', '[]'::jsonb, 'total', 0));
  end if;

  with filtered as materialized (
    select cc.*, c.course_code, c.course_name, competency.competency_code, competency.competency_name
    from public.hr_learning_course_competency cc
    join public.hr_learning_course c on c.id = cc.course_id and c.tenant_id = cc.tenant_id
    join public.hr_competency competency on competency.id = cc.competency_id and competency.tenant_id = cc.tenant_id
    where (p_tenant_id is null or cc.tenant_id = p_tenant_id)
      and (v_keyword is null or c.course_code ilike '%' || v_keyword || '%'
        or c.course_name ilike '%' || v_keyword || '%' or competency.competency_code ilike '%' || v_keyword || '%'
        or competency.competency_name ilike '%' || v_keyword || '%')
  ), paged as (
    select * from filtered order by course_code, competency_code offset v_offset limit v_limit
  )
  select jsonb_build_object(
    'records', coalesce(jsonb_agg(
      (to_jsonb(paged) - 'course_code' - 'course_name' - 'competency_code' - 'competency_name')
      || jsonb_build_object(
        'course', jsonb_build_object('id', course_id, 'code', course_code, 'name', course_name),
        'competency', jsonb_build_object('id', competency_id, 'code', competency_code, 'name', competency_name)
      ) order by course_code, competency_code
    ), '[]'::jsonb),
    'total', (select count(*) from filtered)
  ) into v_result from paged;
  return coalesce(v_result, jsonb_build_object('records', '[]'::jsonb, 'total', 0));
end
$$;


ALTER FUNCTION "public"."hr_list_learning_records_secure"("p_kind" "text", "p_from" integer, "p_to" integer, "p_keyword" "text", "p_status" "text", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_list_lifecycle_options_secure("text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_lifecycle_options_secure"("p_kind" "text", "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
begin
  if p_kind not in ('case', 'template', 'employee', 'organization', 'position', 'handoff') then
    raise exception '不支持的生命周期选项类型';
  end if;
  if not app_private.can_execute_business_action('HrLifecycle', 'Hr:Lifecycle:View', null, false) then
    raise exception '当前账号没有查看生命周期选项的权限' using errcode = '42501';
  end if;
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;

  if p_kind = 'case' then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', c.id, 'tenant_id', c.tenant_id, 'code', c.case_no, 'name', e.employee_name,
      'status', c.execution_status, 'case_type', c.case_type, 'employee_id', c.employee_id
    ) order by c.planned_effective_date desc)
    from public.hr_lifecycle_case c
    join public.mdm_employee e on e.id = c.employee_id and e.tenant_id = c.tenant_id
    where (p_tenant_id is null or c.tenant_id = p_tenant_id)
      and c.execution_status in ('planning', 'in_progress', 'ready')), '[]'::jsonb);
  end if;
  if p_kind = 'template' then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', t.id, 'tenant_id', t.tenant_id, 'code', t.template_code, 'name', t.template_name,
      'status', t.status, 'case_type', t.case_type
    ) order by t.case_type, t.is_default desc, t.template_name)
    from public.hr_lifecycle_template t
    where (p_tenant_id is null or t.tenant_id = p_tenant_id)), '[]'::jsonb);
  end if;
  if p_kind = 'employee' then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', e.id, 'tenant_id', e.tenant_id, 'code', e.employee_no, 'name', e.employee_name,
      'organization_id', e.organization_id, 'position_id', e.position_id, 'status', e.employment_status
    ) order by e.employee_no)
    from public.mdm_employee e
    where (p_tenant_id is null or e.tenant_id = p_tenant_id)
      and e.employment_status <> 'terminated'), '[]'::jsonb);
  end if;
  if p_kind = 'organization' then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', o.id, 'tenant_id', o.tenant_id, 'code', o.organization_code, 'name', o.organization_name,
      'status', o.status
    ) order by o.organization_code)
    from public.mdm_organization o
    where (p_tenant_id is null or o.tenant_id = p_tenant_id) and o.status = '1'), '[]'::jsonb);
  end if;
  if p_kind = 'position' then
    return coalesce((select jsonb_agg(jsonb_build_object(
      'id', p.id, 'tenant_id', p.tenant_id, 'code', p.position_code, 'name', p.position_name,
      'organization_id', p.organization_id, 'status', case when p.enabled then '1' else '0' end
    ) order by p.position_code)
    from public.mdm_position p
    where (p_tenant_id is null or p.tenant_id = p_tenant_id) and p.enabled), '[]'::jsonb);
  end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
    'id', h.id, 'tenant_id', h.tenant_id, 'code', c.candidate_name, 'name', e.employee_name,
    'status', h.status, 'employee_id', h.onboard_employee_id,
    'organization_id', h.organization_id, 'position_id', h.position_id
  ) order by h.completed_at desc)
  from public.hr_recruitment_handoff h
  join public.hr_candidate c on c.id = h.candidate_id and c.tenant_id = h.tenant_id
  join public.mdm_employee e on e.id = h.onboard_employee_id and e.tenant_id = h.tenant_id
  where (p_tenant_id is null or h.tenant_id = p_tenant_id)
    and h.status = 'completed'
    and not exists (select 1 from public.hr_lifecycle_case lifecycle
      where lifecycle.tenant_id = h.tenant_id
        and lifecycle.source_type = 'recruitment_handoff' and lifecycle.source_id = h.id)), '[]'::jsonb);
end
$$;


ALTER FUNCTION "public"."hr_list_lifecycle_options_secure"("p_kind" "text", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_list_lifecycle_records_secure("text", integer, integer, "text", "text", "uuid", "uuid", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_lifecycle_records_secure"("p_kind" "text", "p_from" integer DEFAULT 0, "p_to" integer DEFAULT 19, "p_keyword" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_case_id" "uuid" DEFAULT NULL::"uuid", "p_template_id" "uuid" DEFAULT NULL::"uuid", "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_offset integer := greatest(coalesce(p_from, 0), 0);
  v_limit integer := least(500, greatest(coalesce(p_to, 19) - greatest(coalesce(p_from, 0), 0) + 1, 1));
  v_keyword text := nullif(btrim(p_keyword), '');
  v_result jsonb;
begin
  if p_kind not in ('case', 'task', 'template', 'template_task') then
    raise exception '不支持的生命周期记录类型';
  end if;
  if not app_private.can_execute_business_action('HrLifecycle', 'Hr:Lifecycle:View', null, false) then
    raise exception '当前账号没有查看入转调离工作台的权限' using errcode = '42501';
  end if;
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;

  if p_kind = 'case' then
    with filtered as materialized (
      select c.*, e.employee_no, e.employee_name,
        o.organization_code, o.organization_name,
        p.position_code, p.position_name,
        template.template_code, template.template_name,
        owner.employee_no owner_no, owner.employee_name owner_name,
        buddy.employee_no buddy_no, buddy.employee_name buddy_name,
        coalesce(task_stats.task_count, 0) task_count,
        coalesce(task_stats.closed_count, 0) closed_task_count,
        coalesce(task_stats.open_blocking_count, 0) open_blocking_task_count,
        coalesce(task_stats.overdue_count, 0) overdue_task_count
      from public.hr_lifecycle_case c
      join public.mdm_employee e on e.id = c.employee_id and e.tenant_id = c.tenant_id
      left join public.mdm_organization o on o.id = c.organization_id and o.tenant_id = c.tenant_id
      left join public.mdm_position p on p.id = c.position_id and p.tenant_id = c.tenant_id
      left join public.hr_lifecycle_template template on template.id = c.template_id and template.tenant_id = c.tenant_id
      left join public.mdm_employee owner on owner.id = c.owner_employee_id and owner.tenant_id = c.tenant_id
      left join public.mdm_employee buddy on buddy.id = c.buddy_employee_id and buddy.tenant_id = c.tenant_id
      left join lateral (
        select count(*)::integer task_count,
          count(*) filter (where t.status in ('completed', 'skipped'))::integer closed_count,
          count(*) filter (where t.blocking and t.status in ('pending', 'processing'))::integer open_blocking_count,
          count(*) filter (where t.status in ('pending', 'processing') and t.due_date < current_date)::integer overdue_count
        from public.hr_lifecycle_task t
        where t.lifecycle_case_id = c.id and t.tenant_id = c.tenant_id
      ) task_stats on true
      where (p_tenant_id is null or c.tenant_id = p_tenant_id)
        and (p_status is null or c.execution_status = p_status)
        and (v_keyword is null or c.case_no ilike '%' || v_keyword || '%'
          or e.employee_no ilike '%' || v_keyword || '%'
          or e.employee_name ilike '%' || v_keyword || '%'
          or o.organization_name ilike '%' || v_keyword || '%'
          or p.position_name ilike '%' || v_keyword || '%')
    ), paged as (
      select * from filtered
      order by case when execution_status in ('planning', 'in_progress', 'ready') then 0 else 1 end,
        planned_effective_date, create_time desc
      offset v_offset limit v_limit
    )
    select jsonb_build_object(
      'records', coalesce(jsonb_agg(
        (to_jsonb(paged) - 'employee_no' - 'employee_name' - 'organization_code' - 'organization_name'
          - 'position_code' - 'position_name' - 'template_code' - 'template_name'
          - 'owner_no' - 'owner_name' - 'buddy_no' - 'buddy_name')
        || jsonb_build_object(
          'employee', jsonb_build_object('id', employee_id, 'code', employee_no, 'name', employee_name),
          'organization', case when organization_id is null then null else jsonb_build_object('id', organization_id, 'code', organization_code, 'name', organization_name) end,
          'position', case when position_id is null then null else jsonb_build_object('id', position_id, 'code', position_code, 'name', position_name) end,
          'template', case when template_id is null then null else jsonb_build_object('id', template_id, 'code', template_code, 'name', template_name) end,
          'owner', case when owner_employee_id is null then null else jsonb_build_object('id', owner_employee_id, 'code', owner_no, 'name', owner_name) end,
          'buddy', case when buddy_employee_id is null then null else jsonb_build_object('id', buddy_employee_id, 'code', buddy_no, 'name', buddy_name) end
        )
        order by case when execution_status in ('planning', 'in_progress', 'ready') then 0 else 1 end,
          planned_effective_date, create_time desc
      ), '[]'::jsonb),
      'total', (select count(*) from filtered)
    ) into v_result from paged;
    return coalesce(v_result, jsonb_build_object('records', '[]'::jsonb, 'total', 0));
  end if;

  if p_kind = 'task' then
    with filtered as materialized (
      select t.*, c.case_no, c.case_type, c.execution_status, c.employee_id,
        e.employee_no, e.employee_name, owner.employee_no owner_no, owner.employee_name owner_name
      from public.hr_lifecycle_task t
      join public.hr_lifecycle_case c on c.id = t.lifecycle_case_id and c.tenant_id = t.tenant_id
      join public.mdm_employee e on e.id = c.employee_id and e.tenant_id = c.tenant_id
      left join public.mdm_employee owner on owner.id = t.owner_employee_id and owner.tenant_id = t.tenant_id
      where (p_tenant_id is null or t.tenant_id = p_tenant_id)
        and (p_case_id is null or t.lifecycle_case_id = p_case_id)
        and (p_status is null or t.status = p_status)
        and (v_keyword is null or t.task_name ilike '%' || v_keyword || '%'
          or t.description ilike '%' || v_keyword || '%'
          or c.case_no ilike '%' || v_keyword || '%'
          or e.employee_name ilike '%' || v_keyword || '%')
    ), paged as (
      select * from filtered
      order by case when status in ('pending', 'processing') then 0 else 1 end,
        due_date nulls last, sort, task_name
      offset v_offset limit v_limit
    )
    select jsonb_build_object(
      'records', coalesce(jsonb_agg(
        (to_jsonb(paged) - 'case_no' - 'case_type' - 'execution_status' - 'employee_id'
          - 'employee_no' - 'employee_name' - 'owner_no' - 'owner_name')
        || jsonb_build_object(
          'case', jsonb_build_object('id', lifecycle_case_id, 'code', case_no, 'name', employee_name,
            'case_type', case_type, 'execution_status', execution_status, 'employee_id', employee_id),
          'employee', jsonb_build_object('id', employee_id, 'code', employee_no, 'name', employee_name),
          'owner', case when owner_employee_id is null then null else jsonb_build_object('id', owner_employee_id, 'code', owner_no, 'name', owner_name) end
        )
        order by case when status in ('pending', 'processing') then 0 else 1 end,
          due_date nulls last, sort, task_name
      ), '[]'::jsonb),
      'total', (select count(*) from filtered)
    ) into v_result from paged;
    return coalesce(v_result, jsonb_build_object('records', '[]'::jsonb, 'total', 0));
  end if;

  if p_kind = 'template' then
    with filtered as materialized (
      select t.*,
        (select count(*) from public.hr_lifecycle_template_task task
          where task.template_id = t.id and task.tenant_id = t.tenant_id) task_count,
        (select count(*) from public.hr_lifecycle_case c
          where c.template_id = t.id and c.tenant_id = t.tenant_id) usage_count
      from public.hr_lifecycle_template t
      where (p_tenant_id is null or t.tenant_id = p_tenant_id)
        and (p_status is null or t.status = p_status)
        and (v_keyword is null or t.template_code ilike '%' || v_keyword || '%'
          or t.template_name ilike '%' || v_keyword || '%'
          or t.description ilike '%' || v_keyword || '%')
    ), paged as (
      select * from filtered order by is_default desc, case_type, template_name
      offset v_offset limit v_limit
    )
    select jsonb_build_object(
      'records', coalesce(jsonb_agg(to_jsonb(paged) order by is_default desc, case_type, template_name), '[]'::jsonb),
      'total', (select count(*) from filtered)
    ) into v_result from paged;
    return coalesce(v_result, jsonb_build_object('records', '[]'::jsonb, 'total', 0));
  end if;

  with filtered as materialized (
    select task.*, template.template_code, template.template_name, template.case_type, template.status template_status
    from public.hr_lifecycle_template_task task
    join public.hr_lifecycle_template template on template.id = task.template_id and template.tenant_id = task.tenant_id
    where (p_tenant_id is null or task.tenant_id = p_tenant_id)
      and (p_template_id is null or task.template_id = p_template_id)
      and (v_keyword is null or task.task_name ilike '%' || v_keyword || '%'
        or task.description ilike '%' || v_keyword || '%'
        or template.template_name ilike '%' || v_keyword || '%')
  ), paged as (
    select * from filtered order by template_name, sort, task_name offset v_offset limit v_limit
  )
  select jsonb_build_object(
    'records', coalesce(jsonb_agg(
      (to_jsonb(paged) - 'template_code' - 'template_name' - 'case_type' - 'template_status')
      || jsonb_build_object('template', jsonb_build_object(
        'id', template_id, 'code', template_code, 'name', template_name,
        'case_type', case_type, 'status', template_status
      )) order by template_name, sort, task_name
    ), '[]'::jsonb),
    'total', (select count(*) from filtered)
  ) into v_result from paged;
  return coalesce(v_result, jsonb_build_object('records', '[]'::jsonb, 'total', 0));
end
$$;


ALTER FUNCTION "public"."hr_list_lifecycle_records_secure"("p_kind" "text", "p_from" integer, "p_to" integer, "p_keyword" "text", "p_status" "text", "p_case_id" "uuid", "p_template_id" "uuid", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_list_organization_design_options_secure("text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_organization_design_options_secure"("p_kind" "text", "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_tenant_id uuid:=app_private.current_user_tenant_id(); v_result jsonb:='[]'::jsonb;
begin
  if p_kind not in ('organization','employee','scenario') then raise exception '不支持的组织变革选项类型'; end if;
  if auth.uid() is null or not app_private.can_execute_business_action(
    'HrOrganizationDesign','Hr:OrganizationDesign:View',null,false
  ) then raise exception '当前账号没有查看组织变革方案的权限' using errcode='42501'; end if;
  if not app_private.is_platform_super() then p_tenant_id:=v_tenant_id; end if;
  if p_kind='organization' then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id',o.id,'tenant_id',o.tenant_id,'code',o.organization_code,'name',o.organization_name,
      'parent_id',o.parent_id,'organization_type',o.organization_type,'status',o.status
    ) order by o.sort,o.organization_name),'[]'::jsonb) into v_result
    from public.mdm_organization o where (p_tenant_id is null or o.tenant_id=p_tenant_id) and o.status='1';
  elsif p_kind='employee' then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id',e.id,'tenant_id',e.tenant_id,'code',e.employee_no,'name',e.employee_name,
      'organization_id',e.organization_id,'status',e.employment_status
    ) order by e.employee_name),'[]'::jsonb) into v_result
    from public.mdm_employee e where (p_tenant_id is null or e.tenant_id=p_tenant_id)
      and e.employment_status in ('probation','active','leave');
  else
    select coalesce(jsonb_agg(jsonb_build_object(
      'id',s.id,'tenant_id',s.tenant_id,'code',s.scenario_code,'name',s.scenario_name,
      'status',s.status,'effective_date',s.effective_date
    ) order by s.effective_date desc,s.scenario_name),'[]'::jsonb) into v_result
    from public.hr_organization_design_scenario s where (p_tenant_id is null or s.tenant_id=p_tenant_id)
      and s.status in ('draft','rejected');
  end if;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."hr_list_organization_design_options_secure"("p_kind" "text", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_list_organization_design_records_secure("text", integer, integer, "text", "text", "uuid", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_organization_design_records_secure"("p_kind" "text", "p_from" integer DEFAULT 0, "p_to" integer DEFAULT 19, "p_keyword" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_scenario_id" "uuid" DEFAULT NULL::"uuid", "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    SET "TimeZone" TO 'Asia/Shanghai'
    AS $$
declare
  v_tenant_id uuid:=app_private.current_user_tenant_id();
  v_offset integer:=greatest(coalesce(p_from,0),0);
  v_limit integer:=least(500,greatest(coalesce(p_to,19)-greatest(coalesce(p_from,0),0)+1,1));
  v_keyword text:=nullif(btrim(p_keyword),''); v_total integer:=0; v_records jsonb:='[]'::jsonb;
begin
  if p_kind not in ('scenario','change') then raise exception '不支持的组织变革记录类型'; end if;
  if auth.uid() is null or not app_private.can_execute_business_action(
    'HrOrganizationDesign','Hr:OrganizationDesign:View',null,false
  ) then raise exception '当前账号没有查看组织变革方案的权限' using errcode='42501'; end if;
  if not app_private.is_platform_super() then p_tenant_id:=v_tenant_id; end if;

  if p_kind='scenario' then
    select count(*)::integer into v_total from public.hr_organization_design_scenario s
    left join public.mdm_employee owner_employee on owner_employee.id=s.owner_employee_id
    where (p_tenant_id is null or s.tenant_id=p_tenant_id)
      and (p_status is null or p_status='' or s.status=p_status)
      and (v_keyword is null or s.scenario_code ilike '%'||v_keyword||'%'
        or s.scenario_name ilike '%'||v_keyword||'%' or s.objective ilike '%'||v_keyword||'%'
        or owner_employee.employee_name ilike '%'||v_keyword||'%');
    select coalesce(jsonb_agg(row_data order by effective_date desc,update_time desc),'[]'::jsonb)
    into v_records from (
      select s.effective_date,s.update_time,jsonb_build_object(
        'id',s.id,'tenant_id',s.tenant_id,'scenario_code',s.scenario_code,
        'scenario_name',s.scenario_name,'objective',s.objective,'effective_date',s.effective_date,
        'owner_employee_id',s.owner_employee_id,'owner_employee_name',owner_employee.employee_name,
        'owner_employee_no',owner_employee.employee_no,'status',s.status,'risk_level',s.risk_level,
        'submission_note',s.submission_note,'decision_note',s.decision_note,
        'baseline_captured_at',s.baseline_captured_at,'submitted_at',s.submitted_at,
        'submitted_by',s.submitted_by,'decided_at',s.decided_at,'decided_by',s.decided_by,
        'handed_off_at',s.handed_off_at,'handed_off_by',s.handed_off_by,'version',s.version,
        'change_count',(select count(*) from public.hr_organization_design_change c where c.scenario_id=s.id),
        'impacted_employee_count',(select coalesce(sum(c.impacted_employee_count),0) from public.hr_organization_design_change c where c.scenario_id=s.id),
        'impacted_position_count',(select coalesce(sum(c.impacted_position_count),0) from public.hr_organization_design_change c where c.scenario_id=s.id),
        'impacted_security_user_count',(select coalesce(sum(c.impacted_security_user_count),0) from public.hr_organization_design_change c where c.scenario_id=s.id),
        'impacted_scope_count',(select coalesce(sum(c.impacted_scope_count),0) from public.hr_organization_design_change c where c.scenario_id=s.id),
        'create_time',s.create_time,'update_time',s.update_time
      ) row_data
      from public.hr_organization_design_scenario s
      left join public.mdm_employee owner_employee on owner_employee.id=s.owner_employee_id
      where (p_tenant_id is null or s.tenant_id=p_tenant_id)
        and (p_status is null or p_status='' or s.status=p_status)
        and (v_keyword is null or s.scenario_code ilike '%'||v_keyword||'%'
          or s.scenario_name ilike '%'||v_keyword||'%' or s.objective ilike '%'||v_keyword||'%'
          or owner_employee.employee_name ilike '%'||v_keyword||'%')
      offset v_offset limit v_limit
    ) rows;
  else
    select count(*)::integer into v_total from public.hr_organization_design_change c
    join public.hr_organization_design_scenario s on s.id=c.scenario_id
    where (p_tenant_id is null or c.tenant_id=p_tenant_id)
      and (p_scenario_id is null or c.scenario_id=p_scenario_id)
      and (p_status is null or p_status='' or c.change_type=p_status)
      and (v_keyword is null or c.current_code ilike '%'||v_keyword||'%'
        or c.current_name ilike '%'||v_keyword||'%' or c.proposed_code ilike '%'||v_keyword||'%'
        or c.proposed_name ilike '%'||v_keyword||'%' or c.rationale ilike '%'||v_keyword||'%'
        or s.scenario_name ilike '%'||v_keyword||'%');
    select coalesce(jsonb_agg(row_data order by sequence,create_time),'[]'::jsonb)
    into v_records from (
      select c.sequence,c.create_time,jsonb_build_object(
        'id',c.id,'tenant_id',c.tenant_id,'scenario_id',c.scenario_id,
        'scenario_code',s.scenario_code,'scenario_name',s.scenario_name,'scenario_status',s.status,
        'change_type',c.change_type,'organization_id',c.organization_id,
        'current_parent_id',c.current_parent_id,'current_code',c.current_code,
        'current_name',c.current_name,'current_type',c.current_type,
        'proposed_parent_id',c.proposed_parent_id,'proposed_parent_name',proposed_parent.organization_name,
        'proposed_code',c.proposed_code,'proposed_name',c.proposed_name,
        'proposed_type',c.proposed_type,'proposed_status',c.proposed_status,
        'rationale',c.rationale,'sequence',c.sequence,
        'impacted_employee_count',c.impacted_employee_count,
        'impacted_position_count',c.impacted_position_count,
        'impacted_requisition_count',c.impacted_requisition_count,
        'impacted_security_user_count',c.impacted_security_user_count,
        'impacted_scope_count',c.impacted_scope_count,'impact_captured_at',c.impact_captured_at,
        'create_time',c.create_time,'update_time',c.update_time
      ) row_data
      from public.hr_organization_design_change c
      join public.hr_organization_design_scenario s on s.id=c.scenario_id
      left join public.mdm_organization proposed_parent on proposed_parent.id=c.proposed_parent_id
      where (p_tenant_id is null or c.tenant_id=p_tenant_id)
        and (p_scenario_id is null or c.scenario_id=p_scenario_id)
        and (p_status is null or p_status='' or c.change_type=p_status)
        and (v_keyword is null or c.current_code ilike '%'||v_keyword||'%'
          or c.current_name ilike '%'||v_keyword||'%' or c.proposed_code ilike '%'||v_keyword||'%'
          or c.proposed_name ilike '%'||v_keyword||'%' or c.rationale ilike '%'||v_keyword||'%'
          or s.scenario_name ilike '%'||v_keyword||'%')
      offset v_offset limit v_limit
    ) rows;
  end if;
  return jsonb_build_object('records',v_records,'total',v_total);
end;
$$;


ALTER FUNCTION "public"."hr_list_organization_design_records_secure"("p_kind" "text", "p_from" integer, "p_to" integer, "p_keyword" "text", "p_status" "text", "p_scenario_id" "uuid", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_list_performance_options_secure("text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_performance_options_secure"("p_kind" "text", "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
begin
  if p_kind not in ('cycle','review','employee','organization','calibration') then
    raise exception '不支持的绩效选项类型';
  end if;
  if not app_private.can_execute_business_action('HrPerformance','Hr:Performance:View',null,false) then
    raise exception '当前账号没有查看绩效选项的权限' using errcode='42501';
  end if;
  if not app_private.is_platform_super() then p_tenant_id:=v_tenant_id; end if;

  if p_kind='cycle' then
    return (select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'tenant_id',c.tenant_id,'code',c.cycle_code,'name',c.cycle_name,'status',c.status) order by c.start_date desc),'[]'::jsonb)
      from public.hr_performance_cycle c where (p_tenant_id is null or c.tenant_id=p_tenant_id) and c.status<>'cancelled');
  end if;
  if p_kind='review' then
    return (select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'tenant_id',r.tenant_id,'name',e.employee_name,'code',e.employee_no,'status',r.status,'cycle_id',r.cycle_id) order by e.employee_name),'[]'::jsonb)
      from public.hr_performance_review r join public.mdm_employee e on e.id=r.employee_id and e.tenant_id=r.tenant_id
      where (p_tenant_id is null or r.tenant_id=p_tenant_id) and r.status<>'cancelled');
  end if;
  if p_kind='employee' then
    return (select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'tenant_id',e.tenant_id,'code',e.employee_no,'name',e.employee_name,'organization_id',e.organization_id) order by e.employee_name),'[]'::jsonb)
      from public.mdm_employee e where (p_tenant_id is null or e.tenant_id=p_tenant_id)
        and e.employment_status not in ('left','terminated'));
  end if;
  if p_kind='organization' then
    return (select coalesce(jsonb_agg(jsonb_build_object('id',o.id,'tenant_id',o.tenant_id,'code',o.organization_code,'name',o.organization_name) order by o.sort,o.organization_name),'[]'::jsonb)
      from public.mdm_organization o where (p_tenant_id is null or o.tenant_id=p_tenant_id) and o.status='1');
  end if;
  return (select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'tenant_id',s.tenant_id,'code',s.session_no,'name',s.session_name,'status',s.status,'cycle_id',s.cycle_id) order by s.scheduled_at desc),'[]'::jsonb)
    from public.hr_performance_calibration_session s where (p_tenant_id is null or s.tenant_id=p_tenant_id) and s.status='in_progress');
end
$$;


ALTER FUNCTION "public"."hr_list_performance_options_secure"("p_kind" "text", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_list_performance_records_secure("text", integer, integer, "text", "text", "uuid", "uuid", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_performance_records_secure"("p_kind" "text", "p_from" integer DEFAULT 0, "p_to" integer DEFAULT 19, "p_keyword" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_cycle_id" "uuid" DEFAULT NULL::"uuid", "p_session_id" "uuid" DEFAULT NULL::"uuid", "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_offset integer := greatest(coalesce(p_from, 0), 0);
  v_limit integer := least(500, greatest(coalesce(p_to, 19) - greatest(coalesce(p_from, 0), 0) + 1, 1));
  v_keyword text := nullif(btrim(p_keyword), '');
  v_result jsonb;
begin
  if p_kind not in ('cycle', 'review', 'goal', 'check_in', 'calibration', 'calibration_item') then
    raise exception '不支持的绩效记录类型';
  end if;
  if not app_private.can_execute_business_action('HrPerformance', 'Hr:Performance:View', null, false) then
    raise exception '当前账号没有查看绩效管理工作台的权限' using errcode = '42501';
  end if;
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;

  if p_kind = 'cycle' then
    with filtered as materialized (
      select c.*, owner.employee_no owner_no, owner.employee_name owner_name,
        (select count(*) from public.hr_performance_review r where r.cycle_id=c.id and r.tenant_id=c.tenant_id and r.status<>'cancelled') review_count,
        (select count(*) from public.hr_performance_review r where r.cycle_id=c.id and r.tenant_id=c.tenant_id and r.status='completed') completed_count,
        (select count(*) from public.hr_performance_review r where r.cycle_id=c.id and r.tenant_id=c.tenant_id and r.status='confirmed') pending_calibration_count
      from public.hr_performance_cycle c
      left join public.mdm_employee owner on owner.id=c.owner_employee_id and owner.tenant_id=c.tenant_id
      where (p_tenant_id is null or c.tenant_id=p_tenant_id)
        and (p_status is null or c.status=p_status)
        and (v_keyword is null or c.cycle_code ilike '%'||v_keyword||'%'
          or c.cycle_name ilike '%'||v_keyword||'%' or owner.employee_name ilike '%'||v_keyword||'%')
    ), paged as (
      select * from filtered order by start_date desc, cycle_code offset v_offset limit v_limit
    )
    select jsonb_build_object(
      'records', coalesce(jsonb_agg((to_jsonb(paged)-'owner_no'-'owner_name') || jsonb_build_object(
        'owner', case when owner_employee_id is null then null else jsonb_build_object('id',owner_employee_id,'code',owner_no,'name',owner_name) end
      ) order by start_date desc, cycle_code), '[]'::jsonb),
      'total', (select count(*) from filtered)
    ) into v_result from paged;
    return coalesce(v_result, jsonb_build_object('records','[]'::jsonb,'total',0));
  end if;

  if p_kind = 'review' then
    with latest_check_in as (
      select distinct on (c.review_id) c.review_id, c.check_in_date, c.risk_status, c.progress_percent
      from public.hr_performance_check_in c
      order by c.review_id, c.check_in_date desc, c.create_time desc
    ), filtered as materialized (
      select r.*, c.cycle_code, c.cycle_name, e.employee_no, e.employee_name,
        e.organization_id, o.organization_name, reviewer.employee_no reviewer_no,
        reviewer.employee_name reviewer_name,
        coalesce(g.goal_count,0) goal_count, coalesce(g.goal_weight,0) goal_weight,
        ci.check_in_date last_check_in_date, ci.risk_status latest_risk_status,
        ci.progress_percent latest_progress_percent
      from public.hr_performance_review r
      join public.hr_performance_cycle c on c.id=r.cycle_id and c.tenant_id=r.tenant_id
      join public.mdm_employee e on e.id=r.employee_id and e.tenant_id=r.tenant_id
      left join public.mdm_organization o on o.id=e.organization_id and o.tenant_id=e.tenant_id
      left join public.mdm_employee reviewer on reviewer.id=r.reviewer_employee_id and reviewer.tenant_id=r.tenant_id
      left join lateral (
        select count(*)::integer goal_count, coalesce(sum(weight),0)::numeric goal_weight
        from public.hr_performance_goal g where g.review_id=r.id and g.tenant_id=r.tenant_id
      ) g on true
      left join latest_check_in ci on ci.review_id=r.id
      where (p_tenant_id is null or r.tenant_id=p_tenant_id)
        and (p_cycle_id is null or r.cycle_id=p_cycle_id)
        and (p_status is null or r.status=p_status)
        and (v_keyword is null or e.employee_no ilike '%'||v_keyword||'%'
          or e.employee_name ilike '%'||v_keyword||'%' or c.cycle_name ilike '%'||v_keyword||'%'
          or o.organization_name ilike '%'||v_keyword||'%')
    ), paged as (
      select * from filtered order by cycle_name desc, employee_no offset v_offset limit v_limit
    )
    select jsonb_build_object(
      'records', coalesce(jsonb_agg((to_jsonb(paged)-'cycle_code'-'cycle_name'-'employee_no'-'employee_name'
        -'organization_id'-'organization_name'-'reviewer_no'-'reviewer_name') || jsonb_build_object(
          'cycle',jsonb_build_object('id',cycle_id,'code',cycle_code,'name',cycle_name),
          'employee',jsonb_build_object('id',employee_id,'code',employee_no,'name',employee_name),
          'organization',case when organization_id is null then null else jsonb_build_object('id',organization_id,'name',organization_name) end,
          'reviewer',case when reviewer_employee_id is null then null else jsonb_build_object('id',reviewer_employee_id,'code',reviewer_no,'name',reviewer_name) end
        ) order by cycle_name desc, employee_no), '[]'::jsonb),
      'total',(select count(*) from filtered)
    ) into v_result from paged;
    return coalesce(v_result,jsonb_build_object('records','[]'::jsonb,'total',0));
  end if;

  if p_kind = 'goal' then
    with filtered as materialized (
      select g.*, r.employee_id, r.cycle_id, r.status review_status,
        e.employee_no, e.employee_name, c.cycle_code, c.cycle_name
      from public.hr_performance_goal g
      join public.hr_performance_review r on r.id=g.review_id and r.tenant_id=g.tenant_id
      join public.mdm_employee e on e.id=r.employee_id and e.tenant_id=r.tenant_id
      join public.hr_performance_cycle c on c.id=r.cycle_id and c.tenant_id=r.tenant_id
      where (p_tenant_id is null or g.tenant_id=p_tenant_id)
        and (p_cycle_id is null or r.cycle_id=p_cycle_id)
        and (p_status is null or g.status=p_status)
        and (v_keyword is null or g.goal_name ilike '%'||v_keyword||'%'
          or g.target_description ilike '%'||v_keyword||'%' or e.employee_name ilike '%'||v_keyword||'%')
    ), paged as (
      select * from filtered order by due_date nulls last, goal_name offset v_offset limit v_limit
    )
    select jsonb_build_object(
      'records',coalesce(jsonb_agg((to_jsonb(paged)-'employee_no'-'employee_name'-'cycle_code'-'cycle_name') || jsonb_build_object(
        'employee',jsonb_build_object('id',employee_id,'code',employee_no,'name',employee_name),
        'cycle',jsonb_build_object('id',cycle_id,'code',cycle_code,'name',cycle_name)
      ) order by due_date nulls last, goal_name),'[]'::jsonb),
      'total',(select count(*) from filtered)
    ) into v_result from paged;
    return coalesce(v_result,jsonb_build_object('records','[]'::jsonb,'total',0));
  end if;

  if p_kind = 'check_in' then
    with filtered as materialized (
      select ci.*, r.employee_id, r.cycle_id, e.employee_no, e.employee_name,
        c.cycle_code, c.cycle_name, facilitator.employee_no facilitator_no,
        facilitator.employee_name facilitator_name
      from public.hr_performance_check_in ci
      join public.hr_performance_review r on r.id=ci.review_id and r.tenant_id=ci.tenant_id
      join public.mdm_employee e on e.id=r.employee_id and e.tenant_id=r.tenant_id
      join public.hr_performance_cycle c on c.id=r.cycle_id and c.tenant_id=r.tenant_id
      left join public.mdm_employee facilitator on facilitator.id=ci.facilitator_employee_id and facilitator.tenant_id=ci.tenant_id
      where (p_tenant_id is null or ci.tenant_id=p_tenant_id)
        and (p_cycle_id is null or r.cycle_id=p_cycle_id)
        and (p_status is null or ci.risk_status=p_status)
        and (v_keyword is null or e.employee_no ilike '%'||v_keyword||'%'
          or e.employee_name ilike '%'||v_keyword||'%' or ci.achievement ilike '%'||v_keyword||'%'
          or ci.next_action ilike '%'||v_keyword||'%')
    ), paged as (
      select * from filtered order by check_in_date desc, create_time desc offset v_offset limit v_limit
    )
    select jsonb_build_object(
      'records',coalesce(jsonb_agg((to_jsonb(paged)-'employee_no'-'employee_name'-'cycle_code'-'cycle_name'-'facilitator_no'-'facilitator_name') || jsonb_build_object(
        'employee',jsonb_build_object('id',employee_id,'code',employee_no,'name',employee_name),
        'cycle',jsonb_build_object('id',cycle_id,'code',cycle_code,'name',cycle_name),
        'facilitator',case when facilitator_employee_id is null then null else jsonb_build_object('id',facilitator_employee_id,'code',facilitator_no,'name',facilitator_name) end
      ) order by check_in_date desc, create_time desc),'[]'::jsonb),
      'total',(select count(*) from filtered)
    ) into v_result from paged;
    return coalesce(v_result,jsonb_build_object('records','[]'::jsonb,'total',0));
  end if;

  if p_kind = 'calibration' then
    with filtered as materialized (
      select s.*, c.cycle_code, c.cycle_name, o.organization_code, o.organization_name,
        facilitator.employee_no facilitator_no, facilitator.employee_name facilitator_name,
        (select count(*) from public.hr_performance_calibration_item i where i.session_id=s.id and i.tenant_id=s.tenant_id) item_count,
        (select count(*) from public.hr_performance_calibration_item i where i.session_id=s.id and i.tenant_id=s.tenant_id
          and (i.calibrated_score<>i.original_score or i.calibrated_level<>i.original_level)) adjusted_count
      from public.hr_performance_calibration_session s
      join public.hr_performance_cycle c on c.id=s.cycle_id and c.tenant_id=s.tenant_id
      left join public.mdm_organization o on o.id=s.organization_id and o.tenant_id=s.tenant_id
      left join public.mdm_employee facilitator on facilitator.id=s.facilitator_employee_id and facilitator.tenant_id=s.tenant_id
      where (p_tenant_id is null or s.tenant_id=p_tenant_id)
        and (p_cycle_id is null or s.cycle_id=p_cycle_id)
        and (p_status is null or s.status=p_status)
        and (v_keyword is null or s.session_no ilike '%'||v_keyword||'%'
          or s.session_name ilike '%'||v_keyword||'%' or c.cycle_name ilike '%'||v_keyword||'%'
          or o.organization_name ilike '%'||v_keyword||'%')
    ), paged as (
      select * from filtered order by scheduled_at desc, session_no offset v_offset limit v_limit
    )
    select jsonb_build_object(
      'records',coalesce(jsonb_agg((to_jsonb(paged)-'cycle_code'-'cycle_name'-'organization_code'-'organization_name'-'facilitator_no'-'facilitator_name') || jsonb_build_object(
        'cycle',jsonb_build_object('id',cycle_id,'code',cycle_code,'name',cycle_name),
        'organization',case when organization_id is null then null else jsonb_build_object('id',organization_id,'code',organization_code,'name',organization_name) end,
        'facilitator',case when facilitator_employee_id is null then null else jsonb_build_object('id',facilitator_employee_id,'code',facilitator_no,'name',facilitator_name) end
      ) order by scheduled_at desc, session_no),'[]'::jsonb),
      'total',(select count(*) from filtered)
    ) into v_result from paged;
    return coalesce(v_result,jsonb_build_object('records','[]'::jsonb,'total',0));
  end if;

  with filtered as materialized (
    select i.*, s.session_no, s.session_name, r.employee_id, r.cycle_id,
      e.employee_no, e.employee_name, c.cycle_code, c.cycle_name
    from public.hr_performance_calibration_item i
    join public.hr_performance_calibration_session s on s.id=i.session_id and s.tenant_id=i.tenant_id
    join public.hr_performance_review r on r.id=i.review_id and r.tenant_id=i.tenant_id
    join public.mdm_employee e on e.id=r.employee_id and e.tenant_id=i.tenant_id
    join public.hr_performance_cycle c on c.id=r.cycle_id and c.tenant_id=i.tenant_id
    where (p_tenant_id is null or i.tenant_id=p_tenant_id)
      and (p_session_id is null or i.session_id=p_session_id)
      and (p_cycle_id is null or r.cycle_id=p_cycle_id)
      and (p_status is null or i.calibrated_level=p_status)
      and (v_keyword is null or e.employee_no ilike '%'||v_keyword||'%'
        or e.employee_name ilike '%'||v_keyword||'%' or s.session_name ilike '%'||v_keyword||'%')
  ), paged as (
    select * from filtered order by calibrated_score desc, employee_no offset v_offset limit v_limit
  )
  select jsonb_build_object(
    'records',coalesce(jsonb_agg((to_jsonb(paged)-'session_no'-'session_name'-'employee_no'-'employee_name'-'cycle_code'-'cycle_name') || jsonb_build_object(
      'session',jsonb_build_object('id',session_id,'code',session_no,'name',session_name),
      'employee',jsonb_build_object('id',employee_id,'code',employee_no,'name',employee_name),
      'cycle',jsonb_build_object('id',cycle_id,'code',cycle_code,'name',cycle_name)
    ) order by calibrated_score desc, employee_no),'[]'::jsonb),
    'total',(select count(*) from filtered)
  ) into v_result from paged;
  return coalesce(v_result,jsonb_build_object('records','[]'::jsonb,'total',0));
end
$$;


ALTER FUNCTION "public"."hr_list_performance_records_secure"("p_kind" "text", "p_from" integer, "p_to" integer, "p_keyword" "text", "p_status" "text", "p_cycle_id" "uuid", "p_session_id" "uuid", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_list_personnel_change_employees_secure(integer, integer, "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_personnel_change_employees_secure"("p_from" integer DEFAULT 0, "p_to" integer DEFAULT 19, "p_keyword" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_from integer := greatest(coalesce(p_from,0),0);
  v_limit integer := least(greatest(coalesce(p_to,19)-greatest(coalesce(p_from,0),0)+1,1),200);
  v_keyword text := nullif(btrim(p_keyword),'');
begin
  if not (
    app_private.can_execute_business_action('HrPersonnelChange','Hr:PersonnelChange:Add',null,false)
    or app_private.can_execute_business_action('HrPersonnelChange','Hr:PersonnelChange:Edit',null,false)
  ) then raise exception 'Missing personnel change write permission' using errcode='42501'; end if;
  return (with filtered as materialized (
    select employee_row.id,employee_row.tenant_id,employee_row.employee_no,employee_row.employee_name,
      employee_row.avatar_url,employee_row.job_title,employee_row.employment_status,
      assignment_row.id as assignment_id,assignment_row.update_time as assignment_updated_at,
      app_private.hr_assignment_snapshot(assignment_row.id) as assignment_snapshot
    from public.mdm_employee employee_row
    join public.mdm_employee_assignment assignment_row
      on assignment_row.employee_id=employee_row.id and assignment_row.tenant_id=employee_row.tenant_id
     and assignment_row.primary_assignment and assignment_row.effective_end is null
    where (app_private.current_read_tenant_id() is null or employee_row.tenant_id = app_private.current_read_tenant_id()) and employee_row.employment_status<>'terminated'
      and (v_keyword is null or employee_row.employee_no ilike '%'||v_keyword||'%' or employee_row.employee_name ilike '%'||v_keyword||'%' or employee_row.job_title ilike '%'||v_keyword||'%')
  ), paged as (select * from filtered order by employee_name,employee_no,id offset v_from limit v_limit)
  select jsonb_build_object('records',coalesce((select jsonb_agg(jsonb_build_object(
    'id',id,'tenant_id',tenant_id,'employee_no',employee_no,'employee_name',employee_name,
    'avatar_url',avatar_url,'job_title',job_title,'employment_status',employment_status,
    'assignment_id',assignment_id,'assignment_updated_at',assignment_updated_at,
    'assignment_snapshot',assignment_snapshot
  ) order by employee_name,employee_no,id) from paged),'[]'::jsonb),'total',(select count(*) from filtered)));
end;
$$;


ALTER FUNCTION "public"."hr_list_personnel_change_employees_secure"("p_from" integer, "p_to" integer, "p_keyword" "text") OWNER TO "postgres";

--

--
-- Name: hr_list_policy_acknowledgement_options_secure("text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_policy_acknowledgement_options_secure"("p_kind" "text", "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_tenant_id uuid:=app_private.current_user_tenant_id(); v_result jsonb:='[]'::jsonb;
begin
  if p_kind not in ('organization','policy') then raise exception '不支持的政策签收选项类型'; end if;
  if auth.uid() is null or not app_private.can_execute_business_action(
    'HrPolicyAcknowledgement','Hr:PolicyAcknowledgement:View',null,false
  ) then raise exception '当前账号没有查看政策与签收的权限' using errcode='42501'; end if;
  if not app_private.is_platform_super() then p_tenant_id:=v_tenant_id; end if;
  if p_kind='organization' then
    select coalesce(jsonb_agg(jsonb_build_object('id',organization.id,'tenant_id',organization.tenant_id,'code',organization.organization_code,'name',organization.organization_name,'status',organization.status) order by organization.sort,organization.organization_name),'[]'::jsonb)
    into v_result from public.mdm_organization organization
    where p_tenant_id is null or organization.tenant_id=p_tenant_id;
  else
    select coalesce(jsonb_agg(jsonb_build_object('id',policy.id,'tenant_id',policy.tenant_id,'code',policy.policy_code,'name',policy.policy_title||' v'||policy.version_no,'status',policy.status,'effective_date',policy.effective_date) order by policy.policy_code,policy.version_no desc),'[]'::jsonb)
    into v_result from public.hr_policy_document policy
    where (p_tenant_id is null or policy.tenant_id=p_tenant_id) and policy.status in ('published','retired');
  end if;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."hr_list_policy_acknowledgement_options_secure"("p_kind" "text", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_list_policy_acknowledgement_records_secure("text", integer, integer, "text", "text", "uuid", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_policy_acknowledgement_records_secure"("p_kind" "text", "p_from" integer DEFAULT 0, "p_to" integer DEFAULT 19, "p_keyword" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_policy_id" "uuid" DEFAULT NULL::"uuid", "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    SET "TimeZone" TO 'Asia/Shanghai'
    AS $$
declare
  v_tenant_id uuid:=app_private.current_user_tenant_id();
  v_offset integer:=greatest(coalesce(p_from,0),0);
  v_limit integer:=least(500,greatest(coalesce(p_to,19)-greatest(coalesce(p_from,0),0)+1,1));
  v_keyword text:=nullif(btrim(p_keyword),'');
  v_evidence_access boolean;
  v_total integer:=0;
  v_records jsonb:='[]'::jsonb;
begin
  if p_kind not in ('policy','receipt') then raise exception '不支持的政策签收记录类型'; end if;
  if auth.uid() is null or not app_private.can_execute_business_action(
    'HrPolicyAcknowledgement','Hr:PolicyAcknowledgement:View',null,false
  ) then raise exception '当前账号没有查看政策与签收的权限' using errcode='42501'; end if;
  if not app_private.is_platform_super() then p_tenant_id:=v_tenant_id; end if;
  v_evidence_access:=app_private.can_execute_business_action(
    'HrPolicyAcknowledgement','Hr:PolicyAcknowledgement:Evidence:View',null,false
  );

  if p_kind='policy' then
    select count(*)::integer into v_total
    from public.hr_policy_document policy
    left join public.mdm_organization organization on organization.id=policy.audience_organization_id
    where (p_tenant_id is null or policy.tenant_id=p_tenant_id)
      and (p_status is null or p_status='' or policy.status=p_status)
      and (v_keyword is null or policy.policy_code ilike '%'||v_keyword||'%'
        or policy.policy_title ilike '%'||v_keyword||'%'
        or policy.category ilike '%'||v_keyword||'%'
        or organization.organization_name ilike '%'||v_keyword||'%');

    select coalesce(jsonb_agg(row_data order by effective_date desc,version_no desc),'[]'::jsonb)
    into v_records from (
      select policy.effective_date,policy.version_no,
        jsonb_build_object(
          'id',policy.id,'tenant_id',policy.tenant_id,'policy_code',policy.policy_code,
          'policy_title',policy.policy_title,'category',policy.category,'version_no',policy.version_no,
          'effective_date',policy.effective_date,'acknowledgement_due_days',policy.acknowledgement_due_days,
          'audience_type',policy.audience_type,'audience_organization_id',policy.audience_organization_id,
          'audience_organization_name',organization.organization_name,
          'audience_employment_type',policy.audience_employment_type,
          'document_reference',policy.document_reference,'content_summary',policy.content_summary,
          'status',policy.status,'supersedes_policy_id',policy.supersedes_policy_id,
          'supersedes_policy_title',supersedes.policy_title,'published_at',policy.published_at,
          'published_by',policy.published_by,'decision_note',policy.decision_note,
          'receipt_count',(select count(*) from public.hr_policy_receipt receipt where receipt.policy_id=policy.id),
          'acknowledged_count',(select count(*) from public.hr_policy_receipt receipt where receipt.policy_id=policy.id and receipt.status='acknowledged'),
          'waived_count',(select count(*) from public.hr_policy_receipt receipt where receipt.policy_id=policy.id and receipt.status='waived'),
          'overdue_count',(select count(*) from public.hr_policy_receipt receipt where receipt.policy_id=policy.id and receipt.status='pending' and receipt.due_date<current_date),
          'create_time',policy.create_time,'update_time',policy.update_time
        ) row_data
      from public.hr_policy_document policy
      left join public.mdm_organization organization on organization.id=policy.audience_organization_id
      left join public.hr_policy_document supersedes on supersedes.id=policy.supersedes_policy_id
      where (p_tenant_id is null or policy.tenant_id=p_tenant_id)
        and (p_status is null or p_status='' or policy.status=p_status)
        and (v_keyword is null or policy.policy_code ilike '%'||v_keyword||'%'
          or policy.policy_title ilike '%'||v_keyword||'%'
          or policy.category ilike '%'||v_keyword||'%'
          or organization.organization_name ilike '%'||v_keyword||'%')
      order by policy.effective_date desc,policy.version_no desc
      offset v_offset limit v_limit
    ) rows;
  else
    select count(*)::integer into v_total
    from public.hr_policy_receipt receipt
    join public.hr_policy_document policy on policy.id=receipt.policy_id
    join public.mdm_employee employee on employee.id=receipt.employee_id
    left join public.mdm_organization organization on organization.id=employee.organization_id
    where (p_tenant_id is null or receipt.tenant_id=p_tenant_id)
      and (p_policy_id is null or receipt.policy_id=p_policy_id)
      and (p_status is null or p_status='' or receipt.status=p_status
        or (p_status='overdue' and receipt.status='pending' and receipt.due_date<current_date))
      and (v_keyword is null or policy.policy_code ilike '%'||v_keyword||'%'
        or policy.policy_title ilike '%'||v_keyword||'%'
        or employee.employee_no ilike '%'||v_keyword||'%'
        or employee.employee_name ilike '%'||v_keyword||'%'
        or organization.organization_name ilike '%'||v_keyword||'%');

    select coalesce(jsonb_agg(row_data order by overdue desc,due_date,employee_name),'[]'::jsonb)
    into v_records from (
      select receipt.due_date,employee.employee_name,
        receipt.status='pending' and receipt.due_date<current_date overdue,
        jsonb_build_object(
          'id',receipt.id,'tenant_id',receipt.tenant_id,'policy_id',receipt.policy_id,
          'policy_code',policy.policy_code,'policy_title',policy.policy_title,
          'policy_version_no',policy.version_no,'policy_status',policy.status,
          'document_reference',policy.document_reference,'employee_id',receipt.employee_id,
          'employee_no',employee.employee_no,'employee_name',employee.employee_name,
          'organization_name',organization.organization_name,'job_title',employee.job_title,
          'delivered_at',receipt.delivered_at,'due_date',receipt.due_date,
          'status',case when receipt.status='pending' and receipt.due_date<current_date then 'overdue' else receipt.status end,
          'stored_status',receipt.status,'acknowledged_at',receipt.acknowledged_at,
          'acknowledged_by',receipt.acknowledged_by,'acknowledgement_note',receipt.acknowledgement_note,
          'evidence_reference',case when v_evidence_access then receipt.evidence_reference else null end,
          'waived_at',receipt.waived_at,'waived_by',receipt.waived_by,
          'waiver_reason',case when v_evidence_access then receipt.waiver_reason else null end,
          'create_time',receipt.create_time,'update_time',receipt.update_time
        ) row_data
      from public.hr_policy_receipt receipt
      join public.hr_policy_document policy on policy.id=receipt.policy_id
      join public.mdm_employee employee on employee.id=receipt.employee_id
      left join public.mdm_organization organization on organization.id=employee.organization_id
      where (p_tenant_id is null or receipt.tenant_id=p_tenant_id)
        and (p_policy_id is null or receipt.policy_id=p_policy_id)
        and (p_status is null or p_status='' or receipt.status=p_status
          or (p_status='overdue' and receipt.status='pending' and receipt.due_date<current_date))
        and (v_keyword is null or policy.policy_code ilike '%'||v_keyword||'%'
          or policy.policy_title ilike '%'||v_keyword||'%'
          or employee.employee_no ilike '%'||v_keyword||'%'
          or employee.employee_name ilike '%'||v_keyword||'%'
          or organization.organization_name ilike '%'||v_keyword||'%')
      order by overdue desc,receipt.due_date,employee.employee_name
      offset v_offset limit v_limit
    ) rows;
  end if;

  return jsonb_build_object('records',v_records,'total',v_total,'evidence_access',v_evidence_access);
end;
$$;


ALTER FUNCTION "public"."hr_list_policy_acknowledgement_records_secure"("p_kind" "text", "p_from" integer, "p_to" integer, "p_keyword" "text", "p_status" "text", "p_policy_id" "uuid", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_list_position_options_secure("uuid", boolean); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_position_options_secure"("p_tenant_id" "uuid" DEFAULT NULL::"uuid", "p_include_disabled" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_tenant_id uuid := app_private.current_user_tenant_id();
begin
  if not (
    app_private.can_execute_business_action('HrEmployeeRoster', 'Hr:Employee:Add', null, false)
    or app_private.can_execute_business_action('HrEmployeeRoster', 'Hr:Employee:Edit', null, false)
    or app_private.can_execute_business_action('HrPosition', 'Hr:Position:View', null, false)
    or app_private.can_execute_business_action('HrPersonnelChange', 'Hr:PersonnelChange:Add', null, false)
    or app_private.can_execute_business_action('HrPersonnelChange', 'Hr:PersonnelChange:Edit', null, false)
  ) then raise exception 'Missing employee or position permission' using errcode = '42501'; end if;
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;
  if p_tenant_id is null then return '[]'::jsonb; end if;

  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', position_row.id,
      'tenant_id', position_row.tenant_id,
      'organization_id', position_row.organization_id,
      'position_code', position_row.position_code,
      'position_name', position_row.position_name,
      'position_kind', position_row.position_kind,
      'system_code', position_row.system_code,
      'job_profile_id', position_row.job_profile_id,
      'grade_id', position_row.grade_id,
      'headcount_limit', position_row.headcount_limit,
      'multiple_incumbents_allowed', position_row.multiple_incumbents_allowed,
      'enabled', position_row.enabled,
      'job_profile', jsonb_build_object(
        'id', profile_row.id, 'job_code', profile_row.job_code, 'job_name', profile_row.job_name
      ),
      'grade', case when grade_row.id is null then null else jsonb_build_object(
        'id', grade_row.id, 'grade_code', grade_row.grade_code, 'grade_name', grade_row.grade_name
      ) end
    ) order by position_row.sort, position_row.position_name)
    from public.mdm_position position_row
    join public.mdm_job_profile profile_row
      on profile_row.id = position_row.job_profile_id and profile_row.tenant_id = position_row.tenant_id
    left join public.mdm_grade grade_row
      on grade_row.id = position_row.grade_id and grade_row.tenant_id = position_row.tenant_id
    where position_row.tenant_id = p_tenant_id
      and (p_include_disabled or position_row.enabled)
  ), '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."hr_list_position_options_secure"("p_tenant_id" "uuid", "p_include_disabled" boolean) OWNER TO "postgres";

--

--
-- Name: hr_list_position_organization_scope_secure("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_position_organization_scope_secure"("p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_target_tenant_id uuid;
begin
  if not app_private.can_execute_business_action(
    'HrPosition',
    'Hr:Position:View',
    null,
    false
  ) then
    raise exception 'Missing position view permission' using errcode = '42501';
  end if;

  v_target_tenant_id := case
    when app_private.is_platform_super() then p_tenant_id
    else app_private.current_user_tenant_id()
  end;

  if not app_private.is_platform_super() and v_target_tenant_id is null then
    raise exception 'Position tenant is required' using errcode = '22023';
  end if;

  return coalesce((
    select jsonb_agg(
      jsonb_build_object(
        'id', organization_row.id,
        'tenant_id', organization_row.tenant_id,
        'tenant', jsonb_build_object(
          'tenant_code', tenant_row.tenant_code,
          'tenant_name', tenant_row.tenant_name
        ),
        'parent_id', organization_row.parent_id,
        'organization_code', organization_row.organization_code,
        'organization_name', organization_row.organization_name,
        'organization_type', organization_row.organization_type,
        'status', organization_row.status,
        'sort', organization_row.sort,
        'is_system', organization_row.is_system,
        'scope_count', (
          select count(*)
          from public.mdm_position position_row
          where position_row.tenant_id = organization_row.tenant_id
            and position_row.organization_id = organization_row.id
        )
      )
      order by tenant_row.tenant_name, organization_row.sort, organization_row.organization_name
    )
    from public.mdm_organization organization_row
    join public.sys_tenant tenant_row on tenant_row.id = organization_row.tenant_id
    where (v_target_tenant_id is null or organization_row.tenant_id = v_target_tenant_id)
      and organization_row.status = '1'
  ), '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."hr_list_position_organization_scope_secure"("p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_list_positions_secure(integer, integer, "text", boolean, "uuid", "uuid"[]); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_positions_secure"("p_from" integer DEFAULT 0, "p_to" integer DEFAULT 19, "p_keyword" "text" DEFAULT NULL::"text", "p_enabled" boolean DEFAULT NULL::boolean, "p_tenant_id" "uuid" DEFAULT NULL::"uuid", "p_organization_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_limit integer;
  v_result jsonb;
begin
  if not app_private.can_execute_business_action('HrPosition', 'Hr:Position:View', null, false) then
    raise exception 'Missing position view permission' using errcode = '42501';
  end if;

  if not app_private.is_platform_super() then
    p_tenant_id := v_tenant_id;
  end if;

  v_limit := least(
    2000,
    greatest(coalesce(p_to, 19) - greatest(coalesce(p_from, 0), 0) + 1, 1)
  );

  with filtered as materialized (
    select
      position_row.*,
      tenant_row.tenant_code,
      tenant_row.tenant_name,
      organization_row.organization_code,
      organization_row.organization_name,
      profile_row.job_code,
      profile_row.job_name,
      grade_row.grade_code,
      grade_row.grade_name,
      (
        select count(*)
        from public.mdm_employee employee_row
        where employee_row.position_id = position_row.id
          and employee_row.tenant_id = position_row.tenant_id
          and employee_row.employment_status <> 'terminated'
      ) as employee_count
    from public.mdm_position position_row
    join public.sys_tenant tenant_row on tenant_row.id = position_row.tenant_id
    left join public.mdm_organization organization_row
      on organization_row.id = position_row.organization_id
     and organization_row.tenant_id = position_row.tenant_id
    join public.mdm_job_profile profile_row
      on profile_row.id = position_row.job_profile_id
     and profile_row.tenant_id = position_row.tenant_id
    left join public.mdm_grade grade_row
      on grade_row.id = position_row.grade_id
     and grade_row.tenant_id = position_row.tenant_id
    where (p_tenant_id is null or position_row.tenant_id = p_tenant_id)
      and (
        coalesce(cardinality(p_organization_ids), 0) = 0
        or position_row.organization_id = any(p_organization_ids)
      )
      and (p_enabled is null or position_row.enabled = p_enabled)
      and (
        nullif(btrim(p_keyword), '') is null
        or position_row.position_code ilike '%' || btrim(p_keyword) || '%'
        or position_row.position_name ilike '%' || btrim(p_keyword) || '%'
        or profile_row.job_name ilike '%' || btrim(p_keyword) || '%'
        or organization_row.organization_name ilike '%' || btrim(p_keyword) || '%'
        or position_row.description ilike '%' || btrim(p_keyword) || '%'
      )
  ), paged as (
    select *
    from filtered
    order by tenant_name, sort, position_name
    offset greatest(coalesce(p_from, 0), 0)
    limit v_limit
  )
  select jsonb_build_object(
    'records', coalesce((
      select jsonb_agg(
        (to_jsonb(paged)
          - 'tenant_code' - 'tenant_name'
          - 'organization_code' - 'organization_name'
          - 'job_code' - 'job_name' - 'grade_code' - 'grade_name')
        || jsonb_build_object(
          'tenant', jsonb_build_object(
            'id', paged.tenant_id,
            'tenant_code', paged.tenant_code,
            'tenant_name', paged.tenant_name
          ),
          'organization', case
            when paged.organization_id is null then null
            else jsonb_build_object(
              'id', paged.organization_id,
              'organization_code', paged.organization_code,
              'organization_name', paged.organization_name
            )
          end,
          'job_profile', jsonb_build_object(
            'id', paged.job_profile_id,
            'job_code', paged.job_code,
            'job_name', paged.job_name
          ),
          'grade', case
            when paged.grade_id is null then null
            else jsonb_build_object(
              'id', paged.grade_id,
              'grade_code', paged.grade_code,
              'grade_name', paged.grade_name
            )
          end
        )
        order by paged.tenant_name, paged.sort, paged.position_name
      )
      from paged
    ), '[]'::jsonb),
    'total', (select count(*) from filtered)
  )
  into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."hr_list_positions_secure"("p_from" integer, "p_to" integer, "p_keyword" "text", "p_enabled" boolean, "p_tenant_id" "uuid", "p_organization_ids" "uuid"[]) OWNER TO "postgres";

--

--
-- Name: hr_list_recruitment_options_secure("text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_recruitment_options_secure"("p_kind" "text", "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_result jsonb;
begin
  if not app_private.can_execute_business_action('HrRecruitment', 'Hr:Recruitment:View', null, false) then
    raise exception '当前账号没有查看招聘选项的权限' using errcode = '42501';
  end if;
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;
  if p_kind = 'requisition' then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', r.id, 'tenant_id', r.tenant_id, 'code', r.requisition_no,
      'name', position.position_name, 'organization_name', organization.organization_name
    ) order by r.requisition_no), '[]'::jsonb) into v_result
    from public.hr_recruitment_requisition r
    join public.mdm_position position on position.id = r.position_id and position.tenant_id = r.tenant_id
    join public.mdm_organization organization on organization.id = r.organization_id
    where (p_tenant_id is null or r.tenant_id = p_tenant_id) and r.status = 'effective';
  elsif p_kind = 'candidate' then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', c.id, 'tenant_id', c.tenant_id, 'name', c.candidate_name,
      'code', r.requisition_no, 'position_name', position.position_name, 'stage', c.stage
    ) order by c.candidate_name), '[]'::jsonb) into v_result
    from public.hr_candidate c
    join public.hr_recruitment_requisition r on r.id = c.requisition_id and r.tenant_id = c.tenant_id
    join public.mdm_position position on position.id = r.position_id and position.tenant_id = r.tenant_id
    where (p_tenant_id is null or c.tenant_id = p_tenant_id)
      and c.stage in ('new', 'screening', 'interview', 'offer');
  elsif p_kind = 'accepted_offer' then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', o.id, 'tenant_id', o.tenant_id, 'code', o.offer_no,
      'name', c.candidate_name, 'candidate_id', c.id, 'proposed_onboard_date', o.proposed_onboard_date
    ) order by o.offer_no), '[]'::jsonb) into v_result
    from public.hr_recruitment_offer o
    join public.hr_candidate c on c.id = o.candidate_id and c.tenant_id = o.tenant_id
    where (p_tenant_id is null or o.tenant_id = p_tenant_id) and o.status = 'accepted';
  elsif p_kind = 'handoff' then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', h.id, 'tenant_id', h.tenant_id, 'name', c.candidate_name,
      'code', o.offer_no, 'planned_onboard_date', h.planned_onboard_date
    ) order by h.planned_onboard_date, c.candidate_name), '[]'::jsonb) into v_result
    from public.hr_recruitment_handoff h
    join public.hr_candidate c on c.id = h.candidate_id and c.tenant_id = h.tenant_id
    join public.hr_recruitment_offer o on o.id = h.offer_id and o.tenant_id = h.tenant_id
    where (p_tenant_id is null or h.tenant_id = p_tenant_id) and h.status in ('pending', 'ready');
  else
    raise exception '不支持的招聘选项类型';
  end if;
  return coalesce(v_result, '[]'::jsonb);
end
$$;


ALTER FUNCTION "public"."hr_list_recruitment_options_secure"("p_kind" "text", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_list_recruitment_records_secure("text", integer, integer, "text", "text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_recruitment_records_secure"("p_kind" "text", "p_from" integer DEFAULT 0, "p_to" integer DEFAULT 19, "p_keyword" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_offset integer := greatest(coalesce(p_from, 0), 0);
  v_limit integer := least(500, greatest(coalesce(p_to, 19) - greatest(coalesce(p_from, 0), 0) + 1, 1));
  v_keyword text := nullif(btrim(p_keyword), '');
  v_sensitive boolean;
  v_result jsonb;
begin
  if p_kind not in ('requisition', 'candidate', 'interview', 'offer', 'handoff', 'task') then
    raise exception '不支持的招聘记录类型';
  end if;
  if not app_private.can_execute_business_action('HrRecruitment', 'Hr:Recruitment:View', null, false) then
    raise exception '当前账号没有查看招聘工作台的权限' using errcode = '42501';
  end if;
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;
  v_sensitive := app_private.can_execute_business_action(
    'HrRecruitment', 'Hr:Recruitment:Sensitive:View', null, false
  );

  if p_kind = 'requisition' then
    with filtered as materialized (
      select r.*, organization.organization_code, organization.organization_name,
        position.position_code, position.position_name,
        (select count(*) from public.hr_candidate c where c.requisition_id = r.id) candidate_count,
        (select count(*) from public.hr_candidate c where c.requisition_id = r.id and c.stage = 'interview') interview_count,
        (select count(*) from public.hr_candidate c where c.requisition_id = r.id and c.stage = 'offer') offer_count
      from public.hr_recruitment_requisition r
      join public.mdm_organization organization on organization.id = r.organization_id
      join public.mdm_position position on position.id = r.position_id and position.tenant_id = r.tenant_id
      where (p_tenant_id is null or r.tenant_id = p_tenant_id)
        and (p_status is null or r.status = p_status)
        and (v_keyword is null or r.requisition_no ilike '%' || v_keyword || '%'
          or organization.organization_name ilike '%' || v_keyword || '%'
          or position.position_name ilike '%' || v_keyword || '%')
    ), paged as (
      select * from filtered order by create_time desc, requisition_no offset v_offset limit v_limit
    )
    select jsonb_build_object(
      'records', coalesce(jsonb_agg(
        (to_jsonb(paged) - 'organization_code' - 'organization_name' - 'position_code' - 'position_name')
        || jsonb_build_object(
          'organization', jsonb_build_object('id', organization_id, 'code', organization_code, 'name', organization_name),
          'position', jsonb_build_object('id', position_id, 'code', position_code, 'name', position_name)
        ) order by create_time desc, requisition_no
      ), '[]'::jsonb),
      'total', (select count(*) from filtered),
      'sensitive_access', v_sensitive
    ) into v_result from paged;
    return coalesce(v_result, jsonb_build_object('records', '[]'::jsonb, 'total', 0, 'sensitive_access', v_sensitive));
  end if;

  if p_kind = 'candidate' then
    with filtered as materialized (
      select c.*, r.requisition_no, position.position_name, organization.organization_name,
        (select count(*) from public.hr_recruitment_interview i where i.candidate_id = c.id and i.status <> 'cancelled') interview_count,
        (select o.status from public.hr_recruitment_offer o where o.candidate_id = c.id order by o.version_no desc limit 1) latest_offer_status,
        (select max(h.changed_at) from public.hr_candidate_stage_history h where h.candidate_id = c.id) stage_changed_at
      from public.hr_candidate c
      join public.hr_recruitment_requisition r on r.id = c.requisition_id and r.tenant_id = c.tenant_id
      join public.mdm_position position on position.id = r.position_id and position.tenant_id = r.tenant_id
      join public.mdm_organization organization on organization.id = r.organization_id
      where (p_tenant_id is null or c.tenant_id = p_tenant_id)
        and (p_status is null or c.stage = p_status)
        and (v_keyword is null or c.candidate_name ilike '%' || v_keyword || '%'
          or r.requisition_no ilike '%' || v_keyword || '%'
          or position.position_name ilike '%' || v_keyword || '%')
    ), paged as (
      select * from filtered order by create_time desc, candidate_name offset v_offset limit v_limit
    )
    select jsonb_build_object(
      'records', coalesce(jsonb_agg(
        (to_jsonb(paged) - 'requisition_no' - 'position_name' - 'organization_name' - 'phone' - 'email' - 'expected_salary')
        || jsonb_build_object(
          'phone', case when v_sensitive then phone else null end,
          'email', case when v_sensitive then email else null end,
          'expected_salary', case when v_sensitive then expected_salary else null end,
          'requisition', jsonb_build_object('id', requisition_id, 'code', requisition_no, 'position_name', position_name, 'organization_name', organization_name)
        ) order by create_time desc, candidate_name
      ), '[]'::jsonb),
      'total', (select count(*) from filtered),
      'sensitive_access', v_sensitive
    ) into v_result from paged;
    return coalesce(v_result, jsonb_build_object('records', '[]'::jsonb, 'total', 0, 'sensitive_access', v_sensitive));
  end if;

  if p_kind = 'interview' then
    with filtered as materialized (
      select i.*, c.candidate_name, r.requisition_no, position.position_name,
        employee.employee_no interviewer_no, employee.employee_name interviewer_name
      from public.hr_recruitment_interview i
      join public.hr_candidate c on c.id = i.candidate_id and c.tenant_id = i.tenant_id
      join public.hr_recruitment_requisition r on r.id = c.requisition_id and r.tenant_id = c.tenant_id
      join public.mdm_position position on position.id = r.position_id and position.tenant_id = r.tenant_id
      join public.mdm_employee employee on employee.id = i.interviewer_employee_id and employee.tenant_id = i.tenant_id
      where (p_tenant_id is null or i.tenant_id = p_tenant_id)
        and (p_status is null or i.status = p_status)
        and (v_keyword is null or c.candidate_name ilike '%' || v_keyword || '%'
          or r.requisition_no ilike '%' || v_keyword || '%'
          or employee.employee_name ilike '%' || v_keyword || '%')
    ), paged as (
      select * from filtered order by scheduled_start_at desc, round_no offset v_offset limit v_limit
    )
    select jsonb_build_object(
      'records', coalesce(jsonb_agg(
        (to_jsonb(paged) - 'candidate_name' - 'requisition_no' - 'position_name' - 'interviewer_no' - 'interviewer_name')
        || jsonb_build_object(
          'candidate', jsonb_build_object('id', candidate_id, 'name', candidate_name, 'requisition_no', requisition_no, 'position_name', position_name),
          'interviewer', jsonb_build_object('id', interviewer_employee_id, 'code', interviewer_no, 'name', interviewer_name)
        ) order by scheduled_start_at desc, round_no
      ), '[]'::jsonb),
      'total', (select count(*) from filtered),
      'sensitive_access', v_sensitive
    ) into v_result from paged;
    return coalesce(v_result, jsonb_build_object('records', '[]'::jsonb, 'total', 0, 'sensitive_access', v_sensitive));
  end if;

  if p_kind = 'offer' then
    with filtered as materialized (
      select o.*, c.candidate_name, r.requisition_no, position.position_name
      from public.hr_recruitment_offer o
      join public.hr_candidate c on c.id = o.candidate_id and c.tenant_id = o.tenant_id
      join public.hr_recruitment_requisition r on r.id = c.requisition_id and r.tenant_id = c.tenant_id
      join public.mdm_position position on position.id = r.position_id and position.tenant_id = r.tenant_id
      where (p_tenant_id is null or o.tenant_id = p_tenant_id)
        and (p_status is null or o.status = p_status)
        and (v_keyword is null or o.offer_no ilike '%' || v_keyword || '%'
          or c.candidate_name ilike '%' || v_keyword || '%' or position.position_name ilike '%' || v_keyword || '%')
    ), paged as (
      select * from filtered order by create_time desc, version_no desc offset v_offset limit v_limit
    )
    select jsonb_build_object(
      'records', coalesce(jsonb_agg(
        (to_jsonb(paged) - 'candidate_name' - 'requisition_no' - 'position_name' - 'monthly_salary' - 'target_bonus')
        || jsonb_build_object(
          'monthly_salary', case when v_sensitive then monthly_salary else null end,
          'target_bonus', case when v_sensitive then target_bonus else null end,
          'candidate', jsonb_build_object('id', candidate_id, 'name', candidate_name, 'requisition_no', requisition_no, 'position_name', position_name)
        ) order by create_time desc, version_no desc
      ), '[]'::jsonb),
      'total', (select count(*) from filtered),
      'sensitive_access', v_sensitive
    ) into v_result from paged;
    return coalesce(v_result, jsonb_build_object('records', '[]'::jsonb, 'total', 0, 'sensitive_access', v_sensitive));
  end if;

  if p_kind = 'handoff' then
    with filtered as materialized (
      select h.*, c.candidate_name, o.offer_no, r.requisition_no,
        organization.organization_name, position.position_name,
        owner.employee_no owner_no, owner.employee_name owner_name,
        buddy.employee_no buddy_no, buddy.employee_name buddy_name,
        onboard.employee_no onboard_no, onboard.employee_name onboard_name,
        (select count(*) from public.hr_recruitment_onboarding_task t where t.handoff_id = h.id) task_count,
        (select count(*) from public.hr_recruitment_onboarding_task t where t.handoff_id = h.id and t.status in ('completed', 'skipped')) completed_task_count,
        (select count(*) from public.hr_recruitment_onboarding_task t where t.handoff_id = h.id and t.status in ('pending', 'in_progress') and t.due_date < current_date) overdue_task_count
      from public.hr_recruitment_handoff h
      join public.hr_candidate c on c.id = h.candidate_id and c.tenant_id = h.tenant_id
      join public.hr_recruitment_offer o on o.id = h.offer_id and o.tenant_id = h.tenant_id
      join public.hr_recruitment_requisition r on r.id = c.requisition_id and r.tenant_id = c.tenant_id
      join public.mdm_organization organization on organization.id = h.organization_id
      join public.mdm_position position on position.id = h.position_id and position.tenant_id = h.tenant_id
      left join public.mdm_employee owner on owner.id = h.owner_employee_id and owner.tenant_id = h.tenant_id
      left join public.mdm_employee buddy on buddy.id = h.buddy_employee_id and buddy.tenant_id = h.tenant_id
      left join public.mdm_employee onboard on onboard.id = h.onboard_employee_id and onboard.tenant_id = h.tenant_id
      where (p_tenant_id is null or h.tenant_id = p_tenant_id)
        and (p_status is null or h.status = p_status)
        and (v_keyword is null or c.candidate_name ilike '%' || v_keyword || '%'
          or o.offer_no ilike '%' || v_keyword || '%' or position.position_name ilike '%' || v_keyword || '%')
    ), paged as (
      select * from filtered order by planned_onboard_date, candidate_name offset v_offset limit v_limit
    )
    select jsonb_build_object(
      'records', coalesce(jsonb_agg(
        (to_jsonb(paged) - 'candidate_name' - 'offer_no' - 'requisition_no' - 'organization_name' - 'position_name'
          - 'owner_no' - 'owner_name' - 'buddy_no' - 'buddy_name' - 'onboard_no' - 'onboard_name')
        || jsonb_build_object(
          'candidate', jsonb_build_object('id', candidate_id, 'name', candidate_name, 'requisition_no', requisition_no),
          'offer', jsonb_build_object('id', offer_id, 'code', offer_no),
          'organization', jsonb_build_object('id', organization_id, 'name', organization_name),
          'position', jsonb_build_object('id', position_id, 'name', position_name),
          'owner', case when owner_employee_id is null then null else jsonb_build_object('id', owner_employee_id, 'code', owner_no, 'name', owner_name) end,
          'buddy', case when buddy_employee_id is null then null else jsonb_build_object('id', buddy_employee_id, 'code', buddy_no, 'name', buddy_name) end,
          'onboard_employee', case when onboard_employee_id is null then null else jsonb_build_object('id', onboard_employee_id, 'code', onboard_no, 'name', onboard_name) end
        ) order by planned_onboard_date, candidate_name
      ), '[]'::jsonb),
      'total', (select count(*) from filtered),
      'sensitive_access', v_sensitive
    ) into v_result from paged;
    return coalesce(v_result, jsonb_build_object('records', '[]'::jsonb, 'total', 0, 'sensitive_access', v_sensitive));
  end if;

  with filtered as materialized (
    select t.*, h.candidate_id, h.planned_onboard_date, c.candidate_name,
      owner.employee_no owner_no, owner.employee_name owner_name
    from public.hr_recruitment_onboarding_task t
    join public.hr_recruitment_handoff h on h.id = t.handoff_id and h.tenant_id = t.tenant_id
    join public.hr_candidate c on c.id = h.candidate_id and c.tenant_id = h.tenant_id
    left join public.mdm_employee owner on owner.id = t.owner_employee_id and owner.tenant_id = t.tenant_id
    where (p_tenant_id is null or t.tenant_id = p_tenant_id)
      and (p_status is null or t.status = p_status)
      and (v_keyword is null or t.task_title ilike '%' || v_keyword || '%'
        or c.candidate_name ilike '%' || v_keyword || '%' or owner.employee_name ilike '%' || v_keyword || '%')
  ), paged as (
    select * from filtered order by due_date, task_title offset v_offset limit v_limit
  )
  select jsonb_build_object(
    'records', coalesce(jsonb_agg(
      (to_jsonb(paged) - 'candidate_id' - 'candidate_name' - 'planned_onboard_date' - 'owner_no' - 'owner_name')
      || jsonb_build_object(
        'handoff', jsonb_build_object('id', handoff_id, 'candidate_id', candidate_id, 'candidate_name', candidate_name, 'planned_onboard_date', planned_onboard_date),
        'owner', case when owner_employee_id is null then null else jsonb_build_object('id', owner_employee_id, 'code', owner_no, 'name', owner_name) end
      ) order by due_date, task_title
    ), '[]'::jsonb),
    'total', (select count(*) from filtered),
    'sensitive_access', v_sensitive
  ) into v_result from paged;
  return coalesce(v_result, jsonb_build_object('records', '[]'::jsonb, 'total', 0, 'sensitive_access', v_sensitive));
end
$$;


ALTER FUNCTION "public"."hr_list_recruitment_records_secure"("p_kind" "text", "p_from" integer, "p_to" integer, "p_keyword" "text", "p_status" "text", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_list_service_delivery_records_secure("text", integer, integer, "text", "text", "text", "text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_service_delivery_records_secure"("p_kind" "text", "p_from" integer DEFAULT 0, "p_to" integer DEFAULT 19, "p_keyword" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_category" "text" DEFAULT NULL::"text", "p_scope" "text" DEFAULT 'mine'::"text", "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_employee_id uuid := app_private.hr_current_employee_id();
  v_manage boolean := app_private.is_platform_super()
    or app_private.has_permission('Hr:SelfService:Manage');
  v_catalog_manage boolean := app_private.is_platform_super()
    or app_private.has_permission('Hr:SelfService:Catalog:Manage');
  v_offset integer := greatest(coalesce(p_from, 0), 0);
  v_limit integer := least(
    500,
    greatest(coalesce(p_to, 19) - greatest(coalesce(p_from, 0), 0) + 1, 1)
  );
  v_keyword text := nullif(btrim(p_keyword), '');
  v_result jsonb;
begin
  if p_kind not in ('service', 'request') then
    raise exception '不支持的员工服务记录类型';
  end if;
  if not app_private.can_execute_business_action(
    'HrSelfService', 'Hr:SelfService:View', null, false
  ) then
    raise exception '当前账号没有查看员工服务中心的权限' using errcode = '42501';
  end if;
  if not app_private.is_platform_super() then
    p_tenant_id := v_tenant_id;
  end if;

  if p_kind = 'service' then
    with filtered as materialized (
      select service.*,
        (select count(*) from public.hr_self_service_request request
          where request.service_id = service.id and request.tenant_id = service.tenant_id
        ) as request_count
      from public.hr_service_catalog service
      where (p_tenant_id is null or service.tenant_id = p_tenant_id)
        and (v_catalog_manage or service.enabled)
        and (p_status is null or service.enabled = (p_status = 'enabled'))
        and (p_category is null or service.category = p_category)
        and (
          v_keyword is null
          or service.service_code ilike '%' || v_keyword || '%'
          or service.service_name ilike '%' || v_keyword || '%'
          or service.description ilike '%' || v_keyword || '%'
          or service.routing_group ilike '%' || v_keyword || '%'
        )
    ), paged as (
      select * from filtered
      order by enabled desc, sort, service_name
      offset v_offset limit v_limit
    )
    select jsonb_build_object(
      'records', coalesce(jsonb_agg(to_jsonb(paged) order by enabled desc, sort, service_name), '[]'::jsonb),
      'total', (select count(*) from filtered)
    ) into v_result from paged;
    return coalesce(v_result, jsonb_build_object('records', '[]'::jsonb, 'total', 0));
  end if;

  with filtered as materialized (
    select request.*,
      service.service_code,
      service.service_name,
      service.category as service_category,
      service.routing_group,
      requester.employee_no as requester_code,
      requester.employee_name as requester_name,
      requester.job_title as requester_job_title,
      assignee.employee_no as assignee_code,
      assignee.employee_name as assignee_name,
      case
        when request.status not in ('submitted', 'assigned', 'in_progress', 'waiting_employee')
          or request.resolution_due_at is null then 'clear'
        when request.resolution_due_at < now() then 'breached'
        when request.resolution_due_at <= now() + interval '4 hours' then 'at_risk'
        else 'on_track'
      end as sla_status
    from public.hr_self_service_request request
    left join public.hr_service_catalog service
      on service.id = request.service_id and service.tenant_id = request.tenant_id
    join public.mdm_employee requester
      on requester.id = request.employee_id and requester.tenant_id = request.tenant_id
    left join public.mdm_employee assignee
      on assignee.id = request.assigned_employee_id and assignee.tenant_id = request.tenant_id
    where (p_tenant_id is null or request.tenant_id = p_tenant_id)
      and (v_manage and p_scope = 'team' or request.employee_id = v_employee_id)
      and (p_status is null or request.status = p_status)
      and (p_category is null or service.category = p_category)
      and (
        v_keyword is null
        or request.request_no ilike '%' || v_keyword || '%'
        or request.title ilike '%' || v_keyword || '%'
        or request.reason ilike '%' || v_keyword || '%'
        or service.service_name ilike '%' || v_keyword || '%'
        or requester.employee_no ilike '%' || v_keyword || '%'
        or requester.employee_name ilike '%' || v_keyword || '%'
      )
  ), paged as (
    select * from filtered
    order by
      case when sla_status = 'breached' then 0 when sla_status = 'at_risk' then 1 else 2 end,
      last_activity_at desc
    offset v_offset limit v_limit
  )
  select jsonb_build_object(
    'records', coalesce(jsonb_agg(
      (to_jsonb(paged)
        - 'service_code' - 'service_name' - 'service_category' - 'routing_group'
        - 'requester_code' - 'requester_name' - 'requester_job_title'
        - 'assignee_code' - 'assignee_name')
      || jsonb_build_object(
        'service', case when service_id is null then null else jsonb_build_object(
          'id', service_id, 'code', service_code, 'name', service_name,
          'category', service_category, 'routing_group', routing_group
        ) end,
        'requester', jsonb_build_object(
          'id', employee_id, 'code', requester_code, 'name', requester_name,
          'job_title', requester_job_title
        ),
        'assignee', case when assigned_employee_id is null then null else jsonb_build_object(
          'id', assigned_employee_id, 'code', assignee_code, 'name', assignee_name
        ) end
      )
      order by
        case when sla_status = 'breached' then 0 when sla_status = 'at_risk' then 1 else 2 end,
        last_activity_at desc
    ), '[]'::jsonb),
    'total', (select count(*) from filtered)
  ) into v_result from paged;
  return coalesce(v_result, jsonb_build_object('records', '[]'::jsonb, 'total', 0));
end
$$;


ALTER FUNCTION "public"."hr_list_service_delivery_records_secure"("p_kind" "text", "p_from" integer, "p_to" integer, "p_keyword" "text", "p_status" "text", "p_category" "text", "p_scope" "text", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_list_succession_options_secure("text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_succession_options_secure"("p_kind" "text", "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_tenant_id uuid:=app_private.current_user_tenant_id(); v_result jsonb;
begin
  if not app_private.can_execute_business_action('HrSuccession','Hr:Succession:View',null,false) then raise exception 'Missing succession view permission' using errcode='42501'; end if;
  if not app_private.is_platform_super() then p_tenant_id:=v_tenant_id; end if;
  if p_kind='position' then
    select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'tenant_id',p.tenant_id,'code',p.position_code,'name',p.position_name,'organization_name',o.organization_name) order by p.position_name),'[]'::jsonb) into v_result
    from public.mdm_position p left join public.mdm_organization o on o.id=p.organization_id where (p_tenant_id is null or p.tenant_id=p_tenant_id) and p.enabled;
  elsif p_kind='employee' then
    select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'tenant_id',e.tenant_id,'code',e.employee_no,'name',e.employee_name,'job_title',e.job_title,'organization_name',o.organization_name) order by e.employee_name),'[]'::jsonb) into v_result
    from public.mdm_employee e left join public.mdm_organization o on o.id=e.organization_id where (p_tenant_id is null or e.tenant_id=p_tenant_id) and e.employment_status in ('probation','active','leave');
  elsif p_kind='plan' then
    select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'tenant_id',p.tenant_id,'code',p.plan_code,'name',p.plan_name,'position_name',pos.position_name) order by p.plan_name),'[]'::jsonb) into v_result
    from public.hr_succession_plan p join public.mdm_position pos on pos.id=p.position_id where (p_tenant_id is null or p.tenant_id=p_tenant_id) and p.status in ('draft','active');
  elsif p_kind='candidate' then
    select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'tenant_id',c.tenant_id,'code',e.employee_no,'name',e.employee_name,'plan_name',p.plan_name,'position_name',pos.position_name) order by e.employee_name),'[]'::jsonb) into v_result
    from public.hr_succession_candidate c join public.mdm_employee e on e.id=c.employee_id join public.hr_succession_plan p on p.id=c.plan_id join public.mdm_position pos on pos.id=p.position_id
    where (p_tenant_id is null or c.tenant_id=p_tenant_id) and c.status in ('nominated','active');
  else raise exception '不支持的继任选项类型'; end if;
  return coalesce(v_result,'[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."hr_list_succession_options_secure"("p_kind" "text", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_list_succession_records_secure("text", integer, integer, "text", "text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_succession_records_secure"("p_kind" "text", "p_from" integer DEFAULT 0, "p_to" integer DEFAULT 19, "p_keyword" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_offset integer := greatest(coalesce(p_from,0),0);
  v_limit integer := least(500,greatest(coalesce(p_to,19)-greatest(coalesce(p_from,0),0)+1,1));
  v_keyword text := nullif(btrim(p_keyword),'');
  v_result jsonb;
begin
  if p_kind not in ('plan','candidate','action') then raise exception '不支持的继任记录类型'; end if;
  if not app_private.can_execute_business_action('HrSuccession', 'Hr:Succession:View', null, false) then
    raise exception 'Missing succession view permission' using errcode = '42501';
  end if;
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;

  if p_kind='plan' then
    with filtered as materialized (
      select p.*, t.tenant_code, t.tenant_name, pos.position_code, pos.position_name,
        o.organization_name, owner.employee_no owner_no, owner.employee_name owner_name,
        (select count(*) from public.hr_succession_candidate c where c.plan_id=p.id and c.status='active') active_candidate_count,
        (select count(*) from public.hr_succession_candidate c where c.plan_id=p.id and c.status='active' and c.readiness='ready_now') ready_now_count
      from public.hr_succession_plan p join public.sys_tenant t on t.id=p.tenant_id
      join public.mdm_position pos on pos.id=p.position_id
      left join public.mdm_organization o on o.id=pos.organization_id
      left join public.mdm_employee owner on owner.id=p.owner_employee_id
      where (p_tenant_id is null or p.tenant_id=p_tenant_id)
        and (p_status is null or p.status=p_status)
        and (v_keyword is null or p.plan_code ilike '%'||v_keyword||'%' or p.plan_name ilike '%'||v_keyword||'%'
          or pos.position_name ilike '%'||v_keyword||'%' or o.organization_name ilike '%'||v_keyword||'%')
    ), paged as (select * from filtered order by criticality desc, next_review_date, plan_name offset v_offset limit v_limit)
    select jsonb_build_object('records',coalesce(jsonb_agg((to_jsonb(paged)-'tenant_code'-'tenant_name'-'position_code'-'position_name'-'organization_name'-'owner_no'-'owner_name')||jsonb_build_object(
      'tenant',jsonb_build_object('id',tenant_id,'code',tenant_code,'name',tenant_name),
      'position',jsonb_build_object('id',position_id,'code',position_code,'name',position_name,'organization_name',organization_name),
      'owner',case when owner_employee_id is null then null else jsonb_build_object('id',owner_employee_id,'code',owner_no,'name',owner_name) end
    ) order by criticality desc,next_review_date,plan_name),'[]'::jsonb),'total',(select count(*) from filtered)) into v_result from paged;
    return coalesce(v_result,jsonb_build_object('records','[]'::jsonb,'total',0));
  end if;

  if p_kind='candidate' then
    with filtered as materialized (
      select c.*, p.plan_code, p.plan_name, pos.position_name,
        e.employee_no, e.employee_name, e.job_title, o.organization_name,
        (select count(*) from public.hr_succession_development_action a where a.candidate_id=c.id and a.status in ('planned','in_progress')) open_action_count
      from public.hr_succession_candidate c join public.hr_succession_plan p on p.id=c.plan_id
      join public.mdm_position pos on pos.id=p.position_id join public.mdm_employee e on e.id=c.employee_id
      left join public.mdm_organization o on o.id=e.organization_id
      where (p_tenant_id is null or c.tenant_id=p_tenant_id) and (p_status is null or c.status=p_status)
        and (v_keyword is null or p.plan_name ilike '%'||v_keyword||'%' or pos.position_name ilike '%'||v_keyword||'%'
          or e.employee_no ilike '%'||v_keyword||'%' or e.employee_name ilike '%'||v_keyword||'%')
    ), paged as (select * from filtered order by status, readiness, priority, employee_name offset v_offset limit v_limit)
    select jsonb_build_object('records',coalesce(jsonb_agg((to_jsonb(paged)-'plan_code'-'plan_name'-'position_name'-'employee_no'-'employee_name'-'job_title'-'organization_name')||jsonb_build_object(
      'plan',jsonb_build_object('id',plan_id,'code',plan_code,'name',plan_name,'position_name',position_name),
      'employee',jsonb_build_object('id',employee_id,'code',employee_no,'name',employee_name,'job_title',job_title,'organization_name',organization_name)
    ) order by status,readiness,priority,employee_name),'[]'::jsonb),'total',(select count(*) from filtered)) into v_result from paged;
    return coalesce(v_result,jsonb_build_object('records','[]'::jsonb,'total',0));
  end if;

  with filtered as materialized (
    select a.*, c.employee_id, e.employee_no, e.employee_name, p.plan_name, pos.position_name,
      owner.employee_no owner_no, owner.employee_name owner_name
    from public.hr_succession_development_action a join public.hr_succession_candidate c on c.id=a.candidate_id
    join public.mdm_employee e on e.id=c.employee_id join public.hr_succession_plan p on p.id=c.plan_id
    join public.mdm_position pos on pos.id=p.position_id left join public.mdm_employee owner on owner.id=a.owner_employee_id
    where (p_tenant_id is null or a.tenant_id=p_tenant_id) and (p_status is null or a.status=p_status)
      and (v_keyword is null or a.action_title ilike '%'||v_keyword||'%' or e.employee_no ilike '%'||v_keyword||'%'
        or e.employee_name ilike '%'||v_keyword||'%' or p.plan_name ilike '%'||v_keyword||'%')
  ), paged as (select * from filtered order by status,due_date,action_title offset v_offset limit v_limit)
  select jsonb_build_object('records',coalesce(jsonb_agg((to_jsonb(paged)-'employee_id'-'employee_no'-'employee_name'-'plan_name'-'position_name'-'owner_no'-'owner_name')||jsonb_build_object(
    'candidate',jsonb_build_object('id',candidate_id,'employee_id',employee_id,'employee_no',employee_no,'employee_name',employee_name,'plan_name',plan_name,'position_name',position_name),
    'owner',case when owner_employee_id is null then null else jsonb_build_object('id',owner_employee_id,'code',owner_no,'name',owner_name) end
  ) order by status,due_date,action_title),'[]'::jsonb),'total',(select count(*) from filtered)) into v_result from paged;
  return coalesce(v_result,jsonb_build_object('records','[]'::jsonb,'total',0));
end;
$$;


ALTER FUNCTION "public"."hr_list_succession_records_secure"("p_kind" "text", "p_from" integer, "p_to" integer, "p_keyword" "text", "p_status" "text", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_list_workforce_options_secure("text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_workforce_options_secure"("p_kind" "text", "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_current_tenant uuid := app_private.current_user_tenant_id();
begin
  if p_kind not in ('plan', 'organization', 'position') then raise exception '不支持的人力规划选项类型'; end if;
  if not app_private.can_execute_business_action('HrHeadcount', 'Hr:Headcount:View', null, false) then
    raise exception '当前账号没有查看人力规划的权限' using errcode = '42501';
  end if;
  if not app_private.is_platform_super() then p_tenant_id := v_current_tenant; end if;

  if p_kind = 'plan' then
    return (select coalesce(jsonb_agg(jsonb_build_object(
      'id', c.id, 'tenant_id', c.tenant_id, 'code', c.plan_no, 'name', c.plan_name,
      'status', c.status, 'period_start', c.period_start, 'period_end', c.period_end
    ) order by c.period_start desc), '[]'::jsonb)
    from public.hr_workforce_plan_cycle c
    where (p_tenant_id is null or c.tenant_id = p_tenant_id) and c.status <> 'cancelled');
  end if;
  if p_kind = 'organization' then
    return (select coalesce(jsonb_agg(jsonb_build_object(
      'id', o.id, 'tenant_id', o.tenant_id, 'code', o.organization_code, 'name', o.organization_name
    ) order by o.sort, o.organization_name), '[]'::jsonb)
    from public.mdm_organization o
    where (p_tenant_id is null or o.tenant_id = p_tenant_id) and o.status = '1');
  end if;
  return (select coalesce(jsonb_agg(jsonb_build_object(
    'id', p.id, 'tenant_id', p.tenant_id, 'organization_id', p.organization_id,
    'code', p.position_code, 'name', p.position_name, 'headcount_limit', p.headcount_limit,
    'current_count', coalesce(i.current_count,0)
  ) order by p.position_name), '[]'::jsonb)
  from public.mdm_position p
  left join lateral (
    select count(*)::integer current_count from public.mdm_employee_assignment a
    where a.tenant_id = p.tenant_id and a.position_id = p.id and a.primary_assignment
      and a.effective_end is null and a.assignment_status <> 'ended'
  ) i on true
  where (p_tenant_id is null or p.tenant_id = p_tenant_id) and p.enabled);
end
$$;


ALTER FUNCTION "public"."hr_list_workforce_options_secure"("p_kind" "text", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_list_workforce_records_secure("text", integer, integer, "text", "text", "uuid", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_list_workforce_records_secure"("p_kind" "text", "p_from" integer DEFAULT 0, "p_to" integer DEFAULT 19, "p_keyword" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_plan_id" "uuid" DEFAULT NULL::"uuid", "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_current_tenant uuid := app_private.current_user_tenant_id();
  v_offset integer := greatest(coalesce(p_from, 0), 0);
  v_limit integer := least(500, greatest(coalesce(p_to, 19) - greatest(coalesce(p_from, 0), 0) + 1, 1));
  v_keyword text := nullif(btrim(p_keyword), '');
  v_result jsonb;
begin
  if p_kind not in ('cycle', 'line', 'effective') then raise exception '不支持的人力规划记录类型'; end if;
  if not app_private.can_execute_business_action('HrHeadcount', 'Hr:Headcount:View', null, false) then
    raise exception '当前账号没有查看人力规划的权限' using errcode = '42501';
  end if;
  if not app_private.is_platform_super() then p_tenant_id := v_current_tenant; end if;

  if p_kind = 'cycle' then
    with filtered as materialized (
      select c.*, t.tenant_name,
        e.employee_no owner_no, e.employee_name owner_name,
        coalesce(x.line_count, 0) line_count,
        coalesce(x.baseline_count, 0) baseline_count,
        coalesce(x.planned_hires, 0) planned_hires,
        coalesce(x.planned_exits, 0) planned_exits,
        coalesce(x.target_count, 0) target_count,
        coalesce(x.planned_payroll, 0) planned_payroll
      from public.hr_workforce_plan_cycle c
      join public.sys_tenant t on t.id = c.tenant_id
      left join public.mdm_employee e on e.id = c.owner_employee_id and e.tenant_id = c.tenant_id
      left join lateral (
        select count(*)::integer line_count, coalesce(sum(l.baseline_count),0)::integer baseline_count,
          coalesce(sum(l.planned_hires),0)::integer planned_hires,
          coalesce(sum(l.planned_exits),0)::integer planned_exits,
          coalesce(sum(l.target_count),0)::integer target_count,
          coalesce(sum(l.planned_payroll),0)::numeric planned_payroll
        from public.hr_workforce_plan_line l where l.plan_id = c.id and l.tenant_id = c.tenant_id
      ) x on true
      where (p_tenant_id is null or c.tenant_id = p_tenant_id)
        and (p_status is null or c.status = p_status)
        and (v_keyword is null or c.plan_no ilike '%' || v_keyword || '%'
          or c.plan_name ilike '%' || v_keyword || '%' or e.employee_name ilike '%' || v_keyword || '%')
    ), paged as (
      select * from filtered order by period_start desc, create_time desc offset v_offset limit v_limit
    )
    select jsonb_build_object(
      'records', coalesce(jsonb_agg(
        (to_jsonb(paged) - 'tenant_name' - 'owner_no' - 'owner_name') || jsonb_build_object(
          'tenant', jsonb_build_object('id', tenant_id, 'name', tenant_name),
          'owner', case when owner_employee_id is null then null else jsonb_build_object(
            'id', owner_employee_id, 'code', owner_no, 'name', owner_name
          ) end
        ) order by period_start desc, create_time desc
      ), '[]'::jsonb),
      'total', (select count(*) from filtered)
    ) into v_result from paged;
    return coalesce(v_result, jsonb_build_object('records','[]'::jsonb,'total',0));
  end if;

  if p_kind = 'line' then
    with incumbent as (
      select a.tenant_id, a.position_id, count(*)::integer current_count
      from public.mdm_employee_assignment a
      where a.primary_assignment and a.effective_end is null and a.assignment_status <> 'ended'
      group by a.tenant_id, a.position_id
    ), requisitions as (
      select r.tenant_id, r.position_id,
        count(*) filter (where r.status not in ('completed','cancelled','rejected'))::integer requisition_count,
        coalesce(sum(greatest(r.opening_count - r.hired_count, 0))
          filter (where r.status not in ('completed','cancelled','rejected')), 0)::integer recruiting_count
      from public.hr_recruitment_requisition r group by r.tenant_id, r.position_id
    ), filtered as materialized (
      select l.*, c.plan_no, c.plan_name, c.status plan_status, c.period_start, c.period_end,
        o.organization_code org_code, o.organization_name org_name, p.position_code, p.position_name,
        coalesce(i.current_count, 0) current_count,
        coalesce(r.requisition_count, 0) requisition_count,
        coalesce(r.recruiting_count, 0) recruiting_count,
        l.target_count - coalesce(i.current_count, 0) forecast_gap
      from public.hr_workforce_plan_line l
      join public.hr_workforce_plan_cycle c on c.id = l.plan_id and c.tenant_id = l.tenant_id
      join public.mdm_organization o on o.id = l.organization_id and o.tenant_id = l.tenant_id
      join public.mdm_position p on p.id = l.position_id and p.tenant_id = l.tenant_id
      left join incumbent i on i.tenant_id = l.tenant_id and i.position_id = l.position_id
      left join requisitions r on r.tenant_id = l.tenant_id and r.position_id = l.position_id
      where (p_tenant_id is null or l.tenant_id = p_tenant_id)
        and (p_plan_id is null or l.plan_id = p_plan_id)
        and (p_status is null or l.priority = p_status)
        and (v_keyword is null or c.plan_no ilike '%' || v_keyword || '%'
          or c.plan_name ilike '%' || v_keyword || '%' or o.organization_name ilike '%' || v_keyword || '%'
          or p.position_code ilike '%' || v_keyword || '%' or p.position_name ilike '%' || v_keyword || '%')
    ), paged as (
      select * from filtered order by
        case priority when 'critical' then 1 when 'high' then 2 when 'normal' then 3 else 4 end,
        demand_date nulls last, position_name offset v_offset limit v_limit
    )
    select jsonb_build_object(
      'records', coalesce(jsonb_agg(
        (to_jsonb(paged) - 'plan_no' - 'plan_name' - 'org_code' - 'org_name' - 'position_code' - 'position_name')
        || jsonb_build_object(
          'plan', jsonb_build_object('id', plan_id, 'code', plan_no, 'name', plan_name, 'status', plan_status),
          'organization', jsonb_build_object('id', organization_id, 'code', org_code, 'name', org_name),
          'position', jsonb_build_object('id', position_id, 'code', position_code, 'name', position_name)
        )
      ), '[]'::jsonb),
      'total', (select count(*) from filtered)
    ) into v_result from paged;
    return coalesce(v_result, jsonb_build_object('records','[]'::jsonb,'total',0));
  end if;

  with incumbent as (
    select a.tenant_id, a.position_id, count(*)::integer current_count
    from public.mdm_employee_assignment a
    where a.primary_assignment and a.effective_end is null and a.assignment_status <> 'ended'
    group by a.tenant_id, a.position_id
  ), latest_control as (
    select distinct on (h.tenant_id, h.position_id) h.*
    from public.hr_position_headcount h
    where h.enabled and h.effective_from <= current_date
      and (h.effective_to is null or h.effective_to >= current_date)
    order by h.tenant_id, h.position_id, h.effective_from desc, h.update_time desc
  ), filtered as materialized (
    select coalesce(h.id, p.id) id, p.tenant_id, p.organization_id, p.id position_id,
      coalesce(h.approved_count, p.headcount_limit) approved_count,
      h.effective_from, h.effective_to, coalesce(h.enabled, true) enabled, h.remark,
      h.source_plan_line_id, o.organization_code org_code, o.organization_name org_name,
      p.position_code, p.position_name,
      coalesce(i.current_count, 0) current_count,
      coalesce(h.approved_count, p.headcount_limit) - coalesce(i.current_count, 0) vacancy_count,
      h.create_by, h.create_time, h.update_by, h.update_time
    from public.mdm_position p
    join public.mdm_organization o on o.id = p.organization_id and o.tenant_id = p.tenant_id
    left join latest_control h on h.tenant_id = p.tenant_id and h.position_id = p.id
    left join incumbent i on i.tenant_id = p.tenant_id and i.position_id = p.id
    where (p_tenant_id is null or p.tenant_id = p_tenant_id)
      and (p_status is null or (p_status = 'vacant' and coalesce(h.approved_count,p.headcount_limit) > coalesce(i.current_count,0))
        or (p_status = 'full' and coalesce(h.approved_count,p.headcount_limit) = coalesce(i.current_count,0))
        or (p_status = 'over' and coalesce(h.approved_count,p.headcount_limit) < coalesce(i.current_count,0)))
      and (v_keyword is null or o.organization_name ilike '%' || v_keyword || '%'
        or p.position_code ilike '%' || v_keyword || '%' or p.position_name ilike '%' || v_keyword || '%')
  ), paged as (
    select * from filtered order by vacancy_count desc, org_name, position_name offset v_offset limit v_limit
  )
  select jsonb_build_object(
    'records', coalesce(jsonb_agg(
      (to_jsonb(paged) - 'org_code' - 'org_name' - 'position_code' - 'position_name')
      || jsonb_build_object(
        'organization', jsonb_build_object('id', organization_id, 'code', org_code, 'name', org_name),
        'position', jsonb_build_object('id', position_id, 'code', position_code, 'name', position_name)
      )
    ), '[]'::jsonb),
    'total', (select count(*) from filtered)
  ) into v_result from paged;
  return coalesce(v_result, jsonb_build_object('records','[]'::jsonb,'total',0));
end
$$;


ALTER FUNCTION "public"."hr_list_workforce_records_secure"("p_kind" "text", "p_from" integer, "p_to" integer, "p_keyword" "text", "p_status" "text", "p_plan_id" "uuid", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_organization_design_overview_secure("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_organization_design_overview_secure"("p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    SET "TimeZone" TO 'Asia/Shanghai'
    AS $$
declare v_tenant_id uuid:=app_private.current_user_tenant_id();
begin
  if auth.uid() is null or not app_private.can_execute_business_action(
    'HrOrganizationDesign','Hr:OrganizationDesign:View',null,false
  ) then raise exception '当前账号没有查看组织变革方案的权限' using errcode='42501'; end if;
  if not app_private.is_platform_super() then p_tenant_id:=v_tenant_id; end if;
  return jsonb_build_object(
    'draft_count',(select count(*) from public.hr_organization_design_scenario s where (p_tenant_id is null or s.tenant_id=p_tenant_id) and s.status in ('draft','rejected')),
    'review_count',(select count(*) from public.hr_organization_design_scenario s where (p_tenant_id is null or s.tenant_id=p_tenant_id) and s.status='impact_review'),
    'approved_count',(select count(*) from public.hr_organization_design_scenario s where (p_tenant_id is null or s.tenant_id=p_tenant_id) and s.status='approved'),
    'handoff_count',(select count(*) from public.hr_organization_design_scenario s where (p_tenant_id is null or s.tenant_id=p_tenant_id) and s.status='handed_off'),
    'high_risk_count',(select count(*) from public.hr_organization_design_scenario s where (p_tenant_id is null or s.tenant_id=p_tenant_id) and s.status not in ('cancelled','handed_off') and s.risk_level in ('high','critical')),
    'change_count',(select count(*) from public.hr_organization_design_change c join public.hr_organization_design_scenario s on s.id=c.scenario_id where (p_tenant_id is null or c.tenant_id=p_tenant_id) and s.status<>'cancelled'),
    'impacted_employee_count',(select coalesce(sum(c.impacted_employee_count),0) from public.hr_organization_design_change c join public.hr_organization_design_scenario s on s.id=c.scenario_id where (p_tenant_id is null or c.tenant_id=p_tenant_id) and s.status in ('impact_review','approved','handed_off')),
    'impacted_security_user_count',(select coalesce(sum(c.impacted_security_user_count),0) from public.hr_organization_design_change c join public.hr_organization_design_scenario s on s.id=c.scenario_id where (p_tenant_id is null or c.tenant_id=p_tenant_id) and s.status in ('impact_review','approved','handed_off'))
  );
end;
$$;


ALTER FUNCTION "public"."hr_organization_design_overview_secure"("p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_people_analytics_overview_business_date_core("date", integer, "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_people_analytics_overview_business_date_core"("p_as_of_date" "date" DEFAULT CURRENT_DATE, "p_period_months" integer DEFAULT 12, "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    SET "TimeZone" TO 'Asia/Shanghai'
    AS $$
declare
  v_current_tenant uuid := app_private.current_user_tenant_id();
  v_tenant_id uuid;
  v_as_of date := least(coalesce(p_as_of_date, current_date), current_date);
  v_months integer := least(36, greatest(coalesce(p_period_months, 12), 3));
  v_period_start date;
  v_opening_date date;
  v_privacy_threshold constant integer := 5;
  v_result jsonb;
begin
  if auth.uid() is null or not app_private.can_execute_business_action(
    'HrPeopleAnalytics', 'Hr:PeopleAnalytics:View', null, false
  ) then
    raise exception '当前账号没有查看人力分析的权限' using errcode = '42501';
  end if;

  if app_private.is_platform_super() then
    v_tenant_id := coalesce(p_tenant_id, v_current_tenant);
  else
    v_tenant_id := v_current_tenant;
  end if;

  if v_tenant_id is null then
    raise exception '当前账号缺少有效租户上下文' using errcode = '22023';
  end if;

  v_period_start := (date_trunc('month', v_as_of)::date - (v_months - 1) * interval '1 month')::date;
  v_opening_date := v_period_start - 1;

  with recursive
  month_axis as (
    select generate_series(
      date_trunc('month', v_period_start)::date,
      date_trunc('month', v_as_of)::date,
      interval '1 month'
    )::date as month_start
  ),
  month_points as (
    select month_start,
      least((month_start + interval '1 month - 1 day')::date, v_as_of) as month_end
    from month_axis
  ),
  opening_population as (
    select assignment.employee_id, assignment.fte
    from public.mdm_employee_assignment assignment
    where assignment.tenant_id = v_tenant_id
      and assignment.primary_assignment
      and assignment.effective_start <= v_opening_date
      and (assignment.effective_end is null or assignment.effective_end >= v_opening_date)
  ),
  closing_population as (
    select assignment.employee_id, assignment.organization_id, assignment.position_id,
      assignment.fte, assignment.effective_start,
      employee.hire_date, employee.employment_type
    from public.mdm_employee_assignment assignment
    join public.mdm_employee employee
      on employee.id = assignment.employee_id and employee.tenant_id = assignment.tenant_id
    where assignment.tenant_id = v_tenant_id
      and assignment.primary_assignment
      and assignment.effective_start <= v_as_of
      and (assignment.effective_end is null or assignment.effective_end >= v_as_of)
  ),
  flow_summary as (
    select
      count(*) filter (
        where employee.hire_date between v_period_start and v_as_of
      )::integer as hires,
      count(*) filter (
        where employee.leave_date between v_period_start and v_as_of
      )::integer as exits
    from public.mdm_employee employee
    where employee.tenant_id = v_tenant_id
  ),
  monthly_flow as (
    select point.month_start, point.month_end,
      (select count(*)::integer
       from public.mdm_employee_assignment assignment
       where assignment.tenant_id = v_tenant_id
         and assignment.primary_assignment
         and assignment.effective_start <= point.month_end
         and (assignment.effective_end is null or assignment.effective_end >= point.month_end)
      ) as headcount,
      (select count(*)::integer
       from public.mdm_employee employee
       where employee.tenant_id = v_tenant_id
         and employee.hire_date between point.month_start and point.month_end
      ) as hires,
      (select count(*)::integer
       from public.mdm_employee employee
       where employee.tenant_id = v_tenant_id
         and employee.leave_date between point.month_start and point.month_end
      ) as exits
    from month_points point
  ),
  organization_raw as (
    select organization.organization_name as name,
      count(*)::integer as headcount,
      round(sum(population.fte), 2) as fte
    from closing_population population
    join public.mdm_organization organization
      on organization.id = population.organization_id and organization.tenant_id = v_tenant_id
    group by organization.id, organization.organization_name
  ),
  organization_safe as (
    select name, headcount, fte, false as protected
    from organization_raw
    where headcount >= v_privacy_threshold
    union all
    select '其他受保护组织', sum(headcount)::integer, round(sum(fte), 2), true
    from organization_raw
    where headcount < v_privacy_threshold
    having sum(headcount) > 0
  ),
  employment_raw as (
    select coalesce(nullif(btrim(employment_type), ''), 'unknown') as key,
      count(*)::integer as headcount
    from closing_population
    group by coalesce(nullif(btrim(employment_type), ''), 'unknown')
  ),
  employment_safe as (
    select key, headcount, false as protected
    from employment_raw
    where headcount >= v_privacy_threshold
    union all
    select 'protected', sum(headcount)::integer, true
    from employment_raw
    where headcount < v_privacy_threshold
    having sum(headcount) > 0
  ),
  tenure_buckets as (
    select bucket_key, bucket_label, sort,
      count(population.employee_id)::integer as headcount
    from (values
      ('under_1', '1 年以内', 1, 0::numeric, 1::numeric),
      ('year_1_3', '1–3 年', 2, 1::numeric, 3::numeric),
      ('year_3_5', '3–5 年', 3, 3::numeric, 5::numeric),
      ('year_5_10', '5–10 年', 4, 5::numeric, 10::numeric),
      ('year_10_plus', '10 年以上', 5, 10::numeric, null::numeric)
    ) bucket(bucket_key, bucket_label, sort, min_years, max_years)
    left join closing_population population
      on population.hire_date is not null
      and (v_as_of - population.hire_date) / 365.25 >= bucket.min_years
      and (bucket.max_years is null or (v_as_of - population.hire_date) / 365.25 < bucket.max_years)
    group by bucket_key, bucket_label, sort
  ),
  data_quality as (
    select * from (values
      ('hire_date', '入职日期',
        (select count(*) from closing_population where hire_date is not null)::integer),
      ('organization', '组织归属',
        (select count(*) from closing_population where organization_id is not null)::integer),
      ('position', '岗位归属',
        (select count(*) from closing_population where position_id is not null)::integer),
      ('employment_type', '用工类型',
        (select count(*) from closing_population where nullif(btrim(employment_type), '') is not null)::integer)
    ) quality(key, label, complete_count)
  ),
  totals as (
    select
      (select count(*)::integer from opening_population) as opening_headcount,
      (select count(*)::integer from closing_population) as ending_headcount,
      (select coalesce(round(sum(fte), 2), 0) from closing_population) as ending_fte,
      (select hires from flow_summary) as hires,
      (select exits from flow_summary) as exits,
      (select coalesce(round(avg((v_as_of - hire_date) / 365.25), 1), 0)
       from closing_population where hire_date is not null) as average_tenure_years
  )
  select jsonb_build_object(
    'as_of_date', v_as_of,
    'period_start_date', v_period_start,
    'period_months', v_months,
    'privacy_threshold', v_privacy_threshold,
    'generated_at', now(),
    'overview', jsonb_build_object(
      'opening_headcount', totals.opening_headcount,
      'ending_headcount', totals.ending_headcount,
      'ending_fte', totals.ending_fte,
      'hires', totals.hires,
      'exits', totals.exits,
      'net_change', totals.ending_headcount - totals.opening_headcount,
      'turnover_rate', case
        when (totals.opening_headcount + totals.ending_headcount) = 0 then 0
        else round(100.0 * totals.exits /
          ((totals.opening_headcount + totals.ending_headcount) / 2.0), 1)
      end,
      'average_tenure_years', totals.average_tenure_years,
      'data_completeness_rate', case when totals.ending_headcount = 0 then 0 else (
        select round(100.0 * sum(complete_count) /
          (totals.ending_headcount * count(*)), 1) from data_quality
      ) end
    ),
    'flow_trend', coalesce((
      select jsonb_agg(jsonb_build_object(
        'month', to_char(month_start, 'YYYY-MM'),
        'headcount', headcount,
        'hires', hires,
        'exits', exits
      ) order by month_start)
      from monthly_flow
    ), '[]'::jsonb),
    'organization_distribution', coalesce((
      select jsonb_agg(jsonb_build_object(
        'name', name,
        'headcount', headcount,
        'fte', fte,
        'share', case when totals.ending_headcount = 0 then 0
          else round(100.0 * headcount / totals.ending_headcount, 1) end,
        'protected', protected
      ) order by protected, headcount desc, name)
      from organization_safe
    ), '[]'::jsonb),
    'employment_distribution', coalesce((
      select jsonb_agg(jsonb_build_object(
        'key', key,
        'headcount', headcount,
        'share', case when totals.ending_headcount = 0 then 0
          else round(100.0 * headcount / totals.ending_headcount, 1) end,
        'protected', protected
      ) order by protected, headcount desc, key)
      from employment_safe
    ), '[]'::jsonb),
    'tenure_distribution', coalesce((
      select jsonb_agg(jsonb_build_object(
        'key', bucket_key,
        'label', bucket_label,
        'headcount', headcount,
        'share', case when totals.ending_headcount = 0 then 0
          else round(100.0 * headcount / totals.ending_headcount, 1) end
      ) order by sort)
      from tenure_buckets
    ), '[]'::jsonb),
    'data_quality', coalesce((
      select jsonb_agg(jsonb_build_object(
        'key', key,
        'label', label,
        'complete_count', complete_count,
        'total_count', totals.ending_headcount,
        'rate', case when totals.ending_headcount = 0 then 0
          else round(100.0 * complete_count / totals.ending_headcount, 1) end
      ) order by key)
      from data_quality
    ), '[]'::jsonb)
  ) into v_result
  from totals;

  return v_result;
end
$$;


ALTER FUNCTION "public"."hr_people_analytics_overview_business_date_core"("p_as_of_date" "date", "p_period_months" integer, "p_tenant_id" "uuid") OWNER TO "postgres";

