CREATE OR REPLACE FUNCTION "public"."hr_people_analytics_overview_secure"("p_as_of_date" "date" DEFAULT NULL::"date", "p_period_months" integer DEFAULT 12, "p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    SET "TimeZone" TO 'Asia/Shanghai'
    AS $$
begin
  return public.hr_people_analytics_overview_business_date_core(
    coalesce(p_as_of_date, current_date),
    p_period_months,
    p_tenant_id
  );
end
$$;


