--
-- Name: hr_performance_overview_secure("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_performance_overview_secure"("p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_featured public.hr_performance_cycle%rowtype;
begin
  if not app_private.can_execute_business_action('HrPerformance', 'Hr:Performance:View', null, false) then
    raise exception '当前账号没有查看绩效管理工作台的权限' using errcode = '42501';
  end if;
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;

  select c.* into v_featured
  from public.hr_performance_cycle c
  where (p_tenant_id is null or c.tenant_id = p_tenant_id)
    and c.status in ('active', 'reviewing')
  order by c.start_date desc, c.create_time desc
  limit 1;

  return jsonb_build_object(
    'active_cycle_count', (
      select count(*) from public.hr_performance_cycle c
      where (p_tenant_id is null or c.tenant_id = p_tenant_id)
        and c.status in ('active', 'reviewing')
    ),
    'in_scope_employee_count', (
      select count(*) from public.hr_performance_review r
      where (p_tenant_id is null or r.tenant_id = p_tenant_id)
        and r.status <> 'cancelled'
        and (v_featured.id is null or r.cycle_id = v_featured.id)
    ),
    'completion_rate', (
      select coalesce(round(100 * count(*) filter (where r.status = 'completed')::numeric
        / nullif(count(*) filter (where r.status <> 'cancelled'), 0), 1), 0)
      from public.hr_performance_review r
      where (p_tenant_id is null or r.tenant_id = p_tenant_id)
        and (v_featured.id is null or r.cycle_id = v_featured.id)
    ),
    'at_risk_check_in_count', (
      with latest as (
        select distinct on (c.review_id) c.review_id, c.risk_status
        from public.hr_performance_check_in c
        join public.hr_performance_review r on r.id = c.review_id and r.tenant_id = c.tenant_id
        where (p_tenant_id is null or c.tenant_id = p_tenant_id)
          and (v_featured.id is null or r.cycle_id = v_featured.id)
        order by c.review_id, c.check_in_date desc, c.create_time desc
      )
      select count(*) from latest where risk_status in ('attention', 'off_track')
    ),
    'pending_calibration_count', (
      select count(*) from public.hr_performance_review r
      where (p_tenant_id is null or r.tenant_id = p_tenant_id)
        and r.status = 'confirmed'
        and (v_featured.id is null or r.cycle_id = v_featured.id)
    ),
    'featured_cycle', case when v_featured.id is null then null else jsonb_build_object(
      'id', v_featured.id,
      'cycle_code', v_featured.cycle_code,
      'cycle_name', v_featured.cycle_name,
      'status', v_featured.status,
      'start_date', v_featured.start_date,
      'end_date', v_featured.end_date,
      'goal_setting_count', (select count(*) from public.hr_performance_review r
        where r.tenant_id = v_featured.tenant_id and r.cycle_id = v_featured.id
          and r.status in ('draft', 'self_review')),
      'manager_review_count', (select count(*) from public.hr_performance_review r
        where r.tenant_id = v_featured.tenant_id and r.cycle_id = v_featured.id
          and r.status = 'manager_review'),
      'calibration_count', (select count(*) from public.hr_performance_review r
        where r.tenant_id = v_featured.tenant_id and r.cycle_id = v_featured.id
          and r.status = 'confirmed'),
      'completed_count', (select count(*) from public.hr_performance_review r
        where r.tenant_id = v_featured.tenant_id and r.cycle_id = v_featured.id
          and r.status = 'completed')
    ) end
  );
end
$$;


ALTER FUNCTION "public"."hr_performance_overview_secure"("p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_policy_acknowledgement_overview_secure("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_policy_acknowledgement_overview_secure"("p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    SET "TimeZone" TO 'Asia/Shanghai'
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_total integer;
  v_acknowledged integer;
begin
  if auth.uid() is null or not app_private.can_execute_business_action(
    'HrPolicyAcknowledgement','Hr:PolicyAcknowledgement:View',null,false
  ) then raise exception '当前账号没有查看政策与签收的权限' using errcode='42501'; end if;
  if not app_private.is_platform_super() then p_tenant_id:=v_tenant_id; end if;

  select count(*)::integer,
    count(*) filter(where receipt.status in ('acknowledged','waived'))::integer
  into v_total,v_acknowledged
  from public.hr_policy_receipt receipt
  join public.hr_policy_document policy on policy.id=receipt.policy_id
  where (p_tenant_id is null or receipt.tenant_id=p_tenant_id)
    and policy.status='published';

  return jsonb_build_object(
    'draft_policy_count',(select count(*) from public.hr_policy_document policy where (p_tenant_id is null or policy.tenant_id=p_tenant_id) and policy.status='draft'),
    'published_policy_count',(select count(*) from public.hr_policy_document policy where (p_tenant_id is null or policy.tenant_id=p_tenant_id) and policy.status='published'),
    'scheduled_policy_count',(select count(*) from public.hr_policy_document policy where (p_tenant_id is null or policy.tenant_id=p_tenant_id) and policy.status='published' and policy.effective_date>current_date),
    'receipt_count',v_total,
    'acknowledged_count',v_acknowledged,
    'pending_count',greatest(v_total-v_acknowledged,0),
    'overdue_count',(select count(*) from public.hr_policy_receipt receipt join public.hr_policy_document policy on policy.id=receipt.policy_id where (p_tenant_id is null or receipt.tenant_id=p_tenant_id) and policy.status='published' and receipt.status='pending' and receipt.due_date<current_date),
    'completion_rate',case when v_total=0 then 0 else round(v_acknowledged*100.0/v_total,1) end,
    'evidence_access',app_private.can_execute_business_action('HrPolicyAcknowledgement','Hr:PolicyAcknowledgement:Evidence:View',null,false)
  );
end;
$$;


ALTER FUNCTION "public"."hr_policy_acknowledgement_overview_secure"("p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_recruitment_overview_secure("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_recruitment_overview_secure"("p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
begin
  if not app_private.can_execute_business_action('HrRecruitment', 'Hr:Recruitment:View', null, false) then
    raise exception '当前账号没有查看招聘工作台的权限' using errcode = '42501';
  end if;
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;
  return jsonb_build_object(
    'active_requisition_count', (
      select count(*) from public.hr_recruitment_requisition r
      where (p_tenant_id is null or r.tenant_id = p_tenant_id) and r.status = 'effective'
    ),
    'open_candidate_count', (
      select count(*) from public.hr_candidate c
      where (p_tenant_id is null or c.tenant_id = p_tenant_id)
        and c.stage in ('new', 'screening', 'interview', 'offer')
    ),
    'upcoming_interview_count', (
      select count(*) from public.hr_recruitment_interview i
      where (p_tenant_id is null or i.tenant_id = p_tenant_id)
        and i.status = 'scheduled' and i.scheduled_start_at <= now() + interval '7 days'
    ),
    'awaiting_offer_response_count', (
      select count(*) from public.hr_recruitment_offer o
      where (p_tenant_id is null or o.tenant_id = p_tenant_id) and o.status = 'sent'
    ),
    'accepted_offer_count', (
      select count(*) from public.hr_recruitment_offer o
      where (p_tenant_id is null or o.tenant_id = p_tenant_id) and o.status = 'accepted'
    ),
    'pending_handoff_count', (
      select count(*) from public.hr_recruitment_handoff h
      where (p_tenant_id is null or h.tenant_id = p_tenant_id) and h.status in ('pending', 'ready')
    ),
    'overdue_task_count', (
      select count(*) from public.hr_recruitment_onboarding_task t
      where (p_tenant_id is null or t.tenant_id = p_tenant_id)
        and t.status in ('pending', 'in_progress') and t.due_date < current_date
    ),
    'hired_candidate_count', (
      select count(*) from public.hr_candidate c
      where (p_tenant_id is null or c.tenant_id = p_tenant_id) and c.stage = 'hired'
    )
  );
end
$$;


ALTER FUNCTION "public"."hr_recruitment_overview_secure"("p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_resolve_workspace_references_secure("uuid"[], "uuid"[], "uuid"[], "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_resolve_workspace_references_secure"("p_employee_ids" "uuid"[] DEFAULT ARRAY[]::"uuid"[], "p_position_ids" "uuid"[] DEFAULT ARRAY[]::"uuid"[], "p_organization_ids" "uuid"[] DEFAULT ARRAY[]::"uuid"[], "p_headcount_scopes" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_is_platform boolean := app_private.is_platform_super();
  v_tenant_id uuid := app_private.current_user_tenant_id();
begin
  if not v_is_platform and not (
    app_private.has_permission('Hr:Employee:View')
    or app_private.has_permission('Hr:Position:View')
    or app_private.has_permission('Hr:PersonnelChange:View')
    or app_private.has_permission('Hr:Lifecycle:View')
    or app_private.has_permission('Hr:Compliance:View')
    or app_private.has_permission('Hr:Headcount:View')
    or app_private.has_permission('Hr:Attendance:View')
    or app_private.has_permission('Hr:SelfService:View')
    or app_private.has_permission('Hr:Performance:View')
    or app_private.has_permission('Hr:Talent:View')
    or app_private.has_permission('Hr:Recruitment:View')
  ) then
    raise exception '当前账号没有查看人力资源引用数据的权限' using errcode='42501';
  end if;

  return jsonb_build_object(
    'employees',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',e.id,'employeeNo',e.employee_no,'employeeName',e.employee_name
      ) order by e.employee_name,e.employee_no)
      from public.mdm_employee e
      where e.id=any(coalesce(p_employee_ids,array[]::uuid[]))
        and (v_is_platform or e.tenant_id=v_tenant_id)
    ),'[]'::jsonb),
    'positions',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',p.id,'positionCode',p.position_code,'positionName',p.position_name
      ) order by p.position_name,p.position_code)
      from public.mdm_position p
      where p.id=any(coalesce(p_position_ids,array[]::uuid[]))
        and (v_is_platform or p.tenant_id=v_tenant_id)
    ),'[]'::jsonb),
    'organizations',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',o.id,'organizationCode',o.organization_code,'organizationName',o.organization_name
      ) order by o.organization_name,o.organization_code)
      from public.mdm_organization o
      where o.id=any(coalesce(p_organization_ids,array[]::uuid[]))
        and (v_is_platform or o.tenant_id=v_tenant_id)
    ),'[]'::jsonb),
    'headcounts',coalesce((
      select jsonb_agg(jsonb_build_object(
        'organizationId',scope.organization_id,
        'positionId',scope.position_id,
        'occupiedCount',(
          select count(*) from public.mdm_employee e
          where e.organization_id=scope.organization_id and e.position_id=scope.position_id
            and e.employment_status<>'terminated'
            and (v_is_platform or e.tenant_id=v_tenant_id)
        )
      ))
      from jsonb_to_recordset(coalesce(p_headcount_scopes,'[]'::jsonb))
        as scope(organization_id uuid,position_id uuid)
    ),'[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."hr_resolve_workspace_references_secure"("p_employee_ids" "uuid"[], "p_position_ids" "uuid"[], "p_organization_ids" "uuid"[], "p_headcount_scopes" "jsonb") OWNER TO "postgres";

--

--
-- Name: hr_review_succession_candidate_secure("uuid", "text", "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_review_succession_candidate_secure"("p_id" "uuid", "p_action" "text", "p_comment" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_tenant_id uuid:=app_private.current_user_tenant_id();
begin
  if not app_private.can_execute_business_action('HrSuccession','Hr:Succession:Candidate:Review',null,false) then raise exception 'Missing succession review permission' using errcode='42501'; end if;
  if p_action not in ('activate','withdraw','place') then raise exception '不支持的候选人评审动作'; end if;
  update public.hr_succession_candidate set status=case p_action when 'activate' then 'active' when 'withdraw' then 'withdrawn' else 'placed' end,last_reviewed_on=current_date,review_comment=coalesce(nullif(btrim(p_comment),''),review_comment)
  where id=p_id and (app_private.is_platform_super() or tenant_id=v_tenant_id);
  if not found then raise exception '继任候选人不存在或无权操作'; end if;
end;
$$;


ALTER FUNCTION "public"."hr_review_succession_candidate_secure"("p_id" "uuid", "p_action" "text", "p_comment" "text") OWNER TO "postgres";

--

--
-- Name: hr_save_absence_master_secure("text", "uuid", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_save_absence_master_secure"("p_kind" "text", "p_id" "uuid" DEFAULT NULL::"uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := coalesce(nullif(p_payload->>'tenant_id', '')::uuid, app_private.current_user_tenant_id());
  v_permission text := case when p_id is null then 'Hr:Absence:Policy:Add' else 'Hr:Absence:Policy:Edit' end;
  v_result_id uuid;
begin
  if p_kind not in ('type', 'policy') then raise exception '不支持的假勤主数据类型'; end if;
  if not app_private.can_execute_business_action('HrAbsence', v_permission, null, false) then
    raise exception 'Missing absence policy permission' using errcode = '42501';
  end if;
  if not app_private.is_platform_super() then v_tenant_id := app_private.current_user_tenant_id(); end if;
  if v_tenant_id is null then raise exception '无法确定租户'; end if;

  if p_kind = 'type' then
    insert into public.hr_leave_type(
      id, tenant_id, leave_code, leave_name, category, unit, paid_ratio,
      minimum_increment, proof_required_after, color, enabled, sort, description
    ) values (
      coalesce(p_id, gen_random_uuid()), v_tenant_id,
      upper(btrim(p_payload->>'leave_code')), btrim(p_payload->>'leave_name'),
      p_payload->>'category', coalesce(p_payload->>'unit', 'day'),
      coalesce((p_payload->>'paid_ratio')::numeric, 1),
      coalesce((p_payload->>'minimum_increment')::numeric, 0.5),
      nullif(p_payload->>'proof_required_after', '')::numeric,
      coalesce(nullif(p_payload->>'color', ''), '#6366f1'),
      coalesce((p_payload->>'enabled')::boolean, true),
      coalesce((p_payload->>'sort')::integer, 0), nullif(btrim(p_payload->>'description'), '')
    )
    on conflict (id) do update set
      leave_code = excluded.leave_code, leave_name = excluded.leave_name,
      category = excluded.category, unit = excluded.unit, paid_ratio = excluded.paid_ratio,
      minimum_increment = excluded.minimum_increment,
      proof_required_after = excluded.proof_required_after, color = excluded.color,
      enabled = excluded.enabled, sort = excluded.sort, description = excluded.description
    where public.hr_leave_type.tenant_id = v_tenant_id
    returning id into v_result_id;
    if v_result_id is null then raise exception '假别不存在或无权修改'; end if;
    return v_result_id;
  end if;

  insert into public.hr_leave_policy(
    id, tenant_id, leave_type_id, policy_code, policy_name, scope_type,
    organization_id, employee_id, grade_id, entitlement_method, annual_quota,
    monthly_accrual, carryover_limit, carryover_expiry_months, allow_negative,
    negative_limit, probation_eligible, effective_from, effective_to, status, description
  ) values (
    coalesce(p_id, gen_random_uuid()), v_tenant_id,
    (p_payload->>'leave_type_id')::uuid, upper(btrim(p_payload->>'policy_code')),
    btrim(p_payload->>'policy_name'), coalesce(p_payload->>'scope_type', 'all'),
    nullif(p_payload->>'organization_id', '')::uuid,
    nullif(p_payload->>'employee_id', '')::uuid,
    nullif(p_payload->>'grade_id', '')::uuid,
    coalesce(p_payload->>'entitlement_method', 'annual'),
    coalesce((p_payload->>'annual_quota')::numeric, 0),
    coalesce((p_payload->>'monthly_accrual')::numeric, 0),
    coalesce((p_payload->>'carryover_limit')::numeric, 0),
    nullif(p_payload->>'carryover_expiry_months', '')::integer,
    coalesce((p_payload->>'allow_negative')::boolean, false),
    coalesce((p_payload->>'negative_limit')::numeric, 0),
    coalesce((p_payload->>'probation_eligible')::boolean, false),
    (p_payload->>'effective_from')::date,
    nullif(p_payload->>'effective_to', '')::date,
    coalesce(p_payload->>'status', 'draft'), nullif(btrim(p_payload->>'description'), '')
  )
  on conflict (id) do update set
    leave_type_id = excluded.leave_type_id, policy_code = excluded.policy_code,
    policy_name = excluded.policy_name, scope_type = excluded.scope_type,
    organization_id = excluded.organization_id, employee_id = excluded.employee_id,
    grade_id = excluded.grade_id, entitlement_method = excluded.entitlement_method,
    annual_quota = excluded.annual_quota, monthly_accrual = excluded.monthly_accrual,
    carryover_limit = excluded.carryover_limit,
    carryover_expiry_months = excluded.carryover_expiry_months,
    allow_negative = excluded.allow_negative, negative_limit = excluded.negative_limit,
    probation_eligible = excluded.probation_eligible,
    effective_from = excluded.effective_from, effective_to = excluded.effective_to,
    status = excluded.status, description = excluded.description
  where public.hr_leave_policy.tenant_id = v_tenant_id
  returning id into v_result_id;
  if v_result_id is null then raise exception '休假政策不存在或无权修改'; end if;
  return v_result_id;
end;
$$;


ALTER FUNCTION "public"."hr_save_absence_master_secure"("p_kind" "text", "p_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: hr_save_attendance_record_secure("text", "uuid", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_save_attendance_record_secure"("p_kind" "text", "p_id" "uuid", "p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_target_tenant uuid := coalesce((p_payload->>'tenant_id')::uuid,v_tenant_id);
  v_id uuid;
  v_record public.hr_attendance_record;
  v_shift_id uuid;
  v_code text;
begin
  if p_kind not in ('shift','assignment','record','correction','period') then raise exception '不支持的考勤记录类型'; end if;
  if not app_private.can_execute_business_action('HrAttendance',
    case when p_id is null then 'Hr:Attendance:Add' else 'Hr:Attendance:Edit' end,null,false) then
    raise exception '当前账号没有维护考勤工时的权限' using errcode='42501';
  end if;
  if not app_private.is_platform_super() then v_target_tenant:=v_tenant_id; end if;
  if v_target_tenant is null then raise exception '请选择租户'; end if;

  if p_kind='shift' then
    if nullif(btrim(p_payload->>'shift_code'),'') is null or nullif(btrim(p_payload->>'shift_name'),'') is null then
      raise exception '班次编码和名称不能为空';
    end if;
    if not exists(select 1 from pg_catalog.pg_timezone_names where name=coalesce(nullif(p_payload->>'time_zone',''),'Asia/Shanghai')) then
      raise exception '班次时区无效';
    end if;
    if p_id is null then
      insert into public.hr_shift(tenant_id,shift_code,shift_name,shift_type,start_time,end_time,break_minutes,
        cross_day,enabled,time_zone,late_grace_minutes,early_leave_grace_minutes,remark)
      values(v_target_tenant,btrim(p_payload->>'shift_code'),btrim(p_payload->>'shift_name'),
        coalesce(p_payload->>'shift_type','regular'),(p_payload->>'start_time')::time,(p_payload->>'end_time')::time,
        coalesce((p_payload->>'break_minutes')::integer,0),coalesce((p_payload->>'cross_day')::boolean,false),
        coalesce((p_payload->>'enabled')::boolean,true),coalesce(nullif(p_payload->>'time_zone',''),'Asia/Shanghai'),
        coalesce((p_payload->>'late_grace_minutes')::integer,0),
        coalesce((p_payload->>'early_leave_grace_minutes')::integer,0),nullif(btrim(p_payload->>'remark'),''))
      returning id into v_id;
    else
      update public.hr_shift set shift_code=btrim(p_payload->>'shift_code'),shift_name=btrim(p_payload->>'shift_name'),
        shift_type=coalesce(p_payload->>'shift_type',shift_type),start_time=(p_payload->>'start_time')::time,
        end_time=(p_payload->>'end_time')::time,break_minutes=coalesce((p_payload->>'break_minutes')::integer,0),
        cross_day=coalesce((p_payload->>'cross_day')::boolean,false),enabled=coalesce((p_payload->>'enabled')::boolean,true),
        time_zone=coalesce(nullif(p_payload->>'time_zone',''),'Asia/Shanghai'),
        late_grace_minutes=coalesce((p_payload->>'late_grace_minutes')::integer,0),
        early_leave_grace_minutes=coalesce((p_payload->>'early_leave_grace_minutes')::integer,0),
        remark=nullif(btrim(p_payload->>'remark'),'')
      where id=p_id and (app_private.is_platform_super() or tenant_id=v_target_tenant) returning id into v_id;
    end if;
  elsif p_kind='assignment' then
    if exists(select 1 from public.hr_attendance_period p where p.tenant_id=v_target_tenant and p.status='closed'
      and (p_payload->>'work_date')::date >= p.period_month
      and (p_payload->>'work_date')::date < p.period_month+interval '1 month') then raise exception '所属考勤期间已封账'; end if;
    if p_id is null then
      insert into public.hr_shift_assignment(tenant_id,employee_id,shift_id,work_date,assignment_status,remark)
      values(v_target_tenant,(p_payload->>'employee_id')::uuid,(p_payload->>'shift_id')::uuid,
        (p_payload->>'work_date')::date,coalesce(p_payload->>'assignment_status','scheduled'),
        nullif(btrim(p_payload->>'remark'),'')) returning id into v_id;
    else
      update public.hr_shift_assignment set employee_id=(p_payload->>'employee_id')::uuid,
        shift_id=(p_payload->>'shift_id')::uuid,work_date=(p_payload->>'work_date')::date,
        assignment_status=coalesce(p_payload->>'assignment_status',assignment_status),remark=nullif(btrim(p_payload->>'remark'),'')
      where id=p_id and (app_private.is_platform_super() or tenant_id=v_target_tenant) returning id into v_id;
    end if;
  elsif p_kind='record' then
    if p_id is not null then select * into v_record from public.hr_attendance_record where id=p_id for update; end if;
    if p_id is not null and (not found or (not app_private.is_platform_super() and v_record.tenant_id<>v_target_tenant)) then
      raise exception '考勤记录不存在或无权操作';
    end if;
    if p_id is not null and v_record.locked_at is not null then raise exception '考勤记录已封账'; end if;
    v_shift_id:=nullif(p_payload->>'shift_id','')::uuid;
    if p_id is null then
      insert into public.hr_attendance_record(tenant_id,employee_id,shift_id,work_date,clock_in_at,clock_out_at,
        attendance_status,source,remark,source_reference)
      values(v_target_tenant,(p_payload->>'employee_id')::uuid,v_shift_id,(p_payload->>'work_date')::date,
        nullif(p_payload->>'clock_in_at','')::timestamptz,nullif(p_payload->>'clock_out_at','')::timestamptz,
        coalesce(p_payload->>'attendance_status','normal'),coalesce(p_payload->>'source','manual'),
        nullif(btrim(p_payload->>'remark'),''),nullif(btrim(p_payload->>'source_reference'),'')) returning id into v_id;
    else
      update public.hr_attendance_record set employee_id=(p_payload->>'employee_id')::uuid,shift_id=v_shift_id,
        work_date=(p_payload->>'work_date')::date,clock_in_at=nullif(p_payload->>'clock_in_at','')::timestamptz,
        clock_out_at=nullif(p_payload->>'clock_out_at','')::timestamptz,
        attendance_status=coalesce(p_payload->>'attendance_status',attendance_status),
        source=coalesce(p_payload->>'source',source),remark=nullif(btrim(p_payload->>'remark'),''),
        source_reference=nullif(btrim(p_payload->>'source_reference'),'')
      where id=p_id returning id into v_id;
    end if;
    perform app_private.hr_valuate_attendance_record(v_id);
  elsif p_kind='correction' then
    select * into v_record from public.hr_attendance_record
    where id=(p_payload->>'attendance_record_id')::uuid
      and (app_private.is_platform_super() or tenant_id=v_target_tenant) for update;
    if not found then raise exception '待修正考勤记录不存在'; end if;
    if v_record.locked_at is not null then raise exception '考勤记录已封账，不能发起修正'; end if;
    if nullif(btrim(p_payload->>'reason'),'') is null then raise exception '修正原因不能为空'; end if;
    if p_id is null then
      v_code:='HRTC'||to_char(clock_timestamp(),'YYYYMMDDHH24MISS')||upper(substr(replace(gen_random_uuid()::text,'-',''),1,6));
      insert into public.hr_attendance_correction(tenant_id,correction_no,attendance_record_id,employee_id,
        requested_clock_in_at,requested_clock_out_at,reason,proof_urls,status,original_snapshot)
      values(v_record.tenant_id,v_code,v_record.id,v_record.employee_id,
        nullif(p_payload->>'requested_clock_in_at','')::timestamptz,
        nullif(p_payload->>'requested_clock_out_at','')::timestamptz,btrim(p_payload->>'reason'),
        coalesce(p_payload->'proof_urls','[]'::jsonb),'draft',jsonb_build_object(
          'clock_in_at',v_record.clock_in_at,'clock_out_at',v_record.clock_out_at,
          'work_minutes',v_record.work_minutes,'attendance_status',v_record.attendance_status,
          'exception_status',v_record.exception_status)) returning id into v_id;
    else
      update public.hr_attendance_correction set requested_clock_in_at=nullif(p_payload->>'requested_clock_in_at','')::timestamptz,
        requested_clock_out_at=nullif(p_payload->>'requested_clock_out_at','')::timestamptz,
        reason=btrim(p_payload->>'reason'),proof_urls=coalesce(p_payload->'proof_urls','[]'::jsonb),
        status=case when status='rejected' then 'draft' else status end,
        reviewed_at=null,reviewed_by=null,review_comment=null
      where id=p_id and status in ('draft','rejected')
        and (app_private.is_platform_super() or tenant_id=v_target_tenant) returning id into v_id;
    end if;
  else
    if p_id is null then
      insert into public.hr_attendance_period(tenant_id,period_month,status)
      values(v_target_tenant,date_trunc('month',(p_payload->>'period_month')::date)::date,'open') returning id into v_id;
    else
      update public.hr_attendance_period set close_note=nullif(btrim(p_payload->>'close_note'),'')
      where id=p_id and status='open' and (app_private.is_platform_super() or tenant_id=v_target_tenant)
      returning id into v_id;
    end if;
  end if;
  if v_id is null then raise exception '记录不存在、状态不允许编辑或租户不匹配'; end if;
  return v_id;
end
$$;


ALTER FUNCTION "public"."hr_save_attendance_record_secure"("p_kind" "text", "p_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: hr_save_benefit_record_secure("text", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_save_benefit_record_secure"("p_kind" "text", "p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_id uuid := nullif(p_payload ->> 'id', '')::uuid;
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_existing_status text;
  v_plan public.hr_benefit_plan;
  v_option public.hr_benefit_option;
  v_event public.hr_benefit_life_event;
  v_enrollment public.hr_employee_benefit_enrollment;
  v_plan_id uuid;
  v_option_id uuid;
  v_life_event_id uuid;
  v_employee_id uuid;
begin
  if auth.uid() is null then raise exception '请先登录' using errcode = '42501'; end if;
  if app_private.is_platform_super() and nullif(p_payload ->> 'tenant_id', '') is not null then
    v_tenant_id := (p_payload ->> 'tenant_id')::uuid;
  end if;

  if p_kind = 'plan' then
    if not app_private.can_execute_business_action(
      'HrBenefits', 'Hr:Benefits:Plan:Manage', v_id, false
    ) then raise exception '当前账号没有管理福利计划的权限' using errcode = '42501'; end if;
    if v_id is null then
      insert into public.hr_benefit_plan(
        tenant_id, plan_code, plan_name, plan_type, provider_name,
        enrollment_method, coverage_scope, currency_code,
        effective_from, effective_to, status, description
      ) values (
        v_tenant_id, btrim(p_payload ->> 'plan_code'), btrim(p_payload ->> 'plan_name'),
        p_payload ->> 'plan_type', nullif(btrim(p_payload ->> 'provider_name'), ''),
        coalesce(nullif(p_payload ->> 'enrollment_method', ''), 'election'),
        coalesce(nullif(p_payload ->> 'coverage_scope', ''), 'employee'),
        coalesce(nullif(p_payload ->> 'currency_code', ''), 'CNY'),
        (p_payload ->> 'effective_from')::date,
        nullif(p_payload ->> 'effective_to', '')::date,
        coalesce(nullif(p_payload ->> 'status', ''), 'draft'),
        nullif(btrim(p_payload ->> 'description'), '')
      ) returning * into v_plan;
      v_id := v_plan.id;
      perform app_private.hr_add_benefit_event(v_tenant_id, 'plan', v_id,
        'created', null, v_plan.status, '创建福利计划');
    else
      select status into v_existing_status from public.hr_benefit_plan
        where id = v_id and tenant_id = v_tenant_id for update;
      if v_existing_status is null then raise exception '福利计划不存在或无权编辑'; end if;
      if v_existing_status not in ('draft', 'active') then
        raise exception '只有草稿或生效中的福利计划可以编辑';
      end if;
      update public.hr_benefit_plan set
        plan_code = btrim(p_payload ->> 'plan_code'),
        plan_name = btrim(p_payload ->> 'plan_name'),
        plan_type = p_payload ->> 'plan_type',
        provider_name = nullif(btrim(p_payload ->> 'provider_name'), ''),
        enrollment_method = p_payload ->> 'enrollment_method',
        coverage_scope = p_payload ->> 'coverage_scope',
        currency_code = p_payload ->> 'currency_code',
        effective_from = (p_payload ->> 'effective_from')::date,
        effective_to = nullif(p_payload ->> 'effective_to', '')::date,
        description = nullif(btrim(p_payload ->> 'description'), '')
      where id = v_id and tenant_id = v_tenant_id returning * into v_plan;
      perform app_private.hr_add_benefit_event(v_tenant_id, 'plan', v_id,
        'updated', v_existing_status, v_existing_status, '更新福利计划资料');
    end if;
  elsif p_kind = 'option' then
    if not app_private.can_execute_business_action(
      'HrBenefits', 'Hr:Benefits:Plan:Manage', v_id, false
    ) then raise exception '当前账号没有管理福利方案的权限' using errcode = '42501'; end if;
    if not app_private.is_platform_super()
      and not app_private.has_permission('Hr:Benefits:Amount:Edit') then
      raise exception '当前账号没有维护福利缴费金额的权限' using errcode = '42501';
    end if;
    v_plan_id := (p_payload ->> 'plan_id')::uuid;
    if not exists (select 1 from public.hr_benefit_plan
      where id = v_plan_id and tenant_id = v_tenant_id and status in ('draft', 'active')) then
      raise exception '福利计划不存在、不可编辑或不属于当前租户';
    end if;
    if v_id is null then
      insert into public.hr_benefit_option(
        tenant_id, plan_id, option_code, option_name, coverage_level,
        contribution_type, employee_contribution, employer_contribution,
        employee_rate, employer_rate, pay_component_id, enabled, sort, description
      ) values (
        v_tenant_id, v_plan_id, btrim(p_payload ->> 'option_code'),
        btrim(p_payload ->> 'option_name'), p_payload ->> 'coverage_level',
        p_payload ->> 'contribution_type',
        coalesce(nullif(p_payload ->> 'employee_contribution', '')::numeric, 0),
        coalesce(nullif(p_payload ->> 'employer_contribution', '')::numeric, 0),
        nullif(p_payload ->> 'employee_rate', '')::numeric,
        nullif(p_payload ->> 'employer_rate', '')::numeric,
        nullif(p_payload ->> 'pay_component_id', '')::uuid,
        coalesce((p_payload ->> 'enabled')::boolean, true),
        coalesce((p_payload ->> 'sort')::integer, 0),
        nullif(btrim(p_payload ->> 'description'), '')
      ) returning * into v_option;
      v_id := v_option.id;
      perform app_private.hr_add_benefit_event(v_tenant_id, 'plan', v_plan_id,
        'option_created', null, null, '新增福利覆盖方案',
        jsonb_build_object('option_id', v_id));
    else
      update public.hr_benefit_option set
        option_code = btrim(p_payload ->> 'option_code'),
        option_name = btrim(p_payload ->> 'option_name'),
        coverage_level = p_payload ->> 'coverage_level',
        contribution_type = p_payload ->> 'contribution_type',
        employee_contribution = coalesce(nullif(p_payload ->> 'employee_contribution', '')::numeric, 0),
        employer_contribution = coalesce(nullif(p_payload ->> 'employer_contribution', '')::numeric, 0),
        employee_rate = nullif(p_payload ->> 'employee_rate', '')::numeric,
        employer_rate = nullif(p_payload ->> 'employer_rate', '')::numeric,
        pay_component_id = nullif(p_payload ->> 'pay_component_id', '')::uuid,
        enabled = coalesce((p_payload ->> 'enabled')::boolean, true),
        sort = coalesce((p_payload ->> 'sort')::integer, 0),
        description = nullif(btrim(p_payload ->> 'description'), '')
      where id = v_id and tenant_id = v_tenant_id and plan_id = v_plan_id
      returning * into v_option;
      if v_option.id is null then raise exception '福利方案不存在或无权编辑'; end if;
      perform app_private.hr_add_benefit_event(v_tenant_id, 'plan', v_plan_id,
        'option_updated', null, null, '更新福利覆盖方案',
        jsonb_build_object('option_id', v_id));
    end if;
  elsif p_kind = 'event' then
    if not app_private.can_execute_business_action(
      'HrBenefits', 'Hr:Benefits:Event:Manage', v_id, false
    ) then raise exception '当前账号没有管理福利人生事件的权限' using errcode = '42501'; end if;
    if v_id is null then
      insert into public.hr_benefit_life_event(
        tenant_id, employee_id, event_type, event_date,
        enrollment_window_end, status, evidence_urls, remark
      ) values (
        v_tenant_id, (p_payload ->> 'employee_id')::uuid,
        p_payload ->> 'event_type', (p_payload ->> 'event_date')::date,
        (p_payload ->> 'enrollment_window_end')::date, 'open',
        coalesce(p_payload -> 'evidence_urls', '[]'::jsonb),
        nullif(btrim(p_payload ->> 'remark'), '')
      ) returning * into v_event;
      v_id := v_event.id;
      perform app_private.hr_add_benefit_event(v_tenant_id, 'life_event', v_id,
        'created', null, 'open', '创建福利人生事件');
    else
      select status into v_existing_status from public.hr_benefit_life_event
        where id = v_id and tenant_id = v_tenant_id for update;
      if v_existing_status is null then raise exception '人生事件不存在或无权编辑'; end if;
      if v_existing_status <> 'open' then raise exception '只有开放中的人生事件可以编辑'; end if;
      update public.hr_benefit_life_event set
        event_type = p_payload ->> 'event_type',
        event_date = (p_payload ->> 'event_date')::date,
        enrollment_window_end = (p_payload ->> 'enrollment_window_end')::date,
        evidence_urls = coalesce(p_payload -> 'evidence_urls', '[]'::jsonb),
        remark = nullif(btrim(p_payload ->> 'remark'), '')
      where id = v_id and tenant_id = v_tenant_id returning * into v_event;
      perform app_private.hr_add_benefit_event(v_tenant_id, 'life_event', v_id,
        'updated', v_existing_status, v_existing_status, '更新福利人生事件');
    end if;
  elsif p_kind = 'enrollment' then
    if not app_private.can_execute_business_action(
      'HrBenefits', 'Hr:Benefits:Enrollment:Manage', v_id, false
    ) then raise exception '当前账号没有管理员工参保的权限' using errcode = '42501'; end if;
    if not app_private.is_platform_super()
      and not app_private.has_permission('Hr:Benefits:Amount:Edit') then
      raise exception '当前账号没有维护福利缴费金额的权限' using errcode = '42501';
    end if;
    v_plan_id := (p_payload ->> 'plan_id')::uuid;
    v_option_id := (p_payload ->> 'option_id')::uuid;
    v_life_event_id := nullif(p_payload ->> 'life_event_id', '')::uuid;
    v_employee_id := (p_payload ->> 'employee_id')::uuid;
    select option.* into v_option from public.hr_benefit_option option
      join public.hr_benefit_plan plan on plan.id = option.plan_id
        and plan.tenant_id = option.tenant_id
      where option.id = v_option_id and option.plan_id = v_plan_id
        and option.tenant_id = v_tenant_id and option.enabled
        and plan.status = 'active';
    if v_option.id is null then raise exception '福利计划或覆盖方案不可参保'; end if;
    if not exists (select 1 from public.hr_benefit_plan plan
      where plan.id = v_plan_id and plan.tenant_id = v_tenant_id
        and (p_payload ->> 'coverage_from')::date >= plan.effective_from
        and (plan.effective_to is null or (p_payload ->> 'coverage_from')::date <= plan.effective_to)) then
      raise exception '参保生效日期不在福利计划有效期内';
    end if;
    if v_life_event_id is not null and not exists (
      select 1 from public.hr_benefit_life_event event
      where event.id = v_life_event_id and event.tenant_id = v_tenant_id
        and event.employee_id = v_employee_id and event.status = 'open'
        and event.enrollment_window_end >= current_date
    ) then raise exception '人生事件不属于该员工、参保窗口已关闭或事件不可用'; end if;
    if v_id is null then
      insert into public.hr_employee_benefit_enrollment(
        tenant_id, employee_id, plan_id, option_id, life_event_id,
        enrollment_no, coverage_from, coverage_to, status, waiver_reason,
        employee_contribution, employer_contribution, currency_code,
        payroll_sync_status, remark
      ) values (
        v_tenant_id, v_employee_id, v_plan_id, v_option_id, v_life_event_id,
        coalesce(nullif(btrim(p_payload ->> 'enrollment_no'), ''),
          'BEN-' || to_char(clock_timestamp(), 'YYYYMMDDHH24MISSMS')),
        (p_payload ->> 'coverage_from')::date,
        nullif(p_payload ->> 'coverage_to', '')::date, 'draft',
        nullif(btrim(p_payload ->> 'waiver_reason'), ''),
        coalesce(nullif(p_payload ->> 'employee_contribution', '')::numeric,
          v_option.employee_contribution),
        coalesce(nullif(p_payload ->> 'employer_contribution', '')::numeric,
          v_option.employer_contribution),
        coalesce(nullif(p_payload ->> 'currency_code', ''),
          (select currency_code from public.hr_benefit_plan where id = v_plan_id)),
        'not_ready', nullif(btrim(p_payload ->> 'remark'), '')
      ) returning * into v_enrollment;
      v_id := v_enrollment.id;
      perform app_private.hr_add_benefit_event(v_tenant_id, 'enrollment', v_id,
        'created', null, 'draft', '创建员工参保草稿');
    else
      select status into v_existing_status from public.hr_employee_benefit_enrollment
        where id = v_id and tenant_id = v_tenant_id for update;
      if v_existing_status <> 'draft' then raise exception '只有草稿参保记录可以编辑'; end if;
      update public.hr_employee_benefit_enrollment set
        employee_id = v_employee_id,
        plan_id = v_plan_id, option_id = v_option_id,
        life_event_id = v_life_event_id,
        coverage_from = (p_payload ->> 'coverage_from')::date,
        coverage_to = nullif(p_payload ->> 'coverage_to', '')::date,
        waiver_reason = nullif(btrim(p_payload ->> 'waiver_reason'), ''),
        employee_contribution = coalesce(nullif(p_payload ->> 'employee_contribution', '')::numeric,
          v_option.employee_contribution),
        employer_contribution = coalesce(nullif(p_payload ->> 'employer_contribution', '')::numeric,
          v_option.employer_contribution),
        currency_code = coalesce(nullif(p_payload ->> 'currency_code', ''), currency_code),
        remark = nullif(btrim(p_payload ->> 'remark'), '')
      where id = v_id and tenant_id = v_tenant_id returning * into v_enrollment;
      if v_enrollment.id is null then raise exception '参保记录不存在或无权编辑'; end if;
      perform app_private.hr_add_benefit_event(v_tenant_id, 'enrollment', v_id,
        'updated', 'draft', 'draft', '更新员工参保草稿');
    end if;
  else
    raise exception '不支持的福利记录类型';
  end if;
  return v_id;
end
$$;


ALTER FUNCTION "public"."hr_save_benefit_record_secure"("p_kind" "text", "p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: hr_save_compensation_master_secure("text", "uuid", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_save_compensation_master_secure"("p_kind" "text", "p_id" "uuid", "p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_id uuid := coalesce(p_id, gen_random_uuid());
  v_tenant_id uuid;
  v_permission text := case when p_id is null
    then 'Hr:Compensation:Policy:Add' else 'Hr:Compensation:Policy:Edit' end;
  v_grade_id uuid;
begin
  if p_kind not in ('component', 'plan', 'band') then
    raise exception '不支持的薪酬主数据类型';
  end if;
  if not app_private.can_execute_business_action('HrCompensation', v_permission, null, false) then
    raise exception 'Missing compensation policy write permission' using errcode = '42501';
  end if;
  v_tenant_id := case when app_private.is_platform_super()
    then coalesce(
      nullif(p_payload->>'tenant_id', '')::uuid,
      case p_kind
        when 'component' then (select tenant_id from public.hr_pay_component where id = p_id)
        when 'plan' then (select tenant_id from public.hr_compensation_plan where id = p_id)
        else (select tenant_id from public.hr_salary_band where id = p_id)
      end
    )
    else app_private.current_user_tenant_id()
  end;
  if v_tenant_id is null then raise exception '请选择所属租户'; end if;

  if p_kind = 'component' then
    insert into public.hr_pay_component(
      id, tenant_id, component_code, component_name, category, amount_type,
      taxable, enabled, sort, description
    ) values (
      v_id, v_tenant_id,
      upper(btrim(p_payload->>'component_code')),
      btrim(p_payload->>'component_name'),
      p_payload->>'category', coalesce(nullif(p_payload->>'amount_type', ''), 'fixed'),
      coalesce((p_payload->>'taxable')::boolean, true),
      coalesce((p_payload->>'enabled')::boolean, true),
      coalesce((p_payload->>'sort')::integer, 0),
      nullif(btrim(p_payload->>'description'), '')
    )
    on conflict (id) do update set
      component_code = excluded.component_code,
      component_name = excluded.component_name,
      category = excluded.category,
      amount_type = excluded.amount_type,
      taxable = excluded.taxable,
      enabled = excluded.enabled,
      sort = excluded.sort,
      description = excluded.description
    where hr_pay_component.tenant_id = v_tenant_id;
    if not found then raise exception '薪酬项目不存在或无权编辑'; end if;
    return v_id;
  end if;

  if p_kind = 'plan' then
    if p_id is not null and exists (
      select 1 from public.hr_employee_compensation
      where plan_id = p_id and status = 'approved'
    ) then
      raise exception '该薪酬方案已有已批准员工薪酬，须复制为新方案后调整';
    end if;
    insert into public.hr_compensation_plan(
      id, tenant_id, plan_code, plan_name, currency_code, pay_frequency,
      enabled, sort, description
    ) values (
      v_id, v_tenant_id,
      upper(btrim(p_payload->>'plan_code')),
      btrim(p_payload->>'plan_name'),
      upper(coalesce(nullif(btrim(p_payload->>'currency_code'), ''), 'CNY')),
      coalesce(nullif(p_payload->>'pay_frequency', ''), 'monthly'),
      coalesce((p_payload->>'enabled')::boolean, true),
      coalesce((p_payload->>'sort')::integer, 0),
      nullif(btrim(p_payload->>'description'), '')
    )
    on conflict (id) do update set
      plan_code = excluded.plan_code,
      plan_name = excluded.plan_name,
      currency_code = excluded.currency_code,
      pay_frequency = excluded.pay_frequency,
      enabled = excluded.enabled,
      sort = excluded.sort,
      description = excluded.description
    where hr_compensation_plan.tenant_id = v_tenant_id;
    if not found then raise exception '薪酬方案不存在或无权编辑'; end if;

    delete from public.hr_compensation_plan_item where plan_id = v_id;
    insert into public.hr_compensation_plan_item(
      tenant_id, plan_id, component_id, default_amount, default_rate, required, sort
    )
    select
      v_tenant_id, v_id, component_row.id,
      nullif(item->>'default_amount', '')::numeric,
      nullif(item->>'default_rate', '')::numeric,
      coalesce((item->>'required')::boolean, false),
      coalesce((item->>'sort')::integer, component_row.sort)
    from jsonb_array_elements(coalesce(p_payload->'items', '[]'::jsonb)) item
    join public.hr_pay_component component_row
      on component_row.id = nullif(item->>'component_id', '')::uuid
     and component_row.tenant_id = v_tenant_id
     and component_row.enabled;
    if jsonb_array_length(coalesce(p_payload->'items', '[]'::jsonb)) <> (
      select count(*) from public.hr_compensation_plan_item where plan_id = v_id
    ) then
      raise exception '薪酬方案包含无效或重复的薪酬项目';
    end if;
    return v_id;
  end if;

  if not app_private.can_execute_business_action(
    'HrCompensation', 'Hr:Compensation:Amount:Edit', null, false
  ) then
    raise exception 'Missing compensation amount edit permission' using errcode = '42501';
  end if;
  v_grade_id := nullif(p_payload->>'grade_id', '')::uuid;
  if not exists (
    select 1 from public.mdm_grade
    where id = v_grade_id and tenant_id = v_tenant_id and enabled
  ) then raise exception '所选职级不可用'; end if;
  if p_id is not null and not exists (
    select 1 from public.hr_salary_band
    where id = p_id and tenant_id = v_tenant_id and status = 'draft'
  ) then raise exception '只有草稿薪级范围可以编辑'; end if;

  insert into public.hr_salary_band(
    id, tenant_id, grade_id, currency_code,
    minimum_amount, midpoint_amount, maximum_amount,
    effective_from, effective_to, status, description
  ) values (
    v_id, v_tenant_id, v_grade_id,
    upper(coalesce(nullif(btrim(p_payload->>'currency_code'), ''), 'CNY')),
    (p_payload->>'minimum_amount')::numeric,
    (p_payload->>'midpoint_amount')::numeric,
    (p_payload->>'maximum_amount')::numeric,
    (p_payload->>'effective_from')::date,
    nullif(p_payload->>'effective_to', '')::date,
    'draft', nullif(btrim(p_payload->>'description'), '')
  )
  on conflict (id) do update set
    grade_id = excluded.grade_id,
    currency_code = excluded.currency_code,
    minimum_amount = excluded.minimum_amount,
    midpoint_amount = excluded.midpoint_amount,
    maximum_amount = excluded.maximum_amount,
    effective_from = excluded.effective_from,
    effective_to = excluded.effective_to,
    description = excluded.description
  where hr_salary_band.tenant_id = v_tenant_id
    and hr_salary_band.status = 'draft';
  if not found then raise exception '薪级范围不存在或无权编辑'; end if;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."hr_save_compensation_master_secure"("p_kind" "text", "p_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: hr_save_compensation_review_record_secure("text", "uuid", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_save_compensation_review_record_secure"("p_kind" "text", "p_id" "uuid" DEFAULT NULL::"uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    SET "TimeZone" TO 'Asia/Shanghai'
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_cycle public.hr_compensation_review_cycle%rowtype;
  v_budget public.hr_compensation_review_budget%rowtype;
  v_item public.hr_compensation_review_item%rowtype;
  v_proposed numeric(18, 2);
  v_percent numeric(10, 4);
  v_reason text;
  v_note text;
  v_exclude boolean := coalesce((p_payload->>'exclude')::boolean, false);
  v_actor text := coalesce(app_private.current_user_email(), auth.uid()::text, 'system');
begin
  if p_kind not in ('cycle', 'budget', 'item') then raise exception '不支持的调薪复核记录类型'; end if;
  if auth.uid() is null then raise exception '请先登录' using errcode = '42501'; end if;

  if p_kind = 'cycle' then
    if not app_private.can_execute_business_action(
      'HrCompensationReview', 'Hr:CompensationReview:Cycle:Manage', null, false
    ) then raise exception '当前账号没有管理调薪周期的权限' using errcode = '42501'; end if;
    if not app_private.can_execute_business_action(
      'HrCompensationReview', 'Hr:CompensationReview:Amount:Edit', null, false
    ) then raise exception '当前账号没有编辑调薪金额的权限' using errcode = '42501'; end if;

    if p_id is not null then
      select * into v_cycle from public.hr_compensation_review_cycle
      where id = p_id and (app_private.is_platform_super() or tenant_id = v_tenant_id) for update;
      if not found then raise exception '调薪周期不存在'; end if;
      if v_cycle.status <> 'draft' then raise exception '只有草稿周期可以修改'; end if;
      v_tenant_id := v_cycle.tenant_id;
    elsif app_private.is_platform_super() and nullif(p_payload->>'tenant_id', '') is not null then
      v_tenant_id := (p_payload->>'tenant_id')::uuid;
    end if;

    if nullif(btrim(p_payload->>'cycle_code'), '') is null
      or nullif(btrim(p_payload->>'cycle_name'), '') is null then
      raise exception '周期编码和名称不能为空';
    end if;

    if p_id is null then
      insert into public.hr_compensation_review_cycle(
        tenant_id, cycle_code, cycle_name, review_year, effective_date,
        recommendation_due_date, calibration_due_date, scope_organization_id,
        currency_code, default_budget_percent, guideline_min_percent,
        guideline_max_percent, status, description
      ) values (
        v_tenant_id,
        upper(btrim(p_payload->>'cycle_code')),
        btrim(p_payload->>'cycle_name'),
        (p_payload->>'review_year')::integer,
        (p_payload->>'effective_date')::date,
        (p_payload->>'recommendation_due_date')::date,
        (p_payload->>'calibration_due_date')::date,
        nullif(p_payload->>'scope_organization_id', '')::uuid,
        upper(coalesce(nullif(p_payload->>'currency_code', ''), 'CNY')),
        coalesce(nullif(p_payload->>'default_budget_percent', '')::numeric, 5),
        coalesce(nullif(p_payload->>'guideline_min_percent', '')::numeric, 0),
        coalesce(nullif(p_payload->>'guideline_max_percent', '')::numeric, 10),
        'draft',
        nullif(btrim(p_payload->>'description'), '')
      ) returning * into v_cycle;
    else
      update public.hr_compensation_review_cycle set
        cycle_code = upper(btrim(p_payload->>'cycle_code')),
        cycle_name = btrim(p_payload->>'cycle_name'),
        review_year = (p_payload->>'review_year')::integer,
        effective_date = (p_payload->>'effective_date')::date,
        recommendation_due_date = (p_payload->>'recommendation_due_date')::date,
        calibration_due_date = (p_payload->>'calibration_due_date')::date,
        scope_organization_id = nullif(p_payload->>'scope_organization_id', '')::uuid,
        currency_code = upper(coalesce(nullif(p_payload->>'currency_code', ''), 'CNY')),
        default_budget_percent = coalesce(nullif(p_payload->>'default_budget_percent', '')::numeric, 5),
        guideline_min_percent = coalesce(nullif(p_payload->>'guideline_min_percent', '')::numeric, 0),
        guideline_max_percent = coalesce(nullif(p_payload->>'guideline_max_percent', '')::numeric, 10),
        description = nullif(btrim(p_payload->>'description'), '')
      where id = p_id returning * into v_cycle;
    end if;
    return v_cycle.id;
  end if;

  if p_kind = 'budget' then
    if not app_private.can_execute_business_action(
      'HrCompensationReview', 'Hr:CompensationReview:Budget:Manage', null, false
    ) or not app_private.can_execute_business_action(
      'HrCompensationReview', 'Hr:CompensationReview:Amount:Edit', null, false
    ) then raise exception '当前账号没有维护调薪预算的权限' using errcode = '42501'; end if;

    select * into v_cycle from public.hr_compensation_review_cycle
    where id = (p_payload->>'cycle_id')::uuid
      and (app_private.is_platform_super() or tenant_id = v_tenant_id) for update;
    if not found then raise exception '调薪周期不存在'; end if;
    if v_cycle.status not in ('draft', 'open') then raise exception '当前阶段不能调整预算'; end if;
    v_tenant_id := v_cycle.tenant_id;

    if p_id is null then
      insert into public.hr_compensation_review_budget(
        tenant_id, cycle_id, organization_id, budget_amount, source, note
      ) values (
        v_tenant_id, v_cycle.id, nullif(p_payload->>'organization_id', '')::uuid,
        (p_payload->>'budget_amount')::numeric, 'manual', nullif(btrim(p_payload->>'note'), '')
      ) returning * into v_budget;
    else
      select * into v_budget from public.hr_compensation_review_budget
      where id = p_id and cycle_id = v_cycle.id and tenant_id = v_tenant_id for update;
      if not found then raise exception '组织预算不存在'; end if;
      update public.hr_compensation_review_budget set
        budget_amount = (p_payload->>'budget_amount')::numeric,
        source = 'manual',
        note = nullif(btrim(p_payload->>'note'), '')
      where id = p_id returning * into v_budget;
    end if;
    return v_budget.id;
  end if;

  if not app_private.can_execute_business_action(
    'HrCompensationReview', 'Hr:CompensationReview:Amount:Edit', null, false
  ) then raise exception '当前账号没有编辑调薪金额的权限' using errcode = '42501'; end if;

  select item.* into v_item
  from public.hr_compensation_review_item item
  where item.id = p_id and (app_private.is_platform_super() or item.tenant_id = v_tenant_id)
  for update;
  if not found then raise exception '员工调薪复核项不存在'; end if;
  select * into v_cycle from public.hr_compensation_review_cycle
  where id = v_item.cycle_id and tenant_id = v_item.tenant_id for update;

  if v_cycle.status = 'open' then
    if not app_private.can_execute_business_action(
      'HrCompensationReview', 'Hr:CompensationReview:Recommend', null, false
    ) then raise exception '当前账号没有提交调薪建议的权限' using errcode = '42501'; end if;
  elsif v_cycle.status = 'calibrating' then
    if not app_private.can_execute_business_action(
      'HrCompensationReview', 'Hr:CompensationReview:Calibrate', null, false
    ) then raise exception '当前账号没有执行调薪校准的权限' using errcode = '42501'; end if;
  else
    raise exception '当前阶段不能修改员工调薪建议';
  end if;

  if v_exclude then
    v_reason := nullif(btrim(p_payload->>'exclusion_reason'), '');
    if v_reason is null then raise exception '排除员工必须填写原因'; end if;
    update public.hr_compensation_review_item set
      status = 'excluded', exclusion_reason = v_reason,
      recommendation_reason = null, calibration_note = null
    where id = v_item.id;
    return v_item.id;
  end if;

  v_proposed := nullif(p_payload->>'proposed_base_amount', '')::numeric;
  if v_proposed is null or v_proposed < 0 then raise exception '建议基本工资必须为非负金额'; end if;
  v_reason := nullif(btrim(p_payload->>'recommendation_reason'), '');
  v_note := nullif(btrim(p_payload->>'calibration_note'), '');
  v_percent := case when v_item.current_base_amount = 0 then 0
    else round((v_proposed - v_item.current_base_amount) * 100 / v_item.current_base_amount, 4) end;

  if v_proposed <> v_item.current_base_amount and v_reason is null then
    raise exception '发生调薪时必须填写建议依据';
  end if;
  if (v_percent < v_cycle.guideline_min_percent or v_percent > v_cycle.guideline_max_percent)
    and coalesce(v_note, v_reason) is null then
    raise exception '超出调薪指引时必须填写例外依据';
  end if;

  if v_cycle.status = 'open' then
    update public.hr_compensation_review_item set
      proposed_base_amount = v_proposed,
      status = 'recommended',
      recommendation_reason = v_reason,
      recommended_by = v_actor,
      recommended_at = now(),
      exclusion_reason = null
    where id = v_item.id;
  else
    update public.hr_compensation_review_item set
      proposed_base_amount = v_proposed,
      status = 'calibrated',
      recommendation_reason = coalesce(v_reason, recommendation_reason),
      calibration_note = v_note,
      calibrated_by = v_actor,
      calibrated_at = now(),
      exclusion_reason = null
    where id = v_item.id;
  end if;
  return v_item.id;
end;
$$;


ALTER FUNCTION "public"."hr_save_compensation_review_record_secure"("p_kind" "text", "p_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: hr_save_compliance_record_secure("text", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_save_compliance_record_secure"("p_kind" "text", "p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_id uuid := nullif(p_payload->>'id', '')::uuid;
  v_tenant_id uuid := coalesce(nullif(p_payload->>'tenant_id', '')::uuid,
    app_private.current_user_tenant_id());
  v_employee_id uuid := nullif(p_payload->>'employee_id', '')::uuid;
  v_existing_contract public.hr_employee_contract;
  v_existing_qualification public.hr_employee_qualification;
  v_core_changed boolean := false;
  v_status text;
begin
  if p_kind not in ('contract', 'qualification') then
    raise exception '不支持的用工合规记录类型';
  end if;
  if not app_private.is_platform_super() then
    v_tenant_id := app_private.current_user_tenant_id();
  end if;
  if v_employee_id is null or not exists (
    select 1 from public.mdm_employee employee
    where employee.id = v_employee_id and employee.tenant_id = v_tenant_id
  ) then
    raise exception '请选择当前租户内的有效员工';
  end if;

  if v_id is null then
    if not app_private.can_execute_business_action(
      'HrCompliance', 'Hr:Compliance:Add', null, false
    ) then
      raise exception '当前账号没有新增合同或资质的权限' using errcode = '42501';
    end if;
  elsif not app_private.can_execute_business_action(
    'HrCompliance', 'Hr:Compliance:Edit', v_id, false
  ) then
    raise exception '当前账号没有编辑合同或资质的权限' using errcode = '42501';
  end if;

  if p_kind = 'contract' then
    if nullif(btrim(p_payload->>'contract_no'), '') is null then raise exception '请输入合同编号'; end if;
    if nullif(p_payload->>'start_date', '') is null then raise exception '请选择合同开始日期'; end if;
    if nullif(btrim(p_payload->>'contract_type'), '') is null then raise exception '请选择合同类型'; end if;
    if nullif(p_payload->>'end_date', '') is not null
      and (p_payload->>'end_date')::date < (p_payload->>'start_date')::date then
      raise exception '合同结束日期不能早于开始日期';
    end if;

    if v_id is null then
      v_status := coalesce(nullif(p_payload->>'contract_status', ''), 'draft');
      if v_status not in ('draft', 'active') then v_status := 'draft'; end if;
      insert into public.hr_employee_contract(
        tenant_id, employee_id, contract_no, contract_type, contract_status,
        sign_date, start_date, end_date, probation_end_date, work_location,
        monthly_salary, renewal_reminder_days, renewal_owner_id,
        attachment_url, remark
      ) values (
        v_tenant_id, v_employee_id, btrim(p_payload->>'contract_no'),
        p_payload->>'contract_type', v_status,
        nullif(p_payload->>'sign_date', '')::date,
        (p_payload->>'start_date')::date, nullif(p_payload->>'end_date', '')::date,
        nullif(p_payload->>'probation_end_date', '')::date,
        nullif(btrim(p_payload->>'work_location'), ''),
        nullif(p_payload->>'monthly_salary', '')::numeric,
        coalesce(nullif(p_payload->>'renewal_reminder_days', '')::integer, 30),
        nullif(p_payload->>'renewal_owner_id', '')::uuid,
        nullif(btrim(p_payload->>'attachment_url'), ''),
        nullif(btrim(p_payload->>'remark'), '')
      ) returning id into v_id;
      perform app_private.hr_add_compliance_event(
        v_tenant_id, 'contract', v_id, 'created', null, v_status,
        '创建劳动合同记录', '{}'::jsonb
      );
    else
      select * into v_existing_contract from public.hr_employee_contract contract
      where contract.id = v_id and contract.tenant_id = v_tenant_id for update;
      if not found then raise exception '劳动合同不存在或无权编辑' using errcode = '42501'; end if;
      if v_existing_contract.contract_status in ('renewed', 'terminated', 'expired') then
        raise exception '已续签、已终止或已到期合同不能直接编辑';
      end if;
      v_status := case when v_existing_contract.contract_status = 'renewing' then 'renewing'
        when p_payload->>'contract_status' in ('draft', 'active')
          then p_payload->>'contract_status'
        else v_existing_contract.contract_status end;
      update public.hr_employee_contract set
        employee_id = v_employee_id,
        contract_no = btrim(p_payload->>'contract_no'),
        contract_type = p_payload->>'contract_type',
        contract_status = v_status,
        sign_date = nullif(p_payload->>'sign_date', '')::date,
        start_date = (p_payload->>'start_date')::date,
        end_date = nullif(p_payload->>'end_date', '')::date,
        probation_end_date = nullif(p_payload->>'probation_end_date', '')::date,
        work_location = nullif(btrim(p_payload->>'work_location'), ''),
        monthly_salary = nullif(p_payload->>'monthly_salary', '')::numeric,
        renewal_reminder_days = coalesce(
          nullif(p_payload->>'renewal_reminder_days', '')::integer, 30),
        renewal_owner_id = nullif(p_payload->>'renewal_owner_id', '')::uuid,
        attachment_url = nullif(btrim(p_payload->>'attachment_url'), ''),
        remark = nullif(btrim(p_payload->>'remark'), '')
      where id = v_id;
      perform app_private.hr_add_compliance_event(
        v_tenant_id, 'contract', v_id, 'updated',
        v_existing_contract.contract_status, v_status,
        '更新劳动合同资料', '{}'::jsonb
      );
    end if;
  else
    if nullif(btrim(p_payload->>'qualification_name'), '') is null then raise exception '请输入资质名称'; end if;
    if nullif(btrim(p_payload->>'qualification_type'), '') is null then raise exception '请选择资质类型'; end if;
    if nullif(p_payload->>'expiry_date', '') is not null
      and nullif(p_payload->>'issue_date', '') is not null
      and (p_payload->>'expiry_date')::date < (p_payload->>'issue_date')::date then
      raise exception '资质到期日期不能早于发证日期';
    end if;
    v_status := case
      when nullif(p_payload->>'expiry_date', '') is null then 'valid'
      when (p_payload->>'expiry_date')::date < current_date then 'expired'
      when (p_payload->>'expiry_date')::date <= current_date
        + coalesce(nullif(p_payload->>'reminder_days', '')::integer, 30) then 'expiring'
      else 'valid' end;

    if v_id is null then
      insert into public.hr_employee_qualification(
        tenant_id, employee_id, qualification_type, qualification_name,
        certificate_no, issuer, issue_date, expiry_date, status,
        attachment_url, reminder_days, responsible_employee_id,
        verification_status, next_review_date, remark
      ) values (
        v_tenant_id, v_employee_id, p_payload->>'qualification_type',
        btrim(p_payload->>'qualification_name'),
        nullif(btrim(p_payload->>'certificate_no'), ''),
        nullif(btrim(p_payload->>'issuer'), ''),
        nullif(p_payload->>'issue_date', '')::date,
        nullif(p_payload->>'expiry_date', '')::date, v_status,
        nullif(btrim(p_payload->>'attachment_url'), ''),
        coalesce(nullif(p_payload->>'reminder_days', '')::integer, 30),
        nullif(p_payload->>'responsible_employee_id', '')::uuid,
        'pending', nullif(p_payload->>'next_review_date', '')::date,
        nullif(btrim(p_payload->>'remark'), '')
      ) returning id into v_id;
      perform app_private.hr_add_compliance_event(
        v_tenant_id, 'qualification', v_id, 'created', null, v_status,
        '创建员工资质记录', '{}'::jsonb
      );
    else
      select * into v_existing_qualification from public.hr_employee_qualification qualification
      where qualification.id = v_id and qualification.tenant_id = v_tenant_id for update;
      if not found then raise exception '员工资质不存在或无权编辑' using errcode = '42501'; end if;
      if v_existing_qualification.status = 'revoked' then raise exception '已撤销资质不能直接编辑'; end if;
      v_core_changed := v_existing_qualification.qualification_type is distinct from p_payload->>'qualification_type'
        or v_existing_qualification.qualification_name is distinct from btrim(p_payload->>'qualification_name')
        or v_existing_qualification.certificate_no is distinct from nullif(btrim(p_payload->>'certificate_no'), '')
        or v_existing_qualification.issuer is distinct from nullif(btrim(p_payload->>'issuer'), '')
        or v_existing_qualification.issue_date is distinct from nullif(p_payload->>'issue_date', '')::date
        or v_existing_qualification.expiry_date is distinct from nullif(p_payload->>'expiry_date', '')::date;
      update public.hr_employee_qualification set
        employee_id = v_employee_id,
        qualification_type = p_payload->>'qualification_type',
        qualification_name = btrim(p_payload->>'qualification_name'),
        certificate_no = nullif(btrim(p_payload->>'certificate_no'), ''),
        issuer = nullif(btrim(p_payload->>'issuer'), ''),
        issue_date = nullif(p_payload->>'issue_date', '')::date,
        expiry_date = nullif(p_payload->>'expiry_date', '')::date,
        status = v_status,
        attachment_url = nullif(btrim(p_payload->>'attachment_url'), ''),
        reminder_days = coalesce(nullif(p_payload->>'reminder_days', '')::integer, 30),
        responsible_employee_id = nullif(p_payload->>'responsible_employee_id', '')::uuid,
        next_review_date = nullif(p_payload->>'next_review_date', '')::date,
        remark = nullif(btrim(p_payload->>'remark'), ''),
        verification_status = case when v_core_changed then 'pending'
          else verification_status end,
        verified_by_employee_id = case when v_core_changed then null
          else verified_by_employee_id end,
        verified_at = case when v_core_changed then null else verified_at end
      where id = v_id;
      perform app_private.hr_add_compliance_event(
        v_tenant_id, 'qualification', v_id, 'updated',
        v_existing_qualification.status, v_status,
        case when v_core_changed then '更新资质核心资料并重新进入核验' else '更新员工资质资料' end,
        jsonb_build_object('verification_reset', v_core_changed)
      );
    end if;
  end if;
  return v_id;
exception
  when unique_violation then
    raise exception '合同编号已存在，请检查后重试';
end
$$;


ALTER FUNCTION "public"."hr_save_compliance_record_secure"("p_kind" "text", "p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: hr_save_contingent_workforce_record_secure("text", "uuid", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_save_contingent_workforce_record_secure"("p_kind" "text", "p_id" "uuid", "p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    SET "TimeZone" TO 'Asia/Shanghai'
    AS $$
declare
  v_current_tenant uuid := app_private.current_user_tenant_id();
  v_tenant_id uuid := case
    when app_private.is_platform_super() and nullif(p_payload ->> 'tenant_id', '') is not null
      then (p_payload ->> 'tenant_id')::uuid
    else v_current_tenant
  end;
  v_action text;
  v_id uuid := coalesce(p_id, gen_random_uuid());
  v_worker public.hr_external_worker%rowtype;
  v_engagement public.hr_external_engagement%rowtype;
  v_position_organization uuid;
  v_billing_rate numeric(18, 2);
  v_expected_version integer;
begin
  if p_kind not in ('vendor', 'worker', 'engagement', 'control') then
    raise exception '不支持的外部用工记录类型';
  end if;
  v_action := case p_kind
    when 'vendor' then 'Hr:ContingentWorkforce:Vendor:Manage'
    when 'worker' then 'Hr:ContingentWorkforce:Worker:Manage'
    when 'engagement' then 'Hr:ContingentWorkforce:Engagement:Manage'
    else 'Hr:ContingentWorkforce:Control:Manage'
  end;
  if auth.uid() is null or not app_private.can_execute_business_action(
    'HrContingentWorkforce', v_action, null, false
  ) then
    raise exception '当前账号没有维护外部用工记录的权限' using errcode = '42501';
  end if;

  if p_kind = 'vendor' then
    if p_id is null then
      insert into public.mdm_external_vendor(
        id, tenant_id, vendor_code, vendor_name, registration_no,
        contact_name, contact_phone, contact_email, service_scope,
        contract_no, contract_start_date, contract_end_date,
        compliance_status, risk_level, status, note
      ) values (
        v_id, v_tenant_id, btrim(p_payload ->> 'vendor_code'), btrim(p_payload ->> 'vendor_name'),
        nullif(btrim(p_payload ->> 'registration_no'), ''),
        nullif(btrim(p_payload ->> 'contact_name'), ''),
        nullif(btrim(p_payload ->> 'contact_phone'), ''),
        nullif(btrim(p_payload ->> 'contact_email'), ''),
        nullif(btrim(p_payload ->> 'service_scope'), ''),
        nullif(btrim(p_payload ->> 'contract_no'), ''),
        nullif(p_payload ->> 'contract_start_date', '')::date,
        nullif(p_payload ->> 'contract_end_date', '')::date,
        coalesce(nullif(p_payload ->> 'compliance_status', ''), 'pending'),
        coalesce(nullif(p_payload ->> 'risk_level', ''), 'medium'),
        'draft', nullif(btrim(p_payload ->> 'note'), '')
      );
    else
      update public.mdm_external_vendor set
        vendor_code = btrim(p_payload ->> 'vendor_code'),
        vendor_name = btrim(p_payload ->> 'vendor_name'),
        registration_no = nullif(btrim(p_payload ->> 'registration_no'), ''),
        contact_name = nullif(btrim(p_payload ->> 'contact_name'), ''),
        contact_phone = nullif(btrim(p_payload ->> 'contact_phone'), ''),
        contact_email = nullif(btrim(p_payload ->> 'contact_email'), ''),
        service_scope = nullif(btrim(p_payload ->> 'service_scope'), ''),
        contract_no = nullif(btrim(p_payload ->> 'contract_no'), ''),
        contract_start_date = nullif(p_payload ->> 'contract_start_date', '')::date,
        contract_end_date = nullif(p_payload ->> 'contract_end_date', '')::date,
        compliance_status = coalesce(nullif(p_payload ->> 'compliance_status', ''), compliance_status),
        risk_level = coalesce(nullif(p_payload ->> 'risk_level', ''), risk_level),
        note = nullif(btrim(p_payload ->> 'note'), '')
      where id = p_id and tenant_id = v_tenant_id;
      if not found then raise exception '供应商不存在或不属于当前租户'; end if;
    end if;
  elsif p_kind = 'worker' then
    if coalesce(nullif(p_payload ->> 'worker_type', ''), '') in ('outsourced', 'dispatch')
       and nullif(p_payload ->> 'vendor_id', '') is null then
      raise exception '外包或劳务派遣人员必须关联供应商';
    end if;
    if p_id is null then
      insert into public.hr_external_worker(
        id, tenant_id, worker_no, worker_name, worker_type, vendor_id,
        vendor_worker_no, phone, email, identity_check_status, status, note
      ) values (
        v_id, v_tenant_id, btrim(p_payload ->> 'worker_no'), btrim(p_payload ->> 'worker_name'),
        p_payload ->> 'worker_type', nullif(p_payload ->> 'vendor_id', '')::uuid,
        nullif(btrim(p_payload ->> 'vendor_worker_no'), ''),
        nullif(btrim(p_payload ->> 'phone'), ''), nullif(btrim(p_payload ->> 'email'), ''),
        coalesce(nullif(p_payload ->> 'identity_check_status', ''), 'pending'),
        'candidate', nullif(btrim(p_payload ->> 'note'), '')
      );
    else
      update public.hr_external_worker set
        worker_no = btrim(p_payload ->> 'worker_no'),
        worker_name = btrim(p_payload ->> 'worker_name'),
        worker_type = p_payload ->> 'worker_type',
        vendor_id = nullif(p_payload ->> 'vendor_id', '')::uuid,
        vendor_worker_no = nullif(btrim(p_payload ->> 'vendor_worker_no'), ''),
        phone = nullif(btrim(p_payload ->> 'phone'), ''),
        email = nullif(btrim(p_payload ->> 'email'), ''),
        identity_check_status = coalesce(nullif(p_payload ->> 'identity_check_status', ''), identity_check_status),
        note = nullif(btrim(p_payload ->> 'note'), '')
      where id = p_id and tenant_id = v_tenant_id and status <> 'blocked';
      if not found then raise exception '外部人员不存在、已锁定或不属于当前租户'; end if;
    end if;
  elsif p_kind = 'engagement' then
    select * into v_worker from public.hr_external_worker
    where id = (p_payload ->> 'worker_id')::uuid and tenant_id = v_tenant_id;
    if not found then raise exception '外部人员不存在或不属于当前租户'; end if;
    if v_worker.status = 'blocked' then raise exception '已锁定的外部人员不能建立用工任务'; end if;

    if nullif(p_payload ->> 'position_id', '') is not null then
      select organization_id into v_position_organization from public.mdm_position
      where id = (p_payload ->> 'position_id')::uuid and tenant_id = v_tenant_id and enabled;
      if not found then raise exception '岗位不存在、已停用或不属于当前租户'; end if;
      if v_position_organization is not null
         and v_position_organization <> (p_payload ->> 'organization_id')::uuid then
        raise exception '所选岗位不属于当前组织';
      end if;
    end if;

    if nullif(p_payload ->> 'billing_rate', '') is not null then
      if not app_private.can_execute_business_action(
        'HrContingentWorkforce', 'Hr:ContingentWorkforce:Cost:Edit', null, false
      ) then
        raise exception '当前账号没有编辑外部用工成本的权限' using errcode = '42501';
      end if;
      v_billing_rate := (p_payload ->> 'billing_rate')::numeric;
    end if;

    if p_id is null then
      insert into public.hr_external_engagement(
        id, tenant_id, engagement_no, worker_id, vendor_id, organization_id,
        position_id, sponsor_employee_id, service_title, work_location,
        start_date, end_date, access_expiry_date, fte, billing_rate,
        billing_unit, currency_code, compliance_status, status, activation_note
      ) values (
        v_id, v_tenant_id, btrim(p_payload ->> 'engagement_no'), v_worker.id,
        coalesce(nullif(p_payload ->> 'vendor_id', '')::uuid, v_worker.vendor_id),
        (p_payload ->> 'organization_id')::uuid,
        nullif(p_payload ->> 'position_id', '')::uuid,
        (p_payload ->> 'sponsor_employee_id')::uuid,
        btrim(p_payload ->> 'service_title'), nullif(btrim(p_payload ->> 'work_location'), ''),
        (p_payload ->> 'start_date')::date, (p_payload ->> 'end_date')::date,
        coalesce(nullif(p_payload ->> 'access_expiry_date', '')::date, (p_payload ->> 'end_date')::date),
        coalesce(nullif(p_payload ->> 'fte', '')::numeric, 1), v_billing_rate,
        nullif(p_payload ->> 'billing_unit', ''),
        coalesce(nullif(upper(p_payload ->> 'currency_code'), ''), 'CNY'),
        'pending', 'draft', nullif(btrim(p_payload ->> 'activation_note'), '')
      );

      insert into public.hr_external_engagement_control(
        tenant_id, engagement_id, control_type, control_name, required, due_date
      ) values
        (v_tenant_id, v_id, 'identity', '身份核验', true, (p_payload ->> 'start_date')::date),
        (v_tenant_id, v_id, 'contract', '用工合同或订单', true, (p_payload ->> 'start_date')::date),
        (v_tenant_id, v_id, 'nda', '保密协议', true, (p_payload ->> 'start_date')::date),
        (v_tenant_id, v_id, 'safety_training', '入场安全培训', true, (p_payload ->> 'start_date')::date),
        (v_tenant_id, v_id, 'access_badge', '门禁授权', true, (p_payload ->> 'start_date')::date),
        (v_tenant_id, v_id, 'system_account', '系统账号授权', true, (p_payload ->> 'start_date')::date);
    else
      select * into v_engagement from public.hr_external_engagement
      where id = p_id and tenant_id = v_tenant_id for update;
      if not found then raise exception '用工任务不存在或不属于当前租户'; end if;
      if v_engagement.status not in ('draft', 'pending_review') then
        raise exception '只有草稿或待审核任务可以修改核心信息';
      end if;
      v_expected_version := nullif(p_payload ->> 'version', '')::integer;
      if v_expected_version is not null and v_expected_version <> v_engagement.version then
        raise exception '用工任务已被其他用户更新，请刷新后重试' using errcode = '40001';
      end if;

      update public.hr_external_engagement set
        engagement_no = btrim(p_payload ->> 'engagement_no'),
        worker_id = v_worker.id,
        vendor_id = coalesce(nullif(p_payload ->> 'vendor_id', '')::uuid, v_worker.vendor_id),
        organization_id = (p_payload ->> 'organization_id')::uuid,
        position_id = nullif(p_payload ->> 'position_id', '')::uuid,
        sponsor_employee_id = (p_payload ->> 'sponsor_employee_id')::uuid,
        service_title = btrim(p_payload ->> 'service_title'),
        work_location = nullif(btrim(p_payload ->> 'work_location'), ''),
        start_date = (p_payload ->> 'start_date')::date,
        end_date = (p_payload ->> 'end_date')::date,
        access_expiry_date = coalesce(nullif(p_payload ->> 'access_expiry_date', '')::date, (p_payload ->> 'end_date')::date),
        fte = coalesce(nullif(p_payload ->> 'fte', '')::numeric, fte),
        billing_rate = case when p_payload ? 'billing_rate' then v_billing_rate else billing_rate end,
        billing_unit = case when p_payload ? 'billing_unit' then nullif(p_payload ->> 'billing_unit', '') else billing_unit end,
        currency_code = case when p_payload ? 'currency_code' then upper(p_payload ->> 'currency_code') else currency_code end,
        activation_note = nullif(btrim(p_payload ->> 'activation_note'), ''),
        version = version + 1
      where id = p_id;

      update public.hr_external_engagement_control set
        due_date = (p_payload ->> 'start_date')::date
      where engagement_id = p_id and status = 'pending';
    end if;
  else
    if p_id is null then
      insert into public.hr_external_engagement_control(
        id, tenant_id, engagement_id, control_type, control_name, required,
        status, due_date, completed_at, completed_by, evidence_reference, note
      ) values (
        v_id, v_tenant_id, (p_payload ->> 'engagement_id')::uuid,
        p_payload ->> 'control_type', btrim(p_payload ->> 'control_name'),
        coalesce((p_payload ->> 'required')::boolean, true),
        coalesce(nullif(p_payload ->> 'status', ''), 'pending'),
        nullif(p_payload ->> 'due_date', '')::date,
        case when p_payload ->> 'status' = 'completed' then now() else null end,
        case when p_payload ->> 'status' = 'completed' then coalesce(auth.jwt() ->> 'email', auth.uid()::text) else null end,
        nullif(btrim(p_payload ->> 'evidence_reference'), ''),
        nullif(btrim(p_payload ->> 'note'), '')
      );
    else
      update public.hr_external_engagement_control set
        control_type = p_payload ->> 'control_type',
        control_name = btrim(p_payload ->> 'control_name'),
        required = coalesce((p_payload ->> 'required')::boolean, required),
        status = coalesce(nullif(p_payload ->> 'status', ''), status),
        due_date = nullif(p_payload ->> 'due_date', '')::date,
        completed_at = case
          when p_payload ->> 'status' = 'completed' then coalesce(completed_at, now()) else null
        end,
        completed_by = case
          when p_payload ->> 'status' = 'completed'
            then coalesce(completed_by, auth.jwt() ->> 'email', auth.uid()::text)
          else null
        end,
        evidence_reference = nullif(btrim(p_payload ->> 'evidence_reference'), ''),
        note = nullif(btrim(p_payload ->> 'note'), '')
      where id = p_id and tenant_id = v_tenant_id;
      if not found then raise exception '准入控制项不存在或不属于当前租户'; end if;
    end if;

    update public.hr_external_engagement engagement set
      compliance_status = case
        when exists (
          select 1 from public.hr_external_engagement_control control
          where control.engagement_id = engagement.id and control.status = 'failed'
        ) then 'blocked'
        when not exists (
          select 1 from public.hr_external_engagement_control control
          where control.engagement_id = engagement.id and control.required
            and control.status not in ('completed', 'waived')
        ) then 'cleared'
        else 'pending'
      end,
      version = version + 1
    where engagement.id = (p_payload ->> 'engagement_id')::uuid
      or engagement.id = (
        select control.engagement_id from public.hr_external_engagement_control control where control.id = v_id
      );
  end if;

  return v_id;
end;
$$;


ALTER FUNCTION "public"."hr_save_contingent_workforce_record_secure"("p_kind" "text", "p_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: hr_save_employee_compensation_secure("uuid", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_save_employee_compensation_secure"("p_id" "uuid", "p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_id uuid := coalesce(p_id, gen_random_uuid());
  v_tenant_id uuid;
  v_employee_id uuid := nullif(p_payload->>'employee_id', '')::uuid;
  v_plan_id uuid := nullif(p_payload->>'plan_id', '')::uuid;
  v_grade_id uuid := nullif(p_payload->>'grade_id', '')::uuid;
  v_plan public.hr_compensation_plan%rowtype;
  v_permission text := case when p_id is null
    then 'Hr:Compensation:Record:Add' else 'Hr:Compensation:Record:Edit' end;
begin
  if not app_private.can_execute_business_action('HrCompensation', v_permission, null, false)
    or not app_private.can_execute_business_action(
      'HrCompensation', 'Hr:Compensation:Amount:Edit', null, false
    ) then
    raise exception 'Missing employee compensation edit permission' using errcode = '42501';
  end if;
  v_tenant_id := case when app_private.is_platform_super()
    then coalesce(
      nullif(p_payload->>'tenant_id', '')::uuid,
      (select tenant_id from public.hr_employee_compensation where id = p_id)
    )
    else app_private.current_user_tenant_id()
  end;
  if v_tenant_id is null then raise exception '请选择所属租户'; end if;
  if not exists (
    select 1 from public.mdm_employee
    where id = v_employee_id and tenant_id = v_tenant_id
      and employment_status in ('probation', 'active', 'leave')
  ) then raise exception '所选员工不可用'; end if;
  select * into v_plan from public.hr_compensation_plan
  where id = v_plan_id and tenant_id = v_tenant_id and enabled;
  if not found then raise exception '所选薪酬方案不可用'; end if;
  if v_grade_id is null then
    select assignment.grade_id into v_grade_id
    from public.mdm_employee_assignment assignment
    where assignment.employee_id = v_employee_id
      and assignment.tenant_id = v_tenant_id
      and assignment.primary_assignment and assignment.assignment_status = 'active'
      and assignment.effective_start <= (p_payload->>'effective_from')::date
      and coalesce(assignment.effective_end, 'infinity'::date) >= (p_payload->>'effective_from')::date
    order by assignment.effective_start desc limit 1;
  end if;
  if v_grade_id is not null and not exists (
    select 1 from public.mdm_grade where id = v_grade_id and tenant_id = v_tenant_id
  ) then raise exception '所选职级无效'; end if;
  if nullif(p_payload->>'source_change_id', '') is not null and not exists (
    select 1 from public.hr_personnel_change
    where id = nullif(p_payload->>'source_change_id', '')::uuid
      and tenant_id = v_tenant_id
  ) then raise exception '关联人事异动无效'; end if;
  if p_id is not null and not exists (
    select 1 from public.hr_employee_compensation
    where id = p_id and tenant_id = v_tenant_id and status = 'draft'
  ) then raise exception '只有草稿员工薪酬可以编辑'; end if;

  insert into public.hr_employee_compensation(
    id, tenant_id, employee_id, plan_id, grade_id, base_amount,
    currency_code, pay_frequency, effective_from, effective_to,
    status, change_reason, source_change_id
  ) values (
    v_id, v_tenant_id, v_employee_id, v_plan_id, v_grade_id,
    (p_payload->>'base_amount')::numeric,
    v_plan.currency_code, v_plan.pay_frequency,
    (p_payload->>'effective_from')::date,
    nullif(p_payload->>'effective_to', '')::date,
    'draft', btrim(p_payload->>'change_reason'),
    nullif(p_payload->>'source_change_id', '')::uuid
  )
  on conflict (id) do update set
    employee_id = excluded.employee_id,
    plan_id = excluded.plan_id,
    grade_id = excluded.grade_id,
    base_amount = excluded.base_amount,
    currency_code = excluded.currency_code,
    pay_frequency = excluded.pay_frequency,
    effective_from = excluded.effective_from,
    effective_to = excluded.effective_to,
    change_reason = excluded.change_reason,
    source_change_id = excluded.source_change_id
  where hr_employee_compensation.tenant_id = v_tenant_id
    and hr_employee_compensation.status = 'draft';
  if not found then raise exception '员工薪酬不存在或无权编辑'; end if;

  delete from public.hr_employee_compensation_item where compensation_id = v_id;
  insert into public.hr_employee_compensation_item(
    tenant_id, compensation_id, component_id, amount, rate, source
  )
  select
    v_tenant_id, v_id, plan_item.component_id,
    coalesce(nullif(payload_item.item->>'amount', '')::numeric, plan_item.default_amount),
    coalesce(nullif(payload_item.item->>'rate', '')::numeric, plan_item.default_rate),
    case when payload_item.item is null then 'plan' else 'override' end
  from public.hr_compensation_plan_item plan_item
  left join lateral (
    select item
    from jsonb_array_elements(coalesce(p_payload->'items', '[]'::jsonb)) item
    where nullif(item->>'component_id', '')::uuid = plan_item.component_id
    limit 1
  ) payload_item on true
  where plan_item.plan_id = v_plan_id
    and plan_item.tenant_id = v_tenant_id;

  if exists (
    select 1 from jsonb_array_elements(coalesce(p_payload->'items', '[]'::jsonb)) item
    where not exists (
      select 1 from public.hr_compensation_plan_item plan_item
      where plan_item.plan_id = v_plan_id
        and plan_item.component_id = nullif(item->>'component_id', '')::uuid
    )
  ) then raise exception '员工薪酬包含方案之外的薪酬项目'; end if;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."hr_save_employee_compensation_secure"("p_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: hr_save_employee_experience_record_secure("text", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_save_employee_experience_record_secure"("p_kind" "text", "p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_id uuid := nullif(p_payload ->> 'id', '')::uuid;
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_status text;
  v_survey public.hr_experience_survey;
  v_question public.hr_experience_question;
  v_action public.hr_experience_action;
begin
  if auth.uid() is null then raise exception '请先登录' using errcode = '42501'; end if;
  if app_private.is_platform_super() and nullif(p_payload ->> 'tenant_id', '') is not null then
    v_tenant_id := (p_payload ->> 'tenant_id')::uuid;
  end if;

  if p_kind = 'survey' then
    if not app_private.can_execute_business_action(
      'HrEmployeeExperience', 'Hr:Experience:Survey:Manage', v_id, false
    ) then raise exception '当前账号没有管理员工体验调查的权限' using errcode = '42501'; end if;
    if v_id is null then
      insert into public.hr_experience_survey(
        tenant_id, survey_code, survey_name, survey_type, cadence,
        audience_type, audience_organization_id, minimum_group_size,
        start_date, end_date, status, description
      ) values (
        v_tenant_id, btrim(p_payload ->> 'survey_code'), btrim(p_payload ->> 'survey_name'),
        p_payload ->> 'survey_type', coalesce(nullif(p_payload ->> 'cadence', ''), 'one_time'),
        coalesce(nullif(p_payload ->> 'audience_type', ''), 'all_active'),
        nullif(p_payload ->> 'audience_organization_id', '')::uuid,
        coalesce((p_payload ->> 'minimum_group_size')::integer, 5),
        (p_payload ->> 'start_date')::date, (p_payload ->> 'end_date')::date,
        'draft', nullif(btrim(p_payload ->> 'description'), '')
      ) returning * into v_survey;
      v_id := v_survey.id;
      perform app_private.hr_add_experience_event(v_tenant_id, 'survey', v_id,
        'created', null, 'draft', '创建员工体验调查');
    else
      select status into v_status from public.hr_experience_survey
        where id = v_id and tenant_id = v_tenant_id for update;
      if v_status is null then raise exception '调查不存在或无权编辑'; end if;
      if v_status <> 'draft' then raise exception '只有草稿调查可以编辑'; end if;
      update public.hr_experience_survey set
        survey_code = btrim(p_payload ->> 'survey_code'),
        survey_name = btrim(p_payload ->> 'survey_name'),
        survey_type = p_payload ->> 'survey_type',
        cadence = p_payload ->> 'cadence',
        audience_type = p_payload ->> 'audience_type',
        audience_organization_id = nullif(p_payload ->> 'audience_organization_id', '')::uuid,
        minimum_group_size = (p_payload ->> 'minimum_group_size')::integer,
        start_date = (p_payload ->> 'start_date')::date,
        end_date = (p_payload ->> 'end_date')::date,
        description = nullif(btrim(p_payload ->> 'description'), '')
      where id = v_id and tenant_id = v_tenant_id returning * into v_survey;
      perform app_private.hr_add_experience_event(v_tenant_id, 'survey', v_id,
        'updated', 'draft', 'draft', '更新调查设置');
    end if;
  elsif p_kind = 'question' then
    if not app_private.can_execute_business_action(
      'HrEmployeeExperience', 'Hr:Experience:Question:Manage', v_id, false
    ) then raise exception '当前账号没有管理调查题目的权限' using errcode = '42501'; end if;
    if not exists (
      select 1 from public.hr_experience_survey survey
      where survey.id = (p_payload ->> 'survey_id')::uuid
        and survey.tenant_id = v_tenant_id and survey.status = 'draft'
    ) then raise exception '只有草稿调查可以维护题目'; end if;
    if v_id is null then
      insert into public.hr_experience_question(
        tenant_id, survey_id, dimension, question_text, answer_type,
        required, enabled, sort
      ) values (
        v_tenant_id, (p_payload ->> 'survey_id')::uuid,
        p_payload ->> 'dimension', btrim(p_payload ->> 'question_text'),
        p_payload ->> 'answer_type', coalesce((p_payload ->> 'required')::boolean, true),
        coalesce((p_payload ->> 'enabled')::boolean, true),
        coalesce((p_payload ->> 'sort')::integer, 0)
      ) returning * into v_question;
      v_id := v_question.id;
      perform app_private.hr_add_experience_event(v_tenant_id, 'survey', v_question.survey_id,
        'question_created', null, 'draft', '新增调查题目',
        jsonb_build_object('question_id', v_id));
    else
      update public.hr_experience_question set
        dimension = p_payload ->> 'dimension',
        question_text = btrim(p_payload ->> 'question_text'),
        answer_type = p_payload ->> 'answer_type',
        required = coalesce((p_payload ->> 'required')::boolean, true),
        enabled = coalesce((p_payload ->> 'enabled')::boolean, true),
        sort = coalesce((p_payload ->> 'sort')::integer, 0)
      where id = v_id and tenant_id = v_tenant_id
        and survey_id = (p_payload ->> 'survey_id')::uuid
      returning * into v_question;
      if v_question.id is null then raise exception '题目不存在或无权编辑'; end if;
      perform app_private.hr_add_experience_event(v_tenant_id, 'survey', v_question.survey_id,
        'question_updated', null, 'draft', '更新调查题目',
        jsonb_build_object('question_id', v_id));
    end if;
  elsif p_kind = 'action' then
    if not app_private.can_execute_business_action(
      'HrEmployeeExperience', 'Hr:Experience:Action:Manage', v_id, false
    ) then raise exception '当前账号没有管理员工体验行动的权限' using errcode = '42501'; end if;
    if not exists (select 1 from public.hr_experience_survey survey
      where survey.id = (p_payload ->> 'survey_id')::uuid and survey.tenant_id = v_tenant_id
        and survey.status in ('open', 'closed')) then
      raise exception '行动计划只能关联收集中或已关闭的调查';
    end if;
    if not exists (select 1 from public.mdm_employee employee
      where employee.id = (p_payload ->> 'owner_employee_id')::uuid
        and employee.tenant_id = v_tenant_id
        and employee.employment_status not in ('left', 'terminated')) then
      raise exception '行动负责人不存在、已离职或不属于当前租户';
    end if;
    if nullif(p_payload ->> 'organization_id', '') is not null and not exists (
      select 1 from public.mdm_organization organization
      where organization.id = (p_payload ->> 'organization_id')::uuid
        and organization.tenant_id = v_tenant_id
    ) then raise exception '行动组织不存在或不属于当前租户'; end if;
    if v_id is null then
      insert into public.hr_experience_action(
        tenant_id, survey_id, organization_id, dimension, title,
        owner_employee_id, due_date, status, success_measure, progress_note
      ) values (
        v_tenant_id, (p_payload ->> 'survey_id')::uuid,
        nullif(p_payload ->> 'organization_id', '')::uuid,
        p_payload ->> 'dimension', btrim(p_payload ->> 'title'),
        (p_payload ->> 'owner_employee_id')::uuid, (p_payload ->> 'due_date')::date,
        'planned', btrim(p_payload ->> 'success_measure'),
        nullif(btrim(p_payload ->> 'progress_note'), '')
      ) returning * into v_action;
      v_id := v_action.id;
      perform app_private.hr_add_experience_event(v_tenant_id, 'action', v_id,
        'created', null, 'planned', '创建员工体验改进行动');
    else
      select status into v_status from public.hr_experience_action
        where id = v_id and tenant_id = v_tenant_id for update;
      if v_status not in ('planned', 'in_progress') then
        raise exception '只有待开始或进行中的行动可以编辑';
      end if;
      update public.hr_experience_action set
        organization_id = nullif(p_payload ->> 'organization_id', '')::uuid,
        dimension = p_payload ->> 'dimension', title = btrim(p_payload ->> 'title'),
        owner_employee_id = (p_payload ->> 'owner_employee_id')::uuid,
        due_date = (p_payload ->> 'due_date')::date,
        success_measure = btrim(p_payload ->> 'success_measure'),
        progress_note = nullif(btrim(p_payload ->> 'progress_note'), '')
      where id = v_id and tenant_id = v_tenant_id returning * into v_action;
      perform app_private.hr_add_experience_event(v_tenant_id, 'action', v_id,
        'updated', v_status, v_status, '更新员工体验改进行动');
    end if;
  else
    raise exception '不支持的员工体验记录类型';
  end if;
  return v_id;
end
$$;


ALTER FUNCTION "public"."hr_save_employee_experience_record_secure"("p_kind" "text", "p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: hr_save_employee_profile_secure("jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_save_employee_profile_secure"("p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception '员工档案数据格式不正确';
  end if;
  if p_payload ? 'driver' and p_payload -> 'driver' <> 'null'::jsonb then
    raise exception '员工档案不再创建司机档案，请前往司机管理从员工花名册选取';
  end if;
  return app_private.save_employee_profile_records_secure(p_payload - 'driver');
end;
$$;


ALTER FUNCTION "public"."hr_save_employee_profile_secure"("p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: hr_save_employee_relations_record_secure("text", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_save_employee_relations_record_secure"("p_kind" "text", "p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_id uuid := nullif(p_payload->>'id', '')::uuid;
  v_tenant_id uuid := coalesce(nullif(p_payload->>'tenant_id', '')::uuid,
    app_private.current_user_tenant_id());
  v_case public.hr_employee_relation_case;
  v_before public.hr_employee_relation_case;
  v_action public.hr_employee_relation_action;
  v_case_no text;
begin
  if p_kind not in ('case', 'action') then
    raise exception '不支持的员工关系记录类型';
  end if;
  if not app_private.is_platform_super() then
    v_tenant_id := app_private.current_user_tenant_id();
  end if;

  if p_kind = 'case' then
    if v_id is null then
      if not app_private.can_execute_business_action(
        'HrEmployeeRelations', 'Hr:EmployeeRelations:Add', null, false
      ) then
        raise exception '当前账号没有新建员工关系案件的权限' using errcode = '42501';
      end if;
      v_case_no := nullif(btrim(p_payload->>'case_no'), '');
      if v_case_no is null or upper(v_case_no) = 'AUTO' then
        v_case_no := 'ERC' || to_char(clock_timestamp(), 'YYYYMMDDHH24MISSMS');
      end if;
      insert into public.hr_employee_relation_case(
        tenant_id, case_no, case_type, title, subject_employee_id,
        reporter_employee_id, anonymous_report, source, severity,
        confidentiality_level, status, allegation_summary, attachment_urls,
        external_reference, remark
      ) values (
        v_tenant_id, v_case_no, p_payload->>'case_type', btrim(p_payload->>'title'),
        (p_payload->>'subject_employee_id')::uuid,
        case when coalesce((p_payload->>'anonymous_report')::boolean, false) then null
          else nullif(p_payload->>'reporter_employee_id', '')::uuid end,
        coalesce((p_payload->>'anonymous_report')::boolean, false),
        coalesce(nullif(p_payload->>'source', ''), 'hr'),
        coalesce(nullif(p_payload->>'severity', ''), 'medium'),
        coalesce(nullif(p_payload->>'confidentiality_level', ''), 'restricted'),
        'draft', btrim(p_payload->>'allegation_summary'),
        coalesce(p_payload->'attachment_urls', '[]'::jsonb),
        nullif(btrim(p_payload->>'external_reference'), ''),
        nullif(btrim(p_payload->>'remark'), '')
      ) returning * into v_case;
      perform app_private.hr_add_employee_relation_event(
        v_case, 'created', null, 'draft', '创建员工关系案件草稿'
      );
      return v_case.id;
    end if;

    if not app_private.can_execute_business_action(
      'HrEmployeeRelations', 'Hr:EmployeeRelations:Edit', v_id, false
    ) then
      raise exception '当前账号没有编辑员工关系案件的权限' using errcode = '42501';
    end if;
    select * into v_before from public.hr_employee_relation_case where id = v_id for update;
    if v_before.id is null or v_before.tenant_id <> v_tenant_id then
      raise exception '员工关系案件不存在或无权编辑';
    end if;
    if v_before.status not in ('draft', 'reported') then
      raise exception '案件完成分级后，核心资料只能通过受控动作更新';
    end if;
    update public.hr_employee_relation_case set
      case_type = p_payload->>'case_type',
      title = btrim(p_payload->>'title'),
      subject_employee_id = (p_payload->>'subject_employee_id')::uuid,
      reporter_employee_id = case
        when coalesce((p_payload->>'anonymous_report')::boolean, false) then null
        else nullif(p_payload->>'reporter_employee_id', '')::uuid end,
      anonymous_report = coalesce((p_payload->>'anonymous_report')::boolean, false),
      source = p_payload->>'source', severity = p_payload->>'severity',
      confidentiality_level = p_payload->>'confidentiality_level',
      allegation_summary = btrim(p_payload->>'allegation_summary'),
      attachment_urls = coalesce(p_payload->'attachment_urls', '[]'::jsonb),
      external_reference = nullif(btrim(p_payload->>'external_reference'), ''),
      remark = nullif(btrim(p_payload->>'remark'), '')
    where id = v_before.id returning * into v_case;
    perform app_private.hr_add_employee_relation_event(
      v_case, 'updated', v_before.status, v_case.status, '更新案件基础资料'
    );
    return v_case.id;
  end if;

  if not app_private.can_execute_business_action(
    'HrEmployeeRelations', 'Hr:EmployeeRelations:Action:Manage', v_id, false
  ) then
    raise exception '当前账号没有管理员工关系处置行动的权限' using errcode = '42501';
  end if;
  select * into v_case from public.hr_employee_relation_case
    where id = (p_payload->>'case_id')::uuid;
  if v_case.id is null or v_case.tenant_id <> v_tenant_id
    or v_case.status not in ('investigating', 'action_required') then
    raise exception '只有调查中或待处置案件可以维护处置行动';
  end if;
  if v_id is null then
    insert into public.hr_employee_relation_action(
      tenant_id, case_id, action_type, title, owner_employee_id, due_date, status, remark
    ) values (
      v_tenant_id, v_case.id, p_payload->>'action_type', btrim(p_payload->>'title'),
      (p_payload->>'owner_employee_id')::uuid, (p_payload->>'due_date')::date,
      'planned', nullif(btrim(p_payload->>'remark'), '')
    ) returning * into v_action;
    perform app_private.hr_add_employee_relation_event(
      v_case, 'action_created', v_case.status, v_case.status,
      '创建处置行动', jsonb_build_object('action_id', v_action.id)
    );
    return v_action.id;
  end if;
  select * into v_action from public.hr_employee_relation_action where id = v_id for update;
  if v_action.id is null or v_action.tenant_id <> v_tenant_id
    or v_action.status <> 'planned' then
    raise exception '只有待开始的处置行动可以编辑';
  end if;
  update public.hr_employee_relation_action set
    action_type = p_payload->>'action_type', title = btrim(p_payload->>'title'),
    owner_employee_id = (p_payload->>'owner_employee_id')::uuid,
    due_date = (p_payload->>'due_date')::date,
    remark = nullif(btrim(p_payload->>'remark'), '')
  where id = v_action.id returning * into v_action;
  perform app_private.hr_add_employee_relation_event(
    v_case, 'action_updated', v_case.status, v_case.status,
    '更新处置行动', jsonb_build_object('action_id', v_action.id)
  );
  return v_action.id;
end
$$;


ALTER FUNCTION "public"."hr_save_employee_relations_record_secure"("p_kind" "text", "p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: hr_save_internal_mobility_application_secure("uuid", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_save_internal_mobility_application_secure"("p_id" "uuid", "p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    SET "TimeZone" TO 'Asia/Shanghai'
    AS $$
declare
  v_tenant_id uuid:=app_private.current_user_tenant_id(); v_self_employee_id uuid:=app_private.hr_current_employee_id();
  v_manage boolean:=app_private.can_execute_business_action('HrInternalMobility','Hr:InternalMobility:Application:Manage',null,false);
  v_self boolean:=app_private.can_execute_business_action('HrInternalMobility','Hr:InternalMobility:Application:Self',null,false);
  v_employee_id uuid:=case when v_manage and nullif(p_payload->>'employee_id','') is not null then (p_payload->>'employee_id')::uuid else v_self_employee_id end;
  v_id uuid:=coalesce(p_id,gen_random_uuid()); v_opportunity public.hr_internal_opportunity%rowtype; v_employee public.mdm_employee%rowtype;
  v_existing public.hr_internal_mobility_application%rowtype;
begin
  if auth.uid() is null or not (v_manage or v_self) then raise exception '当前账号没有提交内部申请的权限' using errcode='42501'; end if;
  if v_employee_id is null then raise exception '当前账号尚未关联员工档案，不能提交内部申请'; end if;
  select * into v_opportunity from public.hr_internal_opportunity
  where id=(p_payload->>'opportunity_id')::uuid
    and (app_private.is_platform_super() or tenant_id=v_tenant_id);
  if not found or v_opportunity.status<>'open' or current_date not between v_opportunity.application_open_date and v_opportunity.application_close_date
    then raise exception '内部机会未开放或已超过申请期'; end if;
  v_tenant_id:=v_opportunity.tenant_id;
  select * into v_employee from public.mdm_employee where id=v_employee_id and tenant_id=v_tenant_id and employment_status in ('probation','active');
  if not found then raise exception '申请员工不可用、已离职或不属于当前租户'; end if;
  if v_employee.hire_date is null or v_employee.hire_date + make_interval(months=>v_opportunity.min_tenure_months)>current_date
    then raise exception '当前员工任职年限未达到机会要求'; end if;
  if v_opportunity.position_id is not null and v_employee.position_id=v_opportunity.position_id then raise exception '员工已在目标岗位，无需重复申请'; end if;
  if p_id is null then
    insert into public.hr_internal_mobility_application(
      id,tenant_id,opportunity_id,employee_id,current_organization_id,current_position_id,current_job_title,
      motivation,relevant_experience,preferred_start_date,manager_awareness
    ) values(
      v_id,v_tenant_id,v_opportunity.id,v_employee.id,v_employee.organization_id,v_employee.position_id,v_employee.job_title,
      btrim(p_payload->>'motivation'),nullif(btrim(p_payload->>'relevant_experience'),''),
      nullif(p_payload->>'preferred_start_date','')::date,coalesce(nullif(p_payload->>'manager_awareness',''),'not_informed')
    );
  else
    select * into v_existing from public.hr_internal_mobility_application
    where id=p_id and (app_private.is_platform_super() or tenant_id=v_tenant_id) for update;
    if not found or (not v_manage and v_existing.employee_id<>v_self_employee_id) then raise exception '内部申请不存在或无权编辑'; end if;
    if v_existing.status<>'draft' then raise exception '仅草稿申请可以编辑'; end if;
    if v_existing.opportunity_id<>v_opportunity.id or v_existing.employee_id<>v_employee_id then raise exception '草稿申请的机会和员工不可更换'; end if;
    update public.hr_internal_mobility_application set motivation=btrim(p_payload->>'motivation'),
      relevant_experience=nullif(btrim(p_payload->>'relevant_experience'),''),
      preferred_start_date=nullif(p_payload->>'preferred_start_date','')::date,
      manager_awareness=coalesce(nullif(p_payload->>'manager_awareness',''),'not_informed') where id=p_id;
  end if;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."hr_save_internal_mobility_application_secure"("p_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: hr_save_internal_opportunity_secure("uuid", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_save_internal_opportunity_secure"("p_id" "uuid", "p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_current_tenant uuid:=app_private.current_user_tenant_id();
  v_tenant_id uuid:=case when app_private.is_platform_super() and nullif(p_payload->>'tenant_id','') is not null then (p_payload->>'tenant_id')::uuid else v_current_tenant end;
  v_id uuid:=coalesce(p_id,gen_random_uuid()); v_existing public.hr_internal_opportunity%rowtype;
  v_org_id uuid:=nullif(p_payload->>'organization_id','')::uuid; v_position_id uuid:=nullif(p_payload->>'position_id','')::uuid;
begin
  if auth.uid() is null or not app_private.can_execute_business_action('HrInternalMobility','Hr:InternalMobility:Opportunity:Manage',null,false)
    then raise exception '当前账号没有管理内部机会草稿的权限' using errcode='42501'; end if;
  if not exists(select 1 from public.mdm_organization o where o.id=v_org_id and o.tenant_id=v_tenant_id and o.status='1')
    then raise exception '目标组织不可用或不属于当前租户'; end if;
  if v_position_id is not null and not exists(select 1 from public.mdm_position p where p.id=v_position_id and p.tenant_id=v_tenant_id and p.enabled and (p.organization_id is null or p.organization_id=v_org_id))
    then raise exception '目标岗位不可用或不属于目标组织'; end if;
  if not exists(select 1 from public.mdm_employee e where e.id=(p_payload->>'hiring_manager_employee_id')::uuid and e.tenant_id=v_tenant_id and e.employment_status in ('probation','active','leave'))
    then raise exception '招聘负责人不可用或不属于当前租户'; end if;
  if p_id is null then
    insert into public.hr_internal_opportunity(
      id,tenant_id,opportunity_code,opportunity_title,opportunity_type,organization_id,position_id,
      hiring_manager_employee_id,capacity,work_location,work_mode,expected_start_date,expected_end_date,
      application_open_date,application_close_date,min_tenure_months,role_summary,required_skills,eligibility_notes
    ) values(
      v_id,v_tenant_id,btrim(p_payload->>'opportunity_code'),btrim(p_payload->>'opportunity_title'),p_payload->>'opportunity_type',
      v_org_id,v_position_id,(p_payload->>'hiring_manager_employee_id')::uuid,
      coalesce(nullif(p_payload->>'capacity','')::integer,1),nullif(btrim(p_payload->>'work_location'),''),
      coalesce(nullif(p_payload->>'work_mode',''),'onsite'),(p_payload->>'expected_start_date')::date,
      nullif(p_payload->>'expected_end_date','')::date,(p_payload->>'application_open_date')::date,
      (p_payload->>'application_close_date')::date,coalesce(nullif(p_payload->>'min_tenure_months','')::integer,0),
      btrim(p_payload->>'role_summary'),btrim(p_payload->>'required_skills'),nullif(btrim(p_payload->>'eligibility_notes'),'')
    );
  else
    select * into v_existing from public.hr_internal_opportunity where id=p_id and (app_private.is_platform_super() or tenant_id=v_current_tenant) for update;
    if not found then raise exception '内部机会不存在或不属于当前租户'; end if;
    if v_existing.status<>'draft' then raise exception '仅草稿内部机会可以编辑'; end if;
    if coalesce(nullif(p_payload->>'version','')::integer,0)<>v_existing.version then raise exception '内部机会已被他人更新，请刷新后重试' using errcode='40001'; end if;
    update public.hr_internal_opportunity set
      opportunity_code=btrim(p_payload->>'opportunity_code'),opportunity_title=btrim(p_payload->>'opportunity_title'),
      opportunity_type=p_payload->>'opportunity_type',organization_id=v_org_id,position_id=v_position_id,
      hiring_manager_employee_id=(p_payload->>'hiring_manager_employee_id')::uuid,
      capacity=(p_payload->>'capacity')::integer,work_location=nullif(btrim(p_payload->>'work_location'),''),
      work_mode=p_payload->>'work_mode',expected_start_date=(p_payload->>'expected_start_date')::date,
      expected_end_date=nullif(p_payload->>'expected_end_date','')::date,
      application_open_date=(p_payload->>'application_open_date')::date,
      application_close_date=(p_payload->>'application_close_date')::date,
      min_tenure_months=(p_payload->>'min_tenure_months')::integer,
      role_summary=btrim(p_payload->>'role_summary'),required_skills=btrim(p_payload->>'required_skills'),
      eligibility_notes=nullif(btrim(p_payload->>'eligibility_notes'),''),version=version+1 where id=p_id;
  end if;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."hr_save_internal_opportunity_secure"("p_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: hr_save_learning_record_secure("text", "uuid", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_save_learning_record_secure"("p_kind" "text", "p_id" "uuid" DEFAULT NULL::"uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_current_tenant uuid := app_private.current_user_tenant_id();
  v_tenant_id uuid;
  v_permission text;
  v_id uuid := coalesce(p_id, gen_random_uuid());
  v_session public.hr_learning_session%rowtype;
begin
  v_tenant_id := case when app_private.is_platform_super()
    then coalesce((p_payload ->> 'tenant_id')::uuid, v_current_tenant)
    else v_current_tenant end;
  if v_tenant_id is null then raise exception '必须指定所属租户'; end if;

  v_permission := case p_kind
    when 'plan' then case when p_id is null then 'Hr:Talent:Add' else 'Hr:Talent:Edit' end
    when 'course' then case when p_id is null then 'Hr:Talent:Course:Add' else 'Hr:Talent:Course:Edit' end
    when 'session' then case when p_id is null then 'Hr:Talent:Session:Add' else 'Hr:Talent:Session:Edit' end
    when 'enrollment' then case when p_id is null then 'Hr:Talent:Enrollment:Add' else 'Hr:Talent:Enrollment:Manage' end
    when 'course_competency' then 'Hr:Talent:Course:Competency'
    when 'certificate' then 'Hr:Talent:Certificate:Manage'
    else null end;
  if v_permission is null then raise exception '不支持的学习发展记录类型'; end if;
  if not app_private.can_execute_business_action('HrTalentDevelopment', v_permission, null, false) then
    raise exception '当前账号没有维护该学习发展记录的权限' using errcode = '42501';
  end if;

  if p_kind = 'plan' then
    if p_id is not null and not exists (
      select 1 from public.hr_training_plan where id = p_id and tenant_id = v_tenant_id and status = 'draft'
    ) then raise exception '仅草稿培训计划允许编辑'; end if;
    insert into public.hr_training_plan(
      id, tenant_id, plan_code, plan_name, training_type, start_date, end_date,
      provider_name, budget, status, objective, remark, owner_employee_id, target_audience, mandatory
    ) values (
      v_id, v_tenant_id, btrim(p_payload ->> 'plan_code'), btrim(p_payload ->> 'plan_name'),
      p_payload ->> 'training_type', (p_payload ->> 'start_date')::date,
      nullif(p_payload ->> 'end_date', '')::date, nullif(btrim(p_payload ->> 'provider_name'), ''),
      nullif(p_payload ->> 'budget', '')::numeric, 'draft', nullif(btrim(p_payload ->> 'objective'), ''),
      nullif(btrim(p_payload ->> 'remark'), ''), nullif(p_payload ->> 'owner_employee_id', '')::uuid,
      nullif(btrim(p_payload ->> 'target_audience'), ''), coalesce((p_payload ->> 'mandatory')::boolean, false)
    ) on conflict (id) do update set
      plan_code = excluded.plan_code, plan_name = excluded.plan_name, training_type = excluded.training_type,
      start_date = excluded.start_date, end_date = excluded.end_date, provider_name = excluded.provider_name,
      budget = excluded.budget, objective = excluded.objective, remark = excluded.remark,
      owner_employee_id = excluded.owner_employee_id, target_audience = excluded.target_audience,
      mandatory = excluded.mandatory;
    return v_id;
  end if;

  if p_kind = 'course' then
    if p_id is not null and not exists (
      select 1 from public.hr_learning_course where id = p_id and tenant_id = v_tenant_id and status = 'draft'
    ) then raise exception '仅草稿课程允许编辑'; end if;
    insert into public.hr_learning_course(
      id, tenant_id, course_code, course_name, category, delivery_mode, duration_hours, credit_hours,
      provider_name, passing_score, minimum_attendance_percent, certificate_enabled,
      certificate_valid_months, status, description, learning_objectives, target_audience
    ) values (
      v_id, v_tenant_id, btrim(p_payload ->> 'course_code'), btrim(p_payload ->> 'course_name'),
      p_payload ->> 'category', p_payload ->> 'delivery_mode', (p_payload ->> 'duration_hours')::numeric,
      coalesce(nullif(p_payload ->> 'credit_hours', '')::numeric, 0), nullif(btrim(p_payload ->> 'provider_name'), ''),
      nullif(p_payload ->> 'passing_score', '')::numeric,
      coalesce(nullif(p_payload ->> 'minimum_attendance_percent', '')::numeric, 80),
      coalesce((p_payload ->> 'certificate_enabled')::boolean, false),
      nullif(p_payload ->> 'certificate_valid_months', '')::integer, 'draft',
      nullif(btrim(p_payload ->> 'description'), ''), nullif(btrim(p_payload ->> 'learning_objectives'), ''),
      nullif(btrim(p_payload ->> 'target_audience'), '')
    ) on conflict (id) do update set
      course_code = excluded.course_code, course_name = excluded.course_name, category = excluded.category,
      delivery_mode = excluded.delivery_mode, duration_hours = excluded.duration_hours,
      credit_hours = excluded.credit_hours, provider_name = excluded.provider_name,
      passing_score = excluded.passing_score, minimum_attendance_percent = excluded.minimum_attendance_percent,
      certificate_enabled = excluded.certificate_enabled, certificate_valid_months = excluded.certificate_valid_months,
      description = excluded.description, learning_objectives = excluded.learning_objectives,
      target_audience = excluded.target_audience;
    return v_id;
  end if;

  if p_kind = 'session' then
    if p_id is not null and not exists (
      select 1 from public.hr_learning_session where id = p_id and tenant_id = v_tenant_id and status = 'planned'
    ) then raise exception '仅待开放班次允许编辑'; end if;
    if not exists (
      select 1 from public.hr_training_plan where id = (p_payload ->> 'plan_id')::uuid
        and tenant_id = v_tenant_id and status in ('published', 'in_progress')
    ) then raise exception '培训计划尚未发布'; end if;
    if not exists (
      select 1 from public.hr_learning_course where id = (p_payload ->> 'course_id')::uuid
        and tenant_id = v_tenant_id and status = 'published'
    ) then raise exception '课程尚未发布'; end if;
    insert into public.hr_learning_session(
      id, tenant_id, session_code, plan_id, course_id, start_at, end_at, enrollment_deadline,
      capacity, instructor_name, location, meeting_url, estimated_cost, status
    ) values (
      v_id, v_tenant_id, btrim(p_payload ->> 'session_code'), (p_payload ->> 'plan_id')::uuid,
      (p_payload ->> 'course_id')::uuid, (p_payload ->> 'start_at')::timestamptz,
      (p_payload ->> 'end_at')::timestamptz, nullif(p_payload ->> 'enrollment_deadline', '')::timestamptz,
      coalesce((p_payload ->> 'capacity')::integer, 30), nullif(btrim(p_payload ->> 'instructor_name'), ''),
      nullif(btrim(p_payload ->> 'location'), ''), nullif(btrim(p_payload ->> 'meeting_url'), ''),
      nullif(p_payload ->> 'estimated_cost', '')::numeric, 'planned'
    ) on conflict (id) do update set
      session_code = excluded.session_code, plan_id = excluded.plan_id, course_id = excluded.course_id,
      start_at = excluded.start_at, end_at = excluded.end_at, enrollment_deadline = excluded.enrollment_deadline,
      capacity = excluded.capacity, instructor_name = excluded.instructor_name, location = excluded.location,
      meeting_url = excluded.meeting_url, estimated_cost = excluded.estimated_cost;
    return v_id;
  end if;

  if p_kind = 'enrollment' then
    if p_id is not null and not exists (
      select 1 from public.hr_training_enrollment where id = p_id and tenant_id = v_tenant_id and status = 'enrolled'
    ) then raise exception '仅已报名记录允许编辑'; end if;
    select * into v_session from public.hr_learning_session
    where id = (p_payload ->> 'session_id')::uuid and tenant_id = v_tenant_id and status = 'open';
    if not found then raise exception '班次当前不可报名'; end if;
    if not exists (
      select 1 from public.mdm_employee where id = (p_payload ->> 'employee_id')::uuid and tenant_id = v_tenant_id
    ) then raise exception '员工不属于当前租户'; end if;
    if p_id is null and (
      select count(*) from public.hr_training_enrollment where session_id = v_session.id and status <> 'withdrawn'
    ) >= v_session.capacity then raise exception '班次名额已满'; end if;
    insert into public.hr_training_enrollment(
      id, tenant_id, plan_id, session_id, employee_id, status, nominated_by_employee_id, remark
    ) values (
      v_id, v_tenant_id, v_session.plan_id, v_session.id, (p_payload ->> 'employee_id')::uuid,
      'enrolled', nullif(p_payload ->> 'nominated_by_employee_id', '')::uuid,
      nullif(btrim(p_payload ->> 'remark'), '')
    ) on conflict (id) do update set
      employee_id = excluded.employee_id, nominated_by_employee_id = excluded.nominated_by_employee_id,
      remark = excluded.remark;
    return v_id;
  end if;

  if p_kind = 'course_competency' then
    if not exists (
      select 1 from public.hr_learning_course where id = (p_payload ->> 'course_id')::uuid
        and tenant_id = v_tenant_id and status = 'draft'
    ) then raise exception '仅草稿课程允许维护能力映射'; end if;
    insert into public.hr_learning_course_competency(
      id, tenant_id, course_id, competency_id, target_level
    ) values (
      v_id, v_tenant_id, (p_payload ->> 'course_id')::uuid,
      (p_payload ->> 'competency_id')::uuid, p_payload ->> 'target_level'
    ) on conflict (id) do update set
      course_id = excluded.course_id, competency_id = excluded.competency_id, target_level = excluded.target_level;
    return v_id;
  end if;

  if p_id is null then raise exception '证书只能由学习完成结果自动生成'; end if;
  update public.hr_learning_certificate
  set credential_url = nullif(btrim(p_payload ->> 'credential_url'), '')
  where id = p_id and tenant_id = v_tenant_id and status = 'valid';
  if not found then raise exception '仅有效证书允许维护凭证地址'; end if;
  return p_id;
end
$$;


ALTER FUNCTION "public"."hr_save_learning_record_secure"("p_kind" "text", "p_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: hr_save_leave_request_secure("uuid", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_save_leave_request_secure"("p_id" "uuid" DEFAULT NULL::"uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := coalesce(nullif(p_payload->>'tenant_id', '')::uuid, app_private.current_user_tenant_id());
  v_permission text := case when p_id is null then 'Hr:Absence:Request:Add' else 'Hr:Absence:Request:Edit' end;
  v_employee_id uuid := (p_payload->>'employee_id')::uuid;
  v_leave_type_id uuid := (p_payload->>'leave_type_id')::uuid;
  v_start_date date := (p_payload->>'start_date')::date;
  v_end_date date := (p_payload->>'end_date')::date;
  v_leave_type public.hr_leave_type%rowtype;
  v_policy_id uuid;
  v_result_id uuid;
begin
  if not app_private.can_execute_business_action('HrAbsence', v_permission, null, false) then
    raise exception 'Missing leave request permission' using errcode = '42501';
  end if;
  if not app_private.is_platform_super() then v_tenant_id := app_private.current_user_tenant_id(); end if;
  if not exists (select 1 from public.mdm_employee where id = v_employee_id and tenant_id = v_tenant_id) then
    raise exception '员工不存在或不属于当前租户';
  end if;
  select * into v_leave_type from public.hr_leave_type
  where id = v_leave_type_id and tenant_id = v_tenant_id and enabled;
  if v_leave_type.id is null then raise exception '假别不存在或已停用'; end if;
  if extract(year from v_start_date) <> extract(year from v_end_date) then
    raise exception '跨年度请假请拆分为两张申请';
  end if;
  v_policy_id := app_private.hr_find_leave_policy(v_tenant_id, v_employee_id, v_leave_type_id, v_start_date);
  if v_policy_id is null then raise exception '当前员工没有匹配的生效休假政策'; end if;

  if p_id is not null and not exists (
    select 1 from public.hr_leave_request where id = p_id and tenant_id = v_tenant_id and status = 'draft'
  ) then raise exception '仅草稿申请允许编辑'; end if;

  insert into public.hr_leave_request(
    id, tenant_id, request_no, employee_id, leave_type_id, policy_id,
    start_date, end_date, start_session, end_session, requested_amount,
    unit_snapshot, reason, proof_urls, status
  ) values (
    coalesce(p_id, gen_random_uuid()), v_tenant_id,
    coalesce(nullif(p_payload->>'request_no', ''),
      'LR-' || to_char(clock_timestamp(), 'YYYYMMDDHH24MISSMS') || '-' ||
      upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 4))),
    v_employee_id, v_leave_type_id, v_policy_id, v_start_date, v_end_date,
    coalesce(p_payload->>'start_session', 'full'), coalesce(p_payload->>'end_session', 'full'),
    (p_payload->>'requested_amount')::numeric, v_leave_type.unit,
    btrim(p_payload->>'reason'), coalesce(p_payload->'proof_urls', '[]'::jsonb), 'draft'
  )
  on conflict (id) do update set
    employee_id = excluded.employee_id, leave_type_id = excluded.leave_type_id,
    policy_id = excluded.policy_id, start_date = excluded.start_date, end_date = excluded.end_date,
    start_session = excluded.start_session, end_session = excluded.end_session,
    requested_amount = excluded.requested_amount, unit_snapshot = excluded.unit_snapshot,
    reason = excluded.reason, proof_urls = excluded.proof_urls
  where public.hr_leave_request.tenant_id = v_tenant_id
    and public.hr_leave_request.status = 'draft'
  returning id into v_result_id;
  if v_result_id is null then raise exception '休假申请不存在或不可编辑'; end if;
  return v_result_id;
end;
$$;


ALTER FUNCTION "public"."hr_save_leave_request_secure"("p_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: hr_save_lifecycle_record_secure("text", "uuid", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_save_lifecycle_record_secure"("p_kind" "text", "p_id" "uuid", "p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_current_tenant uuid := app_private.current_user_tenant_id();
  v_tenant_id uuid;
  v_permission text := case when p_id is null then 'Hr:Lifecycle:Add' else 'Hr:Lifecycle:Edit' end;
  v_id uuid;
  v_case public.hr_lifecycle_case;
  v_template public.hr_lifecycle_template;
  v_handoff public.hr_recruitment_handoff;
  v_case_type text := nullif(p_payload ->> 'case_type', '');
  v_template_id uuid := nullif(p_payload ->> 'template_id', '')::uuid;
  v_handoff_id uuid := nullif(p_payload ->> 'handoff_id', '')::uuid;
  v_planned_date date := nullif(p_payload ->> 'planned_effective_date', '')::date;
begin
  if p_kind not in ('case', 'task', 'template', 'template_task') then raise exception '不支持的生命周期记录类型'; end if;
  if p_kind in ('template', 'template_task') then v_permission := 'Hr:Lifecycle:ManageTemplate'; end if;
  if not app_private.can_execute_business_action('HrLifecycle', v_permission, null, false) then
    raise exception '当前账号没有保存生命周期记录的权限' using errcode = '42501';
  end if;
  v_tenant_id := case when app_private.is_platform_super()
    then coalesce(nullif(p_payload ->> 'tenant_id', '')::uuid, v_current_tenant)
    else v_current_tenant end;

  if p_kind = 'case' then
    if v_planned_date is null then raise exception '计划生效日期不能为空'; end if;
    if v_handoff_id is not null then
      select * into v_handoff from public.hr_recruitment_handoff h
      where h.id = v_handoff_id and h.tenant_id = v_tenant_id and h.status = 'completed';
      if not found then raise exception '招聘交接不存在、未完成或不属于当前租户'; end if;
      v_case_type := 'onboarding';
    end if;
    if v_case_type not in ('onboarding', 'regularization', 'transfer', 'offboarding') then
      raise exception '事项类型无效';
    end if;
    if v_template_id is null then
      select t.id into v_template_id from public.hr_lifecycle_template t
      where t.tenant_id = v_tenant_id and t.case_type = v_case_type
        and t.status = 'active' and t.is_default
      order by t.update_time desc limit 1;
    end if;
    if v_template_id is not null then
      select * into v_template from public.hr_lifecycle_template t
      where t.id = v_template_id and t.tenant_id = v_tenant_id
        and t.case_type = v_case_type and t.status = 'active';
      if not found then raise exception '所选标准任务包不可用或与事项类型不匹配'; end if;
    end if;

    if p_id is null then
      insert into public.hr_lifecycle_case(
        tenant_id, case_no, employee_id, case_type, planned_effective_date, status,
        template_id, source_type, source_id, organization_id, position_id,
        owner_employee_id, buddy_employee_id, priority, execution_status, remark
      ) values (
        v_tenant_id,
        coalesce(nullif(btrim(p_payload ->> 'case_no'), ''), 'LC' || to_char(clock_timestamp(), 'YYYYMMDDHH24MISSMS')),
        coalesce(v_handoff.onboard_employee_id, nullif(p_payload ->> 'employee_id', '')::uuid),
        v_case_type, v_planned_date, 'draft', v_template_id,
        case when v_handoff_id is null then null else 'recruitment_handoff' end, v_handoff_id,
        coalesce(v_handoff.organization_id, nullif(p_payload ->> 'organization_id', '')::uuid),
        coalesce(v_handoff.position_id, nullif(p_payload ->> 'position_id', '')::uuid),
        coalesce(v_handoff.owner_employee_id, nullif(p_payload ->> 'owner_employee_id', '')::uuid),
        coalesce(v_handoff.buddy_employee_id, nullif(p_payload ->> 'buddy_employee_id', '')::uuid),
        coalesce(nullif(p_payload ->> 'priority', ''), 'normal'), 'planning',
        nullif(btrim(p_payload ->> 'remark'), '')
      ) returning id into v_id;
      if v_template_id is not null then
        insert into public.hr_lifecycle_task(
          tenant_id, lifecycle_case_id, template_task_id, task_type, task_name, description,
          owner_role, due_date, required, blocking, evidence_required, status, sort
        )
        select v_tenant_id, v_id, task.id, task.task_type, task.task_name, task.description,
          task.owner_role, v_planned_date + task.due_offset_days,
          task.required, task.blocking, task.evidence_required, 'pending', task.sort
        from public.hr_lifecycle_template_task task
        where task.template_id = v_template_id and task.tenant_id = v_tenant_id;
      end if;
      return v_id;
    end if;

    select * into v_case from public.hr_lifecycle_case c
    where c.id = p_id and c.tenant_id = v_tenant_id for update;
    if not found then raise exception '生命周期事项不存在或无权编辑'; end if;
    if v_case.execution_status <> 'planning' or v_case.status not in ('draft', 'rejected') then
      raise exception '只有待规划的草稿或已驳回事项可以编辑';
    end if;
    if v_handoff_id is distinct from v_case.source_id and v_case.source_id is not null then
      raise exception '已接收的招聘交接来源不能更换';
    end if;
    if v_template_id is distinct from v_case.template_id then
      delete from public.hr_lifecycle_task t
      where t.lifecycle_case_id = v_case.id and t.tenant_id = v_tenant_id
        and t.template_task_id is not null and t.status = 'pending';
    end if;
    update public.hr_lifecycle_case set
      case_no = coalesce(nullif(btrim(p_payload ->> 'case_no'), ''), case_no),
      employee_id = coalesce(v_handoff.onboard_employee_id, nullif(p_payload ->> 'employee_id', '')::uuid, employee_id),
      case_type = v_case_type, planned_effective_date = v_planned_date, template_id = v_template_id,
      organization_id = coalesce(v_handoff.organization_id, nullif(p_payload ->> 'organization_id', '')::uuid),
      position_id = coalesce(v_handoff.position_id, nullif(p_payload ->> 'position_id', '')::uuid),
      owner_employee_id = coalesce(v_handoff.owner_employee_id, nullif(p_payload ->> 'owner_employee_id', '')::uuid),
      buddy_employee_id = coalesce(v_handoff.buddy_employee_id, nullif(p_payload ->> 'buddy_employee_id', '')::uuid),
      priority = coalesce(nullif(p_payload ->> 'priority', ''), priority),
      remark = nullif(btrim(p_payload ->> 'remark'), '')
    where id = p_id;
    if v_template_id is distinct from v_case.template_id and v_template_id is not null then
      insert into public.hr_lifecycle_task(
        tenant_id, lifecycle_case_id, template_task_id, task_type, task_name, description,
        owner_role, due_date, required, blocking, evidence_required, status, sort
      )
      select v_tenant_id, p_id, task.id, task.task_type, task.task_name, task.description,
        task.owner_role, v_planned_date + task.due_offset_days,
        task.required, task.blocking, task.evidence_required, 'pending', task.sort
      from public.hr_lifecycle_template_task task
      where task.template_id = v_template_id and task.tenant_id = v_tenant_id;
    end if;
    return p_id;
  end if;

  if p_kind = 'task' then
    select c.* into v_case from public.hr_lifecycle_case c
    where c.id = nullif(p_payload ->> 'lifecycle_case_id', '')::uuid and c.tenant_id = v_tenant_id;
    if not found or v_case.execution_status in ('ready', 'completed', 'cancelled') then
      raise exception '所选事项不存在或已不允许维护任务';
    end if;
    if nullif(p_payload ->> 'due_date', '') is null then raise exception '任务截止日期不能为空'; end if;
    if p_id is null then
      insert into public.hr_lifecycle_task(
        tenant_id, lifecycle_case_id, task_type, task_name, description, owner_employee_id,
        owner_role, due_date, required, blocking, evidence_required, status, sort
      ) values (
        v_tenant_id, v_case.id, p_payload ->> 'task_type', btrim(p_payload ->> 'task_name'),
        nullif(btrim(p_payload ->> 'description'), ''), nullif(p_payload ->> 'owner_employee_id', '')::uuid,
        coalesce(nullif(p_payload ->> 'owner_role', ''), 'hr'), (p_payload ->> 'due_date')::date,
        coalesce((p_payload ->> 'required')::boolean, true),
        coalesce((p_payload ->> 'blocking')::boolean, true),
        coalesce((p_payload ->> 'evidence_required')::boolean, false), 'pending',
        coalesce((p_payload ->> 'sort')::integer, 0)
      ) returning id into v_id;
      return v_id;
    end if;
    update public.hr_lifecycle_task set
      lifecycle_case_id = v_case.id, task_type = p_payload ->> 'task_type',
      task_name = btrim(p_payload ->> 'task_name'), description = nullif(btrim(p_payload ->> 'description'), ''),
      owner_employee_id = nullif(p_payload ->> 'owner_employee_id', '')::uuid,
      owner_role = coalesce(nullif(p_payload ->> 'owner_role', ''), owner_role),
      due_date = (p_payload ->> 'due_date')::date,
      required = coalesce((p_payload ->> 'required')::boolean, required),
      blocking = coalesce((p_payload ->> 'blocking')::boolean, blocking),
      evidence_required = coalesce((p_payload ->> 'evidence_required')::boolean, evidence_required),
      sort = coalesce((p_payload ->> 'sort')::integer, sort)
    where id = p_id and tenant_id = v_tenant_id and status in ('pending', 'processing')
    returning id into v_id;
    if v_id is null then raise exception '任务不存在、已关闭或无权编辑'; end if;
    return v_id;
  end if;

  if p_kind = 'template' then
    if p_id is null then
      insert into public.hr_lifecycle_template(
        tenant_id, template_code, template_name, case_type, status, is_default, description
      ) values (
        v_tenant_id, btrim(p_payload ->> 'template_code'), btrim(p_payload ->> 'template_name'),
        p_payload ->> 'case_type', 'draft', coalesce((p_payload ->> 'is_default')::boolean, false),
        nullif(btrim(p_payload ->> 'description'), '')
      ) returning id into v_id;
      return v_id;
    end if;
    update public.hr_lifecycle_template set
      template_code = btrim(p_payload ->> 'template_code'),
      template_name = btrim(p_payload ->> 'template_name'),
      case_type = p_payload ->> 'case_type',
      is_default = coalesce((p_payload ->> 'is_default')::boolean, is_default),
      description = nullif(btrim(p_payload ->> 'description'), '')
    where id = p_id and tenant_id = v_tenant_id and status in ('draft', 'inactive')
    returning * into v_template;
    if not found then raise exception '任务包不存在、已启用或无权编辑'; end if;
    return p_id;
  end if;

  select template.* into v_template from public.hr_lifecycle_template template
  where template.id = nullif(p_payload ->> 'template_id', '')::uuid
    and template.tenant_id = v_tenant_id and template.status in ('draft', 'inactive');
  if not found then raise exception '只有草稿或停用任务包可以维护模板任务'; end if;
  if p_id is null then
    insert into public.hr_lifecycle_template_task(
      tenant_id, template_id, task_type, task_name, description, owner_role,
      due_offset_days, required, blocking, evidence_required, sort
    ) values (
      v_tenant_id, v_template.id, p_payload ->> 'task_type', btrim(p_payload ->> 'task_name'),
      nullif(btrim(p_payload ->> 'description'), ''), coalesce(nullif(p_payload ->> 'owner_role', ''), 'hr'),
      coalesce((p_payload ->> 'due_offset_days')::integer, 0),
      coalesce((p_payload ->> 'required')::boolean, true),
      coalesce((p_payload ->> 'blocking')::boolean, true),
      coalesce((p_payload ->> 'evidence_required')::boolean, false),
      coalesce((p_payload ->> 'sort')::integer, 0)
    ) returning id into v_id;
    return v_id;
  end if;
  update public.hr_lifecycle_template_task set
    template_id = v_template.id, task_type = p_payload ->> 'task_type',
    task_name = btrim(p_payload ->> 'task_name'), description = nullif(btrim(p_payload ->> 'description'), ''),
    owner_role = coalesce(nullif(p_payload ->> 'owner_role', ''), owner_role),
    due_offset_days = coalesce((p_payload ->> 'due_offset_days')::integer, due_offset_days),
    required = coalesce((p_payload ->> 'required')::boolean, required),
    blocking = coalesce((p_payload ->> 'blocking')::boolean, blocking),
    evidence_required = coalesce((p_payload ->> 'evidence_required')::boolean, evidence_required),
    sort = coalesce((p_payload ->> 'sort')::integer, sort)
  where id = p_id and tenant_id = v_tenant_id returning id into v_id;
  if v_id is null then raise exception '模板任务不存在或无权编辑'; end if;
  return v_id;
end
$$;


ALTER FUNCTION "public"."hr_save_lifecycle_record_secure"("p_kind" "text", "p_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: hr_save_organization_design_change_secure("uuid", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_save_organization_design_change_secure"("p_id" "uuid", "p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid:=app_private.current_user_tenant_id(); v_id uuid:=coalesce(p_id,gen_random_uuid());
  v_scenario public.hr_organization_design_scenario%rowtype; v_org public.mdm_organization%rowtype;
  v_existing public.hr_organization_design_change%rowtype;
  v_change_type text:=p_payload->>'change_type'; v_target_id uuid:=nullif(p_payload->>'organization_id','')::uuid;
  v_parent_id uuid:=nullif(p_payload->>'proposed_parent_id','')::uuid;
begin
  if auth.uid() is null or not app_private.can_execute_business_action(
    'HrOrganizationDesign','Hr:OrganizationDesign:Scenario:Manage',null,false
  ) then raise exception '当前账号没有管理组织变革草稿的权限' using errcode='42501'; end if;
  select * into v_scenario from public.hr_organization_design_scenario
  where id=(p_payload->>'scenario_id')::uuid and (app_private.is_platform_super() or tenant_id=v_tenant_id) for update;
  if not found then raise exception '组织变革方案不存在或不属于当前租户'; end if;
  v_tenant_id:=v_scenario.tenant_id;
  if v_scenario.status not in ('draft','rejected') then raise exception '仅草稿或被退回方案可调整变更项'; end if;
  if p_id is not null then
    select * into v_existing from public.hr_organization_design_change c
    where c.id=p_id and c.scenario_id=v_scenario.id and c.tenant_id=v_tenant_id for update;
    if not found then raise exception '组织变更项不存在或不属于当前方案'; end if;
  end if;
  if v_change_type not in ('create','rename','reparent','inactivate') then raise exception '不支持的组织变更类型'; end if;
  if v_change_type='create' then
    if v_target_id is not null then raise exception '新增组织不能绑定现有组织'; end if;
    if nullif(btrim(p_payload->>'proposed_code'),'') is null or nullif(btrim(p_payload->>'proposed_name'),'') is null
      or nullif(btrim(p_payload->>'proposed_type'),'') is null then raise exception '新增组织必须填写编码、名称和类型'; end if;
    if exists(select 1 from public.mdm_organization o where o.tenant_id=v_tenant_id and lower(o.organization_code)=lower(btrim(p_payload->>'proposed_code')))
      or exists(select 1 from public.hr_organization_design_change c where c.scenario_id=v_scenario.id and c.id<>v_id and c.change_type='create' and lower(c.proposed_code)=lower(btrim(p_payload->>'proposed_code')))
    then raise exception '组织编码已存在或在当前方案中重复'; end if;
  else
    select * into v_org from public.mdm_organization o where o.id=v_target_id and o.tenant_id=v_tenant_id;
    if not found then raise exception '目标组织不存在或不属于当前租户'; end if;
    if v_org.is_system then raise exception '系统根组织不能纳入组织变革方案'; end if;
    if v_change_type='rename' and nullif(btrim(p_payload->>'proposed_name'),'') is null then raise exception '组织更名必须填写新名称'; end if;
    if v_change_type='reparent' and v_parent_id is null then raise exception '组织迁移必须选择新上级'; end if;
    if v_change_type='reparent' and v_parent_id=v_target_id then raise exception '组织不能成为自己的上级'; end if;
    if v_change_type='reparent' and exists(
      with recursive descendants as (
        select o.id from public.mdm_organization o where o.id=v_target_id and o.tenant_id=v_tenant_id
        union all select child.id from public.mdm_organization child join descendants d on child.parent_id=d.id where child.tenant_id=v_tenant_id
      ) select 1 from descendants where id=v_parent_id and id<>v_target_id
    ) then raise exception '新上级不能位于目标组织的下级范围内'; end if;
  end if;
  if v_parent_id is not null and not exists(select 1 from public.mdm_organization o where o.id=v_parent_id and o.tenant_id=v_tenant_id and o.status='1')
    then raise exception '新上级组织不存在、已停用或不属于当前租户'; end if;

  insert into public.hr_organization_design_change(
    id,tenant_id,scenario_id,change_type,organization_id,current_parent_id,current_code,current_name,current_type,
    proposed_parent_id,proposed_code,proposed_name,proposed_type,proposed_status,rationale,sequence
  ) values (
    v_id,v_tenant_id,v_scenario.id,v_change_type,v_target_id,
    case when v_target_id is null then null else v_org.parent_id end,
    case when v_target_id is null then null else v_org.organization_code end,
    case when v_target_id is null then null else v_org.organization_name end,
    case when v_target_id is null then null else v_org.organization_type end,
    v_parent_id,nullif(btrim(p_payload->>'proposed_code'),''),nullif(btrim(p_payload->>'proposed_name'),''),
    nullif(btrim(p_payload->>'proposed_type'),''),
    case when v_change_type='inactivate' then '0' else nullif(p_payload->>'proposed_status','') end,
    btrim(p_payload->>'rationale'),coalesce(nullif(p_payload->>'sequence','')::integer,10)
  ) on conflict(id) do update set
    change_type=excluded.change_type,organization_id=excluded.organization_id,
    current_parent_id=excluded.current_parent_id,current_code=excluded.current_code,
    current_name=excluded.current_name,current_type=excluded.current_type,
    proposed_parent_id=excluded.proposed_parent_id,proposed_code=excluded.proposed_code,
    proposed_name=excluded.proposed_name,proposed_type=excluded.proposed_type,
    proposed_status=excluded.proposed_status,rationale=excluded.rationale,sequence=excluded.sequence,
    impacted_employee_count=0,impacted_position_count=0,impacted_requisition_count=0,
    impacted_security_user_count=0,impacted_scope_count=0,impact_captured_at=null;
  if v_scenario.status='rejected' then
    update public.hr_organization_design_scenario set status='draft',risk_level='unassessed',
      submission_note=null,decision_note=null,baseline_captured_at=null,submitted_at=null,submitted_by=null,
      decided_at=null,decided_by=null,version=version+1 where id=v_scenario.id;
  end if;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."hr_save_organization_design_change_secure"("p_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: hr_save_organization_design_scenario_secure("uuid", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_save_organization_design_scenario_secure"("p_id" "uuid", "p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_current_tenant uuid:=app_private.current_user_tenant_id();
  v_tenant_id uuid:=case when app_private.is_platform_super() and nullif(p_payload->>'tenant_id','') is not null then (p_payload->>'tenant_id')::uuid else v_current_tenant end;
  v_id uuid:=coalesce(p_id,gen_random_uuid()); v_existing public.hr_organization_design_scenario%rowtype;
begin
  if auth.uid() is null or not app_private.can_execute_business_action(
    'HrOrganizationDesign','Hr:OrganizationDesign:Scenario:Manage',null,false
  ) then raise exception '当前账号没有管理组织变革草稿的权限' using errcode='42501'; end if;
  if nullif(p_payload->>'owner_employee_id','') is not null and not exists(
    select 1 from public.mdm_employee e where e.id=(p_payload->>'owner_employee_id')::uuid and e.tenant_id=v_tenant_id
  ) then raise exception '方案负责人不存在或不属于当前租户'; end if;
  if p_id is null then
    insert into public.hr_organization_design_scenario(
      id,tenant_id,scenario_code,scenario_name,objective,effective_date,owner_employee_id
    ) values (
      v_id,v_tenant_id,btrim(p_payload->>'scenario_code'),btrim(p_payload->>'scenario_name'),
      btrim(p_payload->>'objective'),(p_payload->>'effective_date')::date,
      nullif(p_payload->>'owner_employee_id','')::uuid
    );
  else
    select * into v_existing from public.hr_organization_design_scenario
    where id=p_id and (app_private.is_platform_super() or tenant_id=v_current_tenant) for update;
    if not found then raise exception '组织变革方案不存在或不属于当前租户'; end if;
    if v_existing.status not in ('draft','rejected') then raise exception '当前状态的方案不可编辑'; end if;
    if coalesce(nullif(p_payload->>'version','')::integer,0)<>v_existing.version then
      raise exception '方案已被他人更新，请刷新后重试' using errcode='40001';
    end if;
    update public.hr_organization_design_scenario set
      scenario_code=btrim(p_payload->>'scenario_code'),scenario_name=btrim(p_payload->>'scenario_name'),
      objective=btrim(p_payload->>'objective'),effective_date=(p_payload->>'effective_date')::date,
      owner_employee_id=nullif(p_payload->>'owner_employee_id','')::uuid,status='draft',
      risk_level='unassessed',submission_note=null,decision_note=null,baseline_captured_at=null,
      submitted_at=null,submitted_by=null,decided_at=null,decided_by=null,version=version+1
    where id=p_id;
    update public.hr_organization_design_change set impact_captured_at=null,
      impacted_employee_count=0,impacted_position_count=0,impacted_requisition_count=0,
      impacted_security_user_count=0,impacted_scope_count=0 where scenario_id=p_id;
  end if;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."hr_save_organization_design_scenario_secure"("p_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: hr_save_performance_record_secure("text", "uuid", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_save_performance_record_secure"("p_kind" "text", "p_id" "uuid" DEFAULT NULL::"uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_permission text := case when p_id is null then 'Hr:Performance:Add' else 'Hr:Performance:Edit' end;
  v_cycle public.hr_performance_cycle%rowtype;
  v_review public.hr_performance_review%rowtype;
  v_goal public.hr_performance_goal%rowtype;
  v_check_in public.hr_performance_check_in%rowtype;
  v_session public.hr_performance_calibration_session%rowtype;
  v_item public.hr_performance_calibration_item%rowtype;
begin
  if p_kind not in ('cycle','review','goal','check_in','calibration','calibration_item') then
    raise exception '不支持的绩效记录类型';
  end if;
  if p_kind='calibration_item' then v_permission:='Hr:Performance:Calibrate'; end if;
  if not app_private.can_execute_business_action('HrPerformance',v_permission,null,false) then
    raise exception '当前账号没有执行该绩效操作的权限' using errcode='42501';
  end if;
  if app_private.is_platform_super() and nullif(p_payload->>'tenant_id','') is not null then
    v_tenant_id := (p_payload->>'tenant_id')::uuid;
  end if;

  if p_kind='cycle' then
    if p_id is not null then
      select * into v_cycle from public.hr_performance_cycle where id=p_id and tenant_id=v_tenant_id for update;
      if not found then raise exception '绩效周期不存在'; end if;
      if v_cycle.status<>'draft' then raise exception '只有草稿周期可以修改'; end if;
      update public.hr_performance_cycle set
        cycle_code=btrim(p_payload->>'cycle_code'), cycle_name=btrim(p_payload->>'cycle_name'),
        start_date=(p_payload->>'start_date')::date, end_date=(p_payload->>'end_date')::date,
        owner_employee_id=nullif(p_payload->>'owner_employee_id','')::uuid,
        check_in_frequency_days=coalesce((p_payload->>'check_in_frequency_days')::integer,30),
        self_review_due_date=nullif(p_payload->>'self_review_due_date','')::date,
        manager_review_due_date=nullif(p_payload->>'manager_review_due_date','')::date,
        calibration_due_date=nullif(p_payload->>'calibration_due_date','')::date,
        description=nullif(btrim(p_payload->>'description'),'')
      where id=p_id returning * into v_cycle;
    else
      insert into public.hr_performance_cycle(
        tenant_id,cycle_code,cycle_name,start_date,end_date,owner_employee_id,
        check_in_frequency_days,self_review_due_date,manager_review_due_date,calibration_due_date,status,description
      ) values (
        v_tenant_id,btrim(p_payload->>'cycle_code'),btrim(p_payload->>'cycle_name'),
        (p_payload->>'start_date')::date,(p_payload->>'end_date')::date,
        nullif(p_payload->>'owner_employee_id','')::uuid,
        coalesce((p_payload->>'check_in_frequency_days')::integer,30),
        nullif(p_payload->>'self_review_due_date','')::date,
        nullif(p_payload->>'manager_review_due_date','')::date,
        nullif(p_payload->>'calibration_due_date','')::date,'draft',nullif(btrim(p_payload->>'description'),'')
      ) returning * into v_cycle;
    end if;
    return v_cycle.id;
  end if;

  if p_kind='review' then
    select * into v_cycle from public.hr_performance_cycle
      where id=(p_payload->>'cycle_id')::uuid and tenant_id=v_tenant_id;
    if not found or v_cycle.status not in ('draft','active') then raise exception '只能在草稿或执行中的周期安排员工考核'; end if;
    if p_id is not null then
      select * into v_review from public.hr_performance_review where id=p_id and tenant_id=v_tenant_id for update;
      if not found then raise exception '员工考核不存在'; end if;
      if v_review.status<>'draft' then raise exception '只有目标设定阶段可以修改考核对象'; end if;
      update public.hr_performance_review set
        cycle_id=(p_payload->>'cycle_id')::uuid, employee_id=(p_payload->>'employee_id')::uuid,
        reviewer_employee_id=nullif(p_payload->>'reviewer_employee_id','')::uuid
      where id=p_id returning * into v_review;
    else
      insert into public.hr_performance_review(tenant_id,cycle_id,employee_id,reviewer_employee_id,status)
      values(v_tenant_id,(p_payload->>'cycle_id')::uuid,(p_payload->>'employee_id')::uuid,
        nullif(p_payload->>'reviewer_employee_id','')::uuid,'draft') returning * into v_review;
    end if;
    return v_review.id;
  end if;

  if p_kind='goal' then
    select r.* into v_review from public.hr_performance_review r
      where r.id=(p_payload->>'review_id')::uuid and r.tenant_id=v_tenant_id for update;
    if not found then raise exception '员工考核不存在'; end if;
    if v_review.status not in ('draft','self_review','manager_review') then raise exception '当前阶段不能修改绩效目标'; end if;
    if p_id is not null then
      select * into v_goal from public.hr_performance_goal where id=p_id and tenant_id=v_tenant_id for update;
      if not found or v_goal.review_id<>v_review.id then raise exception '绩效目标不存在'; end if;
      update public.hr_performance_goal set
        goal_name=case when v_review.status='draft' then btrim(p_payload->>'goal_name') else goal_name end,
        target_description=case when v_review.status='draft' then btrim(p_payload->>'target_description') else target_description end,
        goal_type=case when v_review.status='draft' then coalesce(nullif(p_payload->>'goal_type',''),'business') else goal_type end,
        weight=case when v_review.status='draft' then coalesce((p_payload->>'weight')::numeric,0) else weight end,
        due_date=case when v_review.status='draft' then nullif(p_payload->>'due_date','')::date else due_date end,
        progress_percent=coalesce((p_payload->>'progress_percent')::numeric,progress_percent),
        status=coalesce(nullif(p_payload->>'status',''),status),
        actual_result=nullif(btrim(p_payload->>'actual_result'),''),
        evidence_source=nullif(btrim(p_payload->>'evidence_source'),''),
        employee_score=case when v_review.status='self_review' then nullif(p_payload->>'employee_score','')::numeric else employee_score end,
        manager_score=case when v_review.status='manager_review' then nullif(p_payload->>'manager_score','')::numeric else manager_score end
      where id=p_id returning * into v_goal;
    else
      if v_review.status<>'draft' then raise exception '只能在目标设定阶段新增目标'; end if;
      insert into public.hr_performance_goal(
        tenant_id,review_id,goal_name,target_description,goal_type,weight,due_date,
        progress_percent,status,actual_result,evidence_source
      ) values (
        v_tenant_id,v_review.id,btrim(p_payload->>'goal_name'),btrim(p_payload->>'target_description'),
        coalesce(nullif(p_payload->>'goal_type',''),'business'),coalesce((p_payload->>'weight')::numeric,0),
        nullif(p_payload->>'due_date','')::date,coalesce((p_payload->>'progress_percent')::numeric,0),
        coalesce(nullif(p_payload->>'status',''),'draft'),nullif(btrim(p_payload->>'actual_result'),''),
        nullif(btrim(p_payload->>'evidence_source'),'')
      ) returning * into v_goal;
    end if;
    return v_goal.id;
  end if;

  if p_kind='check_in' then
    select * into v_review from public.hr_performance_review
      where id=(p_payload->>'review_id')::uuid and tenant_id=v_tenant_id for update;
    if not found or v_review.status not in ('self_review','manager_review') then
      raise exception '只有执行中的考核可以登记绩效沟通';
    end if;
    if p_id is null then
      insert into public.hr_performance_check_in(
        tenant_id,review_id,check_in_date,progress_percent,risk_status,achievement,blocker,
        next_action,manager_feedback,facilitator_employee_id
      ) values (
        v_tenant_id,v_review.id,coalesce(nullif(p_payload->>'check_in_date','')::date,current_date),
        coalesce((p_payload->>'progress_percent')::numeric,0),coalesce(nullif(p_payload->>'risk_status',''),'on_track'),
        nullif(btrim(p_payload->>'achievement'),''),nullif(btrim(p_payload->>'blocker'),''),
        btrim(p_payload->>'next_action'),nullif(btrim(p_payload->>'manager_feedback'),''),
        nullif(p_payload->>'facilitator_employee_id','')::uuid
      ) returning * into v_check_in;
    else
      update public.hr_performance_check_in set
        check_in_date=coalesce(nullif(p_payload->>'check_in_date','')::date,check_in_date),
        progress_percent=coalesce((p_payload->>'progress_percent')::numeric,progress_percent),
        risk_status=coalesce(nullif(p_payload->>'risk_status',''),risk_status),
        achievement=nullif(btrim(p_payload->>'achievement'),''), blocker=nullif(btrim(p_payload->>'blocker'),''),
        next_action=btrim(p_payload->>'next_action'),manager_feedback=nullif(btrim(p_payload->>'manager_feedback'),''),
        facilitator_employee_id=nullif(p_payload->>'facilitator_employee_id','')::uuid
      where id=p_id and tenant_id=v_tenant_id returning * into v_check_in;
      if not found or v_check_in.review_id<>v_review.id then raise exception '绩效沟通记录不存在'; end if;
    end if;
    update public.hr_performance_goal set progress_percent=v_check_in.progress_percent,
      status=case when v_check_in.progress_percent>=100 then 'completed'
        when v_check_in.risk_status='off_track' then 'at_risk' else 'in_progress' end
    where tenant_id=v_tenant_id and review_id=v_review.id and status<>'completed';
    return v_check_in.id;
  end if;

  if p_kind='calibration' then
    select * into v_cycle from public.hr_performance_cycle
      where id=(p_payload->>'cycle_id')::uuid and tenant_id=v_tenant_id;
    if not found or v_cycle.status not in ('active','reviewing') then raise exception '只能为执行或评议中的周期创建校准会议'; end if;
    if p_id is not null then
      select * into v_session from public.hr_performance_calibration_session where id=p_id and tenant_id=v_tenant_id for update;
      if not found then raise exception '绩效校准会议不存在'; end if;
      if v_session.status<>'setup' then raise exception '只有筹备中的校准会议可以修改'; end if;
      update public.hr_performance_calibration_session set
        session_no=btrim(p_payload->>'session_no'),session_name=btrim(p_payload->>'session_name'),
        cycle_id=v_cycle.id,organization_id=nullif(p_payload->>'organization_id','')::uuid,
        facilitator_employee_id=nullif(p_payload->>'facilitator_employee_id','')::uuid,
        scheduled_at=(p_payload->>'scheduled_at')::timestamptz,
        distribution_note=nullif(btrim(p_payload->>'distribution_note'),'')
      where id=p_id returning * into v_session;
    else
      insert into public.hr_performance_calibration_session(
        tenant_id,session_no,session_name,cycle_id,organization_id,facilitator_employee_id,
        scheduled_at,status,distribution_note
      ) values (
        v_tenant_id,btrim(p_payload->>'session_no'),btrim(p_payload->>'session_name'),v_cycle.id,
        nullif(p_payload->>'organization_id','')::uuid,nullif(p_payload->>'facilitator_employee_id','')::uuid,
        (p_payload->>'scheduled_at')::timestamptz,'setup',nullif(btrim(p_payload->>'distribution_note'),'')
      ) returning * into v_session;
    end if;
    return v_session.id;
  end if;

  if p_id is null then raise exception '校准评分只能修改现有记录'; end if;
  select i.* into v_item from public.hr_performance_calibration_item i
    join public.hr_performance_calibration_session s on s.id=i.session_id and s.tenant_id=i.tenant_id
    where i.id=p_id and i.tenant_id=v_tenant_id and s.status='in_progress' for update of i;
  if not found then raise exception '校准评分不存在或会议已结束'; end if;
  update public.hr_performance_calibration_item set
    calibrated_score=(p_payload->>'calibrated_score')::numeric,
    calibrated_level=coalesce(nullif(p_payload->>'calibrated_level',''),
      app_private.hr_performance_level_for_score((p_payload->>'calibrated_score')::numeric)),
    adjustment_reason=nullif(btrim(p_payload->>'adjustment_reason'),'')
  where id=p_id returning * into v_item;
  return v_item.id;
end
$$;


ALTER FUNCTION "public"."hr_save_performance_record_secure"("p_kind" "text", "p_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: hr_save_personnel_change_secure("jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_save_personnel_change_secure"("p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_id uuid:=nullif(p_payload->>'id','')::uuid;
  v_existing public.hr_personnel_change%rowtype;
  v_assignment public.mdm_employee_assignment%rowtype;
  v_employee public.mdm_employee%rowtype;
  v_position public.mdm_position%rowtype;
  v_profile public.mdm_job_profile%rowtype;
  v_grade public.mdm_grade%rowtype;
  v_tenant_id uuid:=app_private.resolve_mutation_tenant_id((select target.tenant_id from public.mdm_employee target where target.id = nullif(p_payload->>'employee_id','')::uuid));
  v_employee_id uuid:=nullif(p_payload->>'employee_id','')::uuid;
  v_change_type text:=nullif(btrim(p_payload->>'change_type'),'');
  v_effective_date date:=nullif(p_payload->>'effective_date','')::date;
  v_to_organization_id uuid:=nullif(p_payload->>'to_organization_id','')::uuid;
  v_to_position_id uuid:=nullif(p_payload->>'to_position_id','')::uuid;
  v_to_job_profile_id uuid:=nullif(p_payload->>'to_job_profile_id','')::uuid;
  v_to_grade_id uuid:=nullif(p_payload->>'to_grade_id','')::uuid;
  v_to_business_title text:=nullif(btrim(p_payload->>'to_business_title'),'');
  v_to_employment_status text:=nullif(btrim(p_payload->>'to_employment_status'),'');
  v_before jsonb;
  v_after jsonb;
begin
  if p_payload is null or jsonb_typeof(p_payload)<>'object' then raise exception '异动数据格式不正确'; end if;
  if v_id is null then
    if not app_private.can_execute_business_action('HrPersonnelChange','Hr:PersonnelChange:Add',null,false) then raise exception 'Missing personnel change create permission' using errcode='42501'; end if;
    select employee_row.* into v_employee from public.mdm_employee employee_row
    where employee_row.id=v_employee_id and employee_row.tenant_id=v_tenant_id and employee_row.employment_status<>'terminated'
    for update;
    if not found then raise exception '员工不存在、已离职或超出当前租户'; end if;
    select assignment_row.* into v_assignment from public.mdm_employee_assignment assignment_row
    where assignment_row.employee_id=v_employee_id and assignment_row.tenant_id=v_tenant_id and assignment_row.primary_assignment and assignment_row.effective_end is null
    for update;
    if not found then raise exception '员工没有当前有效的主任职记录'; end if;
    v_before:=app_private.hr_assignment_snapshot(v_assignment.id);
  else
    if not app_private.can_execute_business_action('HrPersonnelChange','Hr:PersonnelChange:Edit',null,false) then raise exception 'Missing personnel change edit permission' using errcode='42501'; end if;
    select * into v_existing from public.hr_personnel_change where id=v_id and tenant_id=v_tenant_id for update;
    if not found then raise exception '异动单不存在或无权编辑'; end if;
    if v_existing.status not in ('draft','rejected') then raise exception '仅草稿或已驳回异动单允许编辑'; end if;
    v_employee_id:=v_existing.employee_id;
    v_before:=v_existing.before_assignment_snapshot;
    select * into v_assignment from public.mdm_employee_assignment where id=v_existing.base_assignment_id;
    select * into v_employee from public.mdm_employee where id=v_employee_id and tenant_id=v_tenant_id;
  end if;

  if v_change_type not in ('regularization','transfer','position_change','promotion','demotion','suspension','reinstatement','termination') then raise exception '请选择有效的异动类型'; end if;
  if v_effective_date is null then raise exception '请选择生效日期'; end if;
  if nullif(btrim(p_payload->>'reason'),'') is null then raise exception '请填写异动原因'; end if;

  if v_to_position_id is not null then
    select * into v_position from public.mdm_position where id=v_to_position_id and tenant_id=v_tenant_id and enabled;
    if not found then raise exception '所选新岗位不可用'; end if;
    if v_position.organization_id is not null then v_to_organization_id:=v_position.organization_id; end if;
    v_to_job_profile_id:=v_position.job_profile_id;
    v_to_grade_id:=coalesce(v_to_grade_id,v_position.grade_id);
  end if;
  v_to_organization_id:=coalesce(v_to_organization_id,v_assignment.organization_id);
  v_to_position_id:=coalesce(v_to_position_id,v_assignment.position_id);
  v_to_job_profile_id:=coalesce(v_to_job_profile_id,v_assignment.job_profile_id);
  v_to_grade_id:=coalesce(v_to_grade_id,v_assignment.grade_id);
  v_to_business_title:=coalesce(v_to_business_title,v_assignment.business_title);
  v_to_employment_status:=coalesce(v_to_employment_status,v_employee.employment_status);

  if v_change_type='regularization' then v_to_employment_status:='active'; end if;
  if v_change_type='suspension' then v_to_employment_status:='leave'; end if;
  if v_change_type='reinstatement' then v_to_employment_status:='active'; end if;
  if v_change_type='termination' then v_to_employment_status:='terminated'; end if;
  if v_change_type in ('transfer','position_change') and nullif(p_payload->>'to_position_id','') is null then raise exception '调动或调岗必须选择新岗位'; end if;
  if v_change_type in ('promotion','demotion')
     and nullif(p_payload->>'to_position_id','') is null
     and nullif(p_payload->>'to_job_profile_id','') is null
     and nullif(p_payload->>'to_grade_id','') is null then raise exception '晋升或降职至少需要调整岗位、标准职务或职级'; end if;
  if not exists(select 1 from public.mdm_organization where id=v_to_organization_id and tenant_id=v_tenant_id and status='1') then raise exception '目标组织不可用'; end if;
  if not exists(select 1 from public.mdm_job_profile where id=v_to_job_profile_id and tenant_id=v_tenant_id and enabled) then raise exception '目标标准职务不可用'; end if;
  if v_to_grade_id is not null and not exists(select 1 from public.mdm_grade where id=v_to_grade_id and tenant_id=v_tenant_id and enabled) then raise exception '目标职级不可用'; end if;

  select * into v_position from public.mdm_position where id=v_to_position_id and tenant_id=v_tenant_id;
  select * into v_profile from public.mdm_job_profile where id=v_to_job_profile_id and tenant_id=v_tenant_id;
  if v_to_grade_id is not null then select * into v_grade from public.mdm_grade where id=v_to_grade_id and tenant_id=v_tenant_id; end if;
  v_after:=jsonb_build_object(
    'organizationId',v_to_organization_id,
    'organizationCode',(select organization_code from public.mdm_organization where id=v_to_organization_id),
    'organizationName',(select organization_name from public.mdm_organization where id=v_to_organization_id),
    'positionId',v_to_position_id,'positionCode',v_position.position_code,'positionName',v_position.position_name,
    'jobProfileId',v_to_job_profile_id,'jobCode',v_profile.job_code,'jobName',v_profile.job_name,
    'gradeId',v_to_grade_id,'gradeCode',v_grade.grade_code,'gradeName',v_grade.grade_name,
    'businessTitle',v_to_business_title,'employmentStatus',v_to_employment_status,
    'effectiveStart',v_effective_date,'fte',v_assignment.fte
  );

  if v_id is null then
    insert into public.hr_personnel_change(
      tenant_id,change_no,employee_id,change_type,effective_date,status,
      from_organization_id,to_organization_id,from_position_id,to_position_id,
      from_employment_status,to_employment_status,from_job_title,to_job_title,
      from_job_profile_id,to_job_profile_id,from_grade_id,to_grade_id,
      from_business_title,to_business_title,base_assignment_id,base_assignment_updated_at,
      before_assignment_snapshot,after_assignment_snapshot,reason,remark
    ) values(
      v_tenant_id,btrim(p_payload->>'change_no'),v_employee_id,v_change_type,v_effective_date,'draft',
      v_assignment.organization_id,v_to_organization_id,v_assignment.position_id,v_to_position_id,
      v_employee.employment_status,v_to_employment_status,v_before->>'jobName',v_after->>'jobName',
      v_assignment.job_profile_id,v_to_job_profile_id,v_assignment.grade_id,v_to_grade_id,
      v_assignment.business_title,v_to_business_title,v_assignment.id,v_assignment.update_time,
      v_before,v_after,btrim(p_payload->>'reason'),nullif(btrim(p_payload->>'remark'),'')
    ) returning id into v_id;
  else
    update public.hr_personnel_change set
      change_no=btrim(p_payload->>'change_no'),change_type=v_change_type,effective_date=v_effective_date,
      to_organization_id=v_to_organization_id,to_position_id=v_to_position_id,
      to_employment_status=v_to_employment_status,to_job_title=v_after->>'jobName',
      to_job_profile_id=v_to_job_profile_id,to_grade_id=v_to_grade_id,
      to_business_title=v_to_business_title,after_assignment_snapshot=v_after,
      reason=btrim(p_payload->>'reason'),remark=nullif(btrim(p_payload->>'remark'),'')
    where id=v_id;
  end if;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."hr_save_personnel_change_secure"("p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: hr_save_policy_document_secure("uuid", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_save_policy_document_secure"("p_id" "uuid", "p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_current_tenant uuid:=app_private.current_user_tenant_id();
  v_tenant_id uuid:=case when app_private.is_platform_super() and nullif(p_payload->>'tenant_id','') is not null then (p_payload->>'tenant_id')::uuid else v_current_tenant end;
  v_id uuid:=coalesce(p_id,gen_random_uuid());
  v_existing public.hr_policy_document%rowtype;
  v_supersedes public.hr_policy_document%rowtype;
begin
  if auth.uid() is null or not app_private.can_execute_business_action(
    'HrPolicyAcknowledgement','Hr:PolicyAcknowledgement:Policy:Manage',null,false
  ) then raise exception '当前账号没有管理政策草稿的权限' using errcode='42501'; end if;
  if nullif(p_payload->>'supersedes_policy_id','') is not null then
    select * into v_supersedes from public.hr_policy_document
    where id=(p_payload->>'supersedes_policy_id')::uuid and tenant_id=v_tenant_id;
    if not found then raise exception '被替代政策不存在或不属于当前租户'; end if;
    if lower(v_supersedes.policy_code)<>lower(btrim(p_payload->>'policy_code')) then
      raise exception '新版本与被替代政策的编码必须一致';
    end if;
  end if;
  if p_id is null then
    insert into public.hr_policy_document(
      id,tenant_id,policy_code,policy_title,category,version_no,effective_date,
      acknowledgement_due_days,audience_type,audience_organization_id,
      audience_employment_type,document_reference,content_summary,status,
      supersedes_policy_id,decision_note
    ) values (
      v_id,v_tenant_id,btrim(p_payload->>'policy_code'),btrim(p_payload->>'policy_title'),
      btrim(p_payload->>'category'),coalesce(nullif(p_payload->>'version_no','')::integer,1),
      (p_payload->>'effective_date')::date,
      coalesce(nullif(p_payload->>'acknowledgement_due_days','')::integer,7),
      coalesce(nullif(p_payload->>'audience_type',''),'all'),
      nullif(p_payload->>'audience_organization_id','')::uuid,
      nullif(btrim(p_payload->>'audience_employment_type'),''),
      btrim(p_payload->>'document_reference'),btrim(p_payload->>'content_summary'),
      'draft',nullif(p_payload->>'supersedes_policy_id','')::uuid,
      nullif(btrim(p_payload->>'decision_note'),'')
    );
  else
    select * into v_existing from public.hr_policy_document
    where id=p_id and (app_private.is_platform_super() or tenant_id=v_tenant_id) for update;
    if not found then raise exception '政策不存在或不属于当前租户'; end if;
    if v_existing.status<>'draft' then raise exception '已发布政策不可修改，请创建新版本'; end if;
    update public.hr_policy_document set
      policy_code=btrim(p_payload->>'policy_code'),policy_title=btrim(p_payload->>'policy_title'),
      category=btrim(p_payload->>'category'),version_no=(p_payload->>'version_no')::integer,
      effective_date=(p_payload->>'effective_date')::date,
      acknowledgement_due_days=(p_payload->>'acknowledgement_due_days')::integer,
      audience_type=p_payload->>'audience_type',
      audience_organization_id=nullif(p_payload->>'audience_organization_id','')::uuid,
      audience_employment_type=nullif(btrim(p_payload->>'audience_employment_type'),''),
      document_reference=btrim(p_payload->>'document_reference'),
      content_summary=btrim(p_payload->>'content_summary'),
      supersedes_policy_id=nullif(p_payload->>'supersedes_policy_id','')::uuid,
      decision_note=nullif(btrim(p_payload->>'decision_note'),'')
    where id=p_id;
  end if;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."hr_save_policy_document_secure"("p_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: hr_save_recruitment_record_secure("text", "uuid", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_save_recruitment_record_secure"("p_kind" "text", "p_id" "uuid" DEFAULT NULL::"uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := coalesce(nullif(p_payload ->> 'tenant_id', '')::uuid, app_private.current_user_tenant_id());
  v_id uuid := coalesce(p_id, gen_random_uuid());
  v_permission text;
  v_candidate public.hr_candidate;
  v_offer public.hr_recruitment_offer;
  v_requisition public.hr_recruitment_requisition;
  v_version integer;
  v_offer_no text;
begin
  if p_kind not in ('requisition', 'candidate', 'interview', 'offer', 'handoff', 'task') then
    raise exception '不支持的招聘记录类型';
  end if;
  v_permission := case p_kind
    when 'requisition' then case when p_id is null then 'Hr:Recruitment:Add' else 'Hr:Recruitment:Edit' end
    when 'candidate' then case when p_id is null then 'Hr:Recruitment:Add' else 'Hr:Recruitment:Edit' end
    when 'interview' then case when p_id is null then 'Hr:Recruitment:Interview:Add' else 'Hr:Recruitment:Interview:Edit' end
    when 'offer' then case when p_id is null then 'Hr:Recruitment:Offer:Add' else 'Hr:Recruitment:Offer:Edit' end
    when 'handoff' then case when p_id is null then 'Hr:Recruitment:Handoff:Add' else 'Hr:Recruitment:Handoff:Edit' end
    else 'Hr:Recruitment:Task:Manage'
  end;
  if not app_private.can_execute_business_action('HrRecruitment', v_permission, null, false) then
    raise exception '当前账号没有执行该招聘操作的权限' using errcode = '42501';
  end if;
  if not app_private.is_platform_super() then v_tenant_id := app_private.current_user_tenant_id(); end if;

  if p_kind = 'requisition' then
    if not exists (
      select 1 from public.mdm_organization o
      where o.id = (p_payload ->> 'organization_id')::uuid and o.tenant_id = v_tenant_id
    ) then raise exception '招聘组织不存在或不属于当前租户'; end if;
    if not exists (
      select 1 from public.mdm_position p
      where p.id = (p_payload ->> 'position_id')::uuid and p.tenant_id = v_tenant_id and p.enabled
    ) then raise exception '招聘岗位不存在、已停用或不属于当前租户'; end if;
    if p_id is not null and not exists (
      select 1 from public.hr_recruitment_requisition r
      where r.id = p_id and r.tenant_id = v_tenant_id and r.status in ('draft', 'rejected')
    ) then raise exception '只有草稿或已驳回的招聘需求可以编辑'; end if;
    insert into public.hr_recruitment_requisition(
      id, tenant_id, requisition_no, organization_id, position_id, opening_count,
      hired_count, expected_onboard_date, employment_type, status, reason, requirements
    ) values (
      v_id, v_tenant_id, upper(btrim(p_payload ->> 'requisition_no')),
      (p_payload ->> 'organization_id')::uuid, (p_payload ->> 'position_id')::uuid,
      greatest(coalesce((p_payload ->> 'opening_count')::integer, 1), 1),
      case when p_id is null then 0 else coalesce((select hired_count from public.hr_recruitment_requisition where id = p_id), 0) end,
      nullif(p_payload ->> 'expected_onboard_date', '')::date,
      coalesce(nullif(p_payload ->> 'employment_type', ''), 'full_time'),
      case when p_id is null then 'draft' else coalesce((select status from public.hr_recruitment_requisition where id = p_id), 'draft') end,
      btrim(p_payload ->> 'reason'), nullif(btrim(p_payload ->> 'requirements'), '')
    ) on conflict (id) do update set
      requisition_no = excluded.requisition_no,
      organization_id = excluded.organization_id,
      position_id = excluded.position_id,
      opening_count = excluded.opening_count,
      expected_onboard_date = excluded.expected_onboard_date,
      employment_type = excluded.employment_type,
      reason = excluded.reason,
      requirements = excluded.requirements
    where hr_recruitment_requisition.tenant_id = v_tenant_id;
    return v_id;
  end if;

  if p_kind = 'candidate' then
    select * into v_requisition from public.hr_recruitment_requisition
    where id = (p_payload ->> 'requisition_id')::uuid and tenant_id = v_tenant_id;
    if not found or v_requisition.status <> 'effective' then
      raise exception '候选人只能关联招聘中的有效需求';
    end if;
    if p_id is not null and not exists (
      select 1 from public.hr_candidate c where c.id = p_id and c.tenant_id = v_tenant_id
        and c.stage not in ('hired', 'rejected', 'withdrawn')
    ) then raise exception '已结束的候选人记录不能再编辑'; end if;
    insert into public.hr_candidate(
      id, tenant_id, requisition_id, candidate_name, phone, email, source, stage,
      expected_salary, resume_url, remark, consent_status, consent_at, retention_until
    ) values (
      v_id, v_tenant_id, v_requisition.id, btrim(p_payload ->> 'candidate_name'),
      nullif(btrim(p_payload ->> 'phone'), ''), nullif(lower(btrim(p_payload ->> 'email')), ''),
      coalesce(nullif(p_payload ->> 'source', ''), 'referral'), 'new',
      nullif(p_payload ->> 'expected_salary', '')::numeric,
      nullif(btrim(p_payload ->> 'resume_url'), ''), nullif(btrim(p_payload ->> 'remark'), ''),
      coalesce(nullif(p_payload ->> 'consent_status', ''), 'pending'),
      nullif(p_payload ->> 'consent_at', '')::timestamptz,
      nullif(p_payload ->> 'retention_until', '')::date
    ) on conflict (id) do update set
      requisition_id = excluded.requisition_id,
      candidate_name = excluded.candidate_name,
      phone = excluded.phone,
      email = excluded.email,
      source = excluded.source,
      expected_salary = excluded.expected_salary,
      resume_url = excluded.resume_url,
      remark = excluded.remark,
      consent_status = excluded.consent_status,
      consent_at = excluded.consent_at,
      retention_until = excluded.retention_until
    where hr_candidate.tenant_id = v_tenant_id;
    if p_id is null then
      insert into public.hr_candidate_stage_history(
        tenant_id, candidate_id, from_stage, to_stage, transition_reason, changed_by
      ) values (v_tenant_id, v_id, null, 'new', '创建候选人', coalesce(app_private.current_user_email(), 'system'));
    end if;
    return v_id;
  end if;

  if p_kind = 'interview' then
    select * into v_candidate from public.hr_candidate
    where id = (p_payload ->> 'candidate_id')::uuid and tenant_id = v_tenant_id;
    if not found or v_candidate.stage not in ('screening', 'interview') then
      raise exception '只有筛选中或面试中的候选人可以安排面试';
    end if;
    if not exists (
      select 1 from public.mdm_employee e
      where e.id = (p_payload ->> 'interviewer_employee_id')::uuid and e.tenant_id = v_tenant_id
        and e.employment_status in ('probation', 'active', 'leave')
    ) then raise exception '面试官不存在或不可用'; end if;
    if p_id is not null and not exists (
      select 1 from public.hr_recruitment_interview i
      where i.id = p_id and i.tenant_id = v_tenant_id and i.status = 'scheduled'
    ) then raise exception '只有待进行的面试可以调整'; end if;
    insert into public.hr_recruitment_interview(
      id, tenant_id, candidate_id, round_no, interview_type, scheduled_start_at,
      scheduled_end_at, location, interviewer_employee_id, status
    ) values (
      v_id, v_tenant_id, v_candidate.id, coalesce((p_payload ->> 'round_no')::integer, 1),
      coalesce(nullif(p_payload ->> 'interview_type', ''), 'structured'),
      (p_payload ->> 'scheduled_start_at')::timestamptz,
      (p_payload ->> 'scheduled_end_at')::timestamptz,
      nullif(btrim(p_payload ->> 'location'), ''),
      (p_payload ->> 'interviewer_employee_id')::uuid, 'scheduled'
    ) on conflict (id) do update set
      round_no = excluded.round_no,
      interview_type = excluded.interview_type,
      scheduled_start_at = excluded.scheduled_start_at,
      scheduled_end_at = excluded.scheduled_end_at,
      location = excluded.location,
      interviewer_employee_id = excluded.interviewer_employee_id
    where hr_recruitment_interview.tenant_id = v_tenant_id
      and hr_recruitment_interview.status = 'scheduled';
    if v_candidate.stage = 'screening' then
      perform app_private.hr_append_candidate_stage(v_candidate.id, 'interview', '已安排首轮面试');
    end if;
    return v_id;
  end if;

  if p_kind = 'offer' then
    select * into v_candidate from public.hr_candidate
    where id = (p_payload ->> 'candidate_id')::uuid and tenant_id = v_tenant_id;
    if not found or v_candidate.stage not in ('interview', 'offer') then
      raise exception '只有面试中或 Offer 阶段的候选人可以创建 Offer';
    end if;
    if p_id is not null and not exists (
      select 1 from public.hr_recruitment_offer o
      where o.id = p_id and o.tenant_id = v_tenant_id and o.status in ('draft', 'rejected')
    ) then raise exception '只有草稿或已驳回的 Offer 可以编辑'; end if;
    select coalesce(max(version_no), 0) + 1 into v_version
    from public.hr_recruitment_offer where candidate_id = v_candidate.id and tenant_id = v_tenant_id;
    v_offer_no := coalesce(
      nullif(upper(btrim(p_payload ->> 'offer_no')), ''),
      'OFF-' || to_char(clock_timestamp(), 'YYYYMMDDHH24MISS') || '-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 6))
    );
    insert into public.hr_recruitment_offer(
      id, tenant_id, candidate_id, offer_no, version_no, employment_type,
      monthly_salary, target_bonus, currency, probation_months,
      proposed_onboard_date, expires_on, status
    ) values (
      v_id, v_tenant_id, v_candidate.id, v_offer_no,
      case when p_id is null then v_version else coalesce((select version_no from public.hr_recruitment_offer where id = p_id), v_version) end,
      coalesce(nullif(p_payload ->> 'employment_type', ''), 'full_time'),
      (p_payload ->> 'monthly_salary')::numeric,
      coalesce(nullif(p_payload ->> 'target_bonus', '')::numeric, 0),
      upper(coalesce(nullif(p_payload ->> 'currency', ''), 'CNY')),
      coalesce((p_payload ->> 'probation_months')::integer, 3),
      (p_payload ->> 'proposed_onboard_date')::date,
      (p_payload ->> 'expires_on')::date,
      case when p_id is null then 'draft' else coalesce((select status from public.hr_recruitment_offer where id = p_id), 'draft') end
    ) on conflict (id) do update set
      offer_no = excluded.offer_no,
      employment_type = excluded.employment_type,
      monthly_salary = excluded.monthly_salary,
      target_bonus = excluded.target_bonus,
      currency = excluded.currency,
      probation_months = excluded.probation_months,
      proposed_onboard_date = excluded.proposed_onboard_date,
      expires_on = excluded.expires_on
    where hr_recruitment_offer.tenant_id = v_tenant_id
      and hr_recruitment_offer.status in ('draft', 'rejected');
    return v_id;
  end if;

  if p_kind = 'handoff' then
    select * into v_offer from public.hr_recruitment_offer
    where id = (p_payload ->> 'offer_id')::uuid and tenant_id = v_tenant_id;
    if not found or v_offer.status <> 'accepted' then raise exception '仅已接受的 Offer 可以建立入职交接'; end if;
    select r.* into v_requisition
    from public.hr_candidate c
    join public.hr_recruitment_requisition r on r.id = c.requisition_id and r.tenant_id = c.tenant_id
    where c.id = v_offer.candidate_id and c.tenant_id = v_tenant_id;
    if p_id is not null and not exists (
      select 1 from public.hr_recruitment_handoff h
      where h.id = p_id and h.tenant_id = v_tenant_id and h.status in ('pending', 'ready')
    ) then raise exception '已结束的入职交接不能编辑'; end if;
    insert into public.hr_recruitment_handoff(
      id, tenant_id, candidate_id, offer_id, organization_id, position_id,
      planned_onboard_date, owner_employee_id, buddy_employee_id, onboard_employee_id,
      status, handoff_note
    ) values (
      v_id, v_tenant_id, v_offer.candidate_id, v_offer.id,
      v_requisition.organization_id, v_requisition.position_id,
      coalesce(nullif(p_payload ->> 'planned_onboard_date', '')::date, v_offer.proposed_onboard_date),
      nullif(p_payload ->> 'owner_employee_id', '')::uuid,
      nullif(p_payload ->> 'buddy_employee_id', '')::uuid,
      nullif(p_payload ->> 'onboard_employee_id', '')::uuid,
      'pending', nullif(btrim(p_payload ->> 'handoff_note'), '')
    ) on conflict (id) do update set
      planned_onboard_date = excluded.planned_onboard_date,
      owner_employee_id = excluded.owner_employee_id,
      buddy_employee_id = excluded.buddy_employee_id,
      onboard_employee_id = excluded.onboard_employee_id,
      handoff_note = excluded.handoff_note
    where hr_recruitment_handoff.tenant_id = v_tenant_id
      and hr_recruitment_handoff.status in ('pending', 'ready');
    return v_id;
  end if;

  if not exists (
    select 1 from public.hr_recruitment_handoff h
    where h.id = (p_payload ->> 'handoff_id')::uuid and h.tenant_id = v_tenant_id
      and h.status in ('pending', 'ready')
  ) then raise exception '入职交接不存在或已结束'; end if;
  if p_id is not null and not exists (
    select 1 from public.hr_recruitment_onboarding_task t
    where t.id = p_id and t.tenant_id = v_tenant_id and t.status in ('pending', 'in_progress')
  ) then raise exception '已完成或跳过的入职任务不能编辑'; end if;
  insert into public.hr_recruitment_onboarding_task(
    id, tenant_id, handoff_id, task_category, task_title, task_description,
    owner_employee_id, due_date, status
  ) values (
    v_id, v_tenant_id, (p_payload ->> 'handoff_id')::uuid,
    p_payload ->> 'task_category', btrim(p_payload ->> 'task_title'),
    nullif(btrim(p_payload ->> 'task_description'), ''),
    nullif(p_payload ->> 'owner_employee_id', '')::uuid,
    (p_payload ->> 'due_date')::date,
    coalesce(nullif(p_payload ->> 'status', ''), 'pending')
  ) on conflict (id) do update set
    task_category = excluded.task_category,
    task_title = excluded.task_title,
    task_description = excluded.task_description,
    owner_employee_id = excluded.owner_employee_id,
    due_date = excluded.due_date,
    status = excluded.status
  where hr_recruitment_onboarding_task.tenant_id = v_tenant_id
    and hr_recruitment_onboarding_task.status in ('pending', 'in_progress');
  return v_id;
end
$$;


ALTER FUNCTION "public"."hr_save_recruitment_record_secure"("p_kind" "text", "p_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: hr_save_service_catalog_secure("uuid", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_save_service_catalog_secure"("p_id" "uuid" DEFAULT NULL::"uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_record public.hr_service_catalog;
  v_tenant_id uuid := app_private.current_user_tenant_id();
begin
  if not app_private.can_execute_business_action(
    'HrSelfService', 'Hr:SelfService:Catalog:Manage', null, false
  ) then
    raise exception '当前账号没有维护员工服务目录的权限' using errcode = '42501';
  end if;
  if app_private.is_platform_super() then
    v_tenant_id := coalesce(nullif(p_payload->>'tenant_id', '')::uuid, v_tenant_id);
  end if;

  if nullif(btrim(p_payload->>'service_code'), '') is null
    or nullif(btrim(p_payload->>'service_name'), '') is null
    or nullif(btrim(p_payload->>'category'), '') is null then
    raise exception '服务编码、服务名称和服务类别不能为空';
  end if;

  if p_id is null then
    insert into public.hr_service_catalog(
      tenant_id, service_code, service_name, category, description, service_mode,
      route_path, routing_group, first_response_hours, resolution_hours, enabled, sort
    ) values (
      v_tenant_id, upper(btrim(p_payload->>'service_code')), btrim(p_payload->>'service_name'),
      p_payload->>'category', nullif(btrim(p_payload->>'description'), ''),
      coalesce(nullif(p_payload->>'service_mode', ''), 'case'),
      nullif(btrim(p_payload->>'route_path'), ''), nullif(btrim(p_payload->>'routing_group'), ''),
      coalesce((p_payload->>'first_response_hours')::integer, 8),
      coalesce((p_payload->>'resolution_hours')::integer, 40),
      coalesce((p_payload->>'enabled')::boolean, true),
      coalesce((p_payload->>'sort')::integer, 0)
    ) returning * into v_record;
  else
    select * into v_record from public.hr_service_catalog where id = p_id for update;
    if not found or (
      not app_private.is_platform_super() and v_record.tenant_id <> v_tenant_id
    ) then
      raise exception '员工服务目录记录不存在或无权维护' using errcode = '42501';
    end if;
    update public.hr_service_catalog
    set service_code = upper(btrim(p_payload->>'service_code')),
        service_name = btrim(p_payload->>'service_name'),
        category = p_payload->>'category',
        description = nullif(btrim(p_payload->>'description'), ''),
        service_mode = coalesce(nullif(p_payload->>'service_mode', ''), 'case'),
        route_path = nullif(btrim(p_payload->>'route_path'), ''),
        routing_group = nullif(btrim(p_payload->>'routing_group'), ''),
        first_response_hours = coalesce((p_payload->>'first_response_hours')::integer, 8),
        resolution_hours = coalesce((p_payload->>'resolution_hours')::integer, 40),
        enabled = coalesce((p_payload->>'enabled')::boolean, true),
        sort = coalesce((p_payload->>'sort')::integer, 0)
    where id = p_id returning * into v_record;
  end if;
  return v_record.id;
exception
  when unique_violation then
    raise exception '同一租户下服务编码不能重复';
end
$$;


ALTER FUNCTION "public"."hr_save_service_catalog_secure"("p_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: hr_save_service_request_secure("uuid", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_save_service_request_secure"("p_id" "uuid" DEFAULT NULL::"uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_record public.hr_self_service_request;
  v_service public.hr_service_catalog;
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_employee_id uuid := app_private.hr_current_employee_id();
  v_manage boolean := app_private.is_platform_super()
    or app_private.has_permission('Hr:SelfService:Manage');
begin
  if p_id is null then
    if not app_private.can_execute_business_action(
      'HrSelfService', 'Hr:SelfService:Add', null, false
    ) then
      raise exception '当前账号没有创建员工服务工单的权限' using errcode = '42501';
    end if;
    if app_private.is_platform_super() then
      v_tenant_id := coalesce(nullif(p_payload->>'tenant_id', '')::uuid, v_tenant_id);
    end if;
    if v_manage and nullif(p_payload->>'employee_id', '') is not null then
      v_employee_id := (p_payload->>'employee_id')::uuid;
    end if;
  else
    if not app_private.can_execute_business_action(
      'HrSelfService', 'Hr:SelfService:Edit', null, false
    ) then
      raise exception '当前账号没有编辑员工服务工单的权限' using errcode = '42501';
    end if;
    select * into v_record from public.hr_self_service_request where id = p_id for update;
    if not found or not app_private.hr_service_case_visible(
      v_record.tenant_id, v_record.employee_id
    ) then
      raise exception '员工服务工单不存在或无权编辑' using errcode = '42501';
    end if;
    if v_record.status <> 'draft' then
      raise exception '仅草稿工单可以编辑';
    end if;
    v_tenant_id := v_record.tenant_id;
    v_employee_id := v_record.employee_id;
  end if;

  if v_employee_id is null then
    raise exception '当前账号未关联员工档案，无法创建服务工单';
  end if;
  if nullif(p_payload->>'service_id', '') is null
    or nullif(btrim(p_payload->>'request_no'), '') is null
    or nullif(btrim(p_payload->>'title'), '') is null
    or nullif(btrim(p_payload->>'reason'), '') is null then
    raise exception '服务项目、工单编号、主题和问题说明不能为空';
  end if;

  select * into v_service from public.hr_service_catalog
  where id = (p_payload->>'service_id')::uuid and tenant_id = v_tenant_id and enabled;
  if not found then raise exception '所选员工服务不存在或已停用'; end if;
  if v_service.service_mode <> 'case' then raise exception '跳转型服务不能创建工单'; end if;

  if p_id is null then
    insert into public.hr_self_service_request(
      tenant_id, request_no, employee_id, request_type, title, reason, request_data,
      status, service_id, priority, channel, attachment_urls, last_activity_at
    ) values (
      v_tenant_id, btrim(p_payload->>'request_no'), v_employee_id, v_service.category,
      btrim(p_payload->>'title'), btrim(p_payload->>'reason'), '{}'::jsonb,
      'draft', v_service.id, coalesce(nullif(p_payload->>'priority', ''), 'normal'),
      case when v_manage then coalesce(nullif(p_payload->>'channel', ''), 'agent')
        else 'self_service' end,
      coalesce(p_payload->'attachment_urls', '[]'::jsonb), now()
    ) returning * into v_record;
    perform app_private.hr_add_service_event(
      v_record, 'created', null, 'draft', '创建服务工单',
      jsonb_build_object('service_id', v_service.id)
    );
  else
    update public.hr_self_service_request
    set service_id = v_service.id,
        request_type = v_service.category,
        request_no = btrim(p_payload->>'request_no'),
        title = btrim(p_payload->>'title'),
        reason = btrim(p_payload->>'reason'),
        priority = coalesce(nullif(p_payload->>'priority', ''), 'normal'),
        channel = case when v_manage then coalesce(nullif(p_payload->>'channel', ''), channel)
          else channel end,
        attachment_urls = coalesce(p_payload->'attachment_urls', '[]'::jsonb),
        last_activity_at = now()
    where id = p_id returning * into v_record;
    perform app_private.hr_add_service_event(v_record, 'updated', 'draft', 'draft', '更新工单信息');
  end if;

  return v_record.id;
exception
  when unique_violation then
    raise exception '员工服务工单编号不能重复';
end
$$;


ALTER FUNCTION "public"."hr_save_service_request_secure"("p_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: hr_save_succession_action_secure("uuid", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_save_succession_action_secure"("p_id" "uuid" DEFAULT NULL::"uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_tenant_id uuid:=coalesce(nullif(p_payload->>'tenant_id','')::uuid,app_private.current_user_tenant_id()); v_id uuid:=coalesce(p_id,gen_random_uuid()); v_permission text:=case when p_id is null then 'Hr:Succession:Action:Add' else 'Hr:Succession:Action:Edit' end; v_status text:=coalesce(p_payload->>'status','planned');
begin
  if not app_private.can_execute_business_action('HrSuccession',v_permission,null,false) then raise exception 'Missing succession action permission' using errcode='42501'; end if;
  if not app_private.is_platform_super() then v_tenant_id:=app_private.current_user_tenant_id(); end if;
  if not exists(select 1 from public.hr_succession_candidate where id=(p_payload->>'candidate_id')::uuid and tenant_id=v_tenant_id) then raise exception '继任候选人不存在或不属于当前租户'; end if;
  insert into public.hr_succession_development_action(id,tenant_id,candidate_id,action_type,action_title,action_description,owner_employee_id,start_date,due_date,status,completion_date,outcome)
  values(v_id,v_tenant_id,(p_payload->>'candidate_id')::uuid,p_payload->>'action_type',btrim(p_payload->>'action_title'),nullif(btrim(p_payload->>'action_description'),''),nullif(p_payload->>'owner_employee_id','')::uuid,coalesce(nullif(p_payload->>'start_date','')::date,current_date),(p_payload->>'due_date')::date,v_status,case when v_status='completed' then coalesce(nullif(p_payload->>'completion_date','')::date,current_date) else null end,case when v_status='completed' then nullif(btrim(p_payload->>'outcome'),'') else null end)
  on conflict(id) do update set candidate_id=excluded.candidate_id,action_type=excluded.action_type,action_title=excluded.action_title,action_description=excluded.action_description,owner_employee_id=excluded.owner_employee_id,start_date=excluded.start_date,due_date=excluded.due_date,status=excluded.status,completion_date=excluded.completion_date,outcome=excluded.outcome
  where hr_succession_development_action.tenant_id=v_tenant_id;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."hr_save_succession_action_secure"("p_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: hr_save_succession_candidate_secure("uuid", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_save_succession_candidate_secure"("p_id" "uuid" DEFAULT NULL::"uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_tenant_id uuid:=coalesce(nullif(p_payload->>'tenant_id','')::uuid,app_private.current_user_tenant_id()); v_id uuid:=coalesce(p_id,gen_random_uuid()); v_permission text:=case when p_id is null then 'Hr:Succession:Candidate:Add' else 'Hr:Succession:Candidate:Edit' end; v_plan_position uuid;
begin
  if not app_private.can_execute_business_action('HrSuccession',v_permission,null,false) then raise exception 'Missing succession candidate permission' using errcode='42501'; end if;
  if not app_private.is_platform_super() then v_tenant_id:=app_private.current_user_tenant_id(); end if;
  select position_id into v_plan_position from public.hr_succession_plan where id=(p_payload->>'plan_id')::uuid and tenant_id=v_tenant_id;
  if v_plan_position is null then raise exception '继任计划不存在或不属于当前租户'; end if;
  if not exists(select 1 from public.mdm_employee where id=(p_payload->>'employee_id')::uuid and tenant_id=v_tenant_id) then raise exception '员工不存在或不属于当前租户'; end if;
  if exists(select 1 from public.mdm_employee where id=(p_payload->>'employee_id')::uuid and position_id=v_plan_position) then raise exception '当前岗位任职者不能作为同一岗位的继任候选人'; end if;
  insert into public.hr_succession_candidate(id,tenant_id,plan_id,employee_id,readiness,potential_level,retention_risk,priority,nomination_source,aspiration_confirmed,mobility_scope,strengths,development_gaps,review_comment,status,nominated_on,last_reviewed_on)
  values(v_id,v_tenant_id,(p_payload->>'plan_id')::uuid,(p_payload->>'employee_id')::uuid,p_payload->>'readiness',p_payload->>'potential_level',p_payload->>'retention_risk',coalesce((p_payload->>'priority')::integer,1),coalesce(p_payload->>'nomination_source','talent_review'),coalesce((p_payload->>'aspiration_confirmed')::boolean,false),nullif(btrim(p_payload->>'mobility_scope'),''),nullif(btrim(p_payload->>'strengths'),''),nullif(btrim(p_payload->>'development_gaps'),''),nullif(btrim(p_payload->>'review_comment'),''),coalesce(p_payload->>'status','nominated'),coalesce(nullif(p_payload->>'nominated_on','')::date,current_date),nullif(p_payload->>'last_reviewed_on','')::date)
  on conflict(id) do update set plan_id=excluded.plan_id,employee_id=excluded.employee_id,readiness=excluded.readiness,potential_level=excluded.potential_level,retention_risk=excluded.retention_risk,priority=excluded.priority,nomination_source=excluded.nomination_source,aspiration_confirmed=excluded.aspiration_confirmed,mobility_scope=excluded.mobility_scope,strengths=excluded.strengths,development_gaps=excluded.development_gaps,review_comment=excluded.review_comment,status=excluded.status,nominated_on=excluded.nominated_on,last_reviewed_on=excluded.last_reviewed_on
  where hr_succession_candidate.tenant_id=v_tenant_id;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."hr_save_succession_candidate_secure"("p_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: hr_save_succession_plan_secure("uuid", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_save_succession_plan_secure"("p_id" "uuid" DEFAULT NULL::"uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_tenant_id uuid:=coalesce(nullif(p_payload->>'tenant_id','')::uuid,app_private.current_user_tenant_id()); v_id uuid:=coalesce(p_id,gen_random_uuid()); v_permission text:=case when p_id is null then 'Hr:Succession:Plan:Add' else 'Hr:Succession:Plan:Edit' end;
begin
  if not app_private.can_execute_business_action('HrSuccession',v_permission,null,false) then raise exception 'Missing succession plan permission' using errcode='42501'; end if;
  if not app_private.is_platform_super() then v_tenant_id:=app_private.current_user_tenant_id(); end if;
  if not exists(select 1 from public.mdm_position where id=(p_payload->>'position_id')::uuid and tenant_id=v_tenant_id) then raise exception '岗位不存在或不属于当前租户'; end if;
  insert into public.hr_succession_plan(id,tenant_id,plan_code,position_id,plan_name,criticality,vacancy_risk,business_impact,target_successors,review_cycle_months,next_review_date,owner_employee_id,status,notes)
  values(v_id,v_tenant_id,upper(btrim(p_payload->>'plan_code')),(p_payload->>'position_id')::uuid,btrim(p_payload->>'plan_name'),p_payload->>'criticality',p_payload->>'vacancy_risk',p_payload->>'business_impact',coalesce((p_payload->>'target_successors')::integer,2),coalesce((p_payload->>'review_cycle_months')::integer,6),(p_payload->>'next_review_date')::date,nullif(p_payload->>'owner_employee_id','')::uuid,coalesce(p_payload->>'status','draft'),nullif(btrim(p_payload->>'notes'),''))
  on conflict(id) do update set plan_code=excluded.plan_code,position_id=excluded.position_id,plan_name=excluded.plan_name,criticality=excluded.criticality,vacancy_risk=excluded.vacancy_risk,business_impact=excluded.business_impact,target_successors=excluded.target_successors,review_cycle_months=excluded.review_cycle_months,next_review_date=excluded.next_review_date,owner_employee_id=excluded.owner_employee_id,status=excluded.status,notes=excluded.notes
  where hr_succession_plan.tenant_id=v_tenant_id;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."hr_save_succession_plan_secure"("p_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: hr_save_workforce_record_secure("text", "uuid", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_save_workforce_record_secure"("p_kind" "text", "p_id" "uuid" DEFAULT NULL::"uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_permission text;
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_cycle public.hr_workforce_plan_cycle%rowtype;
  v_line public.hr_workforce_plan_line%rowtype;
  v_position public.mdm_position%rowtype;
  v_baseline integer;
  v_effective public.hr_position_headcount%rowtype;
begin
  if p_kind not in ('cycle','line','effective') then raise exception '不支持的人力规划记录类型'; end if;
  v_permission := case when p_id is null then 'Hr:Headcount:Add' else 'Hr:Headcount:Edit' end;
  if not app_private.can_execute_business_action('HrHeadcount', v_permission, null, false) then
    raise exception '当前账号没有维护人力规划的权限' using errcode = '42501';
  end if;
  if app_private.is_platform_super() and nullif(p_payload->>'tenant_id','') is not null then
    v_tenant_id := (p_payload->>'tenant_id')::uuid;
  end if;
  if v_tenant_id is null then raise exception '缺少所属租户'; end if;

  if p_kind = 'cycle' then
    if p_id is not null then
      select * into v_cycle from public.hr_workforce_plan_cycle where id = p_id for update;
      if not found then raise exception '人力规划周期不存在'; end if;
      if not app_private.is_platform_super() and v_cycle.tenant_id <> v_tenant_id then raise exception '无权维护其他租户数据'; end if;
      if v_cycle.status <> 'draft' then raise exception '仅草稿规划可以编辑'; end if;
      update public.hr_workforce_plan_cycle set
        plan_no = btrim(p_payload->>'plan_no'), plan_name = btrim(p_payload->>'plan_name'),
        scenario = coalesce(nullif(p_payload->>'scenario',''), scenario),
        period_start = (p_payload->>'period_start')::date,
        period_end = (p_payload->>'period_end')::date,
        baseline_date = coalesce(nullif(p_payload->>'baseline_date','')::date, baseline_date),
        owner_employee_id = nullif(p_payload->>'owner_employee_id','')::uuid,
        budget_amount = nullif(p_payload->>'budget_amount','')::numeric,
        currency_code = coalesce(nullif(upper(p_payload->>'currency_code'),''), currency_code),
        objective = nullif(btrim(p_payload->>'objective'),''),
        assumptions = nullif(btrim(p_payload->>'assumptions'),''),
        remark = nullif(btrim(p_payload->>'remark'),'')
      where id = p_id returning * into v_cycle;
      return v_cycle.id;
    end if;
    insert into public.hr_workforce_plan_cycle(
      tenant_id, plan_no, plan_name, scenario, period_start, period_end, baseline_date,
      owner_employee_id, budget_amount, currency_code, objective, assumptions, remark
    ) values (
      v_tenant_id, btrim(p_payload->>'plan_no'), btrim(p_payload->>'plan_name'),
      coalesce(nullif(p_payload->>'scenario',''),'baseline'),
      (p_payload->>'period_start')::date, (p_payload->>'period_end')::date,
      coalesce(nullif(p_payload->>'baseline_date','')::date,current_date),
      nullif(p_payload->>'owner_employee_id','')::uuid,
      nullif(p_payload->>'budget_amount','')::numeric,
      coalesce(nullif(upper(p_payload->>'currency_code'),''),'CNY'),
      nullif(btrim(p_payload->>'objective'),''), nullif(btrim(p_payload->>'assumptions'),''),
      nullif(btrim(p_payload->>'remark'),'')
    ) returning * into v_cycle;
    return v_cycle.id;
  end if;

  if p_kind = 'line' then
    select * into v_cycle from public.hr_workforce_plan_cycle
    where id = (p_payload->>'plan_id')::uuid for update;
    if not found then raise exception '所属人力规划周期不存在'; end if;
    if not app_private.is_platform_super() and v_cycle.tenant_id <> v_tenant_id then raise exception '无权维护其他租户数据'; end if;
    if v_cycle.status <> 'draft' then raise exception '仅草稿规划可以维护岗位需求'; end if;
    v_tenant_id := v_cycle.tenant_id;
    select * into v_position from public.mdm_position
    where id = (p_payload->>'position_id')::uuid and tenant_id = v_tenant_id;
    if not found or not v_position.enabled then raise exception '所选岗位不存在或已停用'; end if;
    if v_position.organization_id <> (p_payload->>'organization_id')::uuid then
      raise exception '岗位与组织不匹配';
    end if;
    select count(*)::integer into v_baseline from public.mdm_employee_assignment a
    where a.tenant_id = v_tenant_id and a.position_id = v_position.id and a.primary_assignment
      and a.effective_end is null and a.assignment_status <> 'ended';
    if nullif(p_payload->>'demand_date','') is not null
      and (p_payload->>'demand_date')::date not between v_cycle.period_start and v_cycle.period_end then
      raise exception '需求日期必须位于规划周期内';
    end if;

    if p_id is not null then
      select * into v_line from public.hr_workforce_plan_line where id = p_id for update;
      if not found or v_line.plan_id <> v_cycle.id then raise exception '人力规划岗位需求不存在'; end if;
      update public.hr_workforce_plan_line set
        organization_id = (p_payload->>'organization_id')::uuid,
        position_id = v_position.id,
        baseline_count = case when v_line.position_id = v_position.id then v_line.baseline_count else v_baseline end,
        planned_hires = coalesce((p_payload->>'planned_hires')::integer,0),
        planned_exits = coalesce((p_payload->>'planned_exits')::integer,0),
        annual_cost_per_head = nullif(p_payload->>'annual_cost_per_head','')::numeric,
        demand_date = nullif(p_payload->>'demand_date','')::date,
        priority = coalesce(nullif(p_payload->>'priority',''),'normal'),
        rationale = btrim(p_payload->>'rationale'),
        assumptions = nullif(btrim(p_payload->>'assumptions'),'')
      where id = p_id returning * into v_line;
      return v_line.id;
    end if;
    insert into public.hr_workforce_plan_line(
      tenant_id, plan_id, organization_id, position_id, baseline_count, planned_hires,
      planned_exits, annual_cost_per_head, demand_date, priority, rationale, assumptions
    ) values (
      v_tenant_id, v_cycle.id, (p_payload->>'organization_id')::uuid, v_position.id, v_baseline,
      coalesce((p_payload->>'planned_hires')::integer,0), coalesce((p_payload->>'planned_exits')::integer,0),
      nullif(p_payload->>'annual_cost_per_head','')::numeric,
      nullif(p_payload->>'demand_date','')::date, coalesce(nullif(p_payload->>'priority',''),'normal'),
      btrim(p_payload->>'rationale'), nullif(btrim(p_payload->>'assumptions'),'')
    ) returning * into v_line;
    return v_line.id;
  end if;

  select * into v_position from public.mdm_position
  where id = (p_payload->>'position_id')::uuid and tenant_id = v_tenant_id;
  if not found then raise exception '岗位不存在'; end if;
  if v_position.organization_id <> (p_payload->>'organization_id')::uuid then raise exception '岗位与组织不匹配'; end if;
  if exists (
    select 1 from public.hr_position_headcount h
    where h.tenant_id = v_tenant_id and h.position_id = v_position.id and h.enabled
      and h.id <> coalesce(p_id, '00000000-0000-0000-0000-000000000000'::uuid)
      and daterange(h.effective_from, coalesce(h.effective_to,'infinity'::date),'[]')
        && daterange((p_payload->>'effective_from')::date,
          coalesce(nullif(p_payload->>'effective_to','')::date,'infinity'::date),'[]')
  ) then raise exception '该岗位在所选期间已有有效编制记录'; end if;
  if p_id is null then
    insert into public.hr_position_headcount(
      tenant_id, organization_id, position_id, approved_count, effective_from, effective_to, enabled, remark
    ) values (
      v_tenant_id, (p_payload->>'organization_id')::uuid, v_position.id,
      (p_payload->>'approved_count')::integer, (p_payload->>'effective_from')::date,
      nullif(p_payload->>'effective_to','')::date,
      coalesce((p_payload->>'enabled')::boolean,true), nullif(btrim(p_payload->>'remark'),'')
    ) returning * into v_effective;
  else
    update public.hr_position_headcount set
      organization_id = (p_payload->>'organization_id')::uuid,
      position_id = v_position.id, approved_count = (p_payload->>'approved_count')::integer,
      effective_from = (p_payload->>'effective_from')::date,
      effective_to = nullif(p_payload->>'effective_to','')::date,
      enabled = coalesce((p_payload->>'enabled')::boolean,true),
      remark = nullif(btrim(p_payload->>'remark'),'')
    where id = p_id and (app_private.is_platform_super() or tenant_id = v_tenant_id)
    returning * into v_effective;
    if not found then raise exception '有效编制记录不存在'; end if;
  end if;
  if v_effective.enabled and v_effective.effective_from <= current_date
    and (v_effective.effective_to is null or v_effective.effective_to >= current_date) then
    if v_effective.approved_count = 0 then
      update public.mdm_position set enabled = false where id = v_position.id;
    else
      update public.mdm_position set headcount_limit = v_effective.approved_count,
        multiple_incumbents_allowed = multiple_incumbents_allowed or v_effective.approved_count > 1
      where id = v_position.id;
    end if;
  end if;
  return v_effective.id;
end
$$;


ALTER FUNCTION "public"."hr_save_workforce_record_secure"("p_kind" "text", "p_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: hr_service_delivery_overview_secure("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_service_delivery_overview_secure"("p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_employee_id uuid := app_private.hr_current_employee_id();
  v_manage boolean := app_private.is_platform_super()
    or app_private.has_permission('Hr:SelfService:Manage');
begin
  if not app_private.can_execute_business_action(
    'HrSelfService', 'Hr:SelfService:View', null, false
  ) then
    raise exception '当前账号没有查看员工服务中心的权限' using errcode = '42501';
  end if;

  if not app_private.is_platform_super() then
    p_tenant_id := v_tenant_id;
  end if;

  return jsonb_build_object(
    'available_service_count', (
      select count(*) from public.hr_service_catalog service
      where (p_tenant_id is null or service.tenant_id = p_tenant_id)
        and service.enabled
    ),
    'open_request_count', (
      select count(*) from public.hr_self_service_request request
      where (p_tenant_id is null or request.tenant_id = p_tenant_id)
        and (v_manage or request.employee_id = v_employee_id)
        and request.status in ('submitted', 'assigned', 'in_progress', 'waiting_employee')
    ),
    'sla_risk_count', (
      select count(*) from public.hr_self_service_request request
      where (p_tenant_id is null or request.tenant_id = p_tenant_id)
        and (v_manage or request.employee_id = v_employee_id)
        and request.status in ('submitted', 'assigned', 'in_progress', 'waiting_employee')
        and request.resolution_due_at is not null
        and request.resolution_due_at <= now() + interval '4 hours'
    ),
    'unassigned_count', (
      select count(*) from public.hr_self_service_request request
      where v_manage
        and (p_tenant_id is null or request.tenant_id = p_tenant_id)
        and request.status = 'submitted'
        and request.assigned_employee_id is null
    ),
    'resolved_month_count', (
      select count(*) from public.hr_self_service_request request
      where (p_tenant_id is null or request.tenant_id = p_tenant_id)
        and (v_manage or request.employee_id = v_employee_id)
        and request.resolved_at >= date_trunc('month', now())
    ),
    'response_on_time_rate', (
      select coalesce(round(
        100 * count(*) filter (
          where request.first_responded_at is not null
            and request.first_response_due_at is not null
            and request.first_responded_at <= request.first_response_due_at
        )::numeric / nullif(count(*) filter (where request.first_responded_at is not null), 0), 1
      ), 0)
      from public.hr_self_service_request request
      where (p_tenant_id is null or request.tenant_id = p_tenant_id)
        and (v_manage or request.employee_id = v_employee_id)
        and request.create_time >= date_trunc('month', now())
    ),
    'manager_view', v_manage
  );
end
$$;


ALTER FUNCTION "public"."hr_service_delivery_overview_secure"("p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_submit_approval("text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_submit_approval"("p_business_type" "text", "p_business_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$ declare v_title text; v_context jsonb; begin
  if p_business_type='hr_recruitment_requisition' then
    if not (select app_private.is_platform_super()) and not (select app_private.has_permission('Hr:Recruitment:Submit')) then
      raise exception '当前账号没有提交招聘需求的权限' using errcode='42501';
    end if;
    select '招聘需求 '||r.requisition_no,jsonb_build_object('requisitionNo',r.requisition_no,
      'organizationId',r.organization_id,'positionId',r.position_id,'openingCount',r.opening_count,
      'expectedOnboardDate',r.expected_onboard_date) into v_title,v_context
    from public.hr_recruitment_requisition r where r.id=p_business_id
      and ((select app_private.is_platform_super()) or r.tenant_id=(select app_private.current_user_tenant_id()))
      and r.status in ('draft','rejected');
    if v_title is null then raise exception '招聘需求不存在或当前状态不可提交'; end if;
    return app_private.start_workflow(p_business_type,p_business_id,v_title,v_context,gen_random_uuid()::text);
  end if;
  return public.hr_submit_approval_before_hr_p2(p_business_type,p_business_id);
end $$;


ALTER FUNCTION "public"."hr_submit_approval"("p_business_type" "text", "p_business_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_submit_approval_before_hr_p1("text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_submit_approval_before_hr_p1"("p_business_type" "text", "p_business_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_permission text;
  v_title text;
  v_context jsonb := '{}'::jsonb;
begin
  if p_business_type = 'hr_personnel_change' then
    v_permission := 'Hr:PersonnelChange:Submit';
    select '人事异动 ' || c.change_no,
           jsonb_build_object('changeNo',c.change_no,'changeType',c.change_type,
             'employeeId',c.employee_id,'effectiveDate',c.effective_date)
      into v_title,v_context
    from public.hr_personnel_change c
    where c.id=p_business_id
      and ((select app_private.is_platform_super()) or c.tenant_id=(select app_private.current_user_tenant_id()))
      and c.status in ('draft','rejected');
  elsif p_business_type = 'hr_lifecycle_case' then
    v_permission := 'Hr:Lifecycle:Submit';
    select '员工生命周期 ' || c.case_no,
           jsonb_build_object('caseNo',c.case_no,'caseType',c.case_type,
             'employeeId',c.employee_id,'plannedEffectiveDate',c.planned_effective_date)
      into v_title,v_context
    from public.hr_lifecycle_case c
    where c.id=p_business_id
      and ((select app_private.is_platform_super()) or c.tenant_id=(select app_private.current_user_tenant_id()))
      and c.status in ('draft','rejected');
  else
    raise exception '不支持的人事审批业务类型';
  end if;
  if v_title is null then raise exception '单据不存在或当前状态不可提交'; end if;
  if not (select app_private.is_platform_super())
     and not (select app_private.has_permission(v_permission)) then
    raise exception '当前账号没有提交该人事单据的权限' using errcode='42501';
  end if;
  return app_private.start_workflow(
    p_business_type,p_business_id,v_title,v_context,gen_random_uuid()::text
  );
end;
$$;


ALTER FUNCTION "public"."hr_submit_approval_before_hr_p1"("p_business_type" "text", "p_business_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_submit_approval_before_hr_p2("text", "uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_submit_approval_before_hr_p2"("p_business_type" "text", "p_business_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_permission text; v_title text; v_context jsonb:='{}'::jsonb;
begin
  if p_business_type='hr_self_service_request' then
    v_permission:='Hr:SelfService:Submit';
    select '员工申请 '||r.request_no,jsonb_build_object('requestNo',r.request_no,'requestType',r.request_type,
      'employeeId',r.employee_id,'durationHours',r.duration_hours,'startAt',r.start_at,'endAt',r.end_at)
    into v_title,v_context from public.hr_self_service_request r
    where r.id=p_business_id and r.tenant_id=(select app_private.current_user_tenant_id())
      and r.status in ('draft','rejected') and (
        (select app_private.has_permission('Hr:SelfService:Manage')) or r.employee_id=(
          select u.hr_employee_id from public.sys_user u where u.id=(select app_private.current_app_user_id())
        ));
    if v_title is null then raise exception '申请不存在或当前状态不可提交'; end if;
    if not (select app_private.is_platform_super()) and not (select app_private.has_permission(v_permission)) then
      raise exception '当前账号没有提交员工申请的权限' using errcode='42501';
    end if;
    return app_private.start_workflow(p_business_type,p_business_id,v_title,v_context,gen_random_uuid()::text);
  end if;
  return public.hr_submit_approval_before_hr_p1(p_business_type,p_business_id);
end $$;


ALTER FUNCTION "public"."hr_submit_approval_before_hr_p2"("p_business_type" "text", "p_business_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_submit_employee_experience_response_secure("uuid", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_submit_employee_experience_response_secure"("p_participant_id" "uuid", "p_answers" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_employee_id uuid := app_private.hr_current_employee_id();
  v_participant public.hr_experience_participant;
  v_survey public.hr_experience_survey;
  v_response_id uuid;
  v_question public.hr_experience_question;
  v_answer jsonb;
  v_numeric numeric;
  v_text text;
begin
  if auth.uid() is null or v_employee_id is null or not app_private.can_execute_business_action(
    'HrEmployeeExperience', 'Hr:Experience:Respond', p_participant_id, false
  ) then raise exception '当前账号没有填写员工体验调查的权限' using errcode = '42501'; end if;
  if jsonb_typeof(p_answers) <> 'array' then raise exception '调查答案格式不正确'; end if;

  select * into v_participant from public.hr_experience_participant participant
    where participant.id = p_participant_id and participant.tenant_id = v_tenant_id
      and participant.employee_id = v_employee_id for update;
  if v_participant.id is null then raise exception '待填写调查不存在或不属于当前员工'; end if;
  if v_participant.status <> 'invited' then raise exception '该调查已完成或不再允许填写'; end if;
  select * into v_survey from public.hr_experience_survey survey
    where survey.id = v_participant.survey_id and survey.tenant_id = v_participant.tenant_id;
  if v_survey.status <> 'open' or current_date not between v_survey.start_date and v_survey.end_date then
    raise exception '调查当前未开放或已超过填写周期';
  end if;
  if exists (
    select 1 from (
      select value ->> 'question_id' question_id, count(*) count_value
      from jsonb_array_elements(p_answers) value
      group by value ->> 'question_id' having count(*) > 1
    ) duplicate
  ) then raise exception '同一道题不能重复提交答案'; end if;
  if exists (
    select 1 from jsonb_array_elements(p_answers) value
    where not exists (select 1 from public.hr_experience_question question
      where question.id = nullif(value ->> 'question_id', '')::uuid
        and question.survey_id = v_survey.id and question.tenant_id = v_tenant_id
        and question.enabled)
  ) then raise exception '答案包含不属于当前调查的题目'; end if;
  if exists (
    select 1 from public.hr_experience_question question
    where question.survey_id = v_survey.id and question.tenant_id = v_tenant_id
      and question.enabled and question.required
      and not exists (select 1 from jsonb_array_elements(p_answers) value
        where nullif(value ->> 'question_id', '')::uuid = question.id)
  ) then raise exception '请完成全部必答题后再提交'; end if;

  insert into public.hr_experience_response(
    tenant_id, survey_id, cohort_organization_id
  ) values (
    v_tenant_id, v_survey.id, v_participant.organization_snapshot_id
  ) returning id into v_response_id;

  for v_answer in select value from jsonb_array_elements(p_answers)
  loop
    select * into v_question from public.hr_experience_question question
      where question.id = (v_answer ->> 'question_id')::uuid
        and question.survey_id = v_survey.id and question.tenant_id = v_tenant_id;
    v_numeric := nullif(v_answer ->> 'numeric_score', '')::numeric;
    v_text := nullif(btrim(v_answer ->> 'text_answer'), '');
    if v_question.answer_type = 'rating_5' then
      if v_numeric is null or v_numeric < 1 or v_numeric > 5 then
        raise exception '五分量表答案必须在 1 到 5 之间';
      end if;
      v_text := null;
    elsif v_question.answer_type = 'enps_11' then
      if v_numeric is null or v_numeric < 0 or v_numeric > 10 then
        raise exception 'eNPS 答案必须在 0 到 10 之间';
      end if;
      v_text := null;
    else
      v_numeric := null;
      if v_question.required and v_text is null then raise exception '开放题不能为空'; end if;
      if v_text is null then continue; end if;
    end if;
    insert into public.hr_experience_answer(
      tenant_id, response_id, question_id, numeric_score, text_answer
    ) values (v_tenant_id, v_response_id, v_question.id, v_numeric, v_text);
  end loop;

  update public.hr_experience_participant set status = 'completed', completed_on = current_date
    where id = v_participant.id;
  return v_response_id;
end
$$;


ALTER FUNCTION "public"."hr_submit_employee_experience_response_secure"("p_participant_id" "uuid", "p_answers" "jsonb") OWNER TO "postgres";

--

--
-- Name: hr_succession_overview_secure("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_succession_overview_secure"("p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
begin
  if not app_private.can_execute_business_action('HrSuccession', 'Hr:Succession:View', null, false) then
    raise exception 'Missing succession view permission' using errcode = '42501';
  end if;
  if not app_private.is_platform_super() then p_tenant_id := v_tenant_id; end if;
  return jsonb_build_object(
    'active_plan_count', (select count(*) from public.hr_succession_plan p where (p_tenant_id is null or p.tenant_id=p_tenant_id) and p.status='active'),
    'critical_position_count', (select count(*) from public.hr_succession_plan p where (p_tenant_id is null or p.tenant_id=p_tenant_id) and p.status='active' and p.criticality='critical'),
    'ready_now_count', (select count(*) from public.hr_succession_candidate c join public.hr_succession_plan p on p.id=c.plan_id where (p_tenant_id is null or c.tenant_id=p_tenant_id) and p.status='active' and c.status='active' and c.readiness='ready_now'),
    'uncovered_plan_count', (select count(*) from public.hr_succession_plan p where (p_tenant_id is null or p.tenant_id=p_tenant_id) and p.status='active' and not exists (select 1 from public.hr_succession_candidate c where c.plan_id=p.id and c.status='active')),
    'overdue_action_count', (select count(*) from public.hr_succession_development_action a where (p_tenant_id is null or a.tenant_id=p_tenant_id) and a.status in ('planned','in_progress') and a.due_date < current_date),
    'due_review_count', (select count(*) from public.hr_succession_plan p where (p_tenant_id is null or p.tenant_id=p_tenant_id) and p.status='active' and p.next_review_date <= current_date + 30)
  );
end;
$$;


ALTER FUNCTION "public"."hr_succession_overview_secure"("p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: hr_transition_attendance_correction_secure("uuid", "text", "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_transition_attendance_correction_secure"("p_id" "uuid", "p_action" "text", "p_comment" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid:=app_private.current_user_tenant_id();
  v_correction public.hr_attendance_correction;
begin
  if p_action not in ('submit','approve','reject','cancel') then raise exception '不支持的修正单动作'; end if;
  if not app_private.can_execute_business_action('HrAttendance',
    case when p_action in ('approve','reject') then 'Hr:Attendance:ReviewCorrection' else 'Hr:Attendance:Edit' end,
    null,false) then raise exception '当前账号没有处理考勤修正的权限' using errcode='42501'; end if;
  select * into v_correction from public.hr_attendance_correction c where c.id=p_id
    and (app_private.is_platform_super() or c.tenant_id=v_tenant_id) for update;
  if not found then raise exception '考勤修正单不存在或无权操作'; end if;
  if p_action='submit' then
    if v_correction.status not in ('draft','rejected') then raise exception '当前修正单不能提交'; end if;
    update public.hr_attendance_correction set status='submitted',submitted_at=now(),
      reviewed_at=null,reviewed_by=null,review_comment=null where id=p_id;
    return;
  end if;
  if p_action='cancel' then
    if v_correction.status not in ('draft','submitted') then raise exception '当前修正单不能取消'; end if;
    update public.hr_attendance_correction set status='cancelled' where id=p_id;
    return;
  end if;
  if v_correction.status<>'submitted' then raise exception '只有待审核修正单可以评审'; end if;
  if p_action='reject' then
    if nullif(btrim(p_comment),'') is null then raise exception '驳回必须填写原因'; end if;
    update public.hr_attendance_correction set status='rejected',reviewed_at=now(),
      reviewed_by=auth.uid()::text,review_comment=btrim(p_comment) where id=p_id;
    return;
  end if;
  if exists(select 1 from public.hr_attendance_record r where r.id=v_correction.attendance_record_id and r.locked_at is not null) then
    raise exception '考勤记录已封账，不能批准修正';
  end if;
  update public.hr_attendance_record set clock_in_at=v_correction.requested_clock_in_at,
    clock_out_at=v_correction.requested_clock_out_at,source='correction',source_reference=v_correction.correction_no,
    remark=concat_ws('；',remark,'修正单 '||v_correction.correction_no||' 已批准')
  where id=v_correction.attendance_record_id;
  perform app_private.hr_valuate_attendance_record(v_correction.attendance_record_id);
  update public.hr_attendance_record set exception_status='resolved'
  where id=v_correction.attendance_record_id and exception_status='clear';
  update public.hr_attendance_correction set status='approved',reviewed_at=now(),
    reviewed_by=auth.uid()::text,review_comment=nullif(btrim(p_comment),'') where id=p_id;
end
$$;


ALTER FUNCTION "public"."hr_transition_attendance_correction_secure"("p_id" "uuid", "p_action" "text", "p_comment" "text") OWNER TO "postgres";

--

--
-- Name: hr_transition_attendance_period_secure("uuid", "text", "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_transition_attendance_period_secure"("p_id" "uuid", "p_action" "text", "p_comment" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid:=app_private.current_user_tenant_id();
  v_period public.hr_attendance_period;
  v_record_count integer;
  v_exception_count integer;
  v_scheduled bigint;
  v_payable bigint;
  v_overtime bigint;
begin
  if p_action not in ('review','close','reopen') then raise exception '不支持的考勤期间动作'; end if;
  if p_action='reopen' and not app_private.is_platform_super() then
    raise exception '只有平台超级管理员可以重新开放已封账期间' using errcode='42501';
  end if;
  if p_action<>'reopen' and not app_private.can_execute_business_action('HrAttendance','Hr:Attendance:ClosePeriod',null,false) then
    raise exception '当前账号没有考勤封账权限' using errcode='42501';
  end if;
  select * into v_period from public.hr_attendance_period p where p.id=p_id
    and (app_private.is_platform_super() or p.tenant_id=v_tenant_id) for update;
  if not found then raise exception '考勤期间不存在或无权操作'; end if;
  if p_action='reopen' then
    if v_period.status<>'closed' then raise exception '只有已封账期间可以重新开放'; end if;
    update public.hr_attendance_record set locked_at=null,locked_by=null
    where tenant_id=v_period.tenant_id and work_date>=v_period.period_month
      and work_date<v_period.period_month+interval '1 month';
    update public.hr_attendance_period set status='open',reviewed_at=null,reviewed_by=null,
      closed_at=null,closed_by=null,close_note=nullif(btrim(p_comment),'') where id=p_id;
    return;
  end if;
  select count(*),count(*) filter(where exception_status='open'),
    coalesce(sum(scheduled_minutes),0),coalesce(sum(payable_minutes),0),coalesce(sum(overtime_minutes),0)
  into v_record_count,v_exception_count,v_scheduled,v_payable,v_overtime
  from public.hr_attendance_record where tenant_id=v_period.tenant_id
    and work_date>=v_period.period_month and work_date<v_period.period_month+interval '1 month';
  if p_action='review' then
    if v_period.status<>'open' then raise exception '只有开放期间可以进入核对'; end if;
    update public.hr_attendance_period set status='reviewing',record_count=v_record_count,
      exception_count=v_exception_count,total_scheduled_minutes=v_scheduled,total_payable_minutes=v_payable,
      total_overtime_minutes=v_overtime,reviewed_at=now(),reviewed_by=auth.uid()::text,
      close_note=nullif(btrim(p_comment),'') where id=p_id;
    return;
  end if;
  if v_period.status<>'reviewing' then raise exception '只有核对中期间可以封账'; end if;
  if v_exception_count>0 then raise exception '仍有 % 条待处理考勤异常，不能封账',v_exception_count; end if;
  if exists(select 1 from public.hr_attendance_correction c join public.hr_attendance_record r
    on r.id=c.attendance_record_id and r.tenant_id=c.tenant_id
    where c.tenant_id=v_period.tenant_id and c.status='submitted'
      and r.work_date>=v_period.period_month and r.work_date<v_period.period_month+interval '1 month') then
    raise exception '期间内仍有待审核修正单，不能封账';
  end if;
  if nullif(btrim(p_comment),'') is null then raise exception '封账必须填写复核说明'; end if;
  update public.hr_attendance_record set locked_at=now(),locked_by=auth.uid()::text
  where tenant_id=v_period.tenant_id and work_date>=v_period.period_month
    and work_date<v_period.period_month+interval '1 month';
  update public.hr_attendance_period set status='closed',record_count=v_record_count,
    exception_count=v_exception_count,total_scheduled_minutes=v_scheduled,total_payable_minutes=v_payable,
    total_overtime_minutes=v_overtime,closed_at=now(),closed_by=auth.uid()::text,
    close_note=btrim(p_comment) where id=p_id;
end
$$;


ALTER FUNCTION "public"."hr_transition_attendance_period_secure"("p_id" "uuid", "p_action" "text", "p_comment" "text") OWNER TO "postgres";

--

--
-- Name: hr_transition_attendance_record_secure("uuid", "text", "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_transition_attendance_record_secure"("p_id" "uuid", "p_action" "text", "p_comment" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid:=app_private.current_user_tenant_id();
  v_record public.hr_attendance_record;
begin
  if p_action not in ('evaluate','waive','reopen') then raise exception '不支持的考勤记录动作'; end if;
  if not app_private.can_execute_business_action('HrAttendance',
    case when p_action='evaluate' then 'Hr:Attendance:Evaluate' else 'Hr:Attendance:ReviewCorrection' end,
    null,false) then raise exception '当前账号没有处理考勤异常的权限' using errcode='42501'; end if;
  select * into v_record from public.hr_attendance_record r where r.id=p_id
    and (app_private.is_platform_super() or r.tenant_id=v_tenant_id) for update;
  if not found then raise exception '考勤记录不存在或无权操作'; end if;
  if v_record.locked_at is not null then raise exception '考勤记录已封账'; end if;
  if p_action='evaluate' then perform app_private.hr_valuate_attendance_record(p_id); return; end if;
  if nullif(btrim(p_comment),'') is null then raise exception '处理异常必须填写原因'; end if;
  if p_action='waive' then
    if v_record.exception_status<>'open' then raise exception '只有待处理异常可以豁免'; end if;
    update public.hr_attendance_record set exception_status='waived',
      valuation_note=concat_ws('；',valuation_note,'豁免：'||btrim(p_comment)) where id=p_id;
  else
    if v_record.exception_status not in ('resolved','waived') then raise exception '当前记录不能重新打开'; end if;
    update public.hr_attendance_record set exception_status='open',
      valuation_note=concat_ws('；',valuation_note,'重新打开：'||btrim(p_comment)) where id=p_id;
  end if;
end
$$;


ALTER FUNCTION "public"."hr_transition_attendance_record_secure"("p_id" "uuid", "p_action" "text", "p_comment" "text") OWNER TO "postgres";

--

--
-- Name: hr_transition_benefit_record_secure("text", "uuid", "text", "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_transition_benefit_record_secure"("p_kind" "text", "p_id" "uuid", "p_action" "text", "p_comment" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_plan public.hr_benefit_plan;
  v_enrollment public.hr_employee_benefit_enrollment;
  v_event public.hr_benefit_life_event;
begin
  if auth.uid() is null then raise exception '请先登录' using errcode = '42501'; end if;

  if p_kind = 'plan' then
    if not app_private.can_execute_business_action(
      'HrBenefits', 'Hr:Benefits:Plan:Manage', p_id, false
    ) then raise exception '当前账号没有管理福利计划的权限' using errcode = '42501'; end if;
    select * into v_plan from public.hr_benefit_plan
      where id = p_id and (app_private.is_platform_super() or tenant_id = v_tenant_id) for update;
    if v_plan.id is null then raise exception '福利计划不存在或无权处理'; end if;
    if p_action = 'activate' and v_plan.status = 'draft' then
      if not exists (select 1 from public.hr_benefit_option
        where plan_id = p_id and tenant_id = v_plan.tenant_id and enabled) then
        raise exception '至少维护一个启用的覆盖方案后才能生效';
      end if;
      update public.hr_benefit_plan set status = 'active' where id = p_id;
      perform app_private.hr_add_benefit_event(v_plan.tenant_id, 'plan', p_id,
        'activated', v_plan.status, 'active', '福利计划已生效');
    elsif p_action = 'deactivate' and v_plan.status = 'active' then
      update public.hr_benefit_plan set status = 'inactive' where id = p_id;
      perform app_private.hr_add_benefit_event(v_plan.tenant_id, 'plan', p_id,
        'deactivated', v_plan.status, 'inactive', '福利计划已停用');
    elsif p_action = 'reactivate' and v_plan.status = 'inactive' then
      update public.hr_benefit_plan set status = 'active' where id = p_id;
      perform app_private.hr_add_benefit_event(v_plan.tenant_id, 'plan', p_id,
        'reactivated', v_plan.status, 'active', '福利计划已重新生效');
    elsif p_action = 'cancel' and v_plan.status = 'draft' then
      update public.hr_benefit_plan set status = 'cancelled' where id = p_id;
      perform app_private.hr_add_benefit_event(v_plan.tenant_id, 'plan', p_id,
        'cancelled', v_plan.status, 'cancelled', '福利计划草稿已取消');
    else raise exception '当前状态不允许执行该计划动作'; end if;
  elsif p_kind = 'enrollment' then
    select * into v_enrollment from public.hr_employee_benefit_enrollment
      where id = p_id and (app_private.is_platform_super() or tenant_id = v_tenant_id) for update;
    if v_enrollment.id is null then raise exception '参保记录不存在或无权处理'; end if;
    if p_action = 'submit' then
      if not app_private.can_execute_business_action(
        'HrBenefits', 'Hr:Benefits:Enrollment:Manage', p_id, false
      ) or v_enrollment.status <> 'draft' then raise exception '当前参保记录不能提交审核'; end if;
      if exists (select 1 from public.hr_employee_benefit_enrollment existing
        where existing.tenant_id = v_enrollment.tenant_id
          and existing.employee_id = v_enrollment.employee_id
          and existing.plan_id = v_enrollment.plan_id
          and existing.id <> v_enrollment.id
          and existing.status in ('pending', 'active')) then
        raise exception '该员工在此福利计划下已有待审核或生效中的参保记录';
      end if;
      update public.hr_employee_benefit_enrollment set status = 'pending'
        where id = p_id;
      perform app_private.hr_add_benefit_event(v_enrollment.tenant_id, 'enrollment', p_id,
        'submitted', 'draft', 'pending', '提交参保审核');
    elsif p_action = 'approve' then
      if not app_private.can_execute_business_action(
        'HrBenefits', 'Hr:Benefits:Approve', p_id, false
      ) or v_enrollment.status <> 'pending' then raise exception '当前参保记录不能审核生效'; end if;
      update public.hr_employee_benefit_enrollment set status = 'active',
        payroll_sync_status = 'ready', approved_by = coalesce(auth.jwt() ->> 'email', auth.uid()::text),
        approved_at = now() where id = p_id;
      if v_enrollment.life_event_id is not null then
        update public.hr_benefit_life_event set status = 'processed', processed_at = now()
          where id = v_enrollment.life_event_id and status = 'open';
      end if;
      perform app_private.hr_add_benefit_event(v_enrollment.tenant_id, 'enrollment', p_id,
        'approved', 'pending', 'active', '参保审核通过并生成薪资输入资格');
    elsif p_action = 'reject' then
      if not app_private.can_execute_business_action(
        'HrBenefits', 'Hr:Benefits:Approve', p_id, false
      ) or v_enrollment.status <> 'pending' or nullif(btrim(p_comment), '') is null then
        raise exception '驳回待审核参保记录时必须填写原因';
      end if;
      update public.hr_employee_benefit_enrollment set status = 'draft'
        where id = p_id;
      perform app_private.hr_add_benefit_event(v_enrollment.tenant_id, 'enrollment', p_id,
        'rejected', 'pending', 'draft', '参保审核已驳回',
        jsonb_build_object('comment', btrim(p_comment)));
    elsif p_action = 'end' then
      if not app_private.can_execute_business_action(
        'HrBenefits', 'Hr:Benefits:Enrollment:Manage', p_id, false
      ) or v_enrollment.status <> 'active' then raise exception '只有生效中的参保可以终止'; end if;
      update public.hr_employee_benefit_enrollment set status = 'ended',
        coverage_to = coalesce(coverage_to, current_date), payroll_sync_status = 'stopped',
        ended_at = now() where id = p_id;
      perform app_private.hr_add_benefit_event(v_enrollment.tenant_id, 'enrollment', p_id,
        'ended', 'active', 'ended', '员工福利保障已终止',
        jsonb_build_object('comment', nullif(btrim(p_comment), '')));
    elsif p_action = 'cancel' and v_enrollment.status = 'draft' then
      if not app_private.can_execute_business_action(
        'HrBenefits', 'Hr:Benefits:Enrollment:Manage', p_id, false
      ) then raise exception '当前账号没有取消参保草稿的权限'; end if;
      update public.hr_employee_benefit_enrollment set status = 'cancelled',
        payroll_sync_status = 'stopped' where id = p_id;
      perform app_private.hr_add_benefit_event(v_enrollment.tenant_id, 'enrollment', p_id,
        'cancelled', 'draft', 'cancelled', '参保草稿已取消');
    else raise exception '当前状态不允许执行该参保动作'; end if;
  elsif p_kind = 'event' then
    if not app_private.can_execute_business_action(
      'HrBenefits', 'Hr:Benefits:Event:Manage', p_id, false
    ) then raise exception '当前账号没有管理福利人生事件的权限' using errcode = '42501'; end if;
    select * into v_event from public.hr_benefit_life_event
      where id = p_id and (app_private.is_platform_super() or tenant_id = v_tenant_id) for update;
    if v_event.id is null then raise exception '人生事件不存在或无权处理'; end if;
    if p_action = 'process' and v_event.status = 'open' then
      update public.hr_benefit_life_event set status = 'processed', processed_at = now()
        where id = p_id;
      perform app_private.hr_add_benefit_event(v_event.tenant_id, 'life_event', p_id,
        'processed', 'open', 'processed', '人生事件已处理');
    elsif p_action = 'cancel' and v_event.status = 'open' then
      update public.hr_benefit_life_event set status = 'cancelled' where id = p_id;
      perform app_private.hr_add_benefit_event(v_event.tenant_id, 'life_event', p_id,
        'cancelled', 'open', 'cancelled', '人生事件已取消');
    else raise exception '当前状态不允许执行该人生事件动作'; end if;
  else raise exception '不支持的福利记录类型'; end if;
  return true;
end
$$;


ALTER FUNCTION "public"."hr_transition_benefit_record_secure"("p_kind" "text", "p_id" "uuid", "p_action" "text", "p_comment" "text") OWNER TO "postgres";

--

--
-- Name: hr_transition_candidate_stage_secure("uuid", "text", "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_transition_candidate_stage_secure"("p_candidate_id" "uuid", "p_to_stage" "text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
begin
  if not app_private.can_execute_business_action('HrRecruitment', 'Hr:Recruitment:Candidate:Move', null, false) then
    raise exception '当前账号没有推进候选人的权限' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.hr_candidate c
    where c.id = p_candidate_id and (app_private.is_platform_super() or c.tenant_id = v_tenant_id)
  ) then raise exception '候选人不存在或无权操作'; end if;
  if p_to_stage not in ('screening', 'rejected', 'withdrawn') then
    raise exception '该阶段必须由面试、Offer 或入职交接动作推进';
  end if;
  perform app_private.hr_append_candidate_stage(p_candidate_id, p_to_stage, p_reason);
end
$$;


ALTER FUNCTION "public"."hr_transition_candidate_stage_secure"("p_candidate_id" "uuid", "p_to_stage" "text", "p_reason" "text") OWNER TO "postgres";

--

--
-- Name: hr_transition_compensation_review_cycle_secure("uuid", "text", "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_transition_compensation_review_cycle_secure"("p_id" "uuid", "p_action" "text", "p_comment" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    SET "TimeZone" TO 'Asia/Shanghai'
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_cycle public.hr_compensation_review_cycle%rowtype;
  v_item public.hr_compensation_review_item%rowtype;
  v_new_compensation_id uuid;
  v_actor text := coalesce(app_private.current_user_email(), auth.uid()::text, 'system');
  v_inserted integer := 0;
begin
  if p_action not in ('open', 'calibrate', 'approve', 'effect', 'cancel') then
    raise exception '不支持的调薪复核动作';
  end if;
  if auth.uid() is null then raise exception '请先登录' using errcode = '42501'; end if;

  select * into v_cycle from public.hr_compensation_review_cycle
  where id = p_id and (app_private.is_platform_super() or tenant_id = v_tenant_id) for update;
  if not found then raise exception '调薪周期不存在'; end if;

  if p_action in ('open', 'cancel') then
    if not app_private.can_execute_business_action(
      'HrCompensationReview', 'Hr:CompensationReview:Cycle:Manage', null, false
    ) then raise exception '当前账号没有管理调薪周期的权限' using errcode = '42501'; end if;
  elsif p_action = 'calibrate' then
    if not app_private.can_execute_business_action(
      'HrCompensationReview', 'Hr:CompensationReview:Calibrate', null, false
    ) then raise exception '当前账号没有执行调薪校准的权限' using errcode = '42501'; end if;
  elsif p_action = 'approve' then
    if not app_private.can_execute_business_action(
      'HrCompensationReview', 'Hr:CompensationReview:Approve', null, false
    ) then raise exception '当前账号没有批准调薪结果的权限' using errcode = '42501'; end if;
  else
    if not app_private.can_execute_business_action(
      'HrCompensationReview', 'Hr:CompensationReview:Effect', null, false
    ) then raise exception '当前账号没有批量生效调薪的权限' using errcode = '42501'; end if;
  end if;

  if p_action = 'open' then
    if v_cycle.status <> 'draft' then raise exception '只有草稿周期可以开放建议'; end if;
    if v_cycle.recommendation_due_date < current_date then raise exception '建议截止日期不能早于当前业务日期'; end if;

    insert into public.hr_compensation_review_item(
      tenant_id, cycle_id, employee_id, organization_id, current_compensation_id,
      current_grade_id, current_base_amount, proposed_base_amount, performance_level, status
    )
    select
      v_cycle.tenant_id,
      v_cycle.id,
      employee.id,
      coalesce(assignment.organization_id, employee.organization_id),
      compensation.id,
      coalesce(assignment.grade_id, compensation.grade_id),
      compensation.base_amount,
      compensation.base_amount,
      performance.performance_level,
      'pending'
    from public.mdm_employee employee
    join lateral (
      select compensation_row.*
      from public.hr_employee_compensation compensation_row
      where compensation_row.tenant_id = employee.tenant_id
        and compensation_row.employee_id = employee.id
        and compensation_row.status = 'approved'
        and compensation_row.currency_code = v_cycle.currency_code
        and compensation_row.effective_from <= current_date
        and coalesce(compensation_row.effective_to, 'infinity'::date) >= current_date
      order by compensation_row.effective_from desc
      limit 1
    ) compensation on true
    left join lateral (
      select assignment_row.*
      from public.mdm_employee_assignment assignment_row
      where assignment_row.tenant_id = employee.tenant_id
        and assignment_row.employee_id = employee.id
        and assignment_row.primary_assignment
        and assignment_row.effective_start <= current_date
        and coalesce(assignment_row.effective_end, 'infinity'::date) >= current_date
      order by assignment_row.effective_start desc
      limit 1
    ) assignment on true
    left join lateral (
      select review.performance_level
      from public.hr_performance_review review
      where review.tenant_id = employee.tenant_id
        and review.employee_id = employee.id
        and review.status = 'completed'
      order by review.completed_at desc nulls last, review.update_time desc
      limit 1
    ) performance on true
    where employee.tenant_id = v_cycle.tenant_id
      and employee.employment_status in ('probation', 'active', 'leave')
      and (v_cycle.scope_organization_id is null
        or coalesce(assignment.organization_id, employee.organization_id) = v_cycle.scope_organization_id)
      and not exists (
        select 1
        from public.hr_compensation_review_item existing_item
        join public.hr_compensation_review_cycle existing_cycle
          on existing_cycle.id = existing_item.cycle_id
         and existing_cycle.tenant_id = existing_item.tenant_id
        where existing_item.tenant_id = employee.tenant_id
          and existing_item.employee_id = employee.id
          and existing_cycle.effective_date = v_cycle.effective_date
          and existing_cycle.id <> v_cycle.id
          and existing_cycle.status not in ('cancelled', 'effected')
      )
    on conflict (cycle_id, employee_id) do nothing;
    get diagnostics v_inserted = row_count;
    if v_inserted = 0 and not exists (
      select 1 from public.hr_compensation_review_item where cycle_id = v_cycle.id
    ) then raise exception '当前范围没有已生效薪酬的在职员工可进入复核'; end if;

    insert into public.hr_compensation_review_budget(
      tenant_id, cycle_id, organization_id, budget_amount, source, note
    )
    select
      item.tenant_id,
      item.cycle_id,
      item.organization_id,
      round(sum(item.current_base_amount) * v_cycle.default_budget_percent / 100, 2),
      'auto',
      '按周期默认预算率自动生成'
    from public.hr_compensation_review_item item
    where item.cycle_id = v_cycle.id
    group by item.tenant_id, item.cycle_id, item.organization_id
    on conflict (cycle_id, organization_id) do update set
      budget_amount = case
        when public.hr_compensation_review_budget.source = 'auto' then excluded.budget_amount
        else public.hr_compensation_review_budget.budget_amount
      end,
      note = case
        when public.hr_compensation_review_budget.source = 'auto' then excluded.note
        else public.hr_compensation_review_budget.note
      end;

    update public.hr_compensation_review_cycle
    set status = 'open', opened_at = now() where id = v_cycle.id;
    return true;
  end if;

  if p_action = 'calibrate' then
    if v_cycle.status <> 'open' then raise exception '只有建议开放中的周期可以进入校准'; end if;
    if exists (
      select 1 from public.hr_compensation_review_item
      where cycle_id = v_cycle.id and status = 'pending'
    ) then raise exception '仍有员工未提交调薪建议或排除说明'; end if;
    perform app_private.hr_validate_compensation_review_budget(v_cycle.id);
    update public.hr_compensation_review_item set
      status = 'calibrated',
      calibrated_by = coalesce(calibrated_by, v_actor),
      calibrated_at = coalesce(calibrated_at, now())
    where cycle_id = v_cycle.id and status = 'recommended';
    update public.hr_compensation_review_cycle set status = 'calibrating' where id = v_cycle.id;
    return true;
  end if;

  if p_action = 'approve' then
    if v_cycle.status <> 'calibrating' then raise exception '只有校准中的周期可以批准'; end if;
    if nullif(btrim(p_comment), '') is null then raise exception '批准调薪必须填写审批结论'; end if;
    if exists (
      select 1 from public.hr_compensation_review_item
      where cycle_id = v_cycle.id and status not in ('calibrated', 'excluded')
    ) then raise exception '仍有员工尚未完成校准'; end if;
    perform app_private.hr_validate_compensation_review_budget(v_cycle.id);
    update public.hr_compensation_review_item set
      status = 'approved', approved_by = v_actor, approved_at = now()
    where cycle_id = v_cycle.id and status = 'calibrated';
    update public.hr_compensation_review_cycle set
      status = 'approved', decision_note = btrim(p_comment), approved_at = now()
    where id = v_cycle.id;
    return true;
  end if;

  if p_action = 'effect' then
    if v_cycle.status <> 'approved' then raise exception '只有已批准周期可以批量生效'; end if;
    if v_cycle.effective_date > current_date then
      raise exception '调薪生效日尚未到达，不能提前写入员工薪酬历史';
    end if;
    perform app_private.hr_validate_compensation_review_budget(v_cycle.id);

    for v_item in
      select * from public.hr_compensation_review_item
      where cycle_id = v_cycle.id and status = 'approved'
      order by employee_id
      for update
    loop
      if v_item.proposed_base_amount = v_item.current_base_amount then
        update public.hr_compensation_review_item set status = 'effected'
        where id = v_item.id;
        continue;
      end if;

      if exists (
        select 1 from public.hr_employee_compensation existing_compensation
        where existing_compensation.tenant_id = v_item.tenant_id
          and existing_compensation.employee_id = v_item.employee_id
          and existing_compensation.status = 'approved'
          and existing_compensation.id <> v_item.current_compensation_id
          and existing_compensation.effective_from <= v_cycle.effective_date
          and coalesce(existing_compensation.effective_to, 'infinity'::date) >= v_cycle.effective_date
      ) then raise exception '员工 % 在生效日已有其他薪酬版本，请刷新周期快照后再处理', v_item.employee_id; end if;

      perform 1 from public.hr_employee_compensation current_compensation
      where current_compensation.id = v_item.current_compensation_id
        and current_compensation.tenant_id = v_item.tenant_id
        and current_compensation.employee_id = v_item.employee_id
        and current_compensation.status = 'approved'
        and current_compensation.base_amount = v_item.current_base_amount
        and current_compensation.effective_from < v_cycle.effective_date
        and coalesce(current_compensation.effective_to, 'infinity'::date) >= v_cycle.effective_date
      for update;
      if not found then raise exception '员工 % 的当前薪酬已发生变化，本次调薪不能自动生效', v_item.employee_id; end if;

      update public.hr_employee_compensation
      set effective_to = v_cycle.effective_date - 1
      where id = v_item.current_compensation_id;

      insert into public.hr_employee_compensation(
        tenant_id, employee_id, plan_id, grade_id, base_amount, currency_code,
        pay_frequency, effective_from, effective_to, status, change_reason,
        source_review_item_id, approved_by, approved_at
      )
      select
        current_compensation.tenant_id,
        current_compensation.employee_id,
        current_compensation.plan_id,
        current_compensation.grade_id,
        v_item.proposed_base_amount,
        current_compensation.currency_code,
        current_compensation.pay_frequency,
        v_cycle.effective_date,
        null,
        'approved',
        '调薪复核：' || v_cycle.cycle_name,
        v_item.id,
        v_actor,
        now()
      from public.hr_employee_compensation current_compensation
      where current_compensation.id = v_item.current_compensation_id
      returning id into v_new_compensation_id;

      insert into public.hr_employee_compensation_item(
        tenant_id, compensation_id, component_id, amount, rate, source
      )
      select
        current_item.tenant_id,
        v_new_compensation_id,
        current_item.component_id,
        current_item.amount,
        current_item.rate,
        current_item.source
      from public.hr_employee_compensation_item current_item
      where current_item.compensation_id = v_item.current_compensation_id;

      update public.hr_compensation_review_item set
        status = 'effected', new_compensation_id = v_new_compensation_id
      where id = v_item.id;
    end loop;

    update public.hr_compensation_review_cycle
    set status = 'effected', effected_at = now(),
      decision_note = concat_ws(E'\n', decision_note, nullif(btrim(p_comment), ''))
    where id = v_cycle.id;
    return true;
  end if;

  if v_cycle.status not in ('draft', 'open') then raise exception '当前阶段不能取消调薪周期'; end if;
  if nullif(btrim(p_comment), '') is null then raise exception '取消周期必须填写原因'; end if;
  update public.hr_compensation_review_item set
    status = 'excluded', exclusion_reason = '周期取消：' || btrim(p_comment)
  where cycle_id = v_cycle.id and status <> 'excluded';
  update public.hr_compensation_review_cycle set
    status = 'cancelled', decision_note = btrim(p_comment)
  where id = v_cycle.id;
  return true;
end;
$$;


ALTER FUNCTION "public"."hr_transition_compensation_review_cycle_secure"("p_id" "uuid", "p_action" "text", "p_comment" "text") OWNER TO "postgres";

--

--
-- Name: hr_transition_compliance_record_secure("text", "uuid", "text", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_transition_compliance_record_secure"("p_kind" "text", "p_id" "uuid", "p_action" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_contract public.hr_employee_contract;
  v_qualification public.hr_employee_qualification;
  v_new_contract_id uuid;
  v_comment text := nullif(btrim(p_payload->>'comment'), '');
  v_new_status text;
begin
  if p_kind = 'contract' then
    select * into v_contract from public.hr_employee_contract contract
    where contract.id = p_id
      and (app_private.is_platform_super() or contract.tenant_id = v_tenant_id)
    for update;
    if not found then raise exception '劳动合同不存在或无权处理' using errcode = '42501'; end if;

    if p_action = 'activate' then
      if not app_private.can_execute_business_action(
        'HrCompliance', 'Hr:Compliance:Edit', p_id, false
      ) then raise exception '当前账号没有使合同生效的权限' using errcode = '42501'; end if;
      if v_contract.contract_status <> 'draft' then raise exception '只有待签署合同可以生效'; end if;
      update public.hr_employee_contract set contract_status = 'active' where id = p_id;
      perform app_private.hr_add_compliance_event(
        v_contract.tenant_id, 'contract', p_id, 'activated', 'draft', 'active',
        coalesce(v_comment, '劳动合同已确认生效'), '{}'::jsonb
      );
      return p_id;
    elsif p_action = 'start_renewal' then
      if not app_private.can_execute_business_action(
        'HrCompliance', 'Hr:Compliance:Contract:Renew', p_id, false
      ) then raise exception '当前账号没有启动合同续签的权限' using errcode = '42501'; end if;
      if v_contract.contract_status <> 'active' or v_contract.end_date is null then
        raise exception '只有存在结束日期的生效中合同可以启动续签';
      end if;
      if nullif(p_payload->>'renewal_owner_id', '') is not null and not exists (
        select 1 from public.mdm_employee employee
        where employee.id = (p_payload->>'renewal_owner_id')::uuid
          and employee.tenant_id = v_contract.tenant_id
      ) then raise exception '请选择当前租户内的续签负责人'; end if;
      update public.hr_employee_contract set
        contract_status = 'renewing', renewal_decision = 'pending',
        renewal_started_at = now(),
        renewal_owner_id = coalesce(nullif(p_payload->>'renewal_owner_id', '')::uuid,
          renewal_owner_id)
      where id = p_id;
      perform app_private.hr_add_compliance_event(
        v_contract.tenant_id, 'contract', p_id, 'renewal_started', 'active', 'renewing',
        coalesce(v_comment, '已启动合同续签决策'), '{}'::jsonb
      );
      return p_id;
    elsif p_action = 'renew' then
      if not app_private.can_execute_business_action(
        'HrCompliance', 'Hr:Compliance:Contract:Renew', p_id, false
      ) then raise exception '当前账号没有完成合同续签的权限' using errcode = '42501'; end if;
      if v_contract.contract_status not in ('active', 'renewing') then
        raise exception '当前合同状态不能办理续签';
      end if;
      if nullif(btrim(p_payload->>'contract_no'), '') is null
        or nullif(p_payload->>'start_date', '') is null
        or nullif(btrim(p_payload->>'contract_type'), '') is null then
        raise exception '请完整填写新合同编号、类型和开始日期';
      end if;
      if (p_payload->>'start_date')::date <= v_contract.start_date then
        raise exception '新合同开始日期必须晚于原合同开始日期';
      end if;
      if nullif(p_payload->>'end_date', '') is not null
        and (p_payload->>'end_date')::date < (p_payload->>'start_date')::date then
        raise exception '新合同结束日期不能早于开始日期';
      end if;
      insert into public.hr_employee_contract(
        tenant_id, employee_id, contract_no, contract_type, contract_status,
        sign_date, start_date, end_date, probation_end_date, work_location,
        monthly_salary, renewal_reminder_days, renewal_owner_id,
        previous_contract_id, attachment_url, remark
      ) values (
        v_contract.tenant_id, v_contract.employee_id, btrim(p_payload->>'contract_no'),
        p_payload->>'contract_type',
        case when p_payload->>'contract_status' = 'draft' then 'draft' else 'active' end,
        nullif(p_payload->>'sign_date', '')::date,
        (p_payload->>'start_date')::date, nullif(p_payload->>'end_date', '')::date,
        nullif(p_payload->>'probation_end_date', '')::date,
        coalesce(nullif(btrim(p_payload->>'work_location'), ''), v_contract.work_location),
        coalesce(nullif(p_payload->>'monthly_salary', '')::numeric, v_contract.monthly_salary),
        coalesce(nullif(p_payload->>'renewal_reminder_days', '')::integer,
          v_contract.renewal_reminder_days),
        coalesce(nullif(p_payload->>'renewal_owner_id', '')::uuid, v_contract.renewal_owner_id),
        v_contract.id, nullif(btrim(p_payload->>'attachment_url'), ''),
        nullif(btrim(p_payload->>'remark'), '')
      ) returning id, contract_status into v_new_contract_id, v_new_status;
      update public.hr_employee_contract set
        contract_status = 'renewed', renewal_decision = 'completed', renewed_at = now()
      where id = p_id;
      perform app_private.hr_add_compliance_event(
        v_contract.tenant_id, 'contract', p_id, 'renewed',
        v_contract.contract_status, 'renewed', coalesce(v_comment, '已创建续签合同'),
        jsonb_build_object('new_contract_id', v_new_contract_id)
      );
      perform app_private.hr_add_compliance_event(
        v_contract.tenant_id, 'contract', v_new_contract_id, 'created', null, v_new_status,
        '由合同续签创建', jsonb_build_object('previous_contract_id', p_id)
      );
      return v_new_contract_id;
    elsif p_action = 'terminate' then
      if not app_private.can_execute_business_action(
        'HrCompliance', 'Hr:Compliance:Contract:Terminate', p_id, false
      ) then raise exception '当前账号没有终止合同的权限' using errcode = '42501'; end if;
      if v_contract.contract_status not in ('draft', 'active', 'renewing') then
        raise exception '当前合同状态不能终止';
      end if;
      if nullif(p_payload->>'termination_date', '') is null or v_comment is null then
        raise exception '终止合同必须填写终止日期和原因';
      end if;
      if (p_payload->>'termination_date')::date < v_contract.start_date then
        raise exception '终止日期不能早于合同开始日期';
      end if;
      update public.hr_employee_contract set
        contract_status = 'terminated', renewal_decision = 'completed',
        termination_date = (p_payload->>'termination_date')::date,
        termination_reason = v_comment
      where id = p_id;
      perform app_private.hr_add_compliance_event(
        v_contract.tenant_id, 'contract', p_id, 'terminated',
        v_contract.contract_status, 'terminated', v_comment,
        jsonb_build_object('termination_date', p_payload->>'termination_date')
      );
      return p_id;
    elsif p_action = 'comment' then
      if not app_private.can_execute_business_action(
        'HrCompliance', 'Hr:Compliance:Edit', p_id, false
      ) then raise exception '当前账号没有补充合同说明的权限' using errcode = '42501'; end if;
      if v_comment is null then raise exception '请输入补充说明'; end if;
      perform app_private.hr_add_compliance_event(
        v_contract.tenant_id, 'contract', p_id, 'commented',
        v_contract.contract_status, v_contract.contract_status, v_comment, '{}'::jsonb
      );
      return p_id;
    end if;
  elsif p_kind = 'qualification' then
    select * into v_qualification from public.hr_employee_qualification qualification
    where qualification.id = p_id
      and (app_private.is_platform_super() or qualification.tenant_id = v_tenant_id)
    for update;
    if not found then raise exception '员工资质不存在或无权处理' using errcode = '42501'; end if;

    if p_action in ('verify', 'reject') then
      if not app_private.can_execute_business_action(
        'HrCompliance', 'Hr:Compliance:Qualification:Verify', p_id, false
      ) then raise exception '当前账号没有核验员工资质的权限' using errcode = '42501'; end if;
      if v_qualification.status = 'revoked' then raise exception '已撤销资质不能核验'; end if;
      if p_action = 'reject' and v_comment is null then raise exception '核验驳回必须填写原因'; end if;
      update public.hr_employee_qualification set
        verification_status = case when p_action = 'verify' then 'verified' else 'rejected' end,
        verified_by_employee_id = case when p_action = 'verify'
          then app_private.hr_current_employee_id() else null end,
        verified_at = case when p_action = 'verify' then now() else null end,
        verification_note = v_comment
      where id = p_id;
      perform app_private.hr_add_compliance_event(
        v_qualification.tenant_id, 'qualification', p_id,
        case when p_action = 'verify' then 'verified' else 'verification_rejected' end,
        v_qualification.verification_status,
        case when p_action = 'verify' then 'verified' else 'rejected' end,
        coalesce(v_comment, '员工资质核验通过'), '{}'::jsonb
      );
      return p_id;
    elsif p_action = 'revoke' then
      if not app_private.can_execute_business_action(
        'HrCompliance', 'Hr:Compliance:Qualification:Revoke', p_id, false
      ) then raise exception '当前账号没有撤销员工资质的权限' using errcode = '42501'; end if;
      if v_qualification.status = 'revoked' then raise exception '员工资质已经撤销'; end if;
      if v_comment is null then raise exception '撤销资质必须填写原因'; end if;
      update public.hr_employee_qualification set
        status = 'revoked', revoked_at = now(), revocation_reason = v_comment
      where id = p_id;
      perform app_private.hr_add_compliance_event(
        v_qualification.tenant_id, 'qualification', p_id, 'revoked',
        v_qualification.status, 'revoked', v_comment, '{}'::jsonb
      );
      return p_id;
    elsif p_action = 'comment' then
      if not app_private.can_execute_business_action(
        'HrCompliance', 'Hr:Compliance:Edit', p_id, false
      ) then raise exception '当前账号没有补充资质说明的权限' using errcode = '42501'; end if;
      if v_comment is null then raise exception '请输入补充说明'; end if;
      perform app_private.hr_add_compliance_event(
        v_qualification.tenant_id, 'qualification', p_id, 'commented',
        v_qualification.status, v_qualification.status, v_comment, '{}'::jsonb
      );
      return p_id;
    end if;
  else
    raise exception '不支持的用工合规记录类型';
  end if;
  raise exception '当前记录不支持此操作';
exception
  when unique_violation then raise exception '续签合同编号已存在，请检查后重试';
end
$$;


ALTER FUNCTION "public"."hr_transition_compliance_record_secure"("p_kind" "text", "p_id" "uuid", "p_action" "text", "p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: hr_transition_contingent_workforce_record_secure("text", "uuid", "text", "text", "date"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_transition_contingent_workforce_record_secure"("p_kind" "text", "p_id" "uuid", "p_action" "text", "p_comment" "text" DEFAULT NULL::"text", "p_effective_date" "date" DEFAULT NULL::"date") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    SET "TimeZone" TO 'Asia/Shanghai'
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_vendor public.mdm_external_vendor%rowtype;
  v_worker public.hr_external_worker%rowtype;
  v_engagement public.hr_external_engagement%rowtype;
  v_action_permission text;
  v_exit_date date := coalesce(p_effective_date, current_date);
begin
  if p_kind not in ('vendor', 'worker', 'engagement') then
    raise exception '不支持的外部用工流转类型';
  end if;
  v_action_permission := case
    when p_kind = 'vendor' then 'Hr:ContingentWorkforce:Vendor:Manage'
    when p_kind = 'worker' then 'Hr:ContingentWorkforce:Worker:Manage'
    when p_action = 'activate' then 'Hr:ContingentWorkforce:Activate'
    when p_action in ('begin_exit', 'end') then 'Hr:ContingentWorkforce:End'
    else 'Hr:ContingentWorkforce:Engagement:Manage'
  end;
  if auth.uid() is null or not app_private.can_execute_business_action(
    'HrContingentWorkforce', v_action_permission, null, false
  ) then
    raise exception '当前账号没有执行此外部用工流转的权限' using errcode = '42501';
  end if;

  if p_kind = 'vendor' then
    select * into v_vendor from public.mdm_external_vendor
    where id = p_id and (app_private.is_platform_super() or tenant_id = v_tenant_id) for update;
    if not found then raise exception '供应商不存在或不属于当前租户'; end if;

    if p_action = 'verify' and v_vendor.compliance_status in ('pending', 'rejected', 'expired') then
      update public.mdm_external_vendor set compliance_status = 'verified', note = coalesce(nullif(btrim(p_comment), ''), note)
      where id = p_id;
    elsif p_action = 'activate' and v_vendor.status in ('draft', 'suspended', 'inactive') then
      if v_vendor.compliance_status <> 'verified' then raise exception '供应商合规审核未通过'; end if;
      if v_vendor.contract_start_date is null or v_vendor.contract_end_date is null
         or current_date not between v_vendor.contract_start_date and v_vendor.contract_end_date then
        raise exception '供应商合同不在有效期内';
      end if;
      update public.mdm_external_vendor set status = 'active', note = coalesce(nullif(btrim(p_comment), ''), note)
      where id = p_id;
    elsif p_action = 'suspend' and v_vendor.status = 'active' then
      update public.mdm_external_vendor set status = 'suspended', note = coalesce(nullif(btrim(p_comment), ''), note)
      where id = p_id;
    elsif p_action = 'deactivate' and v_vendor.status in ('draft', 'suspended', 'expired') then
      if exists (select 1 from public.hr_external_engagement where vendor_id = p_id and status = 'active') then
        raise exception '供应商仍有在场用工任务，不能停用';
      end if;
      update public.mdm_external_vendor set status = 'inactive', note = coalesce(nullif(btrim(p_comment), ''), note)
      where id = p_id;
    else
      raise exception '供应商当前状态不支持此操作';
    end if;
  elsif p_kind = 'worker' then
    select * into v_worker from public.hr_external_worker
    where id = p_id and (app_private.is_platform_super() or tenant_id = v_tenant_id) for update;
    if not found then raise exception '外部人员不存在或不属于当前租户'; end if;

    if p_action = 'verify_identity' and v_worker.status in ('candidate', 'ready') then
      update public.hr_external_worker set identity_check_status = 'passed', status = 'ready',
        note = coalesce(nullif(btrim(p_comment), ''), note) where id = p_id;
    elsif p_action = 'block' and v_worker.status <> 'blocked' then
      if nullif(btrim(p_comment), '') is null then raise exception '锁定外部人员必须填写原因'; end if;
      update public.hr_external_worker set status = 'blocked', note = btrim(p_comment) where id = p_id;
      update public.hr_external_engagement set compliance_status = 'blocked', version = version + 1
      where worker_id = p_id and status in ('draft', 'pending_review', 'active');
    elsif p_action = 'unblock' and v_worker.status = 'blocked' then
      update public.hr_external_worker set status = case when identity_check_status = 'passed' then 'ready' else 'candidate' end,
        note = coalesce(nullif(btrim(p_comment), ''), note) where id = p_id;
    else
      raise exception '外部人员当前状态不支持此操作';
    end if;
  else
    select * into v_engagement from public.hr_external_engagement
    where id = p_id and (app_private.is_platform_super() or tenant_id = v_tenant_id) for update;
    if not found then raise exception '用工任务不存在或不属于当前租户'; end if;
    select * into v_worker from public.hr_external_worker where id = v_engagement.worker_id for update;

    if p_action = 'submit' and v_engagement.status = 'draft' then
      update public.hr_external_engagement set status = 'pending_review', version = version + 1,
        activation_note = coalesce(nullif(btrim(p_comment), ''), activation_note) where id = p_id;
    elsif p_action = 'activate' and v_engagement.status = 'pending_review' then
      if v_worker.status = 'blocked' or v_worker.identity_check_status <> 'passed' then
        raise exception '外部人员身份核验未通过或已锁定';
      end if;
      if v_engagement.vendor_id is not null then
        select * into v_vendor from public.mdm_external_vendor where id = v_engagement.vendor_id;
        if v_vendor.status <> 'active' or v_vendor.compliance_status <> 'verified' then
          raise exception '关联供应商未处于合规有效状态';
        end if;
        if v_vendor.contract_start_date is null or v_vendor.contract_end_date is null
           or v_engagement.start_date < v_vendor.contract_start_date
           or v_engagement.end_date > v_vendor.contract_end_date then
          raise exception '用工任务周期超出供应商合同有效期';
        end if;
      elsif v_worker.worker_type in ('outsourced', 'dispatch') then
        raise exception '外包或劳务派遣任务必须关联供应商';
      end if;
      if exists (
        select 1 from public.hr_external_engagement_control control
        where control.engagement_id = p_id and control.required
          and control.status not in ('completed', 'waived')
      ) then
        raise exception '仍有必需准入控制项未完成';
      end if;
      if exists (
        select 1 from public.hr_external_engagement_control control
        where control.engagement_id = p_id and control.status = 'failed'
      ) then
        raise exception '存在失败的准入控制项';
      end if;
      update public.hr_external_engagement set status = 'active', compliance_status = 'cleared',
        activation_note = coalesce(nullif(btrim(p_comment), ''), activation_note), version = version + 1
      where id = p_id;
      update public.hr_external_worker set status = 'active' where id = v_engagement.worker_id;
    elsif p_action = 'begin_exit' and v_engagement.status = 'active' then
      update public.hr_external_engagement set status = 'offboarding', end_reason = nullif(btrim(p_comment), ''),
        version = version + 1 where id = p_id;
      insert into public.hr_external_engagement_control(
        tenant_id, engagement_id, control_type, control_name, required, due_date
      ) values
        (v_engagement.tenant_id, p_id, 'access_badge', '门禁卡与现场权限回收', true, v_exit_date),
        (v_engagement.tenant_id, p_id, 'system_account', '系统账号停用', true, v_exit_date),
        (v_engagement.tenant_id, p_id, 'equipment', '公司设备与资产归还', true, v_exit_date)
      on conflict (engagement_id, lower(control_name)) do nothing;
    elsif p_action = 'end' and v_engagement.status in ('active', 'offboarding') then
      if nullif(btrim(p_comment), '') is null then raise exception '退场必须填写原因'; end if;
      if exists (
        select 1 from public.hr_external_engagement_control control
        where control.engagement_id = p_id and control.required
          and control.control_name in ('门禁卡与现场权限回收', '系统账号停用', '公司设备与资产归还')
          and control.status not in ('completed', 'waived')
      ) then
        raise exception '退场控制项尚未全部完成';
      end if;
      update public.hr_external_engagement set status = 'ended', actual_exit_date = v_exit_date,
        access_expiry_date = least(access_expiry_date, v_exit_date), end_reason = btrim(p_comment),
        version = version + 1 where id = p_id;
      if not exists (
        select 1 from public.hr_external_engagement engagement
        where engagement.worker_id = v_engagement.worker_id and engagement.id <> p_id
          and engagement.status = 'active'
      ) then
        update public.hr_external_worker set status = 'inactive' where id = v_engagement.worker_id;
      end if;
    elsif p_action = 'cancel' and v_engagement.status in ('draft', 'pending_review') then
      update public.hr_external_engagement set status = 'cancelled', end_reason = nullif(btrim(p_comment), ''),
        version = version + 1 where id = p_id;
    else
      raise exception '用工任务当前状态不支持此操作';
    end if;
  end if;

  return true;
end;
$$;


ALTER FUNCTION "public"."hr_transition_contingent_workforce_record_secure"("p_kind" "text", "p_id" "uuid", "p_action" "text", "p_comment" "text", "p_effective_date" "date") OWNER TO "postgres";

--

--
-- Name: hr_transition_employee_experience_record_secure("text", "uuid", "text", "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_transition_employee_experience_record_secure"("p_kind" "text", "p_id" "uuid", "p_action" "text", "p_comment" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_survey public.hr_experience_survey;
  v_action public.hr_experience_action;
  v_target_status text;
  v_participant_count integer;
begin
  if auth.uid() is null then raise exception '请先登录' using errcode = '42501'; end if;
  if p_kind = 'survey' then
    if not app_private.can_execute_business_action(
      'HrEmployeeExperience', 'Hr:Experience:Launch', p_id, false
    ) then raise exception '当前账号没有发布或关闭调查的权限' using errcode = '42501'; end if;
    select * into v_survey from public.hr_experience_survey survey
      where survey.id = p_id and (app_private.is_platform_super() or survey.tenant_id = v_tenant_id)
      for update;
    if v_survey.id is null then raise exception '调查不存在或无权处理'; end if;
    if p_action = 'launch' and v_survey.status = 'draft' then
      if v_survey.end_date < current_date then raise exception '调查结束日期已过，不能发布'; end if;
      if not exists (select 1 from public.hr_experience_question question
        where question.survey_id = p_id and question.tenant_id = v_survey.tenant_id
          and question.enabled and question.answer_type in ('rating_5', 'enps_11')) then
        raise exception '至少维护一道启用的量表题后才能发布调查';
      end if;
      with recursive organization_scope(id) as (
        select v_survey.audience_organization_id
        where v_survey.audience_type = 'organization'
        union all
        select child.id from public.mdm_organization child
        join organization_scope parent on child.parent_id = parent.id
        where child.tenant_id = v_survey.tenant_id and child.status = '1'
      )
      insert into public.hr_experience_participant(
        tenant_id, survey_id, employee_id, organization_snapshot_id, status, assigned_on
      )
      select employee.tenant_id, v_survey.id, employee.id, employee.organization_id,
        'invited', current_date
      from public.mdm_employee employee
      where employee.tenant_id = v_survey.tenant_id
        and employee.organization_id is not null
        and employee.employment_status not in ('left', 'terminated')
        and (v_survey.audience_type = 'all_active'
          or employee.organization_id in (select id from organization_scope))
      on conflict (survey_id, employee_id) do nothing;
      select count(*) into v_participant_count from public.hr_experience_participant participant
        where participant.survey_id = p_id and participant.tenant_id = v_survey.tenant_id;
      if v_participant_count < v_survey.minimum_group_size then
        raise exception '符合条件的员工少于匿名汇报阈值 % 人，不能发布调查',
          v_survey.minimum_group_size;
      end if;
      v_target_status := case when v_survey.start_date > current_date then 'scheduled' else 'open' end;
      update public.hr_experience_survey set status = v_target_status, launched_at = now()
        where id = p_id;
      perform app_private.hr_add_experience_event(v_survey.tenant_id, 'survey', p_id,
        'launched', 'draft', v_target_status, '发布员工体验调查',
        jsonb_build_object('participant_count', v_participant_count,
          'minimum_group_size', v_survey.minimum_group_size));
    elsif p_action = 'open' and v_survey.status = 'scheduled' then
      if current_date < v_survey.start_date or current_date > v_survey.end_date then
        raise exception '当前日期不在调查开放周期内';
      end if;
      update public.hr_experience_survey set status = 'open' where id = p_id;
      perform app_private.hr_add_experience_event(v_survey.tenant_id, 'survey', p_id,
        'opened', 'scheduled', 'open', '开放员工体验调查');
    elsif p_action = 'close' and v_survey.status in ('scheduled', 'open') then
      update public.hr_experience_survey set status = 'closed', closed_at = now() where id = p_id;
      perform app_private.hr_add_experience_event(v_survey.tenant_id, 'survey', p_id,
        'closed', v_survey.status, 'closed', '关闭员工体验调查');
    elsif p_action = 'cancel' and v_survey.status in ('draft', 'scheduled', 'open') then
      update public.hr_experience_survey set status = 'cancelled', closed_at = now() where id = p_id;
      perform app_private.hr_add_experience_event(v_survey.tenant_id, 'survey', p_id,
        'cancelled', v_survey.status, 'cancelled', '取消员工体验调查',
        jsonb_build_object('comment', nullif(btrim(p_comment), '')));
    else
      raise exception '当前状态不允许执行该调查动作';
    end if;
  elsif p_kind = 'action' then
    select * into v_action from public.hr_experience_action action
      where action.id = p_id and (app_private.is_platform_super() or action.tenant_id = v_tenant_id)
      for update;
    if v_action.id is null then raise exception '改进行动不存在或无权处理'; end if;
    if p_action = 'start' then
      if not app_private.can_execute_business_action(
        'HrEmployeeExperience', 'Hr:Experience:Action:Manage', p_id, false
      ) or v_action.status <> 'planned' then raise exception '当前改进行动不能启动'; end if;
      update public.hr_experience_action set status = 'in_progress', started_at = now(),
        progress_note = coalesce(nullif(btrim(p_comment), ''), progress_note) where id = p_id;
      perform app_private.hr_add_experience_event(v_action.tenant_id, 'action', p_id,
        'started', 'planned', 'in_progress', '启动员工体验改进行动');
    elsif p_action = 'complete' then
      if not app_private.can_execute_business_action(
        'HrEmployeeExperience', 'Hr:Experience:Action:Close', p_id, false
      ) or v_action.status <> 'in_progress' or nullif(btrim(p_comment), '') is null then
        raise exception '验收进行中的行动时必须填写结果总结';
      end if;
      update public.hr_experience_action set status = 'completed', completed_at = now(),
        result_summary = btrim(p_comment) where id = p_id;
      perform app_private.hr_add_experience_event(v_action.tenant_id, 'action', p_id,
        'completed', 'in_progress', 'completed', '验收员工体验改进行动');
    elsif p_action = 'cancel' then
      if not app_private.can_execute_business_action(
        'HrEmployeeExperience', 'Hr:Experience:Action:Manage', p_id, false
      ) or v_action.status not in ('planned', 'in_progress') or nullif(btrim(p_comment), '') is null then
        raise exception '取消未完成行动时必须填写原因';
      end if;
      update public.hr_experience_action set status = 'cancelled',
        progress_note = btrim(p_comment) where id = p_id;
      perform app_private.hr_add_experience_event(v_action.tenant_id, 'action', p_id,
        'cancelled', v_action.status, 'cancelled', '取消员工体验改进行动',
        jsonb_build_object('comment', btrim(p_comment)));
    else
      raise exception '当前状态不允许执行该行动动作';
    end if;
  else
    raise exception '不支持的员工体验记录类型';
  end if;
  return true;
end
$$;


ALTER FUNCTION "public"."hr_transition_employee_experience_record_secure"("p_kind" "text", "p_id" "uuid", "p_action" "text", "p_comment" "text") OWNER TO "postgres";

--

--
-- Name: hr_transition_employee_relation_action_secure("uuid", "text", "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_transition_employee_relation_action_secure"("p_id" "uuid", "p_action" "text", "p_comment" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_action public.hr_employee_relation_action;
  v_case public.hr_employee_relation_case;
  v_from text;
  v_comment text := nullif(btrim(p_comment), '');
  v_event_type text;
begin
  if not app_private.has_permission('Hr:EmployeeRelations:Action:Manage') then
    raise exception '当前账号没有管理员工关系处置行动的权限' using errcode = '42501';
  end if;
  select * into v_action from public.hr_employee_relation_action where id = p_id for update;
  if v_action.id is null then raise exception '处置行动不存在'; end if;
  select * into v_case from public.hr_employee_relation_case where id = v_action.case_id;
  if not app_private.hr_employee_relation_case_visible(
    v_case.tenant_id, v_case.subject_employee_id, v_case.reporter_employee_id,
    v_case.owner_employee_id
  ) then
    raise exception '处置行动不存在或无权处理' using errcode = '42501';
  end if;
  v_from := v_action.status;
  if p_action = 'start' and v_action.status = 'planned' then
    update public.hr_employee_relation_action set status = 'in_progress', started_at = now()
      where id = v_action.id returning * into v_action;
    v_event_type := 'action_started';
  elsif p_action = 'complete' and v_action.status in ('planned', 'in_progress') then
    if v_comment is null then raise exception '完成处置行动必须填写完成说明'; end if;
    update public.hr_employee_relation_action set
      status = 'completed', started_at = coalesce(started_at, now()),
      completed_at = now(), completion_note = v_comment
    where id = v_action.id returning * into v_action;
    v_event_type := 'action_completed';
  elsif p_action = 'cancel' and v_action.status in ('planned', 'in_progress') then
    if v_comment is null then raise exception '取消处置行动必须填写原因'; end if;
    update public.hr_employee_relation_action set status = 'cancelled', completion_note = v_comment
      where id = v_action.id returning * into v_action;
    v_event_type := 'action_cancelled';
  else
    raise exception '当前处置行动不能执行该动作';
  end if;
  perform app_private.hr_add_employee_relation_event(
    v_case, v_event_type, v_case.status, v_case.status, v_comment,
    jsonb_build_object('action_id', v_action.id, 'from_action_status', v_from,
      'to_action_status', v_action.status)
  );
  return true;
end
$$;


ALTER FUNCTION "public"."hr_transition_employee_relation_action_secure"("p_id" "uuid", "p_action" "text", "p_comment" "text") OWNER TO "postgres";

--

--
-- Name: hr_transition_employee_relation_case_secure("uuid", "text", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_transition_employee_relation_case_secure"("p_id" "uuid", "p_action" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_case public.hr_employee_relation_case;
  v_from text;
  v_comment text := nullif(btrim(p_payload->>'comment'), '');
begin
  select * into v_case from public.hr_employee_relation_case where id = p_id for update;
  if v_case.id is null or not app_private.hr_employee_relation_case_visible(
    v_case.tenant_id, v_case.subject_employee_id, v_case.reporter_employee_id,
    v_case.owner_employee_id
  ) then
    raise exception '员工关系案件不存在或无权处理' using errcode = '42501';
  end if;
  v_from := v_case.status;

  if p_action = 'submit' then
    if not app_private.has_permission('Hr:EmployeeRelations:Edit') or v_case.status <> 'draft' then
      raise exception '当前案件不能提交报告';
    end if;
    update public.hr_employee_relation_case set status = 'reported', reported_at = now()
      where id = v_case.id returning * into v_case;
    perform app_private.hr_add_employee_relation_event(
      v_case, 'reported', v_from, v_case.status, v_comment
    );
  elsif p_action = 'triage' then
    if not app_private.has_permission('Hr:EmployeeRelations:Assign')
      or v_case.status not in ('reported', 'triaged') then
      raise exception '当前案件不能执行分派与分级';
    end if;
    if nullif(p_payload->>'owner_employee_id', '') is null
      or nullif(p_payload->>'target_resolution_date', '') is null then
      raise exception '分级时必须指定案件负责人和目标解决日期';
    end if;
    update public.hr_employee_relation_case set
      status = 'triaged', owner_employee_id = (p_payload->>'owner_employee_id')::uuid,
      severity = coalesce(nullif(p_payload->>'severity', ''), severity),
      confidentiality_level = coalesce(
        nullif(p_payload->>'confidentiality_level', ''), confidentiality_level
      ),
      target_resolution_date = (p_payload->>'target_resolution_date')::date,
      triaged_at = coalesce(triaged_at, now())
    where id = v_case.id returning * into v_case;
    perform app_private.hr_add_employee_relation_event(
      v_case, case when v_from = 'reported' then 'triaged' else 'assigned' end,
      v_from, v_case.status, v_comment,
      jsonb_build_object('owner_employee_id', v_case.owner_employee_id)
    );
  elsif p_action = 'start_investigation' then
    if not app_private.has_permission('Hr:EmployeeRelations:Investigate')
      or v_case.status <> 'triaged' then
      raise exception '只有已分级案件可以启动调查';
    end if;
    update public.hr_employee_relation_case set
      status = 'investigating', investigation_started_at = now()
    where id = v_case.id returning * into v_case;
    perform app_private.hr_add_employee_relation_event(
      v_case, 'investigation_started', v_from, v_case.status, v_comment
    );
  elsif p_action = 'require_action' then
    if not app_private.has_permission('Hr:EmployeeRelations:Investigate')
      or v_case.status <> 'investigating' then
      raise exception '只有调查中案件可以进入处置阶段';
    end if;
    if nullif(btrim(p_payload->>'findings_summary'), '') is null then
      raise exception '进入处置阶段前必须填写调查发现';
    end if;
    update public.hr_employee_relation_case set
      status = 'action_required', findings_summary = btrim(p_payload->>'findings_summary')
    where id = v_case.id returning * into v_case;
    perform app_private.hr_add_employee_relation_event(
      v_case, 'action_required', v_from, v_case.status, v_comment
    );
  elsif p_action = 'resolve' then
    if not app_private.has_permission('Hr:EmployeeRelations:Resolve')
      or v_case.status not in ('investigating', 'action_required') then
      raise exception '当前案件不能提交解决结论';
    end if;
    if nullif(p_payload->>'outcome', '') is null
      or nullif(btrim(p_payload->>'resolution_summary'), '') is null then
      raise exception '解决案件必须填写案件结论和解决摘要';
    end if;
    if exists (
      select 1 from public.hr_employee_relation_action action
      where action.case_id = v_case.id and action.tenant_id = v_case.tenant_id
        and action.status in ('planned', 'in_progress')
    ) then
      raise exception '仍有未完成的处置行动，不能解决案件';
    end if;
    update public.hr_employee_relation_case set
      status = 'resolved', outcome = p_payload->>'outcome',
      findings_summary = coalesce(
        nullif(btrim(p_payload->>'findings_summary'), ''), findings_summary
      ),
      resolution_summary = btrim(p_payload->>'resolution_summary'), resolved_at = now(),
      closed_at = null
    where id = v_case.id returning * into v_case;
    perform app_private.hr_add_employee_relation_event(
      v_case, 'resolved', v_from, v_case.status, v_comment
    );
  elsif p_action = 'close' then
    if not app_private.has_permission('Hr:EmployeeRelations:Close')
      or v_case.status <> 'resolved' then
      raise exception '只有已解决案件可以正式结案';
    end if;
    update public.hr_employee_relation_case set status = 'closed', closed_at = now()
      where id = v_case.id returning * into v_case;
    perform app_private.hr_add_employee_relation_event(
      v_case, 'closed', v_from, v_case.status, v_comment
    );
  elsif p_action = 'reopen' then
    if not app_private.has_permission('Hr:EmployeeRelations:Close')
      or v_case.status not in ('resolved', 'closed') or v_comment is null then
      raise exception '重新调查已解决案件时必须填写原因';
    end if;
    update public.hr_employee_relation_case set
      status = 'investigating', resolved_at = null, closed_at = null,
      outcome = null, resolution_summary = null
    where id = v_case.id returning * into v_case;
    perform app_private.hr_add_employee_relation_event(
      v_case, 'reopened', v_from, v_case.status, v_comment
    );
  elsif p_action = 'cancel' then
    if not app_private.has_permission('Hr:EmployeeRelations:Resolve')
      or v_case.status not in ('reported', 'triaged') or v_comment is null then
      raise exception '取消已报告案件时必须填写原因';
    end if;
    update public.hr_employee_relation_case set status = 'cancelled'
      where id = v_case.id returning * into v_case;
    perform app_private.hr_add_employee_relation_event(
      v_case, 'cancelled', v_from, v_case.status, v_comment
    );
  elsif p_action = 'comment' then
    if not app_private.has_permission('Hr:EmployeeRelations:Investigate') or v_comment is null then
      raise exception '补充案件说明需要调查权限并填写内容';
    end if;
    perform app_private.hr_add_employee_relation_event(
      v_case, 'commented', v_from, v_case.status, v_comment
    );
  else
    raise exception '不支持的员工关系案件动作';
  end if;
  return true;
end
$$;


ALTER FUNCTION "public"."hr_transition_employee_relation_case_secure"("p_id" "uuid", "p_action" "text", "p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: hr_transition_internal_mobility_secure("text", "uuid", "text", "text", numeric); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_transition_internal_mobility_secure"("p_kind" "text", "p_id" "uuid", "p_action" "text", "p_comment" "text" DEFAULT NULL::"text", "p_score" numeric DEFAULT NULL::numeric) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    SET "TimeZone" TO 'Asia/Shanghai'
    AS $$
declare
  v_tenant_id uuid:=app_private.current_user_tenant_id(); v_employee_id uuid:=app_private.hr_current_employee_id();
  v_manage boolean:=app_private.can_execute_business_action('HrInternalMobility','Hr:InternalMobility:Application:Manage',null,false);
  v_actor text:=coalesce(public.get_app_user_display_name(),app_private.current_user_email(),auth.uid()::text);
  v_opportunity public.hr_internal_opportunity%rowtype; v_application public.hr_internal_mobility_application%rowtype;
  v_change_id uuid; v_change_no text;
begin
  if p_kind not in ('opportunity','application') then raise exception '不支持的内部人才市场流转类型'; end if;
  if auth.uid() is null then raise exception '请先登录' using errcode='42501'; end if;
  if p_kind='opportunity' then
    if not app_private.can_execute_business_action('HrInternalMobility','Hr:InternalMobility:Publish',null,false)
      then raise exception '当前账号没有发布或关闭内部机会的权限' using errcode='42501'; end if;
    select * into v_opportunity from public.hr_internal_opportunity where id=p_id and (app_private.is_platform_super() or tenant_id=v_tenant_id) for update;
    if not found then raise exception '内部机会不存在或不属于当前租户'; end if;
    if p_action='publish' and v_opportunity.status='draft' then
      if v_opportunity.application_close_date<current_date then raise exception '申请截止日已过，不能发布'; end if;
      update public.hr_internal_opportunity set status='open',published_at=now(),published_by=v_actor,version=version+1 where id=p_id;
    elsif p_action='pause' and v_opportunity.status='open' then
      update public.hr_internal_opportunity set status='paused',decision_note=nullif(btrim(p_comment),''),version=version+1 where id=p_id;
    elsif p_action='reopen' and v_opportunity.status='paused' then
      if v_opportunity.application_close_date<current_date then raise exception '申请截止日已过，不能重新开放'; end if;
      update public.hr_internal_opportunity set status='open',decision_note=nullif(btrim(p_comment),''),version=version+1 where id=p_id;
    elsif p_action='close' and v_opportunity.status in ('open','paused') then
      if nullif(btrim(p_comment),'') is null then raise exception '关闭内部机会必须填写原因'; end if;
      update public.hr_internal_opportunity set status='closed',closed_at=now(),closed_by=v_actor,decision_note=btrim(p_comment),version=version+1 where id=p_id;
    elsif p_action='cancel' and v_opportunity.status='draft' then
      update public.hr_internal_opportunity set status='cancelled',decision_note=nullif(btrim(p_comment),''),version=version+1 where id=p_id;
    else raise exception '内部机会当前状态不支持此操作'; end if;
  else
    select * into v_application from public.hr_internal_mobility_application
    where id=p_id and (app_private.is_platform_super() or tenant_id=v_tenant_id) for update;
    if not found then raise exception '内部申请不存在或不属于当前租户'; end if;
    v_tenant_id:=v_application.tenant_id;
    select * into v_opportunity from public.hr_internal_opportunity where id=v_application.opportunity_id for update;
    if p_action in ('submit','withdraw','accept') then
      if v_application.employee_id<>v_employee_id and not v_manage then raise exception '只能处理本人内部申请' using errcode='42501'; end if;
      if not app_private.can_execute_business_action('HrInternalMobility','Hr:InternalMobility:Application:Self',null,false) and not v_manage
        then raise exception '当前账号没有处理本人申请的权限' using errcode='42501'; end if;
    elsif not v_manage then raise exception '当前账号没有评估内部申请的权限' using errcode='42501'; end if;
    if p_action='submit' and v_application.status='draft' then
      if v_opportunity.status<>'open' or current_date not between v_opportunity.application_open_date and v_opportunity.application_close_date
        then raise exception '内部机会当前未开放申请'; end if;
      update public.hr_internal_mobility_application set status='submitted',submitted_at=now() where id=p_id;
    elsif p_action='withdraw' and v_application.status in ('submitted','under_review','shortlisted','offered') then
      if nullif(btrim(p_comment),'') is null then raise exception '撤回申请必须填写原因'; end if;
      update public.hr_internal_mobility_application set status='withdrawn',decision_note=btrim(p_comment) where id=p_id;
    elsif p_action='review' and v_application.status='submitted' then
      update public.hr_internal_mobility_application set status='under_review',reviewed_at=now(),reviewed_by=v_actor,
        assessment_score=p_score,assessment_note=nullif(btrim(p_comment),'') where id=p_id;
    elsif p_action='shortlist' and v_application.status in ('submitted','under_review') then
      if p_score is null or p_score<0 or p_score>100 then raise exception '进入候选名单必须填写 0-100 的评估分数'; end if;
      if nullif(btrim(p_comment),'') is null then raise exception '进入候选名单必须填写评估依据'; end if;
      update public.hr_internal_mobility_application set status='shortlisted',reviewed_at=coalesce(reviewed_at,now()),
        reviewed_by=coalesce(reviewed_by,v_actor),assessment_score=p_score,assessment_note=btrim(p_comment) where id=p_id;
    elsif p_action='offer' and v_application.status='shortlisted' then
      if nullif(btrim(p_comment),'') is null then raise exception '发出内部录用意向必须填写决策依据'; end if;
      if (select count(*) from public.hr_internal_mobility_application a where a.opportunity_id=v_opportunity.id and a.status in ('offered','accepted','converted'))>=v_opportunity.capacity
        then raise exception '内部机会录用容量已满'; end if;
      update public.hr_internal_mobility_application set status='offered',decision_at=now(),decision_by=v_actor,
        decision_note=btrim(p_comment) where id=p_id;
    elsif p_action='reject' and v_application.status in ('submitted','under_review','shortlisted') then
      if nullif(btrim(p_comment),'') is null then raise exception '拒绝内部申请必须填写原因'; end if;
      update public.hr_internal_mobility_application set status='rejected',reviewed_at=coalesce(reviewed_at,now()),
        reviewed_by=coalesce(reviewed_by,v_actor),decision_at=now(),decision_by=v_actor,decision_note=btrim(p_comment) where id=p_id;
    elsif p_action='accept' and v_application.status='offered' then
      update public.hr_internal_mobility_application set status='accepted',accepted_at=now(),accepted_by=v_actor where id=p_id;
    elsif p_action='convert' and v_application.status='accepted' then
      if not app_private.can_execute_business_action('HrInternalMobility','Hr:InternalMobility:Convert',null,false)
        then raise exception '当前账号没有生成正式人事异动的权限' using errcode='42501'; end if;
      if v_opportunity.opportunity_type<>'permanent' or v_opportunity.position_id is null then raise exception '仅永久岗位机会可以生成正式人事异动'; end if;
      if v_application.tenant_id<>v_tenant_id then raise exception '跨租户场景不能直接生成人事异动，请切换至目标租户办理'; end if;
      v_change_no:='IM'||to_char(clock_timestamp(),'YYYYMMDDHH24MISSMS');
      v_change_id:=public.hr_save_personnel_change_secure(jsonb_build_object(
        'change_no',v_change_no,'employee_id',v_application.employee_id,'change_type','transfer',
        'effective_date',coalesce(v_application.preferred_start_date,v_opportunity.expected_start_date),
        'to_organization_id',v_opportunity.organization_id,'to_position_id',v_opportunity.position_id,
        'reason','内部人才市场录用：'||v_opportunity.opportunity_title,
        'remark','来源内部机会 '||v_opportunity.opportunity_code||'，申请记录 '||v_application.id
      ));
      update public.hr_internal_mobility_application set status='converted',personnel_change_id=v_change_id where id=p_id;
    else raise exception '内部申请当前状态不支持此操作'; end if;
  end if;
  return true;
end;
$$;


ALTER FUNCTION "public"."hr_transition_internal_mobility_secure"("p_kind" "text", "p_id" "uuid", "p_action" "text", "p_comment" "text", "p_score" numeric) OWNER TO "postgres";

--

--
-- Name: hr_transition_learning_record_secure("text", "uuid", "text", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_transition_learning_record_secure"("p_kind" "text", "p_id" "uuid", "p_action" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_permission text;
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_course public.hr_learning_course%rowtype;
  v_session public.hr_learning_session%rowtype;
  v_enrollment public.hr_training_enrollment%rowtype;
  v_status text;
  v_certificate_no text;
begin
  v_permission := case p_kind
    when 'plan' then 'Hr:Talent:Plan:Transition'
    when 'course' then 'Hr:Talent:Course:Publish'
    when 'session' then 'Hr:Talent:Session:Transition'
    when 'enrollment' then 'Hr:Talent:Enrollment:Manage'
    when 'certificate' then 'Hr:Talent:Certificate:Manage'
    else null end;
  if v_permission is null then raise exception '不支持的学习发展状态类型'; end if;
  if not app_private.can_execute_business_action('HrTalentDevelopment', v_permission, null, false) then
    raise exception '当前账号没有推进该学习发展状态的权限' using errcode = '42501';
  end if;

  if p_kind = 'plan' then
    select status into v_status from public.hr_training_plan
    where id = p_id and (app_private.is_platform_super() or tenant_id = v_tenant_id) for update;
    if not found then raise exception '培训计划不存在'; end if;
    if not ((v_status = 'draft' and p_action = 'publish')
      or (v_status = 'published' and p_action in ('start', 'cancel'))
      or (v_status = 'in_progress' and p_action in ('complete', 'cancel'))) then
      raise exception '培训计划状态不允许执行该操作';
    end if;
    update public.hr_training_plan set
      status = case p_action when 'publish' then 'published' when 'start' then 'in_progress'
        when 'complete' then 'completed' else 'cancelled' end,
      approved_by = case when p_action = 'publish' then public.get_app_user_display_name() else approved_by end,
      approved_at = case when p_action = 'publish' then now() else approved_at end,
      actual_cost = case when p_action = 'complete' then coalesce(
        (select sum(coalesce(actual_cost, estimated_cost, 0)) from public.hr_learning_session where plan_id = p_id), 0
      ) else actual_cost end
    where id = p_id;
    return true;
  end if;

  if p_kind = 'course' then
    select * into v_course from public.hr_learning_course
    where id = p_id and (app_private.is_platform_super() or tenant_id = v_tenant_id) for update;
    if not found then raise exception '课程不存在'; end if;
    if not ((v_course.status = 'draft' and p_action = 'publish')
      or (v_course.status = 'published' and p_action = 'retire')) then
      raise exception '课程状态不允许执行该操作';
    end if;
    if p_action = 'publish' and nullif(btrim(v_course.learning_objectives), '') is null then
      raise exception '发布课程前必须维护学习目标';
    end if;
    update public.hr_learning_course set status = case when p_action = 'publish' then 'published' else 'retired' end
    where id = p_id;
    return true;
  end if;

  if p_kind = 'session' then
    select * into v_session from public.hr_learning_session
    where id = p_id and (app_private.is_platform_super() or tenant_id = v_tenant_id) for update;
    if not found then raise exception '培训班次不存在'; end if;
    if not ((v_session.status = 'planned' and p_action in ('open', 'cancel'))
      or (v_session.status = 'open' and p_action in ('start', 'cancel'))
      or (v_session.status = 'in_progress' and p_action in ('complete', 'cancel'))) then
      raise exception '培训班次状态不允许执行该操作';
    end if;
    if p_action = 'complete' and exists (
      select 1 from public.hr_training_enrollment
      where session_id = p_id and status in ('enrolled', 'attending')
    ) then raise exception '仍有学员未登记最终学习结果'; end if;
    update public.hr_learning_session set
      status = case p_action when 'open' then 'open' when 'start' then 'in_progress'
        when 'complete' then 'completed' else 'cancelled' end,
      actual_cost = case when p_action = 'complete' then coalesce(
        nullif(p_payload ->> 'actual_cost', '')::numeric, estimated_cost, 0
      ) else actual_cost end,
      completion_note = case when p_action in ('complete', 'cancel')
        then nullif(btrim(p_payload ->> 'comment'), '') else completion_note end
    where id = p_id;
    return true;
  end if;

  if p_kind = 'enrollment' then
    select * into v_enrollment from public.hr_training_enrollment
    where id = p_id and (app_private.is_platform_super() or tenant_id = v_tenant_id) for update;
    if not found or v_enrollment.session_id is null then raise exception '学习报名记录不存在'; end if;
    select * into v_session from public.hr_learning_session where id = v_enrollment.session_id;
    select * into v_course from public.hr_learning_course where id = v_session.course_id;
    if not ((v_enrollment.status = 'enrolled' and p_action in ('attend', 'pass', 'fail', 'withdraw', 'no_show'))
      or (v_enrollment.status = 'attending' and p_action in ('pass', 'fail', 'withdraw', 'no_show'))) then
      raise exception '学习参与状态不允许执行该操作';
    end if;
    if p_action in ('pass', 'fail') and nullif(p_payload ->> 'attendance_percent', '') is null then
      raise exception '登记学习结果时必须填写出勤率';
    end if;
    if p_action = 'pass' and (p_payload ->> 'attendance_percent')::numeric < v_course.minimum_attendance_percent then
      raise exception '出勤率未达到课程通过标准';
    end if;
    if p_action = 'pass' and v_course.passing_score is not null
      and coalesce(nullif(p_payload ->> 'score', '')::numeric, -1) < v_course.passing_score then
      raise exception '成绩未达到课程通过标准';
    end if;

    update public.hr_training_enrollment set
      status = case p_action when 'attend' then 'attending' when 'pass' then 'passed'
        when 'fail' then 'failed' when 'withdraw' then 'withdrawn' else 'no_show' end,
      attendance_percent = case when p_action in ('pass', 'fail', 'no_show')
        then coalesce(nullif(p_payload ->> 'attendance_percent', '')::numeric, 0) else attendance_percent end,
      score = case when p_action in ('pass', 'fail') then nullif(p_payload ->> 'score', '')::numeric else score end,
      result = case when p_action = 'pass' then 'passed' when p_action = 'fail' then 'failed' else result end,
      completion_comment = nullif(btrim(p_payload ->> 'comment'), ''),
      completed_at = case when p_action = 'attend' then null else now() end
    where id = p_id;

    if p_action = 'pass' then
      if v_course.certificate_enabled then
        v_certificate_no := 'CERT-' || to_char(current_date, 'YYYY') || '-'
          || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 10));
        insert into public.hr_learning_certificate(
          tenant_id, enrollment_id, employee_id, course_id, certificate_no, certificate_name,
          issued_on, expires_on, status
        ) values (
          v_enrollment.tenant_id, v_enrollment.id, v_enrollment.employee_id, v_course.id,
          v_certificate_no, v_course.course_name || ' 完成证书', current_date,
          case when v_course.certificate_valid_months is null then null
            else (current_date + make_interval(months => v_course.certificate_valid_months))::date end,
          'valid'
        ) on conflict (tenant_id, enrollment_id) do nothing;
        update public.hr_training_enrollment set certificate_no = coalesce(certificate_no, v_certificate_no) where id = p_id;
      end if;

      insert into public.hr_employee_training(
        tenant_id, employee_id, training_name, training_type, provider_name,
        start_date, end_date, training_result, certificate_name, certificate_no, cost, remark
      ) values (
        v_enrollment.tenant_id, v_enrollment.employee_id, v_course.course_name, v_course.category,
        v_course.provider_name, v_session.start_at::date, v_session.end_at::date, 'passed',
        case when v_course.certificate_enabled then v_course.course_name || ' 完成证书' else null end,
        case when v_course.certificate_enabled then v_certificate_no else null end,
        null, '由学习发展闭环自动回写，班次：' || v_session.session_code
      );

      insert into public.hr_employee_competency(
        tenant_id, employee_id, competency_id, current_level, assessed_date, assessor_user_id, evidence
      )
      select mapping.tenant_id, v_enrollment.employee_id, mapping.competency_id,
        mapping.target_level, current_date, null,
        '完成课程 ' || v_course.course_code || ' / 班次 ' || v_session.session_code
      from public.hr_learning_course_competency mapping
      where mapping.course_id = v_course.id
      on conflict (tenant_id, employee_id, competency_id) do update set
        current_level = excluded.current_level, assessed_date = excluded.assessed_date,
        assessor_user_id = null, evidence = excluded.evidence;
    end if;
    return true;
  end if;

  if p_action <> 'revoke' or nullif(btrim(p_payload ->> 'comment'), '') is null then
    raise exception '撤销证书必须填写原因';
  end if;
  update public.hr_learning_certificate set
    status = 'revoked', revoked_reason = btrim(p_payload ->> 'comment'), revoked_at = now()
  where id = p_id and status = 'valid'
    and (app_private.is_platform_super() or tenant_id = v_tenant_id);
  if not found then raise exception '仅有效证书允许撤销'; end if;
  return true;
end
$$;


ALTER FUNCTION "public"."hr_transition_learning_record_secure"("p_kind" "text", "p_id" "uuid", "p_action" "text", "p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: hr_transition_lifecycle_case_secure("uuid", "text", "text", "date"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_transition_lifecycle_case_secure"("p_id" "uuid", "p_action" "text", "p_comment" "text" DEFAULT NULL::"text", "p_effective_date" "date" DEFAULT NULL::"date") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_case public.hr_lifecycle_case;
  v_open_blocking integer;
  v_open_required integer;
  v_permission text := case when p_action = 'complete'
    then 'Hr:Lifecycle:CompleteCase' else 'Hr:Lifecycle:Start' end;
begin
  if p_action not in ('start', 'ready', 'complete', 'cancel') then
    raise exception '不支持的事项动作';
  end if;
  if not app_private.can_execute_business_action('HrLifecycle', v_permission, null, false) then
    raise exception '当前账号没有推进生命周期事项的权限' using errcode = '42501';
  end if;
  select * into v_case from public.hr_lifecycle_case c
  where c.id = p_id and (app_private.is_platform_super() or c.tenant_id = v_tenant_id)
  for update;
  if not found then raise exception '生命周期事项不存在或无权操作'; end if;

  perform set_config('app.workflow_engine', 'on', true);
  if p_action = 'start' then
    if v_case.execution_status <> 'planning' or v_case.status not in ('approved', 'effective') then
      raise exception '只有审批通过且待规划的事项可以启动';
    end if;
    if not exists (
      select 1 from public.hr_lifecycle_task t where t.lifecycle_case_id = v_case.id
    ) then raise exception '事项至少需要一项执行任务'; end if;
    update public.hr_lifecycle_case
    set execution_status = 'in_progress', started_at = now()
    where id = v_case.id;
    return;
  end if;
  if p_action = 'ready' then
    if v_case.execution_status <> 'in_progress' then
      raise exception '只有执行中的事项可以校验就绪';
    end if;
    select count(*) into v_open_blocking from public.hr_lifecycle_task t
    where t.lifecycle_case_id = v_case.id and t.blocking
      and t.status in ('pending', 'processing');
    if v_open_blocking > 0 then
      raise exception '仍有 % 项阻断任务未完成', v_open_blocking;
    end if;
    update public.hr_lifecycle_case
    set execution_status = 'ready', ready_at = now()
    where id = v_case.id;
    return;
  end if;
  if p_action = 'complete' then
    if v_case.execution_status <> 'ready' then raise exception '只有已就绪事项可以办结'; end if;
    select count(*) into v_open_required from public.hr_lifecycle_task t
    where t.lifecycle_case_id = v_case.id and t.required
      and t.status in ('pending', 'processing');
    if v_open_required > 0 then raise exception '仍有 % 项必办任务未完成', v_open_required; end if;
    update public.hr_lifecycle_case
    set status = 'effective', execution_status = 'completed',
      actual_effective_date = coalesce(p_effective_date, planned_effective_date),
      completed_at = now(), completed_by = auth.uid()::text,
      remark = coalesce(nullif(btrim(p_comment), ''), remark)
    where id = v_case.id;
    return;
  end if;
  if v_case.execution_status in ('completed', 'cancelled') then
    raise exception '已结束事项不能取消';
  end if;
  if nullif(btrim(p_comment), '') is null then raise exception '取消事项必须填写原因'; end if;
  update public.hr_lifecycle_case
  set status = 'cancelled', execution_status = 'cancelled',
    cancelled_at = now(), cancellation_reason = btrim(p_comment)
  where id = v_case.id;
  update public.hr_lifecycle_task set status = 'cancelled'
  where lifecycle_case_id = v_case.id and status in ('pending', 'processing');
end
$$;


ALTER FUNCTION "public"."hr_transition_lifecycle_case_secure"("p_id" "uuid", "p_action" "text", "p_comment" "text", "p_effective_date" "date") OWNER TO "postgres";

--

--
-- Name: hr_transition_lifecycle_task_secure("uuid", "text", "text", "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_transition_lifecycle_task_secure"("p_id" "uuid", "p_action" "text", "p_note" "text" DEFAULT NULL::"text", "p_evidence_url" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_task public.hr_lifecycle_task;
  v_case public.hr_lifecycle_case;
  v_permission text := case when p_action = 'waive' then 'Hr:Lifecycle:WaiveTask' else 'Hr:Lifecycle:CompleteTask' end;
begin
  if p_action not in ('start', 'complete', 'waive', 'reopen') then raise exception '不支持的任务动作'; end if;
  if not app_private.can_execute_business_action('HrLifecycle', v_permission, null, false) then
    raise exception '当前账号没有处理生命周期任务的权限' using errcode = '42501';
  end if;
  select * into v_task from public.hr_lifecycle_task t
  where t.id = p_id and (app_private.is_platform_super() or t.tenant_id = v_tenant_id)
  for update;
  if not found then raise exception '生命周期任务不存在或无权操作'; end if;
  select * into v_case from public.hr_lifecycle_case c
  where c.id = v_task.lifecycle_case_id and c.tenant_id = v_task.tenant_id;
  if v_case.execution_status not in ('planning', 'in_progress') then
    raise exception '当前事项状态不允许处理任务';
  end if;
  if p_action in ('start', 'complete') and v_task.dependency_task_id is not null and exists (
    select 1 from public.hr_lifecycle_task dependency
    where dependency.id = v_task.dependency_task_id and dependency.status not in ('completed', 'skipped')
  ) then raise exception '前置任务尚未完成'; end if;
  if p_action = 'start' then
    if v_task.status <> 'pending' then raise exception '只有待处理任务可以开始'; end if;
    update public.hr_lifecycle_task set status = 'processing', started_at = now() where id = v_task.id;
    return;
  end if;
  if p_action = 'complete' then
    if v_task.status not in ('pending', 'processing') then raise exception '当前任务不能完成'; end if;
    if v_task.evidence_required and nullif(btrim(p_note), '') is null and nullif(btrim(p_evidence_url), '') is null then
      raise exception '该任务要求填写完成证据或证据链接';
    end if;
    update public.hr_lifecycle_task set status = 'completed', completed_at = now(),
      completed_by = auth.uid()::text, completion_note = nullif(btrim(p_note), ''),
      evidence_note = nullif(btrim(p_note), ''), evidence_url = nullif(btrim(p_evidence_url), ''),
      waived_at = null, waived_by = null, waiver_reason = null
    where id = v_task.id;
    return;
  end if;
  if p_action = 'waive' then
    if v_task.status not in ('pending', 'processing') then raise exception '当前任务不能豁免'; end if;
    if nullif(btrim(p_note), '') is null then raise exception '豁免任务必须填写原因'; end if;
    update public.hr_lifecycle_task set status = 'skipped', waived_at = now(),
      waived_by = auth.uid()::text, waiver_reason = btrim(p_note),
      completed_at = now(), completed_by = auth.uid()::text, completion_note = btrim(p_note)
    where id = v_task.id;
    return;
  end if;
  if v_task.status not in ('completed', 'skipped') then raise exception '只有已关闭任务可以重新打开'; end if;
  update public.hr_lifecycle_task set status = 'pending', started_at = null,
    completed_at = null, completed_by = null, completion_note = null,
    evidence_note = null, evidence_url = null, waived_at = null, waived_by = null, waiver_reason = null
  where id = v_task.id;
end
$$;


ALTER FUNCTION "public"."hr_transition_lifecycle_task_secure"("p_id" "uuid", "p_action" "text", "p_note" "text", "p_evidence_url" "text") OWNER TO "postgres";

--

--
-- Name: hr_transition_lifecycle_template_secure("uuid", "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_transition_lifecycle_template_secure"("p_id" "uuid", "p_action" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_template public.hr_lifecycle_template;
begin
  if p_action not in ('activate', 'deactivate') then raise exception '不支持的任务包动作'; end if;
  if not app_private.can_execute_business_action('HrLifecycle', 'Hr:Lifecycle:ManageTemplate', null, false) then
    raise exception '当前账号没有管理标准任务包的权限' using errcode = '42501';
  end if;
  select * into v_template from public.hr_lifecycle_template t
  where t.id = p_id and (app_private.is_platform_super() or t.tenant_id = v_tenant_id)
  for update;
  if not found then raise exception '标准任务包不存在或无权操作'; end if;
  if p_action = 'activate' then
    if v_template.status = 'active' then return; end if;
    if not exists (select 1 from public.hr_lifecycle_template_task task where task.template_id = v_template.id) then
      raise exception '任务包至少需要一项模板任务';
    end if;
    if v_template.is_default then
      update public.hr_lifecycle_template set is_default = false
      where tenant_id = v_template.tenant_id and case_type = v_template.case_type
        and id <> v_template.id and status = 'active' and is_default;
    end if;
    update public.hr_lifecycle_template set status = 'active' where id = v_template.id;
  else
    if v_template.status <> 'active' then raise exception '只有启用任务包可以停用'; end if;
    update public.hr_lifecycle_template set status = 'inactive', is_default = false where id = v_template.id;
  end if;
end
$$;


ALTER FUNCTION "public"."hr_transition_lifecycle_template_secure"("p_id" "uuid", "p_action" "text") OWNER TO "postgres";

--

--
-- Name: hr_transition_organization_design_secure("uuid", "text", "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_transition_organization_design_secure"("p_id" "uuid", "p_action" "text", "p_comment" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    SET "TimeZone" TO 'Asia/Shanghai'
    AS $$
declare
  v_tenant_id uuid:=app_private.current_user_tenant_id(); v_scenario public.hr_organization_design_scenario%rowtype;
  v_change public.hr_organization_design_change%rowtype;
  v_actor text:=coalesce(public.get_app_user_display_name(),app_private.current_user_email(),auth.uid()::text);
  v_employee_count integer; v_position_count integer; v_requisition_count integer;
  v_security_count integer; v_scope_count integer; v_risk text:='low';
  v_permission text:=case p_action when 'submit' then 'Hr:OrganizationDesign:Impact:Review'
    when 'approve' then 'Hr:OrganizationDesign:Approve' when 'reject' then 'Hr:OrganizationDesign:Approve'
    when 'handoff' then 'Hr:OrganizationDesign:Handoff' else 'Hr:OrganizationDesign:Scenario:Manage' end;
begin
  if p_action not in ('submit','approve','reject','handoff','cancel') then raise exception '不支持的组织变革方案动作'; end if;
  if auth.uid() is null or not app_private.can_execute_business_action('HrOrganizationDesign',v_permission,null,false)
    then raise exception '当前账号没有执行组织变革方案流转的权限' using errcode='42501'; end if;
  select * into v_scenario from public.hr_organization_design_scenario
  where id=p_id and (app_private.is_platform_super() or tenant_id=v_tenant_id) for update;
  if not found then raise exception '组织变革方案不存在或不属于当前租户'; end if;
  if p_action='submit' and v_scenario.status in ('draft','rejected') then
    if not exists(select 1 from public.hr_organization_design_change c where c.scenario_id=p_id)
      then raise exception '至少维护一项组织变更后才能提交影响评审'; end if;
    for v_change in select * from public.hr_organization_design_change c where c.scenario_id=p_id for update loop
      if v_change.organization_id is null then
        v_employee_count:=0; v_position_count:=0; v_requisition_count:=0; v_security_count:=0; v_scope_count:=0;
      else
        with recursive org_scope as (
          select o.id from public.mdm_organization o where o.id=v_change.organization_id and o.tenant_id=v_scenario.tenant_id
          union all select child.id from public.mdm_organization child join org_scope parent_scope on child.parent_id=parent_scope.id where child.tenant_id=v_scenario.tenant_id
        ) select
          (select count(*) from public.mdm_employee e where e.tenant_id=v_scenario.tenant_id and e.organization_id in(select id from org_scope) and e.employment_status in ('probation','active','leave')),
          (select count(*) from public.mdm_position p where p.tenant_id=v_scenario.tenant_id and p.organization_id in(select id from org_scope) and p.enabled),
          (select count(*) from public.hr_recruitment_requisition r where r.tenant_id=v_scenario.tenant_id and r.organization_id in(select id from org_scope) and r.status not in ('cancelled','filled','closed')),
          (select count(*) from public.sys_user u where u.tenant_id=v_scenario.tenant_id and u.organization_id in(select id from org_scope) and u.status='1'),
          (select count(*) from public.hr_policy_document p where p.tenant_id=v_scenario.tenant_id and p.audience_organization_id in(select id from org_scope) and p.status='published')
        into v_employee_count,v_position_count,v_requisition_count,v_security_count,v_scope_count;
      end if;
      update public.hr_organization_design_change set
        impacted_employee_count=v_employee_count,impacted_position_count=v_position_count,
        impacted_requisition_count=v_requisition_count,impacted_security_user_count=v_security_count,
        impacted_scope_count=v_scope_count,impact_captured_at=now() where id=v_change.id;
      if v_security_count>0 then v_risk:='critical';
      elsif v_risk<>'critical' and (v_employee_count>=50 or v_position_count>=20) then v_risk:='high';
      elsif v_risk not in ('critical','high') and (v_employee_count>=10 or v_requisition_count>0 or v_scope_count>0) then v_risk:='medium';
      end if;
    end loop;
    update public.hr_organization_design_scenario set status='impact_review',risk_level=v_risk,
      submission_note=nullif(btrim(p_comment),''),baseline_captured_at=now(),submitted_at=now(),submitted_by=v_actor,
      decision_note=null,decided_at=null,decided_by=null,version=version+1 where id=p_id;
  elsif p_action='approve' and v_scenario.status='impact_review' then
    if nullif(btrim(p_comment),'') is null then raise exception '批准方案必须填写决策依据'; end if;
    update public.hr_organization_design_scenario set status='approved',decision_note=btrim(p_comment),
      decided_at=now(),decided_by=v_actor,version=version+1 where id=p_id;
  elsif p_action='reject' and v_scenario.status='impact_review' then
    if nullif(btrim(p_comment),'') is null then raise exception '退回方案必须填写原因'; end if;
    update public.hr_organization_design_scenario set status='rejected',decision_note=btrim(p_comment),
      decided_at=now(),decided_by=v_actor,version=version+1 where id=p_id;
  elsif p_action='handoff' and v_scenario.status='approved' then
    if nullif(btrim(p_comment),'') is null then raise exception '执行移交必须填写实施窗口与责任说明'; end if;
    update public.hr_organization_design_scenario set status='handed_off',
      decision_note=decision_note||E'\n执行移交：'||btrim(p_comment),handed_off_at=now(),handed_off_by=v_actor,
      version=version+1 where id=p_id;
  elsif p_action='cancel' and v_scenario.status in ('draft','rejected') then
    update public.hr_organization_design_scenario set status='cancelled',risk_level='unassessed',
      submission_note=null,decision_note=null,baseline_captured_at=null,submitted_at=null,submitted_by=null,
      decided_at=null,decided_by=null,version=version+1 where id=p_id;
  else raise exception '组织变革方案当前状态不支持此操作'; end if;
  return true;
end;
$$;


ALTER FUNCTION "public"."hr_transition_organization_design_secure"("p_id" "uuid", "p_action" "text", "p_comment" "text") OWNER TO "postgres";

--

--
-- Name: hr_transition_performance_calibration_secure("uuid", "text", "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_transition_performance_calibration_secure"("p_id" "uuid", "p_action" "text", "p_comment" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_session public.hr_performance_calibration_session%rowtype;
  v_item_count integer;
begin
  if p_action not in ('start','approve','deactivate') then raise exception '不支持的绩效校准动作'; end if;
  if not app_private.can_execute_business_action('HrPerformance','Hr:Performance:Calibrate',null,false) then
    raise exception '当前账号没有执行绩效校准的权限' using errcode='42501';
  end if;
  select * into v_session from public.hr_performance_calibration_session
    where id=p_id and (app_private.is_platform_super() or tenant_id=v_tenant_id) for update;
  if not found then raise exception '绩效校准会议不存在'; end if;

  if p_action='start' then
    if v_session.status<>'setup' then raise exception '只有筹备中的会议可以开始校准'; end if;
    insert into public.hr_performance_calibration_item(
      tenant_id,session_id,review_id,original_score,original_level,calibrated_score,calibrated_level
    )
    select r.tenant_id,v_session.id,r.id,r.manager_score,r.performance_level,r.manager_score,r.performance_level
    from public.hr_performance_review r
    join public.mdm_employee e on e.id=r.employee_id and e.tenant_id=r.tenant_id
    where r.tenant_id=v_session.tenant_id and r.cycle_id=v_session.cycle_id and r.status='confirmed'
      and (v_session.organization_id is null or e.organization_id=v_session.organization_id)
    on conflict (tenant_id,session_id,review_id) do nothing;
    get diagnostics v_item_count = row_count;
    if v_item_count=0 and not exists (select 1 from public.hr_performance_calibration_item where session_id=v_session.id and tenant_id=v_session.tenant_id) then
      raise exception '当前范围没有待校准的员工绩效结果';
    end if;
    update public.hr_performance_calibration_session set status='in_progress' where id=v_session.id;
    update public.hr_performance_cycle set status='reviewing'
      where id=v_session.cycle_id and tenant_id=v_session.tenant_id and status='active';
    return true;
  end if;
  if p_action='approve' then
    if v_session.status<>'in_progress' then raise exception '只有校准中的会议可以定案'; end if;
    if nullif(btrim(p_comment),'') is null then raise exception '校准定案必须填写会议结论'; end if;
    if exists (
      select 1 from public.hr_performance_calibration_item i
      where i.session_id=v_session.id and i.tenant_id=v_session.tenant_id
        and (i.calibrated_score<>i.original_score or i.calibrated_level<>i.original_level)
        and nullif(btrim(i.adjustment_reason),'') is null
    ) then raise exception '发生评分调整时必须逐项填写调整依据'; end if;
    update public.hr_performance_review r set
      calibrated_score=i.calibrated_score,calibrated_level=i.calibrated_level,
      calibration_comment=i.adjustment_reason,total_score=i.calibrated_score,
      performance_level=i.calibrated_level,status='completed',completed_at=now()
    from public.hr_performance_calibration_item i
    where i.session_id=v_session.id and i.tenant_id=v_session.tenant_id
      and r.id=i.review_id and r.tenant_id=i.tenant_id;
    update public.hr_performance_calibration_session set status='approved',approved_at=now(),decision_note=btrim(p_comment)
      where id=v_session.id;
    return true;
  end if;
  if v_session.status<>'setup' then raise exception '只有筹备中的会议可以停用'; end if;
  if nullif(btrim(p_comment),'') is null then raise exception '停用会议必须填写原因'; end if;
  update public.hr_performance_calibration_session set status='deactivated',decision_note=btrim(p_comment) where id=v_session.id;
  return true;
end
$$;


ALTER FUNCTION "public"."hr_transition_performance_calibration_secure"("p_id" "uuid", "p_action" "text", "p_comment" "text") OWNER TO "postgres";

--

--
-- Name: hr_transition_performance_cycle_secure("uuid", "text", "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_transition_performance_cycle_secure"("p_id" "uuid", "p_action" "text", "p_comment" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_cycle public.hr_performance_cycle%rowtype;
  v_permission text := case when p_action in ('activate','begin_review') then 'Hr:Performance:Activate' else 'Hr:Performance:Complete' end;
  v_review_count integer;
begin
  if p_action not in ('activate','begin_review','complete','cancel') then raise exception '不支持的绩效周期动作'; end if;
  if not app_private.can_execute_business_action('HrPerformance',v_permission,null,false) then
    raise exception '当前账号没有推进绩效周期的权限' using errcode='42501';
  end if;
  select * into v_cycle from public.hr_performance_cycle
    where id=p_id and (app_private.is_platform_super() or tenant_id=v_tenant_id) for update;
  if not found then raise exception '绩效周期不存在'; end if;

  if p_action='activate' then
    if v_cycle.status<>'draft' then raise exception '只有草稿周期可以启动'; end if;
    select count(*) into v_review_count from public.hr_performance_review r
      where r.cycle_id=v_cycle.id and r.tenant_id=v_cycle.tenant_id and r.status='draft';
    if v_review_count=0 then raise exception '启动周期前至少安排一名员工考核'; end if;
    if exists (
      select 1 from public.hr_performance_review r
      left join public.hr_performance_goal g on g.review_id=r.id and g.tenant_id=r.tenant_id
      where r.cycle_id=v_cycle.id and r.tenant_id=v_cycle.tenant_id and r.status='draft'
      group by r.id having count(g.id)=0 or coalesce(sum(g.weight),0)<>100
    ) then raise exception '每位员工至少维护一项目标，且目标权重合计必须为 100%%'; end if;
    update public.hr_performance_cycle set status='active',activated_at=now(),description=coalesce(description,p_comment) where id=v_cycle.id;
    update public.hr_performance_review set status='self_review',submitted_at=now()
      where cycle_id=v_cycle.id and tenant_id=v_cycle.tenant_id and status='draft';
    update public.hr_performance_goal set status='in_progress'
      where tenant_id=v_cycle.tenant_id and review_id in (select id from public.hr_performance_review where cycle_id=v_cycle.id and tenant_id=v_cycle.tenant_id);
    return true;
  end if;
  if p_action='begin_review' then
    if v_cycle.status<>'active' then raise exception '只有执行中的周期可以进入评议'; end if;
    if exists (select 1 from public.hr_performance_review where cycle_id=v_cycle.id and tenant_id=v_cycle.tenant_id and status in ('draft','self_review')) then
      raise exception '仍有员工未完成自评，不能进入周期评议';
    end if;
    update public.hr_performance_cycle set status='reviewing' where id=v_cycle.id;
    return true;
  end if;
  if p_action='complete' then
    if v_cycle.status not in ('active','reviewing') then raise exception '当前周期不能完成'; end if;
    if exists (select 1 from public.hr_performance_review where cycle_id=v_cycle.id and tenant_id=v_cycle.tenant_id and status not in ('completed','cancelled')) then
      raise exception '仍有员工绩效结果未完成';
    end if;
    update public.hr_performance_cycle set status='completed',completed_at=now() where id=v_cycle.id;
    return true;
  end if;
  if v_cycle.status not in ('draft','active') then raise exception '当前周期不能取消'; end if;
  if nullif(btrim(p_comment),'') is null then raise exception '取消周期必须填写原因'; end if;
  update public.hr_performance_cycle set status='cancelled',description=concat_ws(E'\n',description,'取消原因：'||btrim(p_comment)) where id=v_cycle.id;
  update public.hr_performance_review set status='cancelled' where cycle_id=v_cycle.id and tenant_id=v_cycle.tenant_id and status<>'completed';
  return true;
end
$$;


ALTER FUNCTION "public"."hr_transition_performance_cycle_secure"("p_id" "uuid", "p_action" "text", "p_comment" "text") OWNER TO "postgres";

--

--
-- Name: hr_transition_performance_review_secure("uuid", "text", "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_transition_performance_review_secure"("p_id" "uuid", "p_action" "text", "p_comment" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_review public.hr_performance_review%rowtype;
  v_permission text := case when p_action in ('submit_self','submit_manager') then 'Hr:Performance:Review' else 'Hr:Performance:Complete' end;
  v_score numeric;
begin
  if p_action not in ('submit_self','submit_manager','complete') then raise exception '不支持的员工考核动作'; end if;
  if not app_private.can_execute_business_action('HrPerformance',v_permission,null,false) then
    raise exception '当前账号没有推进员工考核的权限' using errcode='42501';
  end if;
  select * into v_review from public.hr_performance_review
    where id=p_id and (app_private.is_platform_super() or tenant_id=v_tenant_id) for update;
  if not found then raise exception '员工考核不存在'; end if;

  if p_action='submit_self' then
    if v_review.status<>'self_review' then raise exception '当前考核不在员工自评阶段'; end if;
    if nullif(btrim(p_comment),'') is null then raise exception '提交自评前请填写员工总结'; end if;
    if exists (select 1 from public.hr_performance_goal where review_id=v_review.id and tenant_id=v_review.tenant_id and employee_score is null) then
      raise exception '请完成全部目标的员工自评分';
    end if;
    select round(sum(weight*employee_score)/nullif(sum(weight),0),2) into v_score
      from public.hr_performance_goal where review_id=v_review.id and tenant_id=v_review.tenant_id;
    update public.hr_performance_review set status='manager_review',employee_summary=btrim(p_comment),self_score=v_score
      where id=v_review.id;
    return true;
  end if;
  if p_action='submit_manager' then
    if v_review.status<>'manager_review' then raise exception '当前考核不在主管评价阶段'; end if;
    if nullif(btrim(p_comment),'') is null then raise exception '提交主管评价前请填写评价意见'; end if;
    if exists (select 1 from public.hr_performance_goal where review_id=v_review.id and tenant_id=v_review.tenant_id and manager_score is null) then
      raise exception '请完成全部目标的主管评分';
    end if;
    select round(sum(weight*manager_score)/nullif(sum(weight),0),2) into v_score
      from public.hr_performance_goal where review_id=v_review.id and tenant_id=v_review.tenant_id;
    update public.hr_performance_review set status='confirmed',reviewer_comment=btrim(p_comment),
      manager_score=v_score,total_score=v_score,performance_level=app_private.hr_performance_level_for_score(v_score),
      manager_reviewed_at=now(),confirmed_at=now() where id=v_review.id;
    return true;
  end if;
  if v_review.status<>'confirmed' then raise exception '只有待校准结果可以直接完成'; end if;
  update public.hr_performance_review set status='completed',completed_at=now() where id=v_review.id;
  return true;
end
$$;


ALTER FUNCTION "public"."hr_transition_performance_review_secure"("p_id" "uuid", "p_action" "text", "p_comment" "text") OWNER TO "postgres";

--

--
-- Name: hr_transition_policy_acknowledgement_secure("text", "uuid", "text", "text", "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_transition_policy_acknowledgement_secure"("p_kind" "text", "p_id" "uuid", "p_action" "text", "p_comment" "text" DEFAULT NULL::"text", "p_evidence_reference" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    SET "TimeZone" TO 'Asia/Shanghai'
    AS $$
declare
  v_tenant_id uuid:=app_private.current_user_tenant_id();
  v_policy public.hr_policy_document%rowtype;
  v_receipt public.hr_policy_receipt%rowtype;
  v_actor text:=coalesce(public.get_app_user_display_name(),app_private.current_user_email(),auth.uid()::text);
  v_permission text;
  v_inserted integer;
begin
  if p_kind not in ('policy','receipt') then raise exception '不支持的政策签收流转类型'; end if;
  v_permission:=case when p_kind='policy' then 'Hr:PolicyAcknowledgement:Publish' else 'Hr:PolicyAcknowledgement:Receipt:Manage' end;
  if auth.uid() is null or not app_private.can_execute_business_action(
    'HrPolicyAcknowledgement',v_permission,null,false
  ) then raise exception '当前账号没有执行政策签收流转的权限' using errcode='42501'; end if;

  if p_kind='policy' then
    select * into v_policy from public.hr_policy_document
    where id=p_id and (app_private.is_platform_super() or tenant_id=v_tenant_id) for update;
    if not found then raise exception '政策不存在或不属于当前租户'; end if;
    if p_action='publish' and v_policy.status='draft' then
      with recursive org_scope as (
        select organization.id from public.mdm_organization organization
        where organization.id=v_policy.audience_organization_id and organization.tenant_id=v_policy.tenant_id
        union all
        select child.id from public.mdm_organization child
        join org_scope parent_scope on child.parent_id=parent_scope.id
        where child.tenant_id=v_policy.tenant_id
      )
      insert into public.hr_policy_receipt(tenant_id,policy_id,employee_id,due_date)
      select v_policy.tenant_id,v_policy.id,employee.id,
        greatest(current_date,v_policy.effective_date)+v_policy.acknowledgement_due_days
      from public.mdm_employee employee
      where employee.tenant_id=v_policy.tenant_id
        and employee.employment_status in ('probation','active','leave')
        and (v_policy.audience_type='all'
          or (v_policy.audience_type='organization' and employee.organization_id in (select id from org_scope))
          or (v_policy.audience_type='employment_type' and employee.employment_type=v_policy.audience_employment_type))
      on conflict(policy_id,employee_id) do nothing;
      get diagnostics v_inserted=row_count;
      if v_inserted=0 then raise exception '当前适用人群没有可送达员工，请检查范围后再发布'; end if;
      update public.hr_policy_document set status='published',published_at=now(),published_by=v_actor,
        decision_note=coalesce(nullif(btrim(p_comment),''),decision_note) where id=p_id;
    elsif p_action='retire' and v_policy.status='published' then
      if nullif(btrim(p_comment),'') is null then raise exception '退役政策必须填写原因'; end if;
      update public.hr_policy_document set status='retired',retired_at=now(),retired_by=v_actor,
        decision_note=btrim(p_comment) where id=p_id;
    elsif p_action='cancel' and v_policy.status='draft' then
      update public.hr_policy_document set status='cancelled',decision_note=nullif(btrim(p_comment),'') where id=p_id;
    else raise exception '政策当前状态不支持此操作'; end if;
  else
    select * into v_receipt from public.hr_policy_receipt
    where id=p_id and (app_private.is_platform_super() or tenant_id=v_tenant_id) for update;
    if not found then raise exception '签收记录不存在或不属于当前租户'; end if;
    if p_action='acknowledge' and v_receipt.status='pending' then
      if nullif(btrim(p_comment),'') is null then raise exception '确认签收必须记录确认说明'; end if;
      update public.hr_policy_receipt set status='acknowledged',acknowledged_at=now(),
        acknowledged_by=v_actor,acknowledgement_note=btrim(p_comment),
        evidence_reference=nullif(btrim(p_evidence_reference),'') where id=p_id;
    elsif p_action='waive' and v_receipt.status='pending' then
      if nullif(btrim(p_comment),'') is null then raise exception '豁免签收必须填写原因'; end if;
      update public.hr_policy_receipt set status='waived',waived_at=now(),waived_by=v_actor,
        waiver_reason=btrim(p_comment),evidence_reference=nullif(btrim(p_evidence_reference),'') where id=p_id;
    elsif p_action='reopen' and v_receipt.status in ('acknowledged','waived') then
      if nullif(btrim(p_comment),'') is null then raise exception '重新打开签收必须填写原因'; end if;
      update public.hr_policy_receipt set status='pending',acknowledged_at=null,acknowledged_by=null,
        acknowledgement_note=null,waived_at=null,waived_by=null,waiver_reason=null,
        evidence_reference=null where id=p_id;
    else raise exception '签收记录当前状态不支持此操作'; end if;
  end if;
  return true;
end;
$$;


ALTER FUNCTION "public"."hr_transition_policy_acknowledgement_secure"("p_kind" "text", "p_id" "uuid", "p_action" "text", "p_comment" "text", "p_evidence_reference" "text") OWNER TO "postgres";

--

--
-- Name: hr_transition_recruitment_handoff_secure("uuid", "text", "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_transition_recruitment_handoff_secure"("p_handoff_id" "uuid", "p_action" "text", "p_comment" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_handoff public.hr_recruitment_handoff;
  v_candidate public.hr_candidate;
  v_requisition_id uuid;
  v_open_tasks integer;
  v_hired_count integer;
begin
  if not app_private.can_execute_business_action('HrRecruitment', 'Hr:Recruitment:Handoff:Complete', null, false) then
    raise exception '当前账号没有推进入职交接的权限' using errcode = '42501';
  end if;
  if p_action not in ('ready', 'complete', 'cancel') then raise exception '不支持的入职交接动作'; end if;
  select * into v_handoff from public.hr_recruitment_handoff
  where id = p_handoff_id and (app_private.is_platform_super() or tenant_id = v_tenant_id)
  for update;
  if not found then raise exception '入职交接不存在或无权操作'; end if;
  if p_action = 'ready' and v_handoff.status <> 'pending' then raise exception '只有待准备交接可以标记就绪'; end if;
  if p_action = 'complete' and v_handoff.status not in ('pending', 'ready') then raise exception '当前交接不能完成'; end if;
  if p_action = 'cancel' and v_handoff.status not in ('pending', 'ready') then raise exception '当前交接不能取消'; end if;
  if p_action = 'cancel' and nullif(btrim(p_comment), '') is null then raise exception '取消交接必须填写原因'; end if;

  if p_action = 'complete' then
    if v_handoff.onboard_employee_id is null then raise exception '完成交接前必须关联已创建的员工档案'; end if;
    select count(*) into v_open_tasks from public.hr_recruitment_onboarding_task
    where handoff_id = v_handoff.id and status in ('pending', 'in_progress');
    if v_open_tasks > 0 then raise exception '仍有 % 项入职任务未完成', v_open_tasks; end if;
    update public.hr_recruitment_handoff
    set status = 'completed', completed_at = now(), handoff_note = coalesce(nullif(btrim(p_comment), ''), handoff_note)
    where id = v_handoff.id;
    select * into v_candidate from public.hr_candidate where id = v_handoff.candidate_id for update;
    update public.hr_candidate set onboard_employee_id = v_handoff.onboard_employee_id where id = v_candidate.id;
    if v_candidate.stage <> 'hired' then
      perform app_private.hr_append_candidate_stage(v_candidate.id, 'hired', '入职交接完成并关联员工档案');
    end if;
    v_requisition_id := v_candidate.requisition_id;
    select count(*) into v_hired_count from public.hr_candidate
    where requisition_id = v_requisition_id and stage = 'hired';
    update public.hr_recruitment_requisition
    set hired_count = least(v_hired_count, opening_count),
        status = case when v_hired_count >= opening_count then 'completed' else status end
    where id = v_requisition_id;
  elsif p_action = 'ready' then
    update public.hr_recruitment_handoff set status = 'ready', handoff_note = coalesce(nullif(btrim(p_comment), ''), handoff_note)
    where id = v_handoff.id;
  else
    update public.hr_recruitment_handoff set status = 'cancelled', handoff_note = btrim(p_comment)
    where id = v_handoff.id;
  end if;
end
$$;


ALTER FUNCTION "public"."hr_transition_recruitment_handoff_secure"("p_handoff_id" "uuid", "p_action" "text", "p_comment" "text") OWNER TO "postgres";

--

--
-- Name: hr_transition_recruitment_offer_secure("uuid", "text", "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_transition_recruitment_offer_secure"("p_offer_id" "uuid", "p_action" "text", "p_comment" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_offer public.hr_recruitment_offer;
  v_candidate public.hr_candidate;
  v_requisition public.hr_recruitment_requisition;
  v_permission text;
  v_next_status text;
  v_handoff_id uuid;
begin
  v_permission := case
    when p_action = 'submit' then 'Hr:Recruitment:Offer:Submit'
    when p_action in ('approve', 'reject') then 'Hr:Recruitment:Offer:Approve'
    when p_action in ('send', 'withdraw', 'expire') then 'Hr:Recruitment:Offer:Send'
    when p_action in ('accept', 'decline') then 'Hr:Recruitment:Offer:Respond'
    else null
  end;
  if v_permission is null then raise exception '不支持的 Offer 动作'; end if;
  if not app_private.can_execute_business_action('HrRecruitment', v_permission, null, false) then
    raise exception '当前账号没有执行该 Offer 动作的权限' using errcode = '42501';
  end if;
  select * into v_offer from public.hr_recruitment_offer
  where id = p_offer_id and (app_private.is_platform_super() or tenant_id = v_tenant_id)
  for update;
  if not found then raise exception 'Offer 不存在或无权操作'; end if;
  select * into v_candidate from public.hr_candidate where id = v_offer.candidate_id;
  select requisition.* into v_requisition
  from public.hr_recruitment_requisition requisition where requisition.id = v_candidate.requisition_id;
  if p_action in ('send', 'accept') and v_candidate.stage not in ('interview', 'offer') then
    raise exception '候选人当前阶段不允许发送或接受 Offer';
  end if;

  v_next_status := case
    when p_action = 'submit' and v_offer.status in ('draft', 'rejected') then 'pending_approval'
    when p_action = 'approve' and v_offer.status = 'pending_approval' then 'approved'
    when p_action = 'reject' and v_offer.status = 'pending_approval' then 'rejected'
    when p_action = 'send' and v_offer.status = 'approved' then 'sent'
    when p_action = 'accept' and v_offer.status = 'sent' then 'accepted'
    when p_action = 'decline' and v_offer.status = 'sent' then 'declined'
    when p_action = 'expire' and v_offer.status = 'sent' then 'expired'
    when p_action = 'withdraw' and v_offer.status in ('approved', 'sent') then 'withdrawn'
    else null
  end;
  if v_next_status is null then
    raise exception 'Offer 当前状态 % 不支持动作 %', v_offer.status, p_action;
  end if;
  if p_action in ('reject', 'decline', 'withdraw') and nullif(btrim(p_comment), '') is null then
    raise exception '该 Offer 动作必须填写原因';
  end if;

  update public.hr_recruitment_offer
  set status = v_next_status,
      approval_comment = case when p_action in ('approve', 'reject') then nullif(btrim(p_comment), '') else approval_comment end,
      approved_by = case when p_action = 'approve' then coalesce(app_private.current_user_email(), 'system') else approved_by end,
      approved_at = case when p_action = 'approve' then now() else approved_at end,
      sent_at = case when p_action = 'send' then now() else sent_at end,
      responded_at = case when p_action in ('accept', 'decline') then now() else responded_at end,
      response_note = case when p_action in ('accept', 'decline') then nullif(btrim(p_comment), '') else response_note end
  where id = v_offer.id;

  if p_action = 'send' and v_candidate.stage = 'interview' then
    perform app_private.hr_append_candidate_stage(v_candidate.id, 'offer', 'Offer 已发送');
  end if;
  if p_action = 'accept' then
    if v_candidate.stage = 'interview' then
      perform app_private.hr_append_candidate_stage(v_candidate.id, 'offer', '候选人已接受 Offer');
    end if;
    insert into public.hr_recruitment_handoff(
      tenant_id, candidate_id, offer_id, organization_id, position_id, planned_onboard_date, status
    ) values (
      v_offer.tenant_id, v_candidate.id, v_offer.id, v_requisition.organization_id,
      v_requisition.position_id, v_offer.proposed_onboard_date, 'pending'
    ) on conflict (tenant_id, candidate_id) do update set
      offer_id = excluded.offer_id,
      organization_id = excluded.organization_id,
      position_id = excluded.position_id,
      planned_onboard_date = excluded.planned_onboard_date,
      status = 'pending',
      completed_at = null
    where hr_recruitment_handoff.status <> 'completed'
    returning id into v_handoff_id;
    if v_handoff_id is null then raise exception '已完成入职交接的候选人不能重新接受 Offer'; end if;

    insert into public.hr_recruitment_onboarding_task(
      tenant_id, handoff_id, task_category, task_title, task_description, due_date
    )
    select v_offer.tenant_id, v_handoff_id, seed.category, seed.title, seed.description,
      v_offer.proposed_onboard_date + seed.day_offset
    from (values
      ('documentation', '收集并核验入职资料', '核验身份、学历、离职证明与录用所需资料。', -5),
      ('account', '准备系统账号与权限', '按岗位最小权限原则完成账号、组织和角色开通。', -2),
      ('equipment', '准备工位与工作设备', '确认电脑、工位、门禁及岗位必要设备。', -1),
      ('orientation', '安排首日引导与入职培训', '明确报到联系人、首日议程、制度学习与安全培训。', 0)
    ) seed(category, title, description, day_offset)
    where not exists (
      select 1 from public.hr_recruitment_onboarding_task task
      where task.handoff_id = v_handoff_id and task.task_title = seed.title
    );
  end if;
end
$$;


ALTER FUNCTION "public"."hr_transition_recruitment_offer_secure"("p_offer_id" "uuid", "p_action" "text", "p_comment" "text") OWNER TO "postgres";

--

--
-- Name: hr_transition_service_request_secure("uuid", "text", "uuid", "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_transition_service_request_secure"("p_id" "uuid", "p_action" "text", "p_assignee_employee_id" "uuid" DEFAULT NULL::"uuid", "p_comment" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_record public.hr_self_service_request;
  v_service public.hr_service_catalog;
  v_old_status text;
  v_new_status text;
  v_event_type text;
  v_comment text := nullif(btrim(p_comment), '');
  v_manage boolean := app_private.is_platform_super()
    or app_private.has_permission('Hr:SelfService:Manage');
  v_own boolean;
begin
  select * into v_record from public.hr_self_service_request where id = p_id for update;
  if not found or not app_private.hr_service_case_visible(
    v_record.tenant_id, v_record.employee_id
  ) then
    raise exception '员工服务工单不存在或无权处理' using errcode = '42501';
  end if;
  v_own := v_record.employee_id = app_private.hr_current_employee_id();
  v_old_status := v_record.status;

  if p_action = 'submit' then
    if not (v_own or v_manage) or not app_private.has_permission('Hr:SelfService:Submit') then
      raise exception '当前账号没有提交员工服务工单的权限' using errcode = '42501';
    end if;
    if v_old_status <> 'draft' then raise exception '仅草稿工单可以提交'; end if;
    select * into v_service from public.hr_service_catalog
      where id = v_record.service_id and tenant_id = v_record.tenant_id and enabled;
    if not found or v_service.service_mode <> 'case' then raise exception '服务项目不可受理'; end if;
    v_new_status := 'submitted'; v_event_type := 'submitted';
    update public.hr_self_service_request
    set status = v_new_status,
        first_response_due_at = now() + make_interval(hours => v_service.first_response_hours),
        resolution_due_at = now() + make_interval(hours => v_service.resolution_hours),
        last_activity_at = now()
    where id = p_id returning * into v_record;
  elsif p_action = 'assign' then
    if not app_private.has_permission('Hr:SelfService:Assign') then
      raise exception '当前账号没有分派员工服务工单的权限' using errcode = '42501';
    end if;
    if v_old_status not in ('submitted', 'assigned') then raise exception '当前状态不能分派'; end if;
    if p_assignee_employee_id is null or not exists(
      select 1 from public.mdm_employee employee
      where employee.id = p_assignee_employee_id and employee.tenant_id = v_record.tenant_id
        and employee.employment_status <> 'terminated'
    ) then raise exception '请选择同租户的有效处理人'; end if;
    v_new_status := 'assigned'; v_event_type := 'assigned';
    update public.hr_self_service_request
    set status = v_new_status, assigned_employee_id = p_assignee_employee_id,
        last_activity_at = now()
    where id = p_id returning * into v_record;
  elsif p_action = 'start' then
    if not app_private.has_permission('Hr:SelfService:Resolve') then
      raise exception '当前账号没有处理员工服务工单的权限' using errcode = '42501';
    end if;
    if v_old_status not in ('submitted', 'assigned') then raise exception '当前状态不能开始处理'; end if;
    v_new_status := 'in_progress'; v_event_type := 'started';
    update public.hr_self_service_request
    set status = v_new_status,
        assigned_employee_id = coalesce(assigned_employee_id, app_private.hr_current_employee_id()),
        first_responded_at = coalesce(first_responded_at, now()),
        last_activity_at = now()
    where id = p_id returning * into v_record;
  elsif p_action = 'wait' then
    if not app_private.has_permission('Hr:SelfService:Resolve') then
      raise exception '当前账号没有处理员工服务工单的权限' using errcode = '42501';
    end if;
    if v_old_status <> 'in_progress' then raise exception '仅处理中工单可以等待员工补充'; end if;
    if v_comment is null then raise exception '请说明需要员工补充的材料或信息'; end if;
    v_new_status := 'waiting_employee'; v_event_type := 'waiting';
    update public.hr_self_service_request
    set status = v_new_status, waiting_started_at = now(), waiting_reason = v_comment,
        last_activity_at = now()
    where id = p_id returning * into v_record;
  elsif p_action = 'resume' then
    if not (v_own or app_private.has_permission('Hr:SelfService:Resolve')) then
      raise exception '当前账号没有恢复员工服务工单的权限' using errcode = '42501';
    end if;
    if v_old_status <> 'waiting_employee' then raise exception '当前工单不在等待员工补充状态'; end if;
    v_new_status := 'in_progress'; v_event_type := 'resumed';
    update public.hr_self_service_request
    set status = v_new_status,
        resolution_due_at = case when resolution_due_at is null then null
          else resolution_due_at + (now() - waiting_started_at) end,
        waiting_started_at = null, waiting_reason = null, last_activity_at = now()
    where id = p_id returning * into v_record;
  elsif p_action = 'resolve' then
    if not app_private.has_permission('Hr:SelfService:Resolve') then
      raise exception '当前账号没有解决员工服务工单的权限' using errcode = '42501';
    end if;
    if v_old_status not in ('assigned', 'in_progress') then raise exception '当前状态不能标记为已解决'; end if;
    if v_comment is null then raise exception '请填写可供员工确认的解决结果'; end if;
    v_new_status := 'resolved'; v_event_type := 'resolved';
    update public.hr_self_service_request
    set status = v_new_status, resolution = v_comment, resolved_at = now(),
        first_responded_at = coalesce(first_responded_at, now()),
        waiting_started_at = null, waiting_reason = null, last_activity_at = now()
    where id = p_id returning * into v_record;
  elsif p_action = 'close' then
    if not (v_own or app_private.has_permission('Hr:SelfService:Resolve')) then
      raise exception '当前账号没有关闭员工服务工单的权限' using errcode = '42501';
    end if;
    if v_old_status <> 'resolved' then raise exception '仅已解决工单可以关闭'; end if;
    v_new_status := 'closed'; v_event_type := 'closed';
    update public.hr_self_service_request
    set status = v_new_status, closed_at = now(), last_activity_at = now()
    where id = p_id returning * into v_record;
  elsif p_action = 'reopen' then
    if not (v_own or app_private.has_permission('Hr:SelfService:Resolve')) then
      raise exception '当前账号没有重开员工服务工单的权限' using errcode = '42501';
    end if;
    if v_old_status not in ('resolved', 'closed') then raise exception '仅已解决或已关闭工单可以重开'; end if;
    if v_comment is null then raise exception '请说明重新打开工单的原因'; end if;
    v_new_status := 'in_progress'; v_event_type := 'reopened';
    update public.hr_self_service_request
    set status = v_new_status, resolution = null, resolved_at = null, closed_at = null,
        reopen_count = reopen_count + 1,
        resolution_due_at = greatest(coalesce(resolution_due_at, now()), now()) + interval '8 hours',
        last_activity_at = now()
    where id = p_id returning * into v_record;
  elsif p_action = 'cancel' then
    if not (v_own or v_manage) or not app_private.has_permission('Hr:SelfService:Submit') then
      raise exception '当前账号没有取消员工服务工单的权限' using errcode = '42501';
    end if;
    if v_old_status not in ('draft', 'submitted') then raise exception '当前状态不能取消'; end if;
    v_new_status := 'cancelled'; v_event_type := 'cancelled';
    update public.hr_self_service_request
    set status = v_new_status, last_activity_at = now()
    where id = p_id returning * into v_record;
  elsif p_action = 'comment' then
    if v_comment is null then raise exception '请输入沟通内容'; end if;
    v_new_status := v_old_status; v_event_type := 'commented';
    update public.hr_self_service_request set last_activity_at = now()
      where id = p_id returning * into v_record;
  else
    raise exception '不支持的员工服务工单动作';
  end if;

  perform app_private.hr_add_service_event(
    v_record, v_event_type, v_old_status, v_new_status, v_comment,
    case when p_assignee_employee_id is null then '{}'::jsonb
      else jsonb_build_object('assignee_employee_id', p_assignee_employee_id) end
  );
end
$$;


ALTER FUNCTION "public"."hr_transition_service_request_secure"("p_id" "uuid", "p_action" "text", "p_assignee_employee_id" "uuid", "p_comment" "text") OWNER TO "postgres";

--

--
-- Name: hr_transition_workforce_plan_secure("uuid", "text", "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_transition_workforce_plan_secure"("p_id" "uuid", "p_action" "text", "p_comment" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_cycle public.hr_workforce_plan_cycle%rowtype;
  v_permission text;
  v_line record;
  v_incumbents integer;
begin
  v_permission := case
    when p_action in ('submit','cancel') then 'Hr:Headcount:Submit'
    when p_action in ('approve','return') then 'Hr:Headcount:Approve'
    when p_action = 'activate' then 'Hr:Headcount:Activate'
    when p_action = 'close' then 'Hr:Headcount:Close'
    else null end;
  if v_permission is null then raise exception '不支持的人力规划状态操作'; end if;
  if not app_private.can_execute_business_action('HrHeadcount', v_permission, null, false) then
    raise exception '当前账号没有执行该人力规划操作的权限' using errcode = '42501';
  end if;
  select * into v_cycle from public.hr_workforce_plan_cycle where id = p_id for update;
  if not found then raise exception '人力规划周期不存在'; end if;
  if not app_private.is_platform_super() and v_cycle.tenant_id <> app_private.current_user_tenant_id() then
    raise exception '无权操作其他租户的人力规划';
  end if;

  if p_action = 'submit' then
    if v_cycle.status <> 'draft' then raise exception '仅草稿规划可以提交'; end if;
    if not exists (select 1 from public.hr_workforce_plan_line where plan_id = p_id) then
      raise exception '至少维护一条岗位需求后才能提交';
    end if;
    if exists (
      select 1 from public.hr_workforce_plan_line l
      join public.hr_workforce_plan_cycle other_cycle on other_cycle.id <> v_cycle.id
        and other_cycle.tenant_id = l.tenant_id and other_cycle.status in ('approved','active')
        and daterange(other_cycle.period_start,other_cycle.period_end,'[]')
          && daterange(v_cycle.period_start,v_cycle.period_end,'[]')
      join public.hr_workforce_plan_line other_line on other_line.plan_id = other_cycle.id
        and other_line.position_id = l.position_id
      where l.plan_id = v_cycle.id
    ) then raise exception '规划周期与已批准或执行中的同岗位计划重叠'; end if;
    update public.hr_workforce_plan_cycle set status='submitted', remark=coalesce(nullif(btrim(p_comment),''),remark)
    where id=p_id;
    return true;
  end if;
  if p_action = 'return' then
    if v_cycle.status <> 'submitted' then raise exception '仅待审批规划可以退回'; end if;
    if nullif(btrim(p_comment),'') is null then raise exception '退回时必须填写原因'; end if;
    update public.hr_workforce_plan_cycle set status='draft', remark=btrim(p_comment) where id=p_id;
    return true;
  end if;
  if p_action = 'cancel' then
    if v_cycle.status not in ('draft','submitted') then raise exception '当前状态不能取消'; end if;
    if nullif(btrim(p_comment),'') is null then raise exception '取消时必须填写原因'; end if;
    update public.hr_workforce_plan_cycle set status='cancelled', remark=btrim(p_comment) where id=p_id;
    return true;
  end if;
  if p_action = 'approve' then
    if v_cycle.status <> 'submitted' then raise exception '仅待审批规划可以批准'; end if;
    update public.hr_workforce_plan_cycle set status='approved',
      approved_by=coalesce(public.get_app_user_display_name(),app_private.current_user_email(),'system'),
      approved_at=now(), remark=coalesce(nullif(btrim(p_comment),''),remark)
    where id=p_id;
    return true;
  end if;
  if p_action = 'activate' then
    if v_cycle.status <> 'approved' then raise exception '仅已批准规划可以启用'; end if;
    if current_date < v_cycle.period_start then raise exception '规划尚未到生效日期'; end if;
    if current_date > v_cycle.period_end then raise exception '规划周期已经结束'; end if;
    for v_line in select * from public.hr_workforce_plan_line where plan_id=p_id for update loop
      select count(*)::integer into v_incumbents from public.mdm_employee_assignment a
      where a.tenant_id=v_line.tenant_id and a.position_id=v_line.position_id and a.primary_assignment
        and a.effective_end is null and a.assignment_status <> 'ended';
      if v_line.target_count < v_incumbents then
        raise exception '岗位目标编制 % 低于当前在岗 %，请先完成调配或修订计划', v_line.target_count, v_incumbents;
      end if;
      insert into public.hr_position_headcount(
        tenant_id, organization_id, position_id, approved_count, effective_from, effective_to,
        enabled, remark, source_plan_line_id
      ) values (
        v_line.tenant_id, v_line.organization_id, v_line.position_id, v_line.target_count,
        v_cycle.period_start, v_cycle.period_end, true,
        '由人力规划 ' || v_cycle.plan_no || ' 启用', v_line.id
      ) on conflict (tenant_id, organization_id, position_id, effective_from) do update set
        approved_count=excluded.approved_count, effective_to=excluded.effective_to, enabled=true,
        remark=excluded.remark, source_plan_line_id=excluded.source_plan_line_id;
      if v_line.target_count = 0 then
        update public.mdm_position set enabled=false where id=v_line.position_id and tenant_id=v_line.tenant_id;
      else
        update public.mdm_position set headcount_limit=v_line.target_count,
          multiple_incumbents_allowed=multiple_incumbents_allowed or v_line.target_count > 1
        where id=v_line.position_id and tenant_id=v_line.tenant_id;
      end if;
    end loop;
    update public.hr_workforce_plan_cycle set status='active',activated_at=now(),
      remark=coalesce(nullif(btrim(p_comment),''),remark) where id=p_id;
    return true;
  end if;
  if v_cycle.status <> 'active' then raise exception '仅执行中的规划可以关闭'; end if;
  if current_date < v_cycle.period_end and nullif(btrim(p_comment),'') is null then
    raise exception '提前关闭规划必须填写原因';
  end if;
  update public.hr_workforce_plan_cycle set status='closed',closed_at=now(),
    remark=coalesce(nullif(btrim(p_comment),''),remark) where id=p_id;
  return true;
end
$$;


ALTER FUNCTION "public"."hr_transition_workforce_plan_secure"("p_id" "uuid", "p_action" "text", "p_comment" "text") OWNER TO "postgres";

--

--
-- Name: hr_update_position_secure("uuid", "jsonb"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_update_position_secure"("p_id" "uuid", "p_payload" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_position public.mdm_position%rowtype;
  v_organization_id uuid;
  v_job_profile_id uuid;
  v_grade_id uuid;
  v_headcount_limit integer;
  v_multiple boolean;
begin
  if not app_private.can_execute_business_action(
    'HrPosition', 'Hr:Position:Edit', null, false
  ) then
    raise exception 'Missing position edit permission' using errcode = '42501';
  end if;
  select * into v_position from public.mdm_position where id = p_id;
  if not found or (
    not app_private.is_platform_super()
    and v_position.tenant_id <> app_private.current_user_tenant_id()
  ) then
    raise exception '岗位不存在或无权编辑';
  end if;
  if exists (
    select 1 from jsonb_object_keys(p_payload) key
    where key <> all(array[
      'organization_id','job_profile_id','grade_id','position_code','position_name','enabled','sort',
      'description','headcount_limit','multiple_incumbents_allowed'
    ]::text[])
  ) then
    raise exception '岗位数据包含不允许写入的字段';
  end if;

  v_organization_id := coalesce(
    nullif(p_payload->>'organization_id', '')::uuid,
    v_position.organization_id
  );
  v_job_profile_id := coalesce(
    nullif(p_payload->>'job_profile_id', '')::uuid,
    v_position.job_profile_id
  );
  v_grade_id := case when p_payload ? 'grade_id'
    then nullif(p_payload->>'grade_id', '')::uuid
    else v_position.grade_id
  end;
  v_headcount_limit := coalesce(
    (p_payload->>'headcount_limit')::integer,
    v_position.headcount_limit
  );
  v_multiple := coalesce(
    (p_payload->>'multiple_incumbents_allowed')::boolean,
    v_position.multiple_incumbents_allowed
  );
  if v_organization_id is null then raise exception '请选择岗位所属组织'; end if;
  if not v_multiple and v_headcount_limit <> 1 then
    raise exception '单人岗位的编制人数必须为 1';
  end if;
  if not exists (
    select 1 from public.mdm_organization
    where id = v_organization_id
      and tenant_id = v_position.tenant_id
      and status = '1'
  ) then
    raise exception '所选组织不存在、已停用或不属于当前租户';
  end if;
  if not exists (
    select 1 from public.mdm_job_profile
    where id = v_job_profile_id
      and tenant_id = v_position.tenant_id
      and enabled
  ) then
    raise exception '所选标准职务不存在、已停用或不属于当前租户';
  end if;
  if v_grade_id is not null and not exists (
    select 1 from public.mdm_grade
    where id = v_grade_id
      and tenant_id = v_position.tenant_id
      and enabled
  ) then
    raise exception '所选职级不存在、已停用或不属于当前租户';
  end if;

  update public.mdm_position position_row
  set
    organization_id = v_organization_id,
    job_profile_id = v_job_profile_id,
    grade_id = v_grade_id,
    position_code = upper(coalesce(
      nullif(btrim(p_payload->>'position_code'), ''),
      position_row.position_code
    )),
    position_name = coalesce(
      nullif(btrim(p_payload->>'position_name'), ''),
      position_row.position_name
    ),
    position_kind = 'standard',
    system_code = null,
    enabled = coalesce((p_payload->>'enabled')::boolean, position_row.enabled),
    sort = coalesce((p_payload->>'sort')::integer, position_row.sort),
    description = case when p_payload ? 'description'
      then nullif(btrim(p_payload->>'description'), '')
      else position_row.description
    end,
    headcount_limit = v_headcount_limit,
    multiple_incumbents_allowed = v_multiple,
    update_by = coalesce(auth.uid()::text, 'system'),
    update_time = now()
  where position_row.id = p_id;

  update public.mdm_employee employee_row
  set
    organization_id = v_organization_id,
    job_title = profile_row.job_name,
    update_time = now()
  from public.mdm_job_profile profile_row
  where profile_row.id = v_job_profile_id
    and employee_row.position_id = p_id
    and employee_row.tenant_id = v_position.tenant_id;
  return true;
end;
$$;


ALTER FUNCTION "public"."hr_update_position_secure"("p_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";

--

--
-- Name: hr_workforce_overview_secure("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."hr_workforce_overview_secure"("p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_current_tenant uuid := app_private.current_user_tenant_id();
  v_result jsonb;
begin
  if not app_private.can_execute_business_action('HrHeadcount', 'Hr:Headcount:View', null, false) then
    raise exception '当前账号没有查看人力规划的权限' using errcode = '42501';
  end if;
  if not app_private.is_platform_super() then p_tenant_id := v_current_tenant; end if;

  with current_incumbents as (
    select a.tenant_id, a.position_id, count(*)::integer incumbent_count
    from public.mdm_employee_assignment a
    where a.primary_assignment
      and a.assignment_status <> 'ended'
      and a.effective_start <= current_date
      and (a.effective_end is null or a.effective_end >= current_date)
      and (p_tenant_id is null or a.tenant_id = p_tenant_id)
    group by a.tenant_id, a.position_id
  ), current_control as (
    select distinct on (h.tenant_id, h.position_id)
      h.tenant_id, h.position_id, h.approved_count
    from public.hr_position_headcount h
    where h.enabled
      and h.effective_from <= current_date
      and (h.effective_to is null or h.effective_to >= current_date)
      and (p_tenant_id is null or h.tenant_id = p_tenant_id)
    order by h.tenant_id, h.position_id, h.effective_from desc, h.update_time desc
  ), capacity as (
    select p.tenant_id, p.id position_id,
      coalesce(c.approved_count, p.headcount_limit) operational_limit,
      coalesce(i.incumbent_count, 0) incumbent_count
    from public.mdm_position p
    left join current_control c on c.tenant_id = p.tenant_id and c.position_id = p.id
    left join current_incumbents i on i.tenant_id = p.tenant_id and i.position_id = p.id
    where (p.enabled or c.position_id is not null)
      and (p_tenant_id is null or p.tenant_id = p_tenant_id)
  ), featured_plan as (
    select c.*
    from public.hr_workforce_plan_cycle c
    where (p_tenant_id is null or c.tenant_id = p_tenant_id)
    order by case c.status when 'active' then 1 when 'approved' then 2 when 'submitted' then 3 else 4 end,
      c.period_start desc, c.create_time desc
    limit 1
  ), bridge as (
    select coalesce(sum(l.baseline_count), 0)::integer baseline_count,
      coalesce(sum(l.planned_hires), 0)::integer planned_hires,
      coalesce(sum(l.planned_exits), 0)::integer planned_exits,
      coalesce(sum(l.target_count), 0)::integer target_count,
      coalesce(sum(l.planned_payroll), 0)::numeric planned_payroll
    from public.hr_workforce_plan_line l
    join featured_plan f on f.id = l.plan_id and f.tenant_id = l.tenant_id
  )
  select jsonb_build_object(
    'active_plan_count', (select count(*) from public.hr_workforce_plan_cycle c
      where (p_tenant_id is null or c.tenant_id = p_tenant_id) and c.status = 'active'),
    'pending_approval_count', (select count(*) from public.hr_workforce_plan_cycle c
      where (p_tenant_id is null or c.tenant_id = p_tenant_id) and c.status = 'submitted'),
    'operational_capacity', coalesce((select sum(operational_limit) from capacity), 0),
    'current_incumbent_count', coalesce((select sum(incumbent_count) from capacity), 0),
    'vacancy_count', coalesce((select sum(greatest(operational_limit - incumbent_count, 0)) from capacity), 0),
    'over_capacity_count', coalesce((select sum(greatest(incumbent_count - operational_limit, 0)) from capacity), 0),
    'featured_plan', case when (select id from featured_plan) is null then null else jsonb_build_object(
      'id', (select id from featured_plan),
      'plan_no', (select plan_no from featured_plan),
      'plan_name', (select plan_name from featured_plan),
      'status', (select status from featured_plan),
      'budget_amount', (select budget_amount from featured_plan),
      'currency_code', (select currency_code from featured_plan),
      'baseline_count', (select baseline_count from bridge),
      'planned_hires', (select planned_hires from bridge),
      'planned_exits', (select planned_exits from bridge),
      'target_count', (select target_count from bridge),
      'planned_payroll', (select planned_payroll from bridge),
      'budget_variance', case when (select budget_amount from featured_plan) is null then null
        else (select budget_amount from featured_plan) - (select planned_payroll from bridge) end
    ) end
  ) into v_result;
  return v_result;
end
$$;


ALTER FUNCTION "public"."hr_workforce_overview_secure"("p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: normalize_login_phone("text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."normalize_login_phone"("p_phone" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO ''
    AS $_$
  select case
    when normalized.digits = '' then null
    when normalized.digits ~ '^00861[3-9][0-9]{9}$' then '+' || substring(normalized.digits from 3)
    when normalized.digits ~ '^861[3-9][0-9]{9}$' then '+' || normalized.digits
    when normalized.digits ~ '^1[3-9][0-9]{9}$' then '+86' || normalized.digits
    when btrim(p_phone) like '+%' and normalized.digits ~ '^[0-9]{8,15}$' then '+' || normalized.digits
    else normalized.digits
  end
  from (select regexp_replace(coalesce(p_phone, ''), '[^0-9]', '', 'g') as digits) normalized;
$_$;


ALTER FUNCTION "public"."normalize_login_phone"("p_phone" "text") OWNER TO "postgres";

--

--
-- Name: prevent_platform_tenant_change(); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."prevent_platform_tenant_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    if old.builtin_type is not null then
      raise exception '系统预置租户“%”不可删除', old.tenant_name;
    end if;
    return old;
  end if;

  if old.builtin_type is not null then
    if new.builtin_type is distinct from old.builtin_type then
      raise exception '系统预置租户身份不可修改';
    end if;
    if new.tenant_code is distinct from old.tenant_code then
      raise exception '系统预置租户编码不可修改';
    end if;
    if new.status is distinct from '1' then
      raise exception '系统预置租户不可停用';
    end if;
  elsif new.builtin_type is not null then
    raise exception '不能将普通租户改为系统预置租户';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."prevent_platform_tenant_change"() OWNER TO "postgres";

--

--
-- Name: trg_create_tenant_root_organization(); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."trg_create_tenant_root_organization"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  insert into public.mdm_organization (
    tenant_id,
    organization_code,
    organization_name,
    organization_type,
    status,
    sort,
    description,
    is_system,
    create_by,
    update_by
  ) values (
    new.id,
    'ROOT',
    new.tenant_name,
    'company',
    '1',
    0,
    '租户根组织，由系统自动维护',
    true,
    coalesce(new.create_by, 'platform-owner@example.com'),
    coalesce(new.update_by, new.create_by, 'platform-owner@example.com')
  )
  on conflict (tenant_id, organization_code) do nothing;

  return new;
end;
$$;


ALTER FUNCTION "public"."trg_create_tenant_root_organization"() OWNER TO "postgres";

--

--
-- Name: trg_default_system_organization(); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."trg_default_system_organization"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if new.organization_id is null then
    select o.id
    into new.organization_id
    from public.mdm_organization o
    where o.tenant_id = new.tenant_id
      and o.is_system is true
    limit 1;
  end if;

  if new.organization_id is not null and not exists (
    select 1
    from public.mdm_organization o
    where o.id = new.organization_id
      and o.tenant_id = new.tenant_id
  ) then
    raise exception '用户或角色不能关联到其他租户的组织';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."trg_default_system_organization"() OWNER TO "postgres";

--

--
-- Name: trg_guard_system_organization(); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."trg_guard_system_organization"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'DELETE' and old.is_system then
    raise exception '租户根组织不允许删除';
  end if;

  if tg_op = 'UPDATE' and old.is_system and (
    new.tenant_id is distinct from old.tenant_id
    or new.parent_id is distinct from old.parent_id
    or new.organization_code is distinct from old.organization_code
    or new.organization_type is distinct from old.organization_type
    or new.status is distinct from old.status
    or not new.is_system
  ) then
    raise exception '租户根组织的编码、类型、层级和状态受系统保护';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."trg_guard_system_organization"() OWNER TO "postgres";

--

--
-- Name: trg_set_create_time_and_by(); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."trg_set_create_time_and_by"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  -- set create_time if column exists and is null
  IF TG_ARGV[0] = 'true' THEN
    BEGIN
      IF NEW.create_time IS NULL THEN
        NEW.create_time := now();
      END IF;
    EXCEPTION WHEN undefined_column THEN
      NULL;
    END;
  END IF;

  -- set create_by if column exists and is null
  -- Use auth.jwt() ->> 'email' as the source of truth
  IF TG_ARGV[1] = 'true' THEN
    BEGIN
      IF NEW.create_by IS NULL OR NEW.create_by = '' THEN
        -- prefer JWT email; fallback to 'unknown' if not present
        NEW.create_by := COALESCE((auth.jwt() ->> 'email'), 'unknown');
      END IF;
    EXCEPTION WHEN undefined_column THEN
      NULL;
    END;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trg_set_create_time_and_by"() OWNER TO "postgres";

--

--
-- Name: trg_set_update_time_and_by(); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."trg_set_update_time_and_by"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  begin
    new.update_time := now();
  exception when undefined_column then
    null;
  end;

  begin
    new.update_by := coalesce(
      nullif(public.get_app_user_display_name(), ''),
      nullif(auth.jwt() ->> 'email', ''),
      nullif(old.update_by, ''),
      'unknown'
    );
  exception when undefined_column then
    null;
  end;

  return new;
end
$$;


ALTER FUNCTION "public"."trg_set_update_time_and_by"() OWNER TO "postgres";

--

--
-- Name: trg_validate_sys_organization(); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."trg_validate_sys_organization"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if new.parent_id = new.id then
    raise exception '组织不能将自身设置为上级组织';
  end if;

  if new.leader_user_id is not null and not exists (
    select 1
    from public.sys_user u
    where u.id = new.leader_user_id
      and u.tenant_id = new.tenant_id
  ) then
    raise exception '组织负责人必须属于同一租户';
  end if;

  if new.parent_id is not null and exists (
    with recursive ancestors as (
      select o.id, o.parent_id
      from public.mdm_organization o
      where o.id = new.parent_id

      union all

      select parent.id, parent.parent_id
      from public.mdm_organization parent
      join ancestors child on child.parent_id = parent.id
    )
    select 1 from ancestors where id = new.id
  ) then
    raise exception '组织层级不能形成循环';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."trg_validate_sys_organization"() OWNER TO "postgres";

--

--
-- Name: validate_tms_carrier_payment_application_submission("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."validate_tms_carrier_payment_application_submission"("p_application_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_app record;
  v_item record;
  v_item_count integer;
  v_total numeric(14,2);
  v_outstanding numeric(14,2);
  v_reserved numeric(14,2);
begin
  select * into v_app from public.tms_carrier_payment_application
  where id=p_application_id for update;
  if not found then raise exception '付款申请不存在'; end if;
  if v_app.status not in ('draft','rejected') then raise exception '只有草稿或已驳回申请可以提交审批'; end if;
  if not app_private.is_platform_super() and v_app.tenant_id is distinct from app_private.current_user_tenant_id() then
    raise exception '无权提交其他租户付款申请';
  end if;
  select count(*)::integer, coalesce(sum(applied_amount),0)::numeric(14,2)
  into v_item_count, v_total
  from public.tms_carrier_payment_application_item where application_id=p_application_id;
  if v_item_count < 1 then raise exception '请至少选择一份待付款对账单'; end if;
  if v_total is distinct from v_app.amount then raise exception '付款分配合计必须等于申请金额'; end if;

  for v_item in
    select i.*, s.status statement_status, s.settled_amount,
      coalesce((select sum(si.line_amount) from public.tms_carrier_statement_item si
                where si.statement_id=s.id and si.is_active),0)::numeric(14,2) statement_amount
    from public.tms_carrier_payment_application_item i
    join public.tms_carrier_statement s on s.id=i.statement_id
    where i.application_id=p_application_id order by i.statement_id
  loop
    perform pg_advisory_xact_lock(hashtextextended(v_item.statement_id::text, 841329));
    if v_item.statement_status not in ('confirmed','partially_settled') then
      raise exception '对账单 % 当前状态不允许付款', v_item.statement_no_snapshot;
    end if;
    v_outstanding := greatest(v_item.statement_amount-v_item.settled_amount,0)::numeric(14,2);
    select coalesce(sum(i.applied_amount),0)::numeric(14,2) into v_reserved
    from public.tms_carrier_payment_application_item i
    join public.tms_carrier_payment_application a on a.id=i.application_id
    where i.statement_id=v_item.statement_id
      and a.status in ('pending_review','approved')
      and a.id<>p_application_id;
    if v_item.applied_amount > v_outstanding-v_reserved then
      raise exception '对账单 % 可申请余额不足，当前可申请 %',
        v_item.statement_no_snapshot, greatest(v_outstanding-v_reserved,0);
    end if;
  end loop;
  return true;
end;
$$;


ALTER FUNCTION "public"."validate_tms_carrier_payment_application_submission"("p_application_id" "uuid") OWNER TO "postgres";

