--

--

CREATE TABLE IF NOT EXISTS "public"."hr_employee_benefit_enrollment" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" DEFAULT "app_private"."current_user_tenant_id"() NOT NULL,
    "employee_id" "uuid" NOT NULL,
    "plan_id" "uuid" NOT NULL,
    "option_id" "uuid" NOT NULL,
    "life_event_id" "uuid",
    "enrollment_no" "text" NOT NULL,
    "coverage_from" "date" NOT NULL,
    "coverage_to" "date",
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "waiver_reason" "text",
    "employee_contribution" numeric(18,2) DEFAULT 0 NOT NULL,
    "employer_contribution" numeric(18,2) DEFAULT 0 NOT NULL,
    "currency_code" "text" DEFAULT 'CNY'::"text" NOT NULL,
    "payroll_sync_status" "text" DEFAULT 'not_ready'::"text" NOT NULL,
    "approved_by" "text",
    "approved_at" timestamp with time zone,
    "ended_at" timestamp with time zone,
    "remark" "text",
    "create_by" "text",
    "create_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "update_by" "text",
    "update_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "hr_employee_benefit_enrollment_amounts_nonnegative" CHECK ((("employee_contribution" >= (0)::numeric) AND ("employer_contribution" >= (0)::numeric))),
    CONSTRAINT "hr_employee_benefit_enrollment_currency_check" CHECK (("currency_code" ~ '^[A-Z]{3}$'::"text")),
    CONSTRAINT "hr_employee_benefit_enrollment_dates_check" CHECK ((("coverage_to" IS NULL) OR ("coverage_to" >= "coverage_from"))),
    CONSTRAINT "hr_employee_benefit_enrollment_no_not_blank" CHECK (("btrim"("enrollment_no") <> ''::"text")),
    CONSTRAINT "hr_employee_benefit_enrollment_payroll_status_check" CHECK (("payroll_sync_status" = ANY (ARRAY['not_ready'::"text", 'ready'::"text", 'exported'::"text", 'stopped'::"text"]))),
    CONSTRAINT "hr_employee_benefit_enrollment_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'pending'::"text", 'active'::"text", 'waived'::"text", 'ended'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "hr_employee_benefit_enrollment_waiver_check" CHECK ((("status" <> 'waived'::"text") OR (NULLIF("btrim"("waiver_reason"), ''::"text") IS NOT NULL)))
);


ALTER TABLE "public"."hr_employee_benefit_enrollment" OWNER TO "postgres";

