    CONSTRAINT "hr_employee_contract_renewal_decision_check" CHECK (("renewal_decision" = ANY (ARRAY['not_started'::"text", 'pending'::"text", 'renew'::"text", 'terminate'::"text", 'completed'::"text"]))),
    CONSTRAINT "hr_employee_contract_salary_check" CHECK ((("monthly_salary" IS NULL) OR ("monthly_salary" >= (0)::numeric))),
