    "current_organization_id" "uuid" NOT NULL,
    "current_position_id" "uuid",
    "current_job_title" "text",
    "motivation" "text" NOT NULL,
    "relevant_experience" "text",
    "preferred_start_date" "date",
    "manager_awareness" "text" DEFAULT 'not_informed'::"text" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "submitted_at" timestamp with time zone,
    "reviewed_at" timestamp with time zone,
    "reviewed_by" "text",
    "assessment_score" numeric(5,2),
    "assessment_note" "text",
    "decision_at" timestamp with time zone,
    "decision_by" "text",
    "decision_note" "text",
    "accepted_at" timestamp with time zone,
    "accepted_by" "text",
    "personnel_change_id" "uuid",
    "create_by" "text",
    "create_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "update_by" "text",
    "update_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "hr_internal_mobility_application_accept_check" CHECK (((("status" = ANY (ARRAY['accepted'::"text", 'converted'::"text"])) AND ("accepted_at" IS NOT NULL) AND ("accepted_by" IS NOT NULL)) OR ("status" <> ALL (ARRAY['accepted'::"text", 'converted'::"text"])))),
    CONSTRAINT "hr_internal_mobility_application_awareness_check" CHECK (("manager_awareness" = ANY (ARRAY['not_informed'::"text", 'informed'::"text", 'supported'::"text"]))),
    CONSTRAINT "hr_internal_mobility_application_convert_check" CHECK (((("status" = 'converted'::"text") AND ("personnel_change_id" IS NOT NULL)) OR (("status" <> 'converted'::"text") AND ("personnel_change_id" IS NULL)))),
    CONSTRAINT "hr_internal_mobility_application_decision_check" CHECK (((("status" = ANY (ARRAY['offered'::"text", 'accepted'::"text", 'rejected'::"text", 'converted'::"text"])) AND ("decision_at" IS NOT NULL) AND ("decision_by" IS NOT NULL) AND (NULLIF("btrim"("decision_note"), ''::"text") IS NOT NULL)) OR ("status" = ANY (ARRAY['draft'::"text", 'submitted'::"text", 'under_review'::"text", 'shortlisted'::"text", 'withdrawn'::"text"])))),
    CONSTRAINT "hr_internal_mobility_application_motivation_not_blank" CHECK (("btrim"("motivation") <> ''::"text")),
    CONSTRAINT "hr_internal_mobility_application_review_check" CHECK (((("status" = ANY (ARRAY['under_review'::"text", 'shortlisted'::"text", 'offered'::"text", 'accepted'::"text", 'rejected'::"text", 'converted'::"text"])) AND ("reviewed_at" IS NOT NULL) AND ("reviewed_by" IS NOT NULL)) OR ("status" = ANY (ARRAY['draft'::"text", 'submitted'::"text", 'withdrawn'::"text"])))),
    CONSTRAINT "hr_internal_mobility_application_score_check" CHECK ((("assessment_score" IS NULL) OR (("assessment_score" >= (0)::numeric) AND ("assessment_score" <= (100)::numeric)))),
    CONSTRAINT "hr_internal_mobility_application_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'submitted'::"text", 'under_review'::"text", 'shortlisted'::"text", 'offered'::"text", 'accepted'::"text", 'rejected'::"text", 'withdrawn'::"text", 'converted'::"text"]))),
    CONSTRAINT "hr_internal_mobility_application_submit_check" CHECK (((("status" = 'draft'::"text") AND ("submitted_at" IS NULL)) OR (("status" <> 'draft'::"text") AND ("submitted_at" IS NOT NULL))))
);


