--

CREATE TABLE IF NOT EXISTS "public"."hr_internal_opportunity" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" DEFAULT "app_private"."current_user_tenant_id"() NOT NULL,
    "opportunity_code" "text" NOT NULL,
    "opportunity_title" "text" NOT NULL,
    "opportunity_type" "text" NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "position_id" "uuid",
    "hiring_manager_employee_id" "uuid" NOT NULL,
    "capacity" integer DEFAULT 1 NOT NULL,
    "work_location" "text",
    "work_mode" "text" DEFAULT 'onsite'::"text" NOT NULL,
    "expected_start_date" "date" NOT NULL,
    "expected_end_date" "date",
    "application_open_date" "date" NOT NULL,
    "application_close_date" "date" NOT NULL,
    "min_tenure_months" integer DEFAULT 0 NOT NULL,
    "role_summary" "text" NOT NULL,
    "required_skills" "text" NOT NULL,
    "eligibility_notes" "text",
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "published_at" timestamp with time zone,
    "published_by" "text",
    "closed_at" timestamp with time zone,
    "closed_by" "text",
    "decision_note" "text",
    "version" integer DEFAULT 1 NOT NULL,
    "create_by" "text",
    "create_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "update_by" "text",
    "update_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "hr_internal_opportunity_capacity_check" CHECK ((("capacity" >= 1) AND ("capacity" <= 999))),
    CONSTRAINT "hr_internal_opportunity_close_check" CHECK (((("status" = 'closed'::"text") AND ("closed_at" IS NOT NULL) AND ("closed_by" IS NOT NULL)) OR (("status" <> 'closed'::"text") AND ("closed_at" IS NULL) AND ("closed_by" IS NULL)))),
    CONSTRAINT "hr_internal_opportunity_code_not_blank" CHECK (("btrim"("opportunity_code") <> ''::"text")),
    CONSTRAINT "hr_internal_opportunity_date_check" CHECK ((("application_close_date" >= "application_open_date") AND ("expected_start_date" >= "application_open_date") AND (("expected_end_date" IS NULL) OR ("expected_end_date" >= "expected_start_date")))),
    CONSTRAINT "hr_internal_opportunity_position_check" CHECK ((("opportunity_type" <> 'permanent'::"text") OR ("position_id" IS NOT NULL))),
    CONSTRAINT "hr_internal_opportunity_publish_check" CHECK (((("status" = ANY (ARRAY['open'::"text", 'paused'::"text", 'closed'::"text"])) AND ("published_at" IS NOT NULL) AND ("published_by" IS NOT NULL)) OR (("status" = ANY (ARRAY['draft'::"text", 'cancelled'::"text"])) AND ("published_at" IS NULL) AND ("published_by" IS NULL)))),
    CONSTRAINT "hr_internal_opportunity_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'open'::"text", 'paused'::"text", 'closed'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "hr_internal_opportunity_tenure_check" CHECK ((("min_tenure_months" >= 0) AND ("min_tenure_months" <= 600))),
    CONSTRAINT "hr_internal_opportunity_title_not_blank" CHECK (("btrim"("opportunity_title") <> ''::"text")),
    CONSTRAINT "hr_internal_opportunity_type_check" CHECK (("opportunity_type" = ANY (ARRAY['permanent'::"text", 'rotation'::"text", 'project'::"text", 'gig'::"text"]))),
    CONSTRAINT "hr_internal_opportunity_version_positive" CHECK (("version" > 0)),
    CONSTRAINT "hr_internal_opportunity_work_mode_check" CHECK (("work_mode" = ANY (ARRAY['onsite'::"text", 'hybrid'::"text", 'remote'::"text"])))
);


