--

--
-- Name: hr_workforce_plan_line; Type: TABLE; Schema: public
--

--

CREATE TABLE IF NOT EXISTS "public"."hr_workforce_plan_line" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" DEFAULT "app_private"."current_user_tenant_id"() NOT NULL,
    "plan_id" "uuid" NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "position_id" "uuid" NOT NULL,
    "baseline_count" integer DEFAULT 0 NOT NULL,
    "planned_hires" integer DEFAULT 0 NOT NULL,
    "planned_exits" integer DEFAULT 0 NOT NULL,
    "target_count" integer GENERATED ALWAYS AS ((("baseline_count" + "planned_hires") - "planned_exits")) STORED,
    "annual_cost_per_head" numeric(18,2),
    "planned_payroll" numeric(20,2) GENERATED ALWAYS AS (
CASE
    WHEN ("annual_cost_per_head" IS NULL) THEN NULL::numeric
    ELSE (((("baseline_count" + "planned_hires") - "planned_exits"))::numeric * "annual_cost_per_head")
END) STORED,
    "demand_date" "date",
    "priority" "text" DEFAULT 'normal'::"text" NOT NULL,
    "rationale" "text" NOT NULL,
    "assumptions" "text",
    "create_by" "text",
    "create_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "update_by" "text",
    "update_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "hr_workforce_plan_line_cost_check" CHECK ((("annual_cost_per_head" IS NULL) OR ("annual_cost_per_head" >= (0)::numeric))),
    CONSTRAINT "hr_workforce_plan_line_counts_check" CHECK ((("baseline_count" >= 0) AND ("planned_hires" >= 0) AND ("planned_exits" >= 0) AND ((("baseline_count" + "planned_hires") - "planned_exits") >= 0))),
    CONSTRAINT "hr_workforce_plan_line_priority_check" CHECK (("priority" = ANY (ARRAY['critical'::"text", 'high'::"text", 'normal'::"text", 'low'::"text"]))),
    CONSTRAINT "hr_workforce_plan_line_rationale_not_blank" CHECK (("btrim"("rationale") <> ''::"text"))
);


